-- Pathway: Setup, journal, talents, outfits, Go to, the bags, the minimap (GoodMap and its ride effects), fishing and settings.
-- Built from 28 source files by tools/bundle.py; each part runs as its own file did, in the same order.
local _, P = ...; P.SECTIONS = P.SECTIONS or {}
P.SECTIONS["Modules.lua"] = { 8, "WoWProTips", 257, "Setup", 863, "Place", 1139, "FPS", 1481, "MapLook", 1893, "Talents", 2221, "Catalog", 2785, "Journal", 3989, "Outfits", 4144, "GoTo", 4596, "Boosts", 5445, "Share", 6195, "QuestDelete", 6814, "Bags/Compat", 6975, "Bags/Core", 7729, "Bags/UI", 8912, "Bags/Bank", 10020, "Bags/Mover", 10308, "Bags/Split", 10480, "Bags/Features", 11175, "Bags/Labels", 11340, "Bags/Enable", 11386, "GoodMap/Locales", 16741, "GoodMap/GoodMap", 25201, "GoodMap/Rides", 26218, "GoodMap/Terrain", 26399, "Fishing/FishingBlinker", 28401, "Settings" }
-- ==================== WoWProTips.lua
do local __addon, __ns = ... local function part()
--[[ Pathway — WoW-Pro tips
     The WoW-Pro Community's Forever leveling guides ship unchanged in WoWPro/.
     When the step you're on has a note in them worth reading ("Vagash is in a
     cave atop the hill"), it shows in a small window joined to the bottom of
     your guide, in Pathway's look, with WoW-Pro's name on it.

     The guides themselves are never edited: Pathway reads their notes as they
     load and shows them as written, credited to their authors.
     WoW-Pro Guides by "The WoW-Pro Community" are licensed under a Creative
     Commons Attribution-NonCommercial-NoDerivs 3.0 Unported License
     (https://creativecommons.org/licenses/by-nc-nd/3.0/); see WoWPro/License.md.
     Pathway is free and non-commercial, and is not affiliated with WoW-Pro. ]]

local ADDON, P = __addon, __ns
local A = P.ACCENT
local EMPTY = {}

-- the real WoW-Pro add-on (if it's installed and already loaded) gets its name back
_G.WoWPro = P._wowproWas
P._wowproWas = nil

local function S() return P.db.settings end

---------------------------------------------------------------------------
-- Reading the notes (once, the first time they're needed)
---------------------------------------------------------------------------
local notes                     -- [qid] = { { act = "p"|"t"|"o", qo =, text =, cls =, race = }, ... }
local ACT = { A = "p", T = "t", C = "o", K = "o", l = "o", U = "o", R = "r" }
local VALUE = {                 -- tags followed by a value (everything else is a flag)
	QID = 1, MID = 1, PRE = 1, AVAILABLE = 1, LEAD = 1, ACTIVE = 1, NPC = 1, CCOUNT = 1, ERROR = 1, M = 1, Z = 1, TZ = 1,
	IZ = 1, L = 1, QO = 1, SO = 1, ITEM = 1, EQUIPPED = 1, QG = 1, T = 1, U = 1, ACH = 1, BUFF = 1, BUILDING = 1, COV = 1,
	DATE = 1, DFREN = 1, EX = 1, FLY = 1, GROUP = 1, GUIDE = 1, ILVL = 1, JUMP = 1, LVL = 1, P = 1, PET = 1, REN = 1,
	REP = 1, RECIPE = 1, SPELL = 1, TAXI = 1, TWWREN = 1, HOA = 1, DEAD = 1, PET1 = 1, PET2 = 1, PET3 = 1, SELECT = 1,
	STRATEGY = 1, SWITCH = 1, C = 1, FACTION = 1, GEN = 1, N = 1, R = 1, RANK = 1,
}

-- shown as written; only their markup becomes the game's colors and line breaks
local function Show(text)
	text = text:gsub("%[color=(%x%x%x%x%x%x)%]", "|cff%1"):gsub("%[/color%]", "|r"):gsub("\\n", "\n")
	return text
end

-- "From Rudra Amberstill." / "To Earthseer Farseen." say nothing the guide doesn't
local function Worth(note)
	local plain = note:gsub("%[/?color[^%]]*%]", ""):gsub("\\n", " ")
	local words = select(2, plain:gsub("%S+", ""))
	if #plain < 20 or words < 4 then return false end
	if plain:match("^%s*From [^%.,%(]+%.?%s*$") or plain:match("^%s*To [^%.,%(]+%.?%s*$") then return false end
	return true
end

local function Parse(g, faction)
	if not g.steps then return end
	if g.faction and g.faction ~= faction and g.faction ~= "Neutral" then g.steps = nil return end
	local ok, text = pcall(g.steps)
	g.steps = nil                                  -- read once, then let it go
	if not ok or type(text) ~= "string" then return end
	local taken = {}                               -- quests this guide has picked up so far
	for line in text:gmatch("[^\r\n]+") do
		local act = line:match("^%s*(%a)%s")
		local kind = act and ACT[act]
		if kind then
			local f, tags = {}, {}
			for part in (line .. "|"):gmatch("([^|]*)|") do f[#f + 1] = part end
			local i = 2
			while i <= #f do
				local tag = f[i]:match("^%s*(.-)%s*$")
				if tag ~= "" then
					if VALUE[tag] then tags[tag] = f[i + 1]; i = i + 2 else tags[tag] = true; i = i + 1 end
				else
					i = i + 1
				end
			end
			local note = type(tags.N) == "string" and tags.N or nil
			-- which quest: QID, or ACTIVE (a step done while the quest is in your log)
			local ids = type(tags.QID) == "string" and tags.QID or type(tags.ACTIVE) == "string" and tags.ACTIVE or nil
			-- a "run to" step: before the quest it leads to the giver, during it to the work
			if kind == "r" then
				local first = ids and tonumber(ids:match("%d+"))
				kind = (type(tags.QID) == "string" and not (first and taken[first])) and "p" or "o"
			end
			if act == "A" and ids then for q in ids:gmatch("%d+") do taken[tonumber(q)] = true end end
			if note and ids and Worth(note) then
				for qid in ids:gmatch("%d+") do
					qid = tonumber(qid)
					local list = notes[qid]
					if not list then list = {}; notes[qid] = list end
					list[#list + 1] = { act = kind, qo = tags.QO, text = Show(note),
						cls = type(tags.C) == "string" and tags.C or nil, race = type(tags.R) == "string" and tags.R or nil }
				end
			end
		end
	end
end

-- Read in small pieces: a few milliseconds a frame in the background, so a /reload
-- never has one long hitch. If a note's wanted before it's done, the rest is read then.
local nextGuide, done = 1, false
local function ReadSome(budget)
	if done then return true end
	notes = notes or {}
	local faction = (P.me and P.me.faction) or UnitFactionGroup("player") or "Alliance"
	local list = P.WoWProGuides or EMPTY
	local clock = debugprofilestop
	local stop = budget and clock and clock() + budget
	while list[nextGuide] do
		pcall(Parse, list[nextGuide], faction)
		nextGuide = nextGuide + 1
		if stop and clock() >= stop then return false end
	end
	done = true
	collectgarbage("step", 0)
	return true
end
local function Build() ReadSome(nil) end
local function Background()
	if not ReadSome(2) then C_Timer.After(0, Background) end
end

local function ForMe(n)
	if n.cls then
		local mine = UnitClass("player")
		if not (mine and n.cls:lower():find(mine:lower(), 1, true)) then return false end
	end
	if n.race then
		local mine = UnitRace("player")
		if not (mine and n.race:lower():gsub("%s", ""):find(mine:lower():gsub("%s", ""), 1, true)) then return false end
	end
	return true
end

-- the WoW-Pro note for a quest: what kind of step (p pickup, t turn-in, o objective)
-- and, for an objective, which one (its number, or its text)
function P:WoWProNote(qid, act, index, otext)
	if not (P.WoWProGuides and qid) then return end
	if not done then Build() end
	-- the notes written for that objective first, then the quest's general ones; two at most
	local best, any = {}, {}
	for _, n in ipairs(notes[qid] or EMPTY) do
		if n.act == act and ForMe(n) then
			local list
			if act ~= "o" or not n.qo then list = any
			elseif tonumber(n.qo) == index or (otext and type(n.qo) == "string" and otext:lower():find((n.qo:lower():gsub(":.*$", "")), 1, true)) then list = best end
			if list then
				local dup = false
				for _, t in ipairs(list) do if t == n.text then dup = true end end
				if not dup then list[#list + 1] = n.text end
			end
		end
	end
	for _, t in ipairs(any) do best[#best + 1] = t end
	if #best == 0 then return end
	if best[2] and best[2] ~= best[1] then return best[1] .. "\n" .. best[2] end
	return best[1]
end

-- the note for a step of your guide
function P:WoWProTip(s)
	if not s or s.travel or s.trip or s.flight or s.goal then return end
	if s.quest then
		local e = self.log and self.log[s.quest]
		local o = e and e.objectives and e.objectives[s.index]
		return self:WoWProNote(s.quest, "o", s.index, o and o.text)
	end
	if not s.key then return end
	local pick, turn = self:EntityWork(s.key)
	for _, qid in ipairs(turn) do local t = self:WoWProNote(qid, "t"); if t then return t, qid end end
	for _, qid in ipairs(pick) do local t = self:WoWProNote(qid, "p"); if t then return t, qid end end
end

---------------------------------------------------------------------------
-- The window: joined to your guide, in its look
---------------------------------------------------------------------------
local tip
local function BuildTip(guide)
	tip = CreateFrame("Frame", "PathwayWoWProTip", guide, "BackdropTemplate")
	P.Flat(tip, P.colors.BG, nil, true)
	tip:SetFrameStrata(guide:GetFrameStrata())
	tip:EnableMouse(true)
	tip.bar = tip:CreateTexture(nil, "ARTWORK")
	tip.bar:SetPoint("TOPLEFT", 6, -6); tip.bar:SetPoint("BOTTOMLEFT", 6, 6); tip.bar:SetWidth(2)
	tip.head = tip:CreateFontString(nil, "OVERLAY"); tip.head:SetFontObject(P.fonts.head)
	tip.head:SetPoint("TOPLEFT", 16, -9)
	tip.text = tip:CreateFontString(nil, "OVERLAY"); tip.text:SetFontObject(P.fonts.button)
	tip.text:SetPoint("TOPLEFT", tip.head, "BOTTOMLEFT", 0, -4); tip.text:SetPoint("RIGHT", -12, 0)
	tip.text:SetJustifyH("LEFT"); tip.text:SetSpacing(2); tip.text:SetTextColor(0.86, 0.89, 0.93)
	tip.credit = tip:CreateFontString(nil, "OVERLAY"); tip.credit:SetFontObject(P.fonts.head)
	tip.credit:SetPoint("TOPLEFT", tip.text, "BOTTOMLEFT", 0, -5); tip.credit:SetJustifyH("LEFT"); tip.credit:SetWordWrap(false)
	tip.credit:SetText(P.DIM .. "WoW-Pro Community  ·  CC BY-NC-ND 3.0|r")
	tip:SetScript("OnEnter", function(self)
		GameTooltip:SetOwner(self, "ANCHOR_LEFT")
		GameTooltip:SetText("WoW-Pro tip", 1, 1, 1)
		GameTooltip:AddLine("From the WoW-Pro Community's Forever leveling guides, shown as they wrote it.", 0.7, 0.75, 0.8, true)
		GameTooltip:AddLine("CC BY-NC-ND 3.0  ·  github.com/Ludovicus-Maior/WoW-Pro-Guides", 0.5, 0.55, 0.6, true)
		GameTooltip:AddLine("Settings > Guide turns these off.", 0.5, 0.55, 0.6, true)
		GameTooltip:Show()
	end)
	tip:SetScript("OnLeave", GameTooltip_Hide)
	local function paint() tip.bar:SetColorTexture(A[1], A[2], A[3], 0.9); tip.head:SetText("|c" .. P.ACCENT_HEX .. "WOW-PRO TIP|r") end
	P:OnPaint(paint); paint()
	tip:Hide()
end

local function Place(guide)
	tip:ClearAllPoints()
	-- below the guide, unless it sits near the bottom of the screen
	local bottom = tonumber(guide:GetBottom()) or 400
	local room = bottom * (tonumber(guide:GetEffectiveScale()) or 1) / (tonumber(UIParent:GetEffectiveScale()) or 1)
	if room > (tonumber(tip:GetHeight()) or 60) + 20 then
		tip:SetPoint("TOPLEFT", guide, "BOTTOMLEFT", 0, -4); tip:SetPoint("TOPRIGHT", guide, "BOTTOMRIGHT", 0, -4)
	else
		tip:SetPoint("BOTTOMLEFT", guide, "TOPLEFT", 0, 4); tip:SetPoint("BOTTOMRIGHT", guide, "TOPRIGHT", 0, 4)
	end
end

function P:UpdateWoWProTip()
	local guide = _G.PathwayGuide
	if not guide then return end
	if not tip then BuildTip(guide) end
	local text = S().wowproTips ~= false and guide:IsShown() and self:WoWProTip(self:Current())
	if not text then tip:Hide() return end
	if tip.shown ~= text then
		tip.shown = text
		tip.text:SetText(text)
	end
	-- the text's width set first, so its height counts every wrapped line and the
	-- credit always sits inside the window
	local function Fit()
		local w = (tonumber(guide:GetWidth()) or 300) - 16 - 12
		tip.text:SetWidth(w); tip.credit:SetWidth(w)
		local h = 9 + (tonumber(tip.head:GetStringHeight()) or 12) + 4 + (tonumber(tip.text:GetStringHeight()) or 14)
			+ 5 + (tonumber(tip.credit:GetStringHeight()) or 12) + 9
		tip:SetHeight(math.floor(h + 0.5))
	end
	Fit()
	Place(guide)
	tip:Show()
	-- once more a frame later, when the fonts have laid out
	C_Timer.After(0, function() if tip:IsShown() then Fit(); Place(guide) end end)
end

if P.UpdateGuide then hooksecurefunc(P, "UpdateGuide", function(self) pcall(self.UpdateWoWProTip, self) end) end
P:Listen("READY", function()
	-- the other faction's guides are never needed: let them go
	C_Timer.After(10, function() if not done and S().wowproTips ~= false then Background() end end)
end)
end part() end
-- ==================== Setup.lua
do local __addon, __ns = ... local function part()
-- Copyright (C) 2026 SoFinSicc. Part of Pathway (curseforge.com/wow/addons/pathway): free software under the GPLv3 or later, with additional terms that require keeping this credit. See LICENSE.md.
--[[ Pathway — First-time setup and tips
     The first time you log in, one small panel asks three things: how big you
     want everything, what color, and how you like to do each step (the magic
     button, the quest bar, or both). Every answer shows right away, so you see
     what you get. /pw setup brings it back.
     Tips: the first time something new appears (the magic button, the guide,
     its tabs, the journal), a short note says what it does. Once each. ]]

local ADDON, P = __addon, __ns
local A = P.ACCENT

local function S() return P.db.settings end
local SETUP_VERSION = 7          -- new questions bring the panel back once
P.SETUP_VERSION = SETUP_VERSION
local function Changed() P:ApplyTheme(); P:Send("SETTINGS_CHANGED") end

---------------------------------------------------------------------------
-- Tips: a small callout next to something, shown once
---------------------------------------------------------------------------
local tip, tipQueue = nil, {}
local function BuildTip()
	tip = CreateFrame("Frame", "PathwayTip", UIParent, "BackdropTemplate")
	P:ApplySizes()
	P.Flat(tip, P.colors.BG, P.colors.ACCENT_EDGE)
	tip:SetFrameStrata("DIALOG")
	tip:SetClampedToScreen(true)
	tip:SetWidth(250)
	tip.bar = tip:CreateTexture(nil, "ARTWORK"); tip.bar:SetPoint("TOPLEFT", 1, -1); tip.bar:SetPoint("TOPRIGHT", -1, -1); tip.bar:SetHeight(2)
	tip.title = tip:CreateFontString(nil, "OVERLAY"); tip.title:SetFontObject(P.fonts.title)
	tip.title:SetPoint("TOPLEFT", 12, -10); tip.title:SetPoint("RIGHT", -12, 0); tip.title:SetJustifyH("LEFT")
	tip.text = tip:CreateFontString(nil, "OVERLAY"); tip.text:SetFontObject(P.fonts.button)
	tip.text:SetPoint("TOPLEFT", tip.title, "BOTTOMLEFT", 0, -5); tip.text:SetPoint("RIGHT", -12, 0)
	tip.text:SetJustifyH("LEFT"); tip.text:SetSpacing(2)
	tip.ok = P:FlatButton(tip, "Got it", true)
	tip.ok:SetPoint("BOTTOMRIGHT", -10, 9)
	tip.ok:SetScript("OnClick", function() tip:Hide() end)
	tip:SetScript("OnHide", function()
		local nextT = table.remove(tipQueue, 1)
		if nextT then C_Timer.After(0.4, function() P:Tip(nextT[1], nextT[2], nextT[3], nextT[4]) end) end
	end)
	tip:Hide()
end

-- key: shown once ever; anchor: the frame it points at; side: where the tip goes
function P:Tip(key, anchor, title, text, side)
	if not (P.db and anchor and anchor.IsShown and anchor:IsShown()) then return end
	P.db.tips = P.db.tips or {}
	if P.db.tips[key] or S().tips == false then return end
	if (P.InSetup and P:InSetup()) or P.placing then return end      -- never over setup; it shows later
	if not tip then BuildTip() end
	if tip:IsShown() then
		for _, q in ipairs(tipQueue) do if q[1] == key then return end end
		tipQueue[#tipQueue + 1] = { key, anchor, title, text }
		return
	end
	if InCombatLockdown() then return end
	P.db.tips[key] = true
	tip.bar:SetColorTexture(A[1], A[2], A[3], 1)
	tip.title:SetText(title)
	tip.text:SetText(text)
	tip:SetHeight(10 + tip.title:GetStringHeight() + 5 + tip.text:GetStringHeight() + 40)
	tip:ClearAllPoints()
	-- beside the thing, on whichever side has room
	local cx = tonumber((anchor:GetCenter())) or 0
	local ea, eu = tonumber(anchor:GetEffectiveScale()) or 1, tonumber(UIParent:GetEffectiveScale()) or 1
	local onRight = cx * ea < ((tonumber(UIParent:GetWidth()) or 1000) * eu) / 2
	side = side or (onRight and "RIGHT" or "LEFT")
	if side == "RIGHT" then tip:SetPoint("LEFT", anchor, "RIGHT", 12, 0)
	elseif side == "LEFT" then tip:SetPoint("RIGHT", anchor, "LEFT", -12, 0)
	elseif side == "TOP" then tip:SetPoint("BOTTOM", anchor, "TOP", 0, 12)
	else tip:SetPoint("TOP", anchor, "BOTTOM", 0, -12) end
	tip:Show()
end

function P:ResetTips() if P.db then P.db.tips = {} end end

---------------------------------------------------------------------------
-- The setup panel
---------------------------------------------------------------------------
local panel
local SIZES = { { "auto", "Auto" }, { "normal", "Normal" }, { "large", "Large" }, { "huge", "Extra large" } }
local MAPSIZE = { auto = nil, normal = 1, large = 1.15, huge = 1.3 }
local STYLES = {
	{ "magic", "Magic button", "One button does each step: targets what you need, then uses the quest item." },
	{ "bar", "Quest bar", "A box for each thing to target and each item to use." },
	{ "both", "Both", "The magic button and the quest bar." },
}

local function Choice(parent, y, label, list, get, set)
	local fs = parent:CreateFontString(nil, "OVERLAY"); fs:SetFontObject(P.fonts.title)
	fs:SetPoint("TOPLEFT", 18, y); fs:SetText(label)
	local buttons, x = {}, 18
	for _, o in ipairs(list) do
		local b = P:FlatButton(parent, o[2])
		b.minW = 84
		b:SetLabel(o[2])
		b:SetPoint("TOPLEFT", x, y - 22)
		b.tip = o[3]
		b:SetScript("OnClick", function() set(o[1]); parent:Refresh() end)
		b.value = o[1]
		x = x + b:GetWidth() + 6
		buttons[#buttons + 1] = b
	end
	parent.refreshers[#parent.refreshers + 1] = function()
		local v = get()
		for _, b in ipairs(buttons) do
			local on = b.value == v
			b.edge = on and { A[1], A[2], A[3], 1 } or P.colors.EDGE
			b:SetBackdropBorderColor(unpack(b.edge))
			b.text:SetTextColor(on and 1 or 0.75, on and 1 or 0.78, on and 1 or 0.82)
		end
	end
end

local function Build()
	panel = CreateFrame("Frame", "PathwaySetup", UIParent, "BackdropTemplate")
	P:ApplySizes()
	P.Flat(panel, nil, nil, true)
	panel:SetSize(500, 600)
	panel:SetPoint("CENTER", UIParent, "CENTER", 0, 60)
	panel:SetFrameStrata("DIALOG")
	panel:EnableMouse(true); panel:SetMovable(true); panel:RegisterForDrag("LeftButton")
	panel:SetScript("OnDragStart", panel.StartMoving); panel:SetScript("OnDragStop", panel.StopMovingOrSizing)
	panel.refreshers = {}
	function panel:Refresh() for _, fn in ipairs(self.refreshers) do fn() end end

	local icon = panel:CreateTexture(nil, "ARTWORK"); icon:SetSize(36, 36); icon:SetPoint("TOPLEFT", 16, -14)
	icon:SetTexture(P.MEDIA .. "Icon")
	local title = panel:CreateFontString(nil, "OVERLAY"); title:SetFontObject(P.fonts.big)
	title:SetPoint("TOPLEFT", icon, "TOPRIGHT", 10, -2)
	panel.title = title
	local sub = panel:CreateFontString(nil, "OVERLAY"); sub:SetFontObject(P.fonts.head)
	sub:SetPoint("TOPLEFT", title, "BOTTOMLEFT", 0, -4)
	sub:SetText("A few quick choices. You'll see each one change as you click.")
	local close = P:CloseButton(panel, function() panel:Hide() end); close:SetPoint("TOPRIGHT", -6, -6)

	-- 1. size
	Choice(panel, -70, "How big should everything be?", SIZES,
		function() return S().uiSize or "auto" end,
		function(v)
			S().uiSize = v
			local ms = MAPSIZE[v] or math.min(1.3, P:AutoScale())
			local e = P.GoodMap.ready and P.GoodMap.E
			if e and e.SetLive then e.SetLive("scale", ms) end
			Changed()
		end)

	-- 2. color
	local cl = panel:CreateFontString(nil, "OVERLAY"); cl:SetFontObject(P.fonts.title)
	cl:SetPoint("TOPLEFT", 18, -136); cl:SetText("Pick a color")
	local sw, x = {}, 18
	for _, a in ipairs(P.ACCENTS or {}) do
		local c = a[2]
		local b = CreateFrame("Button", nil, panel, "BackdropTemplate")
		b:SetSize(34, 24); b:SetPoint("TOPLEFT", x, -158)
		P.Flat(b, { c[1], c[2], c[3], 1 }, P.colors.EDGE)
		b:SetScript("OnEnter", function() GameTooltip:SetOwner(b, "ANCHOR_TOP"); GameTooltip:SetText(a[1], 1, 1, 1); GameTooltip:Show() end)
		b:SetScript("OnLeave", GameTooltip_Hide)
		b:SetScript("OnClick", function() S().accent = { c[1], c[2], c[3] }; Changed(); panel:Refresh() end)
		b.c = c
		sw[#sw + 1] = b
		x = x + 40
	end
	panel.refreshers[#panel.refreshers + 1] = function()
		local ac = S().accent or A
		for _, b in ipairs(sw) do
			local same = math.abs(b.c[1] - ac[1]) + math.abs(b.c[2] - ac[2]) + math.abs(b.c[3] - ac[3]) < 0.02
			b:SetBackdropBorderColor(unpack(same and { 1, 1, 1, 1 } or P.colors.EDGE))
		end
	end

	-- 4. how to do each step
	Choice(panel, -196, "How do you like to do each step?", STYLES,
		function()
			local m, b = S().magicButton, S().questBar
			return (m and b) and "both" or b and "bar" or "magic"
		end,
		function(v)
			S().magicButton = v ~= "bar"
			S().questBar = v ~= "magic"
			Changed()
		end)
	local desc = panel:CreateFontString(nil, "OVERLAY"); desc:SetFontObject(P.fonts.head)
	desc:SetPoint("TOPLEFT", 18, -248); desc:SetPoint("RIGHT", -18, 0); desc:SetJustifyH("LEFT"); desc:SetSpacing(2)
	panel.refreshers[#panel.refreshers + 1] = function()
		local m, b = S().magicButton, S().questBar
		desc:SetText((m and b) and STYLES[3][3] or b and STYLES[2][3] or STYLES[1][3])
	end

	-- how to quest each zone
	local QS = {}
	for _, st in ipairs(P.STYLES or {}) do QS[#QS + 1] = { st.key, st.label, st.tip } end
	Choice(panel, -278, "How do you want to quest?", QS,
		function() return S().questStyle or "fast" end,
		function(v) S().questStyle = v; Changed() end)
	local qd = panel:CreateFontString(nil, "OVERLAY"); qd:SetFontObject(P.fonts.head)
	qd:SetPoint("TOPLEFT", 18, -330); qd:SetPoint("RIGHT", -18, 0); qd:SetJustifyH("LEFT"); qd:SetSpacing(2)
	panel.refreshers[#panel.refreshers + 1] = function()
		local k = S().questStyle or "fast"
		for _, st in ipairs(P.STYLES or {}) do if st.key == k then qd:SetText((st.short or st.tip) .. "  Switch any time at the top of the guide.") end end
	end

	-- how solid the windows are
	local OPAC = { { 1, "Solid", "Nothing shows through." }, { 0.95, "Standard", "Almost solid." },
		{ 0.7, "Soft", "The game shows through a little." }, { 0.4, "See-through", "Mostly the game, with the text on top." } }
	Choice(panel, -362, "How solid should the windows be?", OPAC,
		function()
			local v, best, bd = S().bgAlpha or 0.95, 0.95, 9
			for _, o in ipairs(OPAC) do local d = math.abs(o[1] - v); if d < bd then best, bd = o[1], d end end
			return best
		end,
		function(v) S().bgAlpha = v; Changed() end)

	-- where pop-ups come up
	local SPOTS = { { "bottom", "Above the magic button", "Bottom middle, just over the magic button." },
		{ "middle", "Middle", "The middle of the screen." }, { "top", "Top", "Top middle, under the arrow." } }
	Choice(panel, -420, "Where should pop-ups appear?", SPOTS,
		function() return S().popupSpot or "bottom" end,
		function(v) S().popupSpot = v; P.db.pos.popups = nil; Changed() end)
	local pd = panel:CreateFontString(nil, "OVERLAY"); pd:SetFontObject(P.fonts.head)
	pd:SetPoint("TOPLEFT", 18, -472); pd:SetPoint("RIGHT", -18, 0); pd:SetJustifyH("LEFT")
	pd:SetText("Questions, gear and talent tips, campfires. Shift-drag one any time to move them all.")

	-- one more: talking to quest givers
	local aa = P:FlatButton(panel, "")
	aa:SetPoint("TOPLEFT", 18, -500)
	aa:SetScript("OnClick", function() S().autoAccept = not S().autoAccept; S().autoTurnIn = S().autoAccept; Changed(); panel:Refresh() end)
	panel.refreshers[#panel.refreshers + 1] = function()
		aa:SetLabel((S().autoAccept and "|c" .. P.ACCENT_HEX .. "On|r" or "|cff8a929bOff|r") .. "   Accept and turn in quests for me")
	end
	local aad = panel:CreateFontString(nil, "OVERLAY"); aad:SetFontObject(P.fonts.head)
	aad:SetPoint("TOPLEFT", aa, "BOTTOMLEFT", 2, -4); aad:SetText("Only the ones Pathway suggests. Hold Shift to do it yourself.")

	local done = P:FlatButton(panel, "Let's go", true)
	panel.done = done
	done.minW = 120; done:SetLabel("Let's go")
	done:SetPoint("BOTTOMRIGHT", -16, 14)
	local function MapFits()
		-- one Pathway button carries the minimap's menu: no second launcher in the bar
		local e = P.GoodMap.ready and P.GoodMap.E
		if e and e.SetLive then e.SetLive("barLauncher", false) end
		-- the minimap grows with everything else when the size is automatic
		if (S().uiSize or "auto") == "auto" and e and e.SetLive then
			e.SetLive("scale", math.floor(math.min(1.3, P:AutoScale()) * 20 + 0.5) / 20)
		end
	end
	panel.next = P:FlatButton(panel, "Next  >", true)
	panel.next.minW = 120; panel.next:SetLabel("Next  >")
	panel.next:SetPoint("BOTTOMRIGHT", -16, 14)
	panel.next:SetScript("OnClick", function() MapFits(); panel:Hide(); P:SetupNext("look") end)
	panel.step = panel:CreateFontString(nil, "OVERLAY"); panel.step:SetFontObject(P.fonts.head)
	panel.step:SetPoint("TOPRIGHT", -34, -14)
	done:SetScript("OnClick", function()
		MapFits()
		panel:Hide()
		P:FinishSetup()
	end)
	local later = P:FlatButton(panel, "Keep the defaults")
	later:SetPoint("BOTTOMLEFT", 16, 14)
	later:SetScript("OnClick", function()
		MapFits(); panel:Hide()
		P:FinishSetup()
	end)
	tinsert(UISpecialFrames, "PathwaySetup")
	panel:HookScript("OnHide", function() P:SetupClosed() end)
end

function P:ShowSetup()
	if not panel then Build() end
	panel.next:Show()
	panel.done:Hide()
	panel.step:SetText(P.DIM .. P:SetupStepLabel("look") .. "|r")
	local name = UnitName("player")
	panel.title:SetText("Welcome to " .. (P.TITLE or "Pathway") .. ((type(name) == "string" and not (issecretvalue and issecretvalue(name))) and (", " .. name) or ""))
	panel:Refresh()
	panel:Show()
end

StaticPopupDialogs["PATHWAY_PARTS_RELOAD"] = {
	text = "Bags, the minimap and fishing switch on or off after a quick reload. Reload now?",
	button1 = "Reload", button2 = "Later", OnAccept = function() ReloadUI() end,
	timeout = 0, whileDead = true, hideOnEscape = true,
}

---------------------------------------------------------------------------
-- Step one: which parts of Pathway do you want? Everything after this only
-- asks about the parts you picked.
---------------------------------------------------------------------------
local PARTS = {
	{ "guide", "Quest guide", "The arrow, the step window and the magic button", "Interface\\Icons\\INV_Misc_Map_01",
		get = function() return S().guideWindow end,
		set = function(on) S().guideWindow, S().arrow, S().magicButton = on, on, on; if not on then S().questBar = false end end },
	{ "goodmap", "Minimap", "Your zone map as the minimap, styled your way", "Interface\\Icons\\INV_Misc_Spyglass_03", reload = true },
	{ "bags", "Bags", "One clean bag with a Loot Inbox for new things", "Interface\\Icons\\INV_Misc_Bag_08", reload = true },
	{ "gearAlerts", "Gear help", "Upgrades noticed, compared and put on", "Interface\\Icons\\INV_Chest_Chain_05" },
	{ "talentHints", "Talent tips", "Which talent to take next, marked in the tree", "Interface\\Icons\\Ability_Marksmanship" },
	{ "pvpCard", "Player cards", "Who a player is and your odds against them", "Interface\\Icons\\Achievement_PVP_A_01" },
	{ "meter", "Damage meter", "Your group's numbers and your range, live", "Interface\\Icons\\Ability_DualWield" },
	{ "fishing", "Fishing", "Scroll to cast, a bite timer and a catch journal", "Interface\\Icons\\Trade_Fishing", reload = true },
	{ "fps", "Performance meter", "Frame rate, latency, and what's slowing you down", "Interface\\Icons\\INV_Misc_PocketWatch_01" },
}
local parts
local function PartOn(pt) if pt.get then return pt.get() and true or false end return P.GetSetting(pt[1]) and true or false end
local function PartSet(pt, on) if pt.set then pt.set(on) else P.SetSetting(pt[1], on) end end

function P:ShowParts()
	if not parts then
		parts = CreateFrame("Frame", "PathwaySetupParts", UIParent, "BackdropTemplate")
		P.Flat(parts, nil, nil, true)
		parts:SetSize(520, 456)
		parts:SetPoint("CENTER", UIParent, "CENTER", 0, 60)
		parts:SetFrameStrata("DIALOG")
		parts:EnableMouse(true); parts:SetMovable(true); parts:RegisterForDrag("LeftButton")
		parts:SetScript("OnDragStart", parts.StartMoving); parts:SetScript("OnDragStop", parts.StopMovingOrSizing)
		local icon = parts:CreateTexture(nil, "ARTWORK"); icon:SetSize(36, 36); icon:SetPoint("TOPLEFT", 16, -14)
		icon:SetTexture(P.MEDIA .. "Icon")
		local title = parts:CreateFontString(nil, "OVERLAY"); title:SetFontObject(P.fonts.big)
		title:SetPoint("TOPLEFT", icon, "TOPRIGHT", 10, -2)
		parts.title = title
		local sub = parts:CreateFontString(nil, "OVERLAY"); sub:SetFontObject(P.fonts.head)
		sub:SetPoint("TOPLEFT", title, "BOTTOMLEFT", 0, -4)
		sub:SetText("What should Pathway do for you? Click to turn a part on or off.")
		parts.tiles = {}
		for i, pt in ipairs(PARTS) do
			local b = CreateFrame("Button", nil, parts, "BackdropTemplate")
			P.Flat(b, P.colors.BG, P.colors.EDGE)
			b:SetSize(236, 58)
			b:SetPoint("TOPLEFT", 16 + ((i - 1) % 2) * 252, -66 - math.floor((i - 1) / 2) * 66)
			b.icon = b:CreateTexture(nil, "ARTWORK"); b.icon:SetSize(34, 34); b.icon:SetPoint("LEFT", 10, 0)
			b.icon:SetTexture(pt[4]); b.icon:SetTexCoord(0.08, 0.92, 0.08, 0.92)
			b.name = b:CreateFontString(nil, "OVERLAY"); b.name:SetFontObject(P.fonts.title)
			b.name:SetPoint("TOPLEFT", b.icon, "TOPRIGHT", 10, 0); b.name:SetText(pt[2])
			b.desc = b:CreateFontString(nil, "OVERLAY"); b.desc:SetFontObject(P.fonts.head)
			b.desc:SetPoint("TOPLEFT", b.name, "BOTTOMLEFT", 0, -3); b.desc:SetPoint("RIGHT", -10, 0)
			b.desc:SetJustifyH("LEFT"); b.desc:SetText(pt[3]); b.desc:SetMaxLines(2)
			b.state = b:CreateFontString(nil, "OVERLAY"); b.state:SetFontObject(P.fonts.head); b.state:SetPoint("TOPRIGHT", -8, -6)
			b.paint = function()
				local on = PartOn(pt)
				b:SetBackdropBorderColor(unpack(on and { A[1], A[2], A[3], 1 } or P.colors.EDGE))
				b.icon:SetDesaturated(not on); b.icon:SetAlpha(on and 1 or 0.5)
				b.name:SetTextColor(on and 1 or 0.6, on and 1 or 0.62, on and 1 or 0.66)
				b.state:SetText(on and ("|c" .. P.ACCENT_HEX .. "On|r") or "|cff8a929bOff|r")
			end
			b:SetScript("OnClick", function() PartSet(pt, not PartOn(pt)); b.paint() end)
			parts.tiles[i] = b
		end
		local nextB = P:FlatButton(parts, "Next  >", true)
		nextB.minW = 120; nextB:SetLabel("Next  >")
		nextB:SetPoint("BOTTOMRIGHT", -16, 14)
		nextB:SetScript("OnClick", function()
			parts:Hide()
			local reload = false
			for _, pt in ipairs(PARTS) do
				if pt.reload and parts.was[pt[1]] ~= PartOn(pt) then reload = true end
			end
			P.partsNeedReload = reload
			P:SetupNext("parts")
		end)
		parts.step = parts:CreateFontString(nil, "OVERLAY"); parts.step:SetFontObject(P.fonts.head)
		parts.step:SetPoint("TOPRIGHT", -16, -16)
		local keep = P:FlatButton(parts, "Keep everything on")
		keep:SetPoint("BOTTOMLEFT", 16, 14)
		keep:SetScript("OnClick", function()
			for _, pt in ipairs(PARTS) do if not PartOn(pt) then PartSet(pt, true) end end
			for _, t in ipairs(parts.tiles) do t.paint() end
		end)
		local foot = parts:CreateFontString(nil, "OVERLAY"); foot:SetFontObject(P.fonts.head)
		foot:SetPoint("BOTTOMLEFT", keep, "TOPLEFT", 0, 8)
		foot:SetText(P.DIM .. "Change these any time from the Pathway button on your minimap.|r")
		tinsert(UISpecialFrames, "PathwaySetupParts")
		parts:HookScript("OnHide", function() P:SetupClosed() end)
		P:ApplySizes()
	end
	parts.was = {}
	for _, pt in ipairs(PARTS) do parts.was[pt[1]] = PartOn(pt) end
	local name = UnitName("player")
	parts.title:SetText("Welcome to " .. (P.TITLE or "Pathway") .. ((type(name) == "string" and not (issecretvalue and issecretvalue(name))) and (", " .. name) or ""))
	for _, t in ipairs(parts.tiles) do t.paint() end
	parts.step:SetText(P.DIM .. P:SetupStepLabel("parts") .. "|r")
	parts:Show()
end

---------------------------------------------------------------------------
-- The walk through setup: only the steps for the parts you picked
---------------------------------------------------------------------------
local function HasMap() return P.GoodMap and P.GoodMap.ready and P.GetSetting("goodmap") ~= false end
local function AddonButtons()
	local E = P.GoodMap and P.GoodMap.E
	return (HasMap() and E and E.AddonButtons) and E.AddonButtons() or {}
end
local function Steps()
	local list = { "parts", "look" }
	if S().meter and P:MeterAvailable() then list[#list + 1] = "meter" end
	if HasMap() then list[#list + 1] = "map" end
	if #AddonButtons() > 0 then list[#list + 1] = "buttons" end
	list[#list + 1] = "place"
	return list
end
function P:SetupDone() return (P.db and P.db.setupVersion or 0) >= SETUP_VERSION end
function P:SetupStepLabel(key)
	local list = Steps()
	for i, k in ipairs(list) do if k == key then return ("Step %d of %d"):format(i, #list) end end
	return ""
end
local SHOW = {
	parts = function() P:ShowParts() end,
	look = function() P:ShowSetup() end,
	meter = function() P:ShowMeterStep() end,
	map = function() P:ShowMapLook() end,
	buttons = function() P:ShowBarButtons(true) end,
	place = function() P:FinishSetup() end,
}
local function Go(from, dir)
	local list = Steps()
	for i, k in ipairs(list) do
		if k == from then
			local to = list[i + dir]
			if to then SHOW[to]() end
			return
		end
	end
	SHOW[dir > 0 and "place" or "parts"]()
end
function P:SetupNext(from) Go(from, 1) end
function P:SetupBack(from) Go(from, -1) end

---------------------------------------------------------------------------
-- Step: the damage meter, as much or as little as you like
---------------------------------------------------------------------------
local METER_STYLES = {
	{ "simple", "Simple", "Just your own damage per second, small and quiet.", "Interface\\Icons\\Ability_DualWield" },
	{ "group", "Standard", "Everyone in your party or raid, bars moving live, with the group total.", "Interface\\Icons\\Achievement_GuildPerk_EverybodysFriend" },
	{ "detailed", "Detailed", "Your group, plus your range: worst, best and average fight, with this fight moving along it.", "Interface\\Icons\\INV_Misc_Spyglass_03" },
}
local meterPage
function P:ShowMeterStep()
	if not meterPage then
		local f = CreateFrame("Frame", "PathwaySetupMeter", UIParent, "BackdropTemplate")
		meterPage = f
		P.Flat(f, nil, nil, true)
		f:SetSize(520, 360)
		f:SetPoint("CENTER", UIParent, "CENTER", 0, 60)
		f:SetFrameStrata("DIALOG")
		f:EnableMouse(true); f:SetMovable(true); f:RegisterForDrag("LeftButton")
		f:SetScript("OnDragStart", f.StartMoving); f:SetScript("OnDragStop", f.StopMovingOrSizing)
		local icon = f:CreateTexture(nil, "ARTWORK"); icon:SetSize(36, 36); icon:SetPoint("TOPLEFT", 16, -14)
		icon:SetTexture(P.MEDIA .. "Icon")
		local title = f:CreateFontString(nil, "OVERLAY"); title:SetFontObject(P.fonts.big)
		title:SetPoint("TOPLEFT", icon, "TOPRIGHT", 10, -2); title:SetText("Your damage meter")
		local sub = f:CreateFontString(nil, "OVERLAY"); sub:SetFontObject(P.fonts.head)
		sub:SetPoint("TOPLEFT", title, "BOTTOMLEFT", 0, -4); sub:SetText("How much should it show? You can change this any time in settings.")
		f.step = f:CreateFontString(nil, "OVERLAY"); f.step:SetFontObject(P.fonts.head); f.step:SetPoint("TOPRIGHT", -16, -16)
		f.tiles = {}
		for i, m in ipairs(METER_STYLES) do
			local b = CreateFrame("Button", nil, f, "BackdropTemplate")
			P.Flat(b, P.colors.BG, P.colors.EDGE)
			b:SetSize(488, 58); b:SetPoint("TOPLEFT", 16, -66 - (i - 1) * 66)
			b.icon = b:CreateTexture(nil, "ARTWORK"); b.icon:SetSize(34, 34); b.icon:SetPoint("LEFT", 10, 0)
			b.icon:SetTexture(m[4]); b.icon:SetTexCoord(0.08, 0.92, 0.08, 0.92)
			b.name = b:CreateFontString(nil, "OVERLAY"); b.name:SetFontObject(P.fonts.title)
			b.name:SetPoint("TOPLEFT", b.icon, "TOPRIGHT", 10, 0); b.name:SetText(m[2])
			b.desc = b:CreateFontString(nil, "OVERLAY"); b.desc:SetFontObject(P.fonts.head)
			b.desc:SetPoint("TOPLEFT", b.name, "BOTTOMLEFT", 0, -3); b.desc:SetPoint("RIGHT", -10, 0)
			b.desc:SetJustifyH("LEFT"); b.desc:SetText(m[3])
			b.paint = function()
				local on = (S().meterStyle or "detailed") == m[1]
				b:SetBackdropBorderColor(unpack(on and { A[1], A[2], A[3], 1 } or P.colors.EDGE))
				b.name:SetTextColor(on and 1 or 0.7, on and 1 or 0.72, on and 1 or 0.76)
			end
			b:SetScript("OnClick", function()
				S().meterStyle = m[1]
				for _, t in ipairs(f.tiles) do t.paint() end
				if P.RefreshMeter then P:RefreshMeter() end
			end)
			f.tiles[i] = b
		end
		f.combat = P:FlatButton(f, "")
		f.combat:SetPoint("TOPLEFT", 16, -270)
		f.combat:SetScript("OnClick", function()
			S().meterCombatOnly = not S().meterCombatOnly
			f.combat.paint()
			if P.RefreshMeter then P:RefreshMeter() end
		end)
		f.combat.paint = function()
			f.combat:SetLabel((S().meterCombatOnly and ("|c" .. P.ACCENT_HEX .. "On|r") or "|cff8a929bOff|r") .. "   Only show it during a fight")
		end
		local back = P:FlatButton(f, "<  Back"); back:SetPoint("BOTTOMLEFT", 16, 14)
		back:SetScript("OnClick", function() f:Hide(); P:SetupBack("meter") end)
		local nextB = P:FlatButton(f, "Next  >", true); nextB.minW = 120; nextB:SetLabel("Next  >")
		nextB:SetPoint("BOTTOMRIGHT", -16, 14)
		nextB:SetScript("OnClick", function() f:Hide(); P:SetupNext("meter") end)
		tinsert(UISpecialFrames, "PathwaySetupMeter")
		f:HookScript("OnHide", function() P:SetupClosed() end)
		P:ApplySizes()
	end
	for _, t in ipairs(meterPage.tiles) do t.paint() end
	meterPage.combat.paint()
	meterPage.step:SetText(P.DIM .. P:SetupStepLabel("meter") .. "|r")
	meterPage:Show()
end

---------------------------------------------------------------------------
-- Step: other add-ons' minimap buttons. None sit on the bar unless you pick
-- them; the rest wait in the add-on list (the numbered button), a click away.
---------------------------------------------------------------------------
local btnPage
local TILE_W, TILE_H, PER_ROW, MAX_TILES = 236, 44, 2, 16
function P:ShowBarButtons(inSetup)
	local E = P.GoodMap and P.GoodMap.E
	if not (E and E.AddonButtons) then return end
	local items = AddonButtons()
	if not btnPage then
		local f = CreateFrame("Frame", "PathwaySetupButtons", UIParent, "BackdropTemplate")
		btnPage = f
		P.Flat(f, nil, nil, true)
		f:SetWidth(520)
		f:SetPoint("CENTER", UIParent, "CENTER", 0, 60)
		f:SetFrameStrata("DIALOG")
		f:EnableMouse(true); f:SetMovable(true); f:RegisterForDrag("LeftButton")
		f:SetScript("OnDragStart", f.StartMoving); f:SetScript("OnDragStop", f.StopMovingOrSizing)
		local icon = f:CreateTexture(nil, "ARTWORK"); icon:SetSize(36, 36); icon:SetPoint("TOPLEFT", 16, -14)
		icon:SetTexture(P.MEDIA .. "Icon")
		local title = f:CreateFontString(nil, "OVERLAY"); title:SetFontObject(P.fonts.big)
		title:SetPoint("TOPLEFT", icon, "TOPRIGHT", 10, -2); title:SetText("Your add-on buttons")
		local sub = f:CreateFontString(nil, "OVERLAY"); sub:SetFontObject(P.fonts.head)
		sub:SetPoint("TOPLEFT", title, "BOTTOMLEFT", 0, -4); sub:SetPoint("RIGHT", -16, 0); sub:SetJustifyH("LEFT")
		sub:SetText("Which should sit on the minimap's bar? The rest wait in the add-on list (the numbered button), a click away.")
		f.step = f:CreateFontString(nil, "OVERLAY"); f.step:SetFontObject(P.fonts.head); f.step:SetPoint("TOPRIGHT", -16, -16)
		f.tiles = {}
		for i = 1, MAX_TILES do
			local b = CreateFrame("Button", nil, f, "BackdropTemplate")
			P.Flat(b, P.colors.BG, P.colors.EDGE)
			b:SetSize(TILE_W, TILE_H)
			b:SetPoint("TOPLEFT", 16 + ((i - 1) % PER_ROW) * (TILE_W + 16), -78 - math.floor((i - 1) / PER_ROW) * (TILE_H + 8))
			b.icon = b:CreateTexture(nil, "ARTWORK"); b.icon:SetSize(28, 28); b.icon:SetPoint("LEFT", 8, 0)
			b.name = b:CreateFontString(nil, "OVERLAY"); b.name:SetFontObject(P.fonts.title)
			b.name:SetPoint("LEFT", b.icon, "RIGHT", 10, 0); b.name:SetPoint("RIGHT", -52, 0); b.name:SetJustifyH("LEFT")
			b.state = b:CreateFontString(nil, "OVERLAY"); b.state:SetFontObject(P.fonts.head); b.state:SetPoint("RIGHT", -10, 0)
			b.paint = function()
				local on = b.item and E.OnBar(b.item.key)
				b:SetBackdropBorderColor(unpack(on and { A[1], A[2], A[3], 1 } or P.colors.EDGE))
				b.icon:SetDesaturated(not on); b.icon:SetAlpha(on and 1 or 0.6)
				b.name:SetTextColor(on and 1 or 0.7, on and 1 or 0.72, on and 1 or 0.76)
				b.state:SetText(on and ("|c" .. P.ACCENT_HEX .. "On the bar|r") or "|cff8a929bIn the list|r")
			end
			b:SetScript("OnClick", function(self)
				if not self.item then return end
				E.SetOnBar(self.item.key, not E.OnBar(self.item.key))
				self.paint()
			end)
			f.tiles[i] = b
		end
		f.back = P:FlatButton(f, "<  Back"); f.back:SetPoint("BOTTOMLEFT", 16, 14)
		f.back:SetScript("OnClick", function() f.leaving = true; f:Hide(); P:SetupBack("buttons") end)
		f.nextB = P:FlatButton(f, "Next  >", true); f.nextB.minW = 120; f.nextB:SetLabel("Next  >")
		f.nextB:SetPoint("BOTTOMRIGHT", -16, 14)
		f.nextB:SetScript("OnClick", function()
			f.leaving = true; f:Hide()
			if f.inSetup then P:SetupNext("buttons") end
		end)
		f.foot = f:CreateFontString(nil, "OVERLAY"); f.foot:SetFontObject(P.fonts.head)
		f.foot:SetPoint("BOTTOMLEFT", f.back, "TOPLEFT", 0, 8)
		f.foot:SetText(P.DIM .. "When you add an add-on later, Pathway asks once where its button goes.|r")
		tinsert(UISpecialFrames, "PathwaySetupButtons")
		f:HookScript("OnHide", function() if f.inSetup and not f.leaving then P:SetupClosed() end f.leaving = nil end)
		P:ApplySizes()
	end
	local f = btnPage
	f.inSetup = inSetup and true or false
	for i, b in ipairs(f.tiles) do
		local it = items[i]
		b.item = it
		if it then
			b.icon:SetTexture(it.icon or "Interface\\Icons\\INV_Misc_QuestionMark")
			b.name:SetText(it.label)
			b.paint()
			b:Show()
		else
			b:Hide()
		end
	end
	local rows = math.max(1, math.ceil(math.min(#items, MAX_TILES) / PER_ROW))
	f:SetHeight(78 + rows * (TILE_H + 8) + 70)
	f.back:SetShown(f.inSetup)
	f.nextB:SetLabel(f.inSetup and "Next  >" or "Done")
	f.step:SetText(f.inSetup and (P.DIM .. P:SetupStepLabel("buttons") .. "|r") or "")
	-- everything listed here has been asked about
	local E2 = P.GoodMap and P.GoodMap.E
	if E2 and E2.MarkButtonsSeen then E2.MarkButtonsSeen(items) end
	f:Show()
end

-- the first time on this account: setup comes before anything else asks
P:Listen("READY", function()
	if (P.db.setupVersion or 0) >= SETUP_VERSION then return end
	-- the magic button does each step out of the box; the quest bar is there if you want it
	if not P.db.setupDone then S().magicButton, S().questBar = true, false end
	C_Timer.After(2.5, function()
		if InCombatLockdown() then return end
		P:ShowParts()
	end)
end)
end part() end
-- ==================== Place.lua
do local __addon, __ns = ... local function part()
-- Copyright (C) 2026 SoFinSicc. Part of Pathway (curseforge.com/wow/addons/pathway): free software under the GPLv3 or later, with additional terms that require keeping this credit. See LICENSE.md.
--[[ Pathway — Place your windows
     The last step of setup: each window you chose shows on its own, glowing,
     and you drag it where you want it (Ctrl and the mouse wheel sizes it).
     Next goes to the one after. When you're done they lock in place, so a
     stray click never drags one off; Shift-drag moves one later, and Settings
     > Home has "Place my windows" to do this again. ]]

local ADDON, P = __addon, __ns
local A = P.ACCENT
local function S() return P.db.settings end

---------------------------------------------------------------------------
-- Setup is on screen: nothing else pops up over it
---------------------------------------------------------------------------
local SETUP_FRAMES = { "PathwaySetupParts", "PathwaySetup", "PathwaySetupMeter", "PathwaySetupMap" }
function P:InSetup()
	for _, n in ipairs(SETUP_FRAMES) do
		local f = _G[n]
		if f and f:IsShown() then return true end
	end
	return false
end

-- setup closed any way at all (Escape, the X): the guide and arrow come back
function P:SetupClosed()
	C_Timer.After(0, function()
		if P:InSetup() or P.placing then return end
		if P.UpdateGuide then P:UpdateGuide() end
		if P.RefreshArrow then P:RefreshArrow() end
	end)
end

-- the end of every way through setup: mark it done, then place the windows
function P:FinishSetup()
	P.db.setupDone = true; P.db.setupVersion = P.SETUP_VERSION
	for _, n in ipairs(SETUP_FRAMES) do if _G[n] then _G[n]:Hide() end end
	if P.partsNeedReload then P.partsNeedReload = nil; StaticPopup_Show("PATHWAY_PARTS_RELOAD") end
	-- no guide starts on its own: the guide window offers Fastest XP or the journal
	if P.UpdateGuide then P:UpdateGuide() end
	C_Timer.After(0.3, function() P:PlaceWindows(nil, true) end)
end

---------------------------------------------------------------------------
-- The pieces, in the order they're placed
---------------------------------------------------------------------------
local function G(name) return _G[name] end
local PIECES = {
	{ key = "guide", label = "Guide window", text = "Your step, the one after, and your quests.",
		on = function() return S().guideWindow end,
		frame = function() return G("PathwayGuide") end,
		show = function(f) f:Show() end },
	{ key = "arrow", label = "Arrow", text = "Points the way to your next step.", pos = "arrow",
		on = function() return S().arrow end,
		frame = function() return G("PathwayArrow") end,
		show = function(f) f:Show() end },
	{ key = "magic", label = "Magic button", text = "Click it to target what the step needs, again to use the item.",
		on = function() return S().magicButton end,
		frame = function() return G("PathwayMagicButton") end,
		show = function(f) if not InCombatLockdown() then f:Show() end end },
	{ key = "qbar", label = "Quest bar", text = "A box for each thing to target and each item to use.",
		on = function() return S().questBar end,
		frame = function() return G("PathwayQuestBar") end,
		show = function(f) if not InCombatLockdown() then f:Show() end end },
	{ key = "meter", label = "Damage meter", text = "Your group's numbers, live.",
		on = function() return S().meter and P:MeterAvailable() end,
		frame = function() P:RefreshMeter(); return G("PathwayMeter") end,
		show = function(f) f:Show(); P:UpdateMeter() end },
	{ key = "fps", label = "Performance meter", text = "Frame rate and latency. Hover it to see what's using the most.",
		on = function() return S().fps end,
		frame = function() if P.RefreshFPS then P:RefreshFPS() end return G("PathwayFPS") end,
		show = function(f) f:Show() end },
	{ key = "card", label = "Player card", text = "Shows when you point at a player: their gear level, spec, guild and your odds.",
		on = function() return S().pvpCard end,
		frame = function() return P.PreviewCard and P:PreviewCard(true) end,
		show = function(f) f:Show() end,
		moved = function() S().cardSpot = "fixed" end,
		keep = function() S().cardSpot = "tooltip"; P.db.pos.PathwayPlayerCard = nil end,
		keepLabel = "Show it by the tooltip instead",
		done = function() if P.PreviewCard then P:PreviewCard(false) end end },
}

local function SaveAt(piece, f)
	if f:GetName() == "PathwayGuide" and not piece.pos then P:KeepTop(f) return end
	local p, _, rp, x, y = f:GetPoint()
	if not p then return end
	P.db.pos[piece.pos or f:GetName()] = { p, rp, x, y }
end

---------------------------------------------------------------------------
-- The bar at the top and the glow around the window you're placing
---------------------------------------------------------------------------
local bar, box, list, at, frame, before

local function Points(f)
	local out = {}
	for i = 1, f:GetNumPoints() do out[i] = { f:GetPoint(i) } end
	return out
end
local function SetPoints(f, pts)
	f:ClearAllPoints()
	for _, p in ipairs(pts) do f:SetPoint(unpack(p)) end
end

local function Build()
	bar = CreateFrame("Frame", "PathwayPlaceBar", UIParent, "BackdropTemplate")
	P.Flat(bar, nil, nil, true)
	bar:SetSize(460, 128)
	bar:SetPoint("CENTER", UIParent, "CENTER", 0, 140)
	bar:SetFrameStrata("FULLSCREEN_DIALOG")
	bar:SetClampedToScreen(true)
	-- the bar itself can be dragged out of the way too
	bar:EnableMouse(true); bar:SetMovable(true); bar:RegisterForDrag("LeftButton")
	bar:SetScript("OnDragStart", bar.StartMoving)
	bar:SetScript("OnDragStop", function(self) self:StopMovingOrSizing(); self.moved = true end)
	bar.title = bar:CreateFontString(nil, "OVERLAY"); bar.title:SetFontObject(P.fonts.big)
	bar.title:SetPoint("TOPLEFT", 16, -12)
	bar.step = bar:CreateFontString(nil, "OVERLAY"); bar.step:SetFontObject(P.fonts.head)
	bar.step:SetPoint("TOPRIGHT", -16, -16)
	bar.text = bar:CreateFontString(nil, "OVERLAY"); bar.text:SetFontObject(P.fonts.button)
	bar.text:SetPoint("TOPLEFT", bar.title, "BOTTOMLEFT", 0, -6); bar.text:SetPoint("RIGHT", -16, 0)
	bar.text:SetJustifyH("LEFT"); bar.text:SetSpacing(2)
	bar.how = bar:CreateFontString(nil, "OVERLAY"); bar.how:SetFontObject(P.fonts.head)
	bar.how:SetPoint("TOPLEFT", bar.text, "BOTTOMLEFT", 0, -6); bar.how:SetPoint("RIGHT", -16, 0)
	bar.how:SetJustifyH("LEFT"); bar.how:SetSpacing(2)

	bar.nextB = P:FlatButton(bar, "Next  >", true)
	bar.nextB.minW = 100; bar.nextB:SetPoint("BOTTOMRIGHT", -12, 10)
	bar.nextB:SetScript("OnClick", function() P:PlaceStep(at + 1) end)
	bar.keep = P:FlatButton(bar, "Undo move")
	bar.keep:SetPoint("RIGHT", bar.nextB, "LEFT", -6, 0)
	bar.keep:SetScript("OnClick", function()
		local piece = list[at]
		if piece.keep then piece.keep(); P:PlaceStep(at + 1) return end
		if frame and before then SetPoints(frame, before); SaveAt(piece, frame) end
	end)
	bar.back = P:FlatButton(bar, "<  Back")
	bar.back:SetPoint("BOTTOMLEFT", 12, 10)
	bar.back:SetScript("OnClick", function() P:PlaceStep(at - 1) end)

	box = CreateFrame("Frame", "PathwayPlaceBox", UIParent, "BackdropTemplate")
	box:SetFrameStrata("FULLSCREEN")
	box:SetBackdrop({ edgeFile = P.WHITE, edgeSize = 2 })
	box.fill = box:CreateTexture(nil, "BACKGROUND"); box.fill:SetAllPoints(); box.fill:SetColorTexture(A[1], A[2], A[3], 0.10)
	box.label = box:CreateFontString(nil, "OVERLAY"); box.label:SetFontObject(P.fonts.title)
	box.label:SetPoint("BOTTOM", box, "TOP", 0, 6)
	box:EnableMouse(true); box:RegisterForDrag("LeftButton"); box:EnableMouseWheel(true)
	box:SetScript("OnDragStart", function()
		if frame and not (InCombatLockdown() and frame:IsProtected()) then
			frame:SetMovable(true); frame:StartMoving(); box.moving = true
		end
	end)
	box:SetScript("OnDragStop", function()
		if not (frame and box.moving) then return end
		box.moving = nil
		frame:StopMovingOrSizing()
		local piece = list[at]
		SaveAt(piece, frame)
		if piece.moved then piece.moved() end
		P:PlaceBarAside()
	end)
	box:SetScript("OnMouseWheel", function(_, delta)
		if frame and IsControlKeyDown() then P:NudgeScale(frame, delta) end
	end)
	-- follow the window as it moves and resizes
	box:SetScript("OnUpdate", function(self)
		if not frame then return end
		local l, b, w, h = frame:GetRect()
		if not l then return end
		local k = (frame:GetEffectiveScale() or 1) / (UIParent:GetEffectiveScale() or 1)
		self:ClearAllPoints()
		self:SetPoint("BOTTOMLEFT", UIParent, "BOTTOMLEFT", l * k - 4, b * k - 4)
		self:SetSize(w * k + 8, h * k + 8)
	end)
	P:OnPaint(function()
		box:SetBackdropBorderColor(A[1], A[2], A[3], 1)
		box.fill:SetColorTexture(A[1], A[2], A[3], 0.10)
	end)
	box:SetBackdropBorderColor(A[1], A[2], A[3], 1)
	bar:Hide(); box:Hide()
	P:ApplySizes()
end

-- the bar stays clear of the window you're placing: the middle of the screen,
-- or above or below it when the window is there (unless you moved the bar)
local function Rect(f)
	local l, b, w, h = f:GetRect()
	l, b, w, h = tonumber(l), tonumber(b), tonumber(w), tonumber(h)
	if not (l and b and w and h) then return end
	local k = (tonumber(f:GetEffectiveScale()) or 1) / (tonumber(UIParent:GetEffectiveScale()) or 1)
	return l * k, b * k, (l + w) * k, (b + h) * k
end
local function Overlap(a, b)
	return a and b and a[1] and b[1] and a[1] < b[3] and b[1] < a[3] and a[2] < b[4] and b[2] < a[4]
end
function P:PlaceBarAside()
	if not (bar and frame) or bar.moved then return end
	local fr = { Rect(frame) }
	local H = tonumber(UIParent:GetHeight()) or 768
	for _, y in ipairs({ 140, H * 0.3, -H * 0.18, H * 0.38 - 64 }) do
		bar:ClearAllPoints(); bar:SetPoint("CENTER", UIParent, "CENTER", 0, y)
		if not Overlap(fr, { Rect(bar) }) then return end
	end
end

local function Release(piece)
	if piece and piece.done then piece.done() end
end

local function Finish(cancelled)
	if list and list[at] then Release(list[at]) end
	P.placing = nil
	frame, before, list = nil, nil, nil
	if bar then bar:Hide(); box:Hide() end
	S().lockWindows = true
	P:Send("SETTINGS_CHANGED")
	if P.RefreshArrow then P:RefreshArrow() end
	if P.UpdateGuide then P:UpdateGuide() end
	if P.UpdateQuestBar then P:UpdateQuestBar() end
	if not cancelled then P:Toast("Windows locked in place. Shift-drag moves one; Settings > Home places them again.") end
end

function P:PlaceStep(i)
	if not list then return end
	if list[at] then Release(list[at]) end
	if i < 1 then i = 1 end
	if i > #list then Finish() return end
	at = i
	local piece = list[i]
	frame = piece.frame()
	if not frame then P:PlaceStep(i + 1) return end
	piece.show(frame)
	before = Points(frame)
	bar.title:SetText(piece.label)
	bar.step:SetText(P.DIM .. ("Window %d of %d"):format(i, #list) .. "|r")
	bar.text:SetText(piece.text)
	bar.how:SetText(P.DIM .. "It starts in a good spot: keep it, or |cffffffffdrag|r it anywhere. |cffffffffCtrl + mouse wheel|r over it makes it bigger or smaller."
		.. (i == #list and "\nAfter this they lock in place: |cffffffffShift-drag|r moves one any time." or "") .. "|r")
	bar:SetHeight(64 + bar.text:GetStringHeight() + bar.how:GetStringHeight() + 34)
	box.label:SetText("|c" .. P.ACCENT_HEX .. piece.label .. "|r  " .. P.DIM .. "drag me|r")
	bar.back:SetShown(i > 1)
	bar.keep:SetLabel(piece.keepLabel or "Undo move")
	bar.nextB:SetLabel(i == #list and "Done" or "Next  >")
	box:Show()
	P:PlaceBarAside()
end

-- keys: only these pieces (by key); fromSetup: the last step of setup
function P:PlaceWindows(keys, fromSetup)
	if InCombatLockdown() then P:Toast("After this fight: windows can't be placed in combat") return end
	if not bar then Build() end
	list = {}
	local only
	if keys then only = {}; for _, k in ipairs(keys) do only[k] = true end end
	for _, piece in ipairs(PIECES) do
		if (not only or only[piece.key]) and piece.on() then list[#list + 1] = piece end
	end
	if #list == 0 then
		list = nil
		if fromSetup then S().lockWindows = true end
		return
	end
	P.placing = true
	if P.HideSettings then P:HideSettings() end
	if _G.PathwayTip then _G.PathwayTip:Hide() end
	bar.moved = nil
	bar:Show()
	at = 0
	P:PlaceStep(1)
end

-- a fight stops it: everything stays where it got to
P:On("PLAYER_REGEN_DISABLED", function() if P.placing then Finish(true) end end)
end part() end
-- ==================== FPS.lua
do local __addon, __ns = ... local function part()
-- Copyright (C) 2026 SoFinSicc. Part of Pathway (curseforge.com/wow/addons/pathway): free software under the GPLv3 or later, with additional terms that require keeping this credit. See LICENSE.md.
--[[ Pathway — Performance meter
     A small readout of your frame rate and latency, green when all is well.
     Hover it: what's using the most (each add-on's memory, and its time per
     frame when the game shares that), with a short note on what would help.
     Click it: a few one-click ways to make the game run smoother: lighter
     effects, a calmer background frame rate, freeing add-on memory. Every
     change is written down, so "Put it back" restores exactly what you had. ]]

local ADDON, P = __addon, __ns
local A = P.ACCENT
local floor, max, min = math.floor, math.max, math.min

local function S() return P.db.settings end
local GetNumAddOns = (C_AddOns and C_AddOns.GetNumAddOns) or GetNumAddOns
local GetAddOnInfo = (C_AddOns and C_AddOns.GetAddOnInfo) or GetAddOnInfo
local IsAddOnLoaded = (C_AddOns and C_AddOns.IsAddOnLoaded) or IsAddOnLoaded

local f, panel

---------------------------------------------------------------------------
-- Reading
---------------------------------------------------------------------------
local function Latency()
	local _, _, home, world = GetNetStats()
	return home or 0, world or 0
end

local function Color(v, good, ok)          -- higher is better
	if v >= good then return "|cff5ad18a" elseif v >= ok then return "|cffffd25a" end
	return "|cffff6a5a"
end
local function ColorLow(v, good, ok)       -- lower is better
	if v <= good then return "|cff5ad18a" elseif v <= ok then return "|cffffd25a" end
	return "|cffff6a5a"
end

local function MB(kb) return kb >= 1024 and ("%.1f MB"):format(kb / 1024) or ("%d KB"):format(kb) end

-- each loaded add-on: memory (KB) and, when the game shares it, recent time per frame (ms)
-- Reading every add-on's memory is one of the slowest things an add-on can
-- ask the game for, so it's read at most every few seconds, and only while
-- you're looking at the tooltip.
local useCache, useAt = nil, -100
local function AddOnUse()
	local now = GetTime()
	if useCache and now - useAt < 5 then return useCache end
	useAt = now
	local out = {}
	useCache = out
	if UpdateAddOnMemoryUsage then pcall(UpdateAddOnMemoryUsage) end
	local prof = C_AddOnProfiler and C_AddOnProfiler.GetAddOnMetric and Enum and Enum.AddOnProfilerMetric
	for i = 1, (GetNumAddOns and GetNumAddOns() or 0) do
		local name, title = GetAddOnInfo(i)
		if name and IsAddOnLoaded(i) then
			local mem = GetAddOnMemoryUsage and GetAddOnMemoryUsage(i) or 0
			local ms
			if prof and prof.RecentAverageTime then
				local ok, v = pcall(C_AddOnProfiler.GetAddOnMetric, name, prof.RecentAverageTime)
				if ok and type(v) == "number" then ms = v end
			end
			out[#out + 1] = { name = (title and title ~= "" and title:gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", "")) or name, mem = mem, ms = ms }
		end
	end
	return out
end

---------------------------------------------------------------------------
-- The readout
---------------------------------------------------------------------------
local function Paint()
	if not (f and f:IsShown()) then return end
	local fps = GetFramerate() or 0
	local home, world = Latency()
	local ms = max(home, world)
	local parts = { Color(fps, 50, 28) .. floor(fps + 0.5) .. "|r" .. P.DIM .. " fps|r" }
	if S().fpsLatency ~= false then parts[#parts + 1] = ColorLow(ms, 90, 200) .. ms .. "|r" .. P.DIM .. " ms|r" end
	if S().fpsMemory then parts[#parts + 1] = P.DIM .. MB(collectgarbage("count")) .. "|r" end
	f.text:SetText(table.concat(parts, P.DIM .. "  ·  |r"))
	f:SetWidth(f.text:GetStringWidth() + 20)
end

local function Tooltip(self)
	GameTooltip:SetOwner(self, "ANCHOR_BOTTOMLEFT")
	local fps = GetFramerate() or 0
	local home, world = Latency()
	GameTooltip:AddLine("Performance", 1, 1, 1)
	GameTooltip:AddDoubleLine("Frame rate", Color(fps, 50, 28) .. floor(fps + 0.5) .. " fps|r", 0.8, 0.82, 0.86)
	GameTooltip:AddDoubleLine("Latency (home / world)", ColorLow(home, 90, 200) .. home .. "|r / " .. ColorLow(world, 90, 200) .. world .. " ms|r", 0.8, 0.82, 0.86)
	local list = AddOnUse()
	local total = 0
	for _, a in ipairs(list) do total = total + a.mem end
	GameTooltip:AddDoubleLine("Add-on memory", MB(total), 0.8, 0.82, 0.86, 1, 1, 1)
	-- the busiest by time per frame, when the game shares it; else the largest
	local byTime = false
	for _, a in ipairs(list) do if a.ms and a.ms > 0 then byTime = true break end end
	table.sort(list, function(a, b)
		if byTime then return (a.ms or 0) > (b.ms or 0) end
		return a.mem > b.mem
	end)
	GameTooltip:AddLine(" ")
	GameTooltip:AddLine(byTime and "Using the most time each frame" or "Using the most memory", 1, 0.82, 0.3)
	for i = 1, min(6, #list) do
		local a = list[i]
		local right = byTime and ("%.2f ms"):format(a.ms or 0) .. P.DIM .. "  " .. MB(a.mem) .. "|r" or MB(a.mem)
		GameTooltip:AddDoubleLine(a.name, right, 0.9, 0.92, 0.95, 1, 1, 1)
	end
	-- Pathway, part by part: what each part costs (milliseconds of work a second)
	local Perf = P.Perf
	if Perf and Perf.on then
		GameTooltip:AddLine(" ")
		GameTooltip:AddLine("Pathway, part by part", 1, 0.82, 0.3)
		local parts = {}
		for _, part in ipairs(Perf.PARTS) do
			local on = not part.key or P.GetSetting(part.key) ~= false
			parts[#parts + 1] = { part = part, ms = Perf.rate[part.name] or 0, on = on }
		end
		table.sort(parts, function(a, b) if a.on ~= b.on then return a.on end return a.ms > b.ms end)
		local shown = 0
		for _, it in ipairs(parts) do
			if shown >= 8 then break end
			if it.on and (it.ms >= 0.01 or shown < 4) then
				shown = shown + 1
				local c = it.ms < 0.5 and "|cff5ad18a" or it.ms < 2 and "|cffffd25a" or "|cffff6a5a"
				GameTooltip:AddDoubleLine(it.part.name, c .. ("%.2f ms/s"):format(it.ms) .. "|r", 0.9, 0.92, 0.95, 1, 1, 1)
			end
		end
		-- the handlers behind those numbers (a message's cost shows under whoever sent it too)
		local top = Perf.Top and Perf.Top(4) or {}
		if top[1] and top[1][2] >= 1 then
			GameTooltip:AddLine(" ")
			GameTooltip:AddLine("Busiest right now", 1, 0.82, 0.3)
			for _, it in ipairs(top) do
				local c = it[2] < 0.5 and "|cff5ad18a" or it[2] < 2 and "|cffffd25a" or "|cffff6a5a"
				GameTooltip:AddDoubleLine(it[1], c .. ("%.2f ms/s"):format(it[2]) .. "|r", 0.75, 0.78, 0.82, 1, 1, 1)
			end
		end
		GameTooltip:AddLine("Click to turn any part off.  /pw perf lists the busiest in chat.", 0.55, 0.58, 0.62, true)
	end
	-- what would help
	local tips = {}
	if fps < 30 then tips[#tips + 1] = "Low frame rate: click for lighter effects." end
	if max(home, world) > 200 then tips[#tips + 1] = "High latency: that's the connection, not your PC (a wired connection helps)." end
	if list[1] and not byTime and list[1].mem > 100 * 1024 then tips[#tips + 1] = list[1].name .. " holds a lot of memory; a /reload frees it." end
	if #tips > 0 then
		GameTooltip:AddLine(" ")
		for _, t in ipairs(tips) do GameTooltip:AddLine(t, 0.65, 0.68, 0.72, true) end
	end
	GameTooltip:AddLine(" ")
	GameTooltip:AddLine("Click for ways to run smoother.  Shift-drag to move, Ctrl-scroll to size.", 0.55, 0.58, 0.62, true)
	GameTooltip:Show()
end

local function Build()
	f = CreateFrame("Button", "PathwayFPS", UIParent, "BackdropTemplate")
	P.Flat(f, nil, nil, true)
	f:SetSize(110, 22)
	f:SetFrameStrata("LOW")
	f:SetClampedToScreen(true)
	f:SetMovable(true); f:EnableMouse(true); f:RegisterForDrag("LeftButton")
	f:SetScript("OnDragStart", function(self) if P:CanDrag() then self:StartMoving() end end)
	f:SetScript("OnDragStop", function(self)
		self:StopMovingOrSizing()
		local p, _, rp, x, y = self:GetPoint()
		P.db.pos.PathwayFPS = { p, rp, x, y }
	end)
	P:PlaceAt(f)
	f.text = f:CreateFontString(nil, "OVERLAY"); f.text:SetFontObject(P.fonts.button); f.text:SetPoint("CENTER")
	f:SetScript("OnEnter", Tooltip)
	f:SetScript("OnLeave", GameTooltip_Hide)
	f:SetScript("OnClick", function() P:ToggleSpeedUp() end)
	local t, ps = 0, 0
	f:SetScript("OnUpdate", function(_, dt)
		t = t + dt
		if t < 1 then return end
		t = 0
		ps = ps + 1
		if ps >= 3 and P.Perf then ps = 0; P.Perf.Sample() end
		Paint()
		if GameTooltip:IsOwned(f) then Tooltip(f) end
	end)
	P.Perf.Hook(f, "Performance meter", "OnUpdate")
	P:ApplySizes()
end

function P:RefreshFPS()
	if S().fps then
		if not f then Build() end
		f:Show(); Paint()
		if P.Perf then P.Perf.Start(true) end
	else
		if P.Perf then P.Perf.Start(false) end
		if f then
			f:Hide()
			if panel then panel:Hide() end
		end
	end
end
P:Listen("READY", function() P:RefreshFPS() end)
P:Listen("SETTINGS_CHANGED", function() P:RefreshFPS() end)

---------------------------------------------------------------------------
-- Run smoother: one click each, and everything can be put back
---------------------------------------------------------------------------
local function CV(name)
	local get = C_CVar and C_CVar.GetCVar or GetCVar
	local ok, v = pcall(get, name)
	return ok and v or nil
end
local function SetCV(name, value)
	if InCombatLockdown() then return false end
	local set = C_CVar and C_CVar.SetCVar or SetCVar
	return pcall(set, name, tostring(value))
end

-- each: the setting, the value it goes to (never above what you have now)
local LIGHTER = {
	{ "graphicsShadowQuality", 1 }, { "graphicsParticleDensity", 2 }, { "graphicsSpellDensity", 1 },
	{ "graphicsSSAO", 0 }, { "graphicsSunshafts", 0 }, { "graphicsDepthEffects", 0 },
	{ "graphicsGroundClutter", 3 }, { "graphicsViewDistance", 5 }, { "graphicsEnvironmentDetail", 4 },
	{ "graphicsComputeEffects", 0 }, { "graphicsLiquidDetail", 1 },
}

local function Remember(name)
	P.db.perfWas = P.db.perfWas or {}
	if P.db.perfWas[name] == nil then
		local v = CV(name)
		if v ~= nil then P.db.perfWas[name] = v end
	end
end

local ACTIONS = {
	{ "Lighter effects", "Shadows, spell and particle effects, grass and view distance turned down. The biggest gain on most PCs.",
		function()
			local n = 0
			for _, c in ipairs(LIGHTER) do
				local cur = tonumber(CV(c[1]) or "")
				if cur and cur > c[2] then Remember(c[1]); if SetCV(c[1], c[2]) then n = n + 1 end end
			end
			return n > 0 and ("Turned down %d effect setting%s"):format(n, n == 1 and "" or "s") or "Your effects are already light"
		end },
	{ "Calm in the background", "When the game isn't the window in front, it draws 20 frames a second instead of all it can. Your PC stays cool and quick.",
		function()
			Remember("maxFPSBk"); Remember("useMaxFPSBk")
			SetCV("useMaxFPSBk", 1); SetCV("maxFPSBk", 20)
			return "The game slows down in the background"
		end },
	{ "Free add-on memory", "Tidies what every add-on has let go of. Most useful after a long session.",
		function()
			local before = collectgarbage("count")
			collectgarbage("collect")
			return ("Freed %s"):format(MB(max(0, before - collectgarbage("count"))))
		end },
	{ "Put it back", "Every setting above back to exactly what you had.",
		function()
			local n = 0
			for name, v in pairs(P.db.perfWas or {}) do if SetCV(name, v) then n = n + 1 end end
			P.db.perfWas = nil
			return n > 0 and "Your settings are back as they were" or "Nothing to put back"
		end },
}

P.PerfActions = ACTIONS

function P:ToggleSpeedUp()
	if panel and panel:IsShown() then panel:Hide() return end
	if not panel then
		panel = CreateFrame("Frame", "PathwayFPSPanel", UIParent, "BackdropTemplate")
		P.Flat(panel, nil, nil, true)
		panel:SetSize(300, 10)
		panel:SetFrameStrata("DIALOG")
		panel:SetClampedToScreen(true)
		local title = panel:CreateFontString(nil, "OVERLAY"); title:SetFontObject(P.fonts.title)
		title:SetPoint("TOPLEFT", 14, -12); title:SetText("Run smoother")
		local close = P:CloseButton(panel, function() panel:Hide() end); close:SetPoint("TOPRIGHT", -6, -6)
		local y = -38
		for _, a in ipairs(ACTIONS) do
			local b = P:FlatButton(panel, a[1], a[1] ~= "Put it back")
			b.minW = 272; b:SetLabel(a[1])
			b:SetPoint("TOPLEFT", 14, y)
			b:SetScript("OnClick", function()
				if InCombatLockdown() then P:Toast("After this fight") return end
				P:Toast(a[3]())
			end)
			local d = panel:CreateFontString(nil, "OVERLAY"); d:SetFontObject(P.fonts.head)
			d:SetPoint("TOPLEFT", b, "BOTTOMLEFT", 2, -4); d:SetPoint("RIGHT", -14, 0)
			d:SetJustifyH("LEFT"); d:SetSpacing(2); d:SetText(P.DIM .. a[2] .. "|r")
			y = y - 28 - d:GetStringHeight() - 14
		end
		-- every part of Pathway, what it costs, and a switch
		local head = panel:CreateFontString(nil, "OVERLAY"); head:SetFontObject(P.fonts.title)
		head:SetPoint("TOPLEFT", 14, y - 4); head:SetText("Pathway, part by part")
		local sub = panel:CreateFontString(nil, "OVERLAY"); sub:SetFontObject(P.fonts.head)
		sub:SetPoint("TOPLEFT", head, "BOTTOMLEFT", 0, -3); sub:SetText(P.DIM .. "Work each second, measured while this meter is on.|r")
		y = y - 44
		panel.parts = {}
		for _, part in ipairs(P.Perf and P.Perf.PARTS or {}) do
			if part.key then
				local row = CreateFrame("Frame", nil, panel)
				row:SetHeight(20); row:SetPoint("TOPLEFT", 14, y); row:SetPoint("RIGHT", -14, 0)
				row.name = row:CreateFontString(nil, "OVERLAY"); row.name:SetFontObject(P.fonts.button); row.name:SetPoint("LEFT")
				row.ms = row:CreateFontString(nil, "OVERLAY"); row.ms:SetFontObject(P.fonts.head); row.ms:SetPoint("RIGHT", -58, 0)
				row.btn = P:FlatButton(row, "On", true); row.btn.minW = 50; row.btn:SetPoint("RIGHT")
				row.part = part
				row.btn:SetScript("OnClick", function()
					P.SetSetting(part.key, P.GetSetting(part.key) == false)
					if part.reload then StaticPopup_Show("PATHWAY_RELOAD") end
					panel:Fresh()
				end)
				panel.parts[#panel.parts + 1] = row
				y = y - 22
			end
		end
		function panel:Fresh()
			for _, row in ipairs(self.parts) do
				local on = P.GetSetting(row.part.key) ~= false
				local ms = P.Perf.rate[row.part.name] or 0
				row.name:SetText((on and "|cffd8dde3" or "|cff6b7480") .. row.part.name .. "|r")
				row.ms:SetText(on and (P.DIM .. ("%.2f ms/s"):format(ms) .. "|r") or (P.DIM .. "off|r"))
				row.btn:SetLabel(on and "On" or "Off")
				if row.btn.SetAccent then row.btn:SetAccent(on) end
			end
		end
		panel:SetScript("OnShow", function(self) self:Fresh() end)
		local tk = 0
		panel:SetScript("OnUpdate", function(self, dt) tk = tk + dt; if tk > 3 then tk = 0; self:Fresh() end end)
		panel:SetHeight(-y + 10)
		tinsert(UISpecialFrames, "PathwayFPSPanel")
		P:ApplySizes()
	end
	panel:ClearAllPoints()
	if f and f:IsShown() then
		local below = (tonumber(f:GetBottom()) or 0) > 300
		if below then panel:SetPoint("TOPRIGHT", f, "BOTTOMRIGHT", 0, -4) else panel:SetPoint("BOTTOMRIGHT", f, "TOPRIGHT", 0, 4) end
	else
		panel:SetPoint("CENTER")
	end
	panel:Show()
end
end part() end
-- ==================== MapLook.lua
do local __addon, __ns = ... local function part()
-- Copyright (C) 2026 SoFinSicc. Part of Pathway (curseforge.com/wow/addons/pathway): free software under the GPLv3 or later, with additional terms that require keeping this credit. See LICENSE.md.
--[[ Pathway — Your minimap's look
     The edge (thin, bold, glowing, neon, pulsing...), its color and thickness,
     the glow that shows which way you face (arc, wide, beam, comet, front and
     back), and your arrow's shape and color. A preview turns slowly so you see
     the facing glow move, and the real minimap changes as you click.
     Part of the first-time setup; /pw look opens it any time. ]]

local fromSetupFlow
local ADDON, P = __addon, __ns
local A = P.ACCENT
local cos, sin, pi, max, min = math.cos, math.sin, math.pi, math.max, math.min

local function E() return P.GoodMap and P.GoodMap.E end
-- straight to the minimap: read, and change-and-apply right now
local function G(k) local e = E(); return e and e.Get and e.Get(k) end
local function Set(k, v) local e = E(); if e and e.SetLive then e.SetLive(k, v) end end

local COLORS = { "ACCENT", "CLASS", "GOLD", "WHITE", "GREEN", "BLUE", "CYAN", "PURPLE", "PINK", "RED", "ORANGE" }
local COLOR_NAME = { ACCENT = "Pathway color", CLASS = "Class color", GOLD = "Gold", WHITE = "White", GREEN = "Green",
	BLUE = "Blue", CYAN = "Cyan", PURPLE = "Purple", PINK = "Pink", RED = "Red", ORANGE = "Orange" }

-- the edge: a line, and a glow just outside it
local EDGES = {
	{ "NONE", "Line only" }, { "SOFT", "Soft glow" }, { "NEON", "Neon" }, { "PULSE", "Pulse" }, { "BREATHE", "Breathe" },
	{ "AURA", "Aura" }, { "SHADOW", "Shadow" }, { "DOUBLE", "Double ring" }, { "RAINBOW", "Rainbow" }, { "FIRE", "Fire" },
}
local PATTERNS = { { "SOLID", "Solid" }, { "DASHED", "Dashed" }, { "DOTTED", "Dotted" }, { "OFF", "No line" } }
local GLOWS = { { "OFF", "Off" }, { "ARC", "Arc" }, { "WIDE", "Wide" }, { "BEAM", "Beam" }, { "COMET", "Comet" },
	{ "TWIN", "Front & back" }, { "SPOT", "Spot" }, { "FAN", "Fan" } }
local ARROWS = { { "CLASSIC", "Classic" }, { "DART", "Dart" }, { "CHEVRON", "Chevron" }, { "TRIANGLE", "Triangle" },
	{ "NEEDLE", "Needle" }, { "BEACON", "Beacon" }, { "BLIZZARD", "Blizzard" } }

local function Hex(r, g, b) return ("ff%02x%02x%02x"):format(r * 255, g * 255, b * 255) end

-- the edge's color, read back from how the border is set
local function EdgeColor()
	local b = G("border")
	if b == "ACCENT" then return "ACCENT" end
	if b == "CLASS" then return "CLASS" end
	local hex = (G("borderColor") or ""):lower()
	for _, k in ipairs(COLORS) do
		local r, g, bl = E().PaletteColor(k)
		if Hex(r, g, bl) == hex then return k end
	end
end
local function SetEdgeColor(k)
	local b = G("border")
	if b ~= "NONE" then
		if k == "ACCENT" or k == "CLASS" then Set("border", k)
		else
			local r, g, bl = E().PaletteColor(k)
			Set("border", "THIN"); Set("borderColor", Hex(r, g, bl))
		end
	end
	Set("ringColor", k)
end

---------------------------------------------------------------------------
-- The preview: your zone's map in a circle, the edge, its glow, the arrow and
-- the facing glow, turning slowly
---------------------------------------------------------------------------
local win
local function MapArt(holder, map)
	holder.tiles = holder.tiles or {}
	for _, t in ipairs(holder.tiles) do t:Hide() end
	if not (map and C_Map.GetMapArtLayers and C_Map.GetMapArtLayerTextures) then return end
	local layers = C_Map.GetMapArtLayers(map)
	local L = layers and layers[1]
	local tex = L and C_Map.GetMapArtLayerTextures(map, 1)
	if not (L and tex and #tex > 0) then return end
	local w = holder:GetWidth()
	-- show the part of the map around you, zoomed in a little
	local px, py = 0.5, 0.5
	local pos = C_Map.GetPlayerMapPosition and C_Map.GetPlayerMapPosition(map, "player")
	if pos then px, py = pos.x or 0.5, pos.y or 0.5; if pos.GetXY then px, py = pos:GetXY() end end
	local k = w / (L.layerWidth * 0.45)
	local cols = math.ceil(L.layerWidth / L.tileWidth)
	local ox = w / 2 - px * L.layerWidth * k
	local oy = w / 2 - py * L.layerHeight * k
	for i, file in ipairs(tex) do
		local t = holder.tiles[i]
		if not t then
			t = holder:CreateTexture(nil, "ARTWORK")
			t:AddMaskTexture(holder.mask)
			holder.tiles[i] = t
		end
		local c, r = (i - 1) % cols, math.floor((i - 1) / cols)
		t:SetTexture(file)
		t:SetSize(L.tileWidth * k, L.tileHeight * k)
		t:ClearAllPoints()
		t:SetPoint("TOPLEFT", holder, "TOPLEFT", ox + c * L.tileWidth * k, -(oy + r * L.tileHeight * k))
		t:Show()
	end
end

local function BuildPreview(parent, size)
	local f = CreateFrame("Frame", nil, parent)
	f:SetSize(size, size)
	f.map = CreateFrame("Frame", nil, f); f.map:SetAllPoints()
	f.map.mask = f.map:CreateMaskTexture()
	f.map.mask:SetTexture("Interface\\CharacterFrame\\TempPortraitAlphaMask", "CLAMPTOBLACKADDITIVE", "CLAMPTOBLACKADDITIVE")
	f.map.mask:SetAllPoints()
	f.bg = f.map:CreateTexture(nil, "BACKGROUND"); f.bg:SetAllPoints(); f.bg:SetColorTexture(0.12, 0.13, 0.11, 1)
	f.bg:AddMaskTexture(f.map.mask)
	-- the same glow and ring the minimap draws, so what you see here is what you get
	f.halo = E().NewHalo(f, f); f.halo:SetFrameLevel(max(0, f:GetFrameLevel() - 1))
	f.ring = {}
	-- the facing glow, drawn the same way the minimap draws it
	local g = CreateFrame("Frame", nil, f); g:SetPoint("CENTER"); g:SetSize(1, 1)
	g.back = {}
	for i = 1, (E().GLOW_N or 16) do
		g[i] = g:CreateLine(nil, "OVERLAY"); g[i]:SetBlendMode("ADD")
		g.back[i] = g:CreateLine(nil, "OVERLAY"); g.back[i]:SetBlendMode("ADD")
	end
	g.r = size / 2
	f.glow = g
	f.arrow = f:CreateTexture(nil, "OVERLAY", nil, 7); f.arrow:SetPoint("CENTER"); f.arrow:SetSize(28, 28)
	f.angle = 0
	f:SetScript("OnUpdate", function(self, dt)
		self.angle = (self.angle + dt * 0.6) % (2 * pi)
		if self.glow:IsShown() then E().DrawGlowOn(self.glow, self.angle + pi / 2) end
		self.arrow:SetRotation(self.angle)
	end)
	return f
end

local function Paint(f)
	local e = E()
	local size = f:GetWidth()
	local d = size
	-- edge: the same drawing as the minimap's
	local border, bs = G("border"), G("borderSize") or 2
	local r, g, bl = 0, 0, 0
	if border == "ACCENT" then r, g, bl = A[1], A[2], A[3]
	elseif border == "CLASS" then r, g, bl = e.PaletteColor("CLASS")
	elseif border == "BLIZZARD" then r, g, bl, bs = 0.72, 0.6, 0.36, 2
	else
		local c = CreateColorFromHexString and CreateColorFromHexString(G("borderColor") or "ff000000")
		if c then r, g, bl = c:GetRGB() end
	end
	if border == "NONE" then for _, l in ipairs(f.ring) do l:Hide() end
	else e.DrawRingOn(f, f.ring, 72, d / 2 + bs / 2, bs, r, g, bl, 1, G("edgeStyle")) end
	-- the glow around it
	e.StyleHalo(f.halo, { style = G("ringGlow"), d = d, edge = border ~= "NONE" and bs or 0, color = G("ringColor"), pattern = G("edgeStyle") })
	-- facing glow
	local on = G("compassGlow")
	f.glow:SetShown(on and true or false)
	if on then
		f.glow.r = d / 2
		e.StyleGlow(f.glow, { glowStyle = G("glowStyle"), glowColor = G("glowColor"), glowCustom = G("glowCustom"),
			glowAlpha = G("glowAlpha"), glowWidth = G("glowWidth"), borderSize = bs })
	end
	-- arrow
	local style, color = G("arrowStyle"), G("arrowColor")
	f.arrow:SetTexture(e.ArrowTexture(style == "BLIZZARD" and "CLASSIC" or style))
	if style == "BLIZZARD" or (style == "CLASSIC" and color == "GOLD") then
		f.arrow:SetDesaturated(false); f.arrow:SetVertexColor(1, 1, 1)
	else
		f.arrow:SetDesaturated(style == "CLASSIC")
		f.arrow:SetVertexColor(e.PaletteColor(color, G("arrowCustom")))
	end
	local ps = (G("playerSize") or 12) * 2
	f.arrow:SetSize(ps, ps)
end

---------------------------------------------------------------------------
-- The window
---------------------------------------------------------------------------
local function Label(parent, text, x, y)
	local fs = parent:CreateFontString(nil, "OVERLAY"); fs:SetFontObject(P.fonts.title)
	fs:SetPoint("TOPLEFT", x, y); fs:SetText(text)
	return fs
end

local function Buttons(parent, x, y, list, get, set, right)
	local row, bx, by = {}, x, y
	right = right or (parent:GetWidth() - 16)
	for _, o in ipairs(list) do
		local b = P:FlatButton(parent, o[2])
		b.minW = 56; b:SetLabel(o[2])
		if bx > x and bx + b:GetWidth() > right then bx, by = x, by - 26 end
		b:SetPoint("TOPLEFT", bx, by)
		b.value = o[1]
		b:SetScript("OnClick", function() set(o[1]); parent:Refresh() end)
		bx = bx + b:GetWidth() + 4
		row[#row + 1] = b
	end
	parent.refreshers[#parent.refreshers + 1] = function()
		local v = get()
		for _, b in ipairs(row) do
			local on = b.value == v
			b.edge = on and { A[1], A[2], A[3], 1 } or P.colors.EDGE
			b:SetBackdropBorderColor(unpack(b.edge))
			b.text:SetTextColor(on and 1 or 0.75, on and 1 or 0.78, on and 1 or 0.82)
		end
	end
	return by
end

local function Swatches(parent, x, y, get, set)
	local row = {}
	for i, k in ipairs(COLORS) do
		local b = CreateFrame("Button", nil, parent, "BackdropTemplate")
		b:SetSize(24, 18); b:SetPoint("TOPLEFT", x + (i - 1) * 28, y)
		local r, g, bl = E().PaletteColor(k)
		P.Flat(b, { r, g, bl, 1 }, P.colors.EDGE)
		b.key = k
		b:SetScript("OnEnter", function() GameTooltip:SetOwner(b, "ANCHOR_TOP"); GameTooltip:SetText(COLOR_NAME[k], 1, 1, 1); GameTooltip:Show() end)
		b:SetScript("OnLeave", GameTooltip_Hide)
		b:SetScript("OnClick", function() set(k); parent:Refresh() end)
		row[#row + 1] = b
	end
	parent.refreshers[#parent.refreshers + 1] = function()
		local v = get()
		for _, b in ipairs(row) do
			local r, g, bl = E().PaletteColor(b.key)
			b:SetBackdropColor(r, g, bl, 1)
			b:SetBackdropBorderColor(unpack(b.key == v and { 1, 1, 1, 1 } or P.colors.EDGE))
		end
	end
end

local function Slider(parent, x, y, w, lo, hi, step, get, set, fmt)
	local s = CreateFrame("Slider", nil, parent, "BackdropTemplate")
	s:SetOrientation("HORIZONTAL"); s:SetSize(w, 8); s:SetPoint("TOPLEFT", x, y)
	P.Flat(s, P.colors.PANEL)
	local th = s:CreateTexture(nil, "OVERLAY"); th:SetSize(10, 16); s:SetThumbTexture(th)
	s:SetMinMaxValues(lo, hi); s:SetValueStep(step); s:SetObeyStepOnDrag(true)
	local val = s:CreateFontString(nil, "OVERLAY"); val:SetFontObject(P.fonts.button); val:SetPoint("LEFT", s, "RIGHT", 10, 0)
	local busy
	s:SetScript("OnValueChanged", function(_, v)
		if busy then return end
		v = math.floor(v / step + 0.5) * step
		val:SetText(fmt:format(v))
		set(v)
		parent:Refresh()
	end)
	parent.refreshers[#parent.refreshers + 1] = function()
		th:SetColorTexture(A[1], A[2], A[3], 1)
		local v = get() or lo
		busy = true; s:SetValue(v); busy = false
		val:SetText(fmt:format(v))
	end
end

local function Build()
	win = CreateFrame("Frame", "PathwaySetupMap", UIParent, "BackdropTemplate")
	P:ApplySizes()
	P.Flat(win, nil, nil, true)
	win:SetSize(720, 600)
	win:SetPoint("CENTER", UIParent, "CENTER", -120, 40)
	win:SetFrameStrata("DIALOG")
	win:EnableMouse(true); win:SetMovable(true); win:RegisterForDrag("LeftButton")
	win:SetScript("OnDragStart", win.StartMoving); win:SetScript("OnDragStop", win.StopMovingOrSizing)
	win.refreshers = {}
	function win:Refresh()
		for _, fn in ipairs(self.refreshers) do fn() end
		Paint(self.preview)
	end
	tinsert(UISpecialFrames, "PathwaySetupMap")
	win:HookScript("OnHide", function() P:SetupClosed() end)

	local title = win:CreateFontString(nil, "OVERLAY"); title:SetFontObject(P.fonts.big)
	title:SetPoint("TOPLEFT", 18, -16); title:SetText("Your minimap")
	local sub = win:CreateFontString(nil, "OVERLAY"); sub:SetFontObject(P.fonts.head)
	sub:SetPoint("TOPLEFT", title, "BOTTOMLEFT", 0, -4)
	sub:SetText("Every click changes your real minimap right away (top right) and is saved. The preview turns so you can see the facing glow.")
	local close = P:CloseButton(win, function() win:Hide() end); close:SetPoint("TOPRIGHT", -6, -6)

	-- preview on the left
	local holder = CreateFrame("Frame", nil, win, "BackdropTemplate")
	P.Flat(holder, P.colors.PANEL)
	holder:SetSize(200, 220); holder:SetPoint("TOPLEFT", 16, -60)
	win.preview = BuildPreview(holder, 150)
	win.preview:SetPoint("CENTER", holder, "CENTER", 0, 8)
	local cap = holder:CreateFontString(nil, "OVERLAY"); cap:SetFontObject(P.fonts.head)
	cap:SetPoint("BOTTOM", 0, 8); cap:SetText("Preview: turning so you see the glow move")

	-- choices on the right; each section starts below the one before it
	local x = 232
	local y = -60
	Label(win, "Glow around the edge", x, y)
	y = Buttons(win, x, y - 20, EDGES, function() return G("ringGlow") end, function(v) Set("ringGlow", v) end)
	Label(win, "Edge line", x, y - 32)
	y = Buttons(win, x + 90, y - 30, PATTERNS, function() return G("border") == "NONE" and "OFF" or G("edgeStyle") end, function(v)
		if v == "OFF" then Set("border", "NONE") return end
		if G("border") == "NONE" or G("border") == "BLIZZARD" then Set("border", "ACCENT") end
		Set("edgeStyle", v)
	end)
	Label(win, "Thickness", x, y - 32)
	Slider(win, x + 90, y - 36, 170, 1, 12, 1, function() return G("borderSize") end, function(v) Set("borderSize", v) end, "%d px")
	Label(win, "Color", x, y - 58)
	Swatches(win, x + 90, y - 58, EdgeColor, SetEdgeColor)
	y = y - 92

	Label(win, "Glow that shows where you face", x, y)
	y = Buttons(win, x, y - 20, GLOWS, function() return G("compassGlow") and G("glowStyle") or "OFF" end, function(v)
		if v == "OFF" then Set("compassGlow", false) else Set("compassGlow", true); Set("glowStyle", v) end
	end)
	Label(win, "Color", x, y - 32)
	Swatches(win, x + 90, y - 32, function() return G("glowColor") end, function(k) Set("glowColor", k); Set("compassGlow", true) end)
	Label(win, "Brightness", x, y - 58)
	Slider(win, x + 90, y - 62, 120, 0.2, 1, 0.05, function() return G("glowAlpha") end, function(v) Set("glowAlpha", v) end, "%.2f")
	Label(win, "Width", x + 270, y - 58)
	Slider(win, x + 320, y - 62, 80, 0.5, 3, 0.25, function() return G("glowWidth") end, function(v) Set("glowWidth", v) end, "%.2fx")
	y = y - 92

	Label(win, "Your arrow", x, y)
	y = Buttons(win, x, y - 20, ARROWS, function() return G("arrowStyle") end, function(v) Set("arrowStyle", v) end)
	Label(win, "Color", x, y - 32)
	Swatches(win, x + 90, y - 32, function() return G("arrowColor") end, function(k) Set("arrowColor", k); if G("arrowStyle") == "BLIZZARD" then Set("arrowStyle", "CLASSIC") end end)
	Label(win, "Size", x, y - 58)
	Slider(win, x + 90, y - 62, 170, 6, 40, 1, function() return G("playerSize") end, function(v) Set("playerSize", v) end, "%d")
	local rightBottom = y - 80

	-- quick looks for the whole thing (left, under the preview)
	local qy = -296
	local looks = {
		{ "Clean", { border = "ACCENT", edgeStyle = "SOLID", borderSize = 2, ringGlow = "NONE", compassGlow = true, glowStyle = "ARC", arrowStyle = "CLASSIC", arrowColor = "ACCENT", glowColor = "ACCENT" } },
		{ "Glowing", { border = "ACCENT", edgeStyle = "SOLID", borderSize = 2, ringGlow = "SOFT", ringColor = "ACCENT", compassGlow = true, glowStyle = "WIDE", arrowStyle = "DART", arrowColor = "ACCENT", glowColor = "ACCENT" } },
		{ "Neon", { border = "ACCENT", edgeStyle = "SOLID", borderSize = 3, ringGlow = "NEON", ringColor = "ACCENT", compassGlow = true, glowStyle = "BEAM", arrowStyle = "CHEVRON", arrowColor = "WHITE", glowColor = "ACCENT" } },
		{ "Classic", { border = "BLIZZARD", edgeStyle = "SOLID", borderSize = 2, ringGlow = "NONE", compassGlow = false, glowStyle = "ARC", arrowStyle = "BLIZZARD", arrowColor = "GOLD", glowColor = "GOLD" } },
		{ "Rainbow", { border = "THIN", borderColor = "ff000000", edgeStyle = "SOLID", borderSize = 2, ringGlow = "RAINBOW", compassGlow = true, glowStyle = "COMET", arrowStyle = "DART", arrowColor = "WHITE", glowColor = "WHITE" } },
		{ "Shadow", { border = "THIN", borderColor = "ff1a1a1a", edgeStyle = "SOLID", borderSize = 3, ringGlow = "SHADOW", compassGlow = true, glowStyle = "SPOT", arrowStyle = "NEEDLE", arrowColor = "GOLD", glowColor = "GOLD" } },
		{ "Campfire", { border = "ACCENT", edgeStyle = "SOLID", borderSize = 2, ringGlow = "FIRE", compassGlow = true, glowStyle = "WIDE", arrowStyle = "DART", arrowColor = "GOLD", glowColor = "GOLD" } },
	}
	Label(win, "Or start from a look", 16, qy)
	for i, l in ipairs(looks) do
		local b = P:FlatButton(win, l[1])
		b.minW = 92; b:SetLabel(l[1])
		b:SetPoint("TOPLEFT", 16 + ((i - 1) % 2) * 100, qy - 22 - math.floor((i - 1) / 2) * 28)
		b:SetScript("OnClick", function() for k, v in pairs(l[2]) do Set(k, v) end; win:Refresh() end)
	end

	-- size and shape
	local sy = qy - 22 - 3 * 28 - 12
	Label(win, "Map size", 16, sy)
	local SIZES = { { 220, "Small" }, { 280, "Medium" }, { 340, "Large" }, { 420, "Huge" } }
	local function CurSize()
		local sz = G("shape") == "SQUARE" and G("width") or G("roundSize")
		local best, bd
		for _, o in ipairs(SIZES) do local d = math.abs((sz or 0) - o[1]); if not bd or d < bd then best, bd = o[1], d end end
		return best
	end
	local by = Buttons(win, 16, sy - 20, SIZES, CurSize, function(v)
		if G("shape") == "SQUARE" then Set("width", v); Set("height", math.floor(v * 0.9 / 10 + 0.5) * 10) else Set("roundSize", v) end
	end, 216)
	Label(win, "Shape", 16, by - 34)
	by = Buttons(win, 16, by - 54, { { "ROUND", "Round" }, { "SQUARE", "Square" } }, function() return G("shape") end, function(v) Set("shape", v) end, 216)
	local leftBottom = by - 36

	-- what shows on it, across the bottom
	local oy = math.min(leftBottom, rightBottom) - 6
	local toggles = { { "compass", "N E S W" }, { "playerCoords", "Coordinates" }, { "clock", "Clock" }, { "zoneText", "Zone name" } }
	Label(win, "On the map", 16, oy)
	local tb = {}
	for i, t in ipairs(toggles) do
		local b = P:FlatButton(win, t[2])
		b.minW = 96; b:SetLabel(t[2])
		b:SetPoint("TOPLEFT", 116 + (i - 1) * 104, oy + 3)
		b:SetScript("OnClick", function() Set(t[1], not G(t[1])); win:Refresh() end)
		tb[#tb + 1] = { b, t[1] }
	end
	win.refreshers[#win.refreshers + 1] = function()
		for _, x in ipairs(tb) do
			local on = G(x[2]) and true or false
			x[1].edge = on and { A[1], A[2], A[3], 1 } or P.colors.EDGE
			x[1]:SetBackdropBorderColor(unpack(x[1].edge))
			x[1].text:SetTextColor(on and 1 or 0.55, on and 1 or 0.58, on and 1 or 0.62)
		end
	end
	win:SetHeight(-oy + 70)

	local back = P:FlatButton(win, "<  Back")
	back:SetPoint("BOTTOMLEFT", 16, 14)
	back:SetScript("OnClick", function() win:Hide(); P:SetupBack("map") end)
	local done = P:FlatButton(win, "Done", true)
	done.minW = 120; done:SetLabel("Done")
	done:SetPoint("BOTTOMRIGHT", -16, 14)
	done:SetScript("OnClick", function()
		win:Hide()
		if fromSetupFlow then P:SetupNext("map") else P:Toast("Saved. /pw look changes your minimap any time") end
	end)
	win.done, win.back = done, back
end

function P:ShowMapLook(fromSettings)
	if not (P.GoodMap and P.GoodMap.ready and E()) then P:Toast("The minimap is switched off") return end
	if (P.GoodMap.API or 0) < 2 then
		print("|cff35d07fPath|rway: the minimap's files are older than the rest of Pathway. Quit the game fully and start it again.")
		return
	end
	if not win then Build() end
	MapArt(win.preview.map, P.GoodMap.S and P.GoodMap.S.map and P.GoodMap.S.map:GetMapID() or P:PlayerZone())
	win.back:SetShown(not fromSettings)
	fromSetupFlow = not fromSettings
	if not win.stepText then
		win.stepText = win:CreateFontString(nil, "OVERLAY"); win.stepText:SetFontObject(P.fonts.head)
		win.stepText:SetPoint("TOPRIGHT", -34, -14)
	end
	win.stepText:SetText(fromSetupFlow and (P.DIM .. P:SetupStepLabel("map") .. "|r") or "")
	if win.done and win.done.SetLabel then win.done:SetLabel(fromSetupFlow and "Next  >" or "Done") end
	win:Refresh()
	win:Show()
end

-- the look follows Pathway's color
P:OnPaint(function() if win and win:IsShown() then win:Refresh() end end)
end part() end
