do local __addon, __ns = ... local function part()
-- Copyright (C) 2026 SoFinSicc. Part of Pathway (curseforge.com/wow/addons/pathway): free software under the GPLv3 or later, with additional terms that require keeping this credit. See LICENSE.md.
--[[ Pathway — Talent suggestions
     When you have a point to spend, Pathway tells you where it goes and lights
     up that talent in your talent window. The builds follow the leveling builds
     the big guide sites agree on: one tree first for its key talent, then the
     next. Pathway only points: you click the talent yourself. ]]

local ADDON, P = __addon, __ns

local function S() return P.db.settings end

-- class -> the order points go in: "Talent name:ranks", ranks counted from zero
local BUILDS = {
	WARRIOR = { name = "Arms, then Fury",
		"Improved Heroic Strike:3", "Deflection:2", "Tactical Mastery:3", "Improved Charge:2", "Anger Management:1",
		"Deep Wounds:3", "Tactical Mastery:5", "Two-Handed Weapon Specialization:5", "Sweeping Strikes:1",
		"Sword Specialization:5", "Impale:2", "Improved Overpower:1", "Mortal Strike:1",
		"Cruelty:5", "Unbridled Wrath:5", "Improved Battle Shout:5", "Enrage:5" },
	ROGUE = { name = "Combat, then Assassination",
		"Improved Sinister Strike:2", "Lightning Reflexes:3", "Precision:5", "Lightning Reflexes:5", "Improved Sprint:2",
		"Dual Wield Specialization:5", "Blade Flurry:1", "Sword Specialization:5", "Weapon Expertise:2", "Aggression:3",
		"Adrenaline Rush:1", "Malice:5", "Murder:2", "Ruthlessness:3", "Relentless Strikes:1", "Lethality:5",
		"Improved Slice and Dice:3", "Remorseless Attacks:1" },
	MAGE = { name = "Frost, then Arcane",
		"Improved Frostbolt:5", "Ice Shards:5", "Piercing Ice:3", "Improved Blizzard:3", "Cold Snap:1", "Frost Channeling:3",
		"Permafrost:3", "Ice Block:1", "Improved Cone of Cold:3", "Shatter:3", "Ice Barrier:1",
		"Arcane Subtlety:2", "Arcane Focus:3", "Arcane Concentration:5", "Improved Arcane Explosion:3", "Arcane Meditation:3",
		"Shatter:5", "Frostbite:3" },
	PRIEST = { name = "Shadow, then Discipline",
		"Wand Specialization:5", "Spirit Tap:5", "Improved Shadow Word: Pain:2", "Shadow Focus:3", "Improved Mind Blast:5",
		"Mind Flay:1", "Shadow Reach:3", "Shadow Weaving:5", "Vampiric Embrace:1", "Darkness:5", "Shadowform:1",
		"Improved Power Word: Shield:3", "Improved Power Word: Fortitude:2", "Meditation:3", "Inner Focus:1",
		"Mental Agility:5", "Unbreakable Will:2" },
	WARLOCK = { name = "Affliction, then Demonology",
		"Improved Corruption:5", "Improved Life Tap:2", "Improved Curse of Agony:3", "Suppression:2", "Amplify Curse:1",
		"Nightfall:2", "Grim Reach:2", "Fel Concentration:3", "Siphon Life:1", "Shadow Mastery:5", "Dark Pact:1",
		"Improved Imp:3", "Demonic Embrace:5", "Improved Voidwalker:3", "Fel Domination:1", "Fel Intellect:3",
		"Improved Healthstone:2" },
	HUNTER = { name = "Beast Mastery, then Marksmanship",
		"Improved Aspect of the Hawk:5", "Thick Hide:3", "Endurance Training:2", "Bestial Swiftness:1", "Unleashed Fury:5",
		"Ferocity:5", "Intimidation:1", "Bestial Discipline:2", "Spirit Bond:2", "Frenzy:5", "Bestial Wrath:1",
		"Efficiency:5", "Lethal Shots:5", "Aimed Shot:1", "Mortal Shots:5" },
	PALADIN = { name = "Retribution, then Holy",
		"Benediction:5", "Improved Judgement:2", "Improved Seal of the Crusader:3", "Conviction:5", "Seal of Command:1",
		"Vindication:3", "Pursuit of Justice:2", "Two-Handed Weapon Specialization:3", "Sanctity Aura:1",
		"Vengeance:5", "Repentance:1", "Divine Strength:5", "Improved Seal of Righteousness:5", "Divine Intellect:5",
		"Consecration:1" },
	DRUID = { name = "Feral, then Restoration",
		"Ferocity:5", "Thick Hide:3", "Feline Swiftness:2", "Sharpened Claws:3", "Predatory Strikes:3", "Blood Frenzy:2",
		"Primal Fury:2", "Improved Shred:2", "Savage Fury:2", "Faerie Fire (Feral):1", "Heart of the Wild:5",
		"Leader of the Pack:1", "Furor:5", "Natural Shapeshifter:3", "Omen of Clarity:1", "Feral Instinct:5",
		"Brutal Impact:2" },
	SHAMAN = { name = "Enhancement, then Elemental",
		"Ancestral Knowledge:5", "Thundering Strikes:5", "Two-Handed Axes and Maces:1", "Improved Ghost Wolf:2",
		"Flurry:5", "Elemental Weapons:3", "Parry:1", "Weapon Mastery:5", "Stormstrike:1", "Anticipation:3",
		"Convection:5", "Concussion:5", "Call of Flame:3", "Elemental Focus:1", "Call of Thunder:1" },
}
P.TalentBuilds = BUILDS

---------------------------------------------------------------------------
-- Reading your talents: Forever's talent window (a tree of nodes, PlayerSpellsFrame),
-- into name -> { rank, max, can (a point can go in now), icon, node }.
---------------------------------------------------------------------------
local function Traits()
	return C_Traits and C_Traits.GetNodeInfo and C_ClassTalents and C_ClassTalents.GetActiveConfigID
end
local function TalentsFrame() return _G.PlayerSpellsFrame and _G.PlayerSpellsFrame.TalentsFrame end

local function ConfigAndTree()
	local cfg = C_ClassTalents.GetActiveConfigID and C_ClassTalents.GetActiveConfigID()
	local tf = TalentsFrame()
	if tf and tf.configurationInfo and tf.configurationInfo.ID then cfg = tf.configurationInfo.ID end
	if not cfg then return end
	local tree = tf and tf.talentTreeID
	if not tree then
		local info = C_Traits.GetConfigInfo and C_Traits.GetConfigInfo(cfg)
		tree = info and info.treeIDs and info.treeIDs[1]
	end
	return cfg, tree
end

local function SpellName(id)
	if not id then return end
	if C_Spell and C_Spell.GetSpellName then return C_Spell.GetSpellName(id) end
	return GetSpellInfo and (GetSpellInfo(id))
end
local function SpellIcon(id)
	if not id then return end
	if C_Spell and C_Spell.GetSpellTexture then return C_Spell.GetSpellTexture(id) end
	return GetSpellTexture and GetSpellTexture(id)
end

local function ReadTraits()
	local list = {}
	local cfg, tree = ConfigAndTree()
	if not (cfg and tree and C_Traits.GetTreeNodes) then return list, 0 end
	for _, nodeID in ipairs(C_Traits.GetTreeNodes(tree) or {}) do
		local ok, info = pcall(C_Traits.GetNodeInfo, cfg, nodeID)
		if ok and info and info.ID and info.ID ~= 0 and info.isVisible ~= false then
			local entryID = info.activeEntry and info.activeEntry.entryID or (info.entryIDs and info.entryIDs[1])
			local e = entryID and C_Traits.GetEntryInfo(cfg, entryID)
			local d = e and e.definitionID and C_Traits.GetDefinitionInfo(e.definitionID)
			local spell = d and (d.overriddenSpellID or d.spellID)
			local name = (d and d.overrideName ~= "" and d.overrideName) or SpellName(spell)
			if name then
				list[name] = { node = nodeID, rank = info.currentRank or info.ranksPurchased or 0, max = info.maxRanks or 1,
					can = info.canPurchaseRank and true or false, icon = d and d.overrideIcon or SpellIcon(spell),
					x = info.posX, y = info.posY }
			end
		end
	end
	local n = 0
	if C_Traits.GetTreeCurrencyInfo then
		local ok, cur = pcall(C_Traits.GetTreeCurrencyInfo, cfg, tree, false)
		if ok and type(cur) == "table" then for _, c in ipairs(cur) do n = n + (c.quantity or 0) end end
	end
	return list, n
end

local function Read()
	if Traits() then return ReadTraits() end
	return {}, 0
end
local function Unspent() return select(2, Read()) end

-- the next few talents of your class's build you can put points in, in order
function P:NextTalents(count)
	local build = BUILDS[P.me and P.me.classFile or select(2, UnitClass("player"))]
	build = build or { name = "Leveling" }
	local list = Read()
	local out, planned = {}, {}
	for _, entry in ipairs(build) do
		local name, want = entry:match("^(.-):(%d+)$")
		local t = list[name]
		want = tonumber(want)
		if t then
			local have = (planned[name] or t.rank)
			if have < math.min(want, t.max) and (t.can or planned[name]) then
				planned[name] = have + 1
				out[#out + 1] = { name = name, t = t, rank = have + 1 }
				if #out >= (count or 1) then break end
			end
		end
	end
	-- this server's trees have talents of their own: when the build has nothing
	-- that fits, keep filling the part of the tree you've been spending in, top to bottom
	if #out < (count or 1) then
		local sx, sn = 0, 0
		for _, t in pairs(list) do if t.rank > 0 and t.x then sx, sn = sx + t.x * t.rank, sn + t.rank end end
		local cx = sn > 0 and sx / sn or nil
		local pool = {}
		for name, t in pairs(list) do
			if t.can and t.rank < t.max and not planned[name] then pool[#pool + 1] = { name = name, t = t } end
		end
		table.sort(pool, function(a, b)
			local ay, by = a.t.y or 0, b.t.y or 0
			if ay ~= by then return ay < by end
			if cx then return math.abs((a.t.x or 0) - cx) < math.abs((b.t.x or 0) - cx) end
			return a.name < b.name
		end)
		for _, c in ipairs(pool) do
			if #out >= (count or 1) then break end
			out[#out + 1] = { name = c.name, t = c.t, rank = c.t.rank + 1, fill = true }
		end
	end
	return out, build.name
end
function P:NextTalent()
	local list, buildName = self:NextTalents(1)
	local n = list[1]
	if n then return n.name, n.t, nil, buildName end
end

---------------------------------------------------------------------------
-- The talent window: rings and numbers on what to click next (1, 2, 3)
---------------------------------------------------------------------------
local marks = {}
local function Mark(i)
	local m = marks[i]
	if m then return m end
	m = CreateFrame("Frame", nil, UIParent)
	m.glow = m:CreateTexture(nil, "OVERLAY")
	m.glow:SetAllPoints(); m.glow:SetTexture("Interface\\Buttons\\CheckButtonHilight"); m.glow:SetBlendMode("ADD")
	m.badge = m:CreateTexture(nil, "OVERLAY", nil, 2); m.badge:SetTexture(P.MEDIA .. "Dot"); m.badge:SetSize(20, 20)
	m.badge:SetPoint("CENTER", m, "TOPRIGHT", -6, -6)
	m.num = m:CreateFontString(nil, "OVERLAY", nil, 3); m.num:SetFontObject(P.fonts.title); m.num:SetPoint("CENTER", m.badge, "CENTER", 0, 0)
	m.pulse = m:CreateAnimationGroup(); m.pulse:SetLooping("BOUNCE")
	local a = m.pulse:CreateAnimation("Alpha"); a:SetFromAlpha(1); a:SetToAlpha(0.4); a:SetDuration(0.7); a:SetTarget(m.glow)
	marks[i] = m
	return m
end
local function HideMarks() for _, m in ipairs(marks) do m:Hide(); m.pulse:Stop() end end

local banner
local function Banner(parent, text)
	if not banner then
		banner = CreateFrame("Frame", nil, UIParent, "BackdropTemplate")
		P.Flat(banner, nil, nil, true)
		banner:SetHeight(24)
		banner.t = banner:CreateFontString(nil, "OVERLAY"); banner.t:SetFontObject(P.fonts.button); banner.t:SetPoint("CENTER")
	end
	if not text then banner:Hide() return end
	banner:SetParent(parent); banner:SetFrameLevel(parent:GetFrameLevel() + 50)
	banner:ClearAllPoints(); banner:SetPoint("BOTTOM", parent, "TOP", 0, 4)
	banner.t:SetText(text)
	banner:SetWidth(banner.t:GetStringWidth() + 24)
	banner:Show()
end

local function ButtonFor(t)
	local tf = TalentsFrame()
	if t.node and tf and tf.nodeIDToButton then return tf.nodeIDToButton[t.node], tf end
	for _, prefix in ipairs({ "PlayerTalentFrameTalent", "TalentFrameTalent" }) do
		for i = 1, 60 do
			local b = _G[prefix .. i]
			if not b then break end
			if b:IsVisible() and b:GetID() == t.index then return b, _G.PlayerTalentFrame or _G.TalentFrame end
		end
	end
end

function P:MarkTalent()
	HideMarks()
	if not (P.db and S().talentHints) then Banner(nil) return end
	local frame = TalentsFrame() or _G.PlayerTalentFrame or _G.TalentFrame
	if not (frame and frame:IsVisible()) then return end
	local list, buildName = self:NextTalents(3)
	if not list[1] or Unspent() < 1 then Banner(nil) return end
	local A = P.ACCENT
	local names = {}
	for i, n in ipairs(list) do
		local b = ButtonFor(n.t)
		if b and b:IsVisible() then
			local m = Mark(i)
			m:SetParent(b); m:SetFrameLevel(b:GetFrameLevel() + 10)
			m:ClearAllPoints(); m:SetPoint("TOPLEFT", b, "TOPLEFT", -5, 5); m:SetPoint("BOTTOMRIGHT", b, "BOTTOMRIGHT", 5, -5)
			local strength = i == 1 and 1 or 0.45
			m.glow:SetVertexColor(A[1], A[2], A[3], strength)
			m.badge:SetVertexColor(A[1] * strength, A[2] * strength, A[3] * strength, 1)
			m.num:SetText(i)
			m:Show()
			if i == 1 then m.pulse:Play() end
		end
		names[#names + 1] = (i == 1 and "|c" .. P.ACCENT_HEX or "|cffd8dde3") .. i .. ". " .. n.name .. " " .. n.rank .. "/" .. n.t.max .. "|r"
	end
	Banner(frame, P.TITLE .. "  " .. table.concat(names, P.DIM .. "  ›  |r") .. "  " .. P.DIM .. "(" .. (buildName or "") .. ")|r")
end

local hooked
local function HookFrame()
	if hooked then return end
	local f = TalentsFrame() or _G.PlayerTalentFrame or _G.TalentFrame
	if not f then return end
	hooked = true
	f:HookScript("OnShow", function() C_Timer.After(0.1, function() P:MarkTalent() end) end)
	f:HookScript("OnHide", function() HideMarks(); Banner(nil) end)
	for _, fn in ipairs({ "TalentFrame_Update", "PlayerTalentFrame_Update" }) do
		if type(_G[fn]) == "function" then hooksecurefunc(fn, function() P:MarkTalent() end) end
	end
	for i = 1, 5 do
		local tab = _G[(f:GetName() or "") .. "Tab" .. i]
		if tab then tab:HookScript("OnClick", function() C_Timer.After(0, function() P:MarkTalent() end) end) end
	end
end

local function OpenTalents()
	if not TalentsFrame() and not (_G.PlayerTalentFrame or _G.TalentFrame) and UIParentLoadAddOn then
		pcall(UIParentLoadAddOn, "Blizzard_PlayerSpells")
		if not TalentsFrame() then pcall(UIParentLoadAddOn, "Blizzard_TalentUI") end
	end
	HookFrame()
	if PlayerSpellsUtil and PlayerSpellsUtil.OpenToClassTalentsTab then pcall(PlayerSpellsUtil.OpenToClassTalentsTab)
	elseif TogglePlayerSpellsFrame then pcall(TogglePlayerSpellsFrame) end
	C_Timer.After(0.2, function() P:MarkTalent() end)
end
function P:OpenTalents() OpenTalents() end

---------------------------------------------------------------------------
-- Telling you: once per new point, a small card
---------------------------------------------------------------------------
local lastTold
local function Tell()
	if not (P.db and S().talentHints) then return end
	local n = Unspent()
	if n < 1 then lastTold = nil; P:DismissPrompt("talent"); return end
	local name, t, tabName, buildName = P:NextTalent()
	if not name then return end
	local key = name .. (t.rank + 1)
	if key == lastTold then return end
	lastTold = key
	if InCombatLockdown() then return end
	P:Ask({
		key = "talent",
		icon = t.icon or "Interface\\Icons\\INV_Misc_Book_11",
		title = ("Talent point%s: %s"):format(n > 1 and (" (" .. n .. ")") or "", name),
		text = ("Rank %d of %d%s\n" .. P.DIM .. "%s leveling build|r"):format(t.rank + 1, t.max,
			tabName and ("  ·  " .. tabName) or "", buildName),
		buttons = {
			{ "Later", function() end },
			{ "Show me", OpenTalents, true },
		},
	})
end

local function Changed() if P.db then P:Debounce("talents", 0.3, function() Tell(); P:MarkTalent() end) end end
for _, ev in ipairs({ "CHARACTER_POINTS_CHANGED", "TRAIT_CONFIG_UPDATED", "TRAIT_NODE_CHANGED", "TRAIT_TREE_CURRENCY_INFO_UPDATED" }) do
	P:On(ev, Changed)
end
P:On("PLAYER_LEVEL_UP", function() if P.db then C_Timer.After(1.5, Tell) end end)
P:On("ADDON_LOADED", function(_, name) if name == "Blizzard_TalentUI" or name == "Blizzard_PlayerSpells" then HookFrame() end end)
P:Listen("READY", function()
	HookFrame()
	C_Timer.After(8, Tell)
end)
P:Listen("SETTINGS_CHANGED", function() if not S().talentHints then HideMarks(); Banner(nil) end end)

-- /pw talents: what's next, and the whole order
function P:TalentSlash()
	local build = BUILDS[P.me and P.me.classFile or select(2, UnitClass("player"))]
	if not build then P:Print("No talent build for your class yet.") return end
	local name, t, tabName = P:NextTalent()
	P:Print(("%s leveling build. %s"):format(build.name,
		name and ("Next: " .. name .. " (" .. (t.rank + 1) .. "/" .. t.max .. (tabName and (", " .. tabName) or "") .. ")") or "Nothing to add right now."))
	OpenTalents()
end
end part() end
