--[[ Pathway — Catalog
     Every quest this character could ever do, organized the way you'd look
     for them: by zone (with its level range and continent), by dungeon, by
     class and by profession, and in chains built from each quest's
     prerequisites and follow-ups.
       · a zone's "main story" is its chains plus its breadcrumbs: just what
         moves you forward
       · guides are loaded from here: a zone, its story, one chain, a dungeon's
         quests, a single quest, or the flight paths you haven't found ]]

local ADDON, P = __addon, __ns
local K = P.K
local pairs, ipairs, sort, floor, max, min = pairs, ipairs, table.sort, math.floor, math.max, math.min
local EMPTY = {}

local C = {}
P.Cat = C

C.PROF = { [129] = "First Aid", [164] = "Blacksmithing", [165] = "Leatherworking", [171] = "Alchemy", [182] = "Herbalism",
	[185] = "Cooking", [186] = "Mining", [197] = "Tailoring", [202] = "Engineering", [333] = "Enchanting",
	[356] = "Fishing", [393] = "Skinning", [633] = "Lockpicking", [762] = "Riding" }
local CLASS_SORT = { [-61] = true, [-81] = true, [-82] = true, [-141] = true, [-161] = true, [-162] = true,
	[-261] = true, [-262] = true, [-263] = true }

---------------------------------------------------------------------------
-- Where a quest belongs
---------------------------------------------------------------------------
local function FirstMap(kind, ids)
	for _, id in ipairs(ids or EMPTY) do
		local e = P:Entity(kind, id)
		if e and e[2] then
			local best, n = nil, -1
			for map, pts in pairs(e[2]) do if #pts > n then best, n = map, #pts end end
			if best then return best end
		end
	end
end

local function DungeonOf(q)
	local function check(kind, ids)
		for _, id in ipairs(ids or EMPTY) do
			local e = P:Entity(kind, id)
			if e and type(e[3]) == "string" then return e[3] end
		end
	end
	local d = check("N", q[K.ON]) or check("O", q[K.OO])
	if d then return d end
	for _, iid in ipairs(q[K.OI] or EMPTY) do
		local it = P.I[iid]
		if it then d = check("N", it[2]) or check("O", it[3]); if d then return d end end
	end
	return check("N", q[K.SN]) or check("N", q[K.EN])
end

local function Range(list)
	local lv = {}
	for _, qid in ipairs(list) do
		local l = P.Q[qid][K.LVL] or 0
		if l > 0 then lv[#lv + 1] = l end
	end
	if #lv == 0 then return 0, 0 end
	sort(lv)
	return lv[max(1, floor(#lv * 0.1 + 0.5))], lv[max(1, floor(#lv * 0.9 + 0.5))]
end

local function ByLevel(a, b)
	local la, lb = P.Q[a][K.LVL] or 0, P.Q[b][K.LVL] or 0
	if la ~= lb then return la < lb end
	return a < b
end

---------------------------------------------------------------------------
-- Chains: prerequisites and follow-ups, joined into connected groups,
-- ordered so every quest comes after what it needs
---------------------------------------------------------------------------
local function BuildChains(mine)
	local parent = {}
	local function find(x)
		local p = parent[x]
		if not p then parent[x] = x; return x end
		if p == x then return x end
		local r = find(p)
		parent[x] = r
		return r
	end
	local function union(a, b) local ra, rb = find(a), find(b); if ra ~= rb then parent[ra] = rb end end
	-- a link joins a chain only when it's one-to-one: a quest that opens many
	-- (a hub like "A Threat Within") or one that needs many ends the chain there,
	-- unless the data names it as the chain's next step
	local succ, pcount, scount, explicit = {}, {}, {}, {}
	local function add(a, b)
		if not (mine[a] and mine[b]) or a == b then return end
		succ[a] = succ[a] or {}
		if succ[a][b] then return end
		succ[a][b] = true
		scount[a] = (scount[a] or 0) + 1
		pcount[b] = (pcount[b] or 0) + 1
	end
	for qid in pairs(mine) do
		local q = P.Q[qid]
		for _, p in ipairs(q[K.PRE] or EMPTY) do add(p, qid) end
		for _, p in ipairs(q[K.PREANY] or EMPTY) do add(p, qid) end
		if q[K.NEXT] then add(qid, q[K.NEXT]); explicit[qid .. ">" .. q[K.NEXT]] = true end
	end
	for a, list in pairs(succ) do
		for b in pairs(list) do
			if (scount[a] == 1 or explicit[a .. ">" .. b]) and (pcount[b] == 1 or explicit[a .. ">" .. b]) then union(a, b)
			else list[b] = nil end
		end
	end
	local groups = {}
	for qid in pairs(parent) do
		local r = find(qid)
		groups[r] = groups[r] or {}
		table.insert(groups[r], qid)
	end
	local chains, chainOf = {}, {}
	for _, members in pairs(groups) do
		if #members >= 2 then
			-- Kahn's order, lowest level first among the ready ones
			local indeg, ready, order = {}, {}, {}
			local inSet = {}
			for _, q in ipairs(members) do inSet[q] = true; indeg[q] = 0 end
			for _, q in ipairs(members) do for s in pairs(succ[q] or EMPTY) do if inSet[s] then indeg[s] = indeg[s] + 1 end end end
			for _, q in ipairs(members) do if indeg[q] == 0 then ready[#ready + 1] = q end end
			while #ready > 0 do
				sort(ready, ByLevel)
				local q = table.remove(ready, 1)
				order[#order + 1] = q
				for s in pairs(succ[q] or EMPTY) do
					if inSet[s] then
						indeg[s] = indeg[s] - 1
						if indeg[s] == 0 then ready[#ready + 1] = s end
					end
				end
			end
			if #order < #members then           -- a loop in the data: keep the rest by level
				local seen = {}
				for _, q in ipairs(order) do seen[q] = true end
				local rest = {}
				for _, q in ipairs(members) do if not seen[q] then rest[#rest + 1] = q end end
				sort(rest, ByLevel)
				for _, q in ipairs(rest) do order[#order + 1] = q end
			end
			-- named after a title the chain repeats ("The Defias Brotherhood"), else its first quest
			local count, name = {}, nil
			for _, q in ipairs(order) do
				local n = P.Q[q][K.NAME]
				count[n] = (count[n] or 0) + 1
				if count[n] >= 2 and not name then name = n end
			end
			local lo, hi = Range(order)
			local chain = { id = order[1], quests = order, name = name or P.Q[order[1]][K.NAME], lo = lo, hi = hi }
			chains[#chains + 1] = chain
			for _, q in ipairs(order) do chainOf[q] = chain end
		end
	end
	sort(chains, function(a, b) if a.lo ~= b.lo then return a.lo < b.lo end return a.name < b.name end)
	return chains, chainOf
end

---------------------------------------------------------------------------
-- Build once, rebuild when the character's level or settings change it
---------------------------------------------------------------------------
function C:Build()
	if self.built then return end
	local zones, dungeons, profs = {}, {}, {}
	local class = { key = "class", name = (UnitClass("player")) .. " quests", quests = {} }
	local mine, zoneOf = {}, {}
	for qid, q in pairs(P.Q) do
		if P:ForMe(qid) then
			mine[qid] = true
			local skill = q[K.SKILL]
			if skill then
				local b = profs[skill]
				if not b then b = { key = "prof:" .. skill, name = C.PROF[skill] or ("Skill " .. skill), quests = {} }; profs[skill] = b end
				b.quests[#b.quests + 1] = qid
			elseif q[K.CLS] or CLASS_SORT[q[K.SORT] or 0] then
				class.quests[#class.quests + 1] = qid
			else
				local zone = q[K.ZONE] or FirstMap("N", q[K.SN]) or FirstMap("O", q[K.SO])
				if zone then
					local z = zones[zone]
					if not z then z = { key = "zone:" .. zone, map = zone, name = P:MapName(zone), quests = {} }; zones[zone] = z end
					z.quests[#z.quests + 1] = qid
					zoneOf[qid] = zone
				end
			end
			local d = DungeonOf(q)
			if d then
				local b = dungeons[d]
				if not b then b = { key = "dungeon:" .. d, name = d, quests = {} }; dungeons[d] = b end
				b.quests[#b.quests + 1] = qid
			end
		end
	end
	self.mine = mine
	self.chains, self.chainOf = BuildChains(mine)
	-- a chain lives in the zone that holds most of it
	for _, ch in ipairs(self.chains) do
		local count, best, n = {}, nil, 0
		for _, qid in ipairs(ch.quests) do
			local z = zoneOf[qid]
			if z then
				count[z] = (count[z] or 0) + 1
				if count[z] > n then best, n = z, count[z] end
			end
		end
		ch.home = best
	end

	local function finish(b)
		sort(b.quests, ByLevel)
		b.lo, b.hi = Range(b.quests)
		return b
	end
	self.zones, self.zoneList = zones, {}
	for map, z in pairs(zones) do
		finish(z)
		local info = C_Map.GetMapInfo(map)
		local cont = info and info.parentMapID
		z.cont = (cont == 1414 or cont == 1415) and cont or 0
		z.contName = z.cont ~= 0 and P:MapName(z.cont) or "Elsewhere"
		-- chains that start here, and the rest
		z.chains, z.singles, z.story = {}, {}, {}
		local seen = {}
		for _, qid in ipairs(z.quests) do
			local ch = self.chainOf[qid]
			if ch then
				if not seen[ch] and ch.home == map then
					seen[ch] = true
					z.chains[#z.chains + 1] = ch
				end
			else
				z.singles[#z.singles + 1] = qid
			end
		end
		-- the main story: its chains and its breadcrumbs
		for _, ch in ipairs(z.chains) do for _, qid in ipairs(ch.quests) do z.story[qid] = true end end
		for _, qid in ipairs(z.quests) do if P.Q[qid][K.CRUMB] then z.story[qid] = true end end
		if #z.quests >= 3 then self.zoneList[#self.zoneList + 1] = z end
	end
	sort(self.zoneList, function(a, b)
		if a.cont ~= b.cont then return a.cont > b.cont end      -- Eastern Kingdoms, then Kalimdor, then the rest
		if a.lo ~= b.lo then return a.lo < b.lo end
		return a.name < b.name
	end)
	self.dungeonList = {}
	for _, b in pairs(dungeons) do self.dungeonList[#self.dungeonList + 1] = finish(b) end
	sort(self.dungeonList, function(a, b) if a.lo ~= b.lo then return a.lo < b.lo end return a.name < b.name end)
	self.class = finish(class)
	-- Forever's own and hidden quests (and ones Pathway learned), by zone
	local fz = {}
	for qid in pairs(mine) do
		if qid >= 78000 or (P.base and not P.base[qid]) then
			local z = zoneOf[qid] or P.Q[qid][K.ZONE] or 0
			local b = fz[z]
			if not b then b = { key = "forever:" .. z, name = z ~= 0 and P:MapName(z) or "Elsewhere", quests = {}, map = z ~= 0 and z or nil }; fz[z] = b end
			b.quests[#b.quests + 1] = qid
		end
	end
	self.foreverList = {}
	for _, b in pairs(fz) do self.foreverList[#self.foreverList + 1] = finish(b) end
	sort(self.foreverList, function(a, b) if a.lo ~= b.lo then return a.lo < b.lo end return a.name < b.name end)
	self.profList = {}
	for _, b in pairs(profs) do self.profList[#self.profList + 1] = finish(b) end
	sort(self.profList, function(a, b) return a.name < b.name end)
	self.built = true
end

function C:Reset() self.built = false end
P:Listen("SETTINGS_CHANGED", function() C:Reset() end)

---------------------------------------------------------------------------
-- Progress
---------------------------------------------------------------------------
function C:Progress(list)
	local done, total = 0, 0
	for _, qid in ipairs(list) do
		total = total + 1
		if P.done[qid] then done = done + 1 end
	end
	return done, total, total > 0 and done / total or 0
end

function C:SetProgress(set)
	local done, total = 0, 0
	for qid in pairs(set) do
		total = total + 1
		if P.done[qid] then done = done + 1 end
	end
	return done, total, total > 0 and done / total or 0
end

-- the zones that suit you best right now
function C:ForYou(n)
	self:Build()
	local lvl = P.me.level or 1
	local out = {}
	for _, z in ipairs(self.zoneList) do
		if z.lo <= lvl + 1 and z.hi >= lvl - 1 then
			local avail = 0
			for _, qid in ipairs(z.quests) do if P:Available(qid) then avail = avail + 1 end end
			if avail > 0 then out[#out + 1] = { zone = z, avail = avail } end
		end
	end
	sort(out, function(a, b) return a.avail > b.avail end)
	local res = {}
	for i = 1, min(n or 3, #out) do res[i] = out[i].zone end
	return res
end

---------------------------------------------------------------------------
-- Loading guides
--   zone:<map>  story:<map>  chain:<first quest>  dungeon:<name>  class
--   prof:<skill>  quest:<id>  flights
---------------------------------------------------------------------------
local function Set(list) local s = {} for _, q in ipairs(list) do s[q] = true end return s end

-- Chains, one at a time.
--   Storyline: only the story chain that fits your level best (the one
--     you're on, else the one whose next quest is closest to your level),
--     start to finish, with the breadcrumbs that lead into it. Then the next
--     best one.
--   All quests: every quest in the zone, but chain to chain: you finish one
--     chain before the next starts (the one you're on, else the closest), and
--     quests on their own are picked up where they sit along that chain.
local function Doable(qid) return P.log[qid] or P:Available(qid) end
-- the quest of a chain you'd do next (or are doing)
local function NextOf(ch)
	for _, q in ipairs(ch.quests) do
		if not P.done[q] and Doable(q) then return q end
	end
end
local function Started(ch)
	for _, q in ipairs(ch.quests) do if P.log[q] then return true end end
	return false
end
-- how well a chain fits you now: lower is better. A little below your level
-- is easy experience, above it is hard going; a chain you're on comes first.
function C:Fit(ch)
	local q = NextOf(ch)
	if not q then return end
	local lvl = P.me.level or 1
	local ql = P.Q[q][K.LVL] or 0
	if ql <= 0 then ql = lvl end
	local d = ql - lvl
	local score = d >= 0 and d * 1.5 or -d
	if Started(ch) then score = score - 4
	elseif P.done[ch.quests[1]] then score = score - 1 end      -- partway through: carry on with it
	return score, q
end
function C:BestChain(chains)
	local best, bs
	for _, ch in ipairs(chains) do
		local sc = self:Fit(ch)
		if sc and (not bs or sc < bs) then best, bs = ch, sc end
	end
	return best, bs
end
-- where a quest is picked up (or handed in, once it's in your log): world yards
local function GiverAt(qid, inst, px, py)
	local q = P.Q[qid]
	local ents = {}
	local by = P.log[qid] and { K.EN, K.EO } or { K.SN, K.SO }
	for _, id in ipairs(q[by[1]] or EMPTY) do ents[#ents + 1] = { "N", id } end
	for _, id in ipairs(q[by[2]] or EMPTY) do ents[#ents + 1] = { "O", id } end
	if #ents == 0 then return end
	local d, _, _, _, wx, wy = P:Nearest(ents, inst, px, py)
	return d, wx, wy
end

function C:StoryFocus(z)
	local focus = self:BestChain(z.chains)
	if not focus then return end
	local set = {}
	for _, q in ipairs(focus.quests) do set[q] = true end
	-- the breadcrumbs that lead into it
	for qid in pairs(z.story) do
		local crumb = P.Q[qid][K.CRUMB]
		if crumb and set[crumb] and not P.done[qid] and Doable(qid) then set[qid] = true end
	end
	return set, focus
end

local NEAR_CHAIN = 90       -- yards: a quest on its own this close to the chain's people is "on the way"
function C:ZoneFocus(z)
	local inst, px, py = P:PlayerPos()
	local set = {}
	-- what you've started here stays in
	for _, qid in ipairs(z.quests) do if P.log[qid] then set[qid] = true end end
	-- the chain: one you're on, else the closest one you can start
	local focus, fd
	for _, ch in ipairs(z.chains) do
		local q = NextOf(ch)
		if q then
			local d = GiverAt(q, inst, px, py) or math.huge
			if Started(ch) then d = -1 end
			if not fd or d < fd then focus, fd = ch, d end
		end
	end
	local spots = {}
	if focus then
		for _, q in ipairs(focus.quests) do
			set[q] = true
			if not P.done[q] then
				local _, wx, wy = GiverAt(q, inst, px, py)
				if wx then spots[#spots + 1] = { wx, wy } end
			end
		end
	end
	if px then spots[#spots + 1] = { px, py } end
	-- quests on their own: along the chain (all of them, once the chains are done)
	for _, qid in ipairs(z.singles) do
		if not P.done[qid] and P:Available(qid) then
			if not focus then set[qid] = true
			else
				local _, wx, wy = GiverAt(qid, inst, px, py)
				if wx then
					for _, sp in ipairs(spots) do
						if (sp[1] - wx) ^ 2 + (sp[2] - wy) ^ 2 <= NEAR_CHAIN * NEAR_CHAIN then set[qid] = true break end
					end
				end
			end
		end
	end
	if not next(set) then return end
	return set, focus
end

-- the closest zone whose story has a chain for your level (yours first)
function C:StoryElsewhere(not_)
	self:Build()
	local inst, px, py = P:PlayerPos()
	local best, bs
	for _, z in ipairs(self.zoneList) do
		if z.map ~= not_ then
			local ch, sc = self:BestChain(z.chains)
			if ch then
				local i, wx, wy = P:WorldPos(z.map, 0.5, 0.5)
				local yd = (i and i == inst and px) and math.sqrt((wx - px) ^ 2 + (wy - py) ^ 2) or 30000
				local total = sc + yd / 2500
				if not bs or total < bs then best, bs = z, total end
			end
		end
	end
	return best
end

-- what a guide leads into when it's done
function P:NextGuide(key)
	C:Build()
	local kind, arg = key:match("^(%a+):?(.*)$")
	local id = tonumber(arg)
	-- after a chain or a single quest: on with the way you quest (never a
	-- style you didn't pick)
	local function Yours(zone)
		local st = P:QuestStyle()
		if st == "fast" then return "fast" end
		if not zone then return end
		return (st == "all" and "zone:" or "story:") .. zone
	end
	if kind == "chain" then
		local ch = C.chainOf[id]
		return Yours(ch and ch.home)
	elseif kind == "quest" then
		local ch = C.chainOf[id]
		if ch then return "chain:" .. ch.id end
		local q = P.Q[id]
		return Yours(q and q[K.ZONE] and C.zones[q[K.ZONE]] and q[K.ZONE])
	elseif kind == "story" or kind == "zone" then
		return key                                   -- the next chain, the same way
	elseif kind == "start" then
		return Yours(tonumber(arg))                  -- first steps done: the zone, your way
	end
end

function C:Find(key)
	self:Build()
	local kind, arg = key:match("^(%a+):?(.*)$")
	if kind == "zone" or kind == "story" then
		local z = self.zones[tonumber(arg)]
		if not z then return end
		if kind == "zone" then
			local set, focus = self:ZoneFocus(z)
			if not set then return end
			if focus then
				local d = 0
				for _, q in ipairs(focus.quests) do if P.done[q] then d = d + 1 end end
				return set, ("%s: all quests · %s  %d/%d"):format(z.name, focus.name, d, #focus.quests)
			end
			return set, z.name .. ": all quests"
		end
		local set, focus = self:StoryFocus(z)
		if not set then return end
		if focus then
			local d = 0
			for _, q in ipairs(focus.quests) do if P.done[q] then d = d + 1 end end
			return set, ("%s: %s  %d/%d"):format(z.name, focus.name, d, #focus.quests)
		end
		return set, z.name .. ": main story"
	elseif kind == "chain" then
		local ch = self.chainOf[tonumber(arg)]
		if ch then return Set(ch.quests), ch.name end
	elseif kind == "dungeon" then
		for _, b in ipairs(self.dungeonList) do if b.name == arg then return Set(b.quests), b.name end end
	elseif kind == "class" then
		return Set(self.class.quests), self.class.name
	elseif kind == "forever" then
		for _, b in ipairs(self.foreverList) do if b.key == key then return Set(b.quests), b.name .. ": Forever quests" end end
	elseif kind == "prof" then
		for _, b in ipairs(self.profList) do if b.key == key then return Set(b.quests), b.name end end
	elseif kind == "quest" then
		local q = P.Q[tonumber(arg)]
		if q then return { [tonumber(arg)] = true }, q[K.NAME] end
	end
end

function P:LoadGuide(key, quiet)
	local start = key:match("^start:(%d+)$")
	if start then
		local z = tonumber(start)
		return self:StartRoute("zone", { map = z, quiet = quiet, title = self:MapName(z) .. ": first steps", guide = key })
	end
	if key == "flights" then
		return self:StartRoute("flights", { title = "Flight paths", guide = "flights", quiet = quiet })
	end
	if key == "fast" then return self:StartRoute("fast", { quiet = quiet }) end
	local set, title = C:Find(key)
	if not set then return false end
	local ok = self:StartRoute("guide", { quests = set, title = title, guide = key, quiet = quiet })
	if ok and not quiet then
		self:Toast("Guide loaded: " .. title)
		if self.GuideState and self:GuideState() == "mini" then self:SetGuideState("open") end
	end
	return ok
end

-- why can't I do this one? (for the journal)
local WHY = {
	done = "Done", ready = "Ready to turn in", active = "In your quest log", available = "You can pick this up now",
	low = "Easy for you now (gray)", elsewhere = "No known location",
}
function C:StatusText(qid)
	local st, why = P:QuestStatus(qid)
	if WHY[st] then return st, WHY[st] end
	local q = P.Q[qid]
	if st == "high" then return st, ("Needs level %d"):format(max(q[K.REQ] or 0, (q[K.LVL] or 0) - P.db.settings.aheadLevels)) end
	if why and why:find("^needs ") then
		local id = tonumber(why:match("(%d+)"))
		return st, "First: " .. (id and P.Q[id] and P.Q[id][K.NAME] or why)
	end
	if why == "not offered" then return st, "Its giver didn't offer it: counted as done" end
	if why == "elite" then return st, "Elite: you chose to skip these" end
	if why == "profession" then return st, "Needs " .. (C.PROF[q[K.SKILL]] or "a profession") end
	if why and why:find("excluded") then return st, "Not available: you took a different path" end
	if why == "chain moved on" then return st, "You're past this one in the chain" end
	if why == "breadcrumb not needed" then return st, "Not needed: you found the way already" end
	return st, why or "Not available yet"
end
end part() end
-- ==================== Journal.lua
do local __addon, __ns = ... local function part()
-- Copyright (C) 2026 SoFinSicc. Part of Pathway (curseforge.com/wow/addons/pathway): free software under the GPLv3 or later, with additional terms that require keeping this credit. See LICENSE.md.
--[[ Pathway — Journal
     The quest catalog as a window, in three columns:
       · where: zones (by continent), dungeons, your class, professions, pets & mounts, flights
       · what: the place's progress, one-click guides, its chains and quests
       · the quest: where it starts and ends, what to do, what comes before
     /pw journal  ·  Guides on the world map bar  ·  key binding ]]

local ADDON, P = __addon, __ns
local K = P.K
local A = P.ACCENT
local floor, max, min = math.floor, math.max, math.min
local C = P.Cat
local EMPTY = {}

local W, H = 900, 600
local LEFT_W, MID_W = 230, 310
local ROW = 22
local DOT = P.MEDIA .. "Dot"
local WHITE = "Interface\\Buttons\\WHITE8x8"

local STATUS = {
	done      = { { 0.40, 0.75, 0.45 }, "Done" },
	ready     = { { 1, 0.82, 0.30 }, "Ready to turn in" },
	active    = { A, "In your log" },
	available = { { 0.95, 0.96, 0.97 }, "Available" },
	low       = { { 0.55, 0.57, 0.60 }, "Easy now" },
	high      = { { 1, 0.55, 0.30 }, "Too high for now" },
	locked    = { { 0.45, 0.47, 0.52 }, "Not yet" },
	elsewhere = { { 0.45, 0.47, 0.52 }, "No location" },
}

local function Hex(c) return ("|cff%02x%02x%02x"):format(floor(c[1] * 255), floor(c[2] * 255), floor(c[3] * 255)) end
local function Pct(f) return floor(f * 100 + 0.5) .. "%" end
local function Dot(c, size)
	size = size or 8
	return ("|T%s:%d:%d:0:0:16:16:0:16:0:16:%d:%d:%d|t"):format(DOT, size, size, floor(c[1] * 255), floor(c[2] * 255), floor(c[3] * 255))
end
local function Tex(path, size) return ("|T%s:%d:%d:0:0:64:64:5:59:5:59|t"):format(path, size or 14, size or 14) end

-- the game's quest colors: gray, green, yellow, orange, red
local function LevelColor(lvl)
	if not lvl or lvl <= 0 then return { 0.6, 0.62, 0.66 } end
	if GetQuestDifficultyColor then
		local c = GetQuestDifficultyColor(lvl)
		if c then return { c.r, c.g, c.b } end
	end
	local d = lvl - (P.me.level or 1)
	if d >= 5 then return { 1, 0.1, 0.1 } elseif d >= 3 then return { 1, 0.5, 0.25 } elseif d >= -2 then return { 1, 1, 0 }
	elseif d >= -8 then return { 0.25, 0.75, 0.25 } end
	return { 0.5, 0.5, 0.5 }
end
local function Range(g)
	if not g.lo or g.lo <= 0 then return "" end
	return g.lo == g.hi and tostring(g.lo) or (g.lo .. "–" .. g.hi)
end

---------------------------------------------------------------------------
-- A small virtual list: fixed rows, wheel scrolling, a thin thumb
---------------------------------------------------------------------------
local function List(parent, width, height, render, onClick)
	local f = CreateFrame("Frame", nil, parent)
	f:SetSize(width, height)
	f.rows, f.items, f.offset = {}, {}, 0
	local n = floor(height / ROW)
	for i = 1, n do
		local r = CreateFrame("Button", nil, f)
		r:SetSize(width - 8, ROW)
		r:SetPoint("TOPLEFT", 0, -(i - 1) * ROW)
		r.hl = r:CreateTexture(nil, "BACKGROUND"); r.hl:SetAllPoints(); r.hl:SetColorTexture(1, 1, 1, 0.05); r.hl:Hide()
		r.sel = r:CreateTexture(nil, "BACKGROUND"); r.sel:SetAllPoints(); r.sel:SetColorTexture(A[1], A[2], A[3], 0.14); r.sel:Hide()
		r.edge = r:CreateTexture(nil, "BORDER"); r.edge:SetPoint("TOPLEFT"); r.edge:SetPoint("BOTTOMLEFT"); r.edge:SetWidth(2)
		r.edge:SetColorTexture(A[1], A[2], A[3], 1); r.edge:Hide()
		-- progress: a faint track and its fill, along the bottom
		r.track = r:CreateTexture(nil, "BORDER"); r.track:SetPoint("BOTTOMLEFT", 6, 1); r.track:SetPoint("BOTTOMRIGHT", -6, 1)
		r.track:SetHeight(2); r.track:SetColorTexture(1, 1, 1, 0.07)
		r.bar = r:CreateTexture(nil, "ARTWORK"); r.bar:SetPoint("BOTTOMLEFT", 6, 1); r.bar:SetHeight(2); r.bar:SetColorTexture(A[1], A[2], A[3], 0.85)
		r.badge = r:CreateFontString(nil, "OVERLAY"); r.badge:SetFontObject(P.fonts.head); r.badge:SetPoint("LEFT", 6, 1)
		r.badge:SetWidth(38); r.badge:SetJustifyH("LEFT")
		r.left = r:CreateFontString(nil, "OVERLAY"); r.left:SetFontObject(P.fonts.button)
		r.left:SetJustifyH("LEFT"); r.left:SetWordWrap(false)
		r.right = r:CreateFontString(nil, "OVERLAY"); r.right:SetFontObject(P.fonts.head); r.right:SetPoint("RIGHT", -6, 1)
		r:SetScript("OnEnter", function(s) s.hl:Show(); if f.onEnter and s.item then f.onEnter(s, s.item) end end)
		r:SetScript("OnLeave", function(s) s.hl:Hide(); GameTooltip:Hide() end)
		r:RegisterForClicks("LeftButtonUp", "RightButtonUp")
		r:SetScript("OnClick", function(s, btn) if s.item then onClick(s.item, btn) end end)
		f.rows[i] = r
	end
	local thumb = f:CreateTexture(nil, "OVERLAY")
	thumb:SetColorTexture(1, 1, 1, 0.16); thumb:SetWidth(3)
	f:EnableMouseWheel(true)
	f:SetScript("OnMouseWheel", function(s, d)
		s.offset = max(0, min(#s.items - n, s.offset - d * 3))
		s:Refresh()
	end)
	function f:SetItems(items, keep)
		self.items = items
		if not keep then self.offset = 0 end
		self.offset = max(0, min(self.offset, #items - n))
		self:Refresh()
	end
	function f:Refresh()
		for i, r in ipairs(self.rows) do
			local it = self.items[i + self.offset]
			r.item = it
			if it then
				r:Show(); r.bar:Hide(); r.track:Hide(); r.sel:Hide(); r.edge:Hide()
				r.badge:SetText("")
				r.left:SetFontObject(P.fonts.button)
				r.left:ClearAllPoints(); r.left:SetPoint("LEFT", 6, 1); r.left:SetPoint("RIGHT", r.right, "LEFT", -6, 0)
				r:EnableMouse(not it.head)
				render(r, it)
			else
				r:Hide()
			end
		end
		if #self.items > n then
			local h = max(16, height * n / #self.items)
			thumb:SetHeight(h)
			thumb:ClearAllPoints()
			thumb:SetPoint("TOPRIGHT", 0, -(height - h) * self.offset / (#self.items - n))
			thumb:Show()
		else
			thumb:Hide()
		end
	end
	return f
end

local function Bar(r, frac)
	r.track:Show()
	r.bar:SetWidth(max(1, (r:GetWidth() - 12) * frac))
	r.bar:Show()
end
local function WithBadge(r, text)
	r.badge:SetText(text)
	r.left:ClearAllPoints(); r.left:SetPoint("LEFT", 46, 1); r.left:SetPoint("RIGHT", r.right, "LEFT", -6, 0)
end
local function Heading(r, text)
	r.left:SetFontObject(P.fonts.head)
	r.left:SetText(text:upper())
	r.right:SetText("")
end

---------------------------------------------------------------------------
-- State
---------------------------------------------------------------------------
local win
local J = { tab = "home", hideDone = false, open = {} }    -- open[chain] = expanded
P.Journal = J

local TABS = {
	{ "home", "For you" }, { "zones", "Zones" }, { "forever", "Forever & secrets" }, { "dungeons", "Dungeons" }, { "class", "Class" }, { "profs", "Professions" }, { "collect", "Pets & mounts" }, { "flights", "Flight paths" },
}

local function Keep(qid) return not (J.hideDone and P.done[qid]) end

-- pets, mounts and curios you can go and get: ones for your side, with a known source
local collGroups
local function Mine(fac)
	local me = (P.me and P.me.faction or UnitFactionGroup("player")) == "Horde" and "H" or "A"
	return not fac or fac:find(me, 1, true) ~= nil
end
local function Gettable(id)
	local src = P.SRC and P.SRC[id]
	if not src then return false end
	if (src[2] and #src[2] > 0) or (src[4] and #src[4] > 0) or (src[5] and #src[5] > 0) then return true end
	for _, v in ipairs(src[3] or EMPTY) do
		local n = P.N and P.N[v]
		if n and Mine(n[4]) then return true end
	end
	return false
end
local function Owned(id)
	if ((P.Item and P.Item.GetItemCount or GetItemCount)(id, true) or 0) > 0 then return true end
	-- learned ones live in the mount and pet journals, where this client has them
	if C_MountJournal and C_MountJournal.GetMountFromItem then
		local ok, mid = pcall(C_MountJournal.GetMountFromItem, id)
		if ok and mid then
			local ok2, collected = pcall(function() return select(11, C_MountJournal.GetMountInfoByID(mid)) end)
			if ok2 and collected then return true end
		end
	end
	return false
end
local function How(id)
	local src = P.SRC[id]
	if src[2] and #src[2] > 0 then return "quest" end
	if src[3] and #src[3] > 0 then return "vendor" end
	if src[5] and #src[5] > 0 then return "found" end
	return "drop"
end
local function CollGroups()
	if collGroups then return collGroups end
	collGroups = {}
	for _, g in ipairs({ { "pets", "Companion pets" }, { "mounts", "Mounts" }, { "curios", "Curios" } }) do
		local list = {}
		for _, id in ipairs((P.COLL and P.COLL[g[1]]) or EMPTY) do
			if Gettable(id) then list[#list + 1] = { id = id, name = P.SRC[id][1] } end
		end
		table.sort(list, function(a, b) return a.name < b.name end)
		if #list > 0 then collGroups[#collGroups + 1] = { key = "coll:" .. g[1], name = g[2], coll = list } end
	end
	return collGroups
end
local function CollCount(g)
	local n = 0
	for _, e in ipairs(g.coll) do if Owned(e.id) then n = n + 1 end end
	return n
end

---------------------------------------------------------------------------
-- Left: places
---------------------------------------------------------------------------
local function LeftItems()
	C:Build()
	local items = {}
	if J.tab == "zones" then
		local best = C:ForYou(3)
		local star = {}
		for _, z in ipairs(best) do star[z] = true end
		if #best > 0 then
			items[#items + 1] = { head = "Suggested for you" }
			for _, z in ipairs(best) do items[#items + 1] = { group = z, star = true } end
		end
		local cont
		for _, z in ipairs(C.zoneList) do
			if z.cont ~= cont then cont = z.cont; items[#items + 1] = { head = z.contName } end
			items[#items + 1] = { group = z }
		end
	elseif J.tab == "dungeons" then
		for _, b in ipairs(C.dungeonList) do items[#items + 1] = { group = b } end
	elseif J.tab == "forever" then
		items[1] = { head = "New in Forever, hidden and learned" }
		for _, b in ipairs(C.foreverList) do items[#items + 1] = { group = b } end
	elseif J.tab == "class" then
		items[1] = { group = C.class }
	elseif J.tab == "profs" then
		for _, b in ipairs(C.profList) do items[#items + 1] = { group = b } end
	elseif J.tab == "collect" then
		items[1] = { head = "Go and get them" }
		for _, g in ipairs(CollGroups()) do items[#items + 1] = { group = g } end
	elseif J.tab == "flights" then
		local byZone, order, known, total = {}, {}, 0, 0
		for _, fp in ipairs(P:FlightList()) do
			local z = byZone[fp.map]
			if not z then
				z = { key = "fz:" .. fp.map, name = P:MapName(fp.map), flights = {}, map = fp.map, known = 0 }
				byZone[fp.map] = z; order[#order + 1] = z
			end
			z.flights[#z.flights + 1] = fp
			total = total + 1
			if fp.known then known = known + 1; z.known = z.known + 1 end
		end
		J.flightsKnown, J.flightsTotal = known, total
		items[1] = { head = ("%d of %d discovered"):format(known, total) }
		for _, z in ipairs(order) do items[#items + 1] = { group = z } end
	end
	return items
end

local function RenderLeft(r, it)
	if it.head then return Heading(r, it.head) end
	local g = it.group
	if J.group == g then r.sel:Show(); r.edge:Show() end
	if g.coll then
		local have = CollCount(g)
		r.left:SetText("|cffffffff" .. g.name .. "|r")
		r.right:SetText(P.DIM .. have .. "/" .. #g.coll .. "|r")
		Bar(r, have / #g.coll)
		return
	end
	if g.flights then
		local missing = #g.flights - g.known
		r.left:SetText((missing > 0 and "|cffffffff" or "|cff8a929b") .. g.name .. "|r")
		r.right:SetText(missing > 0 and ("|cffffd27a" .. missing .. " new|r") or (P.DIM .. "all|r"))
		Bar(r, g.known / #g.flights)
		return
	end
	local _, _, frac = C:Progress(g.quests)
	if g.lo and g.lo > 0 then WithBadge(r, Hex(LevelColor(floor((g.lo + g.hi) / 2))) .. Range(g) .. "|r") end
	local done = frac >= 1
	r.left:SetText((it.star and Dot(A, 7) .. " " or "") .. (done and "|cff8a929b" or "|cffffffff") .. g.name .. "|r")
	r.right:SetText(done and "|cff66bf73100%|r" or Pct(frac))
	Bar(r, frac)
end

---------------------------------------------------------------------------
-- Middle: the place's chains and quests
---------------------------------------------------------------------------
local function MidItems()
	local items = {}
	local search = J.search and #J.search >= 3 and J.search:lower()
	if search then
		C:Build()
		local hits = {}
		for qid in pairs(C.mine) do
			if P.Q[qid][K.NAME]:lower():find(search, 1, true) and Keep(qid) then hits[#hits + 1] = qid end
		end
		table.sort(hits, function(a, b) return (P.Q[a][K.LVL] or 0) < (P.Q[b][K.LVL] or 0) end)
		for i = 1, min(#hits, 300) do items[#items + 1] = { qid = hits[i] } end
		return items, #hits
	end
	local g = J.group
	if not g then return items end
	if g.flights then
		for _, fp in ipairs(g.flights) do items[#items + 1] = { flight = fp } end
		return items
	end
	if g.coll then
		local have = {}
		for _, e in ipairs(g.coll) do
			if Owned(e.id) then have[#have + 1] = e else items[#items + 1] = { coll = e } end
		end
		if #have > 0 and not J.hideDone then
			items[#items + 1] = { head = "You have" }
			for _, e in ipairs(have) do items[#items + 1] = { coll = e, owned = true } end
		end
		return items
	end
	local shown = {}
	local chains = g.chains
	if not chains then
		chains = {}
		local seen = {}
		for _, qid in ipairs(g.quests) do
			local ch = C.chainOf[qid]
			if ch and not seen[ch] then seen[ch] = true; chains[#chains + 1] = ch end
		end
	end
	local chainItems = {}
	for _, ch in ipairs(chains) do
		local list = {}
		for i, qid in ipairs(ch.quests) do
			shown[qid] = true
			if Keep(qid) then list[#list + 1] = { qid = qid, indent = true, step = i, of = #ch.quests } end
		end
		if #list > 0 then
			chainItems[#chainItems + 1] = { chain = ch }
			if J.open[ch] then for _, it in ipairs(list) do chainItems[#chainItems + 1] = it end end
		end
	end
	if #chainItems > 0 then
		items[#items + 1] = { head = "Story chains" }
		for _, it in ipairs(chainItems) do items[#items + 1] = it end
	end
	local rest = {}
	for _, qid in ipairs(g.quests) do if not shown[qid] and Keep(qid) then rest[#rest + 1] = qid end end
	if #rest > 0 then items[#items + 1] = { head = #chainItems > 0 and "Side quests" or "Quests" } end
	for _, qid in ipairs(rest) do items[#items + 1] = { qid = qid } end
	if #items == 0 then items[1] = { head = J.hideDone and "All done here" or "Nothing here" } end
	return items
end

local HOW = { quest = "|cffffd27aquest|r", vendor = "|cff9fd3ffvendor|r", drop = "|cffff9a6bdrop|r", found = "|cffc9b3ffchest|r" }
local function RenderMid(r, it)
	if it.head then return Heading(r, it.head) end
	if it.coll then
		local e = it.coll
		local icon = (C_Item and C_Item.GetItemIconByID and C_Item.GetItemIconByID(e.id)) or (GetItemIcon and GetItemIcon(e.id))
		r.left:SetText((icon and Tex(icon, 14) .. "  " or "") .. (it.owned and "|cff9aa3ad" or "|cffffffff") .. e.name .. "|r")
		r.right:SetText(it.owned and "|cff66bf73have|r" or HOW[How(e.id)])
		if J.item == e then r.sel:Show(); r.edge:Show() end
		return
	end
	if it.flight then
		local fp = it.flight
		r.left:SetText((fp.known and Tex("Interface\\TaxiFrame\\UI-Taxi-Icon-Green", 12) or Dot({ 1, 0.82, 0.3 }, 9)) .. "  "
			.. (fp.known and "|cff9aa3ad" or "|cffffffff") .. fp.name .. "|r")
		r.right:SetText(fp.known and (P.DIM .. "known|r") or "|cffffd27anew|r")
		if J.flight == fp then r.sel:Show(); r.edge:Show() end
		return
	end
	if it.chain then
		local ch = it.chain
		local done, total, frac = C:Progress(ch.quests)
		local open = J.open[ch]
		r.left:SetText(P.DIM .. (open and "–" or "+") .. "|r  " .. (done >= total and "|cff8a929b" or "|cffffffff") .. ch.name .. "|r")
		r.right:SetText((done >= total and "|cff66bf73" or "") .. done .. "/" .. total .. (done >= total and "|r" or ""))
		Bar(r, frac)
		return
	end
	local qid = it.qid
	local q = P.Q[qid]
	local st = P:QuestStatus(qid)
	local look = STATUS[st] or STATUS.locked
	local name = q[K.NAME]
	local col = (st == "done" or st == "locked" or st == "low" or st == "elsewhere") and look[1] or { 0.93, 0.95, 0.96 }
	local elite = P:QuestElite(qid)
	r.left:SetText((it.indent and "    " or "") .. Dot(look[1], 8) .. "  " .. Hex(col) .. name .. "|r"
		.. (elite and st ~= "done" and "  |cffff8c4dElite|r" or ""))
	local lvl = q[K.LVL] or 0
	r.right:SetText(lvl > 0 and (Hex(LevelColor(lvl)) .. lvl .. "|r") or "")
	if J.qid == qid then r.sel:Show(); r.edge:Show() end
end

---------------------------------------------------------------------------
-- Right: one quest
---------------------------------------------------------------------------
local function Where(kind, id)
	local e = P:Entity(kind, id)
	if not e then return "?" end
	if type(e[3]) == "string" then return "|cffffffff" .. e[1] .. "|r" .. P.DIM .. "  inside " .. e[3] .. "|r" end
	local best, n = nil, -1
	for map, pts in pairs(e[2] or EMPTY) do if #pts > n then best, n = map, #pts end end
	if not best then return "|cffffffff" .. e[1] .. "|r" end
	local x, y = P.Unpack(e[2][best][1])
	return ("|cffffffff%s|r\n%s%s  %.0f, %.0f|r"):format(e[1], P.DIM, P:MapName(best), x * 100, y * 100)
end

local function Section(L, title) L[#L + 1] = ""; L[#L + 1] = Hex(A) .. title:upper() .. "|r" end

local function QuestText(qid)
	local q = P.Q[qid]
	local L = {}
	local st, why = C:StatusText(qid)
	local look = STATUS[st] or STATUS.locked
	local lvl = q[K.LVL] or 0
	L[1] = Dot(look[1], 9) .. " " .. Hex(look[1]) .. why .. "|r"
	L[2] = P.DIM .. "Level " .. (lvl > 0 and (Hex(LevelColor(lvl)) .. lvl .. "|r" .. P.DIM) or "?")
		.. ((q[K.REQ] or 0) > 1 and ("  ·  from level " .. q[K.REQ]) or "") .. "|r"
	local elite = P:QuestElite(qid)
	if elite then L[#L + 1] = "|cffff8c4dElite: level " .. elite .. " elites. Bring a group.|r" end
	local mates = P.PartyOn and P:PartyOn(qid)
	if mates then L[#L + 1] = Hex(A) .. "Your group has it: " .. mates .. "|r" end

	local ch = C.chainOf[qid]
	if ch then
		local pos
		for i, id in ipairs(ch.quests) do if id == qid then pos = i break end end
		local dots = {}
		for i, id in ipairs(ch.quests) do
			if i > 12 then dots[#dots + 1] = P.DIM .. "...|r" break end
			dots[#dots + 1] = Dot(i == pos and A or (P.done[id] and STATUS.done[1] or { 0.35, 0.37, 0.42 }), i == pos and 10 or 7)
		end
		Section(L, "Chain")
		L[#L + 1] = "|cffffffff" .. ch.name .. "|r" .. P.DIM .. ("  ·  step %d of %d|r"):format(pos or 0, #ch.quests)
		L[#L + 1] = table.concat(dots, " ")
	end

	Section(L, "Where")
	local pick = Tex("Interface\\GossipFrame\\AvailableQuestIcon", 13)
	local turn = Tex("Interface\\GossipFrame\\ActiveQuestIcon", 13)
	if q[K.SN] then L[#L + 1] = pick .. " " .. Where("N", q[K.SN][1])
	elseif q[K.SO] then L[#L + 1] = pick .. " " .. Where("O", q[K.SO][1])
	elseif q[K.SI] then L[#L + 1] = pick .. " Starts from an item: |cffffffff" .. (P.I[q[K.SI][1]] and P.I[q[K.SI][1]][1] or "?") .. "|r" end
	if q[K.EN] then L[#L + 1] = turn .. " " .. Where("N", q[K.EN][1])
	elseif q[K.EO] then L[#L + 1] = turn .. " " .. Where("O", q[K.EO][1]) end

	local obj = {}
	for _, id in ipairs(q[K.ON] or EMPTY) do obj[#obj + 1] = "Kill |cffffffff" .. P:EntityName("N", id) .. "|r" end
	for _, id in ipairs(q[K.OO] or EMPTY) do obj[#obj + 1] = "Use |cffffffff" .. P:EntityName("O", id) .. "|r" end
	for _, id in ipairs(q[K.OI] or EMPTY) do
		local it = P.I[id]
		if it then
			local from = it[2] and it[2][1] and P:EntityName("N", it[2][1]) or it[3] and it[3][1] and P:EntityName("O", it[3][1])
			obj[#obj + 1] = "Get |cffffffff" .. it[1] .. "|r" .. (from and (P.DIM .. "  from " .. from .. "|r") or "")
		end
	end
	if #obj > 0 then
		Section(L, "To do")
		for _, o in ipairs(obj) do L[#L + 1] = Dot({ 0.5, 0.53, 0.58 }, 6) .. "  " .. o end
	end

	local pre = {}
	for _, id in ipairs(q[K.PRE] or EMPTY) do pre[#pre + 1] = id end
	for _, id in ipairs(q[K.PREANY] or EMPTY) do pre[#pre + 1] = id end
	if #pre > 0 then
		Section(L, "Needs first")
		for _, id in ipairs(pre) do
			local pq = P.Q[id]
			if pq then L[#L + 1] = Dot(P.done[id] and STATUS.done[1] or STATUS.high[1], 8) .. " " .. pq[K.NAME] end
		end
	end
	if q[K.NEXT] and P.Q[q[K.NEXT]] then
		Section(L, "Leads to")
		L[#L + 1] = P.Q[q[K.NEXT]][K.NAME]
	end
	if q[K.TEXT] and q[K.TEXT] ~= "" then
		Section(L, "Story")
		L[#L + 1] = P.DIM .. q[K.TEXT] .. "|r"
	end
	return table.concat(L, "\n")
end

local function FlightText(fp)
	local L = { P.DIM .. P:MapName(fp.map) .. (" %.0f, %.0f|r"):format(fp.x * 100, fp.y * 100), "" }
	L[#L + 1] = fp.known and (Dot(STATUS.done[1], 9) .. " |cff66bf73You have this flight path.|r")
		or (Dot({ 1, 0.82, 0.3 }, 9) .. " |cffffd27aNot discovered yet.|r\n\nTalk to the flight master once and it's yours. Pathway uses it from then on when flying is faster.")
	return table.concat(L, "\n")
end

