local function SetModel(npc)
	local m = win.model
	if npc and m.SetCreature then
		m:Show(); m:ClearModel(); m:SetCreature(npc)
		if m.SetPortraitZoom then m:SetPortraitZoom(0.6) end
	else
		m:Hide()
	end
end

local function ItemText(e)
	local L = {}
	if Owned(e.id) then L[#L + 1] = Dot(STATUS.done[1], 9) .. " |cff66bf73You have this one.|r"; L[#L + 1] = "" end
	local list = P:Sources(e.id)
	if list then
		for _, s in ipairs(list) do L[#L + 1] = s.text end
	else
		L[#L + 1] = P.DIM .. "Pathway doesn't know where this comes from yet.|r"
	end
	L[#L + 1] = ""
	L[#L + 1] = P.DIM .. "Get it takes you the fastest way there, then back to your guide.|r"
	return table.concat(L, "\n")
end

local function UpdateRight()
	local r = win.right
	r.go:Hide(); r.chain:Hide(); r.map:Hide()
	if J.item then
		r.title:SetText(J.item.name)
		r.body:SetText(ItemText(J.item))
		SetModel(nil)
		local list = P:Sources(J.item.id)
		local first = list and list[1]
		if first and first.kind ~= "here" then r.go:SetLabel("Get it"); r.go:Show() end
	elseif J.flight then
		r.title:SetText(J.flight.name)
		r.body:SetText(FlightText(J.flight))
		SetModel(J.flight.id)
		if J.flight.known then r.map:Show() else r.go:SetLabel("Go there"); r.go:Show() end
	elseif J.qid then
		local q = P.Q[J.qid]
		r.title:SetText(q[K.NAME])
		r.body:SetText(QuestText(J.qid))
		SetModel(q[K.SN] and q[K.SN][1] or nil)
		r.go:SetLabel("Go"); r.go:Show()
		if C.chainOf[J.qid] then r.chain:Show() end
	else
		r.title:SetText(J.tab == "flights" and "Flight paths" or J.tab == "collect" and "Pets & mounts" or "Quest journal")
		r.body:SetText(INTRO[J.tab] or INTRO.zones)
		SetModel(nil)
	end
	r.title:SetWidth(r:GetWidth() - 24 - (r.model:IsShown() and 84 or 0))
	r.body:SetHeight(r.body:GetStringHeight() + 4)
	r.scroll:SetVerticalScroll(0)
end

local function UpdateHeader()
	local m = win.mid
	local g = J.group
	m.story:Hide(); m.all:Hide(); m.fast:Hide(); m.meter:Hide(); m.done:Hide()
	if J.search and #J.search >= 3 then
		m.title:SetText("Search"); m.sub:SetText(P.DIM .. (J.hits or 0) .. " quests|r")
		m.done:Show()
		return
	end
	if not g then m.title:SetText(""); m.sub:SetText(""); return end
	m.title:SetText(g.name)
	if g.flights then
		m.sub:SetText(P.DIM .. g.known .. " of " .. #g.flights .. " discovered|r")
		return
	end
	if g.coll then
		m.sub:SetText(P.DIM .. CollCount(g) .. " of " .. #g.coll .. " collected|r")
		m.done:Show()
		return
	end
	local done, total, frac = C:Progress(g.quests)
	m.sub:SetText(P.DIM .. (g.lo > 0 and ("Levels " .. Range(g) .. "  ·  ") or "") .. done .. " of " .. total .. " done|r")
	m.meter:Show()
	m.meter.fill:SetWidth(max(1, (m.meter:GetWidth()) * frac))
	m.meter.text:SetText(Pct(frac))
	m.done:Show()
	if g.story and next(g.story) then
		local _, _, sf = C:SetProgress(g.story)
		m.story:SetLabel("Storyline  " .. Pct(sf))
		m.story:Show()
		m.all:ClearAllPoints(); m.all:SetPoint("LEFT", m.story, "RIGHT", 6, 0)
	else
		m.all:ClearAllPoints(); m.all:SetPoint("TOPLEFT", 10, -64)
	end
	m.all:SetLabel(g.map and "All quests" or "Follow all")
	m.all:Show()
	if g.map then m.fast:ClearAllPoints(); m.fast:SetPoint("LEFT", m.all, "RIGHT", 6, 0); m.fast:Show() end
end

