-- a zone's map, drawn small: its art tiles, scaled into the card
local function MapArt(holder, map)
	holder.tiles = holder.tiles or {}
	for _, t in ipairs(holder.tiles) do t:Hide() end
	if not (map and C_Map.GetMapArtLayers and C_Map.GetMapArtLayerTextures) then return false end
	local layers = C_Map.GetMapArtLayers(map)
	local L = layers and layers[1]
	local tex = L and C_Map.GetMapArtLayerTextures(map, 1)
	if not (L and tex and #tex > 0) then return false end
	local w, h = holder:GetWidth(), holder:GetHeight()
	local k = math.max(w / L.layerWidth, h / L.layerHeight)
	local cols = math.ceil(L.layerWidth / L.tileWidth)
	local ox = (w - L.layerWidth * k) / 2
	local oy = (h - L.layerHeight * k) / 2
	for i, file in ipairs(tex) do
		local t = holder.tiles[i]
		if not t then t = holder:CreateTexture(nil, "ARTWORK"); holder.tiles[i] = t end
		local c, r = (i - 1) % cols, math.floor((i - 1) / cols)
		t:SetTexture(file)
		t:SetSize(L.tileWidth * k, L.tileHeight * k)
		t:ClearAllPoints()
		t:SetPoint("TOPLEFT", holder, "TOPLEFT", ox + c * L.tileWidth * k, -(oy + r * L.tileHeight * k))
		t:Show()
	end
	return true
end

local function Head(parent, text, x, y)
	local fs = parent.heads and parent.heads[text]
	if not fs then
		fs = parent:CreateFontString(nil, "OVERLAY"); fs:SetFontObject(P.fonts.head)
		parent.heads = parent.heads or {}; parent.heads[text] = fs
	end
	fs:ClearAllPoints(); fs:SetPoint("TOPLEFT", x, y)
	fs:SetText(text:upper())
	return fs
end

local function Card(parent, w, h)
	local c = CreateFrame("Button", nil, parent, "BackdropTemplate")
	P.Flat(c, P.colors.PANEL)
	c:SetSize(w, h)
	c.hl = c:CreateTexture(nil, "HIGHLIGHT"); c.hl:SetAllPoints(); c.hl:SetColorTexture(1, 1, 1, 0.04)
	c:SetScript("OnEnter", function(self) self:SetBackdropBorderColor(A[1], A[2], A[3], 0.9); if self.tip then
		GameTooltip:SetOwner(self, "ANCHOR_TOP"); GameTooltip:SetText(self.tip, 1, 1, 1, 1, true); GameTooltip:Show() end end)
	c:SetScript("OnLeave", function(self) self:SetBackdropBorderColor(unpack(P.colors.EDGE)); GameTooltip:Hide() end)
	return c
end

local function Text(parent, font, justify)
	local fs = parent:CreateFontString(nil, "OVERLAY"); fs:SetFontObject(font or P.fonts.button)
	fs:SetJustifyH(justify or "LEFT"); fs:SetWordWrap(false)
	return fs
end

-- the newest Forever quests you haven't done, the ones you can take first
local function NewInForever(n)
	C:Build()
	local list = {}
	for _, b in ipairs(C.foreverList) do
		for _, qid in ipairs(b.quests) do if not P.done[qid] then list[#list + 1] = qid end end
	end
	table.sort(list, function(a, b)
		local aa, ab = P:Available(a) and 1 or 0, P:Available(b) and 1 or 0
		if aa ~= ab then return aa > ab end
		return a > b
	end)
	local out = {}
	for i = 1, math.min(n, #list) do out[i] = list[i] end
	return out
end

-- pets and mounts you don't have yet, the closest to get first
local function ToCollect(n)
	local inst, px, py = P:PlayerPos()
	local cands = {}
	for _, g in ipairs(CollGroups()) do
		for _, e in ipairs(g.coll) do
			if not Owned(e.id) then
				local src = P.SRC[e.id]
				local ents = {}
				for _, v in ipairs(src[3] or EMPTY) do local nn = P.N and P.N[v]; if nn and Mine(nn[4]) then ents[#ents + 1] = { "N", v } end end
				for _, v in ipairs(src[4] or EMPTY) do ents[#ents + 1] = { "N", v } end
				local d = inst and #ents > 0 and P:Nearest(ents, inst, px, py) or nil
				cands[#cands + 1] = { e = e, d = d or 1e9, kind = g.key }
			end
		end
	end
	table.sort(cands, function(a, b) return a.d < b.d end)
	local out = {}
	for i = 1, math.min(n, #cands) do out[i] = cands[i] end
	return out
end

local function BuildHome(home)
	local W2 = home:GetWidth()
	local LW = W2 - 290
	-- continue / start here
	home.cont = Card(home, LW, 58); home.cont:SetPoint("TOPLEFT", 0, -22)
	local c = home.cont
	c.icon = c:CreateTexture(nil, "ARTWORK"); c.icon:SetSize(34, 34); c.icon:SetPoint("LEFT", 12, 0)
	c.title = Text(c, P.fonts.title); c.title:SetPoint("TOPLEFT", c.icon, "TOPRIGHT", 10, -1); c.title:SetPoint("RIGHT", -130, 0)
	c.sub = Text(c, P.fonts.head); c.sub:SetPoint("TOPLEFT", c.title, "BOTTOMLEFT", 0, -4); c.sub:SetPoint("RIGHT", -130, 0)
	c.go = P:FlatButton(c, "Show guide", true); c.go:SetPoint("RIGHT", -12, 0)
	-- suggested zones, with their maps
	home.zones = {}
	local cw = math.floor((LW - 16) / 3)
	for i = 1, 3 do
		local z = Card(home, cw, 150)
		z:SetPoint("TOPLEFT", (i - 1) * (cw + 8), -108)
		z.art = CreateFrame("Frame", nil, z); z.art:SetPoint("TOPLEFT", 1, -1); z.art:SetSize(cw - 2, 92)
		z.art:SetClipsChildren(true)
		z.shade = z.art:CreateTexture(nil, "OVERLAY"); z.shade:SetPoint("BOTTOMLEFT"); z.shade:SetPoint("BOTTOMRIGHT"); z.shade:SetHeight(30)
		z.shade:SetColorTexture(0, 0, 0, 0.55)
		z.lvl = Text(z.art, P.fonts.small); z.lvl:SetPoint("BOTTOMLEFT", 8, 7)
		z.name = Text(z, P.fonts.title); z.name:SetPoint("TOPLEFT", 10, -100); z.name:SetPoint("RIGHT", -10, 0)
		z.sub = Text(z, P.fonts.head); z.sub:SetPoint("TOPLEFT", z.name, "BOTTOMLEFT", 0, -4)
		z.bar = z:CreateTexture(nil, "ARTWORK"); z.bar:SetHeight(2); z.bar:SetPoint("BOTTOMLEFT", 1, 1)
		z.go = P:FlatButton(z, "Go", true); z.go:SetPoint("BOTTOMRIGHT", -8, 8)
		home.zones[i] = z
	end
	-- new in Forever
	home.news = {}
	for i = 1, 5 do
		local r = Card(home, LW, 40)
		r:SetPoint("TOPLEFT", 0, -286 - (i - 1) * 44)
		r.face = CreateFrame("PlayerModel", nil, r); r.face:SetSize(34, 34); r.face:SetPoint("LEFT", 4, 0)
		r.icon = r:CreateTexture(nil, "ARTWORK"); r.icon:SetSize(26, 26); r.icon:SetPoint("LEFT", 8, 0)
		r.name = Text(r, P.fonts.button); r.name:SetPoint("TOPLEFT", 46, -7); r.name:SetPoint("RIGHT", -70, 0)
		r.sub = Text(r, P.fonts.head); r.sub:SetPoint("TOPLEFT", r.name, "BOTTOMLEFT", 0, -3); r.sub:SetPoint("RIGHT", -70, 0)
		r.go = P:FlatButton(r, "Go"); r.go:SetPoint("RIGHT", -8, 0)
		home.news[i] = r
	end
	-- right: pets & mounts, and shortcuts
	local RX = LW + 18
	home.coll = {}
	for i = 1, 4 do
		local r = Card(home, 272, 46)
		r:SetPoint("TOPLEFT", RX, -22 - (i - 1) * 50)
		r.icon = r:CreateTexture(nil, "ARTWORK"); r.icon:SetSize(32, 32); r.icon:SetPoint("LEFT", 8, 0)
		r.name = Text(r, P.fonts.button); r.name:SetPoint("TOPLEFT", 48, -9); r.name:SetPoint("RIGHT", -60, 0)
		r.sub = Text(r, P.fonts.head); r.sub:SetPoint("TOPLEFT", r.name, "BOTTOMLEFT", 0, -3); r.sub:SetPoint("RIGHT", -60, 0)
		r.go = P:FlatButton(r, "Get it"); r.go:SetPoint("RIGHT", -8, 0)
		home.coll[i] = r
	end
	home.quick = {}
	local qy = -236
	for i, q in ipairs({
		{ "Closest quests for me", function() P:StartRoute("next") end, "Interface\\Icons\\INV_Misc_Map_01" },
		{ "Quest this zone", function() P:LoadZoneGuide(nil) end, "Interface\\Icons\\INV_Misc_Book_09" },
		{ "Flight paths to find", function() P:LoadGuide("flights") end, "Interface\\Icons\\Ability_Mount_Gryphon_01" },
		{ "Find the nearest...", function(b) P.Find:Menu(b) end, "Interface\\Icons\\INV_Misc_Spyglass_02" },
		{ "Gear upgrades from quests", function() if CharacterFrame and not CharacterFrame:IsShown() then ToggleCharacter("PaperDollFrame") end; if P.ToggleGearFinder then P:ToggleGearFinder() end end, "Interface\\Icons\\INV_Chest_Chain_05" },
		{ "My next talents", function() if P.OpenTalents then P:OpenTalents() end end, "Interface\\Icons\\Ability_Marksmanship" },
	}) do
		local b = Card(home, 272, 34)
		b:SetPoint("TOPLEFT", RX, qy - (i - 1) * 38)
		b.icon = b:CreateTexture(nil, "ARTWORK"); b.icon:SetSize(22, 22); b.icon:SetPoint("LEFT", 8, 0); b.icon:SetTexture(q[3])
		b.icon:SetTexCoord(0.08, 0.92, 0.08, 0.92)
		b.name = Text(b, P.fonts.button); b.name:SetPoint("LEFT", b.icon, "RIGHT", 10, 0); b.name:SetText(q[1])
		b:SetScript("OnClick", function(self) q[2](self) end)
		home.quick[i] = b
	end
end

local function RenderHome()
	local home = win.home
	if not home.cont then BuildHome(home) end
	local LW = home:GetWidth() - 290
	-- continue
	local c = home.cont
	local r, s = P.route, P:Current()
	if r and s then
		c.icon:SetTexture(P.MEDIA .. "Icon")
		c.title:SetText("Continue: " .. (r.title or "your guide"))
		c.sub:SetText((P:StopLabel(s)))
		c.go:SetLabel("Show guide")
		c.go:SetScript("OnClick", function() if P.SetGuideState then P:SetGuideState("open") end; win:Hide() end)
	else
		local st = P:Suggest()
		c.icon:SetTexture("Interface\\Icons\\INV_Misc_Map_01")
		c.title:SetText("Start here")
		c.sub:SetText(st and ("Next: " .. P:StopLabel(st)) or "Pick a zone below, or search for any quest")
		c.go:SetLabel("Go")
		c.go:SetScript("OnClick", function() P:StartRoute("next"); win:Hide() end)
	end
	-- zones
	Head(home, "Continue", 2, -6)
	Head(home, "Suggested for you", 2, -92)
	local zones = C:ForYou(3)
	for i, card in ipairs(home.zones) do
		local z = zones[i]
		if z then
			local d, t, frac = C:Progress(z.quests)
			if not MapArt(card.art, z.map) then
				card.art.tiles = card.art.tiles or {}
			end
			card.lvl:SetText("Levels " .. (z.lo or "?") .. "-" .. (z.hi or "?"))
			card.name:SetText(z.name)
			card.sub:SetText(("%d%% done"):format(frac * 100))
			card.bar:SetColorTexture(A[1], A[2], A[3], 1)
			card.bar:SetWidth(math.max(1, (card:GetWidth() - 2) * frac))
			card.tip = "Open " .. z.name .. " in the journal"
			card:SetScript("OnClick", function() P:ShowZoneInJournal(z.map) end)
			card.go:SetScript("OnClick", function() P:PlayZone(z.map, P:QuestStyle()); win:Hide() end)
			local st = P:QuestStyle()
			card.go.tip = st == "fast" and "Fastest XP: only the top quests for experience, a set at a time"
				or st == "all" and "All quests here, one chain at a time" or "Storyline: the chain that fits your level, start to finish"
			card:Show()
		else
			card:Hide()
		end
	end
	-- new in Forever
	Head(home, "New in Forever", 2, -270)
	local news = NewInForever(#home.news)
	for i, row in ipairs(home.news) do
		local qid = news[i]
		local q = qid and P.Q[qid]
		if q then
			local npc = q[K.SN] and q[K.SN][1]
			if npc and row.face.SetCreature then
				row.icon:Hide(); row.face:Show(); row.face:ClearModel(); row.face:SetCreature(npc)
				if row.face.SetPortraitZoom then row.face:SetPortraitZoom(0.9) end
			else
				row.face:Hide(); row.icon:Show(); row.icon:SetTexture("Interface\\GossipFrame\\AvailableQuestIcon")
			end
			local ok = P:Available(qid)
			local _, why = C:StatusText(qid)
			row.name:SetText((ok and "|cffffffff" or "|cffb4bac2") .. q[K.NAME] .. "|r")
			row.sub:SetText(P.DIM .. P:MapName(q[K.ZONE]) .. "  ·  level " .. (q[K.LVL] or "?") .. "  ·  " .. (why or "") .. "|r")
			row.tip = q[K.TEXT]
			row:SetScript("OnClick", function() P:ShowQuestInJournal(qid) end)
			row.go:SetScript("OnClick", function() P:LoadGuide("quest:" .. qid); win:Hide() end)
			row:Show()
		else
			row:Hide()
		end
	end
	-- pets & mounts
	local cx = LW + 20
	Head(home, "Pets & mounts to get", cx, -6)
	Head(home, "Quick", cx, -220)
	local coll = ToCollect(4)
	for i, row in ipairs(home.coll) do
		local it = coll[i]
		if it then
			local id = it.e.id
			row.icon:SetTexture((C_Item and C_Item.GetItemIconByID and C_Item.GetItemIconByID(id)) or (GetItemIcon and GetItemIcon(id)))
			row.name:SetText(it.e.name)
			local yd = it.d < 1e8 and ("  ·  " .. (it.d >= 1000 and ("%.1fk yd"):format(it.d / 1000) or (math.floor(it.d) .. " yd"))) or ""
			row.sub:SetText(P.DIM .. (it.kind == "coll:mounts" and "Mount" or it.kind == "coll:pets" and "Pet" or "Curio") .. yd .. "|r")
			row:SetScript("OnClick", function() J.tab, J.group = "collect", nil; J:AutoSelect(); J.item = it.e; J:Refresh() end)
			row:SetScript("OnEnter", function(self) self:SetBackdropBorderColor(A[1], A[2], A[3], 0.9); GameTooltip:SetOwner(self, "ANCHOR_LEFT"); GameTooltip:SetItemByID(id); GameTooltip:Show() end)
			row.go:SetScript("OnClick", function() local list = P:Sources(id); if list and list[1] then P:GoGet(id, list[1]); win:Hide() end end)
			row:Show()
		else
			row:Hide()
		end
	end
end

function J:Refresh(keep)
	if not win or not win:IsShown() then return end
	for _, t in ipairs(win.tabs) do
		local on = t.key == J.tab
		t.text:SetTextColor(on and 1 or 0.6, on and 1 or 0.64, on and 1 or 0.7)
		t.bg:SetShown(on); t.line:SetShown(on)
	end
	local isHome = J.tab == "home" and not (J.search and #J.search >= 3)
	win.home:SetShown(isHome)
	win.lp:SetShown(not isHome); win.mid:SetShown(not isHome); win.right:SetShown(not isHome)
	if isHome then RenderHome(); win.find:Hide() return end
	win.left:SetItems(LeftItems(), keep)
	local items, hits = MidItems()
	J.hits = hits
	local m = win.mid
	local searching = J.search and #J.search >= 3
	local hasHero = J.group and not J.group.flights and not J.group.coll and not searching
	m.list:ClearAllPoints()
	m.list:SetPoint("TOPLEFT", 4, hasHero and -96 or -52)
	m.list:SetHeight(m:GetHeight() - (hasHero and 100 or 56))
	m.list:SetItems(items, keep)
	UpdateHeader()
	m.done.text:SetText((J.hideDone and Dot(A, 8) or Dot({ 0.35, 0.37, 0.42 }, 8)) .. " Hide done")
	m.done:SetWidth(m.done.text:GetStringWidth() + 8)
	UpdateRight()
	win.find:SetShown(J.tab == "flights")
end

local function GroupKey(g)
	if g.map and g.story then return "zone:" .. g.map end
	return g.key
end

local function Pane(parent, w)
	local p = CreateFrame("Frame", nil, parent, "BackdropTemplate")
	P.Flat(p, P.colors.PANEL)
	p:SetWidth(w)
	return p
end

local function Build()
	win = CreateFrame("Frame", "PathwayJournal", UIParent, "BackdropTemplate")
	if P.ApplySizes then P:ApplySizes() end
	P.Flat(win, nil, nil, true)
	win:SetSize(W, H)
	local pos = P.db.pos.PathwayJournal
	if pos then win:SetPoint(pos[1], UIParent, pos[2], pos[3], pos[4]) else win:SetPoint("CENTER") end
	win:SetFrameStrata("HIGH")
	win:SetMovable(true); win:EnableMouse(true); win:RegisterForDrag("LeftButton"); win:SetClampedToScreen(true)
	win:SetScript("OnDragStart", win.StartMoving)
	win:SetScript("OnDragStop", function(f)
		f:StopMovingOrSizing()
		local p, _, rp, x, y = f:GetPoint(); P.db.pos.PathwayJournal = { p, rp, x, y }
	end)
	tinsert(UISpecialFrames, "PathwayJournal")
	win:Hide()

	local title = win:CreateFontString(nil, "OVERLAY"); title:SetFontObject(P.fonts.title)
	title:SetPoint("TOPLEFT", 16, -14); title:SetText(P.TITLE .. "  " .. P.DIM .. "Journal|r")
	P:OnPaint(function() title:SetText(P.TITLE .. "  " .. P.DIM .. "Journal|r") end)
	local close = P:CloseButton(win, function() win:Hide() end); close:SetPoint("TOPRIGHT", -8, -8)

	-- search
	local sb = CreateFrame("EditBox", nil, win, "BackdropTemplate")
	P.Flat(sb, P.colors.PANEL)
	sb:SetSize(220, 22); sb:SetPoint("TOPRIGHT", -36, -10)
	sb:SetFontObject(P.fonts.button); sb:SetTextInsets(22, 6, 0, 0); sb:SetAutoFocus(false)
	sb.glass = sb:CreateTexture(nil, "OVERLAY"); sb.glass:SetSize(12, 12); sb.glass:SetPoint("LEFT", 6, 0)
	sb.glass:SetTexture("Interface\\Common\\UI-Searchbox-Icon"); sb.glass:SetVertexColor(0.7, 0.72, 0.76)
	sb.hint = sb:CreateFontString(nil, "OVERLAY"); sb.hint:SetFontObject(P.fonts.head); sb.hint:SetPoint("LEFT", 22, 0)
	sb.hint:SetText("Search every quest")
	sb:SetScript("OnTextChanged", function(s)
		local t = s:GetText()
		s.hint:SetShown(t == "")
		J.search = t
		J:Refresh()
	end)
	sb:SetScript("OnEscapePressed", function(s) s:SetText(""); s:ClearFocus() end)
	sb:SetScript("OnEnterPressed", function(s) s:ClearFocus() end)
	win.search = sb

	-- tabs: a quiet segmented row
	win.tabs = {}
	local x = 12
	for _, t in ipairs(TABS) do
		local b = CreateFrame("Button", nil, win)
		b.key = t[1]
		b.bg = b:CreateTexture(nil, "BACKGROUND"); b.bg:SetAllPoints(); b.bg:SetColorTexture(A[1], A[2], A[3], 0.18)
		b.line = b:CreateTexture(nil, "ARTWORK"); b.line:SetColorTexture(A[1], A[2], A[3], 1)
		b.line:SetPoint("BOTTOMLEFT"); b.line:SetPoint("BOTTOMRIGHT"); b.line:SetHeight(2)
		b.hl = b:CreateTexture(nil, "HIGHLIGHT"); b.hl:SetAllPoints(); b.hl:SetColorTexture(1, 1, 1, 0.05)
		b.text = b:CreateFontString(nil, "OVERLAY"); b.text:SetFontObject(P.fonts.button); b.text:SetPoint("CENTER"); b.text:SetText(t[2])
		b:SetSize(b.text:GetStringWidth() + 24, 24)
		b:SetPoint("TOPLEFT", x, -38)
		x = x + b:GetWidth() + 2
		b:SetScript("OnClick", function()
			J.tab, J.group, J.qid, J.flight, J.item = t[1], nil, nil, nil, nil
			if J.search and J.search ~= "" then sb:SetText("") end
			J:AutoSelect()
			J:Refresh()
		end)
		win.tabs[#win.tabs + 1] = b
	end

	local top, bottom = -68, 12
	local paneH = H + top - bottom

	-- left
	local lp = Pane(win, LEFT_W); lp:SetPoint("TOPLEFT", 10, top); lp:SetHeight(paneH)
	win.lp = lp
	win.home = CreateFrame("Frame", nil, win)
	win.home:SetPoint("TOPLEFT", 14, top - 2); win.home:SetSize(W - 28, paneH - 2)
	win.home:Hide()
	win.left = List(lp, LEFT_W - 6, paneH - 8, RenderLeft, function(it)
		if not it.group then return end
		J.group, J.qid, J.flight, J.item = it.group, nil, nil, nil
		if J.search and J.search ~= "" then sb:SetText("") end
		J:Refresh(true)
	end)
	win.left:SetPoint("TOPLEFT", 4, -4)
	win.left.onEnter = function(row, it)
		if not it.group or it.group.flights then return end
		local g = it.group
		local d, t = C:Progress(g.quests)
		GameTooltip:SetOwner(row, "ANCHOR_RIGHT")
		GameTooltip:AddLine(g.name, 1, 1, 1)
		if g.lo > 0 then GameTooltip:AddLine("Levels " .. Range(g), 0.7, 0.75, 0.8) end
		GameTooltip:AddLine(("%d of %d quests done"):format(d, t), 0.7, 0.75, 0.8)
		if g.chains and #g.chains > 0 then GameTooltip:AddLine(("%d story chains"):format(#g.chains), 0.7, 0.75, 0.8) end
		GameTooltip:Show()
	end

	-- middle: a header with the place's progress and its guides, then the list
	local mp = Pane(win, MID_W); mp:SetPoint("TOPLEFT", lp, "TOPRIGHT", 6, 0); mp:SetHeight(paneH)
	win.mid = mp
	mp.title = mp:CreateFontString(nil, "OVERLAY"); mp.title:SetFontObject(P.fonts.big); mp.title:SetPoint("TOPLEFT", 10, -10)
	mp.title:SetPoint("RIGHT", -70, 0); mp.title:SetJustifyH("LEFT"); mp.title:SetWordWrap(false)
	mp.sub = mp:CreateFontString(nil, "OVERLAY"); mp.sub:SetFontObject(P.fonts.head); mp.sub:SetPoint("TOPLEFT", 10, -30)
	-- progress meter
	local meter = CreateFrame("Frame", nil, mp)
	meter:SetPoint("TOPLEFT", 10, -46); meter:SetPoint("RIGHT", -46, 0); meter:SetHeight(6)
	meter.bg = meter:CreateTexture(nil, "BACKGROUND"); meter.bg:SetAllPoints(); meter.bg:SetColorTexture(1, 1, 1, 0.08)
	meter.fill = meter:CreateTexture(nil, "ARTWORK"); meter.fill:SetPoint("TOPLEFT"); meter.fill:SetPoint("BOTTOMLEFT")
	meter.fill:SetTexture(WHITE); meter.fill:SetVertexColor(A[1], A[2], A[3], 1)
	meter.text = mp:CreateFontString(nil, "OVERLAY"); meter.text:SetFontObject(P.fonts.button)
	meter.text:SetPoint("LEFT", meter, "RIGHT", 8, 0)
	meter:SetScript("OnShow", function() meter.text:Show() end)
	meter:SetScript("OnHide", function() meter.text:Hide() end)
	mp.meter = meter
	-- three ways to quest a zone: its story, every quest, or the fastest experience
	mp.story = P:FlatButton(mp, "Storyline", true); mp.story:SetPoint("TOPLEFT", 10, -64)
	mp.story.tip = "Only the story chain that fits your level best, start to finish. Then the next best one."
	mp.story:SetScript("OnClick", function() if J.group then P:PlayZone(J.group.map, "story"); win:Hide() end end)
	mp.all = P:FlatButton(mp, "All quests")
	mp.all.tip = "Every quest here, one chain at a time: a chain is finished before the next starts."
	mp.all:SetScript("OnClick", function()
		local g = J.group
		if not g then return end
		if g.map then P:PlayZone(g.map, "all") else P:LoadGuide(GroupKey(g)) end
		win:Hide()
	end)
	mp.fast = P:FlatButton(mp, "Fastest XP")
	mp.fast.tip = "Only the quickest experience: the top 25% by XP a minute, each quest timed from what it asks and your own pace. Finish that set without picking up anything else, then on to wherever the next set gives the most XP per minute, trip included, on either continent."
	mp.fast:SetScript("OnClick", function() if J.group then P:PlayZone(J.group.map, "fast"); win:Hide() end end)
	-- hide done: a quiet toggle in the corner
	local hd = CreateFrame("Button", nil, mp)
	hd:SetHeight(18); hd:SetPoint("TOPRIGHT", -8, -10)
	hd.text = hd:CreateFontString(nil, "OVERLAY"); hd.text:SetFontObject(P.fonts.head); hd.text:SetPoint("RIGHT")
	hd:SetScript("OnClick", function() J.hideDone = not J.hideDone; J:Refresh(true) end)
	mp.done = hd
	mp.list = List(mp, MID_W - 8, paneH - 100, RenderMid, function(it, btn)
		if it.chain then
			if btn == "RightButton" then P:LoadGuide("chain:" .. it.chain.id) return end
			J.open[it.chain] = not J.open[it.chain]
		elseif it.qid then
			J.qid, J.flight, J.item = it.qid, nil, nil
		elseif it.flight then
			J.flight, J.qid, J.item = it.flight, nil, nil
		elseif it.coll then
			J.item, J.qid, J.flight = it.coll, nil, nil
		end
		J:Refresh(true)
	end)
	mp.list.onEnter = function(row, it)
		if it.coll then
			GameTooltip:SetOwner(row, "ANCHOR_RIGHT")
			GameTooltip:SetItemByID(it.coll.id)
			GameTooltip:Show()
		elseif it.chain then
			local d, t = C:Progress(it.chain.quests)
			GameTooltip:SetOwner(row, "ANCHOR_RIGHT")
			GameTooltip:AddLine(it.chain.name, 1, 1, 1)
			GameTooltip:AddLine(("%d quests  ·  %d done  ·  levels %d–%d"):format(t, d, it.chain.lo, it.chain.hi), 0.7, 0.75, 0.8)
			GameTooltip:AddLine("Click to open  ·  right-click to follow it", 0.5, 0.55, 0.6)
			GameTooltip:Show()
		elseif it.qid then
			local st = P:QuestStatus(it.qid)
			GameTooltip:SetOwner(row, "ANCHOR_RIGHT")
			GameTooltip:AddLine(P.Q[it.qid][K.NAME], 1, 1, 1)
			local _, why = C:StatusText(it.qid)
			local c = (STATUS[st] or STATUS.locked)[1]
			GameTooltip:AddLine(why, c[1], c[2], c[3])
			GameTooltip:Show()
		end
	end

	-- right: the quest
	local rw = W - LEFT_W - MID_W - 32
	local rp = Pane(win, rw); rp:SetPoint("TOPLEFT", mp, "TOPRIGHT", 6, 0); rp:SetHeight(paneH)
	win.right = rp
	local holder = CreateFrame("Frame", nil, rp, "BackdropTemplate")
	holder:SetSize(76, 76); holder:SetPoint("TOPRIGHT", -8, -8)
	P.Flat(holder, { 0, 0, 0, 0.25 })
	local model = CreateFrame("PlayerModel", nil, holder)
	model:SetPoint("TOPLEFT", 1, -1); model:SetPoint("BOTTOMRIGHT", -1, 1)
	hooksecurefunc(model, "Show", function() holder:Show() end)
	hooksecurefunc(model, "Hide", function() holder:Hide() end)
	rp.model = model
	win.model = model
	rp.title = rp:CreateFontString(nil, "OVERLAY"); rp.title:SetFontObject(P.fonts.big)
	rp.title:SetPoint("TOPLEFT", 12, -12)
	rp.title:SetJustifyH("LEFT"); rp.title:SetJustifyV("TOP"); rp.title:SetHeight(40); rp.title:SetWordWrap(true)
	local scroll = CreateFrame("ScrollFrame", nil, rp)
	scroll:SetPoint("TOPLEFT", 12, -90); scroll:SetPoint("BOTTOMRIGHT", -12, 40)
	local content = CreateFrame("Frame", nil, scroll)
	content:SetSize(rw - 24, 10)
	scroll:SetScrollChild(content)
	scroll:EnableMouseWheel(true)
	scroll:SetScript("OnMouseWheel", function(s, d)
		local maxS = max(0, rp.body:GetStringHeight() - s:GetHeight())
		s:SetVerticalScroll(max(0, min(maxS, s:GetVerticalScroll() - d * 30)))
	end)
	rp.scroll = scroll
	rp.body = content:CreateFontString(nil, "OVERLAY"); rp.body:SetFontObject(P.fonts.button)
	rp.body:SetPoint("TOPLEFT"); rp.body:SetWidth(rw - 24)
	rp.body:SetJustifyH("LEFT"); rp.body:SetJustifyV("TOP"); rp.body:SetSpacing(3)
	local sep = rp:CreateTexture(nil, "ARTWORK"); sep:SetColorTexture(1, 1, 1, 0.06); sep:SetHeight(1)
	sep:SetPoint("BOTTOMLEFT", 10, 34); sep:SetPoint("BOTTOMRIGHT", -10, 34)
	rp.go = P:FlatButton(rp, "Go", true); rp.go:SetPoint("BOTTOMLEFT", 12, 9)
	rp.go.tip = "The arrow takes you through this quest, start to finish."
	rp.go:SetScript("OnClick", function()
		if J.item then
			local list = P:Sources(J.item.id)
			if list and list[1] then P:GoGet(J.item.id, list[1]) end
		elseif J.flight then
			local fp = J.flight
			P:StartRoute("next", { single = { key = "fm" .. fp.id, flight = fp.id, ents = { { "N", fp.id } }, name = fp.name,
				point = { fp.map, fp.x, fp.y } }, title = "Flight path" })
		elseif J.qid then
			P:LoadGuide("quest:" .. J.qid)
		end
	end)
	rp.chain = P:FlatButton(rp, "Follow the chain"); rp.chain:SetPoint("LEFT", rp.go, "RIGHT", 6, 0)
	rp.chain.tip = "Every quest in this chain, in order."
	rp.chain:SetScript("OnClick", function()
		local ch = J.qid and C.chainOf[J.qid]
		if ch then P:LoadGuide("chain:" .. ch.id) end
	end)
	rp.map = P:FlatButton(rp, "Show on map"); rp.map:SetPoint("BOTTOMLEFT", 12, 9)
	rp.map:SetScript("OnClick", function()
		local fp = J.flight
		if fp and WorldMapFrame and WorldMapFrame.SetMapID then ShowUIPanel(WorldMapFrame); WorldMapFrame:SetMapID(fp.map) end
	end)

	win.find = P:FlatButton(win, "Find new ones", true)
	win.find:SetPoint("RIGHT", sb, "LEFT", -8, 0)
	win.find.tip = "A route through the flight paths you haven't discovered on this continent"
	win.find:SetScript("OnClick", function() P:LoadGuide("flights") end)

	win:SetScript("OnShow", function() J:Refresh() end)
end

-- open on the zone you're in (or the best one for you)
function J:AutoSelect()
	C:Build()
	if J.tab == "zones" then
		J.group = C.zones[P:PlayerZone() or 0] or C:ForYou(1)[1] or C.zoneList[1]
	elseif J.tab == "class" then
		J.group = C.class
	elseif J.tab == "dungeons" then
		J.group = C.dungeonList[1]
	elseif J.tab == "forever" then
		J.group = C.foreverList[1]
	elseif J.tab == "profs" then
		J.group = C.profList[1]
	elseif J.tab == "collect" then
		J.group = CollGroups()[1]
	end
end

function P:ToggleJournal(tab)
	if not win then Build() end
	if win:IsShown() and not tab then win:Hide() return end
	if tab then J.tab, J.group, J.qid, J.flight, J.item = tab, nil, nil, nil, nil end
	if not J.group then J:AutoSelect() end
	win:Show()
	J:Refresh()
	if P.db.setupDone and P.Tip then
		P:Tip("journal", win, "The journal", "For you: what suits you right now, with one click to start.\n\nZones, dungeons, class and professions hold every guide. Search finds any quest by name.", "TOP")
	end
end

function P:ShowZoneInJournal(map)
	if not win then Build() end
	C:Build()
	J.tab, J.qid, J.flight, J.item = "zones", nil, nil, nil
	J.group = C.zones[map or 0] or C.zones[P:PlayerZone() or 0] or J.group
	if not J.group then J:AutoSelect() end
	if J.search and J.search ~= "" then win.search:SetText("") end
	win:Show()
	J:Refresh()
end

function P:ShowQuestInJournal(qid)
	if not win then Build() end
	C:Build()
	local q = P.Q[qid]
	if not q then return end
	J.tab = "zones"
	J.group = C.zones[q[K.ZONE] or 0] or J.group
	J.qid, J.flight, J.item = qid, nil, nil
	local ch = C.chainOf[qid]
	if ch then J.open[ch] = true end
	win:Show()
	J:Refresh()
end

local function Live() if win and win:IsShown() then J:Refresh(true) end end
P:Listen("QUESTS_CHANGED", Live)
P:Listen("QUEST_PROGRESS", Live)
P:Listen("FLIGHTS_CHANGED", Live)
P:OnPaint(Live)
end part() end
-- ==================== Outfits.lua
do local __addon, __ns = ... local function part()
-- Copyright (C) 2026 SoFinSicc. Part of Pathway (curseforge.com/wow/addons/pathway): free software under the GPLv3 or later, with additional terms that require keeping this credit. See LICENSE.md.
--[[ Pathway — Your outfits, one click away
     With transmog outfits saved, a button on the minimap bar lists them: click
     one to wear it, anywhere (the game's own /outfit, so it's free and works
     away from a Transmogrifier). No outfits saved, no button. Settings or the
     parts menu turns it off. ]]

local ADDON, P = __addon, __ns
local A = P.ACCENT

local function S() return P.db.settings end
local T = function() return C_TransmogOutfitInfo end

-- your saved outfits, in the order the Transmogrifier shows them (that order
-- is the number /outfit takes)
local cache, cacheT = nil, -100
function P:Outfits(fresh)
	if not fresh and cache and GetTime() - cacheT < 5 then return cache end
	local list = {}
	local api = T()
	if api then
		local function add(i, info)
			if type(info) ~= "table" then return end
			local name = info.name
			if issecretvalue and issecretvalue(name) then name = nil end
			list[#list + 1] = { index = i, id = info.outfitID, name = (name and name ~= "") and name or ("Outfit " .. i), icon = info.icon }
		end
		if api.GetOutfitInfoByPlayerFacingIndex then
			for i = 1, 60 do
				local ok, info = pcall(api.GetOutfitInfoByPlayerFacingIndex, i)
				if not ok or not info then break end
				add(i, info)
			end
		end
		if #list == 0 and api.GetOutfitsInfo then
			local ok, all = pcall(api.GetOutfitsInfo)
			if ok and type(all) == "table" then for i, info in ipairs(all) do add(i, info) end end
		end
	end
	cache, cacheT = list, GetTime()
	return list
end
function P:HasOutfits() return #self:Outfits() > 0 end

local function ActiveID()
	local api = T()
	if not (api and api.GetActiveOutfitID) then return end
	local ok, id = pcall(api.GetActiveOutfitID)
	if ok and not (issecretvalue and issecretvalue(id)) then return id end
end

---------------------------------------------------------------------------
-- The list: one row per outfit. Each row is the game's own secure button
-- running "/outfit !N" (the ! keeps it on instead of toggling it off), so
-- it's built and moved only out of combat.
---------------------------------------------------------------------------
local panel
local rows = {}
local ROW = 26

local function Row(i)
	local r = rows[i]
	if r then return r end
	r = CreateFrame("Button", "PathwayOutfitRow" .. i, panel, "SecureActionButtonTemplate,BackdropTemplate")
	r:SetHeight(ROW)
	r:RegisterForClicks("AnyUp", "AnyDown")
	r:SetAttribute("type", "macro")
	r.icon = r:CreateTexture(nil, "ARTWORK"); r.icon:SetSize(20, 20); r.icon:SetPoint("LEFT", 4, 0)
	r.icon:SetTexCoord(0.08, 0.92, 0.08, 0.92)
	r.text = r:CreateFontString(nil, "OVERLAY"); r.text:SetFontObject(P.fonts.button)
	r.text:SetPoint("LEFT", r.icon, "RIGHT", 8, 0); r.text:SetPoint("RIGHT", -24, 0); r.text:SetJustifyH("LEFT")
	r.on = r:CreateTexture(nil, "OVERLAY"); r.on:SetTexture(P.MEDIA .. "Dot"); r.on:SetSize(8, 8); r.on:SetPoint("RIGHT", -8, 0)
	r.hi = r:CreateTexture(nil, "HIGHLIGHT"); r.hi:SetAllPoints(); r.hi:SetColorTexture(1, 1, 1, 0.06)
	r:HookScript("OnClick", function() C_Timer.After(0.3, function() if panel and panel:IsShown() then P:FillOutfits() end end) end)
	rows[i] = r
	return r
end

function P:FillOutfits()
	if not panel or InCombatLockdown() then return end
	local list = self:Outfits(true)
	local active = ActiveID()
	local w = 220
	for i, o in ipairs(list) do
		local r = Row(i)
		r:ClearAllPoints()
		r:SetPoint("TOPLEFT", 6, -30 - (i - 1) * (ROW + 2)); r:SetPoint("RIGHT", -6, 0)
		r:SetAttribute("macrotext", "/outfit !" .. o.index)
		r.icon:SetTexture(o.icon or 134400)
		r.text:SetText(o.name)
		r.on:SetShown(active ~= nil and o.id == active)
		r.on:SetVertexColor(A[1], A[2], A[3], 1)
		r:Show()
		w = math.max(w, r.text:GetStringWidth() + 70)
	end
	for i = #list + 1, #rows do rows[i]:Hide() end
	panel.empty:SetShown(#list == 0)
	panel:SetSize(math.min(w, 340), 38 + math.max(1, #list) * (ROW + 2))
end

local function Build()
	panel = CreateFrame("Frame", "PathwayOutfits", UIParent, "BackdropTemplate")
	P.Flat(panel, nil, nil, true)
	panel:SetFrameStrata("DIALOG")
	panel:SetClampedToScreen(true)
	panel:EnableMouse(true)
	panel.title = panel:CreateFontString(nil, "OVERLAY"); panel.title:SetFontObject(P.fonts.title)
	panel.title:SetPoint("TOPLEFT", 12, -10); panel.title:SetText("Outfits")
	panel.close = P:CloseButton(panel, function() if not InCombatLockdown() then panel:Hide() end end)
	panel.close:SetPoint("TOPRIGHT", -4, -4)
	panel.empty = panel:CreateFontString(nil, "OVERLAY"); panel.empty:SetFontObject(P.fonts.button)
	panel.empty:SetPoint("TOPLEFT", 14, -36); panel.empty:SetText(P.DIM .. "No outfits saved yet.|r")
	-- close when you click anywhere else (never in combat: the rows are secure)
	panel:SetScript("OnShow", function() panel:RegisterEvent("GLOBAL_MOUSE_DOWN") end)
	panel:SetScript("OnHide", function() panel:UnregisterEvent("GLOBAL_MOUSE_DOWN") end)
	panel:SetScript("OnEvent", function()
		if InCombatLockdown() then return end
		local owner = _G.PathwayMinimapOutfits
		if not (panel:IsMouseOver() or (owner and owner:IsMouseOver())) then panel:Hide() end
	end)
	panel:Hide()
	if P.ApplySizes then P:ApplySizes() end
end

function P:ToggleOutfits(owner)
	if InCombatLockdown() then self:Toast("Outfits: after this fight") return end
	if not panel then Build() end
	if panel:IsShown() then panel:Hide() return end
	panel:ClearAllPoints()
	if owner then
		local _, y = owner:GetCenter()
		local up = y and y < UIParent:GetHeight() / 2
		panel:SetPoint(up and "BOTTOMRIGHT" or "TOPRIGHT", owner, up and "TOPRIGHT" or "BOTTOMRIGHT", 0, up and 4 or -4)
	else
		panel:SetPoint("TOPRIGHT", UIParent, "TOPRIGHT", -20, -240)
	end
	self:FillOutfits()
	panel:Show()
end

-- outfits saved or changed: the button comes and goes with them
local function Changed()
	cache = nil
	if P.UpdateMinimapButtons then P:UpdateMinimapButtons() end
	if panel and panel:IsShown() then P:FillOutfits() end
end
for _, ev in ipairs({ "TRANSMOG_OUTFITS_CHANGED", "TRANSMOGRIFY_CLOSE", "TRANSMOG_DISPLAYED_OUTFIT_CHANGED", "VIEWED_TRANSMOG_OUTFIT_CHANGED" }) do
	P:On(ev, function() if not InCombatLockdown() then C_Timer.After(0.5, Changed) end end)
end
P:On("PLAYER_REGEN_ENABLED", function() if cache == nil then Changed() end end)
P:On("PLAYER_REGEN_DISABLED", function() if panel and panel:IsShown() then panel:Hide() end end)
P:Listen("READY", function() C_Timer.After(3, Changed) end)
end part() end
-- ==================== GoTo.lua
do local __addon, __ns = ... local function part()
-- Copyright (C) 2026 SoFinSicc. Part of Pathway (curseforge.com/wow/addons/pathway): free software under the GPLv3 or later, with additional terms that require keeping this credit. See LICENSE.md.
--[[ Pathway — Go anywhere
     The globe button on the minimap bar (or /pw go): type a zone, click it, and
     Pathway takes you there the fastest way it can find from where you stand.
     It weighs everything: running or riding by the real roads and passes, the
     flight paths you know, boats, zeppelins, the tram and the Feathermoon
     ferry, your hearthstone, mage and druid teleports, Astral Recall and the
     engineering transporters (Gadgetzan, Everlook) when they're ready. You see
     the whole way before you go, leg by leg, and each leg becomes a step in
     your guide; the guide you were on picks up again when you arrive. ]]

local ADDON, P = __addon, __ns
local A = P.ACCENT
local floor, max, min = math.floor, math.max, math.min

local function S() return P.db.settings end

---------------------------------------------------------------------------
-- Places you can go: every zone and city with a map Pathway can place, and
-- every town: each one with a flight master (named by the game's own flight
-- list where it gives one, else below), plus the inn towns without one.
---------------------------------------------------------------------------
-- flight master -> the town they stand in
local FM_TOWN = {
	[523] = "Sentinel Hill", [931] = "Lakeshire", [1387] = "Grom'gol Base Camp", [1571] = "Menethil Harbor",
	[1572] = "Thelsamar", [2226] = "The Sepulcher", [2299] = "Morgan's Vigil", [2389] = "Tarren Mill",
	[2409] = "Darkshire", [2432] = "Southshore", [2835] = "Refuge Pointe", [2851] = "Hammerfall",
	[2858] = "Booty Bay", [2859] = "Booty Bay", [2861] = "Kargath", [2941] = "Thorium Point", [3305] = "Thorium Point",
	[3615] = "The Crossroads", [3838] = "Rut'theran Village", [3841] = "Auberdine", [4267] = "Astranaar",
	[4312] = "Sun Rock Retreat", [4314] = "Revantusk Village", [4317] = "Freewind Post", [4319] = "Thalanaar",
	[4321] = "Theramore Isle", [4407] = "Stonetalon Peak", [6026] = "Stonard", [6706] = "Nijel's Point",
	[6726] = "Shadowprey Village", [7823] = "Gadgetzan", [7824] = "Gadgetzan", [8018] = "Aerie Peak",
	[8019] = "Feathermoon Stronghold", [8020] = "Camp Mojache", [8609] = "Nethergarde Keep", [8610] = "Valormok",
	[10378] = "Camp Taurajo", [10583] = "Marshal's Refuge", [10897] = "Nighthaven", [11798] = "Nighthaven",
	[11800] = "Nighthaven", [12740] = "Nighthaven", [11138] = "Everlook", [11139] = "Everlook",
	[11899] = "Brackenwall Village", [11900] = "Bloodvenom Post", [11901] = "Zoram'gar Outpost",
	[12577] = "Talrendis Point", [12578] = "Talonbranch Glade", [12596] = "Chillwind Camp", [12616] = "Splintertree Post",
	[12617] = "Light's Hope Chapel", [12636] = "Light's Hope Chapel", [13177] = "Flame Crest",
	[15177] = "Cenarion Hold", [15178] = "Cenarion Hold", [16227] = "Ratchet",
}
-- towns with an inn but no flight master: the inn in that zone
local INN_TOWN = { [1429] = "Goldshire", [1426] = "Kharanos", [1420] = "Brill", [1411] = "Razor Hill",
	[1412] = "Bloodhoof Village", [1438] = "Dolanaar" }

local places
local function MyLetter() return (P.me and P.me.faction == "Horde") and "H" or "A" end
local function Places()
	if places then return places end
	places = {}
	local seen = {}
	-- a town: the spot to head for, and the zone it's in
	local towns = {}
	local function town(name, map, x, y, fac)
		if not (name and map and x) or name == "" then return end
		local key = name:lower()
		local mine = fac and fac:find(MyLetter(), 1, true) ~= nil
		local had = towns[key]
		if had and (had.mine or not mine) then return end
		local zone = P:MapName(P:ZoneOf(map) or map)
		local p = { name = name, low = key, map = P:ZoneOf(map) or map, point = { map, x, y }, zone = zone, mine = mine,
			hostile = fac and not mine, town = true }
		if had then for k, v in pairs(p) do had[k] = v end else towns[key] = p end
	end
	for id, row in pairs(P.FM or {}) do
		local x, y = P.Unpack(row[3])
		town(FM_TOWN[id], row[2], x, y, row[4])
	end
	for _, row in pairs(P.SV or {}) do
		if row[3] and bit.band(row[3], 128) ~= 0 then
			local pts = row[4]
			for i = 1, #pts, 2 do
				local name = INN_TOWN[pts[i]]
				if name then local x, y = P.Unpack(pts[i + 1]); town(name, pts[i], x, y, row[5]) end
			end
		end
	end
	-- the game's own flight list: its names ("Gadgetzan, Tanaris"), for towns not named above
	if C_TaxiMap and C_TaxiMap.GetTaxiNodesForMap then
		for _, cont in ipairs({ 1414, 1415 }) do
			local ok, nodes = pcall(C_TaxiMap.GetTaxiNodesForMap, cont)
			for _, n in ipairs(ok and type(nodes) == "table" and nodes or {}) do
				local name = type(n.name) == "string" and n.name:match("^([^,]+)")
				if name and n.position and not towns[name:lower()] then
					local inst, wx, wy = P:WorldPos(cont, n.position.x, n.position.y)
					if inst then
						-- the zone it's in: the flight master standing there
						local best, bd
						for _, row in pairs(P.FM or {}) do
							local fx, fy = P.Unpack(row[3])
							local i2, x2, y2 = P:WorldPos(row[2], fx, fy)
							if i2 == inst then
								local d = (x2 - wx) ^ 2 + (y2 - wy) ^ 2
								if not bd or d < bd then best, bd = row, d end
							end
						end
						if best and bd < 150 * 150 then
							local fx, fy = P.Unpack(best[3])
							town(name, best[2], fx, fy, best[4])
						end
					end
				end
			end
		end
	end
	for _, p in pairs(towns) do places[#places + 1] = p end
	local function add(map)
		if seen[map] or not P:MapXform(map) then return end
		local info = C_Map.GetMapInfo and C_Map.GetMapInfo(map)
		if info and info.mapType and info.mapType ~= 3 then return end
		local name = P:MapName(map)
		if not name or name == "" then return end
		seen[map] = true
		local z = P.Cat and P.Cat.zones and P.Cat.zones[map]
		-- a city and its flight master's town can share a name: the city wins
		for i = #places, 1, -1 do if places[i].town and places[i].low == name:lower() then table.remove(places, i) end end
		places[#places + 1] = { map = map, name = name, lo = z and z.lo, hi = z and z.hi, low = name:lower() }
	end
	if P.Cat and P.Cat.Build then P.Cat:Build() end
	for map = 1411, 1460 do add(map) end
	for map in pairs(P.Cat and P.Cat.zones or {}) do add(map) end
	table.sort(places, function(a, b) return a.name < b.name end)
	return places
end

function P.ResetPlaces() places = nil end

-- The town you're in, if any. The game's own area comes first (the subzone
-- named after the town: "Menethil Harbor", "Goldshire"); where its name doesn't
-- match, or you're on its outskirts, Pathway's own area for it counts: a circle
-- round the town's flight master or inn. Pathway learns each town's real size
-- as you walk it: every step inside the game's area for the town widens that
-- town's circle to fit (saved, so it only has to be learned once). Leaving takes
-- a little more than entering, so it doesn't flicker at the edge.
local TOWN_IN, EDGE, LEAVE, MOST = 170, 25, 40, 700
local townPts
local function Learned()
	local l = P.db and P.db.learned
	if not l then return {} end
	l.towns = l.towns or {}
	return l.towns
end
function P:TownRadius(name)
	local r = Learned()[name]
	return r and math.max(80, r) or TOWN_IN
end
local function TownPts()
	if not townPts then
		townPts = {}
		for _, p in ipairs(Places()) do
			if p.town and p.point then
				local i, x, y = P:WorldPos(p.point[1], p.point[2], p.point[3])
				if i then townPts[#townPts + 1] = { p = p, inst = i, x = x, y = y } end
			end
		end
	end
	return townPts
end
-- the town or city a spot is in ("stormwind", "goldshire"), or nil out in the wild
local CITY = { [1453] = true, [1454] = true, [1455] = true, [1456] = true, [1457] = true, [1458] = true }
function P:TownAt(map, inst, x, y)
	if map and CITY[map] then return "city" .. map end
	if not inst then return end
	for _, t in ipairs(TownPts()) do
		if t.inst == inst then
			local r = self:TownRadius(t.p.low)
			if (t.x - x) ^ 2 + (t.y - y) ^ 2 <= r * r then return t.p.low end
		end
	end
end
function P:TownHere(wasIn)
	local sub = GetSubZoneText and GetSubZoneText()
	sub = sub and sub ~= "" and sub:lower()
	TownPts()
	local inst, px, py = self:PlayerPos()
	if sub then
		for _, t in ipairs(townPts) do
			if t.p.low == sub then
				-- inside the game's own area: learn how far out it reaches
				if inst and t.inst == inst then
					local d = math.sqrt((t.x - px) ^ 2 + (t.y - py) ^ 2) + EDGE
					local L = Learned()
					if d <= MOST and d > (L[t.p.low] or 0) + 5 then L[t.p.low] = math.floor(d) end
				end
				return t.p
			end
		end
	end
	if not inst then return end
	for _, t in ipairs(townPts) do
		if t.inst == inst then
			local r = self:TownRadius(t.p.low) + (wasIn and LEAVE or 0)
			if (t.x - px) ^ 2 + (t.y - py) ^ 2 <= r * r then return t.p end
		end
	end
end

local function Friendly(fac)
	local me = (P.me and P.me.faction == "Horde") and "H" or "A"
	return fac and fac:find(me, 1, true) ~= nil
end

-- where in a zone to head for: a flight master you know there, else any of
-- your side's, else an inn, else the middle of the map
function P:ZoneDoor(map)
	local best, rank
	for id, row in pairs(P.FM or {}) do
		if row[2] == map and Friendly(row[4]) then
			local r = (self.cdb.flights and self.cdb.flights[id]) and 1 or 2
			if not rank or r < rank then
				local x, y = P.Unpack(row[3])
				best, rank = { map, x, y, row[1] }, r
			end
		end
	end
	if best then return best end
	for _, row in pairs(P.SV or {}) do
		if row[3] and bit.band(row[3], 128) ~= 0 and Friendly(row[5]) then
			local pts = row[4]
			for i = 1, #pts, 2 do
				if pts[i] == map then
					local x, y = P.Unpack(pts[i + 1])
					return { map, x, y, row[1] }
				end
			end
		end
	end
	return { map, 0.5, 0.5 }
end

local function Time(secs)
	secs = max(0, secs or 0)
	if secs < 60 then return ("%d s"):format(max(5, floor(secs / 5 + 0.5) * 5)) end
	return ("%d min"):format(floor(secs / 60 + 0.5))
end

-- the whole way to a zone or a town: legs, seconds, seconds on foot (nil when you're there)
local function Door(self, p)
	if type(p) == "table" and p.point then return { p.point[1], p.point[2], p.point[3], p.name } end
	return self:ZoneDoor(type(p) == "table" and p.map or p)
end
local function Here(self, p)
	if type(p) == "table" and p.point then
		local inst, px, py = self:PlayerPos()
		local i2, wx, wy = self:WorldPos(p.point[1], p.point[2], p.point[3])
		return inst and i2 == inst and (wx - px) ^ 2 + (wy - py) ^ 2 < 120 * 120
	end
	return self:PlayerZone() == (type(p) == "table" and p.map or p)
end
function P:WayTo(map)
	local door = Door(self, map)
	if type(map) == "table" then map = map.map end
	local inst, wx, wy = self:WorldPos(door[1], door[2], door[3])
	if not inst then return end
	local legs, total, walk = self:PlanWay({ map = door[1], x = door[2], y = door[3], wx = wx, wy = wy, inst = inst, name = self:MapName(map) })
	return legs, total, walk, door
end

function P:GoToZone(map)
	if not map then return false end
	local place = type(map) == "table" and map or nil
	if place then map = place.map end
	local name = place and place.name or self:MapName(map)
	if Here(self, place or map) then self:Toast("You're in " .. name) return false end
	local door = Door(self, place or map)
	local legs, total, walk = self:WayTo(place or map)
	local way
	if legs and #legs > 0 then
		local parts = {}
		for _, l in ipairs(legs) do parts[#parts + 1] = l.text end
		way = table.concat(parts, ", then ") .. "."
	end
	local stop = { key = "goto" .. (place and place.low or map), goal = "Go to " .. name, name = door[4] or name, point = { door[1], door[2], door[3] },
		far = true, inZone = not place and map or nil, reach = place and 60 or 40, way = way }
	local ok = self:StartRoute("next", { single = stop, title = "To " .. name, quiet = true })
	if ok then
		if self.GuideState and self:GuideState() ~= "open" and S().guideWindow ~= false then self:SetGuideState("open") end
		local msg = "To " .. name
		if total then msg = msg .. ": about " .. Time(total) end
		if walk and total and walk < 1e8 and walk - total > 60 then msg = msg .. (" (saves %s)"):format(Time(walk - total)) end
		self:Toast(msg)
	else
		self:Toast("Pathway can't find a way to " .. name .. " from here")
	end
	return ok
end

-- "/pw go west" -> Westfall, "/pw go gadget" -> Gadgetzan (a town: the place itself)
function P:FindZone(text)
	text = (text or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
	if text == "" then return end
	local starts, has
	for _, p in ipairs(Places()) do
		if p.low == text then return p.town and p or p.map end
		if not starts and p.low:sub(1, #text) == text then starts = p.town and p or p.map end
		if not has and p.low:find(text, 1, true) then has = p.town and p or p.map end
	end
	return starts or has
end

---------------------------------------------------------------------------
-- The window: search, pick, see the way
---------------------------------------------------------------------------
local win
local ROWS, ROW = 9, 22
local picked

local function Matches(q)
	q = (q or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
	local out = {}
	if q == "" then
		-- for your level first, then your side's cities
		local seen = {}
		for _, z in ipairs(P.Cat and P.Cat.ForYou and P.Cat:ForYou(5) or {}) do
			for _, p in ipairs(Places()) do if p.map == z.map and not p.town and not seen[p] then seen[p] = true; out[#out + 1] = p end end
		end
		local caps = (P.me and P.me.faction == "Horde") and { 1454, 1456, 1458 } or { 1453, 1455, 1457 }
		for _, m in ipairs(caps) do
			for _, p in ipairs(Places()) do if p.map == m and not p.town and not seen[p] then seen[p] = true; out[#out + 1] = p end end
		end
		return out, true
	end
	local a, b = {}, {}
	for _, p in ipairs(Places()) do
		if p.low:sub(1, #q) == q then a[#a + 1] = p elseif p.low:find(q, 1, true) then b[#b + 1] = p end
	end
	for _, p in ipairs(b) do a[#a + 1] = p end
	return a
end

local function ShowWay(p)
	picked = p
	local legs, total, walk = P:WayTo(p.town and p or p.map)
	local lines = {}
	if Here(P, p.town and p or p.map) then
		lines[1] = P.DIM .. "You're here.|r"
	elseif not legs then
		lines[1] = P.DIM .. "No way there that Pathway knows from here.|r"
	elseif #legs == 0 then
		lines[1] = "Run there: about " .. Time(total)
	else
		for i, l in ipairs(legs) do
			lines[#lines + 1] = ("|c%s%d|r  %s  %s%s|r"):format(P.ACCENT_HEX, i, l.text, P.DIM, Time(l.secs))
		end
		local foot = (walk and walk < 1e8) and ("   running: " .. Time(walk)) or "   (the only way from here)"
		lines[#lines + 1] = "|cffffffffAbout " .. Time(total) .. "|r" .. P.DIM .. foot .. "|r"
	end
	win.way:SetText(table.concat(lines, "\n"))
	win.go:SetShown(not Here(P, p.town and p or p.map) and legs ~= nil)
	win.go:SetLabel("Go to " .. p.name)
	win:SetHeight(64 + ROWS * ROW + 18 + max(1, #lines) * 15 + (win.go:IsShown() and 30 or 4))
end

local function Fill()
	local list, suggested = Matches(win.search:GetText())
	win.head:SetText(suggested and (P.DIM .. "For your level, and your cities|r") or "")
	for i = 1, ROWS do
		local r, p = win.rows[i], list[i]
		if p then
			r.p = p
			r.text:SetText(p.name)
			if p.town then
				r.sub:SetText(P.DIM .. (p.zone or "") .. (p.hostile and ((P.me and P.me.faction == "Horde") and "  ·  Alliance" or "  ·  Horde") or "") .. "|r")
			else
				r.sub:SetText(p.lo and p.lo > 0 and (P.DIM .. (p.lo == p.hi and p.lo or (p.lo .. "-" .. p.hi)) .. "|r") or "")
			end
			r.sel:SetShown(picked == p)
			r:Show()
		else
			r.p = nil
			r:Hide()
		end
	end
	win.more:SetText(#list > ROWS and (P.DIM .. ("+%d more: keep typing"):format(#list - ROWS) .. "|r") or "")
end

local function Build()
	win = CreateFrame("Frame", "PathwayGoTo", UIParent, "BackdropTemplate")
	P.Flat(win, nil, nil, true)
	win:SetFrameStrata("DIALOG")
	win:SetWidth(320)
	win:SetClampedToScreen(true)
	win:EnableMouse(true)
	win:SetMovable(true); win:RegisterForDrag("LeftButton")
	win:SetScript("OnDragStart", function(self) self:StartMoving() end)
	win:SetScript("OnDragStop", function(self) self:StopMovingOrSizing() end)
	win.title = win:CreateFontString(nil, "OVERLAY"); win.title:SetFontObject(P.fonts.title)
	win.title:SetPoint("TOPLEFT", 12, -10); win.title:SetText("Go anywhere")
	win.close = P:CloseButton(win, function() win:Hide() end); win.close:SetPoint("TOPRIGHT", -4, -4)

	local eb = CreateFrame("EditBox", nil, win, "BackdropTemplate")
	P.Flat(eb)
	eb:SetPoint("TOPLEFT", 10, -32); eb:SetPoint("RIGHT", -10, 0); eb:SetHeight(22)
	eb:SetFontObject(P.fonts.button); eb:SetTextInsets(8, 8, 0, 0); eb:SetAutoFocus(false)
	eb.hint = eb:CreateFontString(nil, "OVERLAY"); eb.hint:SetFontObject(P.fonts.head)
	eb.hint:SetPoint("LEFT", 8, 0); eb.hint:SetText("Type a zone, city or town")
	eb:SetScript("OnTextChanged", function(self) self.hint:SetShown(self:GetText() == ""); Fill() end)
	eb:SetScript("OnEnterPressed", function(self)
		local r = win.rows[1]
		if r and r.p then ShowWay(r.p); Fill() end
		self:ClearFocus()
	end)
	eb:SetScript("OnEscapePressed", function(self) if self:GetText() ~= "" then self:SetText("") else self:ClearFocus(); win:Hide() end end)
	win.search = eb

	win.head = win:CreateFontString(nil, "OVERLAY"); win.head:SetFontObject(P.fonts.head)
	win.head:SetPoint("TOPLEFT", eb, "BOTTOMLEFT", 2, -4)
	win.rows = {}
	for i = 1, ROWS do
		local r = CreateFrame("Button", nil, win)
		r:SetHeight(ROW)
		r:SetPoint("TOPLEFT", 10, -70 - (i - 1) * ROW); r:SetPoint("RIGHT", -10, 0)
		r.hi = r:CreateTexture(nil, "HIGHLIGHT"); r.hi:SetAllPoints(); r.hi:SetColorTexture(1, 1, 1, 0.06)
		r.sel = r:CreateTexture(nil, "BACKGROUND"); r.sel:SetAllPoints(); r.sel:SetColorTexture(A[1], A[2], A[3], 0.18); r.sel:Hide()
		r.text = r:CreateFontString(nil, "OVERLAY"); r.text:SetFontObject(P.fonts.button); r.text:SetPoint("LEFT", 6, 0)
		r.sub = r:CreateFontString(nil, "OVERLAY"); r.sub:SetFontObject(P.fonts.head); r.sub:SetPoint("RIGHT", -6, 0)
		r:SetScript("OnClick", function(self) if self.p then ShowWay(self.p); Fill() end end)
		r:SetScript("OnDoubleClick", function(self) if self.p and P:GoToZone(self.p.town and self.p or self.p.map) then win:Hide() end end)
		win.rows[i] = r
	end
	win.more = win:CreateFontString(nil, "OVERLAY"); win.more:SetFontObject(P.fonts.head)
	win.more:SetPoint("TOPLEFT", 14, -70 - ROWS * ROW)
	win.way = win:CreateFontString(nil, "OVERLAY"); win.way:SetFontObject(P.fonts.button)
	win.way:SetPoint("TOPLEFT", 14, -70 - ROWS * ROW - 18); win.way:SetPoint("RIGHT", -12, 0)
	win.way:SetJustifyH("LEFT"); win.way:SetSpacing(3)
	win.go = P:FlatButton(win, "Go", true)
	win.go:SetPoint("BOTTOMRIGHT", -10, 10)
	win.go:SetScript("OnClick", function() if picked and P:GoToZone(picked.town and picked or picked.map) then win:Hide() end end)
	win.go:Hide()
	win:SetHeight(64 + ROWS * ROW + 22)
	win:SetScript("OnShow", function() picked = nil; win.way:SetText(P.DIM .. "Click a place to see the fastest way there. Double-click to go.|r"); Fill() end)
	win:Hide()
	if P.ApplySizes then P:ApplySizes() end
end

function P:ToggleGoTo(owner)
	if not win then Build() end
	if win:IsShown() then win:Hide() return end
	win:ClearAllPoints()
	if owner then
		local _, y = owner:GetCenter()
		local up = y and y < UIParent:GetHeight() / 2
		win:SetPoint(up and "BOTTOMRIGHT" or "TOPRIGHT", owner, up and "TOPRIGHT" or "BOTTOMRIGHT", 0, up and 4 or -4)
	else
		win:SetPoint("CENTER", UIParent, "CENTER", 0, 80)
	end
	win.search:SetText("")
	win:Show()
	win.search:SetFocus()
end
end part() end
-- ==================== Boosts.lua
do local __addon, __ns = ... local function part()
-- Copyright (C) 2026 SoFinSicc. Part of Pathway (curseforge.com/wow/addons/pathway): free software under the GPLv3 or later, with additional terms that require keeping this credit. See LICENSE.md.
--[[ Pathway — XP boosts
     Forever has a few ways to earn more experience, and each is worth most at a
     certain moment. Pathway asks at that moment, never more than once at a time,
     and every question has "Never ask" to turn it off for good:
       · the Cozy Sleeping Bag (+1% XP a stack, 3 stacks), when a new Fastest XP
         set starts and you're missing it; no bag yet from level 14, the way to
         its quest chain
       · XP food (+5% kill XP for 15 minutes), before a set with killing in it
       · rested XP, when you log out (or go away) out in the wild: the nearest inn
       · a campfire you pass, when your camp buffs are gone or nearly: a pop-up
     Saying yes puts the bag or the food on your magic button (and step key), or
     takes you there. ]]

local ADDON, P = __addon, __ns
local floor, GetTime = math.floor, GetTime

local function S() return P.db.settings end

local BAG = 211527                                -- Cozy Sleeping Bag
local WELL_RESTED, WELL_FED_XP = 429959, 1243969  -- the bag's buff; cooked food's experience buff
local CAMP_BENEFITS, CAMP_NEARBY = 1229741, 1283391
local BAG_CHAIN = { 79007, 79008, 79192, 79980, 79974, 79975, 79976 }
local SNOOZE = 1800                               -- "not now": half an hour
-- the bag's chain is a walk round the world from level 14, though its quests say 22-32
P.ANY_LEVEL = P.ANY_LEVEL or {}
for _, qid in ipairs(BAG_CHAIN) do P.ANY_LEVEL[qid] = true end

local Aura
do
	local names = { [WELL_RESTED] = "Well-Rested", [WELL_FED_XP] = "Well Fed", [CAMP_BENEFITS] = "Camp Benefits", [CAMP_NEARBY] = "Campfire Nearby" }
	function Aura(id)
		local U = C_UnitAuras
		if U and U.GetPlayerAuraBySpellID then
			local ok, a = pcall(U.GetPlayerAuraBySpellID, id)
			if ok and a then return a end
		end
		-- not found by its id (the game's may differ): by its name
		local name = names[id]
		if name and AuraUtil and AuraUtil.FindAuraByName then return AuraUtil.FindAuraByName(name, "player") end
	end
end
P.BoostAura = function(_, id) return Aura(id) end
local function Left(a)
	if not a then return 0 end
	local t = a.expirationTime
	-- a time the game keeps from add-ons (a "secret" value) can't be read: treat it as plenty
	if issecretvalue and issecretvalue(t) then return math.huge end
	if type(t) ~= "number" or t == 0 then return math.huge end
	return t - GetTime()
end

local function Busy()
	return InCombatLockdown() or UnitIsDeadOrGhost("player") or UnitOnTaxi("player") or (IsInInstance and IsInInstance())
end

-- "not now" for half an hour, per question
local snoozed = {}
local function Snoozed(kind) return snoozed[kind] and GetTime() < snoozed[kind] end
local function Snooze(kind) snoozed[kind] = GetTime() + SNOOZE end

---------------------------------------------------------------------------
-- The item a yes put on your magic button: it stays until it's done its job
---------------------------------------------------------------------------
local boost              -- { item, kind, until }
function P:BoostItem()
	if not boost then return end
	if GetTime() > boost["until"] or P.Item.GetItemCount(boost.item) == 0 then boost = nil; return end
	return boost.item
end
local function OnButton(item, kind)
	boost = { item = item, kind = kind, ["until"] = GetTime() + 600 }
	if P.UpdateQuestBar then P:UpdateQuestBar() end
	local how = S().magicButton and "your magic button" or (S().questBar and "your quest bar" or "your step key")
	P:Toast(("On %s: click it to use %s"):format(how, (C_Item and C_Item.GetItemNameByID or GetItemInfo)(item) or "it"))
end
local function Done(kind)
	if boost and boost.kind == kind then boost = nil; if P.UpdateQuestBar and not InCombatLockdown() then P:UpdateQuestBar() end end
end

---------------------------------------------------------------------------
-- XP food: cooked food whose buff gives experience (its own words say so)
---------------------------------------------------------------------------
local isXPFood = {}
local function XPFood(id)
	local c = isXPFood[id]
	if c ~= nil then return c end
	local spellID = select(2, (C_Item and C_Item.GetItemSpell or GetItemSpell)(id))
	local text = spellID and ((C_Spell and C_Spell.GetSpellDescription) or GetSpellDescription or function() end)(spellID)
	if not text or text == "" then return false end           -- not loaded yet: asked again next time
	c = text:lower():find("experience", 1, true) ~= nil
	isXPFood[id] = c
	return c
end
local function FindXPFood()
	local C = P.Container
	for bag = 0, 4 do
		for slot = 1, (C.GetContainerNumSlots(bag) or 0) do
			local it = C.GetContainerItemInfo(bag, slot)
			if it and it.itemID and XPFood(it.itemID) then return it.itemID end
		end
	end
end
P.FindXPFood = function() return FindXPFood() end

---------------------------------------------------------------------------
-- The questions
---------------------------------------------------------------------------
local function NeverButton(setting, what)
	return { "Never ask", function()
		S()[setting] = false
		P:Toast(what .. " are off (Settings, Quest help, to turn them back on)")
	end, nil, "link" }
end

local function AskBag()
	if Snoozed("bag") then return end
	local a = Aura(WELL_RESTED)
	if a and (a.applications or 1) >= 3 and Left(a) > 900 then return end
	if IsResting() then return end                         -- it only works out in the world
	local getCd = C_Container and C_Container.GetItemCooldown or GetItemCooldown
	local start, dur = getCd(BAG)
	if start and dur and dur > 0 and start + dur - GetTime() > 5 then return end
	P:Ask({ key = "boost:bag", item = "item:" .. BAG, icon = (C_Item and C_Item.GetItemIconByID or GetItemIcon)(BAG) or 134400,
		title = "Lay out your Cozy Sleeping Bag?",
		text = "Lie in it for three minutes: +3% experience from everything, and it lasts through death.\n" ..
			P.DIM .. "A good moment: a new set is starting.|r",
		buttons = { NeverButton("xpNudges", "XP buff questions"), { "Not now", function() Snooze("bag") end },
			{ "Put it on my button", function() OnButton(BAG, "bag") end, true } } })
	return true
end

local function BagChainStart()
	for _, qid in ipairs(BAG_CHAIN) do
		if P:Available(qid) then return qid end
	end
end
local function AskBagChain()
	if Snoozed("chain") or (P.me.level or 1) < 14 or (P.cdb and P.cdb.bagChainNo) then return end
	local first = BagChainStart()
	if not first then return end
	P:Ask({ key = "boost:chain", icon = (C_Item and C_Item.GetItemIconByID or GetItemIcon)(BAG) or 134400,
		title = "Get the Cozy Sleeping Bag",
		text = "A quest chain from level 14 across a few zones: good experience on the way, and at the end a bag that gives +3% experience whenever you want it.",
		buttons = { NeverButton("xpNudges", "XP buff questions"), { "Not now", function() Snooze("chain") end },
			{ "Take me there", function()
				local qs = {}
				for _, qid in ipairs(BAG_CHAIN) do qs[qid] = true end
				P:StartRoute("guide", { quests = qs, title = "Cozy Sleeping Bag", guide = "chain:bag", detour = true })
			end, true } } })
	return true
end

-- a set with killing in it: food's +5% kill experience pays
local function KillHeavy(b)
	local n = 0
	for qid in pairs(b and b.quests or {}) do
		local q = P.Q[qid]
		if q and q[P.K.ON] and #q[P.K.ON] > 0 and not (q[P.K.SN] and q[P.K.SN][1] == q[P.K.ON][1]) then n = n + 1 end
	end
	return n >= 2
end
local askedNoFood
local function AskFood(b)
	if Snoozed("food") or Left(Aura(WELL_FED_XP)) > 120 or not KillHeavy(b) then return end
	local food = FindXPFood()
	if food then
		P:Ask({ key = "boost:food", item = "item:" .. food, icon = (C_Item and C_Item.GetItemIconByID or GetItemIcon)(food) or 134400,
			title = "Eat before you go?",
			text = ("|cffffffff%s|r: +5%% experience from kills for 15 minutes (lost if you die).\n" .. P.DIM .. "This set has a lot of killing in it.|r")
				:format((C_Item and C_Item.GetItemNameByID or GetItemInfo)(food) or "Your food"),
			buttons = { NeverButton("xpNudges", "XP buff questions"), { "Not now", function() Snooze("food") end },
				{ "Put it on my button", function() OnButton(food, "food") end, true } } })
		return true
	end
	-- none on you: where to get it, once a session (cooked food; the cooking trainer teaches it)
	if askedNoFood or not P.Find then return end
	local id, row, yd = P.Find:Nearest("prof:cooking")
	if not id then return end
	askedNoFood = true
	P:Ask({ key = "boost:nofood", icon = "Interface\\Icons\\INV_Misc_Food_15", title = "No XP food on you",
		text = ("Most cooked food gives +5%% experience from kills. Nearest cooking trainer: |cffffffff%s|r, %d yd.\n" ..
			P.DIM .. "Cook at any campfire, or buy it from other players.|r"):format(row[1], floor(yd)),
		buttons = { NeverButton("xpNudges", "XP buff questions"), { "Not now", function() Snooze("food") end },
			{ "Take me there", function() P.Find:Go("prof:cooking") end, true } } })
	return true
end

-- the moment a new Fastest XP set starts: one question at most
function P:BoostMoment(b)
	if not (P.db and S().xpNudges ~= false) or Busy() then return end
	if (P.me.level or 1) >= 60 then return end
	if P.Item.GetItemCount(BAG) > 0 then
		if AskBag() then return end
	elseif AskBagChain() then return end
	AskFood(b)
end

---------------------------------------------------------------------------
-- Rested: logging out (or stepping away) out in the world
---------------------------------------------------------------------------
local function RestedFull()
	local r, max = GetXPExhaustion and GetXPExhaustion() or 0, UnitXPMax and UnitXPMax("player") or 0
	return max > 0 and r >= max * 1.45
end
local function AskRest(leaving)
	if not (P.db and S().restNudge ~= false) or Snoozed("rest") then return end
	if IsResting() or (IsInInstance and IsInInstance()) or (P.me.level or 1) >= 60 or RestedFull() then return end
	if InCombatLockdown() or UnitOnTaxi("player") then return end
	local id, row, yd
	if P.Find then id, row, yd = P.Find:Nearest("inn") end
	local bag = P.Item.GetItemCount(BAG) > 0
	if not id and not bag then return end
	local text = "At an inn or in a city you build rested XP while away: double XP from kills until it's used."
	if id then text = text .. ("\nNearest inn: |cffffffff%s|r, %d yd."):format(row[1], floor(yd)) end
	if bag then text = text .. "\n" .. P.DIM .. "Your Cozy Sleeping Bag counts as an inn too.|r" end
	local buttons = { NeverButton("restNudge", "Rested reminders"), { leaving and "Log out here" or "Not now", function() Snooze("rest") end } }
	if bag then buttons[#buttons + 1] = { "Use my bag", function() if leaving and CancelLogout then CancelLogout() end; OnButton(BAG, "bag") end } end
	if id then buttons[#buttons + 1] = { "Take me there", function()
		if leaving and CancelLogout then CancelLogout() end
		P.Find:Go("inn")
	end, true } end
	P:Ask({ key = "boost:rest", icon = "Interface\\Icons\\Spell_Nature_Sleep", title = leaving and "Logging out out here?" or "Taking a break?",
		text = text, buttons = buttons })
end
P:On("PLAYER_CAMPING", function() AskRest(true) end)
local awaySince
P:On("PLAYER_FLAGS_CHANGED", function(_, unit)
	if unit and unit ~= "player" then return end
	if UnitIsAFK and UnitIsAFK("player") then
		awaySince = GetTime()
		C_Timer.After(120, function() if awaySince and GetTime() - awaySince >= 119 and UnitIsAFK("player") then AskRest(false) end end)
	else awaySince = nil end
end)

---------------------------------------------------------------------------
-- A campfire you pass: a pop-up, when your camp buffs are gone or nearly
---------------------------------------------------------------------------
local pop, lastPop = nil, { t = -1e9 }
local EMBERS = 10

local function BuildPop()
	pop = CreateFrame("Frame", "PathwayCampfire", UIParent)
	pop:SetSize(360, 96)
	-- the pop-up spot it shares with the others (Shift-drag moves it)
	P:PopupFrame(pop)
	pop:SetFrameStrata("HIGH")
	pop:Hide()
	pop.bg = pop:CreateTexture(nil, "BACKGROUND")
	pop.bg:SetAllPoints()
	pop.bg:SetColorTexture(0.06, 0.035, 0.02, 0.92)
	pop.line = pop:CreateTexture(nil, "BORDER")
	pop.line:SetPoint("BOTTOMLEFT"); pop.line:SetPoint("BOTTOMRIGHT"); pop.line:SetHeight(2)
	pop.line:SetColorTexture(1, 0.55, 0.15, 0.9)
	-- the fire lives in its own square inside the window: everything it draws is
	-- clipped to it, so the glow and the embers never spill out
	local FX = 72
	local fx = CreateFrame("Frame", nil, pop)
	fx:SetPoint("TOPLEFT", 6, -6); fx:SetPoint("BOTTOMLEFT", 6, 8); fx:SetWidth(FX)
	fx:SetClipsChildren(true)
	local art = CreateFrame("Frame", nil, fx)
	art:SetAllPoints()
	pop.fx = art
	pop.glow = art:CreateTexture(nil, "BACKGROUND", nil, 1)
	pop.glow:SetTexture(P.MEDIA .. "Dot"); pop.glow:SetBlendMode("ADD")
	pop.glow:SetPoint("CENTER", art, "CENTER", 0, -2); pop.glow:SetSize(FX, FX)
	pop.glow:SetVertexColor(1, 0.45, 0.1, 0.45)
	-- the fire: a ring that breathes, the icon, embers rising off it
	pop.ring = art:CreateTexture(nil, "ARTWORK")
	pop.ring:SetTexture(P.MEDIA .. "Ring"); pop.ring:SetBlendMode("ADD")
	pop.ring:SetPoint("CENTER", art, "CENTER", 0, -2); pop.ring:SetSize(52, 52)
	pop.ring:SetVertexColor(1, 0.6, 0.2, 0.9)
	pop.icon = art:CreateTexture(nil, "OVERLAY")
	pop.icon:SetTexture("Interface\\Icons\\Spell_Fire_Fire"); pop.icon:SetSize(36, 36)
	pop.icon:SetPoint("CENTER", pop.ring, "CENTER")
	local mask = art:CreateMaskTexture()
	mask:SetTexture("Interface\\CharacterFrame\\TempPortraitAlphaMask", "CLAMPTOBLACKADDITIVE", "CLAMPTOBLACKADDITIVE")
	mask:SetAllPoints(pop.icon); pop.icon:AddMaskTexture(mask)
	pop.embers = {}
	for i = 1, EMBERS do
		local e = art:CreateTexture(nil, "OVERLAY", nil, 2)
		e:SetTexture(P.MEDIA .. "Dot"); e:SetBlendMode("ADD"); e:SetSize(4, 4)
		e:SetVertexColor(1, 0.55 + (i % 3) * 0.12, 0.15, 1)
		local g = e:CreateAnimationGroup(); g:SetLooping("REPEAT")
		-- a short rise: they fade out well inside the square
		local up = g:CreateAnimation("Translation"); up:SetOffset(((i % 5) - 2) * 4, 22 + (i % 4) * 4); up:SetDuration(1.1 + (i % 4) * 0.2)
		local fade = g:CreateAnimation("Alpha"); fade:SetFromAlpha(1); fade:SetToAlpha(0); fade:SetDuration(up:GetDuration())
		local sc = g:CreateAnimation("Scale"); sc:SetScaleFrom(1, 1); sc:SetScaleTo(0.3, 0.3); sc:SetDuration(up:GetDuration())
		e.anim, e.delay = g, (i - 1) * 0.15
		pop.embers[i] = e
	end
	local breathe = pop.ring:CreateAnimationGroup(); breathe:SetLooping("BOUNCE")
	local b1 = breathe:CreateAnimation("Scale"); b1:SetScaleFrom(0.94, 0.94); b1:SetScaleTo(1.06, 1.06); b1:SetDuration(0.9); b1:SetSmoothing("IN_OUT")
	pop.breathe = breathe
	local flick = pop.glow:CreateAnimationGroup(); flick:SetLooping("BOUNCE")
	local f1 = flick:CreateAnimation("Alpha"); f1:SetFromAlpha(0.45); f1:SetToAlpha(0.85); f1:SetDuration(0.45); f1:SetSmoothing("IN_OUT")
	pop.flicker = flick
	-- words
	pop.title = pop:CreateFontString(nil, "OVERLAY")
	pop.title:SetFont(STANDARD_TEXT_FONT, 17, "OUTLINE"); pop.title:SetTextColor(1, 0.72, 0.3)
	pop.title:SetPoint("TOPLEFT", pop, "TOPLEFT", 6 + 72 + 10, -10)
	pop.title:SetText("CAMPFIRE NEARBY")
	pop.text = pop:CreateFontString(nil, "OVERLAY")
	pop.text:SetFontObject(P.fonts and P.fonts.button or GameFontHighlightSmall)
	pop.text:SetPoint("TOPLEFT", pop.title, "BOTTOMLEFT", 0, -4); pop.text:SetWidth(360 - 6 - 72 - 10 - 30)
	pop.text:SetJustifyH("LEFT"); pop.text:SetSpacing(2)
	pop.sit = P:FlatButton(pop, "Sit down", true)
	pop.sit:SetPoint("BOTTOMRIGHT", pop, "BOTTOMRIGHT", -8, 10)
	pop.sit:SetScript("OnClick", function() if not InCombatLockdown() and DoEmote then DoEmote("SIT") end end)
	pop.never = CreateFrame("Button", nil, pop)
	pop.never:SetPoint("BOTTOMLEFT", pop, "BOTTOMLEFT", 6 + 72 + 10, 12); pop.never:SetSize(110, 14)
	pop.never.t = pop.never:CreateFontString(nil, "OVERLAY"); pop.never.t:SetFontObject(P.fonts and P.fonts.button or GameFontDisableSmall)
	pop.never.t:SetPoint("LEFT"); pop.never.t:SetText(P.DIM .. "Don't show again|r")
	pop.never:SetScript("OnClick", function()
		S().campfirePop = false; pop:Hide()
		P:Toast("Campfire pop-ups are off (Settings, Quest help, to turn them back on)")
	end)
	pop.close = P:CloseButton(pop, function() pop:Hide() end)
	pop.close:SetPoint("TOPRIGHT", pop, "TOPRIGHT", -2, -2)
	-- in: a quick fade and a small lift; out: a soft fade
	local inA = pop:CreateAnimationGroup()
	local a1 = inA:CreateAnimation("Alpha"); a1:SetFromAlpha(0); a1:SetToAlpha(1); a1:SetDuration(0.2)
	local t1 = inA:CreateAnimation("Translation"); t1:SetOffset(0, 6); t1:SetDuration(0.2); t1:SetSmoothing("OUT")
	pop.inA = inA
	local outA = pop:CreateAnimationGroup()
	local a2 = outA:CreateAnimation("Alpha"); a2:SetFromAlpha(1); a2:SetToAlpha(0); a2:SetDuration(0.5)
	outA:SetScript("OnFinished", function() pop:Hide(); pop.leaving = nil end)
	pop.outA = outA
	pop:SetScript("OnShow", function(self)
		self.leaving = nil
		self.outA:Stop(); self:SetAlpha(1); self.inA:Play(); self.breathe:Play(); self.flicker:Play()
		for _, e in ipairs(self.embers) do
			e:ClearAllPoints(); e:SetPoint("CENTER", self.ring, "CENTER", 0, -6); e:SetAlpha(0)
			C_Timer.After(e.delay, function() if self:IsShown() then e:SetAlpha(1); e.anim:Play() end end)
		end
	end)
	pop:SetScript("OnHide", function(self)
		-- still by the fire: its timer takes the spot
		C_Timer.After(0.1, function() if Aura(CAMP_NEARBY) and P.ShowFireTimer then P.ShowFireTimer() end end)
		self.breathe:Stop(); self.flicker:Stop()
		for _, e in ipairs(self.embers) do e.anim:Stop() end
	end)
end

local function HidePop(fade)
	if pop and pop:IsShown() and not pop.leaving then if fade then pop.leaving = true; pop.outA:Play() else pop:Hide() end end
end

-- what sitting there would give you that you're short of now
local function PopText()
	local parts = { "Sit a minute: camp buffs for an hour." }
	if Left(Aura(WELL_FED_XP)) < 120 and P.Item.GetItemCount(BAG) == 0 then
		parts[#parts + 1] = P.DIM .. "Cook there too: +5% kill XP.|r"
	elseif Left(Aura(WELL_RESTED)) < 600 and P.Item.GetItemCount(BAG) > 0 then
		parts[#parts + 1] = P.DIM .. "A good spot for your Sleeping Bag.|r"
	end
	return table.concat(parts, "\n")
end

local function ShowPop()
	if not pop then BuildPop() end
	pop.text:SetText(PopText())
	-- as tall as its words, with the buttons clear of them
	pop:SetHeight(math.max(86, 10 + 17 + 4 + pop.text:GetStringHeight() + 10 + 22 + 10))
	pop:Hide(); pop.leaving = nil
	pop:Show()
	if S().sound then PlaySound(SOUNDKIT.IG_QUEST_LIST_OPEN or 875) end
	C_Timer.After(14, function() HidePop(true) end)
end
P.ShowCampfirePop = function() ShowPop() end

---------------------------------------------------------------------------
-- The campfire window: in the pop-up spot while you're by a fire (or sitting, or
-- sleeping in your bag). What it shows:
--   · Fire        how long until it burns out (exact when it was seen placed, by you or
--                 a player sharing; otherwise "up to", the most it can have left)
--   · Camp buffs  the minute you sit for them (Welcoming Campfire), then how long they last
--   · Sleeping bag  its 3 stacks (one a minute lying on it) and the next one's countdown
--   · a row of what you can use there: camp objects you carry, the bag, XP food, one
--     click each (the game's own secure item buttons, so they're changed out of combat)
-- Camp object names: Stoked by KonigTX (MIT).
---------------------------------------------------------------------------
local WELCOME = { 1229739, 1289723 }              -- "Welcoming Campfire": the minute you sit
local CAMP_OBJECTS = {
	"Mana Well", "Fermenter", "Alchemy Laboratory", "Sharpening Wheel", "Anvil", "Master Forge",
	"Enchanted Lute", "Arcane Salvager", "Arcane Forge", "Reagent Bot", "Repair Bot", "Anarchist's Workbench",
	"Incense Candle", "Greenhouse", "Seed Hybridizer", "Camp Tent", "Tanning Rack", "Sewing Machine",
	"Lodestone", "Rock Garden", "Molten Foundry", "Camp Chair", "Field Guide", "Trapper's Workbench",
	"Faction Banner", "Spinning Wheel", "Loom", "Cookie's Feast", "Iron Oven",
	"First Aid Kit", "Toxin Study", "Plague Doctor's Laboratory", "Fish Bowl", "Fishing Rack", "Fishing Hut",
}
local OBJECT_IDS = { [279972] = true, [279973] = true }      -- the faction banners
local isObject = {}
for _, n in ipairs(CAMP_OBJECTS) do isObject[n:lower()] = true end
local function CampObject(id, name)
	if OBJECT_IDS[id] then return true end
	if not name then return false end
	name = name:lower()
	return isObject[name] or isObject[(name:gsub("%s*%(.-%)%s*$", ""))] or false
end

local card, items
-- in a town: its campfire never burns out
local function InTown()
	if not P.TownAt then return end
	local inst, px, py = P:PlayerPos()
	if not inst then return end
	local ok, t = pcall(P.TownAt, P, P:PlayerZone(), inst, px, py)
	return ok and t or nil
end
P.CampInTown = InTown
-- the bag's stacks as little lit and unlit dots (a picture: the game's font has no dot)
local function Dots(n)
	local on = "|T" .. P.MEDIA .. "Dot:10:10:0:0:64:64:0:64:0:64:255:210:0|t"
	local off = "|T" .. P.MEDIA .. "Dot:10:10:0:0:64:64:0:64:0:64:85:85:85|t"
	return on:rep(n) .. off:rep(math.max(0, 3 - n))
end
local function Clock(sec) sec = math.max(0, math.floor(sec + 0.5)); return ("%d:%02d"):format(sec / 60, sec % 60) end
local function Long(sec)
	if sec == math.huge then return "on" end
	if sec >= 3600 then return ("%d h %02d"):format(sec / 3600, (sec % 3600) / 60) end
	return ("%d min"):format(math.max(1, floor(sec / 60 + 0.5)))
end

-- the sit countdown: the buff's own time, or a minute from when it came
local welcomeAt
local function WelcomeLeft()
	local a
	for _, id in ipairs(WELCOME) do a = a or Aura(id) end
	if not a and AuraUtil and AuraUtil.FindAuraByName then a = AuraUtil.FindAuraByName("Welcoming Campfire", "player") end
	if not a then welcomeAt = nil return end
	welcomeAt = welcomeAt or GetTime()
	local left = Left(a)
	if left == math.huge then left = 60 - (GetTime() - welcomeAt) end
	return math.max(0, left)
end

-- the sleeping bag: stacks, and lying on it (the game counts you as resting there)
local bagLying, lastStacks
local function Stacks()
	local a = Aura(WELL_RESTED)
	if not a then return 0, 0 end
	local n = a.applications
	if issecretvalue and issecretvalue(n) then n = nil end
	return tonumber(n) or 1, Left(a)
end
local function BagCheck()
	local n = Stacks()
	if lastStacks and n > lastStacks and bagLying then bagLying = GetTime() end       -- a stack: the next one in a minute
	lastStacks = n
	local resting = IsResting and IsResting()
	if resting and not bagLying and P.bagPlacedAt and GetTime() - P.bagPlacedAt < 300 then bagLying = GetTime() end
	if not resting then bagLying = nil end
end
P:On("PLAYER_UPDATE_RESTING", BagCheck)
P:On("UNIT_SPELLCAST_SUCCEEDED", function(_, unit, _, spellID)
	if unit ~= "player" then return end
	local name = spellID and C_Spell and C_Spell.GetSpellName and C_Spell.GetSpellName(spellID)
	if name and name:find("Sleeping Bag", 1, true) then P.bagPlacedAt = GetTime(); C_Timer.After(1, BagCheck) end
end)

-- what you can use at the fire: from your bags
local function UsableHere()
	local out, seen = {}, {}
	local C = P.Container
	local nameOf = (C_Item and C_Item.GetItemNameByID) or GetItemInfo
	for bag = 0, 4 do
		for slot = 1, (C.GetContainerNumSlots(bag) or 0) do
			local it = C.GetContainerItemInfo(bag, slot)
			local id = it and it.itemID
			if id and not seen[id] and CampObject(id, nameOf(id)) then seen[id] = true; out[#out + 1] = id end
		end
	end
	if (GetItemCount and GetItemCount(BAG) or 0) > 0 and select(1, Stacks()) < 3 then out[#out + 1] = BAG end
	if Left(Aura(WELL_FED_XP)) < 120 then local food = FindXPFood(); if food then out[#out + 1] = food end end
	return out
end

-- the row of item buttons: the game's secure buttons, only ever changed out of combat
local MAX_ITEMS, ISIZE = 7, 30
local itemsDirty
local function BuildItems()
	items = CreateFrame("Frame", "PathwayCampItems", UIParent)
	items:SetSize(10, ISIZE)
	items:SetFrameStrata("HIGH")
	items:Hide()
	items.buttons = {}
	for i = 1, MAX_ITEMS do
		local b = CreateFrame("Button", "PathwayCampItem" .. i, items, "SecureActionButtonTemplate")
		b:SetSize(ISIZE, ISIZE)
		b:SetPoint("LEFT", (i - 1) * (ISIZE + 6), 0)
		b:RegisterForClicks("AnyUp", "AnyDown")
		b:SetAttribute("type", "item")
		b.icon = b:CreateTexture(nil, "ARTWORK"); b.icon:SetAllPoints(); b.icon:SetTexCoord(0.08, 0.92, 0.08, 0.92)
		local hl = b:CreateTexture(nil, "HIGHLIGHT"); hl:SetAllPoints(); hl:SetColorTexture(1, 0.8, 0.4, 0.25)
		b.count = b:CreateFontString(nil, "OVERLAY", "NumberFontNormalSmall"); b.count:SetPoint("BOTTOMRIGHT", -1, 1)
		b.cd = CreateFrame("Cooldown", nil, b, "CooldownFrameTemplate"); b.cd:SetAllPoints()
		b:SetScript("OnEnter", function(self)
			if not self.id then return end
			GameTooltip:SetOwner(self, "ANCHOR_TOP")
			GameTooltip:SetItemByID(self.id)
			GameTooltip:Show()
		end)
		b:SetScript("OnLeave", function() GameTooltip:Hide() end)
		b:Hide()
		items.buttons[i] = b
	end
end
-- out of combat only: what the buttons hold, and where the row sits (inside the card)
local function FillItems()
	if InCombatLockdown() then itemsDirty = true return end
	itemsDirty = false
	if not items then BuildItems() end
	local list = (card and card:IsShown()) and UsableHere() or {}
	local n = math.min(#list, MAX_ITEMS)
	for i, b in ipairs(items.buttons) do
		local id = list[i]
		b.id = id
		if id then
			b:SetAttribute("item", "item:" .. id)
			b.icon:SetTexture((C_Item and C_Item.GetItemIconByID or GetItemIcon)(id) or 134400)
			local c = GetItemCount and GetItemCount(id) or 1
			b.count:SetText(c > 1 and c or "")
			local start, dur = (C_Container and C_Container.GetItemCooldown or GetItemCooldown)(id)
			if start and dur and dur > 1.5 then b.cd:SetCooldown(start, dur) else b.cd:Clear() end
			b:Show()
		else
			b:SetAttribute("item", nil)
			b:Hide()
		end
	end
	items:SetWidth(math.max(10, n * (ISIZE + 6) - 6))
	items:ClearAllPoints()
	if card and card:IsShown() and n > 0 then
		items:SetPoint("BOTTOM", card, "BOTTOM", 0, 8)
		items:Show()
	else
		items:Hide()
	end
	if card then
		card.itemRows = n > 0 and 1 or 0
		card:SetWidth(math.max(196, n * (ISIZE + 6) + 20))
	end
end
P:On("PLAYER_REGEN_ENABLED", function() if itemsDirty then FillItems(); if card and card:IsShown() then card:Paint() end end end)
P:On("BAG_UPDATE_DELAYED", function() if card and card:IsShown() then P:Debounce("campitems", 0.3, FillItems) end end)

-- The card: a round fire with its burn time running down the ring around it, the time under
-- it, then a tile for each camp buff (each with its own countdown sweep), then what you can
-- use here. Every tile keeps a line saying what it means (shown when you point at it).
local TILE, MED = 38, 66
local function Sweep(parent, ring)
	local cd = CreateFrame("Cooldown", nil, parent, "CooldownFrameTemplate")
	cd:SetAllPoints()
	if cd.SetHideCountdownNumbers then cd:SetHideCountdownNumbers(true) end
	if cd.SetDrawEdge then cd:SetDrawEdge(false) end
	if cd.SetDrawBling then cd:SetDrawBling(false) end
	if ring and cd.SetSwipeTexture then cd:SetSwipeTexture(P.MEDIA .. "CampRing") end
	-- the coloured part is the time still to run, shrinking round as it goes
	return cd
end
-- start a sweep only when it changed, so it runs smoothly in between
local function SetSweep(cd, ends, dur, r, g, b, a)
	if not ends or not dur or dur <= 0 or dur == math.huge then
		if cd.ends then cd:Clear(); cd.ends = nil end
		return
	end
	if not cd.ends or math.abs(cd.ends - ends) > 0.5 or cd.dur ~= dur then
		cd:SetCooldown(ends - dur, dur); cd.ends, cd.dur = ends, dur
	end
	if cd.SetSwipeColor then cd:SetSwipeColor(r, g, b, a or 0.8) end
end
local function Tile(parent, icon)
	local t = CreateFrame("Frame", nil, parent)
	t:SetSize(TILE, TILE)
	local bg = t:CreateTexture(nil, "BACKGROUND"); bg:SetPoint("TOPLEFT", -1, 1); bg:SetPoint("BOTTOMRIGHT", 1, -1)
	bg:SetColorTexture(0, 0, 0, 0.75)
	t.icon = t:CreateTexture(nil, "ARTWORK"); t.icon:SetAllPoints(); t.icon:SetTexture(icon); t.icon:SetTexCoord(0.08, 0.92, 0.08, 0.92)
	t.cd = Sweep(t)
	local top = CreateFrame("Frame", nil, t); top:SetAllPoints(); top:SetFrameLevel(t.cd:GetFrameLevel() + 2)
	t.count = top:CreateFontString(nil, "OVERLAY"); t.count:SetFont(STANDARD_TEXT_FONT, 15, "OUTLINE")
	t.count:SetPoint("BOTTOMRIGHT", -1, 2)
	t.value = top:CreateFontString(nil, "OVERLAY"); t.value:SetFont(STANDARD_TEXT_FONT, 11, "OUTLINE")
	t.value:SetPoint("TOP", t, "BOTTOM", 0, -3)
	-- what it means: on the tooltip, and the card's hint line
	t.label = t:CreateFontString(nil, "OVERLAY"); t.label:Hide()
	t:EnableMouse(true)
	t:SetScript("OnEnter", function(self)
		GameTooltip:SetOwner(self, "ANCHOR_TOP")
		GameTooltip:AddLine(self.name or "", 1, 0.82, 0.3)
		local txt = self.label:GetText()
		if txt and txt ~= "" then GameTooltip:AddLine(txt, 1, 1, 1, true) end
		GameTooltip:Show()
	end)
	t:SetScript("OnLeave", function() GameTooltip:Hide() end)
	return t
end
local function Dim(t, off)
	t.icon:SetDesaturated(off and true or false)
	t.icon:SetVertexColor(off and 0.55 or 1, off and 0.55 or 1, off and 0.55 or 1)
end

local function BuildCard()
	card = CreateFrame("Frame", "PathwayFireTimer", UIParent)
	card:SetSize(196, 200)
	P:PopupFrame(card)
	card:SetFrameStrata("HIGH")
	card:Hide()
	local bg = card:CreateTexture(nil, "BACKGROUND"); bg:SetAllPoints(); bg:SetColorTexture(0.06, 0.035, 0.02, 0.92)
	local warm = card:CreateTexture(nil, "BACKGROUND", nil, 1); warm:SetPoint("TOPLEFT"); warm:SetPoint("TOPRIGHT"); warm:SetHeight(110)
	warm:SetTexture(P.MEDIA .. "Glow"); warm:SetBlendMode("ADD"); warm:SetVertexColor(1, 0.45, 0.1, 0.18)
	local line = card:CreateTexture(nil, "BORDER"); line:SetPoint("BOTTOMLEFT"); line:SetPoint("BOTTOMRIGHT"); line:SetHeight(2)
	line:SetColorTexture(1, 0.55, 0.15, 0.9)
	card.title = card:CreateFontString(nil, "OVERLAY"); card.title:SetFontObject(P.fonts and P.fonts.button or GameFontNormalSmall)
	card.title:SetPoint("TOPLEFT", 8, -6); card.title:SetText("Campfire"); card.title:SetTextColor(1, 0.72, 0.3)
	card.close = P:CloseButton(card, function() card.dismissed = true; card:Hide() end)
	card.close:SetPoint("TOPRIGHT", -2, -2)

	-- the fire: round, its time running down the ring
	local med = CreateFrame("Frame", nil, card)
	med:SetSize(MED, MED); med:SetPoint("TOP", 0, -14)
	local back = med:CreateTexture(nil, "BACKGROUND"); back:SetAllPoints(); back:SetTexture(P.MEDIA .. "Dot"); back:SetVertexColor(0, 0, 0, 0.85)
	local icon = med:CreateTexture(nil, "ARTWORK"); icon:SetPoint("TOPLEFT", 7, -7); icon:SetPoint("BOTTOMRIGHT", -7, 7)
	icon:SetTexture("Interface\\Icons\\Spell_Fire_Fire")
	if med.CreateMaskTexture then
		local mask = med:CreateMaskTexture()
		mask:SetAllPoints(icon); mask:SetTexture("Interface\\CharacterFrame\\TempPortraitAlphaMask", "CLAMPTOBLACKADDITIVE", "CLAMPTOBLACKADDITIVE")
		icon:AddMaskTexture(mask)
	end
	local track = med:CreateTexture(nil, "BORDER"); track:SetAllPoints(); track:SetTexture(P.MEDIA .. "CampRing"); track:SetVertexColor(1, 1, 1, 0.14)
	med.cd = Sweep(med, true)
	local halo = med:CreateTexture(nil, "BACKGROUND", nil, -1); halo:SetPoint("CENTER"); halo:SetSize(MED * 1.7, MED * 1.7)
	halo:SetTexture(P.MEDIA .. "Glow"); halo:SetBlendMode("ADD"); halo:SetVertexColor(1, 0.5, 0.12, 0.6)
	local breathe = halo:CreateAnimationGroup(); breathe:SetLooping("BOUNCE")
	local ba = breathe:CreateAnimation("Alpha"); ba:SetFromAlpha(0.45); ba:SetToAlpha(1); ba:SetDuration(1.6)
	med.halo, med.breathe, med.icon = halo, breathe, icon
	card.med = med
	card.fire = { name = "Campfire" }
	card.fire.value = card:CreateFontString(nil, "OVERLAY"); card.fire.value:SetFont(STANDARD_TEXT_FONT, 18, "OUTLINE")
	card.fire.value:SetPoint("TOP", med, "BOTTOM", 0, -4)
	card.fire.label = card:CreateFontString(nil, "OVERLAY"); card.fire.label:SetFontObject(P.fonts and P.fonts.small or GameFontHighlightSmall)
	card.fire.label:SetTextColor(0.75, 0.72, 0.68)

	-- the buffs
	card.sit = Tile(card, "Interface\\Icons\\Spell_Nature_Sleep"); card.sit.name = "Camp buffs"
	card.bag = Tile(card, (C_Item and C_Item.GetItemIconByID or GetItemIcon)(BAG) or "Interface\\Icons\\INV_Misc_Bag_10"); card.bag.name = "Sleeping bag"
	card.fed = Tile(card, "Interface\\Icons\\INV_Misc_Food_15"); card.fed.name = "Well Fed"
	card.hint = card:CreateFontString(nil, "OVERLAY"); card.hint:SetFontObject(P.fonts and P.fonts.small or GameFontHighlightSmall)
	card.hint:SetWidth(180); card.hint:SetJustifyH("CENTER"); card.hint:SetTextColor(0.62, 0.66, 0.72)
	card.sep = card:CreateTexture(nil, "BORDER"); card.sep:SetHeight(1); card.sep:SetColorTexture(1, 0.6, 0.2, 0.35)

	-- the timer's old names, kept for anything reading them
	card.text, card.time = card.fire.label, card.fire.value
	local fade = card:CreateAnimationGroup()
	local a = fade:CreateAnimation("Alpha"); a:SetFromAlpha(0); a:SetToAlpha(1); a:SetDuration(0.2)
	card:HookScript("OnShow", function() fade:Play(); breathe:Play(); FillItems() end)
	card:HookScript("OnHide", function() breathe:Stop(); FillItems() end)
	card:SetScript("OnUpdate", function(self, el)
		self.acc = (self.acc or 0) + el
		if self.acc < 0.25 then return end
		self.acc = 0
		self:Paint()
	end)
	function card:Paint()
		local now = GetTime()
		-- the fire
		local f, sure
		if P.FireHere then f, sure = P:FireHere() end
		local life = P.FIRE_LIFE or 900
		local left = f and (f.ends - now) or 0
		local r = self.fire
		local near = Aura(CAMP_NEARBY) ~= nil
		local town = near and (not f or f.src == "guess") and InTown()
		local lit = true
		if town then
			-- a town's campfire: always lit
			self.outAt = nil
			r.label:SetText("Town campfire: always lit"); r.value:SetText("")
			SetSweep(self.med.cd, nil)
		elseif not f or left <= 0 then
			SetSweep(self.med.cd, nil)
			r.value:SetText("")
			if near then
				r.label:SetText("Fire nearby: time unknown")
				self.outAt = nil
			else
				if not self.outAt then self.outAt = now end
				r.label:SetText("The fire's out"); lit = false
			end
		else
			self.outAt = nil
			r.label:SetText(sure and "Fire burns out in" or "Fire burns out in up to")
			local cr, cg, cb = 1, 0.72, 0.3
			if left < 60 then cr, cg, cb = 1, 0.35, 0.25 elseif left < 180 then cr, cg, cb = 1, 0.55, 0.2 end
			r.value:SetText(Clock(left)); r.value:SetTextColor(cr, cg, cb)
			SetSweep(self.med.cd, f.ends, life, cr, cg, cb, 0.95)
		end
		self.med.icon:SetDesaturated(not lit)
		self.med.halo:SetShown(lit)
		local y = -14 - MED - 4
		if r.value:GetText() ~= "" then y = y - 20 end
		r.label:ClearAllPoints(); r.label:SetPoint("TOP", self, "TOP", 0, y)
		y = y - 18
		local hints = {}

		-- sitting: the minute, then the buffs
		local t = self.sit
		local wl = WelcomeLeft()
		local ben = Aura(CAMP_BENEFITS)
		t.count:SetText("")
		if wl then
			t.label:SetText("Camp buffs in"); t.value:SetText(Clock(wl)); t.value:SetTextColor(0.55, 0.85, 1)
			SetSweep(t.cd, now + wl, 60, 0, 0, 0, 0.7); Dim(t, false)
			hints[#hints + 1] = "Stay sitting: camp buffs in " .. Clock(wl)
		elseif ben then
			local bl = Left(ben)
			t.label:SetText("Camp buffs"); t.value:SetText(Long(bl)); t.value:SetTextColor(0.5, 0.95, 0.55)
			SetSweep(t.cd, nil); Dim(t, false)
		else
			t.label:SetText("Sit a minute for camp buffs"); t.value:SetText(""); SetSweep(t.cd, nil); Dim(t, true)
			if lit then hints[#hints + 1] = "Sit a minute for camp buffs" end
		end
		-- the sleeping bag: when you have one or its buff
		t = self.bag
		local n, sl = Stacks()
		local hasBag = (GetItemCount and GetItemCount(BAG) or 0) > 0
		t.has = hasBag or n > 0
		if t.has then
			local dots = Dots(n)
			t.count:SetText(n > 0 and n or ""); t.count:SetTextColor(n >= 3 and 0.5 or 1, n >= 3 and 0.95 or 0.85, n >= 3 and 0.55 or 0.4)
			if n >= 3 then
				t.label:SetText("Sleeping bag " .. dots); t.value:SetText(Long(sl)); t.value:SetTextColor(0.5, 0.95, 0.55)
				SetSweep(t.cd, nil); Dim(t, false)
			elseif bagLying then
				local into = (now - bagLying) % 60
				t.label:SetText("Sleeping bag " .. dots); t.value:SetText("next " .. Clock(60 - into)); t.value:SetTextColor(1, 0.85, 0.4)
				SetSweep(t.cd, now + 60 - into, 60, 0, 0, 0, 0.7); Dim(t, false)
			else
				t.label:SetText("Sleeping bag " .. dots .. "  |cff8a8f99lie on it: a stack a minute|r"); t.value:SetText(n > 0 and Long(sl) or "")
				t.value:SetTextColor(0.75, 0.75, 0.75)
				SetSweep(t.cd, nil); Dim(t, n == 0)
				if n < 3 then hints[#hints + 1] = "Lie on your bag: a stack a minute" end
			end
		end
		-- fed
		t = self.fed
		local fa = Aura(WELL_FED_XP)
		local fl = fa and Left(fa)
		if fa then
			t.label:SetText("Well Fed: more experience"); t.value:SetText(Long(fl)); t.value:SetTextColor(0.5, 0.95, 0.55); Dim(t, false)
		else
			t.label:SetText("You're not Well Fed"); t.value:SetText("not fed"); t.value:SetTextColor(1, 0.4, 0.35); Dim(t, true)
		end
		-- lay the tiles out in a row, centred
		local tiles = { self.sit }
		if self.bag.has then tiles[#tiles + 1] = self.bag; self.bag:Show() else self.bag:Hide() end
		tiles[#tiles + 1] = self.fed
		local gap = 14
		local w = #tiles * TILE + (#tiles - 1) * gap
		for i, tile in ipairs(tiles) do
			tile:ClearAllPoints(); tile:SetPoint("TOPLEFT", self, "TOP", -w / 2 + (i - 1) * (TILE + gap), y); tile:Show()
		end
		y = y - TILE - 18
		self.hint:SetText(hints[1] or "")
		self.hint:ClearAllPoints()
		if hints[1] then self.hint:SetPoint("TOP", self, "TOP", 0, y); y = y - (self.hint:GetStringHeight() or 12) - 6 end
		-- what you can use here, under a line
		if (self.itemRows or 0) > 0 then
			self.sep:ClearAllPoints(); self.sep:SetPoint("TOPLEFT", 14, y - 2); self.sep:SetPoint("TOPRIGHT", -14, y - 2); self.sep:Show()
			y = y - 8 - ISIZE - 8
		else
			self.sep:Hide()
		end
		local h = -y + 4
		if math.abs((self:GetHeight() or 0) - h) > 0.5 then self:SetHeight(h); P:PopupLayout() end
		-- only while you're by a fire, sitting for its buffs or in your bag; a burnt-out fire
		-- says so for a few seconds first
		local busy = near or wl or bagLying
		if not busy then
			self.awayAt = self.awayAt or now
			if now - self.awayAt > ((self.outAt and 3) or 1) then self:Hide() end
		else
			self.awayAt = nil
		end
	end
end
local function ShowTimer()
	if S().fireTimer == false then return end
	if not card then BuildCard() end
	if card.dismissed or card:IsShown() then return end
	-- only by a fire, sitting for its buffs, or in your bag
	local near = Aura(CAMP_NEARBY) ~= nil
	if not (near or WelcomeLeft() or bagLying) then return end
	-- by a fire Pathway hadn't noted yet (and not a town's): note it now
	if near and not InTown() and not (P.FireHere and P:FireHere()) and P.NoteFireHere then P:NoteFireHere() end
	card.outAt, card.awayAt = nil, nil
	card:Paint()
	card:Show()
end
local function HideTimer() if card then card:Hide(); card.dismissed = nil end end
P.ShowFireTimer = ShowTimer
-- sleeping in your bag away from a fire: the window too (for its countdown)
P:On("PLAYER_UPDATE_RESTING", function() C_Timer.After(0.5, function() if bagLying then ShowTimer() end end) end)

local hadNearby, hadBenefits
local function CampCheck()
	if not P.db then return end
	local near = Aura(CAMP_NEARBY) ~= nil
	local ben = Aura(CAMP_BENEFITS)
	if ben and not hadBenefits and pop and pop:IsShown() then
		HidePop(true)
		P:Toast("Camp buffs: an hour")
	end
	hadBenefits = ben ~= nil
	if near and not hadNearby and S().campfirePop ~= false and not Busy() then
		-- only when camp buffs are gone or nearly, and not twice for the same fire
		local inst, px, py = P:PlayerPos()
		local same = inst and lastPop.inst == inst and (lastPop.x - px) ^ 2 + (lastPop.y - py) ^ 2 < 200 * 200 and GetTime() - lastPop.t < 900
		if Left(ben) < 900 and not same then
			lastPop = { t = GetTime(), inst = inst, x = px or 0, y = py or 0 }
			ShowPop()
		end
	elseif not near and hadNearby then
		HidePop(true)
		HideTimer()
	end
	if near and not (pop and pop:IsShown() and not pop.leaving) then C_Timer.After(0, ShowTimer) end
	hadNearby = near
end
-- a buff that's now on: its item comes off your button
local function BoostCheck()
	if boost.kind == "food" and Left(Aura(WELL_FED_XP)) > 60 then Done("food") end
	if boost and boost.kind == "bag" then
		local a = Aura(WELL_RESTED)
		if a and (a.applications or 1) >= 3 then Done("bag") end
	end
end
-- already by a fire when you log in or /reload: the timer comes up as well
P:On("PLAYER_ENTERING_WORLD", function() C_Timer.After(2, function() if P.db then CampCheck() end end) end)
P:On("UNIT_AURA", function(_, unit)
	if unit ~= "player" then return end
	CampCheck()
	BagCheck()
	if boost then BoostCheck() end
end)
P:On("PLAYER_REGEN_DISABLED", function() HidePop(false) end)
end part() end
-- ==================== Share.lua
do local __addon, __ns = ... local function part()
-- Copyright (C) 2026 SoFinSicc. Part of Pathway (curseforge.com/wow/addons/pathway): free software under the GPLv3 or later, with additional terms that require keeping this credit. See LICENSE.md.
--[[ Pathway — What players learn, shared
     Pathway players on your realm and side tell each other two things, over a
     hidden add-on channel (it never shows in your chat):
       · what quests really pay: the rewards each of you has seen in the quest
         window or your log. Only what you saw yourself is sent, never what you
         heard, and a number has to make sense for the quest before it's kept.
       · campfires: ones you placed or sat at, in the same words CampFirePin
         (BeeTwenty's Campfire add-on) uses on its own channel, so its players
         and Pathway's see each other's fires. They show on the world map and
         the minimap while they burn, then they're gone.
     Nothing about you, your character or where you are goes out; just quest
     numbers and fire spots. Everything kept is tidied as it goes: fires only
     live in memory until they burn out, quest numbers the add-on's own data
     already has are dropped, and the lists never grow past a cap.
     Settings, Quest help: Share with other Pathway players. ]]

local ADDON, P = __addon, __ns
local floor, GetTime, tonumber = math.floor, GetTime, tonumber

local function S() return P.db.settings end
local function On() return P.db and S().share ~= false end

local PREFIX, CHANNEL = "PathwayNet", "PathwayNet"          -- quest rewards
local FIRE_PREFIX, FIRE_CHANNEL = "Campfire1", "CampfireNet"  -- campfires, as CampFirePin shares them
local MAX_PEER = 2000                     -- quest numbers heard from others, at most
local FIRE_LIFE, FIRE_NEAR = 900, 45      -- a fire burns fifteen minutes (the game's data); two spots this close are one fire
P.FIRE_LIFE = FIRE_LIFE

local CI = C_ChatInfo
if CI and CI.RegisterAddonMessagePrefix then pcall(CI.RegisterAddonMessagePrefix, PREFIX); pcall(CI.RegisterAddonMessagePrefix, FIRE_PREFIX) end

---------------------------------------------------------------------------
-- The channel: joined quietly a little after you log in, never shown in chat
---------------------------------------------------------------------------
local joined = false
local function Hide(name)
	for i = 1, (NUM_CHAT_WINDOWS or 10) do
		local f = _G["ChatFrame" .. i]
		if f and ChatFrame_RemoveChannel then pcall(ChatFrame_RemoveChannel, f, name) end
	end
end
local function Index(name)
	local id = GetChannelName and GetChannelName(name)
	return id and id > 0 and id or nil
end
if ChatFrame_AddMessageEventFilter then
	local function quiet(_, _, _, _, _, chan, _, _, _, _, base)
		local n = base or chan
		return type(n) == "string" and (n:find(CHANNEL, 1, true) or n:find(FIRE_CHANNEL, 1, true) or n:find("SmoreSkills", 1, true)) ~= nil
	end
	ChatFrame_AddMessageEventFilter("CHAT_MSG_CHANNEL_NOTICE", quiet)
	ChatFrame_AddMessageEventFilter("CHAT_MSG_CHANNEL_NOTICE_USER", quiet)
end
-- What went over the channels: joined or not, who's been heard and how much was
-- sent. A day's worth, kept small (/pw net shows it).
local function Net()
	local db = P.db
	if not db then return end
	local n = db.net
	if not n or (time() - (n.since or 0)) > 86400 then
		n = { since = time(), joined = {}, heard = {}, sent = {} }
		db.net = n
	end
	return n
end
local function NoteHeard(prefix, who)
	local n = Net()
	if not n then return end
	local h = n.heard[prefix]
	if not h then h = { n = 0, who = {}, players = 0 }; n.heard[prefix] = h end
	h.n, h.last = h.n + 1, time()
	if who and not h.who[who] and h.players < 100 then h.who[who] = true; h.players = h.players + 1 end
end
local function NoteSent(msg) local n = Net(); if n then local k = msg:sub(1, 1) == "F" and "fire" or "quest"; n.sent[k] = (n.sent[k] or 0) + 1 end end
-- the game stopping one of Pathway's channel calls (it says so with an event): kept for /pw net
P:On("ADDON_ACTION_BLOCKED", function(_, who, what)
	if who == ADDON and type(what) == "string" and (what:find("AddonMessage") or what:find("Channel")) then local n = Net(); if n then n.blocked = what end end
end)
P:On("ADDON_ACTION_FORBIDDEN", function(_, who, what)
	if who == ADDON and type(what) == "string" and (what:find("AddonMessage") or what:find("Channel")) then local n = Net(); if n then n.blocked = what end end
end)

local function Join()
	if not On() or not (JoinTemporaryChannel and GetChannelName) then return end
	for _, name in ipairs({ CHANNEL, FIRE_CHANNEL, "SmoreSkills" }) do
		if not Index(name) then pcall(JoinTemporaryChannel, name) end
	end
	C_Timer.After(2, function()
		Hide(CHANNEL); Hide(FIRE_CHANNEL); Hide("SmoreSkills")
		local n = Net()
		if n then n.joined = { [CHANNEL] = Index(CHANNEL) or false, [FIRE_CHANNEL] = Index(FIRE_CHANNEL) or false, at = time() } end
		if Index(CHANNEL) or Index(FIRE_CHANNEL) then joined = true; P:Send("SHARE_READY") end
	end)
end
local function Leave()
	local owner = { [FIRE_CHANNEL] = "Campfire", SmoreSkills = "SmoreSkills" }
	for _, name in ipairs({ CHANNEL, FIRE_CHANNEL, "SmoreSkills" }) do
		-- an add-on that's running keeps its own channel: leave that one to it
		local mine = name == CHANNEL or not (C_AddOns and C_AddOns.IsAddOnLoaded and C_AddOns.IsAddOnLoaded(owner[name]))
		if mine and Index(name) and LeaveChannelByName then pcall(LeaveChannelByName, name) end
	end
	joined = false
end
P:On("PLAYER_LOGIN", function() C_Timer.After(25, Join) end)     -- after the game's own channels
P:Listen("SETTINGS_CHANGED", function() if not P.db then return end if On() then if not joined then Join() end else Leave() end end)

-- a short queue, so a burst never trips the game's limits
local queue, sending = {}, false
local function Pump()
	local item = table.remove(queue, 1)
	if not item then sending = false; return end
	local id = Index(item[3])
	if id and CI and CI.SendAddonMessage and not (CI.InChatMessagingLockdown and CI.InChatMessagingLockdown()) then
		-- the game answers with a result (0 or true: sent); anything else is kept for /pw net
		local ok, res = pcall(CI.SendAddonMessage, item[2], item[1], "CHANNEL", id)
		if ok and (res == nil or res == true or res == 0) then NoteSent(item[1])
		else local n = Net(); if n then n.fail = tostring(ok and res or "error") end end
	end
	C_Timer.After(1.5, Pump)
end
local function Out(msg, fire)
	if not On() or #msg > 250 then return end
	if #queue >= 20 then return end
	queue[#queue + 1] = { msg, PREFIX, CHANNEL }          -- Pathway's own channel only
	if not sending then sending = true; Pump() end
end
P.ShareOut = function(_, msg) Out(msg) end

---------------------------------------------------------------------------
-- Quest rewards
---------------------------------------------------------------------------
-- does a number make sense for this quest? (within a sensible range of what
-- the data says, or of a quest of its level)
local function Plausible(qid, xp)
	local q = P.Q[qid]
	if not q or xp < 10 or xp > 60000 then return false end
	local packed = P.XP and P.XP[qid]
	local base
	if packed then base = floor(packed / 1000)
	else local L = q[P.K.LVL] or 0; if L <= 0 then return xp < 30000 end; base = L * L * 5 + L * 45 + 80 end
	return xp >= base * 0.25 and xp <= base * 5
end
-- what others have seen: votes for up to two numbers a quest, the most-seen wins
function P:PeerXP(qid)
	local t = self.db and self.db.peerXP and self.db.peerXP[qid]
	if not t then return end
	local best, n = nil, 0
	for v, c in pairs(t) do if c > n then best, n = v, c end end
	return best, n
end
local function Heard(qid, xp, sender)
	local db = P.db
	if (db.questXP and db.questXP[qid]) or not Plausible(qid, xp) then return end
	local packed = P.XP and P.XP[qid]
	if packed and floor(packed / 100) % 10 == 1 and floor(packed / 1000) == xp then return end   -- the data has it already
	db.peerXP = db.peerXP or {}
	local t = db.peerXP[qid]
	if not t then
		if (db.peerN or 0) >= MAX_PEER then return end
		t = {}; db.peerXP[qid] = t; db.peerN = (db.peerN or 0) + 1
	end
	if t[xp] then t[xp] = math.min(t[xp] + 1, 99)
	else
		-- two numbers at most: a third replaces the weaker
		local n, weak, wc = 0, nil, nil
		for v, c in pairs(t) do n = n + 1; if not wc or c < wc then weak, wc = v, c end end
		if n >= 2 then t[weak] = nil end
		t[xp] = 1
	end
end

-- yours, as you see them: sent in a batch a minute later
local pending = {}
local function Flush()
	local parts = {}
	for qid, xp in pairs(pending) do
		parts[#parts + 1] = qid .. "=" .. xp
		if #parts >= 18 then Out("X:" .. table.concat(parts, ",")); parts = {} end
	end
	if #parts > 0 then Out("X:" .. table.concat(parts, ",")) end
	wipe(pending)
end
function P:ShareQuestXP(qid, xp)
	if not On() then return end
	pending[qid] = xp
	self:Debounce("sharexp", 60, Flush)
end

-- asking: quests near your level whose real number nobody here has yet
local asked = {}                -- answers we've heard this minute, so others don't repeat them
local function Ask()
	if not On() or not P.Q then return end
	local me, list = P.me.level or 1, {}
	local db = P.db
	for _, qid in ipairs(P:AvailableList()) do
		local packed = P.XP and P.XP[qid]
		local measured = packed and floor(packed / 100) % 10 == 1
		if not measured and not (db.questXP and db.questXP[qid]) and not P:PeerXP(qid) then
			list[#list + 1] = qid
			if #list >= 30 then break end
		end
	end
	if #list > 0 then Out("XQ:" .. table.concat(list, ",")) end
end
-- once in a while, not at every /reload: the answers you got are already saved
P:Listen("SHARE_READY", function()
	if time() - (P.db.askAt or 0) < 900 then return end
	C_Timer.After(30, function() P.db.askAt = time(); Ask() end)
end)
P:On("PLAYER_LEVEL_UP", function() C_Timer.After(20, Ask) end)

local answering = {}
local function Answer(ids)
	local mine = P.db.questXP
	if not mine then return end
	for id in ids:gmatch("%d+") do
		local qid = tonumber(id)
		if mine[qid] then answering[qid] = mine[qid] end
	end
	if not next(answering) then return end
	-- a moment's wait: if someone else answers first, we don't
	P:Debounce("shareanswer", 1 + math.random() * 5, function()
		local parts = {}
		for qid, xp in pairs(answering) do if not asked[qid] then parts[#parts + 1] = qid .. "=" .. xp end end
		wipe(answering)
		for i = 1, #parts, 18 do Out("X:" .. table.concat(parts, ",", i, math.min(#parts, i + 17))) end
	end)
end

---------------------------------------------------------------------------
-- Campfires: kept in memory only, gone when they burn out.
-- Where they come from (src):
--   mine        placed or sat at by you
--   pathway     another Pathway player (Pathway's own channel)
--   campfire    CampFirePin players (BeeTwenty, MIT): heard on its channel, never sent to
--   smore       S'more Skills hosts: heard when they post a camp, never sent to
--   kerzo       a group member running Kerzo Camping Sync placed it: heard, never sent to
--   happycamper Happy Camper's public camp lookup (HappyCamperAPI): read only, credited,
--               and never passed on, as its terms ask
--   guess       "Campfire Nearby" is on you (a fire within ~100 yards, direction unknown):
--               kept for the timer, never drawn on a map, never shared
-- Pathway players share fires only with each other, on Pathway's own channel.
---------------------------------------------------------------------------
local fires = {}                -- { inst, x, y, ends, exact, who, tier, features, placed, seen, src, layer }
P.fireVer = 0
local function Changed() P.fireVer = P.fireVer + 1; P:Send("FIRES_CHANGED") end
local RANK = { guess = 0, happycamper = 1, smore = 2, campfire = 2, kerzo = 3, pathway = 3, mine = 4 }
local function AddFire(inst, x, y, left, exact, who, extra)
	if not (inst and x and y) or left <= 0 then return end
	local now = GetTime()
	local src = extra and extra.src or (exact and "mine" or "guess")
	if not exact and src ~= "guess" then exact = false end
	-- a real fire found: the guesses around it were this one
	if src ~= "guess" then
		for i = #fires, 1, -1 do
			local g = fires[i]
			if g.src == "guess" and g.inst == inst and (g.x - x) ^ 2 + (g.y - y) ^ 2 < 130 * 130 then table.remove(fires, i) end
		end
	end
	for _, f in ipairs(fires) do
		if f.inst == inst and (f.x - x) ^ 2 + (f.y - y) ^ 2 < FIRE_NEAR * FIRE_NEAR then
			-- the same fire: a better spot, a better source or a later end wins
			if exact and not f.exact then f.x, f.y, f.exact = x, y, true end
			if (RANK[src] or 0) > (RANK[f.src] or 0) then f.src = src end
			f.ends = math.max(f.ends, now + left)
			f.seen = now
			if who and not f.who then f.who = who end
			if extra then
				f.tier = extra.tier or f.tier; f.features = extra.features or f.features
				f.placed = f.placed or extra.placed; f.layer = f.layer or extra.layer
			end
			Changed()
			return f, false
		end
	end
	local f = { inst = inst, x = x, y = y, ends = now + left, exact = exact, who = who, seen = now, src = src,
		tier = extra and extra.tier, features = extra and extra.features, placed = extra and extra.placed, layer = extra and extra.layer }
	fires[#fires + 1] = f
	if #fires > 80 then table.remove(fires, 1) end
	Changed()
	return f, true
end
P.AddFireForTest = AddFire
local function Tidy()
	local now, gone = GetTime(), false
	for i = #fires, 1, -1 do if fires[i].ends <= now then table.remove(fires, i); gone = true end end
	if gone then Changed() end
end
C_Timer.NewTicker(30, Tidy)

---------------------------------------------------------------------------
-- Your layer: the zone's own number in the ids of the creatures around you (from
-- your target, mouseover and nameplates). Not in a group, where those can mislead.
---------------------------------------------------------------------------
local layer = { id = nil, map = nil, at = 0 }
local function ReadLayer(unit)
	if IsInGroup and IsInGroup() then return end
	local ok, guid = pcall(UnitGUID, unit)
	if not ok or type(guid) ~= "string" or (issecretvalue and issecretvalue(guid)) then return end
	local kind, _, _, _, zone = strsplit("-", guid)
	if kind ~= "Creature" and kind ~= "Vehicle" then return end
	local z = tonumber(zone)
	if z and z > 0 then
		local map = P:PlayerZone()
		if layer.id ~= z or layer.map ~= map then layer.id, layer.map = z, map; Changed() end
		layer.at = GetTime()
	end
end
P:On("PLAYER_TARGET_CHANGED", function() ReadLayer("target") end)
P:On("UPDATE_MOUSEOVER_UNIT", function() ReadLayer("mouseover") end)
P:On("NAME_PLATE_UNIT_ADDED", function(_, unit) ReadLayer(unit) end)
P:On("ZONE_CHANGED_NEW_AREA", function() layer.id, layer.map = nil, nil end)
-- your layer here, when it's known (nil when not)
function P:MyLayer()
	if layer.id and layer.map == P:PlayerZone() and GetTime() - layer.at < 1800 then return layer.id end
end
-- a fire known to be on another layer than yours
local function OtherLayer(f)
	local mine = P:MyLayer()
	return mine and f.layer and f.layer ~= mine
end
P.FireOtherLayer = OtherLayer

-- the fires on a continent (or all), with minutes left
function P:Campfires(inst)
	local out, now = {}, GetTime()
	for _, f in ipairs(fires) do
		if f.ends > now and (not inst or f.inst == inst) then out[#out + 1] = f end
	end
	return out
end
-- the ones to draw on a map: real fires on your layer (or a layer not known)
function P:FirePins(inst)
	local out = {}
	for _, f in ipairs(P:Campfires(inst)) do
		if f.src ~= "guess" and not OtherLayer(f) then out[#out + 1] = f end
	end
	return out
end
-- the fire you're at: the nearest known one within reach, yours or one on your layer
-- first. known = its end is sure (it was seen placed)
function P:FireHere()
	local inst, px, py = P:PlayerPos()
	if not inst then return end
	local best, bd = nil, nil
	for _, f in ipairs(P:Campfires(inst)) do
		local reach = f.src == "guess" and FIRE_NEAR * 1.5 or 110
		local d = (f.x - px) ^ 2 + (f.y - py) ^ 2
		if d < reach * reach and not OtherLayer(f) then
			-- a real fire beats a guess; then the nearest
			local score = d + (f.src == "guess" and 1e6 or 0)
			if not bd or score < bd then best, bd = f, score end
		end
	end
	if best then return best, best.placed ~= nil end
end

-- What Pathway players tell each other, on Pathway's channel only:
--   F:inst;x;y;tier;age;placedAge;layer;features   (Pathway's own x and y, ages in seconds,
--                                                   placedAge -1 / layer 0 when unknown)
--   FG:inst;x;y                                    burnt out or gone
--   FR                                             which fires are burning?
-- Shared: fires stood at (yours) and ones heard from CampFirePin, S'more Skills or a Kerzo
-- group. Never a guess, and never one only Happy Camper's lookup knows.
local TIER = { B = "Basic", J = "Journeyman", E = "Expert" }
local TIER_CODE = { Basic = "B", Journeyman = "J", Expert = "E" }
local SHAREABLE = { mine = true, campfire = true, smore = true, kerzo = true }
local function Tell(f, relay)
	if not (f and f.exact and SHAREABLE[f.src]) then return end
	local now = GetTime()
	Out(("F:%d;%.1f;%.1f;%s;%d;%d;%d;%s"):format(f.inst, f.x, f.y, TIER_CODE[f.tier] or "", floor(now - (f.seen or now)),
		f.placed and floor(now - f.placed) or -1, f.layer or 0, (f.features or ""):gsub("[;:]", " "):sub(1, 120)))
	f.told = now
end
-- a fire heard from another add-on: passed to Pathway players a moment later, unless one of
-- them already did (everyone hears the same thing; one telling is enough)
local function Relay(f)
	if not (f and SHAREABLE[f.src]) or f.src == "mine" then return end
	C_Timer.After(2 + math.random() * 6, function()
		if GetTime() - (f.heardPW or -1e9) > 20 and GetTime() - (f.told or -1e9) > 60 then Tell(f, true) end
	end)
end
local lastReply = -1e9
local function ReplyAll()
	if GetTime() - lastReply < 30 then return end
	lastReply = GetTime()
	local n = 0
	for _, f in ipairs(P:Campfires()) do
		if GetTime() - (f.heardPW or 0) > 8 then Tell(f); n = n + 1; if n >= 10 then break end end
	end
end
local function Gone(inst, x, y)
	for i = #fires, 1, -1 do
		local f = fires[i]
		if f.inst == inst and (f.x - x) ^ 2 + (f.y - y) ^ 2 < 20 * 20 and GetTime() - (f.mine or -1e9) > 10 then table.remove(fires, i); Changed() end
	end
end
-- a /reload keeps the fires you knew: saved as you go, brought back as you load, and the
-- save is let go right after. Asking the channel again isn't needed straight after one.
-- Happy Camper's are never saved (its lookup is asked again).
P:On("PLAYER_LOGOUT", function()
	if not P.db then return end
	local now, list = GetTime(), {}
	for _, f in ipairs(P:Campfires()) do
		if f.src ~= "happycamper" then
			list[#list + 1] = { f.inst, f.x, f.y, floor(f.ends - now), f.exact or nil, f.who, f.tier, f.features,
				f.placed and floor(now - f.placed) or nil, f.mine and true or nil, f.src, f.layer }
		end
	end
	P.db.fireKeep = #list > 0 and { at = time(), list = list } or nil
end)
local fireAsked
P:Listen("READY", function()
	local keep = P.db.fireKeep
	P.db.fireKeep = nil
	if not keep or type(keep.list) ~= "table" then return end
	local gone = time() - (keep.at or 0)
	if gone < 0 or gone > FIRE_LIFE then return end
	fireAsked = gone < 300
	local now = GetTime()
	for _, k in ipairs(keep.list) do
		local src = k[11] or (k[5] and (k[6] and "pathway" or "mine") or "guess")
		local f = AddFire(k[1], k[2], k[3], (k[4] or 0) - gone, k[5], k[6], { tier = k[7], features = k[8],
			placed = k[9] and now - k[9] - gone, src = src, layer = k[12] })
		if f and k[10] then f.mine = now end
	end
end)
P:Listen("SHARE_READY", function() if not fireAsked then Out("FR") end end)   -- what fires are burning? (once you've joined)

-- finding them yourself: placing one, sitting at one, walking past one
local CAMP_BENEFITS, CAMP_NEARBY = 1229741, 1283391
-- the same look as the campfire pop-up: by the buff's id, then by its name (so a
-- different id in the game can't hide the fire)
local function Has(id)
	if P.BoostAura then return P:BoostAura(id) ~= nil end
	local U = C_UnitAuras
	if U and U.GetPlayerAuraBySpellID then local ok, a = pcall(U.GetPlayerAuraBySpellID, id); return ok and a ~= nil end
end
-- you're by a fire Pathway didn't know: noted as a guess where you are (for the timer
-- only: the fire is somewhere within ~100 yards, so it's never put on a map)
function P:NoteFireHere()
	local inst, px, py = P:PlayerPos()
	if inst and not P:FireHere() then AddFire(inst, px, py, FIRE_LIFE, false, nil, { src = "guess", layer = P:MyLayer() }) end
	return P:FireHere()
end
local hadNear, hadBen
P:On("UNIT_AURA", function(_, unit)
	if unit ~= "player" or not P.db then return end
	local near, ben = Has(CAMP_NEARBY), Has(CAMP_BENEFITS)
	local inst, px, py = P:PlayerPos()
	-- a town's own campfire never burns out: nothing to note, time or tell anyone
	local town = (near or ben) and P.CampInTown and P.CampInTown()
	if inst and not town then
		if ben and not hadBen then
			-- you sat at it: it's right here (within a few yards)
			local f = AddFire(inst, px, py, FIRE_LIFE * 0.7, true, nil, { src = "mine", layer = P:MyLayer() })
			if f then f.mine = GetTime(); Tell(f) end
		end
		if near and not hadNear and not P:FireHere() then
			-- a fire you've just come near: somewhere within ~100 yards, at most a whole fire's life left
			AddFire(inst, px, py, FIRE_LIFE, false, nil, { src = "guess", layer = P:MyLayer() })
		end
	end
	hadNear, hadBen = near, ben
end)
P:On("UNIT_SPELLCAST_SUCCEEDED", function(_, unit, _, spellID)
	if unit ~= "player" or not P.db then return end
	local name = spellID and ((C_Spell and C_Spell.GetSpellName and C_Spell.GetSpellName(spellID)) or (GetSpellInfo and GetSpellInfo(spellID)))
	if not (name and name:find("Campfire", 1, true)) then return end
	-- making a Campfire Kit (or anything else with the word in it) isn't placing one
	if name:find("Kit", 1, true) then return end
	local inst, px, py = P:PlayerPos()
	if not inst then return end
	-- it only counts once the fire's own buff is on you: a real fire, right here
	local tier = name:match("^(%a+) Campfire")
	local tries = 0
	local function Check()
		tries = tries + 1
		if not Has(CAMP_NEARBY) then
			if tries < 6 then C_Timer.After(1, Check) end
			return
		end
		local f = AddFire(inst, px, py, FIRE_LIFE, true, nil, { tier = TIER_CODE[tier] and tier or nil, placed = GetTime() - tries, src = "mine", layer = P:MyLayer() })
		if f then f.mine = GetTime(); Tell(f) end
	end
	C_Timer.After(1, Check)
end)

---------------------------------------------------------------------------
-- What comes in
---------------------------------------------------------------------------
-- a sender says at most 30 things a minute, as CampFirePin allows
local budget = {}
local function Allowed(who)
	local now, b = GetTime(), budget[who]
	if not b or now - b[1] > 60 then b = { now, 0 }; budget[who] = b end
	b[2] = b[2] + 1
	return b[2] <= 30
end
C_Timer.NewTicker(120, function() local now = GetTime(); for k, b in pairs(budget) do if now - b[1] > 60 then budget[k] = nil end end end)

local function Coords(inst, x, y) return inst and x and y and inst >= 0 and math.abs(x) < 50000 and math.abs(y) < 50000 end
local function Feats(g) return g and g ~= "" and g:gsub("[^%w %-',]", ""):sub(1, 150) or nil end

-- Pathway players
local function PathwayFire(kind, body, who)
	if kind == "FR" then C_Timer.After(1 + math.random() * 4, ReplyAll) return end
	local a, b, c, d, e, f, g, h = strsplit(";", body or "")
	local inst, x, y = tonumber(a), tonumber(b), tonumber(c)
	if not Coords(inst, x, y) then return end
	if kind == "FG" then Gone(inst, x, y) return end
	local age, placedAge, lay = tonumber(e), tonumber(f), tonumber(g)
	if not age or age < 0 or age > FIRE_LIFE then return end
	local left = (placedAge and placedAge >= 0) and (FIRE_LIFE - placedAge) or (FIRE_LIFE - age)
	local fire = AddFire(inst, x, y, math.min(left, FIRE_LIFE), true, who, { tier = TIER[d], features = Feats(h),
		placed = (placedAge and placedAge >= 0) and GetTime() - placedAge or nil, src = "pathway", layer = (lay and lay > 0) and lay or nil })
	if fire then fire.heardPW = GetTime(); fire.seen = GetTime() - age end
end

-- CampFirePin: C;inst;x;y;tier;age;placedAge;features, its x north (Pathway's y), its y west
-- (Pathway's x). Listened to only: Pathway doesn't answer on its channel.
local function CampfireMessage(msg, who)
	local kind, a, b, c, d, e, f, g = strsplit(";", msg)
	local inst, nx, wy = tonumber(a), tonumber(b), tonumber(c)
	if not Coords(inst, nx, wy) then return end
	if kind == "C" then
		local age, placedAge = tonumber(e), tonumber(f)
		if not age or age < 0 or age > FIRE_LIFE then return end
		local left = (placedAge and placedAge >= 0) and (FIRE_LIFE - placedAge) or (FIRE_LIFE - age)
		local fire, new = AddFire(inst, wy, nx, math.min(left, FIRE_LIFE), true, who, { tier = TIER[d], features = Feats(g),
			placed = (placedAge and placedAge >= 0) and GetTime() - placedAge or nil, src = "campfire" })
		if fire then fire.seen = GetTime() - age; if new then Relay(fire) end end
	elseif kind == "G" then
		Gone(inst, wy, nx)
	end
end

-- S'more Skills: a host posting a camp: H:map:x:y:faction:owner:want:slots...:litAt:layer[/n]
-- (zone-map position x 10000, lit at in server time). Listened to only.
local SMORE_PREFIX, SMORE_CHANNEL = "SmoreSk", "SmoreSkills"
local function SmoreMessage(text, who)
	local parts = { strsplit(":", text) }
	if parts[1] ~= "H" or #parts < 14 then return end
	local map, mx, my = tonumber(parts[2]), tonumber(parts[3]), tonumber(parts[4])
	local fac = parts[5] and parts[5]:gsub(";", ":")
	if not (map and mx and my) then return end
	local mine = UnitFactionGroup and UnitFactionGroup("player")
	if fac and fac ~= "-" and mine and fac ~= mine then return end
	local n = #parts
	local lit, lay
	if n >= 15 then
		lay = tonumber((parts[n]:match("^(%d+)")))
		lit = tonumber(parts[n - 1])
	else
		lit = tonumber(parts[n])
	end
	local inst, x, y = P:WorldPos(map, mx / 10000, my / 10000)
	if not Coords(inst, x, y) then return end
	local age = lit and (time() - lit) or nil
	if age and (age < 0 or age > FIRE_LIFE) then return end
	local left = age and (FIRE_LIFE - age) or FIRE_LIFE * 0.6
	local fire, new = AddFire(inst, x, y, left, true, who, { placed = age and GetTime() - age or nil, src = "smore",
		layer = (lay and lay > 0) and lay or nil })
	if fire and new then Relay(fire) end
end

-- Kerzo Camping Sync, in your group: "2:F:tier:placedAt" then "2:M:map:x:y" (zone-map
-- position x 10000, placed at in server time). Listened to only.
local KERZO_PREFIX = "KCS2"
local kerzoFire = {}
local function KerzoMessage(text, who)
	local ver, kind, a, b, c = strsplit(":", text)
	if ver ~= "2" then return end
	if kind == "F" then
		kerzoFire[who] = { tier = tonumber(a), at = tonumber(b), t = GetTime() }
	elseif kind == "M" then
		local f = kerzoFire[who]
		kerzoFire[who] = nil
		local map, mx, my = tonumber(a), tonumber(b), tonumber(c)
		if not (f and GetTime() - f.t < 30 and map and mx and my) then return end
		local inst, x, y = P:WorldPos(map, mx / 10000, my / 10000)
		if not Coords(inst, x, y) then return end
		local age = f.at and (time() - f.at) or 0
		if age < 0 or age > FIRE_LIFE then return end
		local names = { "Basic", "Journeyman", "Expert" }
		local fire, new = AddFire(inst, x, y, FIRE_LIFE - age, true, who, { tier = names[f.tier or 0], placed = GetTime() - age, src = "kerzo" })
		if fire and new then Relay(fire) end
	end
end

-- Happy Camper: its public camp lookup only (HappyCamperAPI, which its author lets any add-on
-- read). Read-only, shown with its credit, never saved or passed on. Its camp channel and
-- internals are not touched: those need its author's permission.
local function ReadHappyCamper()
	local api = _G.HappyCamperAPI
	if not (api and type(api.GetNearbyCamps) == "function" and (tonumber(api.version) or 0) >= 1) then return end
	local ok, camps = pcall(api.GetNearbyCamps)
	if not ok or type(camps) ~= "table" then return end
	for _, c in ipairs(camps) do
		if type(c) == "table" and c.mapID and c.x and c.y then
			local inst, x, y = P:WorldPos(c.mapID, c.x, c.y)
			if Coords(inst, x, y) then
				local left = tonumber(c.timeLeft)
				local feats = {}
				for _, o in ipairs(type(c.objects) == "table" and c.objects or {}) do if o.name then feats[#feats + 1] = o.name end end
				local fire = AddFire(inst, x, y, left or FIRE_LIFE * 0.5, true, nil, { src = "happycamper",
					features = #feats > 0 and table.concat(feats, ", ") or nil, layer = tonumber(c.layer),
					placed = left and GetTime() - (FIRE_LIFE - left) or nil })
				if fire then fire.hc = true end
			end
		end
	end
end
C_Timer.NewTicker(15, function() if P.db and S().firePins ~= false then ReadHappyCamper() end end)
P.ReadHappyCamper = ReadHappyCamper

-- the other add-ons' words: their prefixes, registered so the game passes them on
if CI and CI.RegisterAddonMessagePrefix then pcall(CI.RegisterAddonMessagePrefix, SMORE_PREFIX); pcall(CI.RegisterAddonMessagePrefix, KERZO_PREFIX) end

P:On("CHAT_MSG_ADDON", function(_, prefix, msg, dist, sender)
	if not (P.db and On() and msg) then return end
	if prefix ~= PREFIX and prefix ~= FIRE_PREFIX and prefix ~= SMORE_PREFIX and prefix ~= KERZO_PREFIX then return end
	if (issecretvalue and (issecretvalue(msg) or issecretvalue(sender))) then return end
	local me = UnitName("player")
	local who = sender and (Ambiguate and Ambiguate(sender, "short") or sender:match("^[^-]+"))
	if who == me or not Allowed(who or "?") then return end
	NoteHeard(prefix, who)
	if prefix == FIRE_PREFIX then CampfireMessage(msg, who) return end
	if prefix == SMORE_PREFIX then SmoreMessage(msg, who) return end
	if prefix == KERZO_PREFIX then KerzoMessage(msg, who) return end
	if msg == "FR" then PathwayFire("FR", nil, who) return end
	local kind, body = msg:match("^(%a+):(.*)$")
	if kind == "F" or kind == "FG" then PathwayFire(kind, body, who)
	elseif kind == "X" then
		for q, x in body:gmatch("(%d+)=(%d+)") do
			q, x = tonumber(q), tonumber(x)
			asked[q] = true
			Heard(q, x, who)
		end
		P:Debounce("shareasked", 60, function() wipe(asked) end)
	elseif kind == "XQ" then
		Answer(body)
	end
end)
-- S'more Skills hosts also post camps as channel chat ("SmoreSk H:..."): read, and kept out of your chat
P:On("CHAT_MSG_CHANNEL", function(_, text, sender, _, _, _, _, _, _, chan)
	if not (P.db and On()) or type(text) ~= "string" or (issecretvalue and issecretvalue(text)) then return end
	if type(chan) ~= "string" or not chan:lower():find(SMORE_CHANNEL:lower(), 1, true) then return end
	if text:sub(1, #SMORE_PREFIX) ~= SMORE_PREFIX then return end
	local who = sender and (Ambiguate and Ambiguate(sender, "short") or sender:match("^[^-]+"))
	if who == UnitName("player") or not Allowed(who or "?") then return end
	NoteHeard(SMORE_PREFIX, who)
	SmoreMessage(strtrim(text:sub(#SMORE_PREFIX + 1)), who)
end)
if ChatFrame_AddMessageEventFilter then
	ChatFrame_AddMessageEventFilter("CHAT_MSG_CHANNEL", function(_, _, text, _, _, _, _, _, _, _, chan)
		return type(chan) == "string" and chan:lower():find(SMORE_CHANNEL:lower(), 1, true) ~= nil
	end)
end

---------------------------------------------------------------------------
-- Tidying at login: what the add-on's own data now has needn't be kept twice
---------------------------------------------------------------------------
P:On("PLAYER_LOGIN", function()
	C_Timer.After(10, function()
		local db = P.db
		if not (db and P.XP) then return end
		local n = 0
		-- the same number the data has now (Forever's own): no need to keep it twice. A different
		-- one stays: the game may have changed since the data was made.
		local function same(qid, xp)
			local packed = P.XP[qid]
			return packed and floor(packed / 100) % 10 == 1 and floor(packed / 1000) == xp
		end
		for qid, xp in pairs(db.questXP or {}) do
			if same(qid, xp) or not P.Q[qid] then db.questXP[qid] = nil end
		end
		for qid in pairs(db.peerXP or {}) do
			local best = P:PeerXP(qid)
			if not P.Q[qid] or same(qid, best) then db.peerXP[qid] = nil else n = n + 1 end
		end
		-- what you saw yourself makes what you heard unneeded
		for qid in pairs(db.questXP or {}) do if db.peerXP and db.peerXP[qid] then db.peerXP[qid] = nil; n = n - 1 end end
		db.peerN = math.max(0, n)
		if db.peerXP and not next(db.peerXP) then db.peerXP = nil end
		if db.questXP and not next(db.questXP) then db.questXP = nil end
	end)
end)

---------------------------------------------------------------------------
-- Questie, when it's installed: its quest experience can be newer than the copy
-- Pathway ships (it's the same QuestieDB, updated more often). Where it has a
-- different number for a quest Pathway only knows the old world's reward for,
-- that number is Forever's own, measured in play: Pathway uses it. In memory
-- only, nothing saved.
---------------------------------------------------------------------------
P:On("PLAYER_LOGIN", function()
	C_Timer.After(8, function()
		local QL = _G.QuestieLoader
		if not (QL and QL.ImportModule and P.XP) then return end
		local ok, mod = pcall(QL.ImportModule, QL, "QuestXP")
		local db = ok and type(mod) == "table" and mod.db
		if type(db) ~= "table" then return end
		local n = 0
		for qid, row in pairs(db) do
			if type(qid) == "number" and type(row) == "table" then
				local lvl, xp = tonumber(row[1]), tonumber(row[2])
				local ours = P.XP[qid]
				local oursMeasured = ours and floor(ours / 100) % 10 == 1
				if lvl and xp and xp > 0 and lvl > 0 and lvl < 100 and not oursMeasured and (not ours or floor(ours / 1000) ~= xp) then
					P.XP[qid] = xp * 1000 + 100 + lvl
					n = n + 1
				end
			end
		end
		if n > 0 then P.questieXP = n end
	end)
end)

-- /pw net: are we reaching anyone?
local function Ago(t)
	if not t then return "never" end
	local m = floor((time() - t) / 60)
	if m < 1 then return "just now" elseif m < 60 then return m .. " min ago" end
	return floor(m / 60) .. " h ago"
end
function P:NetReport()
	if not On() then P:Print("Sharing is off (Settings, Quest help: Share with other Pathway players).") return end
	local n = Net() or { joined = {}, heard = {}, sent = {} }
	local function chan(name) local id = Index(name) return id and ("joined (#" .. id .. ")") or "|cffff6060not joined|r" end
	P:Print(("Sharing: %s %s. Listening: %s %s, %s %s."):format(CHANNEL, chan(CHANNEL), FIRE_CHANNEL, chan(FIRE_CHANNEL), SMORE_CHANNEL, chan(SMORE_CHANNEL)))
	print(("   Heard since %s:"):format(date("%H:%M", n.since or time())))
	for _, row in ipairs({ { PREFIX, "Pathway players" }, { FIRE_PREFIX, "CampFirePin players" }, { SMORE_PREFIX, "S'more Skills hosts" }, { KERZO_PREFIX, "Kerzo Camping Sync (group)" } }) do
		local h = n.heard[row[1]] or { n = 0, players = 0 }
		print(("     %s: %d (%d messages, last %s)"):format(row[2], h.players, h.n, Ago(h.last)))
	end
	local hc = 0
	for _, f in ipairs(P:Campfires()) do if f.src == "happycamper" then hc = hc + 1 end end
	print(("     Happy Camper (its camp lookup): %s"):format(_G.HappyCamperAPI and (hc .. " camps near you") or "not installed"))
	print(("   Sent to Pathway players: %d quest messages, %d fire messages. Fires known now: %d (on the map: %d)."):format(
		n.sent.quest or 0, n.sent.fire or 0, #P:Campfires(), #P:FirePins()))
	local lay = P:MyLayer()
	print("   Your layer: " .. (lay and tostring(lay) or "not known yet (target or mouse over a creature)"))
	if n.fail then print("   |cffff6060The game refused the last message: " .. n.fail .. "|r") end
	if n.blocked then print("   |cffff6060The game blocked: " .. n.blocked .. "|r") end
end
end part() end
-- ==================== QuestDelete.lua
do local __addon, __ns = ... local function part()
-- Copyright (C) 2026 SoFinSicc. Part of Pathway (curseforge.com/wow/addons/pathway): free software under the GPLv3 or later, with additional terms that require keeping this credit. See LICENSE.md.
--[[ Pathway — Delete quests, from the quest log
     A "Delete" button on Forever's Map & Quest Log, beside the search box. Click it and a small panel
     slides out beside the log, and every quest in the log gets a tick box:
       · Delete all: every quest in your log
       · Keep the best: keeps your top 25% by experience, deletes the rest.
         Hover it to see which ones would go.
       · or tick the ones to go: the panel counts them and offers to delete
         exactly those
     A quest that's ready to hand in is never deleted, whichever you pick: that
     experience is already yours. It gets a green mark instead of a tick box,
     and the panel says how many it's keeping.
     Every delete asks once more on the same button (click again within a few
     seconds), then the quests go one by one, smoothly, with a bar showing how
     far along it is. Nothing is saved: ticks last while the panel is open.
     Settings, Quest help: Delete quests button. ]]

local ADDON, P = __addon, __ns
local floor, ceil, GetTime = math.floor, math.ceil, GetTime

local function S() return P.db.settings end

local RED = { 0.93, 0.33, 0.3 }
local RED_BG = { 0.28, 0.07, 0.06, 1 }
local KEEP_SHARE = 0.25                 -- "keep the best": the top quarter by experience
local CONFIRM_FOR = 3.5                 -- seconds a "click again" stays armed

local mode = false                      -- the panel's open and the tick boxes show
local ticked = {}                       -- [questID] = true
local preview                           -- the quests a hovered button would delete: [questID] = true
local panel, button, checks = nil, nil, {}
local busy                              -- { ids, i, done, cant, left, tries, wait } while deleting
local hand                              -- quests left for you to say Yes to, one box at a time

---------------------------------------------------------------------------
-- The quests in your log, with what each pays
---------------------------------------------------------------------------
-- ready to hand in: Pathway's log, or the game's word for it
local function Ready(qid)
	local e = P.log[qid]
	if e and e.complete then return true end
	local ok, r = pcall(C_QuestLog.ReadyForTurnIn or C_QuestLog.IsComplete, qid)
	return ok and r == true
end
local function LogQuests()
	local out = {}
	for i = 1, (C_QuestLog.GetNumQuestLogEntries() or 0) do
		local info = C_QuestLog.GetInfo(i)
		local qid = info and not info.isHeader and info.questID
		if qid and qid > 0 then
			local e = P.log[qid]
			out[#out + 1] = { id = qid, index = i, title = info.title, done = Ready(qid) and true or false, xp = P:QuestXP(qid) or 0 }
		end
	end
	return out
end
-- all but the best quarter (and anything ready to hand in: that's experience waiting)
local function AllButBest()
	local list = LogQuests()
	local keep = ceil(#list * KEEP_SHARE)
	table.sort(list, function(a, b) if a.xp ~= b.xp then return a.xp > b.xp end return a.index < b.index end)
	local go = {}
	for i, q in ipairs(list) do
		if i > keep and not q.done then go[#go + 1] = q.id end
	end
	return go, keep
end
local function AllIDs()
	local go, ready = {}, 0
	for _, q in ipairs(LogQuests()) do if q.done then ready = ready + 1 else go[#go + 1] = q.id end end
	return go, ready
end
local function TickedIDs()
	local go, have = {}, {}
	for _, q in ipairs(LogQuests()) do have[q.id] = true end
	for qid in pairs(ticked) do if have[qid] and not Ready(qid) then go[#go + 1] = qid else ticked[qid] = nil end end
	return go
end
local function AsSet(ids) local s = {}; for _, id in ipairs(ids) do s[id] = true end return s end

---------------------------------------------------------------------------
-- The tick boxes: one in the gap at the left of each quest row (where a
-- header's +/- sits), only while the panel is open
---------------------------------------------------------------------------
local function MapLog() return QuestMapFrame and QuestScrollFrame and QuestScrollFrame.titleFramePool end
local function LogShown() return MapLog() and QuestMapFrame:IsVisible() end
-- the quest rows showing now: { row, questID }
local function Rows()
	local out = {}
	if not MapLog() then return out end
	for row in QuestScrollFrame.titleFramePool:EnumerateActive() do
		if row.questID and row:IsShown() then out[#out + 1] = { row, row.questID } end
	end
	return out
end

local Refresh, UpdatePanel
local function Check(row)
	local c = checks[row]
	if c then return c end
	c = CreateFrame("Button", nil, row)
	c:SetSize(14, 14)
	-- over the quest's round icon at the left of its row, while deleting
	c:SetPoint("TOPLEFT", row, "TOPLEFT", 9, -9)
	c.cover = c:CreateTexture(nil, "BACKGROUND"); c.cover:SetPoint("CENTER"); c.cover:SetSize(24, 24)
	c.cover:SetTexture(P.MEDIA .. "Dot"); c.cover:SetVertexColor(0.07, 0.06, 0.05, 1)
	c:SetFrameLevel(row:GetFrameLevel() + 30)
	c.box = c:CreateTexture(nil, "ARTWORK"); c.box:SetAllPoints(); c.box:SetColorTexture(0.05, 0.05, 0.06, 0.9)
	c.edge = c:CreateTexture(nil, "BORDER"); c.edge:SetPoint("TOPLEFT", -1, 1); c.edge:SetPoint("BOTTOMRIGHT", 1, -1)
	c.edge:SetColorTexture(0.45, 0.47, 0.5, 0.9)
	c.ready = c:CreateTexture(nil, "OVERLAY"); c.ready:SetTexture("Interface\\RaidFrame\\ReadyCheck-Ready")
	c.ready:SetPoint("CENTER"); c.ready:SetSize(14, 14)
	c.mark = c:CreateTexture(nil, "OVERLAY"); c.mark:SetTexture("Interface\\Buttons\\UI-CheckBox-Check")
	c.mark:SetPoint("CENTER", 1, 0); c.mark:SetSize(18, 18); c.mark:SetVertexColor(RED[1], RED[2], RED[3])
	-- a little pop when it's ticked
	local g = c.mark:CreateAnimationGroup()
	local s1 = g:CreateAnimation("Scale"); s1:SetScaleFrom(0.4, 0.4); s1:SetScaleTo(1.15, 1.15); s1:SetDuration(0.12); s1:SetOrder(1)
	local s2 = g:CreateAnimation("Scale"); s2:SetScaleFrom(1.15, 1.15); s2:SetScaleTo(1, 1); s2:SetDuration(0.08); s2:SetOrder(2)
	c.pop = g
	-- the row turns a soft red while it's set to go
	c.tint = row:CreateTexture(nil, "BACKGROUND", nil, -1)
	c.tint:SetPoint("TOPLEFT", row, "TOPLEFT", 0, 0); c.tint:SetPoint("BOTTOMRIGHT", row, "BOTTOMRIGHT", 0, 0)
	c.tint:SetAlpha(0)
	c.tint:SetColorTexture(RED[1], RED[2], RED[3], 0.16)
	c:SetScript("OnEnter", function(self)
		self.edge:SetColorTexture(RED[1], RED[2], RED[3], 1)
		if self.qid then
			GameTooltip:SetOwner(self, "ANCHOR_LEFT")
			if Ready(self.qid) then
				GameTooltip:SetText("Ready to hand in", 0.49, 0.95, 0.61)
				GameTooltip:AddLine("Always kept: its experience is already yours.", 0.8, 0.8, 0.8, true)
			else
				GameTooltip:SetText(ticked[self.qid] and "Set to delete" or "Tick to delete", 1, 1, 1)
			end
			local xp = P:QuestXP(self.qid) or 0
			if xp > 0 then GameTooltip:AddLine(P.Short(xp) .. " XP", 0.7, 0.7, 0.7) end
			GameTooltip:Show()
		end
	end)
	c:SetScript("OnLeave", function(self) self.edge:SetColorTexture(0.45, 0.47, 0.5, 0.9); GameTooltip:Hide() end)
	c:SetScript("OnClick", function(self)
		if P:QuestDeleteTick(self.qid) then self.pop:Play() end
	end)
	checks[row] = c
	return c
end

-- tick or untick a quest; true when it's now ticked
function P:QuestDeleteTick(qid)
	if busy or not qid then return end
	if Ready(qid) then return end                -- ready to hand in: kept, always
	if ticked[qid] then ticked[qid] = nil else ticked[qid] = true end
	PlaySound(SOUNDKIT.IG_MAINMENU_OPTION_CHECKBOX_ON or 856)
	Refresh(); UpdatePanel()
	return ticked[qid]
end

function Refresh()
	for _, c in pairs(checks) do c:Hide(); c.qid = nil; c.tint:SetAlpha(0) end
	if not mode then return end
	for _, r in ipairs(Rows()) do
		local row, qid = r[1], r[2]
		local c = Check(row)
		c.qid = qid
		c:Show()
		local ready = Ready(qid)
		local on = not ready and ticked[qid]
		c.mark:SetShown(on and true or false)
		c.ready:SetShown(ready and true or false)
		c.box:SetShown(not ready); c.edge:SetShown(not ready)
		local alpha = on and 0.16 or (preview and preview[qid]) and 0.09 or 0
		c.tint:SetAlpha(alpha > 0 and 1 or 0)
		c.tint:SetColorTexture(RED[1], RED[2], RED[3], alpha)
	end
end

---------------------------------------------------------------------------
-- Deleting. Forever only lets a quest go from something you did: the well-known
-- macro works because it runs straight off your key press, all in one go. So the
-- quests are dropped inside your click, the same way, and the timers only check
-- the log afterwards. Anything still there gets the next way on your next click
-- ("Try again"), and the last resort is the game's own Abandon box, one Yes each.
---------------------------------------------------------------------------
local VERIFY = 1.2                      -- seconds for the log to catch up before checking
local POPUPS = { "ABANDON_QUEST", "ABANDON_QUEST_WITH_ITEMS" }

local function InLog(qid)
	local i = C_QuestLog.GetLogIndexForQuestID and C_QuestLog.GetLogIndexForQuestID(qid)
	return (tonumber(i) or 0) > 0
end
local function CanDrop(qid)
	if not C_QuestLog.CanAbandonQuest then return true end
	local ok, can = pcall(C_QuestLog.CanAbandonQuest, qid)
	return not (ok and can == false)
end
local function Popup()
	if not StaticPopup_FindVisible then return end
	for _, w in ipairs(POPUPS) do local d = StaticPopup_FindVisible(w); if d then return d, w end end
end
local function HidePopups() if StaticPopup_Hide then for _, w in ipairs(POPUPS) do StaticPopup_Hide(w) end end end

-- each runs inside your click, for one quest, with nothing waited on
local WAYS = {
	-- 1. the macro everyone uses: pick it, mark it, drop it
	function(qid)
		C_QuestLog.SetSelectedQuest(qid); C_QuestLog.SetAbandonQuest(); C_QuestLog.AbandonQuest()
	end,
	-- 2. Blizzard's own Abandon, from the quest's menu, and its Yes
	function(qid)
		QuestMapQuestOptions_AbandonQuest(qid)
		local d = Popup()
		if d then StaticPopup_OnClick(d, 1) end
		HidePopups()
	end,
	-- 3. the Abandon button on the quest's own page in the Map & Quest Log, and its Yes
	function(qid)
		QuestMapFrame_ShowQuestDetails(qid)
		QuestMapFrame.DetailsFrame.AbandonButton:Click()
		local d = Popup()
		if d then StaticPopup_OnClick(d, 1) end
		HidePopups()
		if QuestMapFrame_ReturnFromQuestDetails then QuestMapFrame_ReturnFromQuestDetails() end
	end,
}

-- the way that worked last goes first, then the rest in order
local function Order()
	local first, out = P.db.abandonWay, {}
	if WAYS[first or 0] then out[1] = first end
	for i = 1, #WAYS do if i ~= first then out[#out + 1] = i end end
	return out
end

local ByHand, Verify
local function Finish()
	local b = busy
	busy = nil
	wipe(ticked)
	local n = b and b.done or 0
	local text = ("Deleted %d quest%s"):format(n, n == 1 and "" or "s")
	if b and b.cant > 0 then text = text .. (", %d can't be dropped"):format(b.cant) end
	P:Toast(text)
	if panel then panel.doneText = text; panel.doneAt = GetTime() end
	UpdatePanel(); Refresh()
	if b and b.left and #b.left > 0 then ByHand(b.left) end
end

-- one way, for every quest still to go, all inside this click
local function Round()
	local way = table.remove(busy.tries, 1)
	busy.way, busy.waiting = way, false
	busy.round = busy.round + 1
	for _, qid in ipairs(busy.ids) do
		if InLog(qid) then pcall(WAYS[way], qid) end
	end
	busy.checkAt = GetTime() + VERIFY
	UpdatePanel()
	local token = {}
	busy.token = token
	C_Timer.After(VERIFY, function() if busy and busy.token == token then Verify() end end)
end

function Verify()
	local left = {}
	for _, qid in ipairs(busy.ids) do if InLog(qid) then left[#left + 1] = qid end end
	local gone = #busy.ids - #left
	busy.done = busy.done + gone
	if gone > 0 then P.db.abandonWay = busy.way end
	busy.ids = left
	if #left == 0 then Finish() return end
	if #busy.tries > 0 then
		-- your next click tries the next way: it has to come from you
		busy.waiting = true
		UpdatePanel()
	else
		busy.left = left
		Finish()
	end
end
local function Retry() if busy and busy.waiting then Round() end end

-- the quest log tells us the moment each one goes: the bar fills as it does
P:On("QUEST_REMOVED", function(_, qid)
	if busy and not busy.waiting then busy.seen = busy.seen + 1; UpdatePanel() end
	if hand and hand[1] == qid then table.remove(hand, 1); C_Timer.After(0.15, ByHand) end
end)

-- the last resort: the game's own box, one quest at a time; Yes drops it, No stops
function ByHand(list)
	if list then hand = list end
	if not hand then return end
	while hand[1] and not InLog(hand[1]) do table.remove(hand, 1) end
	local qid = hand[1]
	if not qid or not QuestMapQuestOptions_AbandonQuest then
		if panel then panel.handLeft = nil end
		hand = nil; UpdatePanel()
		return
	end
	if panel then panel.handLeft = #hand end
	UpdatePanel()
	if not pcall(QuestMapQuestOptions_AbandonQuest, qid) then hand = nil; UpdatePanel(); return end
	-- the box closed and the quest is still there: you said No, so the rest stay
	local function Watch()
		if not hand or hand[1] ~= qid then return end
		if Popup() then C_Timer.After(0.3, Watch) return end
		C_Timer.After(0.6, function()
			if hand and hand[1] == qid and InLog(qid) then
				P:Toast(("Kept %d quest%s"):format(#hand, #hand == 1 and "" or "s"))
				hand = nil
				if panel then panel.handLeft = nil end
				UpdatePanel()
			end
		end)
	end
	C_Timer.After(0.3, Watch)
end

-- called from your click: everything that can go goes now
local function Start(ids)
	if busy or hand or #ids == 0 then return end
	local go, cant = {}, 0
	for _, qid in ipairs(ids) do
		ticked[qid] = nil
		if InLog(qid) and not Ready(qid) then
			if CanDrop(qid) then go[#go + 1] = qid else cant = cant + 1 end
		end
	end
	-- from the bottom of the log up, as the macro does it safest
	local idx = {}
	for _, q in ipairs(LogQuests()) do idx[q.id] = q.index end
	table.sort(go, function(a, b) return (idx[a] or 0) > (idx[b] or 0) end)
	busy = { ids = go, total = #go, done = 0, cant = cant, seen = 0, round = 0, tries = Order() }
	preview = nil
	PlaySound(SOUNDKIT.IG_QUEST_LOG_ABANDON_QUEST or 846)
	if #go == 0 then Finish() return end
	Round()
end
-- delete these (ready ones are still kept), the same way the panel's buttons do
function P:QuestDeleteStart(ids) Start(ids) end

---------------------------------------------------------------------------
-- The panel beside the log
---------------------------------------------------------------------------
-- a button that asks once more: the first click arms it, the second does it
local function Armed(b, label, armedLabel, ids)
	b.ids = ids
	if b.armedAt and GetTime() - b.armedAt < CONFIRM_FOR then b:SetLabel(armedLabel) else b.armedAt = nil; b:SetLabel(label) end
	local free = not ((busy and not busy.waiting) or hand)
	b:SetEnabled(#ids > 0 and free)
	b:SetAlpha((#ids > 0 and free) and 1 or 0.45)
end
local function DangerButton(parent, accent)
	local b = P:FlatButton(parent, "", accent)
	b:SetHeight(24)
	b.minW = 196
	b.red = accent
	if accent then P.Flat(b, RED_BG, { RED[1], RED[2], RED[3], 0.8 }); b.edge = { RED[1], RED[2], RED[3], 0.8 } end
	b:HookScript("OnEnter", function(self)
		self:SetBackdropBorderColor(RED[1], RED[2], RED[3], 1)
		if self.ids and not busy then preview = AsSet(self.ids); Refresh() end
	end)
	b:HookScript("OnLeave", function(self) if preview then preview = nil; Refresh() end end)
	b:SetScript("OnClick", function(self)
		if busy and busy.waiting then Retry() return end
		if busy then return end
		if self.armedAt and GetTime() - self.armedAt < CONFIRM_FOR then
			self.armedAt = nil
			Start(self.ids or {})
		else
			self.armedAt = GetTime()
			PlaySound(SOUNDKIT.IG_MAINMENU_OPTION_CHECKBOX_ON or 856)
			-- the "click again" fades back if it isn't
			C_Timer.After(CONFIRM_FOR + 0.05, UpdatePanel)
			UpdatePanel()
		end
	end)
	return b
end

local function Build()
	local host = QuestMapFrame:GetParent()
	panel = CreateFrame("Frame", "PathwayQuestDelete", host, "BackdropTemplate")
	P.Flat(panel, P.colors.BG, P.colors.EDGE, true)
	panel:SetSize(220, 240)
	panel:SetClampedToScreen(true)
	panel:SetFrameStrata(host:GetFrameStrata())
	panel:SetFrameLevel(host:GetFrameLevel() + 40)
	panel:EnableMouse(true)
	panel:Hide()
	panel.bar = panel:CreateTexture(nil, "ARTWORK"); panel.bar:SetPoint("TOPLEFT"); panel.bar:SetPoint("TOPRIGHT"); panel.bar:SetHeight(2)
	panel.bar:SetColorTexture(RED[1], RED[2], RED[3], 0.9)
	panel.title = panel:CreateFontString(nil, "OVERLAY"); panel.title:SetFontObject(P.fonts.title)
	panel.title:SetPoint("TOPLEFT", 12, -10); panel.title:SetText("Delete quests")
	panel.close = P:CloseButton(panel, function() P:QuestDeleteMode(false) end)
	panel.close:SetPoint("TOPRIGHT", -4, -4)
	panel.sub = panel:CreateFontString(nil, "OVERLAY"); panel.sub:SetFontObject(P.fonts.button)
	panel.sub:SetPoint("TOPLEFT", panel.title, "BOTTOMLEFT", 0, -4); panel.sub:SetTextColor(0.65, 0.68, 0.72)

	panel.keep = panel:CreateFontString(nil, "OVERLAY"); panel.keep:SetFontObject(P.fonts.button)
	panel.keep:SetPoint("TOPLEFT", panel.sub, "BOTTOMLEFT", 0, -4); panel.keep:SetWidth(196); panel.keep:SetJustifyH("LEFT")
	panel.all = DangerButton(panel, false)
	panel.all:SetPoint("TOP", panel, "TOP", 0, -66)
	panel.best = DangerButton(panel, false)
	panel.best:SetPoint("TOP", panel.all, "BOTTOM", 0, -6)
	panel.bestNote = panel:CreateFontString(nil, "OVERLAY"); panel.bestNote:SetFontObject(P.fonts.button)
	panel.bestNote:SetPoint("TOP", panel.best, "BOTTOM", 0, -3); panel.bestNote:SetWidth(196); panel.bestNote:SetJustifyH("LEFT")
	panel.bestNote:SetTextColor(0.55, 0.58, 0.62)

	panel.line = panel:CreateTexture(nil, "ARTWORK"); panel.line:SetHeight(1); panel.line:SetColorTexture(1, 1, 1, 0.08)
	panel.line:SetPoint("TOPLEFT", panel.bestNote, "BOTTOMLEFT", 0, -9); panel.line:SetPoint("RIGHT", panel, "RIGHT", -12, 0)
	panel.count = panel:CreateFontString(nil, "OVERLAY"); panel.count:SetFontObject(P.fonts.title)
	panel.count:SetPoint("TOPLEFT", panel.line, "BOTTOMLEFT", 0, -8)
	panel.hint = panel:CreateFontString(nil, "OVERLAY"); panel.hint:SetFontObject(P.fonts.button)
	panel.hint:SetPoint("TOPLEFT", panel.count, "BOTTOMLEFT", 0, -3); panel.hint:SetWidth(196); panel.hint:SetJustifyH("LEFT")
	panel.hint:SetTextColor(0.55, 0.58, 0.62)
	panel.picked = DangerButton(panel, true)
	panel.picked:SetPoint("TOP", panel.hint, "BOTTOM", 0, -12)
	panel.untick = CreateFrame("Button", nil, panel)
	panel.untick:SetSize(80, 14); panel.untick:SetPoint("TOP", panel.picked, "BOTTOM", 0, -4)
	panel.untick.t = panel.untick:CreateFontString(nil, "OVERLAY"); panel.untick.t:SetFontObject(P.fonts.button); panel.untick.t:SetPoint("CENTER")
	panel.untick.t:SetText(P.DIM .. "Untick all|r")
	panel.untick:SetScript("OnClick", function() if not busy then wipe(ticked); Refresh(); UpdatePanel() end end)

	-- deleting: a bar that fills as they go
	panel.prog = CreateFrame("StatusBar", nil, panel)
	panel.prog:SetStatusBarTexture("Interface\\Buttons\\WHITE8X8"); panel.prog:SetStatusBarColor(RED[1], RED[2], RED[3], 0.9)
	panel.prog:SetPoint("BOTTOMLEFT", panel.picked, "TOPLEFT", 0, 6); panel.prog:SetPoint("BOTTOMRIGHT", panel.picked, "TOPRIGHT", 0, 6)
	panel.prog:SetHeight(4); panel.prog:SetMinMaxValues(0, 1)
	panel.prog.bg = panel.prog:CreateTexture(nil, "BACKGROUND"); panel.prog.bg:SetAllPoints(); panel.prog.bg:SetColorTexture(1, 1, 1, 0.06)
	panel.prog:Hide()

	-- in: a short slide from the log's edge
	local inA = panel:CreateAnimationGroup()
	local m = inA:CreateAnimation("Translation"); m:SetOffset(14, 0); m:SetDuration(0.01); m:SetOrder(1)
	local m2 = inA:CreateAnimation("Translation"); m2:SetOffset(-14, 0); m2:SetDuration(0.18); m2:SetSmoothing("OUT"); m2:SetOrder(2)
	local a = inA:CreateAnimation("Alpha"); a:SetFromAlpha(0); a:SetToAlpha(1); a:SetDuration(0.18); a:SetOrder(2)
	panel.inA = inA
	panel:SetScript("OnShow", function(self) self.inA:Play() end)
	panel:SetScript("OnHide", function() if mode and not LogShown() then P:QuestDeleteMode(false) end end)
end

function UpdatePanel()
	if not (panel and panel:IsShown()) then return end
	local all, ready = AllIDs()
	local best, keep = AllButBest()
	local picked = TickedIDs()
	local total = #all + ready
	panel.sub:SetText(("%d quest%s in your log"):format(total, total == 1 and "" or "s"))
	panel.keep:SetText(ready > 0 and ("|TInterface\\RaidFrame\\ReadyCheck-Ready:12:12|t |cff7cf29c%d ready to hand in, kept|r"):format(ready)
		or (P.DIM .. "Ready to hand in: always kept.|r"))
	Armed(panel.all, ("Delete all %d"):format(#all), ("Click again: delete all %d"):format(#all), all)
	Armed(panel.best, ("Keep the best, delete %d"):format(#best), ("Click again: delete %d"):format(#best), best)
	panel.bestNote:SetText(("Keeps your top 25%% by XP (%d)."):format(keep))
	if hand and panel.handLeft then
		panel.count:SetText(("|cffffd200%d left|r: click Yes on each"):format(panel.handLeft))
		panel.hint:SetText("They wouldn't go on their own. No keeps the rest.")
		panel.prog:Hide()
	elseif busy and busy.waiting then
		panel.count:SetText(("|cffffd200%d didn't go|r"):format(#busy.ids))
		panel.hint:SetText("Click any button to try another way.")
		panel.prog:Hide()
	elseif busy then
		local n = math.min(busy.total, busy.done + busy.seen)
		panel.count:SetText(("Deleting %d of %d"):format(n, busy.total))
		panel.hint:SetText("")
		panel.prog:Show(); panel.prog:SetValue(n / math.max(1, busy.total))
	elseif panel.doneAt and GetTime() - panel.doneAt < 2.5 then
		panel.count:SetText("|cff7cf29c" .. panel.doneText .. "|r")
		panel.hint:SetText("")
		panel.prog:Hide()
		C_Timer.After(2.6, UpdatePanel)
	else
		panel.doneAt = nil
		panel.prog:Hide()
		if #picked > 0 then
			panel.count:SetText(("|cffffffff%d|r ticked"):format(#picked))
			panel.hint:SetText("Tick more, or delete these.")
		else
			panel.count:SetText("Or pick them yourself")
			panel.hint:SetText("Tick them in the quest log.")
		end
	end
	Armed(panel.picked, #picked > 0 and ("Delete %d quest%s"):format(#picked, #picked == 1 and "" or "s") or "Nothing ticked yet",
		("Click again: delete %d"):format(#picked), picked)
	if busy and busy.waiting then
		local t = ("Try again: %d left"):format(#busy.ids)
		for _, b in ipairs({ panel.all, panel.best, panel.picked }) do b.armedAt = nil; b:SetLabel(t); b:SetEnabled(true); b:SetAlpha(1) end
	end
	panel.untick:SetShown(#picked > 0 and not busy)
	-- as tall as what it holds, so nothing ever runs into anything
	local h = 66 + 24 + 6 + 24 + 3 + panel.bestNote:GetStringHeight() + 9 + 1 + 8 + panel.count:GetStringHeight() + 3
		+ panel.hint:GetStringHeight() + 12 + 24 + 4 + 14 + 10
	panel:SetHeight(floor(h + 0.5))
end

-- beside the log: to the right of the map window when there's room, else inside it
local function PlacePanel()
	panel:ClearAllPoints()
	local host = QuestMapFrame:GetParent()
	local right = tonumber(host:GetRight()) or 0
	local k = (tonumber(host:GetEffectiveScale()) or 1) / (tonumber(UIParent:GetEffectiveScale()) or 1)
	local room = (tonumber(UIParent:GetRight()) or 0) - right * k
	if room > 240 then panel:SetPoint("TOPLEFT", host, "TOPRIGHT", 6, -24)
	else panel:SetPoint("TOPRIGHT", QuestMapFrame, "TOPLEFT", -8, -24) end
end

function P:QuestDeleteMode(on)
	if not MapLog() then return end
	if on == nil then on = not mode end
	if on and not LogShown() then return end
	mode = on and true or false
	if not panel then Build() end
	if not mode then wipe(ticked); preview = nil end
	if mode then PlacePanel() end
	panel:SetShown(mode)
	if button then button:SetLabel(mode and "Done" or button.label); if button.fit then button.fit() end end
	Refresh(); UpdatePanel()
end

---------------------------------------------------------------------------
-- The button on the log: beside the "Quests: 17/20" count
---------------------------------------------------------------------------
-- "Clean up ▾": red, with the game's own trash icon and a little arrow that says
-- it opens choices; it lights up under the mouse, and says "Done" while you're in it
local function CleanUpButton(parent)
	local b = CreateFrame("Button", nil, parent, "BackdropTemplate")
	b:SetHeight(22)
	P.Flat(b, RED_BG, { RED[1], RED[2], RED[3], 0.85 })
	b.glow = b:CreateTexture(nil, "BACKGROUND", nil, -2)
	b.glow:SetTexture(P.MEDIA .. "Glow"); b.glow:SetBlendMode("ADD")
	b.glow:SetPoint("TOPLEFT", -10, 8); b.glow:SetPoint("BOTTOMRIGHT", 10, -8)
	b.glow:SetVertexColor(RED[1], RED[2] * 0.6, RED[3] * 0.5, 0.18)
	b.icon = b:CreateTexture(nil, "ARTWORK")
	b.icon:SetSize(14, 14); b.icon:SetPoint("LEFT", 6, 0)
	if not pcall(b.icon.SetAtlas, b.icon, "common-icon-delete") or not b.icon:GetAtlas() then b.icon:SetTexture("Interface\\Buttons\\UI-GroupLoot-Pass-Up") end
	b.text = b:CreateFontString(nil, "OVERLAY"); b.text:SetFontObject(P.fonts.button)
	b.text:SetPoint("LEFT", b.icon, "RIGHT", 4, 0); b.text:SetTextColor(1, 0.86, 0.82)
	b.chev = b:CreateTexture(nil, "ARTWORK")
	b.chev:SetTexture(P.MEDIA .. "Arrow"); b.chev:SetSize(10, 10); b.chev:SetRotation(math.pi)
	b.chev:SetPoint("LEFT", b.text, "RIGHT", 4, -1); b.chev:SetVertexColor(1, 0.7, 0.65)
	-- a slow breath on the glow while the mouse is on it
	local g = b.glow:CreateAnimationGroup(); g:SetLooping("BOUNCE")
	local a1 = g:CreateAnimation("Alpha"); a1:SetFromAlpha(0.35); a1:SetToAlpha(0.8); a1:SetDuration(0.7); a1:SetSmoothing("IN_OUT")
	b.breathe = g
	function b:SetLabel(t)
		self.text:SetText(t)
		local open = t == "Done"
		self.chev:SetShown(not open)
		self:SetWidth(6 + 14 + 4 + self.text:GetStringWidth() + (open and 8 or 18))
	end
	b.label = "Clean up"
	b:SetLabel("Clean up")
	b:SetScript("OnEnter", function(self)
		self:SetBackdropColor(0.42, 0.1, 0.08, 1); self:SetBackdropBorderColor(1, 0.45, 0.4, 1)
		self.glow:SetVertexColor(RED[1], RED[2] * 0.6, RED[3] * 0.5, 0.7); self.breathe:Play()
		GameTooltip:SetOwner(self, "ANCHOR_TOP")
		GameTooltip:SetText("Clean up quests", 1, 0.86, 0.82)
		GameTooltip:AddLine("Delete all", 0.85, 0.85, 0.85)
		GameTooltip:AddLine("Keep your best 25% by XP, delete the rest", 0.85, 0.85, 0.85)
		GameTooltip:AddLine("Or tick exactly the ones to go", 0.85, 0.85, 0.85)
		GameTooltip:AddLine("Quests ready to hand in are always kept", 0.49, 0.95, 0.61)
		GameTooltip:Show()
	end)
	b:SetScript("OnLeave", function(self)
		self:SetBackdropColor(RED_BG[1], RED_BG[2], RED_BG[3], 1); self:SetBackdropBorderColor(RED[1], RED[2], RED[3], 0.85)
		self.breathe:Stop(); self.glow:SetAlpha(1); self.glow:SetVertexColor(RED[1], RED[2] * 0.6, RED[3] * 0.5, 0.18)
		GameTooltip:Hide()
	end)
	b:SetScript("OnMouseDown", function(self) self.icon:SetPoint("LEFT", 7, -1) end)
	b:SetScript("OnMouseUp", function(self) self.icon:SetPoint("LEFT", 6, 0) end)
	return b
end

local function AddButton()
	if button then return end
	if MapLog() then
		-- Forever's Map & Quest Log: between the search box and "Quests: 7/40", the
		-- search box giving up the room
		local sf = QuestScrollFrame
		local b = CleanUpButton(sf)
		b:SetPoint("TOPLEFT", sf.SearchBox, "TOPRIGHT", 4, 1)
		b:SetFrameLevel(sf:GetFrameLevel() + 10)
		button = b
		-- the search box gives up exactly the button's width (and gets it back when it's off)
		local function Fit()
			local box = sf.SearchBox
			if not box.pwOrig then box.pwOrig = tonumber(box:GetWidth()) or 190 end
			if button:IsShown() then box:SetWidth(box.pwOrig - ((tonumber(button:GetWidth()) or 80) + 6))
			else box:SetWidth(box.pwOrig) end
			if QuestLogCount then
				QuestLogCount:ClearAllPoints()
				QuestLogCount:SetPoint("TOPLEFT", button:IsShown() and button or box, "TOPRIGHT", 3, button:IsShown() and -1 or 0)
			end
		end
		-- the game sets the search box's width each time it counts the quests: take that as the width to fit in
		if QuestLogQuests_ShowQuestCount then hooksecurefunc("QuestLogQuests_ShowQuestCount", function() sf.SearchBox.pwOrig = nil; Fit() end) end
		if QuestLogQuests_Update then hooksecurefunc("QuestLogQuests_Update", function() if mode then Refresh(); UpdatePanel() end end) end
		QuestMapFrame:GetParent():HookScript("OnHide", function() if mode then P:QuestDeleteMode(false) end end)
		QuestMapFrame:HookScript("OnHide", function() if mode then P:QuestDeleteMode(false) end end)
		button.fit = Fit
	else
		return
	end
	button:SetScript("OnClick", function() P:QuestDeleteMode() end)
	button:SetShown(S().questDelete ~= false)
	if button.fit then button.fit() end
end
P:Listen("READY", AddButton)
P:On("ADDON_LOADED", function(_, name) if name == "Blizzard_WorldMap" then C_Timer.After(0, AddButton) end end)
P:Listen("SETTINGS_CHANGED", function()
	if not button then return end
	local on = S().questDelete ~= false
	if not on and mode then P:QuestDeleteMode(false) end
	button:SetShown(on)
	if button.fit then button.fit() end
end)
end part() end
-- ==================== Bags/Compat.lua
do local __addon, __ns = ... local function part()
-- Copyright (C) 2026 SoFinSicc. Part of Pathway (curseforge.com/wow/addons/pathway): free software under the GPLv3 or later, with additional terms that require keeping this credit. See LICENSE.md.
--[[ Pathway — Bags compatibility
     Lil's GoodBags lives here as Pathway's bag module. GoodBags was written
     for retail (bank tabs, the Warband bank, specs); WoW: Forever runs on the
     Classic client (a bank plus bank bags). This file bridges the two so the
     bag code itself stays the same:
       · P.Item / P.Container / P.BankAPI: the APIs GoodBags uses, filled in
         from the older globals where the Forever client doesn't have them
       · on Forever the bank's "tabs" are its slots and bank bags ]]

local ADDON, P = __addon, __ns
local GB = {}
P.Bags = GB

local function shim(real, fill)
	return setmetatable(fill, { __index = real or {} })
end

local function pick(real, name, fallback) return (real and real[name]) or fallback end

---------------------------------------------------------------------------
-- Items and containers
---------------------------------------------------------------------------
P.Item = shim(C_Item, {
	GetItemInfo = pick(C_Item, "GetItemInfo", GetItemInfo),
	GetItemInfoInstant = pick(C_Item, "GetItemInfoInstant", GetItemInfoInstant),
	GetItemQualityColor = pick(C_Item, "GetItemQualityColor", function(q) return GetItemQualityColor(q) end),
	GetItemNameByID = pick(C_Item, "GetItemNameByID", function(id) return (GetItemInfo(id)) end),
	GetItemIconByID = pick(C_Item, "GetItemIconByID", GetItemIcon),
	GetItemQualityByID = pick(C_Item, "GetItemQualityByID", function(id) return (select(3, GetItemInfo(id))) end),
	GetItemMaxStackSizeByID = pick(C_Item, "GetItemMaxStackSizeByID", function(id) return (select(8, GetItemInfo(id))) end),
	GetItemStats = pick(C_Item, "GetItemStats", GetItemStats),
	GetDetailedItemLevelInfo = pick(C_Item, "GetDetailedItemLevelInfo", GetDetailedItemLevelInfo),
	GetCurrentItemLevel = pick(C_Item, "GetCurrentItemLevel", function() return nil end),
	DoesItemExist = pick(C_Item, "DoesItemExist", function() return false end),
	CanBeRefunded = pick(C_Item, "CanBeRefunded", function() return false end),
	GetItemCount = pick(C_Item, "GetItemCount", GetItemCount),
	GetItemSpell = pick(C_Item, "GetItemSpell", GetItemSpell),
	IsEquippedItem = pick(C_Item, "IsEquippedItem", IsEquippedItem),
	GetItemInventoryTypeByID = pick(C_Item, "GetItemInventoryTypeByID", function(id) return (select(4, GetItemInfoInstant(id))) end),
	RequestLoadItemDataByID = pick(C_Item, "RequestLoadItemDataByID", function() end),
})

local function SortBankBags()
	if C_Container and C_Container.SortBankBags then C_Container.SortBankBags()
	elseif SortBankBags then SortBankBags() end
end

local function InfoTable(bag, slot)
	local icon, count, locked, quality, readable, lootable, link, filtered, noValue, id, bound = GetContainerItemInfo(bag, slot)
	if not icon then return nil end
	return { iconFileID = icon, stackCount = count, isLocked = locked, quality = quality, isReadable = readable,
		hyperlink = link, hasNoValue = noValue, itemID = id, isBound = bound, itemName = link and link:match("%[(.-)%]") }
end

P.Container = shim(C_Container, {
	GetContainerNumSlots = pick(C_Container, "GetContainerNumSlots", GetContainerNumSlots),
	GetContainerNumFreeSlots = pick(C_Container, "GetContainerNumFreeSlots", GetContainerNumFreeSlots),
	GetContainerItemInfo = pick(C_Container, "GetContainerItemInfo", InfoTable),
	GetContainerItemLink = pick(C_Container, "GetContainerItemLink", GetContainerItemLink),
	GetContainerItemID = pick(C_Container, "GetContainerItemID", GetContainerItemID),
	PickupContainerItem = pick(C_Container, "PickupContainerItem", PickupContainerItem),
	SplitContainerItem = pick(C_Container, "SplitContainerItem", SplitContainerItem),
	GetContainerItemQuestInfo = pick(C_Container, "GetContainerItemQuestInfo", function() return nil end),
	SortBank = pick(C_Container, "SortBank", SortBankBags),
})
GB.CanSortBank = (C_Container and (C_Container.SortBank or C_Container.SortBankBags)) or SortBankBags

---------------------------------------------------------------------------
-- The bank
---------------------------------------------------------------------------
GB.TABS = (C_Bank and C_Bank.FetchPurchasedBankTabIDs and Enum.BankType and true) or false
GB.CHAR = (Enum.BankType and Enum.BankType.Character) or 0
GB.ACCT = GB.TABS and Enum.BankType.Account or nil

local BANK = BANK_CONTAINER or -1
local function BankBags(bt)
	if GB.TABS then return C_Bank.FetchPurchasedBankTabIDs(bt) or {} end
	if bt ~= GB.CHAR then return {} end
	local t = { BANK }
	local first = (NUM_BAG_SLOTS or 4) + 1
	for i = first, first + (NUM_BANKBAGSLOTS or 6) - 1 do t[#t + 1] = i end
	return t
end
GB.BankBags = BankBags

local function BagIcon(bag)
	if bag == BANK then return 133633 end
	local inv = C_Container and C_Container.ContainerIDToInventoryID and C_Container.ContainerIDToInventoryID(bag)
		or ContainerIDToInventoryID and ContainerIDToInventoryID(bag)
	return inv and GetInventoryItemTexture("player", inv) or 134400
end

local function BagName(bag)
	if bag == BANK then return "Bank" end
	local name = C_Container and C_Container.GetBagName and C_Container.GetBagName(bag) or GetBagName and GetBagName(bag)
	return name or ("Bag " .. (bag - (NUM_BAG_SLOTS or 4)))
end

-- tabs as GoodBags expects them: { ID =, name =, icon =, depositFlags = }
function GB.BankTabData(bt)
	if GB.TABS then return C_Bank.FetchPurchasedBankTabData(bt) or {} end
	local out = {}
	for _, bag in ipairs(BankBags(bt)) do
		local n = P.Container.GetContainerNumSlots(bag) or 0
		if n > 0 then out[#out + 1] = { ID = bag, name = BagName(bag), icon = BagIcon(bag), depositFlags = 0 } end
	end
	return out
end

P.BankAPI = shim(GB.TABS and C_Bank or nil, {
	FetchPurchasedBankTabIDs = BankBags,
	FetchPurchasedBankTabData = GB.BankTabData,
	CanViewBank = function(bt) if GB.TABS and C_Bank.CanViewBank then return C_Bank.CanViewBank(bt) end; return bt == GB.CHAR end,
	CloseBankFrame = pick(C_Bank, "CloseBankFrame", CloseBankFrame),
	FetchBankLockedReason = GB.TABS and C_Bank.FetchBankLockedReason or function() return nil end,
	DoesBankTypeSupportMoneyTransfer = GB.TABS and C_Bank.DoesBankTypeSupportMoneyTransfer or function() return false end,
	CanPurchaseBankTab = GB.TABS and C_Bank.CanPurchaseBankTab or function() return false end,
	FetchDepositedMoney = GB.TABS and C_Bank.FetchDepositedMoney or function() return 0 end,
	IsItemAllowedInBankType = GB.TABS and C_Bank.IsItemAllowedInBankType or function(bt) return bt == GB.CHAR end,
})
GB.CanDeposit = GB.TABS and C_Bank.AutoDepositItemsIntoBank and true or false

---------------------------------------------------------------------------
-- Bag IDs: backpack and four bags, plus the reagent bag where it exists
---------------------------------------------------------------------------
GB.BAGS = { 0, 1, 2, 3, 4 }
GB.REAGENT_BAG = Enum.BagIndex and Enum.BagIndex.ReagentBag or nil
if GB.REAGENT_BAG then GB.BAGS[#GB.BAGS + 1] = GB.REAGENT_BAG end

GB.Menu = MenuUtil or P.MiniMenu

---------------------------------------------------------------------------
-- Shims the minimap and fishing modules use
---------------------------------------------------------------------------
P.AddOns = shim(C_AddOns, {
	IsAddOnLoaded = pick(C_AddOns, "IsAddOnLoaded", IsAddOnLoaded or function() return false end),
	LoadAddOn = pick(C_AddOns, "LoadAddOn", LoadAddOn or function() return false end),
})
function P.ZonePVP()
	if C_PvP and C_PvP.GetZonePVPInfo then return C_PvP.GetZonePVPInfo() end
	return GetZonePVPInfo()
end
local MINIMAP_RADIUS = { [0] = 233.33, 200, 166.67, 133.33, 100, 66.67 }   -- outdoors, per zoom
P.Minimap = setmetatable({}, { __index = function(_, k)
	if C_Minimap and C_Minimap[k] then return C_Minimap[k] end
	if k == "GetViewRadius" then return function() return MINIMAP_RADIUS[Minimap:GetZoom()] or 233.33 end end
	return function() end
end })

-- currencies shown in the bag footer
function GB.BackpackCurrency(i)
	if C_CurrencyInfo and C_CurrencyInfo.GetBackpackCurrencyInfo then return C_CurrencyInfo.GetBackpackCurrencyInfo(i) end
	if GetBackpackCurrencyInfo then
		local name, count, icon, id = GetBackpackCurrencyInfo(i)
		if name then return { quantity = count, iconFileID = icon, currencyTypesID = id } end
	end
end
end part() end
