--[[ Lil's GoodBags — Core
     Data, scanning, the Loot Inbox model, categories and caches.
     Everything here is UI-agnostic; UI.lua draws it, Features.lua extends it. ]]

local ADDON, P = __addon, __ns
local GB = P.Bags
local C_Item, C_Container, C_Bank = P.Item, P.Container, P.BankAPI

GB.VERSION = "1.1.0"
GB.ACCENT = { 0.431, 0.906, 0.718 }          -- #6ee7b7 mint
GB.ACCENT_HEX = "ff6ee7b7"
GB.TITLE = "|cff6ee7b7Path|rway  |cffd8dde3Bags|r"

local C_Container, C_Item, C_Timer = C_Container, C_Item, C_Timer
local GetTime, time, pairs, ipairs, wipe, max, min = GetTime, time, pairs, ipairs, wipe, math.max, math.min

-- GB.BAGS and GB.REAGENT_BAG come from Compat.lua

---------------------------------------------------------------------------
-- Saved variables
---------------------------------------------------------------------------
local DEFAULTS = {
	settings = {
		view = "categorized",      -- "categorized" | "unified" | "bags" (each bag as it is, with labels)
		cols = 12,
		iconSize = 37,
		scale = 1,
		ageMinutes = 30,           -- auto-age Inbox items into categories (0 = off)
		autoClear = false,         -- sweep Inbox when closing a vendor or bank
		bankUI = true,             -- use GoodBags for the bank
		welcomed = false,
		showIlvl = true, showBind = true, showUpgrade = true, showCollect = false, showSets = true,
		bankView = "sorted",       -- bank tabs: "sorted" (categories) | "slots" (real slot grid)
		autoSortBank = false,      -- Clean Up the character bank after each visit's moves
		autoSortWarband = false,   -- same for the Warband bank
		autoRestock = true,        -- top up the restock list whenever the bank opens
		theme = "native",          -- "native" | "flat" | "ui" (match ElvUI)
		accent = { 0.431, 0.906, 0.718 },
		bgAlpha = 0.95,
		qualityTint = "full",      -- "full" | "subtle" | "off"
		fontSize = "normal",
		takeOverBags = true,
		autoSell = false,
		showSplit = true,
	},
	conflicts = {},
	collapsed = {}, junk = {}, neverSell = {}, pinned = {},
	chars = {}, warband = { items = {}, t = 0, money = 0 },
	pos = {},
}
local CHAR_DEFAULTS = { inbox = {}, locks = {}, claimed = {}, bagLabels = {},
	restock = {},     -- [itemID] = how many to keep in your bags
	toBank = {},      -- [itemID] = true: deposit on the next bank visit
	withdraw = {},    -- [itemID] = true: withdraw on the next bank visit
}

local function merge(dst, src)
	for k, v in pairs(src) do
		if type(v) == "table" then
			if type(dst[k]) ~= "table" then dst[k] = {} end
			merge(dst[k], v)
		elseif dst[k] == nil then
			dst[k] = v
		end
	end
	return dst
end

---------------------------------------------------------------------------
-- Tiny event bus
---------------------------------------------------------------------------
local eventFrame = CreateFrame("Frame")
local handlers, messages = {}, {}

-- events only start flowing once the bag module is switched on (GB:EnableEvents)
local live = false
function GB:On(event, fn)
	if not handlers[event] then
		handlers[event] = {}
		-- pcall: an event renamed in a future patch must never break loading
		if live then pcall(eventFrame.RegisterEvent, eventFrame, event) end
	end
	local list = handlers[event]
	list[#list + 1] = fn
end

function GB:EnableEvents()
	live = true
	for event in pairs(handlers) do pcall(eventFrame.RegisterEvent, eventFrame, event) end
end

eventFrame:SetScript("OnEvent", function(_, event, ...)
	local list = handlers[event]
	if list then for i = 1, #list do list[i](event, ...) end end
end)
Pathway.Perf.Hook(eventFrame, "Bags", "OnEvent")

-- internal messages (no Blizzard events involved)
function GB:Listen(msg, fn) messages[msg] = messages[msg] or {}; table.insert(messages[msg], fn) end
function GB:Send(msg, ...) local l = messages[msg]; if l then for i = 1, #l do l[i](...) end end end

-- coalesce bursts (BAG_UPDATE fires per-slot; we only care once per frame-ish)
local pending = {}
function GB:Debounce(key, delay, fn)
	if pending[key] then return end
	pending[key] = true
	C_Timer.After(delay, function() pending[key] = nil; fn() end)
end

function GB:Print(msg, ...)
	print((GB.TITLE .. ": " .. msg):format(...))
end

---------------------------------------------------------------------------
-- Static item info (never changes for an itemID, so cache forever)
---------------------------------------------------------------------------
local static = {}
function GB.Static(itemID)
	local s = static[itemID]
	if not s then
		local _, _, _, equipLoc, _, classID, subclassID = C_Item.GetItemInfoInstant(itemID)
		s = { equipLoc = equipLoc or "", classID = classID or -1, subclassID = subclassID or -1 }
		if C_Item.IsItemKeystoneByID then s.isKey = C_Item.IsItemKeystoneByID(itemID) or nil end
		static[itemID] = s
	end
	return s
end

---------------------------------------------------------------------------
-- Scanning
---------------------------------------------------------------------------
GB.slots = {}        -- array of item records in the player's bags
GB.index = {}        -- [bag*1000+slot] = record
GB.counts = {}       -- [itemID] = count in bags
GB.free = { normal = { n = 0 }, reagent = { n = 0 } }
GB.bank = { slots = {}, counts = {}, warCounts = {}, free = { character = { n = 0 }, account = { n = 0 } } }

local loc = ItemLocation and ItemLocation:CreateEmpty()
local pool = {}
local function NewRecord() local r = table.remove(pool) or {}; return r end
local function Recycle(list) for i = #list, 1, -1 do local r = list[i]; wipe(r); pool[#pool + 1] = r; list[i] = nil end end

local function FillRecord(r, bag, slot, info)
	r.bag, r.slot = bag, slot
	r.itemID = info.itemID
	r.link = info.hyperlink
	r.count = info.stackCount or 1
	r.quality = info.quality or 1
	r.icon = info.iconFileID
	r.locked = info.isLocked
	r.noValue = info.hasNoValue
	r.bound = info.isBound
	r.name = info.itemName
	r.readable = info.isReadable
	local qi = C_Container.GetContainerItemQuestInfo(bag, slot)
	if qi then r.isQuest, r.questID, r.questActive = qi.isQuestItem, qi.questID, qi.isActive end

	local s = GB.Static(r.itemID)
	r.classID, r.subclassID, r.equipLoc = s.classID, s.subclassID, s.equipLoc
	if C_Container.GetContainerItemEquipmentSetInfo and (s.classID == 2 or s.classID == 4) then
		r.inSet, r.setList = C_Container.GetContainerItemEquipmentSetInfo(bag, slot)
	end
	if s.isKey then
		local mapID, level = (r.link or ""):match("|Hkeystone:%d+:(%d+):(%d+)")
		r.isKey, r.keyMap, r.keyLevel = true, tonumber(mapID), tonumber(level)
	end
	if (s.classID == 2 or s.classID == 4) and s.equipLoc ~= "" and loc then
		loc:SetBagAndSlot(bag, slot)
		if C_Item.DoesItemExist(loc) then
			r.ilvl = C_Item.GetCurrentItemLevel(loc)
			r.wue = C_Item.IsBoundToAccountUntilEquip and C_Item.IsBoundToAccountUntilEquip(loc) or nil
		end
	end
	return r
end

local function ScanBag(bag, out, counts, free)
	local n = C_Container.GetContainerNumSlots(bag) or 0
	for slot = 1, n do
		local info = C_Container.GetContainerItemInfo(bag, slot)
		if info and info.itemID then
			local r = FillRecord(NewRecord(), bag, slot, info)
			out[#out + 1] = r
			counts[r.itemID] = (counts[r.itemID] or 0) + r.count
		elseif free then
			free.n = free.n + 1
			if not free.bag then free.bag, free.slot = bag, slot end
		end
	end
	return n
end

function GB:ScanBags()
	Recycle(self.slots); wipe(self.index); wipe(self.counts)
	local fn, fr = self.free.normal, self.free.reagent
	fn.n, fn.bag, fn.slot, fn.total = 0, nil, nil, 0
	fr.n, fr.bag, fr.slot, fr.total = 0, nil, nil, 0
	for _, bag in ipairs(self.BAGS) do
		local f = (bag == self.REAGENT_BAG) and fr or fn
		f.total = f.total + ScanBag(bag, self.slots, self.counts, f)
	end
	for _, r in ipairs(self.slots) do self.index[r.bag * 1000 + r.slot] = r end
end

local function PurchasedTabs(bankType)
	if not bankType then return {} end
	return GB.BankBags(bankType)
end
GB.PurchasedTabs = PurchasedTabs

function GB:ScanBank()
	local b = self.bank
	Recycle(b.slots); wipe(b.counts); wipe(b.warCounts)
	b.index = b.index or {}; wipe(b.index)
	local readable = {}
	for kind, bankType in pairs({ character = GB.CHAR, account = GB.ACCT }) do
		local f = b.free[kind]; f.n, f.bag, f.slot, f.total = 0, nil, nil, 0
		for _, bag in ipairs(PurchasedTabs(bankType)) do
			if (C_Container.GetContainerNumSlots(bag) or 0) > 0 then readable[kind] = true end
			local start = #b.slots
			f.total = f.total + ScanBag(bag, b.slots, kind == "account" and b.warCounts or b.counts, f)
			for i = start + 1, #b.slots do b.slots[i].bankKind = kind end
		end
	end
	for _, r in ipairs(b.slots) do b.index[r.bag * 1000 + r.slot] = r end
	-- remember for account-wide tooltips and Bank Anywhere
	-- only ever save from a bank that's open and actually readable, so a
	-- closing or half-loaded bank can never overwrite a good copy with nothing
	if not self.bankOpen then return end
	local me = self:CharEntry()
	if me and readable.character then
		me.bank = CopyTable(b.counts); me.t = time()
		me.bankSnap = self:Snapshot("character", GB.CHAR)
	end
	if readable.account and C_Bank and C_Bank.CanViewBank and Enum.BankType and C_Bank.CanViewBank(GB.ACCT) then
		self.db.warband.items = CopyTable(b.warCounts)
		self.db.warband.t = time()
		self.db.warband.snap = self:Snapshot("account", GB.ACCT)
		if C_Bank.FetchDepositedMoney then self.db.warband.money = C_Bank.FetchDepositedMoney(GB.ACCT) or 0 end
	end
end

-- A saved copy of one bank: its tabs and every stack, compact enough for SavedVariables.
function GB:Snapshot(kind, bankType)
	local snap = { t = time(), tabs = {}, items = {} }
	if C_Bank and C_Bank.FetchPurchasedBankTabData and bankType then
		for _, tab in ipairs(C_Bank.FetchPurchasedBankTabData(bankType) or {}) do
			snap.tabs[#snap.tabs + 1] = { ID = tab.ID, name = tab.name, icon = tab.icon,
				size = C_Container.GetContainerNumSlots(tab.ID) or 0 }
		end
	end
	for _, r in ipairs(self.bank.slots) do
		if r.bankKind == kind then
			snap.items[#snap.items + 1] = { r.bag, r.slot, r.itemID, r.count, r.link, r.icon, r.quality, r.ilvl }
		end
	end
	return snap
end

-- Turn a saved copy back into item records the layout understands.
function GB:SnapshotRecords(snap, kind)
	local out = {}
	for _, e in ipairs(snap and snap.items or {}) do
		local id = e[3]
		local st = GB.Static(id)
		out[#out + 1] = { bag = e[1], slot = e[2], itemID = id, count = e[4], link = e[5], icon = e[6],
			quality = e[7] or 1, ilvl = e[8], classID = st.classID, subclassID = st.subclassID, equipLoc = st.equipLoc,
			name = C_Item.GetItemNameByID and C_Item.GetItemNameByID(id) or nil, bankKind = kind, saved = true }
	end
	return out
end

---------------------------------------------------------------------------
-- Loot Inbox model
--   We diff total item counts (bags + equipped + open bank) rather than
--   trusting slot-based "new" flags, so splitting, stacking, swapping bags,
--   equipping and banking never create false "new" items.
---------------------------------------------------------------------------
local baseline
GB.silentUntil = math.huge          -- silent until the world has fully loaded

local function Totals()
	local t = {}
	for id, c in pairs(GB.counts) do t[id] = c end
	for slot = 1, 19 do
		local id = GetInventoryItemID("player", slot)
		if id then t[id] = (t[id] or 0) + 1 end
	end
	if GB.bankOpen then
		for id, c in pairs(GB.bank.counts) do t[id] = (t[id] or 0) + c end
		for id, c in pairs(GB.bank.warCounts) do t[id] = (t[id] or 0) + c end
	end
	return t
end

function GB:Rebaseline() baseline = Totals() end

function GB:DiffNew()
	local now = Totals()
	local inbox, locks = self.cdb.inbox, self.cdb.locks
	local silent = (not baseline) or GetTime() < self.silentUntil
	local gained, changed = 0, false

	if not silent then
		local fresh = {}
		for id, c in pairs(now) do
			local old = baseline[id] or 0
			if c > old then fresh[id] = c - old; gained = gained + 1 end
		end
		-- a burst of dozens of different items at once is data loading, not loot
		if gained <= 40 then
			local t = time()
			for id, delta in pairs(fresh) do
				local e = inbox[id]
				if e then e.n, e.t = e.n + delta, t else inbox[id] = { n = delta, t = t } end
				changed = true
				self:Send("ITEM_GAINED", id, delta)
			end
		end
	end

	-- keep the inbox honest: gone from bags = gone from inbox
	-- (never while silent: at login the bags may not be populated yet)
	for id, e in pairs(silent and {} or inbox) do
		local inBags = self.counts[id] or 0
		if inBags == 0 then
			inbox[id], locks[id] = nil, nil; changed = true
		elseif e.n > inBags then
			e.n = inBags
		end
	end
	baseline = now
	return changed
end

function GB:IsNew(itemID) return self.cdb.inbox[itemID] ~= nil end
function GB:IsLocked(itemID) return self.cdb.locks[itemID] == true end

function GB:ToggleLock(itemID)
	if not self.cdb.inbox[itemID] then return end
	self.cdb.locks[itemID] = (not self.cdb.locks[itemID]) or nil
	self:RequestLayout()
	return self.cdb.locks[itemID]
end

function GB:Sweep()
	local inbox, locks = self.cdb.inbox, self.cdb.locks
	local n = 0
	for id in pairs(inbox) do
		if not locks[id] then inbox[id] = nil; n = n + 1 end
	end
	if C_NewItems and C_NewItems.ClearAll then C_NewItems.ClearAll() end
	self:RequestLayout()
	return n
end

function GB:InboxCount()
	local n = 0
	for _, r in ipairs(self.slots) do if self.cdb.inbox[r.itemID] then n = n + 1 end end
	return n
end

function GB:AgeInbox()
	local age = self.db.settings.ageMinutes
	if not age or age <= 0 then return end
	local cutoff, changed = time() - age * 60, false
	for id, e in pairs(self.cdb.inbox) do
		if not self.cdb.locks[id] and e.t <= cutoff then self.cdb.inbox[id] = nil; changed = true end
	end
	if changed then self:RequestLayout() end
end

---------------------------------------------------------------------------
-- Equipped item levels & upgrade detection
---------------------------------------------------------------------------
local SLOTS = {
	INVTYPE_HEAD = { 1 }, INVTYPE_NECK = { 2 }, INVTYPE_SHOULDER = { 3 }, INVTYPE_CHEST = { 5 }, INVTYPE_ROBE = { 5 },
	INVTYPE_WAIST = { 6 }, INVTYPE_LEGS = { 7 }, INVTYPE_FEET = { 8 }, INVTYPE_WRIST = { 9 }, INVTYPE_HAND = { 10 },
	INVTYPE_FINGER = { 11, 12 }, INVTYPE_TRINKET = { 13, 14 }, INVTYPE_CLOAK = { 15 },
	INVTYPE_WEAPON = { 16, 17 }, INVTYPE_2HWEAPON = { 16 }, INVTYPE_WEAPONMAINHAND = { 16 }, INVTYPE_RANGED = { 16 },
	INVTYPE_RANGEDRIGHT = { 16 }, INVTYPE_WEAPONOFFHAND = { 17 }, INVTYPE_SHIELD = { 17 }, INVTYPE_HOLDABLE = { 17 },
}
-- armor subclass each class wants (cloth 1, leather 2, mail 3, plate 4)
local ARMOR = { WARRIOR = 4, PALADIN = 4, DEATHKNIGHT = 4, HUNTER = 3, SHAMAN = 3, EVOKER = 3,
	DRUID = 2, ROGUE = 2, MONK = 2, DEMONHUNTER = 2, MAGE = 1, PRIEST = 1, WARLOCK = 1 }

--[[ An item earns the green arrow when it beats what's equipped in that slot
     on ANY of these, and the arrow gets brighter for each one it beats:
       1. item level        2. your spec's main stat        3. sockets
     Items with the wrong main stat for your spec, the wrong armor type, or
     that you can't use never get an arrow. A socket alone only counts when
     the item isn't far below what you wear (SOCKET_ILVL_SLACK). ]]
local SOCKET_ILVL_SLACK = 10
local STAT_WORD = { [1] = "STRENGTH", [2] = "AGILITY", [4] = "INTELLECT" }
local STAT_NAME = { STRENGTH = SPELL_STAT1_NAME or "Strength", AGILITY = SPELL_STAT2_NAME or "Agility", INTELLECT = SPELL_STAT4_NAME or "Intellect" }

local myStat                 -- "STRENGTH" | "AGILITY" | "INTELLECT"
local equipped = {}          -- [slot] = { ilvl=, stat=, sockets= } | false (empty) ; nil = not loaded yet
local upgradeCache = {}

local function ReadStats(link)
	local stats = C_Item.GetItemStats and C_Item.GetItemStats(link)
	if not stats then return nil end
	local mine, other, sockets = 0, false, 0
	for key, v in pairs(stats) do
		if key:find("^EMPTY_SOCKET_") then
			sockets = sockets + v
		elseif key:find("^ITEM_MOD_") and (key:find("STRENGTH") or key:find("AGILITY") or key:find("INTELLECT")) then
			if myStat and key:find(myStat) then mine = max(mine, v) else other = true end
		end
	end
	local n = C_Item.GetItemNumSockets and C_Item.GetItemNumSockets(link)
	if n and n > sockets then sockets = n end
	return mine, other and mine == 0, sockets
end

local function ReadEquipped(slot)
	local link = GetInventoryItemLink("player", slot)
	if not link then return false end
	local ilvl = C_Item.GetDetailedItemLevelInfo(link)
	local stat, _, sockets = ReadStats(link)
	if not ilvl or ilvl <= 1 or not stat then return nil end   -- not loaded yet
	return { ilvl = ilvl, stat = stat, sockets = sockets }
end

function GB:RefreshEquipped()
	wipe(equipped); wipe(upgradeCache)
	local spec = GetSpecialization and GetSpecialization()
	local primary = spec and select(6, GetSpecializationInfo(spec))
	myStat = STAT_WORD[primary]
end

local function Equipped(slot)
	local e = equipped[slot]
	if e == nil then
		e = ReadEquipped(slot)
		if e ~= nil then equipped[slot] = e end
	end
	return e
end

-- returns nil (no arrow) or { score = 1..3, ilvl = +n, stat = +n, sockets = +n, slot = n }
local function Evaluate(r)
	if not r.ilvl or r.ilvl <= 1 or not r.link then return false end
	local slots = SLOTS[r.equipLoc]
	if not slots then return false end
	if r.classID == 4 and r.equipLoc ~= "INVTYPE_CLOAK" and r.subclassID >= 1 and r.subclassID <= 4 then
		if r.subclassID ~= ARMOR[GB.class] then return false end
	end
	if C_Item.IsCosmeticItem and C_Item.IsCosmeticItem(r.link) then return false end
	if C_PlayerInfo and C_PlayerInfo.CanUseItem and not C_PlayerInfo.CanUseItem(r.itemID) then return false end

	local stat, wrongStat, sockets = ReadStats(r.link)
	if stat == nil then return nil end           -- item data still loading
	if wrongStat then return false end

	-- compare against the weakest of the slots it could go in
	local target, targetSlot
	for _, s in ipairs(slots) do
		local e = Equipped(s)
		if e == nil then return nil end           -- equipped gear still loading
		if e == false then target, targetSlot = false, s; break end
		if target == nil or e.ilvl < target.ilvl then target, targetSlot = e, s end
	end
	if target == false then return { score = 3, empty = true, slot = targetSlot } end

	local dIlvl = r.ilvl - target.ilvl
	local dStat = stat - target.stat
	local dSock = sockets - target.sockets
	local score = 0
	if dIlvl > 0 then score = score + 1 end
	if dStat > 0 then score = score + 1 end
	if dSock > 0 and dIlvl >= -SOCKET_ILVL_SLACK then score = score + 1 end
	if score == 0 then return false end
	return { score = score, ilvl = dIlvl, stat = dStat, sockets = dSock, slot = targetSlot }
end

function GB:UpgradeInfo(r)
	-- Pathway's gear scoring decides: class stat weights, can-use checks, rings/trinkets/2H
	if r.bankKind or r.saved or not r.link or not r.bag then return nil end
	local v = upgradeCache[r.link]
	if v == nil then
		local ok, up, why = pcall(P.EvaluateGear, P, r.bag, r.slot)
		if not ok then up = nil end
		if why == "loading" then return nil end
		v = false
		if up then
			local pct = up.pct
			v = { score = (not pct or pct >= 0.15) and 3 or (pct >= 0.06 and 2 or 1), pct = pct, empty = up.oldLink == nil, diff = P:GearDiff(up) }
		end
		upgradeCache[r.link] = v
	end
	return v or nil
end

function GB:IsUpgrade(r) return self:UpgradeInfo(r) ~= nil end
function GB:ClearUpgradeCache() wipe(equipped); wipe(upgradeCache) end
GB.STAT_NAME = function() return myStat and STAT_NAME[myStat] or "" end

---------------------------------------------------------------------------
-- Collection status (cached per link, cleared when collections change)
---------------------------------------------------------------------------
local collectCache = {}
local function Uncollected(r)
	local id, link = r.itemID, r.link
	if C_MountJournal and C_MountJournal.GetMountFromItem then
		local mountID = C_MountJournal.GetMountFromItem(id)
		if mountID then return not select(11, C_MountJournal.GetMountInfoByID(mountID)) end
	end
	if link and (r.classID == 2 or r.classID == 4) and C_TransmogCollection and r.equipLoc ~= ""
		and r.equipLoc ~= "INVTYPE_FINGER" and r.equipLoc ~= "INVTYPE_TRINKET" and r.equipLoc ~= "INVTYPE_NECK" then
		local appearanceID, sourceID = C_TransmogCollection.GetItemInfo(link)
		if not sourceID then return false end
		if C_TransmogCollection.PlayerHasTransmogByItemInfo(link) then return false end
		if appearanceID and C_TransmogCollection.GetAllAppearanceSources then
			for _, src in ipairs(C_TransmogCollection.GetAllAppearanceSources(appearanceID) or {}) do
				local info = C_TransmogCollection.GetSourceInfo(src)
				if info and info.isCollected then return false end
			end
		end
		return true
	end
	return false
end

function GB:IsUncollected(r)
	local key = r.link or r.itemID
	local v = collectCache[key]
	if v == nil then
		local ok, res = pcall(Uncollected, r)
		v = ok and res or false
		collectCache[key] = v
	end
	return v
end
function GB:ClearCollectCache() wipe(collectCache) end

---------------------------------------------------------------------------
-- Categories
---------------------------------------------------------------------------
GB.CATEGORIES = {
	{ key = "pinned",      title = "Pinned" },
	{ key = "crafting",    title = "Crafting Needs" },
	{ key = "equipment",   title = "Equipment" },
	{ key = "consumable",  title = "Consumables" },
	{ key = "quest",       title = "Quest" },
	{ key = "tradegoods",  title = "Trade Goods" },
	{ key = "collectible", title = "Collectibles" },
	{ key = "decor",       title = "Decor" },
	{ key = "recipe",      title = "Recipes" },
	{ key = "other",       title = "Other" },
	{ key = "junk",        title = "Junk" },
}

GB.craftNeeds = {}   -- [itemID] = { {name=, qty=, order=bool}, ... }  (filled by Features.lua)

function GB:IsJunk(r)
	if self.db.neverSell[r.itemID] then return false end
	if self.db.junk[r.itemID] then return true end
	return r.quality == 0 and not r.noValue
end

function GB:Classify(r)
	if self.db.pinned[r.itemID] or r.isKey then return "pinned" end
	if self:IsJunk(r) then return "junk" end
	if self.craftNeeds[r.itemID] then return "crafting" end
	local c, sc = r.classID, r.subclassID
	if r.isQuest or r.questID or c == 12 then return "quest" end
	if c == 20 then return "decor" end
	if (c == 2 or c == 4 or c == 19) and r.equipLoc ~= "" and r.equipLoc ~= "INVTYPE_NON_EQUIP_IGNORE" then return "equipment" end
	if c == 17 or (c == 15 and (sc == 2 or sc == 5)) then return "collectible" end
	if c == 0 then return "consumable" end
	if c == 5 or c == 7 or c == 3 or c == 8 or c == 19 then return "tradegoods" end
	if c == 9 then return "recipe" end
	return "other"
end

function GB.SortRecords(a, b)
	if a.quality ~= b.quality then return a.quality > b.quality end
	if (a.ilvl or 0) ~= (b.ilvl or 0) then return (a.ilvl or 0) > (b.ilvl or 0) end
	if a.classID ~= b.classID then return a.classID < b.classID end
	if a.subclassID ~= b.subclassID then return a.subclassID < b.subclassID end
	local an, bn = a.name or "", b.name or ""
	if an ~= bn then return an < bn end
	if a.itemID ~= b.itemID then return a.itemID < b.itemID end
	if a.count ~= b.count then return a.count > b.count end
	if a.bag ~= b.bag then return a.bag < b.bag end
	return a.slot < b.slot
end

function GB.BagOrder(a, b)
	if a.bag ~= b.bag then return a.bag < b.bag end
	return a.slot < b.slot
end

---------------------------------------------------------------------------
-- Search: plain text plus a few tokens
--   boe  wue  bound  junk  new  upgrade  uncollected  reagent  quest
--   ilvl>40  ilvl<20  ilvl=45   q:epic / q:4
---------------------------------------------------------------------------
local QUALITY = { poor = 0, common = 1, uncommon = 2, rare = 3, epic = 4, legendary = 5, artifact = 6, heirloom = 7 }
local parsed, parsedFor = {}, nil
local function Parse(q)
	if q == parsedFor then return parsed end
	parsedFor = q; parsed = {}
	for tok in q:lower():gmatch("%S+") do parsed[#parsed + 1] = tok end
	return parsed
end

function GB:Matches(r, query)
	if not query or query == "" then return true end
	for _, tok in ipairs(Parse(query)) do
		local ok
		local op, num = tok:match("^ilvl([<>=])(%d+)$")
		local q = tok:match("^q:(%w+)$")
		if op then
			local v, n = r.ilvl or 0, tonumber(num)
			ok = (op == ">" and v > n) or (op == "<" and v > 0 and v < n) or (op == "=" and v == n)
		elseif q then
			ok = r.quality == (tonumber(q) or QUALITY[q])
		elseif tok == "boe" then ok = self:BindType(r) == 2 and not r.bound
		elseif tok == "wue" or tok == "warbound" then ok = r.wue
		elseif tok == "bound" then ok = r.bound
		elseif tok == "junk" then ok = self:IsJunk(r)
		elseif tok == "new" then ok = self:IsNew(r.itemID)
		elseif tok == "upgrade" then ok = self:IsUpgrade(r)
		elseif tok == "uncollected" then ok = self:IsUncollected(r)
		elseif tok == "reagent" then ok = r.bag == self.REAGENT_BAG or r.classID == 5 or r.classID == 7
		elseif tok == "quest" then ok = r.isQuest or r.questID ~= nil or r.classID == 12
		else
			ok = (r.name and r.name:lower():find(tok, 1, true)) ~= nil
		end
		if not ok then return false end
	end
	return true
end

function GB:BindType(r)
	if r.bindType == nil and r.link then
		r.bindType = select(14, C_Item.GetItemInfo(r.link)) or false
	end
	return r.bindType
end

---------------------------------------------------------------------------
-- Character cache (for account-wide counts)
---------------------------------------------------------------------------
function GB:CharEntry()
	return self.db and self.charKey and self.db.chars[self.charKey]
end

function GB:SaveCharSnapshot()
	local me = self:CharEntry()
	if not me or self.leaving then return end
	if #self.slots == 0 and me.bags and next(me.bags) then return end   -- bags not loaded yet
	local bags = {}
	for id, c in pairs(self.counts) do bags[id] = c end
	for slot = 1, 19 do
		local id = GetInventoryItemID("player", slot)
		if id then bags[id] = (bags[id] or 0) + 1 end
	end
	me.bags, me.t = bags, time()
	local m = GetMoney()
	if m and m > 0 then me.money = m end   -- GetMoney() can read 0 while logging out
end

---------------------------------------------------------------------------
-- Lifecycle
---------------------------------------------------------------------------
function GB:RequestLayout() self:Send("LAYOUT") end

local function FullUpdate()
	if not GB.db then return end          -- bag events can fire before PLAYER_LOGIN
	if GB.leaving then return end         -- bags read as empty while logging out / zoning
	GB:ScanBags()
	if GB.bankOpen then GB:ScanBank() end
	GB:DiffNew()
	GB:RequestLayout()
end
GB.FullUpdate = FullUpdate

function GB:Init()
	PathwayBagsDB = merge(PathwayBagsDB or {}, DEFAULTS)
	PathwayBagsCharDB = merge(PathwayBagsCharDB or {}, CHAR_DEFAULTS)
	GB.db, GB.cdb = PathwayBagsDB, PathwayBagsCharDB

	local name, realm = UnitName("player"), GetNormalizedRealmName() or GetRealmName() or ""
	GB.class = select(2, UnitClass("player"))
	GB.charKey = name .. "-" .. realm
	GB.db.chars[GB.charKey] = GB.db.chars[GB.charKey] or {}
	local me = GB.db.chars[GB.charKey]
	me.name, me.realm, me.class = name, realm, GB.class
	me.bags, me.bank = me.bags or {}, me.bank or {}

	GB:RefreshEquipped()
	GB:ScanBags()
	GB:Send("READY")
	C_Timer.NewTicker(30, function() GB:AgeInbox() end)
end

GB:On("PLAYER_ENTERING_WORLD", function(_, isLogin, isReload)
	if isLogin or isReload then
		GB.silentUntil = GetTime() + 4
		C_Timer.After(4.2, function() GB:RefreshEquipped(); GB:ScanBags(); GB:Rebaseline(); GB:SaveCharSnapshot(); GB:RequestLayout() end)
	end
end)

GB:On("BAG_UPDATE_DELAYED", function() FullUpdate() end)
GB:On("BAG_CONTAINER_UPDATE", function() FullUpdate() end)
GB:On("PLAYER_SPECIALIZATION_CHANGED", function(_, unit)
	if unit and unit ~= "player" then return end
	GB:RefreshEquipped(); GB:Debounce("spec", 0.3, function() GB:RequestLayout() end)
end)
GB:On("PLAYER_EQUIPMENT_CHANGED", function()
	GB:RefreshEquipped()
	GB:Debounce("equip", 0.1, FullUpdate)
end)
-- names / bind types arrive late for uncached items: rescan once the burst settles
GB:On("GET_ITEM_INFO_RECEIVED", function() GB:Debounce("iteminfo", 0.5, FullUpdate) end)
for _, e in ipairs({ "TRANSMOG_COLLECTION_UPDATED", "NEW_TOY_ADDED", "NEW_MOUNT_ADDED", "NEW_PET_ADDED" }) do
	GB:On(e, function() GB:ClearCollectCache(); GB:Debounce("collect", 0.5, function() GB:RequestLayout() end) end)
end
GB:On("PLAYER_LEAVING_WORLD", function() GB.leaving = true end)
GB:On("PLAYER_ENTERING_WORLD", function() GB.leaving = false end)
GB:On("PLAYER_LOGOUT", function()
	local me = GB:CharEntry()
	local m = GetMoney()
	if me and m and m > 0 then me.money = m end
end)
GB:On("PLAYER_MONEY", function() local me = GB:CharEntry(); if me then me.money = GetMoney() end end)

-- Bank awareness for the inbox diff (bank items moving into bags are not "new")
GB:On("BANKFRAME_OPENED", function()
	GB.bankOpen = true
	GB.silentUntil = GetTime() + 1.5
	GB:ScanBags(); GB:ScanBank(); GB:Rebaseline()
	GB:Send("BANK_OPENED")
end)
GB:On("BANKFRAME_CLOSED", function()
	if not GB.bankOpen then return end
	-- don't re-read the bank here: it's already unreadable, and the last
	-- live scan (taken on every change while it was open) is the good copy
	GB.bankOpen = false
	GB:ScanBags(); GB:Rebaseline(); GB:SaveCharSnapshot()
	GB:Send("BANK_CLOSED")
end)
local function BankChanged() if GB.bankOpen then GB:Debounce("bank", 0.1, FullUpdate) end end
GB:On("PLAYERBANKSLOTS_CHANGED", BankChanged)
GB:On("PLAYER_ACCOUNT_BANK_TAB_SLOTS_CHANGED", BankChanged)
GB:On("BANK_TABS_CHANGED", BankChanged)
end part() end
