do local __addon, __ns = ... local function part()
-- Copyright (C) 2026 SoFinSicc. Part of Pathway (curseforge.com/wow/addons/pathway): free software under the GPLv3 or later, with additional terms that require keeping this credit. See LICENSE.md.
--[[ Lil's GoodBags — UI
     Flat windows, packed category layout, the Loot Inbox section, item
     buttons, Blizzard bag/bank takeover and the combat-safe layout queue. ]]

local ADDON, P = __addon, __ns
local GB = P.Bags
local C_Item, C_Container, C_Bank = P.Item, P.Container, P.BankAPI

local floor, ceil, max, min = math.floor, math.ceil, math.max, math.min
local ipairs, pairs, wipe, tinsert = ipairs, pairs, wipe, table.insert
local InCombatLockdown = InCombatLockdown

-- button methods differ between clients: call them only when they exist
local function Call(b, m, ...) local f = b[m]; if f then return f(b, ...) end end
local function Match(b, on)
	if b.SetMatchesSearch then b:SetMatchesSearch(on) else b:SetAlpha(on and 1 or 0.3) end
end
local function Cooldown(b)
	if b.UpdateCooldown then return b:UpdateCooldown(true) end
	local r = b.gbRecord
	if not (r and r.bag and b.Cooldown and C_Container.GetContainerItemCooldown) then return end
	local start, dur, enable = C_Container.GetContainerItemCooldown(r.bag, r.slot)
	if CooldownFrame_Set then CooldownFrame_Set(b.Cooldown, start, dur, enable) end
end

local WHITE = "Interface\\Buttons\\WHITE8X8"
local A = GB.ACCENT
local PAD, GAP, HEADER_H, SEC_GAP, TOP_H, FOOT_H = 10, 4, 20, 12, 34, 28
local SEARCH_H = 22
local HEAD_H = TOP_H + SEARCH_H + 6      -- title row + search row

-- Palette tables are shared by reference and re-filled by ApplyTheme, so
-- everything painted from them follows the theme, accent and opacity live.
local BG      = { 0.067, 0.075, 0.086, 0.96 }
local EDGE    = { 0.16, 0.18, 0.21, 1 }
local PANEL   = { 0.11, 0.12, 0.14, 1 }
local SLOT_BG = { 0.17, 0.19, 0.22, 1 }
local ACCENT_BG   = { A[1] * 0.22, A[2] * 0.22, A[3] * 0.22, 1 }
local ACCENT_EDGE = { A[1], A[2], A[3], 0.7 }
local ACCENT_SOFT = { A[1] * 0.12, A[2] * 0.12, A[3] * 0.12, 1 }

---------------------------------------------------------------------------
-- Fonts & flat widgets
---------------------------------------------------------------------------
local fontList = {}
local function MakeFont(name, size, flags, r, g, b)
	local f = CreateFont(name)
	f:SetFont(STANDARD_TEXT_FONT, size, flags or "")
	f:SetTextColor(r or 1, g or 1, b or 1)
	fontList[#fontList + 1] = { f, size, flags or "" }
	return f
end
local F_TITLE = MakeFont("PathwayBagsFontTitle", 13, "", 0.95, 0.96, 0.97)
local F_HEAD  = MakeFont("PathwayBagsFontHead", 10, "", 0.60, 0.65, 0.71)
local F_BTN   = MakeFont("PathwayBagsFontButton", 11, "", 0.93, 0.95, 0.96)
local F_TAG   = MakeFont("PathwayBagsFontTag", 10, "OUTLINE", 1, 1, 1)
local F_FREE  = MakeFont("PathwayBagsFontFree", 14, "", 0.55, 0.6, 0.66)
GB.fonts = { title = F_TITLE, head = F_HEAD, button = F_BTN, tag = F_TAG }

---------------------------------------------------------------------------
-- Themes
--   native : soft tooltip-style border, fits right in with Blizzard's UI
--   flat   : crisp 1px lines, the original GoodBags look
--   ui     : borrows colors and font from ElvUI when it's loaded
---------------------------------------------------------------------------
local painted = setmetatable({}, { __mode = "k" })
local paintHooks = {}
local winStyle = { bgFile = WHITE, edgeFile = WHITE, edgeSize = 1 }
local FLAT_STYLE = { bgFile = WHITE, edgeFile = WHITE, edgeSize = 1 }
local NATIVE_STYLE = { bgFile = WHITE, edgeFile = "Interface\\Tooltips\\UI-Tooltip-Border", edgeSize = 14,
	insets = { left = 3, right = 3, top = 3, bottom = 3 } }

local function Paint(f)
	local d = painted[f]
	if not d then return end
	f:SetBackdrop(d.window and winStyle or FLAT_STYLE)
	f:SetBackdropColor(unpack(d.bg))
	f:SetBackdropBorderColor(unpack(d.edge))
end

local function Flat(f, bg, edge, isWindow)
	painted[f] = { bg = bg or (isWindow and BG) or PANEL, edge = edge or EDGE, window = isWindow }
	Paint(f)
end
GB.Flat = Flat
function GB:OnPaint(fn) paintHooks[#paintHooks + 1] = fn end

local function ElvUIMedia()
	local E = ElvUI and type(ElvUI) == "table" and ElvUI[1]
	return E and E.media
end

local function fill(t, r, g, b, a) t[1], t[2], t[3], t[4] = r, g, b, a or 1 end

function GB:ApplyTheme()
	local s = self.db and self.db.settings
	if not s then return end
	local ac = (P.db and P.db.settings.accent) or s.accent or { 0.431, 0.906, 0.718 }
	A[1], A[2], A[3] = ac[1], ac[2], ac[3]
	self.ACCENT_HEX = ("ff%02x%02x%02x"):format(floor(A[1] * 255 + 0.5), floor(A[2] * 255 + 0.5), floor(A[3] * 255 + 0.5))
	self.TITLE = "|c" .. self.ACCENT_HEX .. "Path|rway  |cffd8dde3Bags|r"
	fill(ACCENT_BG, A[1] * 0.22, A[2] * 0.22, A[3] * 0.22, 1)
	fill(ACCENT_EDGE, A[1], A[2], A[3], 0.7)
	fill(ACCENT_SOFT, A[1] * 0.12, A[2] * 0.12, A[3] * 0.12, 1)

	local alpha = s.bgAlpha or 0.95
	local theme, font = s.theme or "native", STANDARD_TEXT_FONT
	local m = theme == "ui" and ElvUIMedia()
	if m then
		local bc = m.backdropfadecolor or m.backdropcolor or { 0.06, 0.06, 0.06 }
		local ec = m.bordercolor or { 0, 0, 0 }
		fill(BG, bc[1], bc[2], bc[3], alpha)
		fill(EDGE, ec[1], ec[2], ec[3], 1)
		fill(PANEL, bc[1] + 0.04, bc[2] + 0.04, bc[3] + 0.04, 1)
		fill(SLOT_BG, bc[1] + 0.08, bc[2] + 0.08, bc[3] + 0.08, 1)
		winStyle = FLAT_STYLE
		font = m.normFont or font
	elseif theme == "flat" then
		fill(BG, 0.067, 0.075, 0.086, alpha); fill(EDGE, 0.16, 0.18, 0.21, 1)
		fill(PANEL, 0.11, 0.12, 0.14, 1); fill(SLOT_BG, 0.17, 0.19, 0.22, 1)
		winStyle = FLAT_STYLE
	else -- native
		fill(BG, 0.035, 0.04, 0.05, alpha); fill(EDGE, 0.24, 0.26, 0.3, 1)
		fill(PANEL, 0.1, 0.11, 0.13, 0.95); fill(SLOT_BG, 0.15, 0.16, 0.185, 1)
		winStyle = NATIVE_STYLE
	end
	-- the window border in native mode is the tooltip edge, tinted
	if theme == "native" then self.WINDOW_EDGE = { 0.62, 0.64, 0.7, 1 } else self.WINDOW_EDGE = EDGE end
	for f, d in pairs(painted) do
		if d.window then d.edge = self.WINDOW_EDGE end
		Paint(f)
	end

	local scale = ({ small = -1, normal = 0, large = 1.5 })[s.fontSize or "normal"] or 0
	for _, e in ipairs(fontList) do e[1]:SetFont(font, e[2] + scale, e[3]) end
	for _, fn in ipairs(paintHooks) do fn() end
end

function GB:FlatButton(parent, label, accent)
	local b = CreateFrame("Button", nil, parent, "BackdropTemplate")
	b:SetHeight(20)
	b.text = b:CreateFontString(nil, "OVERLAY")
	b.text:SetFontObject(F_BTN)
	b.text:SetPoint("CENTER")
	local bg = accent and ACCENT_BG or PANEL
	local edge = accent and ACCENT_EDGE or EDGE
	Flat(b, bg, edge)
	b:SetScript("OnEnter", function(self)
		self:SetBackdropBorderColor(A[1], A[2], A[3], 1)
		if self.tip then
			GameTooltip:SetOwner(self, "ANCHOR_TOP")
			GameTooltip:SetText(self.tip, 1, 1, 1, 1, true)
			GameTooltip:Show()
		end
	end)
	b:SetScript("OnLeave", function(self) self:SetBackdropBorderColor(unpack(edge)); GameTooltip:Hide() end)
	function b:SetLabel(t) self.text:SetText(t); self:SetWidth(max(self.minW or 0, self.text:GetStringWidth() + 18)) end
	b:SetLabel(label or "")
	return b
end

-- small square button with an icon (gear, etc.)
function GB:IconButton(parent, texture, tip)
	local b = CreateFrame("Button", nil, parent, "BackdropTemplate")
	b:SetSize(22, 20)
	Flat(b, PANEL, EDGE)
	b.icon = b:CreateTexture(nil, "ARTWORK")
	b.icon:SetSize(14, 14); b.icon:SetPoint("CENTER")
	b.icon:SetTexture(texture)
	b.icon:SetVertexColor(0.85, 0.88, 0.92)
	b.tip = tip
	b:RegisterForClicks("LeftButtonUp", "RightButtonUp")
	b:SetScript("OnEnter", function(self)
		self:SetBackdropBorderColor(A[1], A[2], A[3], 1); self.icon:SetVertexColor(1, 1, 1)
		if self.tip then GameTooltip:SetOwner(self, "ANCHOR_TOP"); GameTooltip:SetText(self.tip, 1, 1, 1, 1, true); GameTooltip:Show() end
	end)
	b:SetScript("OnLeave", function(self)
		self:SetBackdropBorderColor(unpack(EDGE)); self.icon:SetVertexColor(0.85, 0.88, 0.92); GameTooltip:Hide()
	end)
	return b
end

---------------------------------------------------------------------------
-- Window factory (bags + bank share it)
---------------------------------------------------------------------------
local windows = {}

local function SavePos(w)
	local p, _, rp, x, y = w:GetPoint()
	GB.db.pos[w:GetName()] = { p, rp, x, y }
end

local function RestorePos(w, default)
	local pos = GB.db.pos[w:GetName()] or default
	w:ClearAllPoints()
	w:SetPoint(pos[1], UIParent, pos[2], pos[3], pos[4])
end

local function CreateWindow(name, title)
	local w = CreateFrame("Frame", name, UIParent, "BackdropTemplate")
	Flat(w, BG, EDGE, true)
	w:SetFrameStrata("MEDIUM")
	w:SetToplevel(true)
	w:SetClampedToScreen(true)
	w:SetMovable(true)
	w:EnableMouse(true)
	w:Hide()
	tinsert(UISpecialFrames, name)
	windows[#windows + 1] = w

	-- header / drag strip
	local hdr = CreateFrame("Frame", nil, w)
	hdr:SetPoint("TOPLEFT"); hdr:SetPoint("TOPRIGHT"); hdr:SetHeight(TOP_H)
	hdr:EnableMouse(true)
	hdr:RegisterForDrag("LeftButton")
	hdr:SetScript("OnDragStart", function() w:StartMoving() end)
	hdr:SetScript("OnDragStop", function() w:StopMovingOrSizing(); SavePos(w) end)
	w.header = hdr

	local accentBar = w:CreateTexture(nil, "ARTWORK")
	accentBar:SetPoint("TOPLEFT", 4, -4); accentBar:SetPoint("TOPRIGHT", -4, -4); accentBar:SetHeight(2)
	w.accentBar = accentBar

	w.title = hdr:CreateFontString(nil, "OVERLAY")
	w.title:SetFontObject(F_TITLE)
	w.title:SetPoint("LEFT", PAD + 2, -1)
	w.titleFn = type(title) == "function" and title or function() return title end
	w.title:SetText(w.titleFn())
	GB:OnPaint(function()
		accentBar:SetColorTexture(A[1], A[2], A[3], 0.85)
		w.title:SetText(w.titleFn())
	end)

	local close = CreateFrame("Button", nil, hdr)
	close:SetSize(20, 20)
	close:SetPoint("RIGHT", -PAD + 2, -1)
	close.t = close:CreateFontString(nil, "OVERLAY"); close.t:SetFontObject(F_TITLE); close.t:SetPoint("CENTER"); close.t:SetText("×")
	close.t:SetTextColor(0.6, 0.65, 0.7)
	close:SetScript("OnEnter", function(s) s.t:SetTextColor(1, 0.45, 0.45) end)
	close:SetScript("OnLeave", function(s) s.t:SetTextColor(0.6, 0.65, 0.7) end)
	close:SetScript("OnClick", function() w:Hide() end)
	w.close = close

	-- search
	local sb = CreateFrame("EditBox", nil, w, "BackdropTemplate")
	Flat(sb, PANEL)
	sb:SetHeight(SEARCH_H)
	sb:SetPoint("TOPLEFT", PAD, -TOP_H)
	sb:SetPoint("TOPRIGHT", -PAD, -TOP_H)
	sb:SetAutoFocus(false)
	sb:SetFontObject(F_BTN)
	sb:SetTextInsets(8, 8, 0, 0)
	sb.ph = sb:CreateFontString(nil, "OVERLAY")
	sb.ph:SetFontObject(F_HEAD); sb.ph:SetPoint("LEFT", 9, 0); sb.ph:SetPoint("RIGHT", -9, 0)
	sb.ph:SetJustifyH("LEFT"); sb.ph:SetWordWrap(false)
	sb.ph:SetText("Search   ·   try  boe,  junk,  upgrade,  ilvl>40,  q:epic")
	sb.icon = sb:CreateTexture(nil, "OVERLAY")
	sb.icon:SetSize(12, 12); sb.icon:SetPoint("RIGHT", -7, 0)
	sb.icon:SetTexture("Interface\\Common\\UI-Searchbox-Icon")
	sb.icon:SetVertexColor(0.6, 0.65, 0.7)
	sb:SetScript("OnEscapePressed", function(s) s:SetText(""); s:ClearFocus() end)
	sb:SetScript("OnEnterPressed", function(s) s:ClearFocus() end)
	sb:SetScript("OnEditFocusGained", function(s) s:SetBackdropBorderColor(A[1], A[2], A[3], 1) end)
	sb:SetScript("OnEditFocusLost", function(s) s:SetBackdropBorderColor(unpack(EDGE)) end)
	sb:SetScript("OnTextChanged", function(s)
		local t = s:GetText()
		s.ph:SetShown(t == "")
		w.query = t
		GB:RefreshSearch(w)
	end)
	w.search = sb

	-- content + footer
	w.content = CreateFrame("Frame", nil, w)
	w.content:SetPoint("TOPLEFT", PAD, -HEAD_H)
	w.footer = CreateFrame("Frame", nil, w)
	w.footer:SetPoint("BOTTOMLEFT", PAD, 6); w.footer:SetPoint("BOTTOMRIGHT", -PAD, 6); w.footer:SetHeight(FOOT_H - 6)

	w.buttons, w.holders, w.headers, w.shown = {}, {}, {}, {}
	w.freeRecs = { normal = { free = true }, reagent = { free = true, reagent = true } }
	w.dirty = true
	w:SetScript("OnShow", function(self)
		self:SetScale(GB.db.settings.scale)
		if self.dirty then GB:Layout(self, true) end
		PlaySound(SOUNDKIT.IG_BACKPACK_OPEN)
	end)
	return w
end

---------------------------------------------------------------------------
-- Item buttons
--   Each bag gets an invisible holder frame whose ID is the bag ID; buttons
--   are Blizzard's own ContainerFrameItemButtonTemplate parented to it, so
--   clicking, using, dragging, selling and banking stay 100% Blizzard code.
---------------------------------------------------------------------------
local function Holder(w, bag)
	local h = w.holders[bag]
	if not h then
		h = CreateFrame("Frame", nil, w.content)
		h:SetAllPoints(w.content)
		h:SetID(bag)
		h.IsCombinedBagContainer = function() return false end
		h.MatchesBagID = function(self, id) return self:GetID() == id end
		w.holders[bag] = h
	end
	return h
end

local function ItemClickHook(self, button)
	local r = self.gbRecord
	if not r or r.free or r.empty then return end
	-- Shift+Right-Click: our split window (Blizzard's would pop up too; we close it)
	if button == "RightButton" and IsShiftKeyDown() and not IsAltKeyDown() and not IsControlKeyDown() and not r.saved
		and (r.count or 1) > 1 then
		GB:OpenSplit(self, r)
		return
	end
	if not IsAltKeyDown() or IsShiftKeyDown() or IsControlKeyDown() then return end
	if button == "LeftButton" then
		GB:ShowCopyBox(r)
	elseif button == "RightButton" then
		if self.gbSection == "inbox" then
			local locked = GB:ToggleLock(r.itemID)
			GB:Toast(locked and "Kept in Inbox — won't be swept" or "Released — will sort normally")
		else
			GB:ItemMenu(self, r)
		end
	end
end

local function Skin(b)
	b.gbBG = b:CreateTexture(nil, "BACKGROUND", nil, -7)
	b.gbBG:SetAllPoints()
	b.gbBG:SetColorTexture(unpack(SLOT_BG))

	b.icon:ClearAllPoints()
	b.icon:SetPoint("TOPLEFT", 1, -1)
	b.icon:SetPoint("BOTTOMRIGHT", -1, 1)
	b.icon:SetTexCoord(0.08, 0.92, 0.08, 0.92)

	if b.ClearNormalTexture then b:ClearNormalTexture() elseif b:GetNormalTexture() then b:GetNormalTexture():SetAlpha(0) end
	if b.IconBorder then b.IconBorder:SetAlpha(0) end
	local hl = b:GetHighlightTexture()
	if hl then hl:SetColorTexture(1, 1, 1, 0.14); hl:ClearAllPoints(); hl:SetAllPoints(b.icon) end
	local pt = b:GetPushedTexture()
	if pt then pt:SetColorTexture(1, 1, 1, 0.22); pt:ClearAllPoints(); pt:SetAllPoints(b.icon) end
	if b.Count then b.Count:ClearAllPoints(); b.Count:SetPoint("BOTTOMRIGHT", -2, 2) end
	if b.BattlepayItemTexture then b.BattlepayItemTexture:SetAlpha(0) end
	if b.ExtendedSlot then b.ExtendedSlot:SetAlpha(0) end
	if b.IconQuestTexture then b.IconQuestTexture:ClearAllPoints(); b.IconQuestTexture:SetAllPoints(b.icon) end
	if b.NewItemTexture then
		b.NewItemTexture:ClearAllPoints()
		b.NewItemTexture:SetPoint("TOPLEFT", -3, 3); b.NewItemTexture:SetPoint("BOTTOMRIGHT", 3, -3)
	end
	if b.flash then b.flash:SetAlpha(0) end
	if b.UpgradeIcon then
		b.UpgradeIcon:ClearAllPoints(); b.UpgradeIcon:SetPoint("TOPRIGHT", 1, 1); b.UpgradeIcon:SetSize(15, 15)
		-- glow behind the arrow for 2- and 3-way upgrades
		local g = b:CreateTexture(nil, "OVERLAY", nil, 1)
		g:SetAtlas("bags-greenarrow")
		g:SetBlendMode("ADD")
		g:SetPoint("CENTER", b.UpgradeIcon, "CENTER")
		g:SetSize(24, 24)
		g:SetVertexColor(0.4, 1, 0.45)
		g:Hide()
		local ag = g:CreateAnimationGroup()
		ag:SetLooping("BOUNCE")
		local a1 = ag:CreateAnimation("Alpha"); a1:SetFromAlpha(0.35); a1:SetToAlpha(1); a1:SetDuration(0.8); a1:SetSmoothing("IN_OUT")
		g.pulse = ag
		b.gbUpGlow = g
	end
	if b.JunkIcon then b.JunkIcon:ClearAllPoints(); b.JunkIcon:SetPoint("TOPLEFT", 1, -1); b.JunkIcon:SetSize(13, 12) end

	local function tag(point, x, y)
		local fs = b:CreateFontString(nil, "OVERLAY", nil, 7)
		fs:SetFontObject(F_TAG)
		fs:SetPoint(point, x, y)
		return fs
	end
	b.gbIlvl = tag("BOTTOMRIGHT", -2, 2)
	b.gbBind = tag("BOTTOMLEFT", 2, 2)
	b.gbNew  = tag("TOPLEFT", 2, -2)
	b.gbNew:SetTextColor(A[1], A[2], A[3])
	b.gbQueue = tag("TOPRIGHT", -2, -2)
	b.gbQueue:SetTextColor(1, 0.82, 0.48)

	b.gbDot = b:CreateTexture(nil, "OVERLAY", nil, 7)
	b.gbDot:SetSize(6, 6)
	b.gbDot:SetColorTexture(0.85, 0.45, 1, 1)

	b.gbSet = b:CreateTexture(nil, "OVERLAY", nil, 6)
	b.gbSet:SetSize(7, 7)
	b.gbSet:SetPoint("LEFT", 2, 0)
	b.gbSet:SetColorTexture(0.35, 0.68, 1, 1)
	b.gbSet:Hide()
	if b.gbPair then b.gbPair:SetText(""); b.gbPairBG:Hide() end

	-- linked split stacks: a tiny pill with the other stack's count
	b.gbPairBG = b:CreateTexture(nil, "OVERLAY", nil, 5)
	b.gbPairBG:SetColorTexture(0, 0, 0, 0.75)
	b.gbPairBG:Hide()
	b.gbPair = b:CreateFontString(nil, "OVERLAY", nil, 7)
	b.gbPair:SetFontObject(F_TAG)
	b.gbPair:SetPoint("TOP", 0, -1)
	b.gbPairBG:SetPoint("TOPLEFT", b.gbPair, "TOPLEFT", -2, 1)
	b.gbPairBG:SetPoint("BOTTOMRIGHT", b.gbPair, "BOTTOMRIGHT", 2, -1)

	b.gbLock = b:CreateTexture(nil, "OVERLAY", nil, 7)
	b.gbLock:SetSize(12, 12)
	b.gbLock:SetPoint("TOPLEFT", 1, -1)
	b.gbLock:SetTexture("Interface\\PetBattles\\PetBattle-LockIcon")
	b.gbLock:SetVertexColor(A[1], A[2], A[3])

	b.gbFree = b:CreateFontString(nil, "OVERLAY")
	b.gbFree:SetFontObject(F_FREE)
	b.gbFree:SetPoint("CENTER", 0, 3)
	b.gbFreeSub = b:CreateFontString(nil, "OVERLAY")
	b.gbFreeSub:SetFontObject(F_HEAD)
	b.gbFreeSub:SetPoint("BOTTOM", 0, 3)

	b:HookScript("OnClick", ItemClickHook)
end

local function GetButton(w, bag, slot)
	local t = w.buttons[bag]
	if not t then t = {}; w.buttons[bag] = t end
	local b = t[slot]
	if not b then
		b = CreateFrame("ItemButton", nil, Holder(w, bag), "ContainerFrameItemButtonTemplate")
		b:SetID(slot)
		Skin(b)
		t[slot] = b
	end
	return b
end

local function ClearTags(b)
	b.gbIlvl:SetText(""); b.gbBind:SetText(""); b.gbNew:SetText(""); b.gbQueue:SetText("")
	b.gbSet:Hide()
	b.gbDot:Hide(); b.gbLock:Hide()
	if b.UpgradeIcon then b.UpgradeIcon:Hide() end
	if b.gbUpGlow then b.gbUpGlow:Hide(); b.gbUpGlow.pulse:Stop() end
	if b.JunkIcon then b.JunkIcon:Hide() end
	if b.NewItemTexture then b.NewItemTexture:Hide() end
	if b.newitemglowAnim and b.newitemglowAnim:IsPlaying() then b.newitemglowAnim:Stop() end
end

local function Glow(b, on)
	if not b.NewItemTexture then return end
	if on then
		b.NewItemTexture:SetAtlas("bags-glow-white")
		b.NewItemTexture:SetVertexColor(A[1], A[2], A[3])
		b.NewItemTexture:Show()
		if not b.newitemglowAnim:IsPlaying() then b.newitemglowAnim:Play() end
	end
end

function GB:UpdateButton(b, r, section, w)
	b.gbRecord, b.gbSection = r, section
	ClearTags(b)
	local s = self.db.settings

	if r.empty then
		SetItemButtonTexture(b, nil)
		SetItemButtonCount(b, 0)
		Call(b, "SetHasItem", false)
		if b.Cooldown then b.Cooldown:Hide() end
		if b.IconQuestTexture then b.IconQuestTexture:Hide() end
		b.gbFree:Hide(); b.gbFreeSub:Hide()
		b.gbBG:SetColorTexture(0.12, 0.13, 0.15, 1)
		Match(b, not (w and w.query and w.query ~= ""))
		return
	end
	if r.free then
		SetItemButtonTexture(b, nil)
		SetItemButtonCount(b, 0)
		Call(b, "SetHasItem", false)
		if b.Cooldown then b.Cooldown:Hide() end
		if b.IconQuestTexture then b.IconQuestTexture:Hide() end
		b.gbBG:SetColorTexture(0.12, 0.13, 0.15, 1)
		b.gbFree:SetText(r.freeCount or 0); b.gbFree:Show()
		b.gbFreeSub:SetText(r.reagent and "reagent" or "free"); b.gbFreeSub:Show()
		Match(b, true)
		return
	end
	b.gbFree:Hide(); b.gbFreeSub:Hide()

	SetItemButtonTexture(b, r.icon)
	SetItemButtonCount(b, r.count)
	SetItemButtonQuality(b, r.quality, r.link, false, r.bound)
	if b.IconBorder then b.IconBorder:SetAlpha(0) end
	SetItemButtonDesaturated(b, r.locked)
	Call(b, "SetReadable", r.readable)
	Call(b, "UpdateQuestItem", r.isQuest, r.questID, r.questActive)
	Cooldown(b)

	local q, tint = r.quality or 1, s.qualityTint or "full"
	b.gbNew:SetTextColor(A[1], A[2], A[3])
	if q >= 2 and tint ~= "off" then
		local cr, cg, cb = C_Item.GetItemQualityColor(q)
		if tint == "subtle" then
			b.gbBG:SetColorTexture(SLOT_BG[1] * 0.5 + cr * 0.5, SLOT_BG[2] * 0.5 + cg * 0.5, SLOT_BG[3] * 0.5 + cb * 0.5, 1)
		else
			b.gbBG:SetColorTexture(cr, cg, cb, 1)
		end
	elseif q == 0 and tint ~= "off" then
		b.gbBG:SetColorTexture(0.3, 0.3, 0.3, 1)
	else
		b.gbBG:SetColorTexture(unpack(SLOT_BG))
	end

	if s.showIlvl and r.ilvl and r.ilvl > 1 then b.gbIlvl:SetText(r.ilvl) end
	if r.isKey and r.keyLevel then
		b.gbIlvl:SetText("|cffffd27a+" .. r.keyLevel .. "|r")
		b.gbBind:SetText(GB:KeystoneShort(r.keyMap))
	end
	if s.showSets and r.inSet then b.gbSet:Show() end
	if not r.saved and GB.SplitPartner then
		local other = GB:SplitPartner(r)
		if other then
			b.gbPair:SetText(other); b.gbPair:SetTextColor(A[1], A[2], A[3]); b.gbPairBG:Show()
		end
	end
	-- queued for the next bank visit
	if r.saved and self.cdb.withdraw[r.itemID] then b.gbQueue:SetText("take")
	elseif not r.bankKind and not r.saved and self.cdb.toBank[r.itemID] then b.gbQueue:SetText("bank") end
	if s.showBind then
		if r.wue then b.gbBind:SetText("|cff66bbffWuE|r")
		elseif not r.bound and self:BindType(r) == 2 then b.gbBind:SetText("|cff7cf29cBoE|r") end
	end
	local up = s.showUpgrade and b.UpgradeIcon and self:UpgradeInfo(r)
	local upgrade = up ~= nil and up ~= false
	if upgrade then
		-- 1 reason: soft arrow · 2 reasons: full arrow + glow · 3 reasons: glow pulses
		b.UpgradeIcon:SetAlpha(up.score >= 2 and 1 or 0.55)
		b.UpgradeIcon:Show()
		if up.score >= 2 then
			b.gbUpGlow:SetAlpha(up.score >= 3 and 1 or 0.55)
			b.gbUpGlow:Show()
			if up.score >= 3 then b.gbUpGlow.pulse:Play() end
		end
	end
	if false and s.showCollect and self:IsUncollected(r) then  -- no transmog or collections on Forever
		b.gbDot:ClearAllPoints()
		b.gbDot:SetPoint("TOPRIGHT", -3, upgrade and -15 or -3)
		b.gbDot:Show()
	end
	if b.JunkIcon and MerchantFrame and MerchantFrame:IsShown() and self:IsJunk(r) then b.JunkIcon:Show() end

	if section == "inbox" or section == "session" then
		Glow(b, section == "inbox")
		if section == "inbox" and self:IsLocked(r.itemID) then
			b.gbLock:Show()
		elseif not r.badgeHidden then
			local n = section == "session" and self.session and self.session.gains[r.itemID]
				or (self.cdb.inbox[r.itemID] and self.cdb.inbox[r.itemID].n)
			if n and n > 0 then b.gbNew:SetText("+" .. n) end
		end
	end

	Match(b, self:Matches(r, w and w.query))
end

function GB:RefreshSearch(w)
	for b in pairs(w.shown) do
		local r = b.gbRecord
		if r and r.empty then Match(b, not (w.query and w.query ~= ""))
		elseif r and not r.free then Match(b, self:Matches(r, w.query)) end
	end
end

---------------------------------------------------------------------------
-- Section headers
---------------------------------------------------------------------------
local function AcquireHeader(w, i)
	local h = w.headers[i]
	if not h then
		h = CreateFrame("Button", nil, w.content)
		h:SetHeight(HEADER_H)
		h.label = h:CreateFontString(nil, "OVERLAY")
		h.label:SetFontObject(F_HEAD)
		h.label:SetPoint("LEFT", 0, 1)
		h.label:SetJustifyH("LEFT")
		h.line = h:CreateTexture(nil, "ARTWORK")
		h.line:SetHeight(1)
		h.line:SetPoint("LEFT", h.label, "RIGHT", 6, 0)
		h.line:SetPoint("RIGHT", 0, 1)
		h.line:SetColorTexture(1, 1, 1, 0.06)
		h:SetScript("OnClick", function(self, button)
			if self.onClick then self.onClick(self, button) return end
			if not self.key or not self.collapsible then return end
			GB.db.collapsed[self.key] = not GB.db.collapsed[self.key] or nil
			GB:Layout(w)
		end)
		h:SetScript("OnEnter", function(self) if self.collapsible then self.label:SetTextColor(A[1], A[2], A[3]) end end)
		h:SetScript("OnLeave", function(self) self.label:SetTextColor(0.60, 0.65, 0.71) end)
		w.headers[i] = h
	end
	return h
end

---------------------------------------------------------------------------
-- Packed layout: sections flow left→right and wrap, like words in a line.
---------------------------------------------------------------------------
function GB:Layout(w, opening)
	if not w or not self.db then return end
	if not w:IsShown() then w.dirty = true; return end
	-- opening a window mid-fight is fine (nothing under the cursor yet);
	-- reshuffling one that's already open is not
	if InCombatLockdown() and not opening then
		-- never shuffle buttons under the cursor mid-fight; refresh in place
		w.dirty = true
		self.combatQueued = true
		self:RefreshInPlace(w)
		if w.OnCombatQueued then w:OnCombatQueued() end
		return
	end
	w.dirty = false

	local s = self.db.settings
	local cols, size = w.cols or s.cols, s.iconSize
	local cell = size + GAP
	local innerW = cols * cell - GAP
	local sections = w:BuildSections()

	for _, h in ipairs(w.headers) do h:Hide() end
	local prevShown = w.shown
	w.shown = {}

	local x, y, rowH, hi = 0, 0, 0, 0
	for _, sec in ipairs(sections) do
		local items = sec.items or {}
		local n = #items
		if n > 0 or sec.alwaysShow then
			local collapsed = sec.collapsible ~= false and self.db.collapsed[sec.key]
			local wCells = sec.fullWidth and cols or min(max(n, sec.minCells or 3), cols)
			local secW = wCells * cell - GAP
			if x > 0 and (sec.fullWidth or x + secW > innerW + 1) then
				y = y + rowH; x = 0; rowH = 0
			end

			if not sec.noHeader then
				hi = hi + 1
				local h = AcquireHeader(w, hi)
				h.key, h.collapsible, h.onClick = sec.key, sec.collapsible ~= false, sec.onHeaderClick
				h:RegisterForClicks("LeftButtonUp", "RightButtonUp")
				h:ClearAllPoints()
				h:SetPoint("TOPLEFT", w.content, "TOPLEFT", x, -y)
				h:SetWidth(secW)
				local count = sec.countText or (n > 0 and ("  |cff6b7480" .. n .. "|r") or "")
				local chevron = (h.collapsible and collapsed) and "|cff6b7480+|r  " or ""
				h.label:SetText(chevron .. (sec.titleColor or "") .. sec.title:upper() .. "|r" .. count)
				h:Show()
			end

			local top = y + (sec.noHeader and 0 or HEADER_H) + (sec.extraTop or 0)
			local rows = 0
			if not collapsed then
				for i, r in ipairs(items) do
					local col, row = (i - 1) % wCells, floor((i - 1) / wCells)
					local b = w.AcquireButton and w:AcquireButton(r) or GetButton(w, r.bag, r.slot)
					b:ClearAllPoints()
					b:SetPoint("TOPLEFT", w.content, "TOPLEFT", x + col * cell, -(top + row * cell))
					b:SetSize(size, size)
					self:UpdateButton(b, r, sec.key, w)
					b:Show()
					w.shown[b] = true
				end
				rows = ceil(n / wCells)
			end
			local itemsBottom = top + rows * cell - (rows > 0 and GAP or 0)
			if sec.onPlace then sec.onPlace(w, x, itemsBottom + (rows > 0 and 6 or 2), secW) end
			local secH = (itemsBottom - y) + (sec.extraBottom or 0)
			rowH = max(rowH, secH + SEC_GAP)
			x = x + secW + SEC_GAP
			if sec.fullWidth then y = y + rowH; x = 0; rowH = 0 end
		end
	end
	y = y + rowH

	for b in pairs(prevShown) do if not w.shown[b] then b:Hide(); b.gbRecord = nil end end
	if w.AfterLayout then w:AfterLayout() end

	local contentH = max(y - SEC_GAP, 30)
	w.content:SetSize(innerW, contentH)
	if w.OnSized then w:OnSized(innerW, contentH) else
		w:SetSize(innerW + PAD * 2, HEAD_H + contentH + 8 + FOOT_H)
	end
end

-- combat: same buttons, same places, fresh icons/counts/cooldowns
function GB:RefreshInPlace(w)
	local idx = w.isBank and (self.bank.index or {}) or self.index
	for b in pairs(w.shown) do
		local old = b.gbRecord
		if old and not old.free and old.bag and old.slot then
			local r = idx[old.bag * 1000 + old.slot]
			if r then self:UpdateButton(b, r, b.gbSection, w)
			else
				SetItemButtonTexture(b, nil); SetItemButtonCount(b, 0); Call(b, "SetHasItem", false); ClearTags(b)
				b.gbBG:SetColorTexture(0.12, 0.13, 0.15, 1)
			end
		end
	end
end

---------------------------------------------------------------------------
-- The bag window
---------------------------------------------------------------------------
local bags

local function FreeRecord(w, kind, f)
	local r = w.freeRecs[kind]
	if not f.bag then return nil end
	r.bag, r.slot, r.freeCount = f.bag, f.slot, f.n
	return r
end

-- "Bags" view: every bag as it really is, slot by slot, each with an optional label
local emptyRecs = {}
local function EmptyRecord(bag, slot)
	local k = bag * 1000 + slot
	local r = emptyRecs[k]
	if not r then r = { bag = bag, slot = slot, empty = true }; emptyRecs[k] = r end
	return r
end

local function BuildBagViewSections(w)
	local sections = {}
	sections[#sections + 1] = { key = "bagsbar", title = "Your bags", fullWidth = true, alwaysShow = true, collapsible = false,
		countText = "  |cff6b7480click a bag's name to label it|r", extraBottom = 26, onPlace = w.PlaceLabelBar }
	for _, bag in ipairs(GB.BAGS) do
		local n = C_Container.GetContainerNumSlots(bag) or 0
		if n > 0 then
			local items = {}
			for slot = 1, n do items[slot] = GB.index[bag * 1000 + slot] or EmptyRecord(bag, slot) end
			local label = GB:BagLabel(bag)
			local free = 0
			for _, r in ipairs(items) do if r.empty then free = free + 1 end end
			sections[#sections + 1] = {
				key = "bag" .. bag, items = items, collapsible = false, minCells = math.min(n, 4),
				title = GB:BagName(bag) .. (label and ("  |c" .. GB.ACCENT_HEX .. label.title .. "|r") or ""),
				countText = "  |cff6b7480" .. free .. " free|r",
				onHeaderClick = function(h) if GB:CanLabel(bag) then GB:LabelMenu(h, bag) end end,
			}
		end
	end
	return sections
end

local function BuildBagSections(w)
	if GB.db.settings.view == "bags" then return BuildBagViewSections(w) end
	local sections = {}
	local inbox, session = {}, {}
	local rest = {}
	local sess = GB.session and GB.session.active and GB.session
	local seenNew, seenSess = {}, {}

	for _, r in ipairs(GB.slots) do
		r.badgeHidden = nil
		if sess and sess.gains[r.itemID] then
			r.badgeHidden = seenSess[r.itemID]; seenSess[r.itemID] = true
			session[#session + 1] = r
		elseif GB.cdb.inbox[r.itemID] then
			r.badgeHidden = seenNew[r.itemID]; seenNew[r.itemID] = true
			inbox[#inbox + 1] = r
		else
			rest[#rest + 1] = r
		end
	end

	if not GB.db.settings.welcomed then
		sections[#sections + 1] = { key = "welcome", title = "Welcome", fullWidth = true, alwaysShow = true,
			collapsible = false, extraBottom = 34, onPlace = w.PlaceWelcome }
	end

	if sess then
		table.sort(session, GB.SortRecords)
		sections[#sections + 1] = { key = "session", title = "Session Yield", items = session, fullWidth = true,
			alwaysShow = true, collapsible = false, titleColor = "|cffffd27a", countText = "  |cff6b7480" .. GB:SessionSummary() .. "|r",
			extraBottom = 26, onPlace = w.PlaceSessionBar }
	end

	local merchant = MerchantFrame and MerchantFrame:IsShown()
	table.sort(inbox, GB.SortRecords)
	sections[#sections + 1] = { key = "inbox", title = "Loot Inbox", items = inbox, fullWidth = true,
		alwaysShow = merchant, collapsible = false, titleColor = "|c" .. GB.ACCENT_HEX,
		countText = #inbox == 0 and "  |cff6b7480all caught up|r" or nil,
		extraBottom = 26, onPlace = w.PlaceInboxBar }
	w.inboxShown = (#inbox > 0 or merchant)

	local normalFree = FreeRecord(w, "normal", GB.free.normal)
	local reagentFree = FreeRecord(w, "reagent", GB.free.reagent)

	if GB.db.settings.view == "unified" then
		table.sort(rest, GB.BagOrder)
		if normalFree then rest[#rest + 1] = normalFree end
		if reagentFree then rest[#rest + 1] = reagentFree end
		sections[#sections + 1] = { key = "all", title = "Bags", items = rest, fullWidth = true, collapsible = false }
	else
		local byCat = {}
		for _, r in ipairs(rest) do
			local k = GB:Classify(r)
			byCat[k] = byCat[k] or {}
			tinsert(byCat[k], r)
		end
		for _, cat in ipairs(GB.CATEGORIES) do
			local list = byCat[cat.key]
			if list then
				table.sort(list, GB.SortRecords)
				sections[#sections + 1] = { key = cat.key, title = cat.title, items = list,
					titleColor = cat.key == "crafting" and "|cffffd27a" or nil }
			end
		end
		local free = {}
		if normalFree then free[#free + 1] = normalFree end
		if reagentFree then free[#free + 1] = reagentFree end
		sections[#sections + 1] = { key = "free", title = "Space", items = free, minCells = 2, collapsible = false }
	end
	return sections
end

local function CreateBagWindow()
	local w = CreateWindow("PathwayBagsFrame", function() return GB.TITLE end)
	bags = w
	GB.bagWindow = w
	w.BuildSections = BuildBagSections
	RestorePos(w, { "BOTTOMRIGHT", "BOTTOMRIGHT", -70, 110 })
	-- until you move it yourself, the bags open beside the guide and the meter, not on top of them
	w:HookScript("OnShow", function(self)
		if GB.db.pos[self:GetName()] or not P.PlaceBeside then return end
		P:PlaceBeside(self, { "PathwayGuide", "PathwayMeter" }, { "BOTTOMRIGHT", "BOTTOMRIGHT", -70, 110 })
	end)

	-- header buttons: bank, view toggle, yield, settings
	local menu = GB:IconButton(w.header, "Interface\\Buttons\\UI-OptionsButton", "Settings\n|cff6b7480Right-click for quick options|r")
	menu:SetPoint("RIGHT", w.close, "LEFT", -6, 0)
	menu:SetScript("OnClick", function(self, button)
		if button == "RightButton" then GB:OptionsMenu(self) else GB:OpenSettings() end
	end)
	local yield = GB:FlatButton(w.header, "Yield")
	yield:SetPoint("RIGHT", menu, "LEFT", -4, 0)
	yield.tip = "Session Yield — track exactly what you farm, and how fast."
	yield:SetScript("OnClick", function() GB:ToggleSession() end)
	w.yieldButton = yield
	local view = GB:FlatButton(w.header, "Grid")
	view:SetPoint("RIGHT", yield, "LEFT", -4, 0)
	view:SetScript("OnClick", function()
		local NEXT = { categorized = "unified", unified = "bags", bags = "categorized" }
		GB:SetView(NEXT[GB.db.settings.view] or "categorized")
	end)
	w.viewButton = view
	local bankBtn = GB:FlatButton(w.header, "Bank")
	bankBtn:SetPoint("RIGHT", view, "LEFT", -4, 0)
	bankBtn.tip = "Bank Anywhere: see your bank and Warband bank from anywhere, and queue deposits and withdrawals for your next visit."
	bankBtn:SetScript("OnClick", function() GB:ToggleBankAnywhere() end)

	-- inbox action bar
	local bar = CreateFrame("Frame", nil, w.content)
	bar:SetHeight(20)
	local sweep = GB:FlatButton(bar, "Sort to Bags", true)
	sweep:SetPoint("LEFT")
	sweep.tip = "Send everything new to its category. Locked items (Alt+Right-Click) stay put."
	sweep:SetScript("OnClick", function()
		local n = GB:Sweep()
		if n > 0 then GB:Toast(("Sorted %d item%s into your bags"):format(n, n == 1 and "" or "s")) end
	end)
	local sendBank = GB:FlatButton(bar, "Bank it")
	sendBank.tip = "Send new trade goods and reagents to your bank: right now if you're at the bank, otherwise on your next visit."
	sendBank:SetScript("OnClick", function() GB:BankInbox() end)
	local sell = GB:FlatButton(bar, "Sell Junk")
	sell:SetPoint("LEFT", sweep, "RIGHT", 6, 0)
	sell:SetScript("OnClick", function() GB:SellJunk() end)
	local hint = bar:CreateFontString(nil, "OVERLAY")
	hint:SetFontObject(F_HEAD)
	hint:SetPoint("RIGHT")
	hint:SetText("Alt+Right-Click: keep   ·   Alt+Click: Wowhead link")
	bar.sweep, bar.sell, bar.hint = sweep, sell, hint
	w.inboxBar = bar

	function w.PlaceInboxBar(win, x, y, width)
		bar:ClearAllPoints()
		bar:SetPoint("TOPLEFT", win.content, "TOPLEFT", x, -y)
		bar:SetWidth(width)
		local merchant = MerchantFrame and MerchantFrame:IsShown()
		sweep:SetShown(GB:InboxCount() > 0)
		local bankable = GB:InboxBankable()
		sendBank:ClearAllPoints()
		sendBank:SetPoint("LEFT", sweep, "RIGHT", 6, 0)
		sendBank:SetShown(sweep:IsShown() and bankable > 0)
		if bankable > 0 then sendBank:SetLabel((GB.bankOpen and "Bank it" or "Bank next visit") .. "  " .. bankable) end
		local junkN, value = GB:JunkSummary()
		if merchant and junkN > 0 then
			sell:SetLabel(("Sell Junk  %d  ·  %s"):format(junkN, GetMoneyString(value, true)))
			sell:ClearAllPoints()
			if sendBank:IsShown() then sell:SetPoint("LEFT", sendBank, "RIGHT", 6, 0)
			elseif sweep:IsShown() then sell:SetPoint("LEFT", sweep, "RIGHT", 6, 0) else sell:SetPoint("LEFT") end
			sell:Show()
		else
			sell:Hide()
		end
		hint:SetShown(sweep:IsShown() and width > (sendBank:IsShown() and 520 or 360))
		bar.placed = true
		bar:Show()
	end

	-- bags view: sort into the labels
	local lbar = CreateFrame("Frame", nil, w.content)
	lbar:SetHeight(20)
	local lsort = GB:FlatButton(lbar, "Clean up to labels", true)
	lsort:SetPoint("LEFT")
	lsort.tip = "Moves each item into the bag labeled for it: equipment to Equipment, potions and food to Consumables, and so on. Items with no labeled bag go to your unlabeled bags."
	lsort:SetScript("OnClick", function() GB:SortToLabels() end)
	local lhint = lbar:CreateFontString(nil, "OVERLAY")
	lhint:SetFontObject(F_HEAD)
	lhint:SetPoint("LEFT", lsort, "RIGHT", 10, 0)
	lbar.hint = lhint
	w.labelBar = lbar
	function w.PlaceLabelBar(win, x, y, width)
		lbar:ClearAllPoints(); lbar:SetPoint("TOPLEFT", win.content, "TOPLEFT", x, -y); lbar:SetWidth(width)
		local n = 0
		for _ in pairs(GB.cdb.bagLabels) do n = n + 1 end
		lsort:SetEnabled(n > 0)
		lsort:SetAlpha(n > 0 and 1 or 0.5)
		lhint:SetText(GB.labelSorting and "|cffffd27aSorting...|r" or (n == 0 and "|cff6b7480Label a bag first: Equipment, Consumables, Trade Goods...|r" or ""))
		lbar.placed = true
		lbar:Show()
	end

	-- session bar
	local sbar = CreateFrame("Frame", nil, w.content)
	sbar:SetHeight(20)
	local stop = GB:FlatButton(sbar, "Stop & Summary")
	stop:SetPoint("LEFT")
	stop:SetScript("OnClick", function() GB:ToggleSession() end)
	local stats = sbar:CreateFontString(nil, "OVERLAY")
	stats:SetFontObject(F_HEAD)
	stats:SetPoint("LEFT", stop, "RIGHT", 10, 0)
	sbar.stats = stats
	w.sessionBar = sbar
	function w.PlaceSessionBar(win, x, y, width)
		sbar:ClearAllPoints(); sbar:SetPoint("TOPLEFT", win.content, "TOPLEFT", x, -y); sbar:SetWidth(width)
		stats:SetText(GB:SessionStatsLine())
		sbar.placed = true
		sbar:Show()
	end

	-- welcome banner
	local wel = CreateFrame("Frame", nil, w.content, "BackdropTemplate")
	Flat(wel, ACCENT_SOFT, ACCENT_EDGE)
	wel:SetHeight(30)
	wel.text = wel:CreateFontString(nil, "OVERLAY")
	wel.text:SetFontObject(F_BTN)
	wel.text:SetPoint("LEFT", 10, 0)
	wel.text:SetText("New loot lands in your |c" .. GB.ACCENT_HEX .. "Loot Inbox|r. Prefer one big grid?")
	local keep = GB:FlatButton(wel, "Keep categories", true)
	keep:SetPoint("RIGHT", -5, 0)
	keep:SetScript("OnClick", function() GB.db.settings.welcomed = true; GB:LayoutAll() end)
	local uni = GB:FlatButton(wel, "Use one grid")
	uni:SetPoint("RIGHT", keep, "LEFT", -5, 0)
	uni:SetScript("OnClick", function() GB.db.settings.welcomed = true; GB:SetView("unified") end)
	w.welcome = wel
	function w.PlaceWelcome(win, x, y, width)
		wel:ClearAllPoints(); wel:SetPoint("TOPLEFT", win.content, "TOPLEFT", x, -y); wel:SetWidth(width)
		wel.text:SetShown(width > 420)
		wel.placed = true
		wel:Show()
	end

	-- footer: money + tracked currencies + combat note
	local money = CreateFrame("Button", nil, w.footer)
	money:SetHeight(18)
	money:SetPoint("LEFT")
	money.text = money:CreateFontString(nil, "OVERLAY")
	money.text:SetFontObject(F_BTN)
	money.text:SetPoint("LEFT")
	money:SetScript("OnEnter", function(self) GB:MoneyTooltip(self) end)
	money:SetScript("OnLeave", GameTooltip_Hide)
	w.money = money

	w.currencies = {}
	for i = 1, 3 do
		local c = CreateFrame("Button", nil, w.footer)
		c:SetHeight(18)
		c.icon = c:CreateTexture(nil, "ARTWORK"); c.icon:SetSize(13, 13); c.icon:SetPoint("RIGHT")
		c.icon:SetTexCoord(0.08, 0.92, 0.08, 0.92)
		c.text = c:CreateFontString(nil, "OVERLAY"); c.text:SetFontObject(F_BTN); c.text:SetPoint("RIGHT", c.icon, "LEFT", -3, 0)
		c:SetScript("OnEnter", function(self)
			if not self.id then return end
			GameTooltip:SetOwner(self, "ANCHOR_TOP")
			GameTooltip:SetCurrencyByID(self.id)
			GameTooltip:Show()
		end)
		c:SetScript("OnLeave", GameTooltip_Hide)
		w.currencies[i] = c
	end

	local note = w.footer:CreateFontString(nil, "OVERLAY")
	note:SetFontObject(F_HEAD)
	note:SetPoint("CENTER", 0, 0)
	note:SetText("|cffffd27aIn combat — new items will sort in after the fight|r")
	note:Hide()
	w.combatNote = note
	function w:OnCombatQueued() note:Show() end

	function w:AfterLayout()
		note:Hide()
		if not self.inboxShown or GB.db.settings.view == "bags" then bar:Hide() end
		if GB.db.settings.view ~= "bags" then lbar:Hide() end
		if not (GB.session and GB.session.active) then sbar:Hide() end
		if GB.db.settings.welcomed then wel:Hide() end
		local v = GB.db.settings.view
		local NAMES = { categorized = "Categories", unified = "Grid", bags = "Bags" }
		self.viewButton:SetLabel(NAMES[v] or "Categories")
		self.viewButton.tip = "Showing: |cffffffff" .. (NAMES[v] or "Categories") .. "|r\nClick for the next view: Categories, Grid, Bags.\n|cff6b7480Bags shows each bag as it is, and lets you label them.|r"
		GB:UpdateFooter()
	end

	w:HookScript("OnHide", function()
		PlaySound(SOUNDKIT.IG_BACKPACK_CLOSE)
		if not GB.syncing and GB.db.settings.takeOverBags ~= false then GB.syncing = true; CloseAllBags(); GB.syncing = false end
	end)
	return w
end

function GB:UpdateFooter()
	local w = bags
	if not w or not w:IsShown() then return end
	w.money.text:SetText(GetMoneyString(GetMoney(), true))
	w.money:SetWidth(w.money.text:GetStringWidth() + 4)
	local prev
	for i, c in ipairs(w.currencies) do
		local info = GB.BackpackCurrency(i)
		if info then
			c.id = info.currencyTypesID
			c.icon:SetTexture(info.iconFileID)
			c.text:SetText(BreakUpLargeNumbers(info.quantity))
			c:SetWidth(c.text:GetStringWidth() + 18)
			c:ClearAllPoints()
			if prev then c:SetPoint("RIGHT", prev, "LEFT", -10, 0) else c:SetPoint("RIGHT") end
			c:Show()
			prev = c
		else
			c.id = nil
			c:Hide()
		end
	end
end

---------------------------------------------------------------------------
-- Taking over from Blizzard's bags & bank
---------------------------------------------------------------------------
local hidden = CreateFrame("Frame")
hidden:Hide()
GB.hiddenParent = hidden
GB.CreateWindow, GB.GetButton, GB.ClearTags, GB.windows = CreateWindow, GetButton, ClearTags, windows

-- Read-only item buttons for saved bank copies (Bank Anywhere): same look,
-- tooltips from the item link, Alt+Click for Wowhead, no container actions.
local function noop() end
function GB.CreateDisplayButton(parent)
	local b = CreateFrame("ItemButton", nil, parent)
	b.UpdateQuestItem, b.UpdateCooldown, b.SetReadable, b.SetHasItem = noop, noop, noop, noop
	Skin(b)
	b:RegisterForClicks("LeftButtonUp", "RightButtonUp")
	b:SetScript("OnEnter", function(self)
		local r = self.gbRecord
		if not r or not r.link then return end
		GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
		GameTooltip:SetHyperlink(r.link)
		GameTooltip:AddLine(" ")
		GameTooltip:AddLine("|cff6b7480Saved copy  ·  Click to " .. (GB.cdb.withdraw[r.itemID] and "cancel the withdraw" or "withdraw it on your next visit") .. "|r")
		GameTooltip:Show()
	end)
	b:SetScript("OnLeave", GameTooltip_Hide)
	b:SetScript("OnClick", function(self, button)
		local r = self.gbRecord
		if not r then return end
		if IsAltKeyDown() then ItemClickHook(self, button); return end
		if IsModifiedClick() and r.link then HandleModifiedItemClick(r.link); return end
		GB:ToggleWithdraw(r.itemID)
	end)
	return b
end
GB.PAD, GB.GAP, GB.TOP_H, GB.FOOT_H, GB.HEAD_H = PAD, GAP, TOP_H, FOOT_H, HEAD_H
GB.colors = { BG = BG, EDGE = EDGE, PANEL = PANEL, SLOT_BG = SLOT_BG,
	ACCENT_BG = ACCENT_BG, ACCENT_EDGE = ACCENT_EDGE, ACCENT_SOFT = ACCENT_SOFT }

local function BlizzardBagsOpen()
	if ContainerFrameCombinedBags and ContainerFrameCombinedBags:IsShown() then return true end
	for i = 1, (NUM_CONTAINER_FRAMES or 13) do
		local f = _G["ContainerFrame" .. i]
		if f and f:IsShown() then return true end
	end
	return false
end

function GB:ShowBags()
	if not bags then return end
	if not bags:IsShown() then bags:Show() end
end

function GB:HideBags() if bags and bags:IsShown() then bags:Hide() end end

function GB:ToggleBags()
	if bags and bags:IsShown() then bags:Hide() else
		if self.db.settings.takeOverBags ~= false then OpenAllBags() end
		self:ShowBags()
	end
end

local function Sync()
	if GB.syncing then return end
	GB.syncing = true
	if BlizzardBagsOpen() then GB:ShowBags() else GB:HideBags() end
	GB.syncing = false
end

function GB:LayoutAll() for _, w in ipairs(windows) do self:Layout(w) end end

function GB:SetView(view)
	self.db.settings.view = view
	self:LayoutAll()
end

GB:Listen("READY", function()
	CreateBagWindow()

	-- another bag addon can keep Blizzard's bag keys; GoodBags still opens with /gb
	if GB.db.settings.takeOverBags ~= false then
		for i = 1, (NUM_CONTAINER_FRAMES or 13) do
			local f = _G["ContainerFrame" .. i]
			if f then f:SetParent(hidden) end
		end
		if ContainerFrameCombinedBags then ContainerFrameCombinedBags:SetParent(hidden) end
		for _, fn in ipairs({ "ToggleAllBags", "OpenAllBags", "CloseAllBags", "ToggleBackpack", "OpenBackpack",
			"CloseBackpack", "ToggleBag", "OpenBag", "CloseBag" }) do
			if _G[fn] then hooksecurefunc(fn, Sync) end
		end
	end

	GB:Send("UI_READY")
	GB:ApplyTheme()
	GB:LayoutAll()
end)

GB:Listen("LAYOUT", function()
	if bags then GB:Layout(bags) end
end)

GB:On("PLAYER_REGEN_ENABLED", function()
	if GB.combatQueued then
		GB.combatQueued = false
		GB:LayoutAll()
	end
end)
GB:On("PLAYER_MONEY", function() GB:UpdateFooter() end)
GB:On("CURRENCY_DISPLAY_UPDATE", function() GB:Debounce("cur", 0.2, function() GB:UpdateFooter() end) end)
GB:On("BAG_UPDATE_COOLDOWN", function()
	for _, w in ipairs(windows) do
		if w:IsShown() then for b in pairs(w.shown) do if b.gbRecord and not b.gbRecord.free then Cooldown(b) end end end
	end
end)
GB:On("ITEM_LOCK_CHANGED", function(_, bag, slot)
	if not bag or not slot then return end
	for _, w in ipairs(windows) do
		local t = w.buttons[bag]
		local b = t and t[slot]
		if b and b:IsShown() then
			local info = C_Container.GetContainerItemInfo(bag, slot)
			SetItemButtonDesaturated(b, info and info.isLocked)
		end
	end
end)
local function MerchantRefresh() if bags and bags:IsShown() then GB:Layout(bags) end end
GB:On("MERCHANT_SHOW", function() C_Timer.After(0, MerchantRefresh) end)
GB:On("MERCHANT_CLOSED", function()
	if GB.db.settings.autoClear then GB:Sweep() else MerchantRefresh() end
end)
end part() end
-- ==================== Bags/Bank.lua
do local __addon, __ns = ... local function part()
-- Copyright (C) 2026 SoFinSicc. Part of Pathway (curseforge.com/wow/addons/pathway): free software under the GPLv3 or later, with additional terms that require keeping this credit. See LICENSE.md.
--[[ Lil's GoodBags — Bank workspace
     One compact window for the character bank and the Warband bank:
       · a tab rail down the left (your tabs, Warband tabs, + to buy more)
       · each tab sorted into categories, or its real slot grid
       · tab settings (name, icon, what auto-deposits there) built in
       · deposit / clean up / Warband gold right in the footer
     Bank Anywhere: the same window away from the bank shows the saved copy
     from your last visit (any character), and lets you queue withdrawals. ]]

local ADDON, P = __addon, __ns
local GB = P.Bags
local C_Item, C_Container, C_Bank = P.Item, P.Container, P.BankAPI

local ipairs, pairs, wipe, max, min, floor, ceil = ipairs, pairs, wipe, math.max, math.min, math.floor, math.ceil
local A = GB.ACCENT
local DIM = "|cff6b7480"

local CHAR = GB.CHAR
local ACCT = GB.ACCT
local KIND = { [CHAR or 0] = "character", [ACCT or 2] = "account" }

local RAIL_W, TOOL_H, BANK_COLS, MAX_ROWS, DROP_H = 74, 30, 14, 9, 30
local TAB_SIZE, TAB_GAP = 28, 4

local w            -- the window
local slotRecs = {}  -- [bag*1000+slot] = reusable empty-slot record

local function Flags() return Enum.BagSlotFlags or {} end
local function HasFlag(v, f) return f and bit.band(v or 0, f) ~= 0 end

---------------------------------------------------------------------------
-- Data helpers
---------------------------------------------------------------------------
local function Live() return w and w.live end

local function Snap(bt)
	if bt == ACCT then return GB.db.warband.snap end
	local c = GB.db.chars[w and w.viewKey or GB.charKey]
	return c and c.bankSnap
end

local saved = {}       -- [kind] = records rebuilt from the saved copy
local savedIndex = {}  -- [kind] = { [bag*1000+slot] = record }
local function SavedRecords(bt)
	local kind = KIND[bt]
	if not saved[kind] then
		saved[kind] = GB:SnapshotRecords(Snap(bt), kind)
		savedIndex[kind] = {}
		for _, r in ipairs(saved[kind]) do savedIndex[kind][r.bag * 1000 + r.slot] = r end
	end
	return saved[kind], savedIndex[kind]
end
function GB:InvalidateSaved() wipe(saved); wipe(savedIndex) end

local function Tabs(bt)
	if not bt then return {} end
	if Live() then
		return (C_Bank and C_Bank.FetchPurchasedBankTabData and C_Bank.FetchPurchasedBankTabData(bt)) or {}
	end
	local snap = Snap(bt)
	return snap and snap.tabs or {}
end

local function TabData(bt, id)
	for _, t in ipairs(Tabs(bt)) do if t.ID == id then return t end end
end

local function CanView(bt)
	if not bt then return false end
	if Live() then return not C_Bank.CanViewBank or C_Bank.CanViewBank(bt) end
	return true
end
local function Locked(bt) return Live() and bt and C_Bank.FetchBankLockedReason and C_Bank.FetchBankLockedReason(bt) ~= nil end

local function Records(bt)
	if Live() then return GB.bank.slots, GB.bank.index or {} end
	return SavedRecords(bt)
end

local function TabUsage(bag, bt)
	if Live() then
		local n = C_Container.GetContainerNumSlots(bag) or 0
		local free = C_Container.GetContainerNumFreeSlots(bag) or 0
		return n - free, n
	end
	local size = 0
	for _, t in ipairs(Tabs(bt or (bag >= 12 and ACCT or CHAR))) do if t.ID == bag then size = t.size or 98 end end
	local used = 0
	local recs = Records(bag >= 12 and ACCT or CHAR)
	for _, r in ipairs(recs) do if r.bag == bag then used = used + 1 end end
	return used, size
end

local function Ago(t)
	local d = time() - (t or 0)
	if d < 120 then return "just now" end
	if d < 3600 then return math.floor(d / 60) .. "m ago" end
	if d < 86400 then return math.floor(d / 3600) .. "h ago" end
	return math.floor(d / 86400) .. "d ago"
end

---------------------------------------------------------------------------
-- Sections for GB:Layout
---------------------------------------------------------------------------
local freeRec = { free = true }

local function Categorized(list, sections, prefix)
	local byCat = {}
	for _, r in ipairs(list) do
		local k = GB:Classify(r)
		byCat[k] = byCat[k] or {}
		byCat[k][#byCat[k] + 1] = r
	end
	for _, cat in ipairs(GB.CATEGORIES) do
		local l = byCat[cat.key]
		if l then
			table.sort(l, GB.SortRecords)
			sections[#sections + 1] = { key = prefix .. cat.key, title = cat.title, items = l }
		end
	end
end

local function BuildSections(win)
	win.dispN = 0
	local bt = win.bankType
	local sections = {}

	-- away from the bank: what will happen on the next visit
	if not Live() then
		local going = {}
		for _, r in ipairs(GB.slots) do if GB.cdb.toBank[r.itemID] then going[#going + 1] = r end end
		local taking = 0
		for _ in pairs(GB.cdb.withdraw) do taking = taking + 1 end
		if #going > 0 or taking > 0 then
			local note = taking > 0 and ("  " .. DIM .. "·  " .. taking .. " to withdraw (marked take)|r") or ""
			sections[1] = { key = "bank_next", title = "Next visit", titleColor = "|cffffd27a", items = going,
				fullWidth = true, alwaysShow = true, collapsible = false,
				countText = (#going > 0 and ("  " .. DIM .. #going .. " to bank|r") or "") .. note }
		end
	end

	if #Tabs(bt) == 0 then
		win.emptyBank = true
		return sections
	end
	win.emptyBank = false
	local recs, idx = Records(bt)

	if win.tabID ~= "all" then
		local bag = win.tabID
		local used, n = TabUsage(bag, bt)
		if GB.db.settings.bankView == "slots" then
			local items = {}
			for slot = 1, n do
				local key = bag * 1000 + slot
				local r = idx[key]
				if not r then
					r = slotRecs[key] or { bag = bag, slot = slot, empty = true }
					slotRecs[key] = r
					r.saved = not Live() or nil
				end
				items[#items + 1] = r
			end
			sections[#sections + 1] = { key = "bank_tab", items = items, fullWidth = true, collapsible = false, noHeader = true,
				title = "", countText = "" }
			return sections
		end
		-- sorted: this tab's items in categories, plus its free space
		local list = {}
		for _, r in ipairs(recs) do if r.bag == bag then list[#list + 1] = r end end
		Categorized(list, sections, "bank_")
		if n - used > 0 then
			local firstFree
			for slot = 1, n do if not idx[bag * 1000 + slot] then firstFree = slot; break end end
			freeRec.bag, freeRec.slot, freeRec.freeCount, freeRec.saved = bag, firstFree, n - used, not Live() or nil
			sections[#sections + 1] = { key = "bank_space", title = "Space", items = { freeRec }, minCells = 2, collapsible = false }
		end
		return sections
	end

	-- All tabs: everything in this bank, sorted into categories
	local kind, list = KIND[bt], {}
	for _, r in ipairs(recs) do if r.bankKind == kind then list[#list + 1] = r end end
	Categorized(list, sections, "bank_")
	if #list == 0 then
		sections[#sections + 1] = { key = "bank_none", title = "Nothing stored here yet", items = {}, alwaysShow = true, fullWidth = true, collapsible = false }
	end
	return sections
end

-- live bank items use real container buttons; saved copies use display buttons
local function AcquireButton(win, r)
	if r.saved then
		win.dispN = win.dispN + 1
		win.disp = win.disp or {}
		local b = win.disp[win.dispN]
		if not b then b = GB.CreateDisplayButton(win.content); win.disp[win.dispN] = b end
		return b
	end
	return GB.GetButton(win, r.bag, r.slot)
end

---------------------------------------------------------------------------
-- Tab rail
---------------------------------------------------------------------------
local function RailButton(parent)
	local b = CreateFrame("Button", nil, parent, "BackdropTemplate")
	b:SetSize(TAB_SIZE, TAB_SIZE)
	GB.Flat(b, GB.colors.PANEL)
	b.icon = b:CreateTexture(nil, "ARTWORK")
	b.icon:SetPoint("TOPLEFT", 2, -2); b.icon:SetPoint("BOTTOMRIGHT", -2, 2)
	b.icon:SetTexCoord(0.08, 0.92, 0.08, 0.92)
	b.bar = b:CreateTexture(nil, "OVERLAY")
	b.bar:SetPoint("TOPLEFT", -5, 0); b.bar:SetPoint("BOTTOMLEFT", -5, 0); b.bar:SetWidth(2)
	b.fill = b:CreateTexture(nil, "OVERLAY")
	b.fill:SetHeight(2)
	b.fill:SetPoint("BOTTOMLEFT", 2, 2)
	b.text = b:CreateFontString(nil, "OVERLAY")
	b.text:SetFontObject(GB.fonts.title)
	b.text:SetPoint("CENTER", 0, 1)
	b:SetScript("OnEnter", function(self)
		self:SetBackdropBorderColor(A[1], A[2], A[3], 1)
		if self.Tooltip then
			GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
			self:Tooltip(GameTooltip)
			GameTooltip:Show()
		end
	end)
	b:SetScript("OnLeave", function(self)
		if not self.selected then self:SetBackdropBorderColor(unpack(GB.colors.EDGE)) end
		GameTooltip:Hide()
	end)
	b:RegisterForClicks("LeftButtonUp", "RightButtonUp")
	return b
end

local function SetSelected(b, on)
	b.selected = on
	b.bar:SetColorTexture(A[1], A[2], A[3], 1)
	b.bar:SetShown(on)
	if on then b:SetBackdropBorderColor(A[1], A[2], A[3], 1) else b:SetBackdropBorderColor(unpack(GB.colors.EDGE)) end
	b.icon:SetDesaturated(false)
	b.icon:SetAlpha(on and 1 or 0.75)
end

local railPool, railLabels = {}, {}
local function RailLabel(i, text)
	local fs = railLabels[i]
	if not fs then
		fs = w.rail:CreateFontString(nil, "OVERLAY")
		fs:SetFontObject(GB.fonts.head)
		railLabels[i] = fs
	end
	fs:SetText(text)
	fs:Show()
	return fs
end

local function BuyTooltip(bt) return function(self, tt)
	local data = C_Bank.FetchNextPurchasableBankTabData and C_Bank.FetchNextPurchasableBankTabData(bt)
	tt:SetText(bt == ACCT and "Buy a Warband bank tab" or "Buy a bank tab", 1, 1, 1)
	if data then
		local c = data.canAfford and "|cffffffff" or "|cffff5555"
		tt:AddLine(c .. GetMoneyString(data.tabCost, true) .. "|r")
	end
end end

function GB:BankRail()
	if not w then return end
	for _, b in ipairs(railPool) do b:Hide(); b.Tooltip = nil end
	for _, fs in ipairs(railLabels) do fs:Hide() end
	-- two columns of tab buttons per bank, so the rail never outgrows the grid
	local used, y, li, gi = 0, -8, 0, 0
	local function Next()
		used = used + 1
		local b = railPool[used]
		if not b then b = RailButton(w.rail); railPool[used] = b end
		b.text:SetText(""); b.icon:Show(); b.fill:Hide()
		local col, row = gi % 2, floor(gi / 2)
		b:ClearAllPoints()
		b:SetPoint("TOPLEFT", w.rail, "TOPLEFT", 8 + col * (TAB_SIZE + TAB_GAP), y - row * (TAB_SIZE + TAB_GAP))
		gi = gi + 1
		b:Show()
		return b
	end

	for _, bt in ipairs({ CHAR, ACCT }) do
		if bt and CanView(bt) then
			li = li + 1
			local label = RailLabel(li, bt == ACCT and "WARBAND" or "BANK")
			label:ClearAllPoints(); label:SetPoint("TOPLEFT", w.rail, "TOPLEFT", 9, y)
			y = y - 15
			gi = 0

			-- "All tabs" for this bank
			local all = Next()
			all.icon:Hide()
			all.text:SetText("all")
			all.text:SetTextColor(0.8, 0.84, 0.88)
			SetSelected(all, w.bankType == bt and w.tabID == "all")
			all.Tooltip = function(_, tt) tt:SetText((bt == ACCT and "Warband bank" or "Bank") .. ": all tabs", 1, 1, 1); tt:AddLine("Everything sorted into categories.", 0.7, 0.7, 0.7, true) end
			all:SetScript("OnClick", function() GB:SelectBankTab(bt, "all") end)

			for _, tab in ipairs(Tabs(bt)) do
				local b = Next()
				b.icon:SetTexture(tab.icon ~= 0 and tab.icon or 134400)
				SetSelected(b, w.bankType == bt and w.tabID == tab.ID)
				local usedN, total = TabUsage(tab.ID, bt)
				local pct = total > 0 and usedN / total or 0
				b.fill:SetWidth(max(1, (TAB_SIZE - 4) * pct))
				if pct >= 0.95 then b.fill:SetColorTexture(1, 0.4, 0.4, 0.9) else b.fill:SetColorTexture(A[1], A[2], A[3], 0.8) end
				b.fill:Show()
				b.Tooltip = function(_, tt)
					local u, t = TabUsage(tab.ID, bt)
					tt:SetText(tab.name ~= "" and tab.name or "Tab", 1, 1, 1)
					tt:AddLine(("%d / %d slots used"):format(u, t), 0.7, 0.7, 0.7)
					if Live() and GB.TABS then tt:AddLine(DIM .. "Right-click for tab settings|r") end
				end
				b:SetScript("OnClick", function(_, button)
					GB:SelectBankTab(bt, tab.ID)
					if button == "RightButton" and Live() and GB.TABS then GB:OpenTabSettings(bt, tab.ID) end
				end)
			end

			if Live() and C_Bank.CanPurchaseBankTab and C_Bank.CanPurchaseBankTab(bt) then
				local plus = Next()
				plus.icon:Hide()
				plus.text:SetText("+")
				plus.text:SetTextColor(A[1], A[2], A[3])
				SetSelected(plus, false)
				plus.Tooltip = BuyTooltip(bt)
				plus:SetScript("OnClick", function() GB:BuyBankTab(bt) end)
			end
			y = y - ceil(gi / 2) * (TAB_SIZE + TAB_GAP) - 8
		end
	end
	w.railHeight = -y
end

---------------------------------------------------------------------------
-- Actions
---------------------------------------------------------------------------
-- Buying a tab is a protected action that only Blizzard's own bank window may
-- do, so we hand over to it for that one click.
function GB:BuyBankTab(bt)
	if not bt then return end
	self:ShowBlizzardBank()
	self:Toast("Click the |cff6ee7b7+|r tab in Blizzard's bank to buy it")
end

function GB:SelectBankTab(bt, tabID)
	if not w then return end
	if not CanView(bt) then bt = (bt == CHAR) and ACCT or CHAR end
	w.bankType = bt
	local tabs = Tabs(bt)
	if tabID == nil then tabID = w.lastTab and w.lastTab[bt] end
	if tabID ~= "all" and not TabData(bt, tabID) then tabID = tabs[1] and tabs[1].ID or "all" end
	w.tabID = tabID
	w.lastTab = w.lastTab or {}; w.lastTab[bt] = tabID
	if w.settings:IsShown() then w.settings:Hide() end
	GB:BankRail()
	GB:BankToolbar()
	GB:Layout(w, true)
	w.scroll:SetVerticalScroll(0)
end

function GB:BankDeposit()
	local bt = w.bankType
	if bt == ACCT and ItemUtil and ItemUtil.IteratePlayerInventory then
		local refundable = ItemUtil.IteratePlayerInventory(function(loc)
			return C_Bank.IsItemAllowedInBankType(ACCT, loc) and C_Item.CanBeRefunded(loc)
		end)
		if refundable then
			StaticPopup_Show("ACCOUNT_BANK_DEPOSIT_ALL_NO_REFUND_CONFIRM", nil, nil, { bankType = bt })
			return
		end
	end
	C_Bank.AutoDepositItemsIntoBank(bt)
end

function GB:BankCleanUp()
	C_Container.SortBank(w.bankType)
	self:Toast("Cleaning up your " .. (w.bankType == ACCT and "Warband bank" or "bank") .. "...")
end

---------------------------------------------------------------------------
-- Toolbar (above the grid) and footer
---------------------------------------------------------------------------
function GB:BankToolbar()
	local bt, tb, live = w.bankType, w.toolbar, Live()
	if w.tabID == "all" then
		tb.icon:SetTexture(bt == ACCT and 4643989 or 133633)   -- generic warband / bank chest art
		tb.name:SetText((bt == ACCT and "Warband bank" or "Bank") .. DIM .. "  ·  all tabs|r")
		tb.gear:Hide()
		local used, total = 0, 0
		for _, t in ipairs(Tabs(bt)) do local u, n = TabUsage(t.ID, bt); used, total = used + u, total + n end
		tb.usage:SetText(total > 0 and (DIM .. used .. " / " .. total .. "|r") or "")
	else
		local t = TabData(bt, w.tabID)
		tb.icon:SetTexture(t and t.icon ~= 0 and t.icon or 134400)
		tb.name:SetText(t and (t.name ~= "" and t.name or "Tab") or "")
		tb.gear:SetShown(t ~= nil and live and GB.TABS)
		local used, total = TabUsage(w.tabID, bt)
		tb.usage:SetText(DIM .. used .. " / " .. total .. "|r")
	end
	tb.view:SetShown(w.tabID ~= "all")
	tb.view:SetLabel(GB.db.settings.bankView == "slots" and "Sorted" or "Slots")
	tb.view.tip = GB.db.settings.bankView == "slots" and "Show this tab sorted into categories" or "Show this tab's real slots"
	-- whose bank (away from the bank you can look at any character's saved copy)
	local who = GB.db.chars[w.viewKey or GB.charKey]
	tb.who:SetShown(not live and bt ~= ACCT)
	if who then tb.who:SetLabel("|c" .. (C_ClassColor and C_ClassColor.GetClassColor(who.class or "") and C_ClassColor.GetClassColor(who.class):GenerateHexColor() or "ffffffff") .. (who.name or "?") .. "|r  v") end
	w.title:SetText(GB.TITLE .. DIM .. (live and "   bank|r" or "   bank anywhere|r"))

	-- footer
	local f = w.foot
	-- only what this client's bank can do
	f.deposit:SetShown(live and GB.CanDeposit)
	f.clean:SetShown(live and GB.CanSortBank and true or false)
	f.smart:SetShown(live and GB.TABS)
	w.drop:Refresh()
	if not live then
		f.reagents:Hide(); f.give:Hide(); f.take:Hide()
		local snap = Snap(bt)
		f.note:SetText(snap and (DIM .. "Saved copy  ·  updated " .. Ago(snap.t) .. "  ·  click items to withdraw next visit|r")
			or (DIM .. "Visit a banker once and Pathway will remember this bank.|r"))
		f.note:Show()
		local money = bt == ACCT and (GB.db.warband.money or 0) or 0
		f.money:SetShown(money > 0)
		f.money:ClearAllPoints(); f.money:SetPoint("RIGHT")
		if money > 0 then f.money:SetText(GetMoneyString(money, true)) end
		w.lockNote:Hide()
		return
	end
	f.note:Hide()
	f.money:ClearAllPoints(); f.money:SetPoint("RIGHT", f.give, "LEFT", -8, 0)
	f.clean:ClearAllPoints()
	if bt == ACCT then f.clean:SetPoint("LEFT", f.reagents.label, "RIGHT", 12, 0)
	elseif GB.CanDeposit then f.clean:SetPoint("LEFT", f.deposit, "RIGHT", 4, 0)
	else f.clean:SetPoint("LEFT") end
	f.deposit:SetLabel(bt == ACCT and "Deposit Warbound" or "Deposit Reagents")
	f.deposit.tip = bt == ACCT and "Move every Warbound item from your bags into the Warband bank."
		or "Move every reagent from your bags into your bank."
	f.reagents:SetShown(bt == ACCT)
	f.reagents:SetChecked(GetCVarBool and GetCVarBool("bankAutoDepositReagents"))
	local money = C_Bank.DoesBankTypeSupportMoneyTransfer and C_Bank.DoesBankTypeSupportMoneyTransfer(bt)
	f.money:SetShown(money); f.give:SetShown(money); f.take:SetShown(money)
	if money then
		f.money:SetText(GetMoneyString(C_Bank.FetchDepositedMoney(bt) or 0, true))
		f.give:SetEnabled(C_Bank.CanDepositMoney(bt)); f.take:SetEnabled(C_Bank.CanWithdrawMoney(bt))
	end
	local locked = Locked(bt)
	w.lockNote:SetShown(locked)
	f.deposit:SetEnabled(not locked); f.clean:SetEnabled(not locked); f.smart:SetEnabled(not locked)
end

---------------------------------------------------------------------------
-- Tab settings panel (name, icon, auto-deposit rules)
---------------------------------------------------------------------------
local DEPOSIT_OPTS = {
	{ "ClassEquipment", "Equipment" }, { "ClassConsumables", "Consumables" },
	{ "ClassProfessionGoods", "Profession goods" }, { "ClassReagents", "Reagents" }, { "ClassJunk", "Junk" },
}

local function Check(parent, label)
	local c = CreateFrame("Button", nil, parent, "BackdropTemplate")
	c:SetSize(16, 16)
	GB.Flat(c, GB.colors.PANEL)
	c.tick = c:CreateTexture(nil, "OVERLAY")
	c.tick:SetPoint("TOPLEFT", 3, -3); c.tick:SetPoint("BOTTOMRIGHT", -3, 3)

	c.label = c:CreateFontString(nil, "OVERLAY")
	c.label:SetFontObject(GB.fonts.button)
	c.label:SetPoint("LEFT", c, "RIGHT", 7, 0)
	c.label:SetText(label)
	function c:SetChecked(v)
		self.checked = v and true or false
		self.tick:SetColorTexture(A[1], A[2], A[3], 1)
		self.tick:SetShown(self.checked)
	end
	function c:GetChecked() return self.checked end
	c:SetScript("OnClick", function(self) self:SetChecked(not self.checked); if self.onToggle then self:onToggle() end end)
	c:SetChecked(false)
	return c
end

local function BuildSettings()
	local p = CreateFrame("Frame", nil, w, "BackdropTemplate")
	GB.Flat(p, GB.colors.BG, GB.colors.ACCENT_EDGE)
	p:SetFrameLevel(w:GetFrameLevel() + 40)
	p:EnableMouse(true)
	p:Hide()
	w.settings = p

	local title = p:CreateFontString(nil, "OVERLAY")
	title:SetFontObject(GB.fonts.title)
	title:SetPoint("TOPLEFT", 14, -12)
	title:SetText("Tab settings")

	local nameLabel = p:CreateFontString(nil, "OVERLAY")
	nameLabel:SetFontObject(GB.fonts.head)
	nameLabel:SetPoint("TOPLEFT", 14, -40)
	nameLabel:SetText("NAME")
	local eb = CreateFrame("EditBox", nil, p, "BackdropTemplate")
	GB.Flat(eb, GB.colors.PANEL)
	eb:SetPoint("TOPLEFT", 14, -56); eb:SetSize(220, 24)
	eb:SetFontObject(GB.fonts.button)
	eb:SetTextInsets(8, 8, 0, 0)
	eb:SetAutoFocus(false)
	eb:SetMaxLetters(16)
	eb:SetScript("OnEscapePressed", function(s) s:ClearFocus() end)
	eb:SetScript("OnEnterPressed", function(s) s:ClearFocus() end)
	p.name = eb

	local iconLabel = p:CreateFontString(nil, "OVERLAY")
	iconLabel:SetFontObject(GB.fonts.head)
	iconLabel:SetPoint("TOPLEFT", 14, -92)
	iconLabel:SetText("ICON  " .. DIM .. "(from what's in this tab)|r")
	p.icons = {}
	for i = 1, 24 do
		local b = CreateFrame("Button", nil, p, "BackdropTemplate")
		b:SetSize(28, 28)
		GB.Flat(b, GB.colors.PANEL)
		local col, row = (i - 1) % 12, floor((i - 1) / 12)
		b:SetPoint("TOPLEFT", 14 + col * 32, -108 - row * 32)
		b.tex = b:CreateTexture(nil, "ARTWORK")
		b.tex:SetPoint("TOPLEFT", 2, -2); b.tex:SetPoint("BOTTOMRIGHT", -2, 2)
		b.tex:SetTexCoord(0.08, 0.92, 0.08, 0.92)
		b:SetScript("OnClick", function(self)
			p.icon = self.value
			for _, o in ipairs(p.icons) do o:SetBackdropBorderColor(unpack(GB.colors.EDGE)) end
			self:SetBackdropBorderColor(A[1], A[2], A[3], 1)
		end)
		p.icons[i] = b
	end

	local depLabel = p:CreateFontString(nil, "OVERLAY")
	depLabel:SetFontObject(GB.fonts.head)
	depLabel:SetPoint("TOPLEFT", 14, -182)
	depLabel:SetText("AUTO-DEPOSIT HERE  " .. DIM .. "(Deposit button and Clean Up)|r")
	p.checks = {}
	for i, opt in ipairs(DEPOSIT_OPTS) do
		local c = Check(p, opt[2])
		local col, row = (i - 1) % 3, floor((i - 1) / 3)
		c:SetPoint("TOPLEFT", 16 + col * 140, -202 - row * 24)
		c.flag = Flags()[opt[1]]
		p.checks[i] = c
	end

	local expLabel = p:CreateFontString(nil, "OVERLAY")
	expLabel:SetFontObject(GB.fonts.head)
	expLabel:SetPoint("TOPLEFT", 14, -258)
	expLabel:SetText("EXPANSION")
	p.exp = {}
	local opts = { { 0, "Any" }, { Flags().ExpansionCurrent, "Current only" }, { Flags().ExpansionLegacy, "Legacy only" } }
	for i, o in ipairs(opts) do
		local c = Check(p, o[2])
		c:SetPoint("TOPLEFT", 16 + (i - 1) * 140, -276)
		c.flag = o[1]
		c.onToggle = function(self) for _, other in ipairs(p.exp) do other:SetChecked(other == self) end end
		p.exp[i] = c
	end

	p.noSort = Check(p, "Leave this tab alone when cleaning up")
	p.noSort:SetPoint("TOPLEFT", 16, -306)
	p.noSort.flag = Flags().DisableAutoSort

	local save = GB:FlatButton(p, "Save", true)
	save.minW = 80; save:SetLabel("Save")
	save:SetPoint("BOTTOMRIGHT", -12, 12)
	local cancel = GB:FlatButton(p, "Cancel")
	cancel:SetPoint("RIGHT", save, "LEFT", -6, 0)
	cancel:SetScript("OnClick", function() p:Hide() end)
	save:SetScript("OnClick", function()
		local flags = 0
		for _, c in ipairs(p.checks) do if c.flag and c:GetChecked() then flags = bit.bor(flags, c.flag) end end
		for _, c in ipairs(p.exp) do if c:GetChecked() and c.flag and c.flag ~= 0 then flags = bit.bor(flags, c.flag) end end
		if p.noSort.flag and p.noSort:GetChecked() then flags = bit.bor(flags, p.noSort.flag) end
		C_Bank.UpdateBankTabSettings(p.bankType, p.tabID, p.name:GetText() or "", p.icon or 134400, flags)
		p:Hide()
		GB:Toast("Tab saved")
	end)
	p:SetScript("OnHide", function() p.name:ClearFocus() end)
end

function GB:OpenTabSettings(bt, tabID)
	local t = TabData(bt, tabID)
	if not t then return end
	local p = w.settings
	p.bankType, p.tabID, p.icon = bt, tabID, t.icon
	p.name:SetText(t.name or "")

	-- icon choices: current icon, then one per distinct item in the tab
	local seen, list = {}, {}
	local function add(icon) if icon and icon ~= 0 and not seen[icon] then seen[icon] = true; list[#list + 1] = icon end end
	add(t.icon)
	for _, r in ipairs(GB.bank.slots) do if r.bag == tabID then add(r.icon) end end
	for _, icon in ipairs({ 134400, 133633, 133639, 136243, 133784, 132281, 134939, 133971 }) do add(icon) end
	for i, b in ipairs(p.icons) do
		local icon = list[i]
		b.value = icon
		b.tex:SetTexture(icon)
		b:SetShown(icon ~= nil)
		b:SetBackdropBorderColor(unpack(icon == t.icon and { A[1], A[2], A[3], 1 } or GB.colors.EDGE))
	end

	local f = t.depositFlags or 0
	for _, c in ipairs(p.checks) do c:SetChecked(HasFlag(f, c.flag)) end
	local expSet = false
	for i, c in ipairs(p.exp) do
		local on = i > 1 and HasFlag(f, c.flag)
		c:SetChecked(on); expSet = expSet or on
	end
	if not expSet then p.exp[1]:SetChecked(true) end
	p.noSort:SetChecked(HasFlag(f, p.noSort.flag))

	p:ClearAllPoints()
	p:SetPoint("TOPLEFT", w.content:GetParent(), "TOPLEFT", 0, 0)
	p:SetPoint("BOTTOMRIGHT", w.content:GetParent(), "BOTTOMRIGHT", 0, 0)
	p:Show()
end

---------------------------------------------------------------------------
-- Drop zone: drag anything from your bags onto the strip to bank it
---------------------------------------------------------------------------
function GB:DropToBank()
	local kind, id = GetCursorInfo()
	if kind ~= "item" then return end
	local loc = C_Cursor and C_Cursor.GetCursorItem()
	local bag, slot
	if loc and loc.GetBagAndSlot then bag, slot = loc:GetBagAndSlot() end
	if not Live() then
		ClearCursor()
		self.cdb.toBank[id] = true
		self.cdb.withdraw[id] = nil
		self:Toast("Will be banked on your next visit")
		self:RequestLayout()
		return
	end
	if not bag or bag > 5 or bag < 0 then return end     -- only from your bags
	local r = self.index[bag * 1000 + slot]
	if not r then return end
	local db, ds = self.BankTargetFor(r)
	if not db then self:Toast("|cffff7a7aNo room in the bank|r"); return end
	C_Container.PickupContainerItem(db, ds)
	if CursorHasItem() then ClearCursor() end
end

---------------------------------------------------------------------------
-- GoodBags Clean: give every tab a job, a name and a matching icon, then let
-- Blizzard's Clean Up move everything into place.
---------------------------------------------------------------------------
local ROLES = {
	{ key = "gear",  name = "Gear",        short = "Gear",   flag = "ClassEquipment" },
	{ key = "cons",  name = "Consumables", short = "Consumables", flag = "ClassConsumables" },
	{ key = "trade", name = "Trade Goods", short = "Materials",   flag = { "ClassProfessionGoods", "ClassReagents" } },
	{ key = "misc",  name = "Collections", short = "Misc" },
	{ key = "junk",  name = "Junk",        short = "Junk",   flag = "ClassJunk" },
}
local ROLE_DESC = { gear = "equipment", cons = "consumables", trade = "reagents & profession goods", misc = "everything else", junk = "junk" }

local function RoleOf(r)
	if r.quality == 0 then return "junk" end
	if (r.classID == 2 or r.classID == 4) and r.equipLoc and r.equipLoc ~= "" then return "gear" end
	if r.classID == 0 then return "cons" end
	if r.classID == 7 or r.classID == 5 or r.classID == 3 or r.classID == 8 or r.classID == 19 then return "trade" end
	return "misc"
end

local function FlagsFor(keys)
	local F, v = Flags(), 0
	for _, role in ipairs(ROLES) do
		if keys[role.key] and role.flag then
			for _, name in ipairs(type(role.flag) == "table" and role.flag or { role.flag }) do
				if F[name] then v = bit.bor(v, F[name]) end
			end
		end
	end
	return v
end

function GB:PlanSmartClean(bt)
	local kind = KIND[bt]
	local tabs = {}
	for _, t in ipairs(Tabs(bt)) do
		if not HasFlag(t.depositFlags, Flags().DisableAutoSort) then tabs[#tabs + 1] = t end
	end
	if #tabs == 0 then return nil, "Every tab is set to be left alone." end
	local size = (C_Container.GetContainerNumSlots(tabs[1].ID) or 98)

	-- what's in this bank, by role, plus the icons each role uses most
	local stacks, icons = {}, {}
	for _, r in ipairs(GB.bank.slots) do
		if r.bankKind == kind then
			local k = RoleOf(r)
			stacks[k] = (stacks[k] or 0) + 1
			icons[k] = icons[k] or {}
			if r.icon then icons[k][r.icon] = (icons[k][r.icon] or 0) + 1 end
		end
	end

	local groups = {}
	for _, role in ipairs(ROLES) do
		if (stacks[role.key] or 0) > 0 then
			groups[#groups + 1] = { keys = { [role.key] = true }, names = { role.name }, shorts = { role.short },
				stacks = stacks[role.key], order = #groups + 1 }
		end
	end
	if #groups == 0 then return nil, "This bank is empty." end
	local function need(g) return math.max(1, ceil(g.stacks / (size * 0.9))) end
	local function total() local n = 0; for _, g in ipairs(groups) do n = n + need(g) end; return n end

	-- more jobs than tabs: share tabs between the smallest groups
	while total() > #tabs and #groups > 1 do
		table.sort(groups, function(a, b) return a.stacks < b.stacks end)
		local a, b = table.remove(groups, 1), table.remove(groups, 1)
		for k in pairs(b.keys) do a.keys[k] = true end
		for _, n in ipairs(b.names) do a.names[#a.names + 1] = n end
		for _, n in ipairs(b.shorts) do a.shorts[#a.shorts + 1] = n end
		a.stacks, a.order = a.stacks + b.stacks, min(a.order, b.order)
		groups[#groups + 1] = a
	end
	table.sort(groups, function(a, b) return a.order < b.order end)

	-- spare tabs go to whichever group is fullest
	for _, g in ipairs(groups) do g.tabs = need(g) end
	local used = 0
	for _, g in ipairs(groups) do used = used + g.tabs end
	while used < #tabs do
		local best
		for _, g in ipairs(groups) do if not best or g.stacks / g.tabs > best.stacks / best.tabs then best = g end end
		best.tabs = best.tabs + 1; used = used + 1
	end
	while used > #tabs do groups[#groups].tabs = groups[#groups].tabs - 1; used = used - 1 end

	local plan, ti = {}, 1
	for _, g in ipairs(groups) do
		-- icons ranked by how many stacks use them
		local ranked = {}
		for k in pairs(g.keys) do for icon, n in pairs(icons[k] or {}) do ranked[#ranked + 1] = { icon, n } end end
		table.sort(ranked, function(a, b) return a[2] > b[2] end)
		-- one job keeps its name; two share a short name; more is just "Mixed"
		local base
		if #g.names == 1 then base = g.names[1]
		elseif #g.names == 2 then
			base = g.shorts[1] .. " & " .. g.shorts[2]
			if #base > 16 then base = g.shorts[1] .. "+" .. g.shorts[2] end
			if #base > 16 then base = g.shorts[1]:sub(1, 7) .. "+" .. g.shorts[2]:sub(1, 8) end
		else base = "Mixed" end
		local desc = {}
		for _, role in ipairs(ROLES) do if g.keys[role.key] then desc[#desc + 1] = ROLE_DESC[role.key] end end
		for i = 1, g.tabs do
			local t = tabs[ti]
			if not t then break end
			local name = g.tabs > 1 and (base:sub(1, 14) .. " " .. i) or base
			plan[#plan + 1] = { tab = t, name = name, icon = (ranked[i] or ranked[1] or { t.icon })[1] or t.icon,
				flags = FlagsFor(g.keys), what = table.concat(desc, ", "), stacks = ceil(g.stacks / g.tabs) }
			ti = ti + 1
		end
	end
	return plan
end

local function ShowPlan()
	local bt = w.bankType
	local plan, why = GB:PlanSmartClean(bt)
	if not plan then GB:Toast(why); return end
	local p = w.plan
	p.bankType, p.data = bt, plan
	local c = "|c" .. GB.ACCENT_HEX
	p.desc:SetText("Here's the plan for this bank. Pathway will:\n" ..
		c .. "1|r  rename each tab and give it an icon from what it holds\n" ..
		c .. "2|r  set what each tab collects\n" ..
		c .. "3|r  run Clean Up so everything moves into its tab\n" ..
		DIM .. "Tabs set to \"leave alone\" are skipped. You can change any tab later in Tab settings.|r")
	for _, row in ipairs(p.rows) do row:Hide() end
	for i, e in ipairs(plan) do
		local row = p.rows[i]
		if not row then
			row = CreateFrame("Frame", nil, p)
			row:SetSize(500, 26)
			row.old = row:CreateTexture(nil, "ARTWORK"); row.old:SetSize(22, 22); row.old:SetPoint("LEFT", 0, 0)
			row.old:SetTexCoord(0.08, 0.92, 0.08, 0.92); row.old:SetDesaturated(true); row.old:SetAlpha(0.6)
			row.arrow = row:CreateFontString(nil, "OVERLAY"); row.arrow:SetFontObject(GB.fonts.head); row.arrow:SetPoint("LEFT", 28, 0); row.arrow:SetText(">")
			row.new = row:CreateTexture(nil, "ARTWORK"); row.new:SetSize(22, 22); row.new:SetPoint("LEFT", 42, 0)
			row.new:SetTexCoord(0.08, 0.92, 0.08, 0.92)
			row.name = row:CreateFontString(nil, "OVERLAY"); row.name:SetFontObject(GB.fonts.button); row.name:SetPoint("LEFT", 72, 0)
			row.what = row:CreateFontString(nil, "OVERLAY"); row.what:SetFontObject(GB.fonts.head); row.what:SetPoint("LEFT", 200, 0)
			p.rows[i] = row
		end
		row:ClearAllPoints()
		row:SetPoint("TOPLEFT", 16, -112 - (i - 1) * 24)
		row.old:SetTexture(e.tab.icon ~= 0 and e.tab.icon or 134400)
		row.new:SetTexture(e.icon)
		row.name:SetText(e.name)
		row.what:SetText("collects " .. e.what .. DIM .. "   ~" .. e.stacks .. " stacks|r")
		row:Show()
	end
	p:ClearAllPoints()
	p:SetPoint("TOPLEFT", w.scroll, "TOPLEFT", 0, 0)
	p:SetPoint("BOTTOMRIGHT", w.drop, "BOTTOMRIGHT", 0, 0)
	p:Show()
end

local function ApplyPlan()
	local p = w.plan
	if not (p.data and GB.bankOpen) then p:Hide(); return end
	for _, e in ipairs(p.data) do
		C_Bank.UpdateBankTabSettings(p.bankType, e.tab.ID, e.name, e.icon, e.flags)
	end
	local bt = p.bankType
	p:Hide()
	GB:Toast("Organizing your " .. (bt == ACCT and "Warband bank" or "bank") .. "...")
	C_Timer.After(0.8, function() if GB.bankOpen then C_Container.SortBank(bt) end end)
end

local function BuildPlanPanel()
	local p = CreateFrame("Frame", nil, w, "BackdropTemplate")
	GB.Flat(p, GB.colors.BG, GB.colors.ACCENT_EDGE)
	p:SetFrameLevel(w:GetFrameLevel() + 40)
	p:EnableMouse(true)
	p:Hide()
	p.rows = {}
	local t = p:CreateFontString(nil, "OVERLAY"); t:SetFontObject(GB.fonts.title); t:SetPoint("TOPLEFT", 16, -12)
	t:SetText("Smart Clean")
	local d = p:CreateFontString(nil, "OVERLAY"); d:SetFontObject(GB.fonts.button)
	d:SetPoint("TOPLEFT", 16, -36); d:SetPoint("RIGHT", -16, 0); d:SetJustifyH("LEFT"); d:SetSpacing(3)
	p.desc = d
	local go = GB:FlatButton(p, "Organize my bank", true)
	go:SetPoint("BOTTOMRIGHT", -12, 12)
	go:SetScript("OnClick", ApplyPlan)
	local cancel = GB:FlatButton(p, "Not now")
	cancel:SetPoint("RIGHT", go, "LEFT", -6, 0)
	cancel:SetScript("OnClick", function() p:Hide() end)
	w.plan = p
end

---------------------------------------------------------------------------
-- The window
---------------------------------------------------------------------------
local function CreateBank()
	w = GB.CreateWindow("PathwayBagsBankFrame", function() return GB.TITLE .. DIM .. ((w and w.live) and "   bank|r" or "   bank anywhere|r") end)
	GB.bankWindow = w
	w.isBank = true
	w.cols = BANK_COLS
	w.BuildSections = BuildSections
	w.AcquireButton = AcquireButton
	local pos = GB.db.pos[w:GetName()] or { "TOPLEFT", "TOPLEFT", 60, -110 }
	w:ClearAllPoints(); w:SetPoint(pos[1], UIParent, pos[2], pos[3], pos[4])

	-- tab rail
	local rail = CreateFrame("Frame", nil, w, "BackdropTemplate")
	GB.Flat(rail, GB.colors.PANEL, { 0, 0, 0, 0 })
	rail:SetPoint("TOPLEFT", 4, -(GB.HEAD_H - 2))
	rail:SetPoint("BOTTOMLEFT", 4, 4)
	rail:SetWidth(RAIL_W)
	w.rail = rail

	-- toolbar
	local tb = CreateFrame("Frame", nil, w)
	tb:SetPoint("TOPLEFT", RAIL_W + GB.PAD, -(GB.HEAD_H - 2))
	tb:SetPoint("TOPRIGHT", -GB.PAD, -(GB.HEAD_H - 2))
	tb:SetHeight(TOOL_H)
	tb.icon = tb:CreateTexture(nil, "ARTWORK")
	tb.icon:SetSize(20, 20); tb.icon:SetPoint("LEFT", 0, 0)
	tb.icon:SetTexCoord(0.08, 0.92, 0.08, 0.92)
	tb.name = tb:CreateFontString(nil, "OVERLAY")
	tb.name:SetFontObject(GB.fonts.title)
	tb.name:SetPoint("LEFT", tb.icon, "RIGHT", 8, 0)
	tb.gear = GB:FlatButton(tb, "Tab settings")
	tb.gear:SetPoint("LEFT", tb.name, "RIGHT", 10, 0)
	tb.gear:SetScript("OnClick", function()
		if w.settings:IsShown() then w.settings:Hide() else GB:OpenTabSettings(w.bankType, w.tabID) end
	end)
	tb.usage = tb:CreateFontString(nil, "OVERLAY")
	tb.usage:SetFontObject(GB.fonts.button)
	tb.usage:SetPoint("RIGHT", 0, 0)
	tb.view = GB:FlatButton(tb, "Slots")
	tb.view:SetPoint("RIGHT", tb.usage, "LEFT", -10, 0)
	tb.view:SetScript("OnClick", function()
		GB.db.settings.bankView = GB.db.settings.bankView == "slots" and "sorted" or "slots"
		GB:BankToolbar(); GB:Layout(w, true)
	end)
	tb.who = GB:FlatButton(tb, "")
	tb.who:SetPoint("RIGHT", tb.view, "LEFT", -6, 0)
	tb.who.tip = "Look at another character's bank"
	tb.who:SetScript("OnClick", function(self)
		GB.Menu.CreateContextMenu(self, function(_, root)
			root:CreateTitle("Whose bank?")
			local keys = {}
			for key, c in pairs(GB.db.chars) do if c.bankSnap then keys[#keys + 1] = key end end
			table.sort(keys)
			for _, key in ipairs(keys) do
				local c = GB.db.chars[key]
				root:CreateRadio((c.name or key) .. "  " .. DIM .. (c.realm or "") .. "|r",
					function() return (w.viewKey or GB.charKey) == key end,
					function() w.viewKey = key; GB:InvalidateSaved(); GB:SelectBankTab(CHAR, nil) end)
			end
			if #keys == 0 then root:CreateTitle(DIM .. "No saved banks yet|r") end
		end)
	end)
	w.toolbar = tb

	-- scrolling grid area
	local scroll = CreateFrame("ScrollFrame", nil, w)
	scroll:SetPoint("TOPLEFT", RAIL_W + GB.PAD, -(GB.HEAD_H + TOOL_H))
	scroll:EnableMouseWheel(true)
	scroll:SetScript("OnMouseWheel", function(self, delta)
		local maxV = max(0, w.content:GetHeight() - self:GetHeight())
		self:SetVerticalScroll(min(maxV, max(0, self:GetVerticalScroll() - delta * 41 * 2)))
	end)
	w.content:SetParent(scroll)
	w.content:ClearAllPoints()
	scroll:SetScrollChild(w.content)
	w.scroll = scroll

	local lock = w:CreateFontString(nil, "OVERLAY")
	lock:SetFontObject(GB.fonts.button)
	lock:SetPoint("BOTTOM", scroll, "BOTTOM", 0, -2)
	lock:SetText("|cffffd27a" .. (ACCOUNT_BANK_ERROR_NO_LOCK or "Another character is using the Warband bank.") .. "|r")
	lock:Hide()
	w.lockNote = lock

	-- empty bank prompt
	local prompt = CreateFrame("Frame", nil, w)
	prompt:SetAllPoints(scroll)
	prompt.text = prompt:CreateFontString(nil, "OVERLAY")
	prompt.text:SetFontObject(GB.fonts.title)
	prompt.text:SetPoint("CENTER", 0, 16)
	prompt.buy = GB:FlatButton(prompt, "Buy your first tab", true)
	prompt.buy:SetPoint("TOP", prompt.text, "BOTTOM", 0, -12)
	prompt.buy:SetScript("OnClick", function() GB:BuyBankTab(w.bankType) end)
	prompt:Hide()
	w.prompt = prompt

	-- footer
	local f = w.footer
	f:ClearAllPoints()
	f:SetPoint("BOTTOMLEFT", RAIL_W + GB.PAD, 6); f:SetPoint("BOTTOMRIGHT", -GB.PAD, 6); f:SetHeight(GB.FOOT_H - 6)
	f.deposit = GB:FlatButton(f, "Deposit Reagents", true)
	f.deposit:SetPoint("LEFT")
	f.deposit:SetScript("OnClick", function() GB:BankDeposit() end)
	f.reagents = Check(f, "+ reagents")
	f.reagents:SetPoint("LEFT", f.deposit, "RIGHT", 8, 0)
	f.reagents.onToggle = function(self) SetCVar("bankAutoDepositReagents", self:GetChecked() and "1" or "0") end
	f.reagents:SetScript("OnShow", function(self) self:SetChecked(GetCVarBool("bankAutoDepositReagents")) end)
	f.clean = GB:FlatButton(f, "Clean Up")
	f.clean:SetPoint("LEFT", f.deposit, "RIGHT", 100, 0)
	f.clean.tip = "Sort this bank. Tabs set to \"leave alone\" are skipped."
	f.clean:SetScript("OnClick", function() GB:BankCleanUp() end)
	f.smart = GB:FlatButton(f, "Smart Clean", true)
	f.smart:SetPoint("LEFT", f.clean, "RIGHT", 4, 0)
	f.smart.tip = "Organize this bank into named tabs (Gear, Consumables, Trade Goods...) with matching icons and deposit rules. You'll see the plan first."
	f.smart:SetScript("OnClick", ShowPlan)

	-- drop strip above the footer
	local dz = CreateFrame("Button", nil, w, "BackdropTemplate")
	GB.Flat(dz, GB.colors.PANEL, GB.colors.EDGE)
	dz:SetPoint("BOTTOMLEFT", RAIL_W + GB.PAD, GB.FOOT_H + 4)
	dz:SetPoint("BOTTOMRIGHT", -GB.PAD, GB.FOOT_H + 4)
	dz:SetHeight(DROP_H - 6)
	dz.text = dz:CreateFontString(nil, "OVERLAY"); dz.text:SetFontObject(GB.fonts.head); dz.text:SetPoint("CENTER")
	dz:RegisterForClicks("LeftButtonUp")
	dz:SetScript("OnReceiveDrag", function() GB:DropToBank() end)
	dz:SetScript("OnClick", function() GB:DropToBank() end)
	function dz:Refresh()
		local holding = GetCursorInfo() == "item"
		self.text:SetText(holding and ("|c" .. GB.ACCENT_HEX .. (Live() and "Drop to bank it" or "Drop to bank it on your next visit") .. "|r")
			or (Live() and "Drag items here to bank them" or "Drag items here to bank them on your next visit"))
		self:SetBackdropBorderColor(unpack(holding and GB.colors.ACCENT_EDGE or GB.colors.EDGE))
	end
	dz:SetScript("OnEnter", function(self) self:Refresh() end)
	dz:Refresh()
	w.drop = dz
	f.take = GB:FlatButton(f, "Withdraw")
	f.take:SetPoint("RIGHT")
	f.take:SetScript("OnClick", function()
		StaticPopup_Hide("BANK_MONEY_DEPOSIT")
		StaticPopup_Show("BANK_MONEY_WITHDRAW", nil, nil, { bankType = w.bankType })
	end)
	f.give = GB:FlatButton(f, "Deposit")
	f.give:SetPoint("RIGHT", f.take, "LEFT", -4, 0)
	f.give:SetScript("OnClick", function()
		StaticPopup_Hide("BANK_MONEY_WITHDRAW")
		StaticPopup_Show("BANK_MONEY_DEPOSIT", nil, nil, { bankType = w.bankType })
	end)
	f.money = f:CreateFontString(nil, "OVERLAY")
	f.money:SetFontObject(GB.fonts.button)
	f.money:SetPoint("RIGHT", f.give, "LEFT", -8, 0)
	f.note = f:CreateFontString(nil, "OVERLAY")
	f.note:SetFontObject(GB.fonts.head)
	f.note:SetPoint("LEFT")
	f.note:Hide()
	w.foot = f

	-- fixed-width window; the grid scrolls past MAX_ROWS rows
	function w:OnSized(innerW, contentH)
		local cell = GB.db.settings.iconSize + GB.GAP
		local viewH = min(contentH, MAX_ROWS * cell + 20)
		viewH = max(viewH, 7 * cell - GB.GAP, (self.railHeight or 0) - TOOL_H - GB.FOOT_H)
		scroll:SetSize(innerW, viewH)
		self.content:SetWidth(innerW)
		self:SetSize(RAIL_W + innerW + GB.PAD * 2, GB.HEAD_H + TOOL_H + viewH + 8 + DROP_H + GB.FOOT_H)
		if self.emptyBank then
			prompt.text:SetText(self.bankType == ACCT and "Your Warband bank has no tabs yet" or "Your bank has no tabs yet")
			prompt.buy:SetShown(Live() and self.bankType ~= nil and C_Bank.CanPurchaseBankTab(self.bankType))
			if not Live() then prompt.text:SetText("No saved copy yet. Visit a banker once and it's here everywhere.") end
			prompt:Show()
		else
			prompt:Hide()
		end
	end

	BuildSettings()
	BuildPlanPanel()

	w:HookScript("OnHide", function()
		w.settings:Hide(); w.plan:Hide()
		if GB.bankOpen and not GB.showingBlizzBank and C_Bank and C_Bank.CloseBankFrame then C_Bank.CloseBankFrame() end
	end)
end

-- the bank window is made the first time you open your bank (or Bank Anywhere),
-- not at every login and /reload
local wanted = false
local function Ensure()
	if not w and wanted then CreateBank(); GB:ApplyTheme() end
	return w
end
GB:Listen("UI_READY", function()
	if not GB.db.settings.bankUI then return end
	wanted = true
	if BankFrame then BankFrame:SetParent(GB.hiddenParent) end
end)

function GB:ShowBlizzardBank()
	if not BankFrame then return end
	self.showingBlizzBank = true
	if w then w:Hide() end
	BankFrame:SetParent(UIParent)
	self.showingBlizzBank = false
end

---------------------------------------------------------------------------
-- Events
---------------------------------------------------------------------------
GB:Listen("BANK_OPENED", function()
	if not Ensure() then return end
	BankFrame:SetParent(GB.hiddenParent)
	local bt = CanView(CHAR) and CHAR or ACCT
	-- the Warband banker opens straight to the Warband side
	if C_PlayerInteractionManager and Enum.PlayerInteractionType and C_PlayerInteractionManager.IsInteractingWithNpcOfType
		and C_PlayerInteractionManager.IsInteractingWithNpcOfType(Enum.PlayerInteractionType.AccountBanker) then bt = ACCT end
	w.live, w.viewKey = true, GB.charKey
	GB:InvalidateSaved()
	w.bankType, w.tabID = bt, "all"
	if w:IsShown() then GB:SelectBankTab(bt, nil) else w:Show(); GB:SelectBankTab(bt, nil) end
	OpenAllBags()
	GB:ShowBags()
end)

GB:Listen("BANK_CLOSED", function()
	GB:InvalidateSaved()
	if w and w:IsShown() and w.live then w:Hide() end
	if w then w.live = false end
	if BankFrame and w then BankFrame:SetParent(GB.hiddenParent) end
	if GB.db.settings.autoClear then GB:Sweep() end
end)

GB:Listen("LAYOUT", function()
	if w and w:IsShown() then
		GB:BankRail(); GB:BankToolbar(); GB:Layout(w)
	end
end)

---------------------------------------------------------------------------
-- Bank Anywhere
---------------------------------------------------------------------------
function GB:ToggleBankAnywhere()
	if not Ensure() then return end
	if w:IsShown() then w:Hide(); return end
	w.live = self.bankOpen and true or false
	w.viewKey = GB.charKey
	self:InvalidateSaved()
	local hasChar = Snap(CHAR) ~= nil
	local bt = (w.live or hasChar or not Snap(ACCT)) and CHAR or ACCT
	w.bankType, w.tabID = bt, "all"
	w:Show()
	self:SelectBankTab(bt, nil)
end

function GB:RefreshBankAnywhere()
	if w and w:IsShown() then self:BankRail(); self:BankToolbar(); self:Layout(w, true) end
end

local function Refresh() if w and GB.bankOpen and w:IsShown() then GB:Debounce("bankui", 0.1, function()
	GB:ScanBank(); GB:BankRail(); GB:BankToolbar(); GB:Layout(w)
end) end end
GB:On("BANK_TABS_CHANGED", Refresh)
GB:On("BANK_TAB_SETTINGS_UPDATED", Refresh)
GB:On("ACCOUNT_MONEY", Refresh)
GB:On("PLAYER_MONEY", Refresh)
GB:On("PLAYER_ACCOUNT_BANK_TAB_SLOTS_CHANGED", Refresh)
GB:On("CURSOR_CHANGED", function() if w and w:IsShown() then w.drop:Refresh() end end)
end part() end
-- ==================== Bags/Mover.lua
do local __addon, __ns = ... local function part()
-- Copyright (C) 2026 SoFinSicc. Part of Pathway (curseforge.com/wow/addons/pathway): free software under the GPLv3 or later, with additional terms that require keeping this credit. See LICENSE.md.
--[[ Lil's GoodBags — Bank visits
     Everything that happens by itself when you reach a banker:
       · Send to Bank:   items you marked (or "Bank it" from the Inbox) get deposited
       · Withdraw:       items you marked in Bank Anywhere come back to your bags
       · Restock:        your restock list is topped up from the bank
       · Auto Clean Up:  optionally tidy the bank afterwards
     Moves are made one at a time with the cursor (like a bag sorter), re-reading
     the bags between moves, and pause in combat. ]]

local ADDON, P = __addon, __ns
local GB = P.Bags
local C_Item, C_Container, C_Bank = P.Item, P.Container, P.BankAPI

local ipairs, pairs, wipe, min, max = ipairs, pairs, wipe, math.min, math.max
local CHAR = GB.CHAR
local ACCT = GB.ACCT
local NORMAL_BAGS = { 0, 1, 2, 3, 4 }

---------------------------------------------------------------------------
-- Marks (work anywhere; carried out on the next bank visit)
---------------------------------------------------------------------------
local function Bankable(r)
	return r.classID == 7 or r.classID == 5 or r.classID == 3 or r.classID == 8
end

function GB:InboxBankable()
	local n = 0
	for _, r in ipairs(self.slots) do
		if self.cdb.inbox[r.itemID] and not self.cdb.locks[r.itemID] and Bankable(r) and not self.cdb.toBank[r.itemID] then n = n + 1 end
	end
	return n
end

function GB:BankInbox()
	local ids, n = {}, 0
	for _, r in ipairs(self.slots) do
		if self.cdb.inbox[r.itemID] and not self.cdb.locks[r.itemID] and Bankable(r) and not ids[r.itemID] then
			ids[r.itemID] = true; n = n + 1
		end
	end
	if n == 0 then return end
	for id in pairs(ids) do self.cdb.toBank[id] = true; self.cdb.inbox[id] = nil end
	if self.bankOpen then
		self:RunBankVisit()
	else
		self:Toast(("%d item%s will go to the bank on your next visit"):format(n, n == 1 and "" or "s"))
	end
	self:RequestLayout()
end

function GB:ToggleToBank(id)
	self.cdb.toBank[id] = (not self.cdb.toBank[id]) or nil
	if self.cdb.toBank[id] then
		self.cdb.withdraw[id] = nil
		if self.bankOpen then self:RunBankVisit() else self:Toast("Will be banked on your next visit") end
	end
	self:RequestLayout()
end

function GB:ToggleWithdraw(id)
	self.cdb.withdraw[id] = (not self.cdb.withdraw[id]) or nil
	if self.cdb.withdraw[id] then
		self.cdb.toBank[id] = nil
		if self.bankOpen then self:RunBankVisit() else self:Toast("Will be withdrawn on your next visit") end
	end
	self:RequestLayout()
	if self.RefreshBankAnywhere then self:RefreshBankAnywhere() end
end

function GB:SetRestock(id, n)
	n = tonumber(n)
	self.cdb.restock[id] = (n and n > 0) and math.floor(n) or nil
	if self.cdb.restock[id] and self.bankOpen then self:RunBankVisit() end
	self:RequestLayout()
end

---------------------------------------------------------------------------
-- Finding room
---------------------------------------------------------------------------
local function MaxStack(id)
	return (C_Item.GetItemMaxStackSizeByID and C_Item.GetItemMaxStackSizeByID(id)) or 1
end

local function IsReagent(id)
	return select(17, C_Item.GetItemInfo(id)) == true
end

local function FreeIn(bags, used)
	for _, bag in ipairs(bags) do
		for slot = 1, (C_Container.GetContainerNumSlots(bag) or 0) do
			if not used[bag * 1000 + slot] and not C_Container.GetContainerItemID(bag, slot) then return bag, slot end
		end
	end
end

-- somewhere in your bags for `amount` of item `id`
local function BagTarget(id, amount)
	local cap = MaxStack(id)
	for _, r in ipairs(GB.slots) do
		if r.itemID == id and not r.locked and r.count < cap then return r.bag, r.slot, min(amount, cap - r.count) end
	end
	local bag, slot = FreeIn(NORMAL_BAGS, GB.index)
	if not bag and IsReagent(id) then bag, slot = FreeIn({ GB.REAGENT_BAG }, GB.index) end
	if bag then return bag, slot, min(amount, cap) end
end

local CLASS_FLAG = function(r)
	local F = Enum.BagSlotFlags or {}
	if r.classID == 2 or r.classID == 4 then return F.ClassEquipment end
	if r.classID == 0 then return F.ClassConsumables end
	if r.classID == 7 or r.classID == 5 then return F.ClassReagents, F.ClassProfessionGoods end
	if GB:IsJunk(r) then return F.ClassJunk end
end

local function TabsFor(bt)
	local list = {}
	for _, t in ipairs((C_Bank.FetchPurchasedBankTabData and C_Bank.FetchPurchasedBankTabData(bt)) or {}) do list[#list + 1] = t end
	return list
end

-- somewhere in the bank for this bag record
local function BankTarget(r)
	local kinds = {}
	if CHAR and (not C_Bank.CanViewBank or C_Bank.CanViewBank(CHAR)) then kinds[#kinds + 1] = { CHAR, "character" } end
	if ACCT and (not C_Bank.CanViewBank or C_Bank.CanViewBank(ACCT)) then
		local loc = ItemLocation and ItemLocation:CreateFromBagAndSlot(r.bag, r.slot)
		if loc and C_Bank.IsItemAllowedInBankType(ACCT, loc) then kinds[#kinds + 1] = { ACCT, "account" } end
	end
	local cap = MaxStack(r.itemID)
	for _, k in ipairs(kinds) do
		-- 1) top up an existing stack
		for _, b in ipairs(GB.bank.slots) do
			if b.bankKind == k[2] and b.itemID == r.itemID and not b.locked and b.count < cap then
				return b.bag, b.slot, min(r.count, cap - b.count)
			end
		end
		-- 2) an empty slot, preferring tabs set to take this kind of item
		local f1, f2 = CLASS_FLAG(r)
		local preferred, others = {}, {}
		for _, t in ipairs(TabsFor(k[1])) do
			local fl = t.depositFlags or 0
			if (f1 and bit.band(fl, f1) ~= 0) or (f2 and bit.band(fl, f2) ~= 0) then preferred[#preferred + 1] = t.ID
			else others[#others + 1] = t.ID end
		end
		local bag, slot = FreeIn(preferred, GB.bank.index or {})
		if not bag then bag, slot = FreeIn(others, GB.bank.index or {}) end
		if bag then return bag, slot, r.count end
	end
end

GB.BankTargetFor = function(r) return BankTarget(r) end

---------------------------------------------------------------------------
-- The visit runner
---------------------------------------------------------------------------
local run          -- current run state
local ticker

local function Refresh()
	GB:ScanBags()
	if GB.bankOpen then GB:ScanBank() end
end

local function Move(sb, ss, db, ds, amount, total)
	ClearCursor()
	if amount < total then C_Container.SplitContainerItem(sb, ss, amount) else C_Container.PickupContainerItem(sb, ss) end
	C_Container.PickupContainerItem(db, ds)
	if CursorHasItem() then ClearCursor() end
end

-- one move per tick; returns false when the intent is finished
local function Step(job)
	local waiting = false   -- an item we need is still locked from the last move
	if job.kind == "deposit" then
		for _, r in ipairs(GB.slots) do
			if r.itemID == job.id then
				if r.locked then waiting = true else
					local db, ds, amt = BankTarget(r)
					if not db then job.blocked = "bank full"; return false end
					Move(r.bag, r.slot, db, ds, amt, r.count)
					run.deposited = run.deposited + amt
					return true
				end
			end
		end
		return waiting
	else -- withdraw / restock
		if job.want <= 0 then return false end
		for _, b in ipairs(GB.bank.slots) do
			if b.itemID == job.id then
				if b.locked then waiting = true else
					local tb, ts, room = BagTarget(job.id, min(job.want, b.count))
					if not tb then job.blocked = "bags full"; return false end
					local amt = min(room, b.count, job.want)
					Move(b.bag, b.slot, tb, ts, amt, b.count)
					job.want = job.want - amt
					if job.kind == "restock" then run.restocked = run.restocked + amt else run.withdrawn = run.withdrawn + amt end
					return true
				end
			end
		end
		return waiting
	end
end

local function Finish()
	if ticker then ticker:Cancel(); ticker = nil end
	local r = run
	run = nil
	if not r then return end
	Refresh()
	-- clear marks that were carried out
	for id in pairs(GB.cdb.toBank) do if (GB.counts[id] or 0) == 0 then GB.cdb.toBank[id] = nil end end
	for id in pairs(GB.cdb.withdraw) do
		local still = false
		for _, b in ipairs(GB.bank.slots) do if b.itemID == id then still = true; break end end
		if not still then GB.cdb.withdraw[id] = nil end
	end
	local parts = {}
	if r.deposited > 0 then parts[#parts + 1] = "banked " .. r.deposited end
	if r.withdrawn > 0 then parts[#parts + 1] = "withdrew " .. r.withdrawn end
	if r.restocked > 0 then parts[#parts + 1] = "restocked " .. r.restocked end
	if r.blocked then parts[#parts + 1] = "|cffff7a7a" .. r.blocked .. "|r" end
	if #parts > 0 then
		local msg = table.concat(parts, "  ·  ")
		GB:Toast(msg:sub(1, 1):upper() .. msg:sub(2))
	end
	-- optional tidy-up afterwards
	if GB.bankOpen then
		local s = GB.db.settings
		if s.autoSortBank and CHAR then C_Container.SortBank(CHAR) end
		if s.autoSortWarband and ACCT and (not C_Bank.CanViewBank or C_Bank.CanViewBank(ACCT)) then
			C_Timer.After(s.autoSortBank and 1.5 or 0, function() if GB.bankOpen then C_Container.SortBank(ACCT) end end)
		end
	end
	GB:RequestLayout()
end

function GB:RunBankVisit()
	if not self.bankOpen then return end
	if run then run.again = true; return end
	Refresh()
	local jobs = {}
	for id in pairs(self.cdb.toBank) do jobs[#jobs + 1] = { kind = "deposit", id = id } end
	for id in pairs(self.cdb.withdraw) do jobs[#jobs + 1] = { kind = "withdraw", id = id, want = math.huge } end
	if self.db.settings.autoRestock then
		for id, target in pairs(self.cdb.restock) do
			local need = target - (self.counts[id] or 0)
			if need > 0 then jobs[#jobs + 1] = { kind = "restock", id = id, want = need } end
		end
	end
	run = { jobs = jobs, i = 1, deposited = 0, withdrawn = 0, restocked = 0, steps = 0 }
	if #jobs == 0 then Finish(); return end
	ticker = C_Timer.NewTicker(0.25, function()
		if not GB.bankOpen then Finish(); return end
		if InCombatLockdown() or CursorHasItem() then return end
		run.steps = run.steps + 1
		if run.steps > 500 then Finish(); return end
		Refresh()
		local job = run.jobs[run.i]
		while job and not Step(job) do
			if job.blocked then run.blocked = job.blocked end
			run.i = run.i + 1
			job = run.jobs[run.i]
		end
		if not job then
			local again = run.again
			Finish()
			if again then GB:RunBankVisit() end
		end
	end)
end

function GB:RestockStatus()
	local list = {}
	for id, target in pairs(self.cdb.restock) do
		list[#list + 1] = { id = id, target = target, have = self.counts[id] or 0 }
	end
	table.sort(list, function(a, b) return a.id < b.id end)
	return list
end

-- kick off a visit once the bank's contents have arrived
GB:Listen("BANK_OPENED", function() C_Timer.After(0.6, function() GB:RunBankVisit() end) end)
end part() end
-- ==================== Bags/Split.lua
do local __addon, __ns = ... local function part()
-- Copyright (C) 2026 SoFinSicc. Part of Pathway (curseforge.com/wow/addons/pathway): free software under the GPLv3 or later, with additional terms that require keeping this credit. See LICENSE.md.
--[[ Lil's GoodBags — Stack splitter
     Shift+Right-Click any stack (bags or bank) for a small split window.
     The new stack goes into a free slot, and both stacks wear a little tag
     with the other one's count, so you can see the pair at a glance. ]]

local ADDON, P = __addon, __ns
local GB = P.Bags
local C_Item, C_Container, C_Bank = P.Item, P.Container, P.BankAPI

local floor, max, min = math.floor, math.max, math.min
local A = GB.ACCENT
local DIM = "|cff6b7480"

GB.splitPairs = {}     -- { id = itemID, a = key, b = key }  (key = bag*1000+slot)

local f            -- the split window
local NORMAL_BAGS = { 0, 1, 2, 3, 4 }

local function Free(bags, avoid)
	for _, bag in ipairs(bags) do
		for slot = 1, (C_Container.GetContainerNumSlots(bag) or 0) do
			if bag * 1000 + slot ~= avoid and not C_Container.GetContainerItemID(bag, slot) then return bag, slot end
		end
	end
end

-- a free slot near the stack: same bag/tab first, then the rest of that side
local function FreeNear(r)
	local key = r.bag * 1000 + r.slot
	local bag, slot = Free({ r.bag }, key)
	if bag then return bag, slot end
	if r.bankKind then
		local bt = r.bankKind == "account" and GB.ACCT or GB.CHAR
		return Free(GB.BankBags(bt), key)
	end
	if r.bag == GB.REAGENT_BAG then return nil end
	return Free(NORMAL_BAGS, key)
end

local function Record(key)
	return GB.index[key] or (GB.bank.index and GB.bank.index[key])
end

-- the other stack's count, if this record is half of a live pair
function GB:SplitPartner(r)
	if not self.db.settings.showSplit then return nil end
	local key = r.bag * 1000 + r.slot
	for i = #self.splitPairs, 1, -1 do
		local p = self.splitPairs[i]
		if p.a == key or p.b == key then
			local other = Record(p.a == key and p.b or p.a)
			local me = Record(key)
			if other and me and other.itemID == p.id and me.itemID == p.id then return other.count end
			table.remove(self.splitPairs, i)  -- merged, moved or used up: forget it
		end
	end
end

local function DoSplit()
	local r, n = f.record, f.amount
	if not r or n < 1 or n >= (r.count or 0) then f:Hide(); return end
	if CursorHasItem() then ClearCursor() end
	local db, ds = FreeNear(r)
	if not db then GB:Toast("|cffff7a7aNo free slot to split into|r"); return end
	C_Container.SplitContainerItem(r.bag, r.slot, n)
	C_Container.PickupContainerItem(db, ds)
	if CursorHasItem() then ClearCursor() end
	table.insert(GB.splitPairs, { id = r.itemID, a = r.bag * 1000 + r.slot, b = db * 1000 + ds })
	while #GB.splitPairs > 30 do table.remove(GB.splitPairs, 1) end
	f:Hide()
	PlaySound(SOUNDKIT.IG_BACKPACK_COIN_SELECT or 856)
end

local function SetAmount(v)
	local total = f.record and f.record.count or 2
	v = max(1, min(total - 1, floor(v + 0.5)))
	f.amount = v
	f.num:SetText(v)
	f.rest:SetText(DIM .. "leaves|r " .. (total - v))
	f.busy = true; f.slider:SetValue(v); f.busy = false
end

local function Create()
	f = CreateFrame("Frame", "PathwayBagsSplit", UIParent, "BackdropTemplate")
	GB.Flat(f, GB.colors.BG, GB.colors.EDGE, true)
	f:SetSize(236, 128)
	f:SetFrameStrata("DIALOG")
	f:EnableMouse(true)
	f:SetClampedToScreen(true)
	tinsert(UISpecialFrames, "PathwayBagsSplit")
	f:Hide()

	f.icon = f:CreateTexture(nil, "ARTWORK")
	f.icon:SetSize(22, 22); f.icon:SetPoint("TOPLEFT", 12, -12)
	f.icon:SetTexCoord(0.08, 0.92, 0.08, 0.92)
	f.title = f:CreateFontString(nil, "OVERLAY")
	f.title:SetFontObject(GB.fonts.button)
	f.title:SetPoint("LEFT", f.icon, "RIGHT", 8, 0); f.title:SetPoint("RIGHT", -12, 0)
	f.title:SetJustifyH("LEFT"); f.title:SetWordWrap(false)

	-- amount: number box with - / +
	local minus = GB:FlatButton(f, "-"); minus.minW = 24; minus:SetLabel("-")
	minus:SetPoint("TOPLEFT", 12, -44)
	local num = CreateFrame("EditBox", nil, f, "BackdropTemplate")
	GB.Flat(num, GB.colors.PANEL)
	num:SetSize(56, 22); num:SetPoint("LEFT", minus, "RIGHT", 4, 0)
	num:SetFontObject(GB.fonts.title); num:SetJustifyH("CENTER"); num:SetNumeric(true); num:SetAutoFocus(false)
	num:SetScript("OnEnterPressed", function() DoSplit() end)
	num:SetScript("OnEscapePressed", function() f:Hide() end)
	num:SetScript("OnTextChanged", function(s, user) if user then SetAmount(tonumber(s:GetText()) or 1) end end)
	local plus = GB:FlatButton(f, "+"); plus.minW = 24; plus:SetLabel("+")
	plus:SetPoint("LEFT", num, "RIGHT", 4, 0)
	minus:SetScript("OnClick", function() SetAmount(f.amount - (IsShiftKeyDown() and 10 or 1)) end)
	plus:SetScript("OnClick", function() SetAmount(f.amount + (IsShiftKeyDown() and 10 or 1)) end)
	f.num = num
	f.rest = f:CreateFontString(nil, "OVERLAY")
	f.rest:SetFontObject(GB.fonts.head)
	f.rest:SetPoint("LEFT", plus, "RIGHT", 10, 0)

	-- slider
	local s = CreateFrame("Slider", nil, f, "BackdropTemplate")
	s:SetOrientation("HORIZONTAL"); s:SetSize(212, 8); s:SetPoint("TOPLEFT", 12, -76)
	GB.Flat(s, GB.colors.PANEL)
	local thumb = s:CreateTexture(nil, "OVERLAY"); thumb:SetSize(10, 16)
	s:SetThumbTexture(thumb); s:SetValueStep(1); s:SetObeyStepOnDrag(true)
	s:SetScript("OnValueChanged", function(_, v) if not f.busy then SetAmount(v) end end)
	f.slider, f.thumb = s, thumb

	-- quick picks + split
	local half = GB:FlatButton(f, "Half"); half:SetPoint("TOPLEFT", 12, -96)
	half:SetScript("OnClick", function() SetAmount(floor((f.record.count or 2) / 2)) end)
	local prev = half
	for _, n in ipairs({ 1, 5, 20 }) do
		local b = GB:FlatButton(f, tostring(n)); b.minW = 26; b:SetLabel(tostring(n))
		b:SetPoint("LEFT", prev, "RIGHT", 4, 0)
		b:SetScript("OnClick", function() SetAmount(n) end)
		prev = b
	end
	local go = GB:FlatButton(f, "Split", true); go.minW = 56; go:SetLabel("Split")
	go:SetPoint("BOTTOMRIGHT", -12, 12)
	go:SetScript("OnClick", DoSplit)
	f.go = go
end

function GB:OpenSplit(button, r)
	if not r or not r.count or r.count < 2 then return end
	if InCombatLockdown() then return end
	if not f then Create() end
	if StackSplitFrame and StackSplitFrame:IsShown() then StackSplitFrame:Hide() end
	f.record = r
	f.icon:SetTexture(r.icon)
	f.title:SetText((r.link or r.name or "Stack") .. "  " .. DIM .. "x" .. r.count .. "|r")
	f.slider:SetMinMaxValues(1, r.count - 1)
	f.thumb:SetColorTexture(A[1], A[2], A[3], 1)
	f:ClearAllPoints()
	f:SetPoint("BOTTOM", button, "TOP", 0, 6)
	f:Show()
	SetAmount(floor(r.count / 2))
	f.num:SetFocus(); f.num:HighlightText()
end

-- the moment either stack changes item, its tag goes away on the next draw
GB:Listen("LAYOUT", function()
	if f and f:IsShown() and f.record then
		local live = Record(f.record.bag * 1000 + f.record.slot)
		if not live or live.itemID ~= f.record.itemID then f:Hide() end
	end
end)
end part() end
-- ==================== Bags/Features.lua
do local __addon, __ns = ... local function part()
-- Copyright (C) 2026 SoFinSicc. Part of Pathway (curseforge.com/wow/addons/pathway): free software under the GPLv3 or later, with additional terms that require keeping this credit. See LICENSE.md.
--[[ Lil's GoodBags — Features
     Toasts, Wowhead copy box, item & options menus, Smart Vendor Sweep,
     Session Yield, Crafting reverse-lookup, account-wide tooltips, slash. ]]

local ADDON, P = __addon, __ns
local GB = P.Bags
local C_Item, C_Container, C_Bank = P.Item, P.Container, P.BankAPI

local ipairs, pairs, wipe, max, min, floor = ipairs, pairs, wipe, math.max, math.min, math.floor
local A = GB.ACCENT
local DIM = "|cff6b7480"
local GOLD = "|cffffd27a"

---------------------------------------------------------------------------
-- Toast
---------------------------------------------------------------------------
local toast
function GB:Toast(msg)
	if not toast then
		toast = CreateFrame("Frame", nil, UIParent, "BackdropTemplate")
		GB.Flat(toast, GB.colors.BG, GB.colors.ACCENT_EDGE)
		toast:SetFrameStrata("DIALOG")
		toast:SetHeight(26)
		toast.text = toast:CreateFontString(nil, "OVERLAY")
		toast.text:SetFontObject(GB.fonts.button)
		toast.text:SetPoint("CENTER")
		local ag = toast:CreateAnimationGroup()
		local a1 = ag:CreateAnimation("Alpha"); a1:SetFromAlpha(0); a1:SetToAlpha(1); a1:SetDuration(0.15); a1:SetOrder(1)
		local a2 = ag:CreateAnimation("Alpha"); a2:SetFromAlpha(1); a2:SetToAlpha(0); a2:SetDuration(0.45); a2:SetStartDelay(1.9); a2:SetOrder(2)
		ag:SetScript("OnFinished", function() toast:Hide() end)
		toast.anim = ag
	end
	toast.text:SetText(msg)
	toast:SetWidth(toast.text:GetStringWidth() + 28)
	toast:ClearAllPoints()
	local w = self.bagWindow
	if w and w:IsShown() then toast:SetPoint("BOTTOM", w, "TOP", 0, 6) else toast:SetPoint("TOP", UIParent, "TOP", 0, -140) end
	toast:SetAlpha(0)
	toast:Show()
	toast.anim:Stop(); toast.anim:Play()
end

---------------------------------------------------------------------------
-- Wowhead copy box (addons can't write the clipboard; one Ctrl+C does it)
---------------------------------------------------------------------------
local function WowheadURL(r)
	local url = "https://www.wowhead.com/item=" .. r.itemID
	local payload = r.link and r.link:match("|Hitem:([^|]+)|h")
	if payload then
		local f = {}
		for v in (payload .. ":"):gmatch("([^:]*):") do f[#f + 1] = v end
		local n = tonumber(f[13] or "")
		if n and n > 0 then
			local bonus = {}
			for i = 14, 13 + n do if f[i] and f[i] ~= "" then bonus[#bonus + 1] = f[i] end end
			if #bonus > 0 then url = url .. "?bonus=" .. table.concat(bonus, ":") end
		end
	end
	if r.ilvl and r.ilvl > 1 then url = url .. (url:find("?", 1, true) and "&" or "?") .. "ilvl=" .. r.ilvl end
	return url
end
GB.WowheadURL = WowheadURL

local copy
function GB:ShowCopyBox(r)
	if not copy then
		copy = CreateFrame("Frame", "PathwayBagsCopyBox", UIParent, "BackdropTemplate")
		GB.Flat(copy, GB.colors.BG, GB.colors.ACCENT_EDGE)
		copy:SetFrameStrata("DIALOG")
		copy:SetSize(380, 74)
		copy:EnableMouse(true)
		tinsert(UISpecialFrames, "PathwayBagsCopyBox")
		copy.title = copy:CreateFontString(nil, "OVERLAY")
		copy.title:SetFontObject(GB.fonts.button)
		copy.title:SetPoint("TOPLEFT", 10, -9)
		copy.title:SetPoint("RIGHT", -10, 0)
		copy.title:SetJustifyH("LEFT")
		copy.hint = copy:CreateFontString(nil, "OVERLAY")
		copy.hint:SetFontObject(GB.fonts.head)
		copy.hint:SetPoint("BOTTOMLEFT", 10, 8)
		local eb = CreateFrame("EditBox", nil, copy, "BackdropTemplate")
		GB.Flat(eb, GB.colors.PANEL)
		eb:SetPoint("TOPLEFT", 8, -26); eb:SetPoint("TOPRIGHT", -8, -26); eb:SetHeight(22)
		eb:SetFontObject(GB.fonts.button)
		eb:SetTextInsets(6, 6, 0, 0)
		eb:SetAutoFocus(false)
		eb:SetScript("OnEscapePressed", function() copy:Hide() end)
		eb:SetScript("OnTextChanged", function(s, user) if user then s:SetText(copy.value); s:HighlightText() end end)
		eb:SetScript("OnEditFocusLost", function() copy:Hide() end)
		eb:SetScript("OnKeyDown", function(s, key)
			if key == "TAB" then
				copy.showID = not copy.showID
				GB:ShowCopyBox(copy.record)
			elseif key == "C" and (IsControlKeyDown() or IsMetaKeyDown()) then
				C_Timer.After(0.05, function()
					copy:Hide()
					GB:Toast("|c" .. GB.ACCENT_HEX .. "Copied!|r  " .. (copy.showID and "Item ID" or "Wowhead link") .. " is on your clipboard")
				end)
			end
		end)
		copy.edit = eb
	end
	copy.record = r
	copy.value = copy.showID and tostring(r.itemID) or WowheadURL(r)
	copy.title:SetText(r.link or r.name or ("Item " .. r.itemID))
	copy.hint:SetText("Ctrl+C to copy   ·   Tab: " .. (copy.showID and "Wowhead link" or "item ID") .. "   ·   Esc to close")
	copy.edit:SetText(copy.value)
	copy:ClearAllPoints()
	local x, y = GetCursorPosition()
	local s = UIParent:GetEffectiveScale()
	copy:SetPoint("BOTTOM", UIParent, "BOTTOMLEFT", x / s, y / s + 18)
	copy:Show()
	copy.edit:SetFocus()
	copy.edit:HighlightText()
end

---------------------------------------------------------------------------
-- Menus (Blizzard's modern Menu system — looks native, zero frames to own)
---------------------------------------------------------------------------
local function Flag(tbl, id) return function() return tbl[id] == true end end
local function Toggle(tbl, id, also) return function() tbl[id] = (not tbl[id]) or nil; if also and tbl[id] then also[id] = nil end; GB:RequestLayout() end end

function GB:ItemMenu(owner, r)
	local db = self.db
	GB.Menu.CreateContextMenu(owner, function(_, root)
		root:CreateTitle(r.name or "Item")
		root:CreateCheckbox("Pin to top", Flag(db.pinned, r.itemID), Toggle(db.pinned, r.itemID))
		root:CreateCheckbox("Mark as junk", Flag(db.junk, r.itemID), Toggle(db.junk, r.itemID, db.neverSell))
		root:CreateCheckbox("Never sell", Flag(db.neverSell, r.itemID), Toggle(db.neverSell, r.itemID, db.junk))
		root:CreateDivider()
		local inBags = not r.bankKind
		if inBags then
			root:CreateCheckbox(self.bankOpen and "Send to bank now" or "Send to bank next visit",
				function() return self.cdb.toBank[r.itemID] == true end, function() self:ToggleToBank(r.itemID) end)
		else
			root:CreateCheckbox(self.bankOpen and "Withdraw now" or "Withdraw next visit",
				function() return self.cdb.withdraw[r.itemID] == true end, function() self:ToggleWithdraw(r.itemID) end)
		end
		local keep = self.cdb.restock[r.itemID]
		root:CreateButton(keep and ("Restock: keep " .. keep .. " on me...") or "Restock: keep some on me...", function()
			C_Timer.After(0, function() StaticPopup_Show("PATHWAYBAGS_RESTOCK", r.name or "this item", nil, { id = r.itemID, count = r.count }) end)
		end)
		root:CreateButton("Send to Loot Inbox", function()
			self.cdb.inbox[r.itemID] = { n = r.count or 1, t = time() }
			self:RequestLayout()
		end)
		root:CreateButton("Copy Wowhead link", function() C_Timer.After(0, function() self:ShowCopyBox(r) end) end)
	end)
end

local function Setting(key) return function(v) return GB.db.settings[key] == v end end
local function Set(key) return function(v) GB.db.settings[key] = v; GB:LayoutAll() end end
local function Check(key) return function() return GB.db.settings[key] end end
local function Flip(key) return function() GB.db.settings[key] = not GB.db.settings[key]; GB:LayoutAll() end end

local function PopupEditBox(dialog) return dialog.GetEditBox and dialog:GetEditBox() or dialog.EditBox or dialog.editBox end
StaticPopupDialogs["PATHWAYBAGS_RESTOCK"] = {
	text = "Restock |cff6ee7b7%s|r\n\nHow many should you always carry? Pathway tops you up from the bank on every visit. (0 removes it)",
	button1 = OKAY or "Okay", button2 = CANCEL or "Cancel",
	hasEditBox = 1,
