-- "Eco-Dome Al'dani" -> "EDA": short dungeon tag for keystones
local keyNames = {}
function GB:KeystoneShort(mapID)
	if not mapID then return "" end
	local v = keyNames[mapID]
	if not v then
		local name = C_ChallengeMode and C_ChallengeMode.GetMapUIInfo and C_ChallengeMode.GetMapUIInfo(mapID)
		v = ""
		if name then
			for word in name:gmatch("[%w']+") do
				local c = word:sub(1, 1)
				if c:match("%u") or #v == 0 then v = v .. c:upper() end
			end
			v = v:sub(1, 4)
		end
		keyNames[mapID] = v
	end
	return "|cffffd27a" .. v .. "|r"
end

