---------------------------------------------------------------------------
-- Smart Vendor Sweep
---------------------------------------------------------------------------
local function VendorPrice(id) return select(11, C_Item.GetItemInfo(id)) or 0 end

function GB:JunkList()
	local list, value = {}, 0
	for _, r in ipairs(self.slots) do
		if self:IsJunk(r) and not r.locked and not r.noValue and not self:IsLocked(r.itemID) then
			local inSet = C_Container.GetContainerItemEquipmentSetInfo and C_Container.GetContainerItemEquipmentSetInfo(r.bag, r.slot)
			if not inSet then
				list[#list + 1] = r
				value = value + VendorPrice(r.itemID) * (r.count or 1)
			end
		end
	end
	return list, value
end

function GB:JunkSummary() local l, v = self:JunkList(); return #l, v end

StaticPopupDialogs["PATHWAYBAGS_SELL"] = {
	text = "Sell %d items? Only the last 12 can be bought back.",
	button1 = YES or "Yes", button2 = NO or "No",
	OnAccept = function(_, data) GB:DoSell(data) end,
	timeout = 0, whileDead = 1, hideOnEscape = 1,
}

function GB:SellJunk()
	if not (MerchantFrame and MerchantFrame:IsShown()) then return end
	local list, value = self:JunkList()
	if #list == 0 then return end
	local queue = {}
	for i, r in ipairs(list) do queue[i] = { bag = r.bag, slot = r.slot, itemID = r.itemID } end
	queue.value = value
	if #queue > 12 then StaticPopup_Show("PATHWAYBAGS_SELL", #queue, nil, queue) else self:DoSell(queue) end
end

function GB:DoSell(queue)
	if self.selling then return end
	self.selling = true
	local i, sold = 0, 0
	local ticker
	ticker = C_Timer.NewTicker(0.15, function()
		i = i + 1
		local q = queue[i]
		if not q or not (MerchantFrame and MerchantFrame:IsShown()) then
			ticker:Cancel()
			self.selling = false
			if sold > 0 then
				self:Toast(("Sold %d item%s for %s"):format(sold, sold == 1 and "" or "s", GetMoneyString(queue.value, true)))
			end
			return
		end
		-- sell by handing the item to the merchant (not "using" it), which
		-- addons are always allowed to do
		if C_Container.GetContainerItemID(q.bag, q.slot) == q.itemID and not CursorHasItem() then
			C_Container.PickupContainerItem(q.bag, q.slot)
			if CursorHasItem() then PickupMerchantItem(0) end
			if CursorHasItem() then ClearCursor() else sold = sold + 1 end
		end
	end)
end

---------------------------------------------------------------------------
-- Session Yield
---------------------------------------------------------------------------
GB.session = { active = false, gains = {}, rares = {} }

local function Price(id)
	local p
	if Auctionator and Auctionator.API and Auctionator.API.v1 then
		p = select(2, pcall(Auctionator.API.v1.GetAuctionPriceByItemID, ADDON, id))
	end
	if type(p) ~= "number" and TSM_API and TSM_API.GetCustomPriceValue then
		p = select(2, pcall(TSM_API.GetCustomPriceValue, "DBMarket", "i:" .. id))
	end
	if type(p) ~= "number" then p = VendorPrice(id) end
	return p or 0
end

local function Elapsed(sec)
	sec = floor(sec)
	if sec >= 3600 then return ("%dh %02dm"):format(floor(sec / 3600), floor((sec % 3600) / 60)) end
	return ("%dm %02ds"):format(floor(sec / 60), sec % 60)
end

local function Coins(c)
	c = max(0, c or 0)
	return GetMoneyString(c >= 10000 and floor(c / 10000) * 10000 or floor(c / 100) * 100, true)
end

function GB:SessionNumbers()
	local s = self.session
	local items, value = 0, 0
	for id, n in pairs(s.gains) do items = items + n; value = value + Price(id) * n end
	local gold = GetMoney() - (s.money0 or GetMoney())
	local secs = max(1, GetTime() - (s.start or GetTime()))
	return items, value, gold, secs, (value + max(gold, 0)) / secs * 3600
end

function GB:SessionSummary()
	local _, _, _, secs, perHour = self:SessionNumbers()
	return Elapsed(secs) .. "  ·  " .. Coins(perHour) .. "/hr"
end

function GB:SessionStatsLine()
	local items, value, gold, secs, perHour = self:SessionNumbers()
	local parts = {
		("%d items"):format(items),
		"~" .. Coins(value) .. " value",
	}
	if gold > 0 then parts[#parts + 1] = Coins(gold) .. " looted" end
	if #self.session.rares > 0 then parts[#parts + 1] = GOLD .. #self.session.rares .. " rare" .. (#self.session.rares == 1 and "" or "s") .. "|r" end
	parts[#parts + 1] = "|c" .. GB.ACCENT_HEX .. Coins(perHour) .. "/hr|r"
	return Elapsed(secs) .. "   " .. table.concat(parts, DIM .. "  ·  |r")
end

function GB:ToggleSession()
	local s = self.session
	if s.active then
		s.active = false
		if s.ticker then s.ticker:Cancel(); s.ticker = nil end
		local items, value, gold, secs, perHour = self:SessionNumbers()
		self:Print("Session Yield — %s", Elapsed(secs))
		self:Print("  %d items  ·  ~%s value  ·  %s gold looted  ·  %s/hr", items, Coins(value), Coins(gold), Coins(perHour))
		local top = {}
		for id, n in pairs(s.gains) do top[#top + 1] = { id = id, n = n, v = Price(id) * n } end
		table.sort(top, function(a, b) return a.v > b.v end)
		for i = 1, min(5, #top) do
			local link = select(2, C_Item.GetItemInfo(top[i].id)) or ("item:" .. top[i].id)
			self:Print("  %s ×%d  ~%s", link, top[i].n, Coins(top[i].v))
		end
		for _, link in ipairs(s.rares) do self:Print("  " .. GOLD .. "Rare catch:|r %s", link) end
		self:Toast("Session ended  ·  " .. Coins(perHour) .. "/hr  ·  summary in chat")
	else
		wipe(s.gains); wipe(s.rares)
		s.active, s.start, s.money0 = true, GetTime(), GetMoney()
		s.ticker = C_Timer.NewTicker(1, function()
			local w = GB.bagWindow
			if w and w:IsShown() and w.sessionBar:IsShown() then w.sessionBar.stats:SetText(GB:SessionStatsLine()) end
		end)
		self:Toast("Session Yield started — farm away")
	end
	if self.bagWindow then self.bagWindow.yieldButton:SetLabel(s.active and ("|c" .. GB.ACCENT_HEX .. "Yield|r") or "Yield") end
	self:RequestLayout()
end

GB:Listen("ITEM_GAINED", function(id, delta)
	local s = GB.session
	if not s.active then return end
	s.gains[id] = (s.gains[id] or 0) + delta
	local q = C_Item.GetItemQualityByID(id)
	if q and q >= 3 then
		local link = select(2, C_Item.GetItemInfo(id)) or ("item:" .. id)
		s.rares[#s.rares + 1] = link
		GB:Toast(GOLD .. "Rare catch!|r  " .. link)
	end
end)

---------------------------------------------------------------------------
-- Crafting reverse-lookup (tracked recipes + your claimed crafting order)
---------------------------------------------------------------------------
local function AddRecipe(recipeID, isRecraft, orderFor)
	local schematic = C_TradeSkillUI.GetRecipeSchematic(recipeID, isRecraft and true or false)
	if not schematic then return end
	local name = schematic.name or ("Recipe " .. recipeID)
	for _, slot in ipairs(schematic.reagentSlotSchematics or {}) do
		if slot.required ~= false then
			for _, reagent in ipairs(slot.reagents or {}) do
				local id = reagent.itemID
				if id then
					GB.craftNeeds[id] = GB.craftNeeds[id] or {}
					table.insert(GB.craftNeeds[id], { name = name, qty = slot.quantityRequired or 1, order = orderFor })
				end
			end
		end
	end
end

function GB:RebuildCrafting()
	if not (C_TradeSkillUI and C_TradeSkillUI.GetRecipesTracked) then return end
	wipe(self.craftNeeds)
	pcall(function()
		for _, isRecraft in ipairs({ false, true }) do
			for _, id in ipairs(C_TradeSkillUI.GetRecipesTracked(isRecraft) or {}) do AddRecipe(id, isRecraft) end
		end
		local order = C_CraftingOrders and C_CraftingOrders.GetClaimedOrder and C_CraftingOrders.GetClaimedOrder()
		if order and order.spellID then
			self.cdb.claimed = { recipeID = order.spellID, isRecraft = order.isRecraft, customer = order.customerName }
		end
		local c = self.cdb.claimed
		if c and c.recipeID then AddRecipe(c.recipeID, c.isRecraft, c.customer or "a customer") end
	end)
	self:RequestLayout()
end

local function CraftChanged() GB:Debounce("craft", 0.3, function() GB:RebuildCrafting() end) end
GB:On("TRACKED_RECIPE_UPDATE", CraftChanged)
GB:On("TRADE_SKILL_SHOW", CraftChanged)
GB:On("CRAFTINGORDERS_CLAIMED_ORDER_ADDED", CraftChanged)
GB:On("CRAFTINGORDERS_CLAIMED_ORDER_UPDATED", CraftChanged)
GB:On("CRAFTINGORDERS_CLAIMED_ORDER_REMOVED", function() GB.cdb.claimed = {}; CraftChanged() end)
GB:On("PLAYER_ENTERING_WORLD", function(_, isLogin, isReload)
	if isLogin or isReload then C_Timer.After(5, function() GB:RebuildCrafting() end) end
end)

---------------------------------------------------------------------------
-- Tooltips: crafting needs + account-wide counts
---------------------------------------------------------------------------
local function ClassColor(class)
	local c = class and C_ClassColor and C_ClassColor.GetClassColor(class)
	return c and c:GenerateHexColor() or "ffffffff"
end

local function Ago(t)
	local d = time() - (t or 0)
	if d < 3600 then return floor(d / 60) .. "m ago" end
	if d < 86400 then return floor(d / 3600) .. "h ago" end
	return floor(d / 86400) .. "d ago"
end

local function ItemCountLines(tt, id)
	local rows, total = {}, 0
	for key, c in pairs(GB.db.chars) do
		local bagsN, bankN
		if key == GB.charKey then
			bagsN = (GB.counts[id] or 0)
			for slot = 1, 19 do if GetInventoryItemID("player", slot) == id then bagsN = bagsN + 1 end end
			bankN = GB.bankOpen and (GB.bank.counts[id] or 0) or ((c.bank or {})[id] or 0)
		else
			bagsN, bankN = (c.bags or {})[id] or 0, (c.bank or {})[id] or 0
		end
		local n = bagsN + bankN
		if n > 0 then
			local where = (bagsN > 0 and bankN > 0) and (DIM .. "  (bags " .. bagsN .. ", bank " .. bankN .. ")|r")
				or (bankN > 0 and (DIM .. "  (bank)|r") or "")
			rows[#rows + 1] = { left = "|c" .. ClassColor(c.class) .. (c.name or key) .. "|r", right = n .. where, n = n, me = key == GB.charKey }
			total = total + n
		end
	end
	local war = GB.bankOpen and (GB.bank.warCounts[id] or 0) or (GB.db.warband.items[id] or 0)
	if war > 0 then
		rows[#rows + 1] = { left = "|cff66bbffWarband bank|r", right = war .. (GB.bankOpen and "" or (DIM .. "  (" .. Ago(GB.db.warband.t) .. ")|r")), n = war }
		total = total + war
	end
	-- only worth the space when the item lives somewhere other than these bags
	if #rows == 0 or (#rows == 1 and rows[1].me and not rows[1].right:find("bank")) then return end
	table.sort(rows, function(a, b) return a.n > b.n end)
	tt:AddLine(" ")
	for i = 1, min(6, #rows) do tt:AddDoubleLine(rows[i].left, rows[i].right, 1, 1, 1, 1, 1, 1) end
	if #rows > 6 then tt:AddLine(DIM .. "...and " .. (#rows - 6) .. " more|r") end
	if #rows > 1 then tt:AddDoubleLine(DIM .. "Total|r", "|c" .. GB.ACCENT_HEX .. total .. "|r") end
end

local function OnItemTooltip(tt, data)
	if not GB.db or (tt ~= GameTooltip and tt ~= ItemRefTooltip) then return end
	local id = data and data.id
	if not id or (issecretvalue and issecretvalue(id)) then return end
	-- why GoodBags thinks this is an upgrade
	local owner = tt.GetOwner and tt:GetOwner()
	local rec = owner and owner.gbRecord
	local up = rec and not rec.free and not rec.empty and rec.itemID == id and GB:UpgradeInfo(rec)
	if up then
		tt:AddLine(" ")
		local pct = up.pct and (DIM .. ("  (+%d%%)"):format(math.floor(up.pct * 100 + 0.5)) .. "|r") or ""
		tt:AddLine("|cff4dff6aUpgrade|r  " .. (up.empty and "fills an empty slot" or (up.diff or "")) .. pct, 1, 1, 1)
	end
	if rec and not rec.free and GB.SplitPartner then
		local other = GB:SplitPartner(rec)
		if other then tt:AddLine(DIM .. "Split stack  ·  the other half has|r " .. other) end
	end
	local needs = GB.craftNeeds[id]
	if needs then
		tt:AddLine(" ")
		for i = 1, min(4, #needs) do
			local nd = needs[i]
			if nd.order then
				tt:AddDoubleLine(GOLD .. "Crafting order|r " .. nd.name, "×" .. nd.qty, 1, 1, 1, 1, 1, 1)
			else
				tt:AddDoubleLine(GOLD .. "Needed for|r " .. nd.name, "×" .. nd.qty, 1, 1, 1, 1, 1, 1)
			end
		end
	end
	ItemCountLines(tt, id)
end

local function OnCurrencyTooltip(tt, data)
	if not GB.db or tt ~= GameTooltip then return end
	local id = data and data.id
	if not id or (issecretvalue and issecretvalue(id)) or not C_CurrencyInfo.FetchCurrencyDataFromAccountCharacters then return end
	if not C_CurrencyInfo.IsAccountCharacterCurrencyDataReady() then
		C_CurrencyInfo.RequestCurrencyDataForAccountCharacters()
		return
	end
	local list = C_CurrencyInfo.FetchCurrencyDataFromAccountCharacters(id)
	if not list or #list == 0 then return end
	table.sort(list, function(a, b) return (a.quantity or 0) > (b.quantity or 0) end)
	tt:AddLine(" ")
	tt:AddLine(DIM .. "Across your Warband|r")
	local shown = 0
	for _, e in ipairs(list) do
		if (e.quantity or 0) > 0 and shown < 6 then
			local class
			for _, c in pairs(GB.db.chars) do if c.name == e.characterName then class = c.class end end
			tt:AddDoubleLine("|c" .. ClassColor(class) .. (e.characterName or "?") .. "|r", BreakUpLargeNumbers(e.quantity), 1, 1, 1, 1, 1, 1)
			shown = shown + 1
		end
	end
end

function GB:MoneyTooltip(owner)
	GameTooltip:SetOwner(owner, "ANCHOR_TOPLEFT")
	GameTooltip:AddLine("Gold")
	local rows, total = {}, 0
	for key, c in pairs(self.db.chars) do
		local m = key == self.charKey and GetMoney() or (c.money or 0)
		if m > 0 then rows[#rows + 1] = { c = c, m = m }; total = total + m end
	end
	table.sort(rows, function(a, b) return a.m > b.m end)
	for _, r in ipairs(rows) do
		GameTooltip:AddDoubleLine("|c" .. ClassColor(r.c.class) .. (r.c.name or "?") .. "|r", GetMoneyString(r.m, true), 1, 1, 1, 1, 1, 1)
	end
	local war = self.db.warband.money or 0
	if war > 0 then
		GameTooltip:AddDoubleLine("|cff66bbffWarband bank|r", GetMoneyString(war, true), 1, 1, 1, 1, 1, 1)
		total = total + war
	end
	GameTooltip:AddLine(" ")
	GameTooltip:AddDoubleLine(DIM .. "Total|r", GetMoneyString(total, true), 1, 1, 1, 1, 1, 1)
	GameTooltip:Show()
end

GB:Listen("READY", function()
	if TooltipDataProcessor and Enum.TooltipDataType then
		TooltipDataProcessor.AddTooltipPostCall(Enum.TooltipDataType.Item, OnItemTooltip)
		if Enum.TooltipDataType.Currency then TooltipDataProcessor.AddTooltipPostCall(Enum.TooltipDataType.Currency, OnCurrencyTooltip) end
	else
		-- Classic clients: the older tooltip hook
		local function hook(tt)
			local _, link = tt:GetItem()
			local id = link and tonumber(link:match("item:(%d+)"))
			if id then OnItemTooltip(tt, { id = id }) end
		end
		GameTooltip:HookScript("OnTooltipSetItem", hook)
		if ItemRefTooltip then ItemRefTooltip:HookScript("OnTooltipSetItem", hook) end
	end
	if C_CurrencyInfo and C_CurrencyInfo.RequestCurrencyDataForAccountCharacters then
		C_Timer.After(8, function() C_CurrencyInfo.RequestCurrencyDataForAccountCharacters() end)
	end
end)

---------------------------------------------------------------------------
-- Slash commands & addon compartment
---------------------------------------------------------------------------
local HELP = {
	"/gb — open or close your bags",
	"/gb settings — open settings",
	"/gb setup — choose Categories or One big grid again",
	"/gb sweep — sort the Loot Inbox into your bags",
	"/gb yield — start or stop a Session Yield",
	"/gb age <minutes> — auto-sort new items after N minutes (0 = never)",
	"/gb cols <n>  ·  /gb scale <0.5-2>",
	"/gb autoclear — toggle sorting the Inbox when a vendor or bank closes",
	"/gb bank — Bank Anywhere: your bank from anywhere",
	"/gb restock — show your restock list",
	"/gb bankui — toggle Pathway's bank window (reloads)",
	"/gb reset — reset window positions",
}

SLASH_PATHWAYBAGS1, SLASH_PATHWAYBAGS2, SLASH_PATHWAYBAGS3 = "/gb", "/goodbags", "/mybag"
SlashCmdList.PATHWAYBAGS = function(msg)
	local cmd, arg = (msg or ""):lower():match("^%s*(%S*)%s*(.-)%s*$")
	if not GB.db then P:Print("Bags are switched off. Turn them on in /pw settings > Modules."); return end
	local s = GB.db.settings
	if cmd == "" then
		GB:ToggleBags()
	elseif cmd == "settings" or cmd == "config" or cmd == "options" then
		GB:OpenSettings()
	elseif cmd == "setup" then
		s.welcomed = false
		GB:ShowBags(); GB:LayoutAll()
	elseif cmd == "sweep" or cmd == "sort" then
		GB:Print("Sorted %d item(s) into your bags.", GB:Sweep())
	elseif cmd == "yield" or cmd == "session" then
		GB:ToggleSession()
	elseif cmd == "age" and tonumber(arg) then
		s.ageMinutes = max(0, floor(tonumber(arg)))
		GB:Print(s.ageMinutes == 0 and "New items stay in the Inbox until you sort them." or "New items auto-sort after %d minutes.", s.ageMinutes)
		GB:AgeInbox()
	elseif cmd == "cols" and tonumber(arg) then
		s.cols = min(24, max(10, floor(tonumber(arg)))); GB:LayoutAll()
	elseif cmd == "scale" and tonumber(arg) then
		s.scale = min(2, max(0.5, tonumber(arg)))
		if GB.bagWindow then GB.bagWindow:SetScale(s.scale) end
		if GB.bankWindow then GB.bankWindow:SetScale(s.scale) end
	elseif cmd == "autoclear" then
		s.autoClear = not s.autoClear
		GB:Print("Sort Inbox when a vendor or bank closes: %s", s.autoClear and "on" or "off")
	elseif cmd == "bank" then
		GB:ToggleBankAnywhere()
	elseif cmd == "restock" then
		local entries = GB:RestockStatus()
		if #entries == 0 then GB:Print("Your restock list is empty. Alt+Right-Click an item and choose Restock.") end
		for _, e in ipairs(entries) do
			GB:Print("  %s  %d / %d", select(2, C_Item.GetItemInfo(e.id)) or ("item " .. e.id), e.have, e.target)
		end
	elseif cmd == "bankui" then
		s.bankUI = not s.bankUI
		StaticPopup_Show("PATHWAYBAGS_RELOAD")
	elseif cmd == "reset" then
		wipe(GB.db.pos)
		GB:Print("Window positions reset — /reload to apply.")
	else
		for _, line in ipairs(HELP) do GB:Print(line) end
	end
end



-- optional: sell junk the moment a vendor opens
GB:On("MERCHANT_SHOW", function()
	if GB.db and GB.db.settings.autoSell then C_Timer.After(0.4, function() GB:SellJunk() end) end
end)
end part() end
-- ==================== Bags/Labels.lua
do local __addon, __ns = ... local function part()
-- Copyright (C) 2026 SoFinSicc. Part of Pathway (curseforge.com/wow/addons/pathway): free software under the GPLv3 or later, with additional terms that require keeping this credit. See LICENSE.md.
--[[ Pathway bags — labels for the Bags view
     In the Bags view each bag can carry a label (Equipment, Consumables, Trade
     Goods...). "Clean up to labels" moves every item into the bag labeled for
     it, one item at a time like any bag sorter, and pauses in combat. Items
     with no labeled bag go to the bags you left unlabeled. ]]

local ADDON, P = __addon, __ns
local GB = P.Bags
local C_Container, C_Item = P.Container, P.Item

GB.LABELS = {
	{ key = "equipment",  title = "Equipment" },
	{ key = "consumable", title = "Consumables" },
	{ key = "tradegoods", title = "Trade Goods" },
	{ key = "quest",      title = "Quest" },
	{ key = "recipe",     title = "Recipes" },
	{ key = "junk",       title = "Junk" },
	{ key = "other",      title = "Everything else" },
}
local BY = {}
for _, l in ipairs(GB.LABELS) do BY[l.key] = l end

function GB:BagLabel(bag) local k = self.cdb and self.cdb.bagLabels[bag] return k and BY[k] end

function GB:BagName(bag)
	if bag == 0 then return "Backpack" end
	local name = C_Container.GetBagName and C_Container.GetBagName(bag)
	return name or ("Bag " .. bag)
end

-- quivers, ammo pouches and soul bags only take their own things
function GB:CanLabel(bag)
	local _, family = C_Container.GetContainerNumFreeSlots(bag)
	return (family or 0) == 0
end

function GB:LabelMenu(owner, bag)
	GB.Menu.CreateContextMenu(owner, function(_, root)
		root:CreateTitle(GB:BagName(bag))
		local cur = self.cdb.bagLabels[bag]
		for _, l in ipairs(GB.LABELS) do
			root:CreateRadio(l.title, function() return cur == l.key end, function()
				self.cdb.bagLabels[bag] = l.key
				self:LayoutAll()
			end)
		end
		root:CreateDivider()
		root:CreateRadio("No label (anything)", function() return cur == nil end, function()
			self.cdb.bagLabels[bag] = nil
			self:LayoutAll()
		end)
	end)
end

-- which label an item belongs under
local MAP = { pinned = false, crafting = "tradegoods", collectible = "other", decor = "other" }
local function LabelFor(r)
	local c = GB:Classify(r)
	if MAP[c] ~= nil then return MAP[c] end
	return c
end

---------------------------------------------------------------------------
-- Sorting: one move at a time, re-reading the bags between moves
---------------------------------------------------------------------------
local ticker, moved, stuck

local function Snapshot()
	local items, free = {}, {}
	for _, bag in ipairs(GB.BAGS) do
		if bag ~= GB.REAGENT_BAG and GB:CanLabel(bag) then
			free[bag] = {}
			for slot = 1, C_Container.GetContainerNumSlots(bag) or 0 do
				local info = C_Container.GetContainerItemInfo(bag, slot)
				if info and info.itemID then
					if info.isLocked then return nil end                 -- still moving: wait
					local st = GB.Static(info.itemID)
					local qi = C_Container.GetContainerItemQuestInfo(bag, slot)
					items[#items + 1] = { bag = bag, slot = slot, itemID = info.itemID, quality = info.quality or 1,
						noValue = info.hasNoValue, classID = st.classID, subclassID = st.subclassID, equipLoc = st.equipLoc,
						isQuest = qi and qi.isQuestItem, questID = qi and qi.questID, isKey = st.isKey }
				else
					table.insert(free[bag], slot)
				end
			end
		end
	end
	return items, free
end

-- the next move: a misplaced item and a free slot where it belongs
local function NextMove()
	local items, free = Snapshot()
	if not items then return "wait" end
	local labels = GB.cdb.bagLabels
	local home, general = {}, {}
	for _, bag in ipairs(GB.BAGS) do
		if free[bag] then
			local l = labels[bag]
			if l then home[l] = home[l] or {}; table.insert(home[l], bag) else general[#general + 1] = bag end
		end
	end
	local function slotIn(bags)
		for _, b in ipairs(bags or {}) do if free[b] and free[b][1] then return b, free[b][1] end end
	end
	stuck = 0
	-- first, items sitting in a bag labeled for something else (makes room), then the rest
	for pass = 1, 2 do
		for _, r in ipairs(items) do
			local want = LabelFor(r)
			local here = labels[r.bag]
			if want and here ~= want and (pass == 2 or here) and not GB.cdb.locks[r.itemID] then
				local wrongHere = here ~= nil                       -- in someone else's labeled bag
				local targets = home[want]
				if targets or wrongHere then
					local b, s = slotIn(targets)
					if not b and wrongHere then b, s = slotIn(general) end
					if b then return r.bag, r.slot, b, s end
					stuck = stuck + 1
				end
			end
		end
	end
end

local function Finish(msg)
	if ticker then ticker:Cancel(); ticker = nil end
	GB.labelSorting = nil
	GB:LayoutAll()
	if msg then GB:Toast(msg) end
end

function GB:SortToLabels()
	if ticker then return end
	if InCombatLockdown() then self:Toast("After the fight") return end
	if not next(self.cdb.bagLabels) then self:Toast("Label a bag first: click its name") return end
	moved, stuck = 0, 0
	GB.labelSorting = true
	self:LayoutAll()
	local idle = 0
	ticker = C_Timer.NewTicker(0.15, function()
		if InCombatLockdown() then return end                        -- pause, carry on after
		if GetCursorInfo() then ClearCursor() return end
		local sb, ss, db, ds = NextMove()
		if sb == "wait" then
			idle = idle + 1
			if idle > 40 then Finish("Bags are busy; try again in a moment") end
			return
		end
		idle = 0
		if not sb or moved >= 300 then
			local note = moved == 0 and "Already tidy" or ("Moved %d item%s to their labels"):format(moved, moved == 1 and "" or "s")
			if (stuck or 0) > 0 then note = note .. (" · %d didn't fit"):format(stuck) end
			Finish(note)
			return
		end
		C_Container.PickupContainerItem(sb, ss)
		C_Container.PickupContainerItem(db, ds)
		moved = moved + 1
	end)
end
end part() end
-- ==================== Bags/Enable.lua
do local __addon, __ns = ... local function part()
-- Copyright (C) 2026 SoFinSicc. Part of Pathway (curseforge.com/wow/addons/pathway): free software under the GPLv3 or later, with additional terms that require keeping this credit. See LICENSE.md.
--[[ Pathway — Bags: switching the module on
     The bag module only wakes up when it's turned on in Pathway's settings
     (Modules page). Off means none of its events, frames or hooks exist. ]]

local ADDON, P = __addon, __ns
local GB = P.Bags

local OTHERS = { "Baganator", "Bagnon", "BetterBags", "AdiBags", "ArkInventory", "Inventorian", "Combuctor", "LilsGoodBags" }

function GB:OpenSettings(page) P:OpenSettings(page or "gear") end

P:Listen("READY", function()
	if not P.db.settings.bags then return end
	GB.enabled = true
	GB:EnableEvents()
	GB:Init()
	P:OnPaint(function() if GB.db and GB.ApplyTheme then GB:ApplyTheme() end end)

	-- one-time heads-up when another bag addon is running too
	C_Timer.After(6, function()
		local found
		for _, name in ipairs(OTHERS) do
			local loaded = C_AddOns and C_AddOns.IsAddOnLoaded and C_AddOns.IsAddOnLoaded(name) or IsAddOnLoaded and IsAddOnLoaded(name)
			if loaded and not GB.db.conflicts[name] then found = name; break end
		end
		if not found or GB.db.settings.takeOverBags == false then return end
		P:Ask({
			key = "bags:conflict",
			icon = "Interface\\Icons\\INV_Misc_Bag_08",
			title = found .. " also replaces your bags",
			text = "Which one should open when you press B?",
			buttons = {
				{ found, function()
					GB.db.conflicts[found] = "other"
					GB.db.settings.takeOverBags = false
					P:Toast("Reload your UI to hand the B key back")
				end },
				{ "Pathway", function() GB.db.conflicts[found] = "pathway" end, true },
			},
		})
	end)
end)
end part() end
