	["Placed by %s"] = "Gesetzt von %s",
	["Ping from %s"] = "Ping von %s",
	["Mode"] = "Modus",
	["Ping here"] = "Hier pingen",
	["Marker here"] = "Markierung hier",
	["Lock"] = "Sperren",
	["Follow me"] = "Mir folgen",
	["Minimap radar"] = "Minikarten-Radar",
	["Replace the Blizzard minimap"] = "Blizzard-Minikarte ersetzen",
	["Show players"] = "Spieler anzeigen",
	["Shape"] = "Form",
	["Round"] = "Rund",
	["Square"] = "Eckig",
	["Mouse"] = "Maus",
	["Hold Alt to use the map"] = "Alt halten, um die Karte zu benutzen",
	["Click-through"] = "Durchklickbar",
	["Inside houses"] = "In Häusern",
	["Automatic"] = "Automatisch",
	["GoodMap's floor plan"] = "GoodMap-Grundriss",
	["Blizzard minimap"] = "Blizzard-Minikarte",
	["No minimap"] = "Keine Minikarte",
	["Preset"] = "Voreinstellung",
	["Lean (best FPS)"] = "Schlank (beste FPS)",
	["Tracking..."] = "Verfolgung...",
	["Settings..."] = "Einstellungen...",
	["Hide GoodMap (Shift-M)"] = "GoodMap ausblenden (Umschalt-M)",
	["Preset applied: %s"] = "Voreinstellung übernommen: %s",
	["Settings will open after combat."] = "Die Einstellungen öffnen sich nach dem Kampf.",
	["All settings reset."] = "Alle Einstellungen zurückgesetzt.",
	["Now using the profile \"%s\"."] = "Du nutzt jetzt das Profil „%s“.",
	["Settings imported."] = "Einstellungen importiert.",
	["That isn't a GoodMap settings string."] = "Das ist kein GoodMap-Einstellungstext.",
	["Copy this text with Ctrl+C and share it:"] = "Kopiere diesen Text mit Strg+C und teile ihn:",
	["Paste GoodMap settings with Ctrl+V. They replace the settings in your current profile."] = "Füge GoodMap-Einstellungen mit Strg+V ein. Sie ersetzen die Einstellungen in deinem aktuellen Profil.",
	["Name your new profile. It starts as a copy of your current settings."] = "Gib deinem neuen Profil einen Namen. Es startet als Kopie deiner aktuellen Einstellungen.",
	["Delete the profile \"%s\"?"] = "Das Profil „%s“ löschen?",
	["Forget every saved house floor plan?"] = "Alle gespeicherten Hausgrundrisse vergessen?",
	["All house floor plans forgotten."] = "Alle Hausgrundrisse vergessen.",
	["%d house floor plans saved (%d rooms). %d new kinds of room learned."] = "%d Hausgrundrisse gespeichert (%d Räume). %d neue Raumarten gelernt.",
	["Position reset."] = "Position zurückgesetzt.",
	["Left-click: show or hide GoodMap"] = "Linksklick: GoodMap ein- oder ausblenden",
	["Top left"] = "Oben links",
	["Top"] = "Oben",
	["Top right"] = "Oben rechts",
	["Bottom left"] = "Unten links",
	["Bottom"] = "Unten",
	["Bottom right"] = "Unten rechts",
	["Show or hide"] = "Ein- oder ausblenden",
	["Toggle (Shift-M)"] = "Umschalten (Umschalt-M)",
	["Shift-M shows or hides GoodMap. While it's hidden, the Blizzard minimap is back."] = "Umschalt-M blendet GoodMap ein oder aus. Solange es ausgeblendet ist, siehst du wieder die Blizzard-Minikarte.",
	["Normal is GoodMap as you set it up. Pick what you farm (herbs, ore, lumber, fishing or void motes) and the zone's routes for it come up, and GoodMap asks in each new zone. Battleground shows the whole battleground with bigger group dots and no quest clutter."] = "Normal ist GoodMap so, wie du es eingerichtet hast. Wähle, was du farmst (Kräuter, Erz, Holz, Angeln oder Leerenpartikel), dann erscheinen die Routen der Zone dafür, und GoodMap fragt in jeder neuen Zone. Schlachtfeld zeigt das ganze Schlachtfeld mit größeren Gruppenpunkten und ohne Questsymbole.",
	["Automatic in battlegrounds"] = "Automatisch in Schlachtfeldern",
	["Switches to Battleground mode when you enter a battleground or arena, and back when you leave."] = "Wechselt in den Schlachtfeldmodus, wenn du ein Schlachtfeld oder eine Arena betrittst, und zurück, wenn du sie verlässt.",
	["Preset: Lean"] = "Voreinstellung: Schlank",
	["Best FPS"] = "Beste FPS",
	["Turns off the heavier map layers and refreshes less often."] = "Schaltet die aufwendigeren Kartenebenen ab und aktualisiert seltener.",
	["Preset: Balanced"] = "Voreinstellung: Ausgewogen",
	["Recommended"] = "Empfohlen",
	["GoodMap's defaults."] = "Die Standardwerte von GoodMap.",
	["Preset: Everything"] = "Voreinstellung: Alles",
	["Show it all"] = "Alles zeigen",
	["Every map layer on, fastest refresh."] = "Alle Kartenebenen an, schnellste Aktualisierung.",
	["Minimap replacement"] = "Ersatz für die Minikarte",
	["Hides the Blizzard minimap while GoodMap is shown. Its buttons move to GoodMap's button bar."] = "Blendet die Blizzard-Minikarte aus, solange GoodMap zu sehen ist. Ihre Knöpfe wandern in die Knopfleiste von GoodMap.",
	["Step aside for the world map"] = "Der Weltkarte Platz machen",
	["Hides GoodMap while the world map (M) is open and brings it back when you close it."] = "Blendet GoodMap aus, solange die Weltkarte (M) offen ist, und holt es zurück, sobald du sie schließt.",
	["Use the Blizzard minimap where there's no position"] = "Blizzard-Minikarte nutzen, wo es keine Position gibt",
	["Most dungeons and raids don't share your position with add-ons, so GoodMap hands over to the Blizzard minimap there."] = "In den meisten Dungeons und Schlachtzügen bekommen AddOns deine Position nicht. Dort übernimmt deshalb die Blizzard-Minikarte.",
	["Frame"] = "Fenster",
	["Lock position and size"] = "Position und Größe sperren",
	["Stops Shift-dragging and resizing the map."] = "Verhindert, dass die Karte mit Umschalt verschoben oder in der Größe geändert wird.",
	["Round looks like the Blizzard minimap. Square shows more of the map."] = "Rund sieht aus wie die Blizzard-Minikarte. Eckig zeigt mehr von der Karte.",
	["Size"] = "Größe",
	["How wide the round map is. You can also drag the grip in the bottom-right corner (hover the map)."] = "Wie breit die runde Karte ist. Du kannst auch am Griff in der unteren rechten Ecke ziehen (mit der Maus über die Karte fahren).",
	["Width"] = "Breite",
	["You can also drag the grip in the bottom-right corner (hover the map)."] = "Du kannst auch am Griff in der unteren rechten Ecke ziehen (mit der Maus über die Karte fahren).",
	["Height"] = "Höhe",
	["Scale"] = "Skalierung",
	["Frame strata"] = "Fensterebene",
	["Which layer of the screen the map is drawn on."] = "Auf welcher Bildschirmebene die Karte gezeichnet wird.",
	["Background"] = "Hintergrund",
	["Low"] = "Niedrig",
	["Medium"] = "Mittel",
	["High"] = "Hoch",
	["Map opacity"] = "Deckkraft der Karte",
	["How solid the map artwork looks."] = "Wie deckend das Kartenbild aussieht.",
	["Full opacity on mouseover"] = "Volle Deckkraft bei Mauskontakt",
	["Shows the artwork fully while your mouse is over the map."] = "Zeigt das Kartenbild voll an, solange deine Maus über der Karte ist.",
	["Opacity when idle"] = "Deckkraft im Leerlauf",
	["Fades the whole map, icons included, while your mouse is somewhere else."] = "Blendet die ganze Karte samt Symbolen ab, solange deine Maus woanders ist.",
	["Opacity in combat"] = "Deckkraft im Kampf",
	["Click-through lets you click the world under the map."] = "Durchklickbar heißt: Du klickst durch die Karte hindurch auf die Spielwelt.",
	["Look"] = "Aussehen",
	["Border"] = "Rahmen",
	["Thin line"] = "Dünne Linie",
	["Class color"] = "Klassenfarbe",
	["None"] = "Keiner",
	["Border color"] = "Rahmenfarbe",
	["Border thickness"] = "Rahmenstärke",
	["Hide close button"] = "Schließen-Knopf ausblenden",
	["Only applies to the Blizzard border."] = "Gilt nur für den Blizzard-Rahmen.",
	["Hide the tab"] = "Reiter ausblenden",
	["The GoodMap button in the bar, Ctrl + right-click and /goodmap open the menu."] = "Das Menü öffnest du über den GoodMap-Knopf in der Leiste, mit Strg + Rechtsklick oder mit /goodmap.",
	["Compass letters"] = "Kompassbuchstaben",
	["N, E, S and W just inside the round map's edge."] = "N, O, S und W direkt innen am Rand der runden Karte.",
	["Facing glow"] = "Blickrichtungsschein",
	["A soft glow slides around the round map's ring to show which way you're facing, as you turn."] = "Ein sanfter Schein gleitet beim Drehen um den Ring der runden Karte und zeigt, wohin du schaust.",
	["Glow color"] = "Farbe des Scheins",
	["GoodMap green"] = "GoodMap-Grün",
	["White"] = "Weiß",
	["Blue"] = "Blau",
	["Cyan"] = "Türkis",
	["Purple"] = "Lila",
	["Pink"] = "Rosa",
	["Red"] = "Rot",
	["Custom"] = "Eigene",
	["Custom glow color"] = "Eigene Farbe des Scheins",
	["Visibility"] = "Sichtbarkeit",
	["Always show in battlegrounds and arenas"] = "Auf Schlachtfeldern und in Arenen immer zeigen",
	["Hide in dungeons, raids and delves"] = "In Dungeons, Schlachtzügen und Tiefen ausblenden",
	["Hide in combat"] = "Im Kampf ausblenden",
	["Calmer in combat"] = "Ruhiger im Kampf",
	["While you're fighting, the button bar and the map text fade out. They come back when combat ends, or when you hover the map."] = "Während du kämpfst, blenden sich die Knopfleiste und der Kartentext aus. Sie kommen zurück, sobald der Kampf vorbei ist oder du mit der Maus über die Karte fährst.",
	["Reset"] = "Zurücksetzen",
	["Reset position"] = "Position zurücksetzen",
	["Moves GoodMap back to the minimap's corner."] = "Setzt GoodMap zurück in die Ecke der Minikarte.",
	["Reset all settings"] = "Alle Einstellungen zurücksetzen",
	["Puts every GoodMap setting in this profile back to default."] = "Setzt alle GoodMap-Einstellungen in diesem Profil auf Standard zurück.",
	["Movement"] = "Bewegung",
	["Keeps you in the middle of the map while you move."] = "Hält dich beim Laufen in der Mitte der Karte.",
	["Follow dead zone"] = "Spielraum beim Folgen",
	["How far you can move from the middle before the map catches up. 0% keeps you exactly in the middle; higher values move the map less often."] = "Wie weit du dich von der Mitte entfernen kannst, bevor die Karte nachzieht. Bei 0 % bleibst du genau in der Mitte, höhere Werte bewegen die Karte seltener.",
	["Resume after"] = "Weiter folgen nach",
	["Seconds after your mouse leaves the map before it follows you again."] = "Sekunden, nachdem deine Maus die Karte verlässt, bis sie dir wieder folgt.",
	["Return to your zone"] = "Zurück zu deiner Zone",
	["After you look at another map, jump back to your zone once you stop using the map."] = "Wenn du dir eine andere Karte angesehen hast, springt GoodMap zu deiner Zone zurück, sobald du die Karte nicht mehr benutzt.",
	["Click to open sub-zones"] = "Klick öffnet Unterzonen",
	["Left-click a sub-zone to open it, right-click to go up a level."] = "Linksklick auf eine Unterzone öffnet sie, Rechtsklick geht eine Ebene hoch.",
	["Extra zoom levels"] = "Zusätzliche Zoomstufen",
	["How far past Blizzard's closest zoom you can go, 25% closer each step. At 20 you can get over 80 times closer."] = "Wie weit du über Blizzards nächste Zoomstufe hinaus heranzoomen kannst, jede Stufe 25 % näher. Bei 20 kommst du über 80-mal näher heran.",
	["Learn your usual zoom"] = "Deinen üblichen Zoom lernen",
	["GoodMap learns how far out you usually look, and goes back to it when you move to another zone or into a city. In between, zoom as close or as far as you like."] = "GoodMap lernt, wie weit du meistens herausgezoomt schaust, und kehrt dorthin zurück, wenn du in eine andere Zone oder eine Stadt kommst. Dazwischen zoomst du so nah oder so weit, wie du willst.",
	["Usual zoom"] = "Üblicher Zoom",
	["Forget my usual zoom"] = "Meinen üblichen Zoom vergessen",
	["GoodMap will learn your usual zoom again from now on."] = "GoodMap lernt deinen üblichen Zoom ab jetzt neu.",
	["Starts learning your usual zoom from scratch."] = "Lernt deinen üblichen Zoom ganz von vorn.",
	["Zoom out while flying"] = "Beim Fliegen herauszoomen",
	["Zoom levels to step out while flying, skyriding or on a flight path. It zooms back in after you land. 0 turns it off."] = "So viele Stufen zoomt GoodMap heraus, wenn du fliegst, himmelsreitest oder einen Flugpunkt nutzt. Nach der Landung zoomt es wieder herein. 0 schaltet es ab.",
	["Zoom in when resting"] = "Beim Ausruhen hineinzoomen",
	["Zoom levels to step in while you're in a city or an inn. It zooms back out when you leave. 0 turns it off."] = "So viele Stufen zoomt GoodMap herein, wenn du in einer Stadt oder einem Gasthaus bist. Beim Verlassen zoomt es wieder heraus. 0 schaltet es ab.",
	["Smooth zoom"] = "Weiches Zoomen",
	["Glides between zoom levels instead of jumping."] = "Gleitet von Zoomstufe zu Zoomstufe, statt zu springen.",
	["Zoom buttons on mouseover"] = "Zoomknöpfe bei Mauskontakt",
	["Minimap zoom keys zoom GoodMap"] = "Minikarten-Zoomtasten zoomen GoodMap",
	["Your Minimap Zoom In and Zoom Out key bindings also zoom GoodMap."] = "Deine Tasten für Minikarte hinein- und herauszoomen zoomen auch GoodMap.",
	["Peek"] = "Kurzer Blick",
	["Peek key"] = "Taste für den kurzen Blick",
	["Use %s"] = "%s nutzen",
	["Hold the peek key to make GoodMap bigger and zoomed out. Let go and it snaps back. %s is the default. You can pick any key above or under %s."] = "Halte die Taste gedrückt, dann wird GoodMap größer und zoomt heraus. Lässt du los, springt es zurück. Standard ist %s. Du kannst oben oder unter %s jede beliebige Taste wählen.",
	["How much bigger GoodMap gets while you hold the peek key."] = "Wie viel größer GoodMap wird, solange du die Taste hältst.",
	["How far out GoodMap zooms while you hold the peek key, from where you are to the whole zone."] = "Wie weit GoodMap herauszoomt, solange du die Taste hältst: von dort, wo du bist, bis zur ganzen Zone.",
	["Zone name"] = "Zonenname",
	["The sub-zone name, colored by PvP status. While you look at another map, it shows that map's name. In a house, it shows the room you're in."] = "Der Name der Unterzone, eingefärbt nach PvP-Status. Schaust du dir eine andere Karte an, steht dort deren Name. In einem Haus steht dort der Raum, in dem du bist.",
	["Zone name position"] = "Position des Zonennamens",
	["Zone name size"] = "Größe des Zonennamens",
	["Left-click for the stopwatch and alarm, right-click for the calendar. It follows the game's 24-hour and local time options."] = "Linksklick für Stoppuhr und Wecker, Rechtsklick für den Kalender. Die Uhr richtet sich nach den 24-Stunden- und Ortszeit-Optionen des Spiels.",
	["Player coordinates"] = "Spielerkoordinaten",
	["Click to center the map on you, Shift-click to share your location in chat."] = "Klick zentriert die Karte auf dich, Umschalt-Klick teilt deine Position im Chat.",
	["Cursor coordinates"] = "Mauszeiger-Koordinaten",
	["Shown while your mouse is over the map."] = "Erscheinen, solange deine Maus über der Karte ist.",
	["Coordinate decimals"] = "Nachkommastellen",
	["Text size"] = "Textgröße",
	["Coordinates, clock and distance."] = "Koordinaten, Uhr und Entfernung.",
	["Shade behind text"] = "Schatten hinter dem Text",
	["A soft dark strip behind the zone name, clock and coordinates, so they're easy to read on any map."] = "Ein weicher dunkler Streifen hinter Zonenname, Uhr und Koordinaten, damit sie auf jeder Karte gut lesbar sind.",
	["Flight info"] = "Fluginfo",
	["On a flight path, shows where you're going under the zone name, and how long is left once GoodMap knows the route. It learns each route the first time you fly it."] = "Zeigt auf einer Flugroute unter dem Zonennamen, wohin du fliegst, und wie lange es noch dauert, sobald GoodMap die Route kennt. Es lernt jede Route beim ersten Flug.",
	["Frame rate, latency and your lowest durability, next to the coordinates."] = "Bildrate, Latenz und deine niedrigste Haltbarkeit, neben den Koordinaten.",
	["On days with a holiday or world event, a small button pops up on the left of the map. Hover it for details, click for the calendar, right-click to hide it for a day, a week, a month or for good."] = "An Tagen mit einem Feiertag oder Weltevent erscheint links an der Karte ein kleiner Knopf. Zeig mit der Maus darauf für Details, klick für den Kalender, Rechtsklick blendet ihn für einen Tag, eine Woche, einen Monat oder ganz aus.",
	["Waypoints"] = "Wegpunkte",
	["Edge arrow for your tracked target"] = "Randpfeil zu deinem verfolgten Ziel",
	["When the quest or map pin you're tracking is outside the view, an arrow on the map's edge points to it."] = "Liegt die verfolgte Quest oder Kartenmarkierung außerhalb der Ansicht, zeigt ein Pfeil am Kartenrand dorthin.",
	["Show distance"] = "Entfernung anzeigen",
	["Show time to arrive"] = "Ankunftszeit anzeigen",
	["Worked out from how fast you've been getting closer."] = "Berechnet daraus, wie schnell du näher kommst.",
	["Zoom out to fit your target"] = "Herauszoomen, bis dein Ziel zu sehen ist",
	["When your tracked target is just outside the view, GoodMap zooms out up to three steps to show it, and back in as you get close."] = "Liegt dein verfolgtes Ziel knapp außerhalb der Ansicht, zoomt GoodMap bis zu drei Stufen heraus, um es zu zeigen, und wieder hinein, wenn du näher kommst.",
	["Corpse arrow"] = "Pfeil zum Leichnam",
	["After you die, an arrow on the map's edge points to your corpse, with the distance."] = "Nach deinem Tod zeigt ein Pfeil am Kartenrand zu deinem Leichnam, mit Entfernung.",
	["Flight mode"] = "Flugmodus",
	["On a flight path, GoodMap shows your whole route, how long is left and when you'll land. It learns each route's time, and estimates new ones from the distance."] = "Auf einer Flugroute zeigt GoodMap die ganze Route, wie lange es noch dauert und wann du landest. Es lernt die Flugzeit jeder Route und schätzt neue anhand der Entfernung.",
	["Show the whole route"] = "Die ganze Route zeigen",
	["Zooms out to fit the whole flight, and back to your usual zoom when you land."] = "Zoomt heraus, bis der ganze Flug passt, und nach der Landung zurück auf deinen üblichen Zoom.",
	["Progress ring"] = "Fortschrittsring",
	["The round map's edge fills up as you fly. On a square map, a bar along the bottom does."] = "Der Rand der runden Karte füllt sich, während du fliegst. Auf einer eckigen Karte tut das ein Balken am unteren Rand.",
	["Hide quests while flying"] = "Quests beim Fliegen ausblenden",
	["Quests, world quests and other map icons step aside while you fly, so the route stands out. Your tracked target stays."] = "Quests, Weltquests und andere Kartensymbole treten beim Fliegen zur Seite, damit die Route hervorsticht. Dein verfolgtes Ziel bleibt.",
	["Landing chime"] = "Landeton",
	["A soft sound 10 seconds before you land."] = "Ein leiser Ton 10 Sekunden vor der Landung.",
	["Offer routes when you gather"] = "Routen beim Sammeln anbieten",
	["The first time you gather a herb, ore or lumber in a zone, GoodMap shows that zone's farming routes."] = "Wenn du in einer Zone zum ersten Mal ein Kraut, Erz oder Holz sammelst, zeigt GoodMap die Farmrouten dieser Zone.",
	["Ask when you fish a pool"] = "Fragen, wenn du in einem Schwarm angelst",
	["When you fish from a pool, GoodMap asks once per zone whether you'd like a route from pool to pool. Fishing anywhere else is left alone."] = "Wenn du in einem Fischschwarm angelst, fragt GoodMap einmal pro Zone, ob du eine Route von Schwarm zu Schwarm möchtest. Überall sonst angelst du ungestört.",
	["Draws the route on the map, with lights running ahead of you to the next spot."] = "Zeichnet die Route auf die Karte, mit Lichtern, die dir zum nächsten Fundort vorauslaufen.",
	["Puts your map pin on the next spot, so the game's arrow and distance lead you there. It replaces your own map pin while you follow a route."] = "Setzt deine Kartenmarkierung auf den nächsten Fundort, damit dich der Pfeil und die Entfernung des Spiels dorthin führen. Solange du einer Route folgst, ersetzt sie deine eigene Kartenmarkierung.",
	["Hide quests while farming"] = "Quests beim Farmen ausblenden",
	["Quests and world quests step aside while you follow a route. Your tracked target stays."] = "Quests und Weltquests treten zur Seite, solange du einer Route folgst. Dein verfolgtes Ziel bleibt.",
	["Remember spots you gather"] = "Gesammelte Fundorte merken",
	["GoodMap keeps the spots you gather, for a route through your own spots."] = "GoodMap merkt sich die Stellen, an denen du sammelst, für eine Route durch deine eigenen Fundorte.",
	["Open farming routes"] = "Farmrouten öffnen",
	["Routes for the zone you're in. Also /goodmap routes."] = "Routen für die Zone, in der du bist. Auch mit /goodmap routes.",
	["Your spots"] = "Deine Fundorte",
	["Forget my spots"] = "Meine Fundorte vergessen",
	["Your gathered spots were forgotten."] = "Deine gesammelten Fundorte wurden vergessen.",
	["Forgets every spot you've gathered, in every zone."] = "Vergisst alle Fundorte, an denen du gesammelt hast, in allen Zonen.",
	["Icons"] = "Symbole",
	["Icon scale"] = "Symbolgröße",
	["Size of map icons. Blizzard's default for the zone map is 60%."] = "Größe der Kartensymbole. Blizzards Standard für die Zonenkarte ist 60 %.",
	["Player arrow"] = "Spielerpfeil",
	["Blizzard's own arrow, or one of GoodMap's in the color you pick."] = "Blizzards eigener Pfeil oder einer von GoodMap in der Farbe deiner Wahl.",
	["Classic"] = "Klassisch",
	["Dart"] = "Spitze",
	["Chevron"] = "Winkel",
	["Triangle"] = "Dreieck",
	["Compass needle"] = "Kompassnadel",
	["Dot and beam"] = "Punkt und Strahl",
	["Arrow color"] = "Pfeilfarbe",
	["Gold on the classic arrow is its own color."] = "Gold ist beim klassischen Pfeil seine eigene Farbe.",
	["Custom arrow color"] = "Eigene Pfeilfarbe",
	["Player arrow size"] = "Größe des Spielerpfeils",
	["Blizzard's default: 12."] = "Blizzard-Standard: 12.",
	["Party and raid dot size"] = "Größe der Gruppen- und Schlachtzugspunkte",
	["Blizzard's default: 8."] = "Blizzard-Standard: 8.",
	["Icon sizes by type"] = "Symbolgrößen nach Art",
	["Quest objectives, world quests and bonus objectives."] = "Questziele, Weltquests und Bonusziele.",
	["Rares and treasures"] = "Seltene Gegner und Schätze",
	["Travel"] = "Reisen",
	["Flight points, portals, and dungeon and delve entrances."] = "Flugpunkte, Portale sowie Dungeon- und Tiefeneingänge.",
	["Add-on icons"] = "AddOn-Symbole",
	["HandyNotes, RareScanner, GatherMate2 and other add-ons' map pins."] = "Kartenmarkierungen von HandyNotes, RareScanner, GatherMate2 und anderen AddOns.",
	["Dark outline"] = "Dunkler Rand",
	["A soft dark circle behind icons, so they stand out on busy map art."] = "Ein weicher dunkler Kreis hinter Symbolen, damit sie sich von unruhiger Kartengrafik abheben.",
	["Extra layers from the world map"] = "Zusätzliche Ebenen von der Weltkarte",
	["Your active quest objectives and quest areas."] = "Deine aktiven Questziele und Questgebiete.",
	["Available quests"] = "Verfügbare Quests",
	["Quest givers you haven't talked to yet."] = "Questgeber, mit denen du noch nicht gesprochen hast.",
	["World quests"] = "Weltquests",
	["World quest refresh"] = "Aktualisierung der Weltquests",
	["Blizzard refreshes every 0.5 s; a calmer rate saves CPU."] = "Blizzard aktualisiert alle 0,5 s. Seltener schont die CPU.",
	["Bonus objectives"] = "Bonusziele",
	["Delves"] = "Tiefen",
	["Tracking and waypoints"] = "Verfolgung und Wegpunkte",
	["Collectibles you track, your map pin and the waypoint you're following. Ctrl-click places a map pin."] = "Sammelobjekte, die du verfolgst, deine Kartenmarkierung und der Wegpunkt, dem du folgst. Strg-Klick setzt eine Kartenmarkierung.",
	["Skyriding races"] = "Himmelsreiten-Rennen",
	["Invasions and contributions"] = "Invasionen und Beiträge",
	["Housing neighborhoods"] = "Nachbarschaften",
	["Plots in your neighborhood: yours, your friends' and the free ones."] = "Grundstücke in deiner Nachbarschaft: deins, die deiner Freunde und die freien.",
	["Built-in layers (turn off to save work)"] = "Eingebaute Ebenen (abschalten spart Rechenzeit)",
	["Points of interest and events"] = "Interessante Orte und Ereignisse",
	["Flight points"] = "Flugpunkte",
	["Dungeon and raid entrances"] = "Dungeon- und Schlachtzugseingänge",
	["Boss icons"] = "Bosssymbole",
	["Pet tamers"] = "Haustierzähmer",
	["Dig sites"] = "Grabungsstätten",
	["Area labels on hover"] = "Gebietsnamen bei Mauskontakt",
	["Sub-zone names when you hover the map."] = "Namen der Unterzonen, wenn du mit der Maus über die Karte fährst.",
	["Area label size"] = "Größe der Gebietsnamen",
	["Add-ons"] = "AddOns",
	["Show HandyNotes icons (if installed)."] = "HandyNotes-Symbole anzeigen (falls installiert).",
	["Show RareScanner icons (if installed)."] = "RareScanner-Symbole anzeigen (falls installiert).",
	["Show GatherMate2 nodes (if installed)."] = "GatherMate2-Vorkommen anzeigen (falls installiert).",
	["Other add-ons' map pins"] = "Kartenmarkierungen anderer AddOns",
	["Pins other add-ons put on the world map, like TomTom waypoints."] = "Markierungen, die andere AddOns auf die Weltkarte setzen, zum Beispiel TomTom-Wegpunkte.",
	["TomTom: Alt + right-click"] = "TomTom: Alt + Rechtsklick",
	["Alt + right-click the map to add a TomTom waypoint (if installed)."] = "Alt + Rechtsklick auf die Karte setzt einen TomTom-Wegpunkt (falls installiert).",
	["Unexplored areas"] = "Unerkundete Gebiete",
	["Show unexplored areas"] = "Unerkundete Gebiete zeigen",
	["Draws the parts of each zone you haven't explored yet. The map art comes with GoodMap (GoodMap_Reveal) and only loads when this is on."] = "Zeichnet die Teile jeder Zone, die du noch nicht erkundet hast. Die Kartengrafiken kommen mit GoodMap (GoodMap_Reveal) und werden nur geladen, wenn das an ist.",
	["Tint unexplored areas"] = "Unerkundete Gebiete einfärben",
	["A cool tint, so you can still tell what you haven't explored."] = "Ein kühler Farbton, damit du trotzdem siehst, was du noch nicht erkundet hast.",
	["Minimap"] = "Minikarte",
	["Radar: the minimap inside GoodMap"] = "Radar: die Minikarte in GoodMap",
	["Embed the minimap"] = "Minikarte einbetten",
	["The real minimap moves into GoodMap, centered on you, so gathering nodes, tracking and other minimap icons show up on the map. It always stays inside GoodMap's window."] = "Die echte Minikarte wandert in GoodMap und bleibt auf dich zentriert. So erscheinen Sammelvorkommen, Verfolgung und andere Minikarten-Symbole direkt auf der Karte. Sie bleibt immer innerhalb des GoodMap-Fensters.",
	["Radar style"] = "Radar-Stil",
	["Aligned: no terrain, and the icons sit exactly where they are on the map (it grows as you zoom). Fixed: a round minimap of a set size."] = "Ausgerichtet: ohne Gelände, die Symbole sitzen genau dort, wo sie auf der Karte sind (wächst beim Zoomen). Fest: eine runde Minikarte in fester Größe.",
	["Aligned to map"] = "An der Karte ausgerichtet",
	["Fixed size"] = "Feste Größe",
	["Auto-zoom the minimap"] = "Minikarte automatisch zoomen",
	["Picks a minimap zoom whose range fits inside GoodMap."] = "Wählt einen Minikarten-Zoom, dessen Reichweite in GoodMap passt.",
	["Radar size"] = "Radargröße",
	["Show minimap terrain"] = "Gelände der Minikarte zeigen",
	["Terrain opacity"] = "Deckkraft des Geländes",
	["Minimap icon size"] = "Größe der Minikarten-Symbole",
	["Size of minimap icons like gathering nodes and tracking."] = "Größe von Minikarten-Symbolen wie Sammelvorkommen und Verfolgung.",
	["Interactive radar"] = "Bedienbares Radar",
	["Lets the radar take clicks and the mouse wheel. When off, clicks go to the map. Hovering a node shows what it is either way."] = "Das Radar nimmt Klicks und das Mausrad an. Ist es aus, gehen Klicks an die Karte. Mit der Maus über einem Vorkommen siehst du so oder so, was es ist.",
	["Hide GoodMap's player arrow"] = "GoodMap-Spielerpfeil ausblenden",
	["Uses the minimap's own arrow instead while the radar is showing."] = "Nutzt stattdessen den Pfeil der Minikarte, solange das Radar zu sehen ist.",
	["Show the radar in cities and inns"] = "Radar in Städten und Gasthäusern zeigen",
	["In cities the minimap can show a gray square where its terrain would be. When this is off, the radar sits out while you're resting."] = "In Städten kann die Minikarte ein graues Quadrat zeigen, wo ihr Gelände wäre. Ist das aus, pausiert das Radar, während du dich ausruhst.",
	["Show the radar indoors"] = "Radar drinnen zeigen",
	["In caves and buildings."] = "In Höhlen und Gebäuden.",
	["Button bar"] = "Knopfleiste",
	["Puts minimap buttons in a bar next to GoodMap."] = "Legt die Minikarten-Knöpfe in eine Leiste neben GoodMap.",
	["Off"] = "Aus",
	["When the Blizzard minimap is hidden"] = "Wenn die Blizzard-Minikarte ausgeblendet ist",
	["Always"] = "Immer",
	["GoodMap button"] = "GoodMap-Knopf",
	["Click for the menu, right-click for settings."] = "Klick für das Menü, Rechtsklick für die Einstellungen.",
	["Blizzard buttons"] = "Blizzard-Knöpfe",
	["Tracking, calendar, mail, add-on compartment and expansion summary."] = "Verfolgung, Kalender, Post, AddOn-Fach und Erweiterungsübersicht.",
	["Other add-on buttons"] = "Knöpfe anderer AddOns",
	["Also docks the minimap buttons some add-ons make on their own, so they don't float over the map."] = "Holt auch die Minikarten-Knöpfe in die Leiste, die manche AddOns selbst erstellen, damit sie nicht über der Karte schweben.",
	["Bar position"] = "Position der Leiste",
	["Below the map"] = "Unter der Karte",
	["Above the map"] = "Über der Karte",
	["Left of the map"] = "Links neben der Karte",
	["Right of the map"] = "Rechts neben der Karte",
	["Button size"] = "Knopfgröße",
	["Button spacing"] = "Knopfabstand",
	["Show only on mouseover"] = "Nur bei Mauskontakt zeigen",
	["Instance difficulty"] = "Schwierigkeitsgrad der Instanz",
	["Show instance difficulty"] = "Schwierigkeitsgrad anzeigen",
	["Shows the dungeon or raid difficulty on GoodMap while the Blizzard minimap is hidden."] = "Zeigt den Schwierigkeitsgrad von Dungeon oder Schlachtzug auf GoodMap, solange die Blizzard-Minikarte ausgeblendet ist.",
	["Difficulty position"] = "Position des Schwierigkeitsgrads",
	["Group"] = "Gruppe",
	["Pings and markers"] = "Pings und Markierungen",
	["Show group pings"] = "Gruppenpings zeigen",
	["Pings from party and raid members who use GoodMap."] = "Pings von Gruppen- und Schlachtzugsmitgliedern, die GoodMap benutzen.",
	["Show group members' pings in the world"] = "Pings der Gruppe in der Welt zeigen",
	["A group member's ping becomes your map pin, so you see it in the world with the distance to it. It replaces your own map pin."] = "Der Ping eines Gruppenmitglieds wird zu deiner Kartenmarkierung. So siehst du ihn in der Welt, mit der Entfernung. Er ersetzt deine eigene Kartenmarkierung.",
	["Double-click to ping"] = "Doppelklick zum Pingen",
	["Double-click the map to ping that spot for your group."] = "Doppelklicke auf die Karte, um die Stelle für deine Gruppe anzupingen.",
	["Double right-click for a raid marker"] = "Doppelter Rechtsklick für eine Schlachtzugsmarkierung",
	["Double right-click the map to drop a raid marker: the red X unless you pick another below. Once a marker is down, a double right-click asks which one you want."] = "Ein doppelter Rechtsklick auf die Karte setzt eine Schlachtzugsmarkierung: das rote X, außer du wählst unten eine andere. Liegt schon eine Markierung, fragt ein doppelter Rechtsklick, welche du willst.",
	["Put your pings and markers in the world"] = "Deine Pings und Markierungen in der Welt zeigen",
	["Your ping or marker also becomes your map pin, so it shows in the world with the distance to it. The game allows one map pin, so each new one replaces the last. Map pins don't work in dungeons, raids and battlegrounds."] = "Dein Ping oder deine Markierung wird auch zu deiner Kartenmarkierung und erscheint so in der Welt, mit der Entfernung. Das Spiel erlaubt eine Kartenmarkierung, jede neue ersetzt also die letzte. In Dungeons, Schlachtzügen und Schlachtfeldern gehen Kartenmarkierungen nicht.",
	["Share in chat"] = "Im Chat teilen",
	["Also posts a map pin link in your group's chat, or in /say when you're not in a group. Players without GoodMap can click it to see the spot on their map and in the world."] = "Postet auch einen Link zur Kartenmarkierung im Gruppenchat, oder in /sagen, wenn du in keiner Gruppe bist. Spieler ohne GoodMap können ihn anklicken und sehen die Stelle auf ihrer Karte und in der Welt.",
	["The mark key places"] = "Die Markiertaste setzt",
	["Hold the mark key and click the map. Everyone in your group who uses GoodMap sees it. Add-ons can't put markers in the world itself, so they show on the map."] = "Halte die Markiertaste und klick auf die Karte. Alle in deiner Gruppe, die GoodMap benutzen, sehen es. AddOns können keine Markierungen in die Welt selbst setzen, deshalb erscheinen sie auf der Karte.",
	["A ping"] = "Einen Ping",
	["A raid marker"] = "Eine Schlachtzugsmarkierung",
	["A ping and a raid marker"] = "Einen Ping und eine Schlachtzugsmarkierung",
	["Raid marker"] = "Schlachtzugsmarkierung",
	["The marker that double right-click and the mark key put down first."] = "Die Markierung, die ein doppelter Rechtsklick und die Markiertaste zuerst setzen.",
	["Markers"] = "Markierungen",
	["Removes the markers on the map for everyone in your group. In a raid, only the leader and assistants can."] = "Entfernt die Markierungen auf der Karte für alle in deiner Gruppe. Im Schlachtzug können das nur Leiter und Assistenten.",
	["Houses"] = "Häuser",
	["Automatic uses GoodMap's floor plan, or the Blizzard minimap if another house map add-on (Chamberlain, HouseMinimap) is installed. No minimap hides both."] = "Automatisch nutzt den GoodMap-Grundriss, oder die Blizzard-Minikarte, wenn ein anderes Hauskarten-AddOn (Chamberlain, HouseMinimap) installiert ist. Keine Minikarte blendet beides aus.",
	["Complete rooms"] = "Räume vervollständigen",
	["Once GoodMap knows a room's size and where its door is, it draws the whole room instead of just where you've walked."] = "Sobald GoodMap die Größe eines Raums und seine Tür kennt, zeichnet es den ganzen Raum und nicht nur die Stellen, an denen du warst.",
	["Room names"] = "Raumnamen",
	["Shows each room's name in the middle of the room."] = "Zeigt den Namen jedes Raums in seiner Mitte.",
	["Show your group"] = "Deine Gruppe zeigen",
	["Party and raid members in the house, as class-colored dots."] = "Gruppen- und Schlachtzugsmitglieder im Haus als Punkte in Klassenfarbe.",
	["House zoom"] = "Zoom im Haus",
	["How big rooms look. You can also use the mouse wheel over the map."] = "Wie groß Räume aussehen. Du kannst auch das Mausrad über der Karte benutzen.",
	["Saved floor plans"] = "Gespeicherte Grundrisse",
	["This house"] = "Dieses Haus",
	["Forget this house"] = "Dieses Haus vergessen",
	["This house's floor plan was forgotten."] = "Der Grundriss dieses Hauses wurde vergessen.",
	["Go inside a house first."] = "Geh zuerst in ein Haus.",
	["Clears the floor plan of the house you're in so GoodMap draws it again from scratch."] = "Löscht den Grundriss des Hauses, in dem du bist, damit GoodMap ihn ganz neu zeichnet.",
	["Every house"] = "Alle Häuser",
	["Forget all houses"] = "Alle Häuser vergessen",
	["Clears every saved floor plan."] = "Löscht alle gespeicherten Grundrisse.",
	["Profiles"] = "Profile",
	["Profile"] = "Profil",
	["Default"] = "Standard",
	["Every character uses the Default profile unless you pick another one."] = "Jeder Charakter nutzt das Profil „Standard“, solange du kein anderes wählst.",
	["Use a profile just for this character"] = "Eigenes Profil für diesen Charakter",
	["Starts as a copy of your current settings."] = "Startet als Kopie deiner aktuellen Einstellungen.",
	["New profile"] = "Neues Profil",
	["New profile..."] = "Neues Profil...",
	["Saves your current settings as a new profile and switches to it."] = "Speichert deine aktuellen Einstellungen als neues Profil und wechselt dorthin.",
	["Delete profile"] = "Profil löschen",
	["Delete this profile"] = "Dieses Profil löschen",
	["The Default profile can't be deleted."] = "Das Profil „Standard“ kann nicht gelöscht werden.",
	["Deletes the profile you're using and switches back to Default."] = "Löscht das Profil, das du gerade nutzt, und wechselt zurück zu „Standard“.",
	["Share settings"] = "Einstellungen teilen",
	["Export"] = "Exportieren",
	["Export settings..."] = "Einstellungen exportieren...",
	["Turns your settings into a short text you can share. Position and zoom aren't included."] = "Macht aus deinen Einstellungen einen kurzen Text zum Teilen. Position und Zoom sind nicht dabei.",
	["Import"] = "Importieren",
	["Import settings..."] = "Einstellungen importieren...",
	["Paste settings someone shared with you."] = "Füge Einstellungen ein, die jemand mit dir geteilt hat.",
	["%s is now your minimap. Shift-M hides or shows it, M opens the world map as usual, and /goodmap opens settings."] = "%s ist jetzt deine Minikarte. Umschalt-M blendet sie ein oder aus, M öffnet wie gewohnt die Weltkarte und /goodmap die Einstellungen.",
	["%s is turned on too and changes the same map. Turn it off. GoodMap stays inactive until then."] = "%s ist auch aktiv und verändert dieselbe Karte. Schalte es ab. Bis dahin bleibt GoodMap inaktiv.",
	["Blizzard's zone map isn't available."] = "Blizzards Zonenkarte ist nicht verfügbar.",
}
