	["Tracking..."] = "Suivi...",
	["Settings..."] = "Options...",
	["Hide GoodMap (Shift-M)"] = "Masquer GoodMap (Maj-M)",
	["Preset applied: %s"] = "Préréglage appliqué : %s",
	["Settings will open after combat."] = "Les options s’ouvriront après le combat.",
	["All settings reset."] = "Toutes les options ont été réinitialisées.",
	["Now using the profile \"%s\"."] = "Profil « %s » utilisé.",
	["Settings imported."] = "Options importées.",
	["That isn't a GoodMap settings string."] = "Ce n’est pas un texte d’options GoodMap.",
	["Copy this text with Ctrl+C and share it:"] = "Copiez ce texte avec Ctrl+C et partagez-le :",
	["Paste GoodMap settings with Ctrl+V. They replace the settings in your current profile."] = "Collez des options GoodMap avec Ctrl+V. Elles remplacent celles de votre profil actuel.",
	["Name your new profile. It starts as a copy of your current settings."] = "Donnez un nom à votre nouveau profil. Il reprend vos options actuelles.",
	["Delete the profile \"%s\"?"] = "Supprimer le profil « %s » ?",
	["Forget every saved house floor plan?"] = "Oublier tous les plans de maison enregistrés ?",
	["All house floor plans forgotten."] = "Tous les plans de maison ont été oubliés.",
	["%d house floor plans saved (%d rooms). %d new kinds of room learned."] = "%d plans de maison enregistrés (%d pièces). %d nouveaux types de pièce appris.",
	["Position reset."] = "Position réinitialisée.",
	["Left-click: show or hide GoodMap"] = "Clic gauche : afficher ou masquer GoodMap",
	["Top left"] = "En haut à gauche",
	["Top"] = "En haut",
	["Top right"] = "En haut à droite",
	["Bottom left"] = "En bas à gauche",
	["Bottom"] = "En bas",
	["Bottom right"] = "En bas à droite",
	["Show or hide"] = "Afficher ou masquer",
	["Toggle (Shift-M)"] = "Basculer (Maj-M)",
	["Shift-M shows or hides GoodMap. While it's hidden, the Blizzard minimap is back."] = "Maj-M affiche ou masque GoodMap. Quand il est masqué, la minicarte de Blizzard revient.",
	["Normal is GoodMap as you set it up. Pick what you farm (herbs, ore, lumber, fishing or void motes) and the zone's routes for it come up, and GoodMap asks in each new zone. Battleground shows the whole battleground with bigger group dots and no quest clutter."] = "Normal, c’est GoodMap tel que vous l’avez réglé. Choisissez ce que vous farmez (plantes, minerai, bois, pêche ou particules du Vide) et les routes de la zone s’affichent, puis GoodMap vous demande dans chaque nouvelle zone. Champ de bataille affiche tout le champ de bataille avec des points de groupe plus grands et sans icônes de quête.",
	["Automatic in battlegrounds"] = "Automatique en champ de bataille",
	["Switches to Battleground mode when you enter a battleground or arena, and back when you leave."] = "Passe en mode champ de bataille quand vous entrez dans un champ de bataille ou une arène, et revient en arrière quand vous en sortez.",
	["Preset: Lean"] = "Préréglage : Léger",
	["Best FPS"] = "Meilleurs FPS",
	["Turns off the heavier map layers and refreshes less often."] = "Désactive les couches les plus lourdes et rafraîchit moins souvent.",
	["Preset: Balanced"] = "Préréglage : Équilibré",
	["Recommended"] = "Recommandé",
	["GoodMap's defaults."] = "Les réglages par défaut de GoodMap.",
	["Preset: Everything"] = "Préréglage : Tout",
	["Show it all"] = "Tout afficher",
	["Every map layer on, fastest refresh."] = "Toutes les couches activées, rafraîchissement le plus rapide.",
	["Minimap replacement"] = "Remplacement de la minicarte",
	["Hides the Blizzard minimap while GoodMap is shown. Its buttons move to GoodMap's button bar."] = "Masque la minicarte de Blizzard tant que GoodMap est affiché. Ses boutons passent dans la barre de boutons de GoodMap.",
	["Step aside for the world map"] = "Laisser la place à la carte du monde",
	["Hides GoodMap while the world map (M) is open and brings it back when you close it."] = "Masque GoodMap pendant que la carte du monde (M) est ouverte et le réaffiche quand vous la fermez.",
	["Use the Blizzard minimap where there's no position"] = "Minicarte de Blizzard là où la position n’est pas disponible",
	["Most dungeons and raids don't share your position with add-ons, so GoodMap hands over to the Blizzard minimap there."] = "La plupart des donjons et des raids ne donnent pas votre position aux addons. GoodMap y laisse donc la place à la minicarte de Blizzard.",
	["Frame"] = "Fenêtre",
	["Lock position and size"] = "Verrouiller la position et la taille",
	["Stops Shift-dragging and resizing the map."] = "Empêche de déplacer la carte avec Maj et de la redimensionner.",
	["Round looks like the Blizzard minimap. Square shows more of the map."] = "Ronde ressemble à la minicarte de Blizzard. Carrée montre une plus grande partie de la carte.",
	["Size"] = "Taille",
	["How wide the round map is. You can also drag the grip in the bottom-right corner (hover the map)."] = "La largeur de la carte ronde. Vous pouvez aussi tirer la poignée en bas à droite (survolez la carte).",
	["Width"] = "Largeur",
	["You can also drag the grip in the bottom-right corner (hover the map)."] = "Vous pouvez aussi tirer la poignée en bas à droite (survolez la carte).",
	["Height"] = "Hauteur",
	["Scale"] = "Échelle",
	["Frame strata"] = "Niveau d’affichage",
	["Which layer of the screen the map is drawn on."] = "Le plan de l’écran sur lequel la carte est dessinée.",
	["Background"] = "Arrière-plan",
	["Low"] = "Bas",
	["Medium"] = "Moyen",
	["High"] = "Haut",
	["Dialog"] = "Dialogue",
	["Map opacity"] = "Opacité de la carte",
	["How solid the map artwork looks."] = "L’opacité du fond de carte.",
	["Full opacity on mouseover"] = "Opacité totale au survol",
	["Shows the artwork fully while your mouse is over the map."] = "Affiche le fond de carte en entier quand la souris est sur la carte.",
	["Opacity when idle"] = "Opacité au repos",
	["Fades the whole map, icons included, while your mouse is somewhere else."] = "Estompe toute la carte, icônes comprises, quand la souris est ailleurs.",
	["Opacity in combat"] = "Opacité en combat",
	["Click-through lets you click the world under the map."] = "Avec les clics traversants, vous cliquez sur le monde sous la carte.",
	["Look"] = "Apparence",
	["Border"] = "Bordure",
	["Thin line"] = "Trait fin",
	["Class color"] = "Couleur de classe",
	["None"] = "Aucune",
	["Border color"] = "Couleur de la bordure",
	["Border thickness"] = "Épaisseur de la bordure",
	["Hide close button"] = "Masquer le bouton Fermer",
	["Only applies to the Blizzard border."] = "Seulement avec la bordure Blizzard.",
	["Hide the tab"] = "Masquer l’onglet",
	["The GoodMap button in the bar, Ctrl + right-click and /goodmap open the menu."] = "Le bouton GoodMap de la barre, Ctrl + clic droit et /goodmap ouvrent le menu.",
	["Compass letters"] = "Lettres de boussole",
	["N, E, S and W just inside the round map's edge."] = "N, E, S et O juste à l’intérieur du bord de la carte ronde.",
	["Facing glow"] = "Halo d’orientation",
	["A soft glow slides around the round map's ring to show which way you're facing, as you turn."] = "Un halo doux glisse autour de l’anneau de la carte ronde pour montrer où vous regardez, à mesure que vous tournez.",
	["Glow color"] = "Couleur du halo",
	["GoodMap green"] = "Vert GoodMap",
	["Gold"] = "Or",
	["White"] = "Blanc",
	["Blue"] = "Bleu",
	["Purple"] = "Violet",
	["Pink"] = "Rose",
	["Red"] = "Rouge",
	["Custom"] = "Personnalisée",
	["Custom glow color"] = "Couleur personnalisée du halo",
	["Visibility"] = "Visibilité",
	["Always show in battlegrounds and arenas"] = "Toujours afficher en champ de bataille et en arène",
	["Hide in dungeons, raids and delves"] = "Masquer en donjon, en raid et dans les gouffres",
	["Hide in combat"] = "Masquer en combat",
	["Calmer in combat"] = "Plus discrète en combat",
	["While you're fighting, the button bar and the map text fade out. They come back when combat ends, or when you hover the map."] = "Pendant un combat, la barre de boutons et le texte de la carte s’estompent. Ils reviennent à la fin du combat, ou quand vous survolez la carte.",
	["Reset"] = "Réinitialiser",
	["Reset position"] = "Réinitialiser la position",
	["Moves GoodMap back to the minimap's corner."] = "Remet GoodMap dans le coin de la minicarte.",
	["Reset all settings"] = "Réinitialiser toutes les options",
	["Puts every GoodMap setting in this profile back to default."] = "Remet toutes les options GoodMap de ce profil par défaut.",
	["Movement"] = "Déplacement",
	["Keeps you in the middle of the map while you move."] = "Vous garde au centre de la carte pendant vos déplacements.",
	["Follow dead zone"] = "Marge de suivi",
	["How far you can move from the middle before the map catches up. 0% keeps you exactly in the middle; higher values move the map less often."] = "La distance que vous pouvez parcourir depuis le centre avant que la carte ne vous rattrape. À 0 %, vous restez pile au centre ; plus la valeur est haute, moins la carte bouge.",
	["Resume after"] = "Reprendre après",
	["Seconds after your mouse leaves the map before it follows you again."] = "Nombre de secondes après le départ de la souris avant que la carte vous suive à nouveau.",
	["Return to your zone"] = "Revenir à votre zone",
	["After you look at another map, jump back to your zone once you stop using the map."] = "Après avoir consulté une autre carte, GoodMap revient à votre zone dès que vous n’utilisez plus la carte.",
	["Click to open sub-zones"] = "Clic pour ouvrir les sous-zones",
	["Left-click a sub-zone to open it, right-click to go up a level."] = "Clic gauche sur une sous-zone pour l’ouvrir, clic droit pour remonter d’un niveau.",
	["Extra zoom levels"] = "Niveaux de zoom en plus",
	["How far past Blizzard's closest zoom you can go, 25% closer each step. At 20 you can get over 80 times closer."] = "Jusqu’où vous pouvez zoomer au-delà du zoom maximal de Blizzard, 25 % plus près à chaque cran. À 20, vous voyez plus de 80 fois plus près.",
	["Learn your usual zoom"] = "Apprendre votre zoom habituel",
	["GoodMap learns how far out you usually look, and goes back to it when you move to another zone or into a city. In between, zoom as close or as far as you like."] = "GoodMap apprend de quelle distance vous regardez d’habitude et y revient quand vous changez de zone ou entrez dans une ville. Entre-temps, zoomez aussi près ou aussi loin que vous voulez.",
	["Usual zoom"] = "Zoom habituel",
	["Forget my usual zoom"] = "Oublier mon zoom habituel",
	["GoodMap will learn your usual zoom again from now on."] = "GoodMap réapprend votre zoom habituel à partir de maintenant.",
	["Starts learning your usual zoom from scratch."] = "Recommence à apprendre votre zoom habituel depuis zéro.",
	["Zoom out while flying"] = "Dézoomer en vol",
	["Zoom levels to step out while flying, skyriding or on a flight path. It zooms back in after you land. 0 turns it off."] = "Nombre de niveaux de dézoom en vol, en vol dynamique ou sur une route aérienne. Le zoom revient après l’atterrissage. 0 désactive.",
	["Zoom in when resting"] = "Zoomer au repos",
	["Zoom levels to step in while you're in a city or an inn. It zooms back out when you leave. 0 turns it off."] = "Nombre de niveaux de zoom en ville ou à l’auberge. Le zoom revient quand vous partez. 0 désactive.",
	["Smooth zoom"] = "Zoom fluide",
	["Glides between zoom levels instead of jumping."] = "Passe d’un niveau de zoom à l’autre en douceur, sans à-coups.",
	["Zoom buttons on mouseover"] = "Boutons de zoom au survol",
	["Minimap zoom keys zoom GoodMap"] = "Les touches de zoom de la minicarte zooment GoodMap",
	["Your Minimap Zoom In and Zoom Out key bindings also zoom GoodMap."] = "Vos raccourcis Zoom avant et Zoom arrière de la minicarte zooment aussi GoodMap.",
	["Peek"] = "Coup d’œil",
	["Peek key"] = "Touche du coup d’œil",
	["Use %s"] = "Utiliser %s",
	["Hold the peek key to make GoodMap bigger and zoomed out. Let go and it snaps back. %s is the default. You can pick any key above or under %s."] = "Maintenez la touche pour agrandir GoodMap et dézoomer. Relâchez-la et tout revient. Par défaut : %s. Vous pouvez choisir n’importe quelle touche ci-dessus ou dans %s.",
	["How much bigger GoodMap gets while you hold the peek key."] = "À quel point GoodMap s’agrandit quand vous maintenez la touche.",
	["How far out GoodMap zooms while you hold the peek key, from where you are to the whole zone."] = "Jusqu’où GoodMap dézoome quand vous maintenez la touche du coup d’œil, d’où vous êtes jusqu’à toute la zone.",
	["Text"] = "Texte",
	["Zone name"] = "Nom de la zone",
	["The sub-zone name, colored by PvP status. While you look at another map, it shows that map's name. In a house, it shows the room you're in."] = "Le nom de la sous-zone, coloré selon le statut JcJ. Sur une autre carte, c’est le nom de cette carte. Dans une maison, c’est la pièce où vous êtes.",
	["Zone name position"] = "Position du nom de la zone",
	["Zone name size"] = "Taille du nom de la zone",
	["Left-click for the stopwatch and alarm, right-click for the calendar. It follows the game's 24-hour and local time options."] = "Clic gauche pour le chronomètre et l’alarme, clic droit pour le calendrier. Elle suit les options 24 h et heure locale du jeu.",
	["Player coordinates"] = "Coordonnées du joueur",
	["Click to center the map on you, Shift-click to share your location in chat."] = "Clic pour centrer la carte sur vous, Maj-clic pour partager votre position dans la discussion.",
	["Cursor coordinates"] = "Coordonnées du curseur",
	["Shown while your mouse is over the map."] = "Affichées quand la souris est sur la carte.",
	["Coordinate decimals"] = "Décimales des coordonnées",
	["Text size"] = "Taille du texte",
	["Coordinates, clock and distance."] = "Coordonnées, horloge et distance.",
	["Shade behind text"] = "Ombre derrière le texte",
	["A soft dark strip behind the zone name, clock and coordinates, so they're easy to read on any map."] = "Une bande sombre et douce derrière le nom de la zone, l’horloge et les coordonnées, pour les lire facilement sur n’importe quelle carte.",
	["Flight info"] = "Infos de vol",
	["On a flight path, shows where you're going under the zone name, and how long is left once GoodMap knows the route. It learns each route the first time you fly it."] = "Pendant un trajet aérien, affiche votre destination sous le nom de la zone, et le temps restant dès que GoodMap connaît le trajet. Il apprend chaque trajet la première fois que vous le faites.",
	["Frame rate, latency and your lowest durability, next to the coordinates."] = "Images par seconde, latence et votre durabilité la plus basse, à côté des coordonnées.",
	["On days with a holiday or world event, a small button pops up on the left of the map. Hover it for details, click for the calendar, right-click to hide it for a day, a week, a month or for good."] = "Les jours de fête ou d’événement mondial, un petit bouton apparaît à gauche de la carte. Survolez-le pour les détails, cliquez pour le calendrier, clic droit pour le masquer un jour, une semaine, un mois ou pour de bon.",
	["Waypoints"] = "Points de passage",
	["Edge arrow for your tracked target"] = "Flèche au bord vers votre cible suivie",
	["When the quest or map pin you're tracking is outside the view, an arrow on the map's edge points to it."] = "Quand la quête ou le repère suivi est hors de vue, une flèche au bord de la carte vous montre la direction.",
	["Show distance"] = "Afficher la distance",
	["Show time to arrive"] = "Afficher le temps d’arrivée",
	["Worked out from how fast you've been getting closer."] = "Calculé d’après la vitesse à laquelle vous vous rapprochez.",
	["Zoom out to fit your target"] = "Dézoomer pour voir votre cible",
	["When your tracked target is just outside the view, GoodMap zooms out up to three steps to show it, and back in as you get close."] = "Quand votre cible suivie est juste hors de vue, GoodMap dézoome jusqu’à trois crans pour l’afficher, puis rezoome à mesure que vous approchez.",
	["Corpse arrow"] = "Flèche vers le corps",
	["After you die, an arrow on the map's edge points to your corpse, with the distance."] = "Après votre mort, une flèche au bord de la carte pointe vers votre corps, avec la distance.",
	["Flight mode"] = "Mode vol",
	["On a flight path, GoodMap shows your whole route, how long is left and when you'll land. It learns each route's time, and estimates new ones from the distance."] = "Sur une route aérienne, GoodMap montre tout le trajet, le temps restant et l’heure d’atterrissage. Il apprend la durée de chaque trajet et estime les nouveaux d’après la distance.",
	["Show the whole route"] = "Afficher tout le trajet",
	["Zooms out to fit the whole flight, and back to your usual zoom when you land."] = "Dézoome pour montrer tout le vol, puis revient à votre zoom habituel à l’atterrissage.",
	["Progress ring"] = "Anneau de progression",
	["The round map's edge fills up as you fly. On a square map, a bar along the bottom does."] = "Le bord de la carte ronde se remplit pendant le vol. Sur une carte carrée, c’est une barre en bas.",
	["Hide quests while flying"] = "Masquer les quêtes en vol",
	["Quests, world quests and other map icons step aside while you fly, so the route stands out. Your tracked target stays."] = "Les quêtes, expéditions et autres icônes de la carte s’effacent pendant le vol pour laisser voir le trajet. Votre cible suivie reste.",
	["Landing chime"] = "Son d’atterrissage",
	["A soft sound 10 seconds before you land."] = "Un son discret 10 secondes avant l’atterrissage.",
	["Offer routes when you gather"] = "Proposer des routes quand vous récoltez",
	["The first time you gather a herb, ore or lumber in a zone, GoodMap shows that zone's farming routes."] = "La première fois que vous récoltez une plante, un minerai ou du bois dans une zone, GoodMap affiche les routes de farm de cette zone.",
	["Ask when you fish a pool"] = "Demander quand vous pêchez dans un banc",
	["When you fish from a pool, GoodMap asks once per zone whether you'd like a route from pool to pool. Fishing anywhere else is left alone."] = "Quand vous pêchez dans un banc de poissons, GoodMap demande une fois par zone si vous voulez une route d’un banc à l’autre. Ailleurs, vous pêchez tranquillement.",
	["Draws the route on the map, with lights running ahead of you to the next spot."] = "Trace la route sur la carte, avec des lumières qui filent devant vous vers le prochain emplacement.",
	["Puts your map pin on the next spot, so the game's arrow and distance lead you there. It replaces your own map pin while you follow a route."] = "Place votre repère sur le prochain emplacement, pour que la flèche et la distance du jeu vous y mènent. Il remplace votre propre repère tant que vous suivez une route.",
	["Hide quests while farming"] = "Masquer les quêtes pendant le farm",
	["Quests and world quests step aside while you follow a route. Your tracked target stays."] = "Les quêtes et expéditions s’effacent tant que vous suivez une route. Votre cible suivie reste.",
	["Remember spots you gather"] = "Mémoriser vos emplacements de récolte",
	["GoodMap keeps the spots you gather, for a route through your own spots."] = "GoodMap garde les emplacements où vous récoltez, pour une route qui passe par les vôtres.",
	["Open farming routes"] = "Ouvrir les routes de farm",
	["Routes for the zone you're in. Also /goodmap routes."] = "Les routes de la zone où vous êtes. Aussi avec /goodmap routes.",
	["Your spots"] = "Vos emplacements",
	["Forget my spots"] = "Oublier mes emplacements",
	["Your gathered spots were forgotten."] = "Vos emplacements de récolte ont été oubliés.",
	["Forgets every spot you've gathered, in every zone."] = "Oublie tous les emplacements où vous avez récolté, dans toutes les zones.",
	["Icons"] = "Icônes",
	["Icon scale"] = "Taille des icônes",
	["Size of map icons. Blizzard's default for the zone map is 60%."] = "Taille des icônes de la carte. Par défaut, Blizzard utilise 60 % pour la carte de zone.",
	["Player arrow"] = "Flèche du joueur",
	["Blizzard's own arrow, or one of GoodMap's in the color you pick."] = "La flèche de Blizzard, ou une flèche de GoodMap dans la couleur de votre choix.",
	["Classic"] = "Classique",
	["Dart"] = "Pointe",
	["Compass needle"] = "Aiguille de boussole",
	["Dot and beam"] = "Point et faisceau",
	["Arrow color"] = "Couleur de la flèche",
	["Gold on the classic arrow is its own color."] = "L’or de la flèche classique est sa propre couleur.",
	["Custom arrow color"] = "Couleur personnalisée de la flèche",
	["Player arrow size"] = "Taille de la flèche du joueur",
	["Blizzard's default: 12."] = "Par défaut chez Blizzard : 12.",
	["Party and raid dot size"] = "Taille des points de groupe et de raid",
	["Blizzard's default: 8."] = "Par défaut chez Blizzard : 8.",
	["Icon sizes by type"] = "Taille des icônes par type",
	["Quests"] = "Quêtes",
	["Quest objectives, world quests and bonus objectives."] = "Objectifs de quête, expéditions et objectifs bonus.",
	["Rares and treasures"] = "Rares et trésors",
	["Travel"] = "Voyage",
	["Flight points, portals, and dungeon and delve entrances."] = "Points de vol, portails, et entrées de donjons et de gouffres.",
	["Add-on icons"] = "Icônes d’addons",
	["HandyNotes, RareScanner, GatherMate2 and other add-ons' map pins."] = "Les marqueurs de carte de HandyNotes, RareScanner, GatherMate2 et d’autres addons.",
	["Dark outline"] = "Contour sombre",
	["A soft dark circle behind icons, so they stand out on busy map art."] = "Un cercle sombre et doux derrière les icônes, pour qu’elles ressortent sur les cartes chargées.",
	["Extra layers from the world map"] = "Couches en plus venues de la carte du monde",
	["Your active quest objectives and quest areas."] = "Vos objectifs et zones de quête en cours.",
	["Available quests"] = "Quêtes disponibles",
	["Quest givers you haven't talked to yet."] = "Les donneurs de quêtes à qui vous n’avez pas encore parlé.",
	["World quests"] = "Expéditions",
	["World quest refresh"] = "Rafraîchissement des expéditions",
	["Blizzard refreshes every 0.5 s; a calmer rate saves CPU."] = "Blizzard rafraîchit toutes les 0,5 s ; plus lent, c’est moins de processeur.",
	["Bonus objectives"] = "Objectifs bonus",
	["Delves"] = "Gouffres",
	["Tracking and waypoints"] = "Suivi et points de passage",
	["Collectibles you track, your map pin and the waypoint you're following. Ctrl-click places a map pin."] = "Les objets de collection suivis, votre repère et le point de passage suivi. Ctrl-clic pose un repère.",
	["Skyriding races"] = "Courses de vol dynamique",
	["Invasions and contributions"] = "Invasions et contributions",
	["Housing neighborhoods"] = "Quartiers",
	["Plots in your neighborhood: yours, your friends' and the free ones."] = "Les parcelles de votre quartier : la vôtre, celles de vos amis et les libres.",
	["Built-in layers (turn off to save work)"] = "Couches intégrées (désactivez-les pour alléger)",
	["Points of interest and events"] = "Points d’intérêt et évènements",
	["Flight points"] = "Points de vol",
	["Dungeon and raid entrances"] = "Entrées de donjons et de raids",
	["Boss icons"] = "Icônes des boss",
	["Pet tamers"] = "Dresseurs de mascottes",
	["Dig sites"] = "Sites de fouilles",
	["Area labels on hover"] = "Noms des lieux au survol",
	["Sub-zone names when you hover the map."] = "Les noms des sous-zones quand vous survolez la carte.",
	["Area label size"] = "Taille des noms des lieux",
	["Add-ons"] = "Addons",
	["Show HandyNotes icons (if installed)."] = "Afficher les icônes de HandyNotes (s’il est installé).",
	["Show RareScanner icons (if installed)."] = "Afficher les icônes de RareScanner (s’il est installé).",
	["Show GatherMate2 nodes (if installed)."] = "Afficher les points de GatherMate2 (s’il est installé).",
	["Other add-ons' map pins"] = "Marqueurs des autres addons",
	["Pins other add-ons put on the world map, like TomTom waypoints."] = "Les marqueurs que d’autres addons placent sur la carte du monde, comme les points de passage de TomTom.",
	["TomTom: Alt + right-click"] = "TomTom : Alt + clic droit",
	["Alt + right-click the map to add a TomTom waypoint (if installed)."] = "Alt + clic droit sur la carte ajoute un point de passage TomTom (s’il est installé).",
	["Unexplored areas"] = "Zones inexplorées",
	["Show unexplored areas"] = "Afficher les zones inexplorées",
	["Draws the parts of each zone you haven't explored yet. The map art comes with GoodMap (GoodMap_Reveal) and only loads when this is on."] = "Dessine les parties de chaque zone que vous n’avez pas encore explorées. Les images de carte sont fournies avec GoodMap (GoodMap_Reveal) et ne se chargent que si cette option est active.",
	["Tint unexplored areas"] = "Teinter les zones inexplorées",
	["A cool tint, so you can still tell what you haven't explored."] = "Une teinte froide, pour savoir quand même ce que vous n’avez pas exploré.",
	["Minimap"] = "Minicarte",
	["Radar: the minimap inside GoodMap"] = "Radar : la minicarte dans GoodMap",
	["Embed the minimap"] = "Intégrer la minicarte",
	["The real minimap moves into GoodMap, centered on you, so gathering nodes, tracking and other minimap icons show up on the map. It always stays inside GoodMap's window."] = "La vraie minicarte passe dans GoodMap, centrée sur vous : les points de récolte, le suivi et les autres icônes de la minicarte apparaissent sur la carte. Elle reste toujours dans la fenêtre de GoodMap.",
	["Radar style"] = "Style du radar",
	["Aligned: no terrain, and the icons sit exactly where they are on the map (it grows as you zoom). Fixed: a round minimap of a set size."] = "Aligné : sans terrain, les icônes sont exactement à leur place sur la carte (il grandit avec le zoom). Fixe : une minicarte ronde de taille fixe.",
	["Aligned to map"] = "Aligné sur la carte",
	["Fixed size"] = "Taille fixe",
	["Auto-zoom the minimap"] = "Zoom automatique de la minicarte",
	["Picks a minimap zoom whose range fits inside GoodMap."] = "Choisit un zoom de minicarte dont la portée tient dans GoodMap.",
	["Radar size"] = "Taille du radar",
	["Show minimap terrain"] = "Afficher le terrain de la minicarte",
	["Terrain opacity"] = "Opacité du terrain",
	["Minimap icon size"] = "Taille des icônes de la minicarte",
	["Size of minimap icons like gathering nodes and tracking."] = "Taille des icônes de la minicarte, comme les points de récolte et le suivi.",
	["Interactive radar"] = "Radar interactif",
	["Lets the radar take clicks and the mouse wheel. When off, clicks go to the map. Hovering a node shows what it is either way."] = "Le radar reçoit les clics et la molette. Désactivé, les clics vont à la carte. Dans les deux cas, survoler un point de récolte montre ce que c’est.",
	["Hide GoodMap's player arrow"] = "Masquer la flèche du joueur de GoodMap",
	["Uses the minimap's own arrow instead while the radar is showing."] = "Utilise plutôt la flèche de la minicarte quand le radar est affiché.",
	["Show the radar in cities and inns"] = "Afficher le radar en ville et à l’auberge",
	["In cities the minimap can show a gray square where its terrain would be. When this is off, the radar sits out while you're resting."] = "En ville, la minicarte peut afficher un carré gris à la place du terrain. Si c’est désactivé, le radar se retire pendant que vous vous reposez.",
	["Show the radar indoors"] = "Afficher le radar à l’intérieur",
	["In caves and buildings."] = "Dans les grottes et les bâtiments.",
	["Button bar"] = "Barre de boutons",
	["Puts minimap buttons in a bar next to GoodMap."] = "Range les boutons de la minicarte dans une barre à côté de GoodMap.",
	["Off"] = "Désactivée",
	["When the Blizzard minimap is hidden"] = "Quand la minicarte de Blizzard est masquée",
	["Always"] = "Toujours",
	["GoodMap button"] = "Bouton GoodMap",
	["Click for the menu, right-click for settings."] = "Clic pour le menu, clic droit pour les options.",
	["Blizzard buttons"] = "Boutons Blizzard",
	["Tracking, calendar, mail, add-on compartment and expansion summary."] = "Suivi, calendrier, courrier, compartiment des addons et récapitulatif de l’extension.",
	["Other add-on buttons"] = "Boutons des autres addons",
	["Also docks the minimap buttons some add-ons make on their own, so they don't float over the map."] = "Range aussi les boutons de minicarte que certains addons créent eux-mêmes, pour qu’ils ne flottent pas sur la carte.",
	["Bar position"] = "Position de la barre",
	["Below the map"] = "Sous la carte",
	["Above the map"] = "Au-dessus de la carte",
	["Left of the map"] = "À gauche de la carte",
	["Right of the map"] = "À droite de la carte",
	["Button size"] = "Taille des boutons",
	["Button spacing"] = "Espacement des boutons",
	["Show only on mouseover"] = "Afficher seulement au survol",
	["Instance difficulty"] = "Difficulté de l’instance",
	["Show instance difficulty"] = "Afficher la difficulté",
	["Shows the dungeon or raid difficulty on GoodMap while the Blizzard minimap is hidden."] = "Affiche la difficulté du donjon ou du raid sur GoodMap quand la minicarte de Blizzard est masquée.",
	["Difficulty position"] = "Position de la difficulté",
	["Group"] = "Groupe",
	["Pings and markers"] = "Signaux et marqueurs",
	["Show group pings"] = "Afficher les signaux du groupe",
	["Pings from party and raid members who use GoodMap."] = "Les signaux des membres du groupe et du raid qui utilisent GoodMap.",
	["Show group members' pings in the world"] = "Afficher les signaux du groupe dans le monde",
	["A group member's ping becomes your map pin, so you see it in the world with the distance to it. It replaces your own map pin."] = "Le signal d’un membre du groupe devient votre repère : vous le voyez dans le monde, avec la distance. Il remplace votre propre repère.",
	["Double-click to ping"] = "Double-clic pour signaler",
	["Double-click the map to ping that spot for your group."] = "Double-cliquez sur la carte pour signaler cet endroit à votre groupe.",
	["Double right-click for a raid marker"] = "Double clic droit pour un marqueur de raid",
	["Double right-click the map to drop a raid marker: the red X unless you pick another below. Once a marker is down, a double right-click asks which one you want."] = "Un double clic droit sur la carte place un marqueur de raid : la croix rouge, sauf si vous en choisissez un autre ci-dessous. Une fois un marqueur posé, un double clic droit vous demande lequel placer.",
	["Put your pings and markers in the world"] = "Afficher vos signaux et marqueurs dans le monde",
	["Your ping or marker also becomes your map pin, so it shows in the world with the distance to it. The game allows one map pin, so each new one replaces the last. Map pins don't work in dungeons, raids and battlegrounds."] = "Votre signal ou marqueur devient aussi votre repère : il apparaît dans le monde, avec la distance. Le jeu n’autorise qu’un repère, chaque nouveau remplace donc le précédent. Les repères ne fonctionnent pas en donjon, en raid ni en champ de bataille.",
	["Share in chat"] = "Partager dans la discussion",
	["Also posts a map pin link in your group's chat, or in /say when you're not in a group. Players without GoodMap can click it to see the spot on their map and in the world."] = "Publie aussi un lien vers le repère dans la discussion du groupe, ou en /dire si vous n’êtes pas en groupe. Les joueurs sans GoodMap peuvent cliquer dessus pour voir l’endroit sur leur carte et dans le monde.",
	["The mark key places"] = "La touche de marquage place",
	["Hold the mark key and click the map. Everyone in your group who uses GoodMap sees it. Add-ons can't put markers in the world itself, so they show on the map."] = "Maintenez la touche de marquage et cliquez sur la carte. Tous ceux de votre groupe qui utilisent GoodMap le voient. Les addons ne peuvent pas placer de marqueurs dans le monde lui-même, ils apparaissent donc sur la carte.",
	["A ping"] = "Un signal",
	["A raid marker"] = "Un marqueur de raid",
	["A ping and a raid marker"] = "Un signal et un marqueur de raid",
	["Raid marker"] = "Marqueur de raid",
	["The marker that double right-click and the mark key put down first."] = "Le marqueur que le double clic droit et la touche de marquage placent en premier.",
	["Markers"] = "Marqueurs",
	["Removes the markers on the map for everyone in your group. In a raid, only the leader and assistants can."] = "Retire les marqueurs de la carte pour tout votre groupe. En raid, seuls le chef et les assistants peuvent le faire.",
	["Houses"] = "Maisons",
	["Automatic uses GoodMap's floor plan, or the Blizzard minimap if another house map add-on (Chamberlain, HouseMinimap) is installed. No minimap hides both."] = "Automatique utilise le plan de GoodMap, ou la minicarte de Blizzard si un autre addon de carte de maison (Chamberlain, HouseMinimap) est installé. Pas de minicarte masque les deux.",
	["Complete rooms"] = "Compléter les pièces",
	["Once GoodMap knows a room's size and where its door is, it draws the whole room instead of just where you've walked."] = "Dès que GoodMap connaît la taille d’une pièce et l’emplacement de sa porte, il la dessine en entier au lieu de seulement là où vous êtes passé.",
	["Room names"] = "Noms des pièces",
	["Shows each room's name in the middle of the room."] = "Affiche le nom de chaque pièce en son centre.",
	["Show your group"] = "Afficher votre groupe",
	["Party and raid members in the house, as class-colored dots."] = "Les membres du groupe ou du raid dans la maison, en points aux couleurs de leur classe.",
	["House zoom"] = "Zoom dans les maisons",
	["How big rooms look. You can also use the mouse wheel over the map."] = "La taille d’affichage des pièces. Vous pouvez aussi utiliser la molette sur la carte.",
	["Saved floor plans"] = "Plans enregistrés",
	["This house"] = "Cette maison",
	["Forget this house"] = "Oublier cette maison",
	["This house's floor plan was forgotten."] = "Le plan de cette maison a été oublié.",
	["Go inside a house first."] = "Entrez d’abord dans une maison.",
	["Clears the floor plan of the house you're in so GoodMap draws it again from scratch."] = "Efface le plan de la maison où vous êtes pour que GoodMap le redessine de zéro.",
	["Every house"] = "Toutes les maisons",
	["Forget all houses"] = "Oublier toutes les maisons",
	["Clears every saved floor plan."] = "Efface tous les plans enregistrés.",
	["Profiles"] = "Profils",
	["Profile"] = "Profil",
	["Default"] = "Par défaut",
	["Every character uses the Default profile unless you pick another one."] = "Chaque personnage utilise le profil « Par défaut », sauf si vous en choisissez un autre.",
	["Use a profile just for this character"] = "Profil propre à ce personnage",
	["Starts as a copy of your current settings."] = "Il reprend vos options actuelles.",
	["New profile"] = "Nouveau profil",
	["New profile..."] = "Nouveau profil...",
	["Saves your current settings as a new profile and switches to it."] = "Enregistre vos options actuelles dans un nouveau profil et l’active.",
	["Delete profile"] = "Supprimer le profil",
	["Delete this profile"] = "Supprimer ce profil",
	["The Default profile can't be deleted."] = "Le profil « Par défaut » ne peut pas être supprimé.",
	["Deletes the profile you're using and switches back to Default."] = "Supprime le profil actuel et revient au profil « Par défaut ».",
	["Share settings"] = "Partager les options",
	["Export"] = "Exporter",
	["Export settings..."] = "Exporter les options...",
	["Turns your settings into a short text you can share. Position and zoom aren't included."] = "Transforme vos options en un court texte à partager. La position et le zoom ne sont pas inclus.",
	["Import"] = "Importer",
	["Import settings..."] = "Importer des options...",
	["Paste settings someone shared with you."] = "Collez les options que quelqu’un vous a partagées.",
	["%s is now your minimap. Shift-M hides or shows it, M opens the world map as usual, and /goodmap opens settings."] = "%s est maintenant votre minicarte. Maj-M l’affiche ou la masque, M ouvre la carte du monde comme d’habitude et /goodmap ouvre les options.",
	["%s is turned on too and changes the same map. Turn it off. GoodMap stays inactive until then."] = "%s est aussi activé et modifie la même carte. Désactivez-le. D’ici là, GoodMap reste inactif.",
	["Blizzard's zone map isn't available."] = "La carte de zone de Blizzard n’est pas disponible.",
}
