-- ==================== GoodMap/GoodMap.lua
do local __addon, __ns = ... local function part()
-- Copyright (C) 2026 SoFinSicc. Part of Pathway (curseforge.com/wow/addons/pathway): free software under the GPLv3 or later, with additional terms that require keeping this credit. See LICENSE.md.
--[[----------------------------------------------------------------------------
  GoodMap 1.4.3                                        Retail / Midnight 12.x

  Your zone map becomes your minimap, round or square.

  * Replaces the Blizzard minimap: the real minimap is embedded as a "radar"
    (gathering nodes, tracking blips) and its buttons are docked in a bar.
  * Steps aside while the world map (M) is open, and hands back to the
    Blizzard minimap wherever your position is unavailable (most instances).
  * Modes: Normal, the farming modes (herbs, ore and fishing:
    the zone's routes come up, and each new zone asks) and Battleground (the
    whole map, bigger group dots, no clutter).
  * On a flight path it shows the route, a countdown and the landing time.
  * Farming routes: gather a herb or ore, or fish a pool, and follow a loop
    through the zone, each kind with a look of its own.
  * GoodMap.lua, Locales.lua (translations) and Bindings.xml (keys). No libraries.
    In Pathway, the retail-only parts (houses, unexplored-area art, lumber,
    void motes, world quests) are left out.

  Performance model
    * Nothing runs while GoodMap is hidden.
    * While shown: a 0.2 s "slow tick" (hover, idle, movement detection, clock)
      and a per-frame "fast tick" that only runs while you move or hover the
      map, then puts itself back to sleep.
    * The facing glow and custom player arrow read your facing once a frame
      and redraw only when it changes.
    * Hot paths allocate no tables (world rects are cached per map).

  Settings: Options > AddOns > GoodMap, or /goodmap.
------------------------------------------------------------------------------]]

local ADDON_NAME, NS = __addon, __ns
NS = NS.GoodMap                 -- GoodMap lives inside Pathway as its minimap module (Pathway's namespace is the global Pathway)
local L = NS.L or setmetatable({}, { __index = function(_, k) return k end })

local E = {}            -- functions (kept in a table to stay far below Lua's local limits)
local S = {}            -- runtime state
local db                -- the active settings profile
local ROOT              -- GoodMapDB: profiles, character choices, house maps

local _G = _G
local pairs, ipairs, type, unpack, wipe, rawget, getmetatable, tostring, tonumber = pairs, ipairs, type, unpack, wipe, rawget, getmetatable, tostring, tonumber
local min, max, abs, floor, ceil, atan2, PI, sqrt = math.min, math.max, math.abs, math.floor, math.ceil, math.atan2, math.pi, math.sqrt
local sin, cos, log, exp = math.sin, math.cos, math.log, math.exp
local random = math.random
local format, tsort, tconcat, tremove = string.format, table.sort, table.concat, table.remove
local GetTime, UnitPosition, IsAltKeyDown, IsShiftKeyDown, IsControlKeyDown = GetTime, UnitPosition, IsAltKeyDown, IsShiftKeyDown, IsControlKeyDown
local C_Map, C_Minimap, C_Timer = C_Map, Pathway.Minimap, C_Timer   -- Pathway.Minimap fills in for Classic clients
local issecret = _G.issecretvalue or function() return false end

local TITLE = "GoodMap"
local BRAND = "|cff35d07fPath|rway minimap"
local ICON = "Interface\\Icons\\INV_Misc_Map_01"
local noop = function() end

-- Key binding labels (Bindings.xml).
_G.BINDING_HEADER_GOODMAP = TITLE
_G.BINDING_NAME_GOODMAP_PEEK = L["Peek: hold to enlarge GoodMap"]
_G.BINDING_NAME_GOODMAP_FARM = L["Farming routes"]
_G.BINDING_NAME_GOODMAP_STOP = L["Stop farming route"]
_G.BINDING_NAME_GOODMAP_MARK = L["Mark: hold and click the map"]

local function Print(...) print(BRAND .. ":", ...) end
local function Clamp(v, lo, hi) if v < lo then return lo elseif v > hi then return hi end return v end
local function Num(fmt) return function(v) return format(fmt, v) end end      -- slider labels
local function Pct(v) return format("%d%%", floor(v * 100 + 0.5)) end

--------------------------------------------------------------------------------
-- Defaults (scalars only, so a reset is a plain copy)
--------------------------------------------------------------------------------
local DEFAULTS = {
	-- mode
	mode = "NORMAL",                  -- NORMAL | HERB | ORE | FISH | PVP
	pvpAuto = true,
	-- minimap replacement
	replaceMinimap = true, yieldWorldMap = true, instanceFallback = true,
	-- frame
	posX = false, posY = false,
	shape = "ROUND", roundSize = 220,
	width = 220, height = 200, scale = 1, strata = "LOW",
	locked = false,
	border = "ACCENT", borderColor = "ff000000", borderSize = 2,
	ringGlow = "SOFT", ringColor = "ACCENT", edgeStyle = "SOLID",
	glowStyle = "ARC", glowAlpha = 0.95, glowWidth = 1,  -- the facing glow: OFF | ARC | WIDE | BEAM | COMET | TWIN   -- a glow around the round map: NONE | SOFT | NEON | PULSE | AURA
	hideTab = true, hideClose = true,
	compass = true, compassGlow = true, glowColor = "ACCENT", glowCustom = "ff35d07f",
	arrowStyle = "CLASSIC", arrowColor = "ACCENT", arrowCustom = "ff4da6ff",   -- arrow: Blizzard's own, or a shape and a color
	idleAlpha = 1, combatAlpha = 1, fullOnHover = true,
	mouse = "NORMAL",                 -- NORMAL | ALT | NONE
	showInPvP = false, hideInInstance = false, hideInCombat = false, combatCalm = false,
	-- navigation
	follow = true, deadzone = 0, resumeDelay = 4, autoReturn = true, clickNavigate = true,
