local function ValidValue(key, v)
	local def = DEFAULTS[key]
	if def == nil then return false end
	if key == "posX" or key == "posY" or key == "zoomIndex" or key == "usualSpan" then return v == false or type(v) == "number" end
	if type(v) ~= type(def) then return false end
	if key == "borderColor" or key == "glowCustom" or key == "arrowCustom" then return v:find("^%x%x%x%x%x%x%x%x$") ~= nil end
	local list = CHOICES[key]
	if list then return (" " .. list .. " "):find(" " .. v .. " ", 1, true) ~= nil end
	if type(v) == "number" then return v == v end
	return true
end

