--------------------------------------------------------------------------------
-- Small helpers
--------------------------------------------------------------------------------
local pending = {}
local function Later(key, fn, delay)          -- coalesces bursts of calls into one
	if pending[key] then return end
	pending[key] = true
	C_Timer.After(delay or 0, function() pending[key] = nil; fn() end)
end

local fadeTargets = {}
local fader = CreateFrame("Frame")
fader:Hide()
fader:SetScript("OnUpdate", Pathway.Perf.W("Minimap", function(self, elapsed)
	local step, busy = elapsed * 5, false   -- full fade in 0.2 s
	for f, target in pairs(fadeTargets) do
		local a = f:GetAlpha()
		if abs(a - target) <= step then
			f:SetAlpha(target)
			fadeTargets[f] = nil
		else
			f:SetAlpha(a + (target > a and step or -step))
			busy = true
		end
	end
	if not busy then self:Hide() end
end))
local function FadeTo(f, alpha)
	if abs(f:GetAlpha() - alpha) < 0.01 then fadeTargets[f] = nil; f:SetAlpha(alpha) return end
	fadeTargets[f] = alpha
	fader:Show()
end

-- Short eased tweens (smooth zoom, peek). fn(value) runs every frame until done.
local tweens, finished = {}, {}
local tweener = CreateFrame("Frame")
tweener:Hide()
tweener:SetScript("OnUpdate", Pathway.Perf.W("Minimap", function(self, elapsed)
	local n = 0
	for key, tw in pairs(tweens) do
		tw.t = min(1, tw.t + elapsed / tw.dur)
		local p = 1 - (1 - tw.t) ^ 3                 -- ease out
		tw.fn(tw.from + (tw.to - tw.from) * p)
		if tw.t >= 1 then
			tweens[key] = nil
			if tw.done then n = n + 1; finished[n] = tw.done end
		end
	end
	for i = 1, n do local done = finished[i]; finished[i] = nil; done() end
	if next(tweens) == nil then self:Hide() end
end))
local function Tween(key, from, to, dur, fn, done)
	if abs(to - from) < 1e-4 then
		tweens[key] = nil
		fn(to)
		if done then done() end
		return
	end
	tweens[key] = { from = from, to = to, t = 0, dur = dur, fn = fn, done = done }
	tweener:Show()
end
local function StopTween(key) tweens[key] = nil end

-- Round map: one circular mask shared by the map pins, the floor plan and the text shading.
local CIRCLE_MASK = "Interface\\CharacterFrame\\TempPortraitAlphaMask"
local maskable = setmetatable({}, { __mode = "k" })   -- texture -> masked now?
local function Mask(t)
	if maskable[t] ~= nil then return end
	maskable[t] = false
	if S.round then t:AddMaskTexture(S.roundMask); maskable[t] = true end
end
local function MaskRegions(f, depth)
	local n = select("#", f:GetRegions())
	if n > 0 then
		local list = { f:GetRegions() }
		for i = 1, n do
			local r = list[i]
			if r.GetObjectType and r:GetObjectType() == "Texture" then Mask(r) end
		end
	end
	if depth > 0 and select("#", f:GetChildren()) > 0 then
		local kids = { f:GetChildren() }
		for i = 1, #kids do MaskRegions(kids[i], depth - 1) end
	end
end

local function Tooltip(owner, title, ...)
	GameTooltip:SetOwner(owner, "ANCHOR_LEFT")
	GameTooltip:SetText(title)
	for i = 1, select("#", ...) do GameTooltip:AddLine((select(i, ...)), 1, 1, 1, true) end
	GameTooltip:Show()
end
local function HideTooltip() GameTooltip:Hide() end

-- Hover without clicks: the frame shows its tooltip, and clicks go on to the map
-- underneath (double-clicks and all). In click-through mode it lets the mouse be.
local function Hoverable(f, onEnter)
	f:SetMouseClickEnabled(false)
	f:SetMouseMotionEnabled(S.interactive ~= false)
	f:SetScript("OnEnter", onEnter)
	f:SetScript("OnLeave", HideTooltip)
	S.hoverFrames = S.hoverFrames or {}
	S.hoverFrames[f] = true
end

-- World <-> map maths. Rects are cached per map, so the per-frame path is allocation free.
local rects, yards = {}, {}
local V0, V1
local function MapRect(mapID)
	local r = rects[mapID]
	if r == nil then
		r = false
		V0, V1 = V0 or CreateVector2D(0, 0), V1 or CreateVector2D(1, 1)
		local cont, a = C_Map.GetWorldPosFromMapPos(mapID, V0)
		local _, b = C_Map.GetWorldPosFromMapPos(mapID, V1)
		if a and b then
			local dx, dy = b.x - a.x, b.y - a.y
			if dx ~= 0 and dy ~= 0 then r = { a.x, a.y, dx, dy, cont } end
		end
		rects[mapID] = r
	end
	return r
end

-- A map belongs to one instance (a continent, a dungeon, the Deeprun Tram...).
-- Your world position only means something on a map of the instance you're in:
-- the same numbers in the tram would otherwise land somewhere on Dun Morogh.
-- Where the game itself places you on a map of another instance (a phased copy
-- of a zone), its word is taken.
local function OnInstance(mapID, r, inst)
	if not (inst and r[5]) or issecret(inst) or r[5] == inst then return true end
	return C_Map.GetPlayerMapPosition and C_Map.GetPlayerMapPosition(mapID, "player") ~= nil
end

local function PlayerPos(mapID)                -- normalized x, y on mapID or nil
	local r = mapID and MapRect(mapID)
	if not r then return end
	local wx, wy, _, inst = UnitPosition("player")
	if not wx or issecret(wx) then return end
	local x, y = (wy - r[2]) / r[4], (wx - r[1]) / r[3]
	if x < -0.05 or x > 1.05 or y < -0.05 or y > 1.05 then return end
	if not OnInstance(mapID, r, inst) then return end
	return x, y
end

-- The map you're on: the lowest map that has art of its own, so a cave, a
-- building, a tunnel or a dungeon floor shows its own map when the game has one,
-- and the zone around it when it doesn't.
local artCache = {}
local function HasArt(mapID)
	local a = artCache[mapID]
	if a == nil then
		local ok, layers = pcall(C_Map.GetMapArtLayers, mapID)
		a = (ok and type(layers) == "table" and #layers > 0) and true or false
		artCache[mapID] = a
	end
	return a
end
E.HasArt = HasArt
E.artCache = artCache
-- Every map that has art, by the instance it belongs to: built once, the first
-- time the game can't say which map you're on (some tunnels and instances), so
-- GoodMap can still find the map whose area holds you.
local byInstance
local function MapsByInstance()
	if byInstance then return byInstance end
	byInstance = {}
	for id = 1, 10000 do
		local info = C_Map.GetMapInfo(id)
		if info then
			local t = info.mapType
			if not (t and Enum.UIMapType and t <= Enum.UIMapType.Continent) and HasArt(id) then
				local r = MapRect(id)
				if r and r[5] then
					local list = byInstance[r[5]] or {}
					list[#list + 1] = id
					byInstance[r[5]] = list
				end
			end
		end
	end
	return byInstance
end
E.MapsByInstance = MapsByInstance
function E.ResetMapIndex() byInstance = nil end

-- The most detailed map of your instance whose area holds you (nil if none).
-- With cave and building maps off, the biggest one: the zone, not the room.
function E.FindMapAt()
	local wx, wy, _, inst = UnitPosition("player")
	if not wx or issecret(wx) or not inst or issecret(inst) then return end
	local list = MapsByInstance()[inst]
	if not list then return end
	local small = not (db and db.subMaps == false)
	local best, bestA
	for _, id in ipairs(list) do
		local r = MapRect(id)
		local x, y = (wy - r[2]) / r[4], (wx - r[1]) / r[3]
		if x >= 0 and x <= 1 and y >= 0 and y <= 1 then
			local a = abs(r[3] * r[4])
			if not best or (small and a < bestA) or (not small and a > bestA) then best, bestA = id, a end
		end
	end
	return best
end

-- Is this map one you're actually on (your instance, or the game places you there)?
function E.MapIsHere(id)
	local r = id and MapRect(id)
	if not r then return true end              -- no world rect: nothing to compare, keep the game's choice
	local _, _, _, inst = UnitPosition("player")
	return OnInstance(id, r, inst)
end

function E.PlayerMapID()
	if C_Map.GetBestMapForUnit then
		local best = C_Map.GetBestMapForUnit("player")
		if db and db.subMaps ~= false then
			local id, guard = best, 0
			while id and id ~= 0 and guard < 6 do
				local info = C_Map.GetMapInfo(id)
				if not info or (info.mapType and Enum.UIMapType and info.mapType <= Enum.UIMapType.Continent) then break end
				if HasArt(id) and E.MapIsHere(id) then return id end
				id, guard = info.parentMapID, guard + 1
			end
		end
		local shown = MapUtil.GetDisplayableMapForPlayer()
		if shown and E.MapIsHere(shown) then return shown end
		-- the game has no map for where you are, or one of another place: look for one
		return E.FindMapAt() or shown
	end
	return MapUtil.GetDisplayableMapForPlayer()
end

-- You're somewhere no map covers (inside an instance that has none, like a
-- tunnel the game never drew): GoodMap hands over to the Blizzard minimap.
function E.NoMapHere()
	local wx, _, _, inst = UnitPosition("player")
	if not wx or issecret(wx) or not inst or issecret(inst) then return false end
	local id = S.playerMap or E.PlayerMapID()
	if not id then return true end
	return not E.MapIsHere(id)
end
-- In a dungeon, raid or delve: the instance's own map, when the game has one
function E.InstanceMap()
	if db and db.instanceMaps == false then return end
	local _, kind = IsInInstance()
	if kind == "none" or kind == "pvp" or kind == "arena" then return end
	local id = C_Map.GetBestMapForUnit and C_Map.GetBestMapForUnit("player")
	if id and HasArt(id) then return id end
end

local function MapYards(mapID)                 -- map width in yards
	local w = yards[mapID]
	if w == nil then
		w = false
		local ww = C_Map.GetMapWorldSize and C_Map.GetMapWorldSize(mapID)
		if ww and ww > 0 then
			w = ww
		else
			local r = MapRect(mapID)
			if r then w = abs(r[4]) end
		end
		yards[mapID] = w
	end
	return w
end

-- World position (continent, x, y) of a point on a map, and back. Used for group pings and markers.
function E.MapToWorld(mapID, x, y)
	local r = mapID and MapRect(mapID)
	if not (r and x and y) then return end
	return r[5], r[1] + y * r[3], r[2] + x * r[4]
end

function E.WorldToMap(mapID, cont, wx, wy, loose)      -- loose: also just off the map's edge
	local r = mapID and MapRect(mapID)
	if not r or r[5] ~= cont then return end
	local x, y = (wy - r[2]) / r[4], (wx - r[1]) / r[3]
	if not loose and (x < 0 or x > 1 or y < 0 or y > 1) then return end
	return x, y
end

function E.Yards(d)
	return d >= 1000 and format(L["%.1fk yd"], d / 1000) or format(L["%d yd"], d)
end

function E.Clock(sec)
	sec = floor(sec + 0.5)
	return format("%d:%02d", floor(sec / 60), sec % 60)
end

function E.ClassColor()
	local _, class = UnitClass("player")
	local c = class and ((_G.C_ClassColor and _G.C_ClassColor.GetClassColor and _G.C_ClassColor.GetClassColor(class)) or (RAID_CLASS_COLORS and RAID_CLASS_COLORS[class]))
	if c then return c.r, c.g, c.b end
	return 1, 0.82, 0
end

local function MT(frame) return getmetatable(frame).__index end   -- original widget methods

--------------------------------------------------------------------------------
-- Settings changes are routed through one table
--------------------------------------------------------------------------------
local APPLY = {}
local function OnKeys(keys, fn) for k in keys:gmatch("%S+") do APPLY[k] = fn end end

function E.OnChanged(key)
	if S.ready and APPLY[key] then APPLY[key](key) end
end

function E.Set(key, value)                     -- used by menus/presets so the panel stays in sync
	local setting = S.settings and S.settings[key]
	if setting then setting:SetValue(value) else db[key] = value; E.OnChanged(key) end
end

--------------------------------------------------------------------------------
-- Saved data and profiles
--   GoodMapDB = { profiles = { [name] = settings }, chars = { [character] = name },
--                 houses = { ... }, rooms = { ... }, setupDone, peekKeyDone }
--------------------------------------------------------------------------------
local DEFAULT_PROFILE = "Default"
local NOEXPORT = { posX = true, posY = true, zoomIndex = true, mode = true, usualSpan = true }

-- Settings from older versions, read the new way.
--   1.3.0-1.3.1: arrowStyle GOLD | WHITE | CLASS was the classic arrow in that color.
--   1.3.1: peekZoomOut (y/n) became peekZoom (steps out; 4 = the whole zone).
-- Works on saved profiles (booleans) and on imported text (strings) alike.
local function Upgrade(p)
	local old = p.arrowStyle
	if old == "GOLD" or old == "WHITE" or old == "CLASS" then
		p.arrowStyle = "CLASSIC"
		if p.arrowColor == nil then p.arrowColor = old end
	end
	local z = p.peekZoomOut
	if z ~= nil and p.peekZoom == nil then
		local on = z == true or z == "y"
		p.peekZoom = type(z) == "string" and (on and "4" or "0") or (on and 4 or 0)
	end
	p.peekZoomOut = nil
end

function E.FillDefaults(p)
	Upgrade(p)
	for k, v in pairs(DEFAULTS) do
		if p[k] == nil or not ValidValue(k, p[k]) then p[k] = v end
	end
	for k, r in pairs(RANGE) do
		if type(p[k]) == "number" then p[k] = Clamp(p[k], r[1], r[2]) end
	end
	return p
end

function E.LoadDB()
	local root = _G.PathwayMapDB
	if type(root) ~= "table" then root = {} end
	if type(root.profiles) ~= "table" then
		-- GoodMap 1.0 kept one flat table; it becomes the "Default" profile.
		local p = {}
		for k in pairs(DEFAULTS) do if root[k] ~= nil then p[k] = root[k] end end
		root = { profiles = { [DEFAULT_PROFILE] = p }, setupDone = root.setupDone and true or false }
	end
	if type(root.profiles[DEFAULT_PROFILE]) ~= "table" then root.profiles[DEFAULT_PROFILE] = {} end
	for _, key in ipairs({ "chars", "houses", "rooms", "flights", "spots", "laps", "barPicks", "seenButtons" }) do
		if type(root[key]) ~= "table" then root[key] = {} end
	end
	if (tonumber(root.v) or 0) < 3 then
		-- 1.2 made GoodMap a third bigger: profiles still on the old default size follow along.
		for _, p in pairs(root.profiles) do
			if type(p) == "table" and p.width == 220 and p.height == 200 then p.width, p.height = DEFAULTS.width, DEFAULTS.height end
		end
	end
	if (tonumber(root.v) or 0) < 4 then
		-- 1.3.1: raid markers start as the red X (1.3.0 started with the star).
		for _, p in pairs(root.profiles) do
			if type(p) == "table" and p.markIcon == "1" then p.markIcon = "7" end
		end
	end
	if (tonumber(root.v) or 0) < 5 then
		-- 1.3.0 and 1.3.1 nudged a moved map toward the bottom left at every load when its
		-- scale wasn't 1. Spots that drifted are put back in the minimap's corner.
		local v = tonumber(root.v) or 0
		local W, H = UIParent:GetWidth(), UIParent:GetHeight()
		for _, p in pairs(root.profiles) do
			local s = type(p) == "table" and tonumber(p.scale) or 1
			if type(p) == "table" and type(p.posX) == "number" and type(p.posY) == "number" and abs(s - 1) >= 0.001 then
				local size = (p.shape == "ROUND" and tonumber(p.roundSize)) or tonumber(p.height) or DEFAULTS.height
				local off = p.posY < size or p.posY * s > H + 1 or p.posX * s > W - 10 or p.posX < -size
				if v == 4 or off then p.posX, p.posY = false, false end
			end
		end
	end
	if (tonumber(root.v) or 0) < 6 then
		-- zoom in as close as you like (20 extra steps instead of 4).
		for _, p in pairs(root.profiles) do
			if type(p) == "table" and p.extraZoom == 4 then p.extraZoom = 20 end
		end
	end
	if (tonumber(root.v) or 0) < 7 then
		-- zoom is remembered zone by zone now (cities too): the old "step in when resting" goes off
		for _, p in pairs(root.profiles) do
			if type(p) == "table" and p.cityZoom == 1 then p.cityZoom = 0 end
		end
	end
	if (tonumber(root.v) or 0) < 8 then
		-- Pathway 1.2: the map starts small. A map still at the old default size follows.
		for _, p in pairs(root.profiles) do
			if type(p) == "table" then
				if p.roundSize == 270 then p.roundSize = 220 end
				if p.width == 300 and p.height == 270 then p.width, p.height = 220, 200 end
			end
		end
	end
	if (tonumber(root.v) or 0) < 9 then
		-- Pathway 1.3: indoors the game paints its own building art (and a black ring)
		-- into the minimap, which showed through as a circle. The radar now sits out
		-- indoors; GoodMap follows the cave, building or floor map instead.
		for _, p in pairs(root.profiles) do
			if type(p) == "table" then p.radarIndoors = false end
		end
	end
	root.v = 9
	_G.PathwayMapDB = root
	ROOT = root
	db = E.FillDefaults(root.profiles[DEFAULT_PROFILE])
end

function E.CharKey()
	return (UnitName("player") or "?") .. " - " .. (GetRealmName() or "?")
end

function E.ProfileName()
	local name = ROOT.chars[E.CharKey()]
	if name and ROOT.profiles[name] then return name end
	return DEFAULT_PROFILE
end

function E.ProfileNames()
	local list = {}
	for name in pairs(ROOT.profiles) do if name ~= DEFAULT_PROFILE then list[#list + 1] = name end end
	tsort(list)
	table.insert(list, 1, DEFAULT_PROFILE)
	return list
end

function E.UseProfile(name, copyFrom)
	if type(name) ~= "string" or name == "" then return end
	local profiles = ROOT.profiles
	if not profiles[name] then
		local p = {}
		if copyFrom then for k, v in pairs(copyFrom) do p[k] = v end end
		profiles[name] = p
	end
	ROOT.chars[E.CharKey()] = (name ~= DEFAULT_PROFILE) and name or nil
	db = E.FillDefaults(profiles[name])
	S.posScale = nil        -- this profile's spot is saved at its own scale
	if S.ready then E.AfterProfileChange() end
end

function E.DeleteProfile(name)
	if name == DEFAULT_PROFILE or not ROOT.profiles[name] then return end
	if E.ProfileName() == name then E.UseProfile(DEFAULT_PROFILE) end
	ROOT.profiles[name] = nil
	for char, p in pairs(ROOT.chars) do if p == name then ROOT.chars[char] = nil end end
	E.RefreshSettings()
end

function E.RefreshSettings()
	for _, setting in pairs(S.settings or {}) do
		if setting.NotifyUpdate then setting:NotifyUpdate() end
	end
end

function E.AfterProfileChange()
	E.EndPeek()
	local mode = E.Mode()
	if mode ~= S.mode then E.ApplyMode() else E.ApplyAll() end
	E.RefreshSettings()
end

-- Export / import: "GoodMap1;key=value;..." with only the values you changed.
function E.ExportString()
	local keys = {}
	for k, v in pairs(DEFAULTS) do
		if not NOEXPORT[k] and db[k] ~= v then keys[#keys + 1] = k end
	end
	tsort(keys)
	local parts = { "GoodMap1" }
	for _, k in ipairs(keys) do
		local v = db[k]
		if type(v) == "boolean" then v = v and "y" or "n"
		elseif type(v) == "number" then v = format("%.4g", v) end
		parts[#parts + 1] = k .. "=" .. tostring(v)
	end
	return tconcat(parts, ";")
end

function E.ImportString(text)
	text = (text or ""):gsub("%s+", "")
	if text:sub(1, 8) ~= "GoodMap1" then return false end
	local raw, values = {}, {}
	for k, v in text:gmatch(";([%w_]+)=([^;]*)") do raw[k] = v end
	Upgrade(raw)
	for k, v in pairs(raw) do
		local def = DEFAULTS[k]
		if def ~= nil and not NOEXPORT[k] then
			local val
			if type(def) == "boolean" then
				if v == "y" then val = true elseif v == "n" then val = false end
			elseif type(def) == "number" then
				val = tonumber(v)
				if val and RANGE[k] then val = Clamp(val, RANGE[k][1], RANGE[k][2]) end
			elseif ValidValue(k, v) then
				val = v
			end
			if val ~= nil then values[k] = val end
		end
	end
	for k, v in pairs(DEFAULTS) do
		if not NOEXPORT[k] then
			local nv = values[k]
			if nv == nil then nv = v end
			db[k] = nv
		end
	end
	if S.ready then E.AfterProfileChange() end
	return true
end

--------------------------------------------------------------------------------
-- Visibility: GoodMap is on unless you turn it off (Shift-M), it steps aside
-- for the world map, and hands over to the Blizzard minimap where there is no
-- position. Toggling it yourself always wins until the next zone change.
--------------------------------------------------------------------------------
function E.ShouldShow()
	local _, kind = IsInInstance()
	local wanted = GetCVar("showBattlefieldMinimap") == "1"
	if (db.showInPvP or S.mode == "PVP") and (kind == "pvp" or kind == "arena") then wanted = true end
	if S.editMode then return true end        -- so it can be moved in Edit Mode
	if not wanted then return false end
	if S.override then return true end
	if db.yieldWorldMap and WorldMapFrame and WorldMapFrame:IsShown() then return false end
	if db.hideInInstance and (kind == "party" or kind == "raid" or kind == "scenario") then return false end
	if db.instanceFallback and kind ~= "none" and kind ~= "pvp" and not UnitPosition("player") and not E.InstanceMap() then return false end
	if db.instanceFallback and not S.houseActive and E.NoMapHere() and not (E.RideHoldsMap and E.RideHoldsMap()) then return false end
	if db.hideInCombat and S.inCombat then return false end
	return true
end

function E.UpdateVisibility()
	if not S.ready then return end
	local map = S.map
	if E.ShouldShow() then
		if not map:IsShown() then map:Show() end
	elseif map:IsShown() and not S.pending then
		map:Hide()
	end
	E.UpdateCluster()
end

function E.OnMapShown()
	if S.mapShown then return end
	if E.ShouldShow() then E.Activate() return end
	-- Shown by Blizzard (zone change) or by the user's toggle? Decide next frame.
	S.pending = true
	S.map:SetAlpha(0)
	C_Timer.After(0, E.ResolvePending)
end

function E.ResolvePending()
	if not S.pending then return end
	S.pending = nil
	if not S.map:IsShown() then return end
	if E.ShouldShow() then E.Activate() else S.map:Hide() end
end

function E.OnMapHidden()
	S.pending = nil
	E.Deactivate()
end

function E.OnToggle(map)                       -- post-hook of BattlefieldMapFrame:Toggle (Shift-M)
	if map:IsShown() then
		-- Remember why it was forced, so only that situation clears it again.
		if S.pending then S.override = (WorldMapFrame and WorldMapFrame:IsShown()) and "world" or "rules" end
	else
		S.override = nil
	end
	E.UpdateHouseView()
end

function E.UpdateCluster()
	local mc = MinimapCluster
	if not mc then return end
	-- "Hide the minimap" inside houses keeps the Blizzard minimap hidden too.
	local houseHide = S.inHouse and E.HouseMode() == "HIDE" and GetCVar("showBattlefieldMinimap") == "1"
	local want = (S.mapShown or houseHide) and db.replaceMinimap and not S.editMode
	if want then
		if not S.clusterHidden then S.clusterHidden = true; E.ClusterOff() end
	elseif S.clusterHidden then
		S.clusterHidden = false
		E.ClusterOn()
	end
	if S.overlay then E.ApplyDifficulty() end
end

-- The Blizzard minimap steps aside by turning invisible and letting the mouse through,
-- never by Hide/Show: the cluster is an Edit Mode frame, and showing or hiding it from an
-- add-on runs the game's whole layout (action bars, buffs) under the add-on's taint. In a
-- fight that layout can't place the action bars, and they vanish. Alpha and mouse run no
-- handlers, so this is safe at any time, in combat too.
S.clusterMouse = {}
local function MouseOff(f)
	if S.grabbed[f] or f == Minimap and S.radarEmbedded then return end
	if f.IsForbidden and f:IsForbidden() then return end
	if f.EnableMouse and f.IsMouseEnabled and not (f.IsProtected and f:IsProtected()) then
		if S.clusterMouse[f] == nil then S.clusterMouse[f] = f:IsMouseEnabled() end
		f:EnableMouse(false)
		if f.EnableMouseWheel and f.IsMouseWheelEnabled then
			if S.clusterMouse[f] and f:IsMouseWheelEnabled() then S.clusterWheel = S.clusterWheel or {}; S.clusterWheel[f] = true end
			f:EnableMouseWheel(false)
		end
	end
	for _, child in ipairs({ f:GetChildren() }) do pcall(MouseOff, child) end
end
function E.ClusterOff()
	local mc = MinimapCluster
	if not mc then return end
	S.clusterAlpha = S.clusterAlpha or mc:GetAlpha()
	mc:SetAlpha(0)
	pcall(MouseOff, mc)
end
function E.ClusterOn()
	local mc = MinimapCluster
	if not mc then return end
	mc:SetAlpha(S.clusterAlpha or 1); S.clusterAlpha = nil
	for f, on in pairs(S.clusterMouse) do
		if not (f == Minimap and S.radarEmbedded) and not S.grabbed[f] then
			pcall(f.EnableMouse, f, on)
			if S.clusterWheel and S.clusterWheel[f] then pcall(f.EnableMouseWheel, f, true) end
		end
	end
	wipe(S.clusterMouse); S.clusterWheel = nil
	if not mc:IsShown() then mc:Show() end     -- only ever hidden by an older version
end
-- a button going back into the cluster while it's invisible stays out of the mouse's way
function E.ClusterTakesBack(b)
	if S.clusterHidden then pcall(MouseOff, b) end
end
-- a button leaving the cluster gets its own mouse back
function E.ClusterGives(b)
	local on = S.clusterMouse[b]
	if on ~= nil then
		S.clusterMouse[b] = nil
		pcall(b.EnableMouse, b, on)
		if S.clusterWheel and S.clusterWheel[b] then S.clusterWheel[b] = nil; pcall(b.EnableMouseWheel, b, true) end
	end
end

--------------------------------------------------------------------------------
-- Modes
--   NORMAL  GoodMap as you set it up.
--   HERB, ORE, LUMBER, FISH, MOTES
--           farming modes: GoodMap as you set it up, plus what you farm. Pick one
--           and the zone's routes for it come up; in each new zone you're asked.
--   PVP     the whole battleground at once, bigger group dots, no clutter.
--           Turns itself on in battlegrounds and arenas (pvpAuto).
-- S.mode holds the layout in effect (NORMAL or PVP); everything mode-aware reads
-- it. E.FarmKind() is what you farm in a farming mode.
--------------------------------------------------------------------------------
function E.InPvP()
	local _, kind = IsInInstance()
	return kind == "pvp" or kind == "arena"
end

function E.Mode()
	if (db.pvpAuto and S.inPvP) or db.mode == "PVP" then return "PVP" end
	return "NORMAL"
end

-- What you farm in a farming mode: H herbs, O ore, L lumber, F fishing, V void motes.
local MODE_KIND = { HERB = "H", ORE = "O", LUMBER = "L", FISH = "F", MOTES = "V" }
local KIND_MODE = { H = "HERB", O = "ORE", L = "LUMBER", F = "FISH", V = "MOTES" }
function E.FarmKind()
	if S.mode == "PVP" then return nil end
	return MODE_KIND[db.mode]
end

function E.ModeList()
	return { "NORMAL", L["Normal"], "HERB", L["Herbs"], "ORE", L["Ore"], "FISH", L["Fishing"], "PVP", L["Battleground"] }
end
local SLASH_MODE = { normal = "NORMAL", herbs = "HERB", herb = "HERB", ore = "ORE", fish = "FISH",
	fishing = "FISH", pvp = "PVP" }

function E.ApplyMode()
	local mode = E.Mode()
	if mode == S.mode then return end
	local was = S.mode
	S.mode = mode
	E.EndPeek()
	if S.dragging then E.StopMove() end
	E.ApplyAll()
	if (mode == "PVP" or was == "PVP") and S.sc.zoomLevels then E.RestoreZoom(S.sc) end
	if S.farmBack then E.FarmLookUpdate() end
	E.Wake()
end

-- The Farming routes key: opens the zone's routes, or closes them again.
function GoodMap_ToggleFarm()
	if not S.ready then return end
	local w = S.routesWin
	if w and w:IsShown() then w:Hide() else E.ShowRoutes() end
end

-- The Stop key: stops the farming route you're on.
function GoodMap_StopRoute()
	if not S.ready then return end
	if S.farm then E.StopRoute() else Print(L["You're not on a farming route."]) end
end

--------------------------------------------------------------------------------
-- Frame: position, size, scale, border, tab, mouse, alpha
--------------------------------------------------------------------------------
function E.SetupFrame()
	local map, sc = S.map, S.sc
	map:SetMovable(true)
	map:SetClampedToScreen(true)
	map:SetResizable(true)
	map:SetResizeBounds(140, 110, 1600, 1200)
	S.mapMouse = map:IsMouseEnabled()

	S.hidden = CreateFrame("Frame")
	S.hidden:Hide()

	-- The tab: drag moves the map, right-click opens our menu.
	local tab = BattlefieldMapTab
	tab:SetUserPlaced(false)
	tab:SetText(TITLE)
	if PanelTemplates_TabResize then PanelTemplates_TabResize(tab, 0) end
	tab:SetScript("OnClick", function(self, button) if button == "RightButton" then E.ShowMenu(self) end end)
	tab:SetScript("OnDragStart", function() E.StartMove() end)
	tab:SetScript("OnDragStop", function() E.StopMove() end)

	-- Shift + drag on the map moves it; middle-click opens tracking.
	sc:HookScript("OnMouseDown", function(self, button)
		if button == "LeftButton" and IsShiftKeyDown() and not db.locked then
			local info = self.mouseButtonInfo and self.mouseButtonInfo.LeftButton
			if info then info.down = false end   -- cancel the map's own panning
			E.StartMove()
		end
	end)
	sc:HookScript("OnMouseUp", function(_, button)
		if S.dragging and button == "LeftButton" then E.StopMove()
		elseif button == "MiddleButton" then E.OpenTracking() end
	end)

	-- Resize grip (visible while hovering an unlocked map)
	local grip = CreateFrame("Button", nil, map)
	grip:SetSize(16, 16)
	grip:SetPoint("BOTTOMRIGHT", sc, "BOTTOMRIGHT", 0, 0)
	grip:SetFrameLevel(9700)
	grip:SetNormalTexture("Interface\\ChatFrame\\UI-ChatIM-SizeGrabber-Up")
	grip:SetHighlightTexture("Interface\\ChatFrame\\UI-ChatIM-SizeGrabber-Highlight")
	grip:SetPushedTexture("Interface\\ChatFrame\\UI-ChatIM-SizeGrabber-Down")
	grip:Hide()
	grip:SetScript("OnMouseDown", function(_, button)
		if button == "LeftButton" and not S.peeking then S.sizing = true; map:StartSizing("BOTTOMRIGHT") end
	end)
	grip:SetScript("OnMouseUp", function()
		if not S.sizing then return end
		S.sizing = false
		map:StopMovingOrSizing()
		map:SetUserPlaced(false)
		E.SavePosition()
		if S.round then
			E.Set("roundSize", floor((map:GetWidth() + map:GetHeight()) / 2 + 0.5))
		else
			E.Set("width", floor(map:GetWidth() + 0.5))
			E.Set("height", floor(map:GetHeight() + 0.5))
		end
		E.ApplyPosition()
		E.ApplySize()
		map:OnFrameSizeChanged()
	end)
	S.grip = grip
	map:HookScript("OnSizeChanged", function()
		if S.sizing then Later("liveResize", function() map:OnFrameSizeChanged(); E.LayoutBar(); E.ApplyShape() end, 0.05) end
	end)

	-- Thin border: four textures for the square map, a ring of short lines for the round one
	local border = CreateFrame("Frame", nil, map)
	border:SetAllPoints(sc)
	border:SetFrameLevel(9400)
	border.edges, border.ring = {}, {}
	for i = 1, 4 do border.edges[i] = border:CreateTexture(nil, "OVERLAY") end
	S.border = border

	-- The round mask. Map tiles, pins, the floor plan and the text shading join it as
	-- they appear. Only hooks watch the map: none of its own fields are changed.
	local mask = map:CreateMaskTexture()
	mask:SetTexture(CIRCLE_MASK, "CLAMPTOBLACKADDITIVE", "CLAMPTOBLACKADDITIVE")
	mask:SetPoint("CENTER", sc, "CENTER", 0, 0)
	mask:SetSize(200, 200)
	S.roundMask = mask
	if map.RefreshDetailLayers then
		hooksecurefunc(map, "RefreshDetailLayers", function() if S.round then E.MaskTiles() end end)
	end
end

-- Map art: every tile of the active detail layers, and the parchment behind them.
function E.MaskTiles()
	local pool = S.map.detailLayerPool
	if pool and pool.EnumerateActive then
		for layer in pool:EnumerateActive() do
			if not layer.gmTileHook and layer.RefreshDetailTiles then
				layer.gmTileHook = true
				hooksecurefunc(layer, "RefreshDetailTiles", function(l) if S.round then MaskRegions(l, 0) end end)
			end
			MaskRegions(layer, 0)
		end
	end
	local bg = S.canvas and S.canvas.TiledBackground
	if bg then Mask(bg) end
end

-- Round or square. Square is GoodMap as it always was.
function E.Diameter()
	local w, h = S.sc:GetWidth(), S.sc:GetHeight()
	if not (w and h) or w <= 0 or h <= 0 then w, h = E.MapSize() end
	return min(w, h)
end

function E.MapSize()
	if db.shape == "ROUND" then
		local d = floor(db.roundSize + 0.5)
		return d, d
	end
	return floor(db.width + 0.5), floor(db.height + 0.5)
end

function E.ApplyShape()
	local round = db.shape == "ROUND"
	local map = S.map
	if S.round ~= round then
		S.round = round
		for t, on in pairs(maskable) do
			if round and not on then t:AddMaskTexture(S.roundMask); maskable[t] = true
			elseif not round and on then t:RemoveMaskTexture(S.roundMask); maskable[t] = false end
		end
		map:ExecuteOnAllPins(function(pin) pin.gmMasked = nil end)
	end
	local d = E.Diameter()
	S.roundMask:SetSize(d, d)
	if round then E.MaskTiles(); E.MaskPins() end
	if S.layers then E.ApplyLayers() end                -- quest areas: the game's on a square map, Pathway's on a round one
	E.ApplyBorder()
	E.ApplyCompass()
end

-- Pins are masked once each; pins that keep making textures are re-checked when they do.
local function MaskPin(pin)
	if pin.gmMasked then return end
	pin.gmMasked = true
	MaskRegions(pin, 2)
	if pin.RefreshOverlays and not pin.gmOverlayHook then
		pin.gmOverlayHook = true
		hooksecurefunc(pin, "RefreshOverlays", function(p) if S.round then MaskRegions(p, 0) end end)
	end
end

function E.MaskPins()
	if S.round and S.map then S.map:ExecuteOnAllPins(MaskPin) end
end

function E.StartMove()
	if db.locked or S.dragging or S.peeking then return end
	S.dragging = true
	S.map:StartMoving()
end

function E.StopMove()
	if not S.dragging then return end
	S.dragging = false
	S.map:StopMovingOrSizing()
	S.map:SetUserPlaced(false)
	E.SavePosition()
	E.ApplyPosition()
end

function E.SavePosition()
	if S.peeking then return end
	local l, t = S.map:GetLeft(), S.map:GetTop()
	if l and t then db.posX, db.posY = l, t end
end

function E.ApplyPosition()
	if S.peeking then return end
	local map = S.map
	map:ClearAllPoints()
	if db.posX and db.posY then
		map:SetPoint("TOPLEFT", UIParent, "BOTTOMLEFT", db.posX, db.posY)
	else
		local s = map:GetScale()           -- default: where the Blizzard minimap lives
		map:SetPoint("TOPRIGHT", UIParent, "TOPRIGHT", -14 / s, -14 / s)
	end
	local tab = BattlefieldMapTab
	tab:ClearAllPoints()
	tab:SetPoint("BOTTOMLEFT", map, "TOPLEFT", 0, 5)
end

function E.ResetPosition()
	db.posX, db.posY = false, false
	E.ApplyPosition()
end

function E.ApplyScale()
	if S.peeking then return end
	local map = S.map
	local new = db.scale
	-- The saved spot is in units of the scale it was saved at. When the scale setting
	-- changes, rescale it so the map stays where it is on screen. (Only then: at load the
	-- map starts at Blizzard's scale, and the spot is already right for db.scale.)
	local was = S.posScale
	if was and db.posX and db.posY and abs(was - new) >= 0.001 then
		db.posX, db.posY = db.posX * was / new, db.posY * was / new
	end
	S.posScale = new
	if abs(map:GetScale() - new) < 0.001 then return end
	map:SetScale(new)
	E.ApplyPosition()
end

function E.ApplySize()
	local map = S.map
	local w, h = E.MapSize()
	if abs(map:GetWidth() - w) > 0.5 or abs(map:GetHeight() - h) > 0.5 then
		map:SetSize(w, h)
		if map:IsShown() then map:OnFrameSizeChanged() else S.sizeDirty = true end
	end
	E.ApplyShape()
	E.LayoutBar()
	E.ApplyText()
	if S.houseActive then E.HouseLayout() end
end

function E.Strata() return db.strata end

function E.ApplyStrata()
	local strata = E.Strata()
	S.map:SetFrameStrata(strata)
	BattlefieldMapTab:SetFrameStrata(strata)
	if S.radarEmbedded then MT(Minimap).SetFrameStrata(Minimap, strata) end
	if S.arrowLayer then E.ApplyUnitPins() end
end

local RING_SEGMENTS = 72
-- Which segments of a ring of n show: solid, dashed or dotted
function E.RingSegmentOn(i, n, pattern)
	if pattern == "DASHED" then return floor((i - 1) / (n / 24)) % 2 == 0 end
	if pattern == "DOTTED" then return (i % 3) == 1 end
	return true
end
-- A ring of lines around a frame's center (the minimap's, or the style page's preview)
function E.DrawRingOn(owner, lines, n, rad, s, r, g, bl, a, pattern)
	local step = 2 * PI / n
	for i = 1, n do
		local l = lines[i]
		if not l then l = owner:CreateLine(nil, "OVERLAY"); lines[i] = l end
		if E.RingSegmentOn(i, n, pattern) then
			local a0, a1 = (i - 1) * step, i * step
			if pattern ~= "DASHED" and pattern ~= "DOTTED" then a1 = a1 + step * 0.15 end   -- a little overlap hides the joints
			l:SetThickness(s)
			l:SetColorTexture(r, g, bl, a)
			l:SetStartPoint("CENTER", owner, rad * cos(a0), rad * sin(a0))
			l:SetEndPoint("CENTER", owner, rad * cos(a1), rad * sin(a1))
			l:Show()
		else
			l:Hide()
		end
	end
	for i = n + 1, #lines do lines[i]:Hide() end
end
function E.DrawRing(r, g, bl, a, s)
	local b = S.border
	E.DrawRingOn(b, b.ring, RING_SEGMENTS, E.Diameter() / 2 + s / 2, s, r, g, bl, a, db.edgeStyle)
end

-- A glow around the round map, in a few styles. It sits just outside the ring.
--   SOFT · NEON · PULSE (quick) · BREATHE (slow and wide) · AURA (wide) ·
--   SHADOW (a dark drop shadow for depth) · DOUBLE (a second thin ring) ·
--   RAINBOW (the color slowly goes around the wheel)
local HALO = "Interface\\AddOns\\Pathway\\GoodMap\\Textures\\"
local RING_LOOK = {
	SOFT    = { tex = "Halo",      alpha = 0.55 },
	NEON    = { tex = "Halo",      alpha = 1 },
	PULSE   = { tex = "Halo",      alpha = 1,    pulse = 1.4 },
	BREATHE = { tex = "Halo-Wide", alpha = 0.85, pulse = 3 },
	AURA    = { tex = "Halo-Wide", alpha = 0.7 },
	SHADOW  = { tex = "Halo-Wide", alpha = 0.9,  dark = true },
	DOUBLE  = { tex = "Halo",      alpha = 0.3,  double = true },
	RAINBOW = { tex = "Halo",      alpha = 0.95, rainbow = true },
	FIRE    = { tex = "Halo",      alpha = 0.5,  fire = true },
}
E.RING_LOOK = RING_LOOK

local function HSV(h)
	local i = floor(h * 6) % 6
	local f = h * 6 - floor(h * 6)
	local q, t = 1 - f, f
	if i == 0 then return 1, t, 0 elseif i == 1 then return q, 1, 0 elseif i == 2 then return 0, 1, t
	elseif i == 3 then return 0, q, 1 elseif i == 4 then return t, 0, 1 end
	return 1, 0, q
end
local function RainbowTick(h)
	local r, g, b = HSV((GetTime() / 12) % 1)
	h.tex:SetVertexColor(r, g, b, h.peak or 1)
	if h.lines2 then for _, l in ipairs(h.lines2) do if l:IsShown() then l:SetColorTexture(r, g, b, 1) end end end
end

-- Builds the glow on any frame (the minimap's, or the style page's preview)
function E.NewHalo(parent, anchor)
	local h = CreateFrame("Frame", nil, parent)
	h:SetPoint("CENTER", anchor, "CENTER")
	h.tex = h:CreateTexture(nil, "BACKGROUND")
	h.tex:SetAllPoints()
	h.pulse = h:CreateAnimationGroup(); h.pulse:SetLooping("BOUNCE")
	h.anim = h.pulse:CreateAnimation("Alpha"); h.anim:SetFromAlpha(0.35); h.anim:SetToAlpha(1); h.anim:SetDuration(1.4)
	if h.anim.SetSmoothing then h.anim:SetSmoothing("IN_OUT") end
	h.lines2 = {}
	return h
end

do
-- The fire ring: flames licking up around the edge, tall over the top and low underneath,
-- each flickering on its own, and embers drifting up off it. All of it the game's own
-- animations (nothing runs in Lua per frame), and none of it runs while the map is hidden.
local FLAMES, EMBERS = 36, 10
local function FireLoop(g)
	-- each time round, an ember starts from a new spot on the ring's upper part
	local e, h = g.ember, g.halo
	local a = math.pi * (0.1 + 0.8 * math.random()) + (math.random() < 0.3 and math.pi * 0.9 or 0)
	e:ClearAllPoints()
	e:SetPoint("CENTER", h, "CENTER", math.cos(a) * h.fireR, math.sin(a) * h.fireR)
	g.move:SetOffset((math.random() - 0.5) * 16, 26 + math.random() * 22)
end
local function BuildFire(h)
	local f = CreateFrame("Frame", nil, h)
	f:SetAllPoints(h)
	f.flames, f.embers = {}, {}
	for i = 1, FLAMES do
		local t = f:CreateTexture(nil, "ARTWORK")
		t:SetTexture(HALO .. "Fire-Flame"); t:SetBlendMode("ADD")
		local g = t:CreateAnimationGroup(); g:SetLooping("BOUNCE")
		local al = g:CreateAnimation("Alpha"); al:SetFromAlpha(0.55); al:SetToAlpha(1)
		local sc = g:CreateAnimation("Scale")
		if sc.SetScaleFrom then sc:SetScaleFrom(0.86, 0.86); sc:SetScaleTo(1.12, 1.12) end
		local dur = 0.22 + math.random() * 0.35
		al:SetDuration(dur); sc:SetDuration(dur * (0.8 + math.random() * 0.5))
		t.flicker = g
		f.flames[i] = t
	end
	for i = 1, EMBERS do
		local e = f:CreateTexture(nil, "OVERLAY")
		e:SetTexture(HALO .. "Fire-Ember"); e:SetBlendMode("ADD")
		e:SetAlpha(0)
		local g = e:CreateAnimationGroup(); g:SetLooping("REPEAT")
		local dur = 1.4 + math.random() * 1.2
		local inA = g:CreateAnimation("Alpha"); inA:SetFromAlpha(0); inA:SetToAlpha(1); inA:SetDuration(dur * 0.25); inA:SetOrder(1)
		local move = g:CreateAnimation("Translation"); move:SetDuration(dur); move:SetOrder(1)
		local outA = g:CreateAnimation("Alpha"); outA:SetFromAlpha(1); outA:SetToAlpha(0); outA:SetDuration(dur * 0.75)
		outA:SetStartDelay(dur * 0.25); outA:SetOrder(1)
		if move.SetSmoothing then move:SetSmoothing("OUT") end
		g.ember, g.halo, g.move = e, h, move
		g:SetScript("OnLoop", FireLoop)
		e.drift = g
		f.embers[i] = e
	end
	return f
end
local function LayFire(h, d)
	local f = h.fire
	local R = d / 2 - 2
	h.fireR = R
	for i, t in ipairs(f.flames) do
		local a = 2 * math.pi * (i - 1) / FLAMES
		local ox, oy = math.cos(a), math.sin(a)
		-- fire rises: lean every tongue upward, tallest over the top
		local dx, dy = ox, oy + 1.1
		local len = math.sqrt(dx * dx + dy * dy); dx, dy = dx / len, dy / len
		local up = (oy + 1) / 2
		local hgt = d * (0.07 + 0.11 * up ^ 1.4) * (0.8 + ((i * 37) % 10) / 25)
		t:SetSize(hgt / 2, hgt)
		t:ClearAllPoints()
		t:SetPoint("CENTER", h, "CENTER", ox * R + dx * hgt * 0.4, oy * R + dy * hgt * 0.4)
		t:SetRotation(math.atan2(dy, dx) - math.pi / 2)
		if not t.flicker:IsPlaying() then t.flicker:Play() end
	end
	for _, e in ipairs(f.embers) do
		local s = 5 + math.random() * 5
		e:SetSize(s, s)
		FireLoop(e.drift)
		if not e.drift:IsPlaying() then
			if e.drift.SetStartDelay then e.drift:SetStartDelay(math.random() * 2) end
			e.drift:Play()
		end
	end
	f:Show()
end

-- o: style, d (map diameter), edge (ring thickness), color (palette name)
function E.StyleHalo(h, o)
	local look = RING_LOOK[o.style]
	if h.fire and not (look and look.fire) then
		h.fire:Hide()
		for _, t in ipairs(h.fire.flames) do t.flicker:Stop() end
		for _, e in ipairs(h.fire.embers) do e.drift:Stop() end
	end
	for _, l in ipairs(h.lines2) do l:Hide() end
	h:SetScript("OnUpdate", nil)
	if not look then h:Hide(); h.pulse:Stop() return end
	local d = o.d + (o.edge or 0)
	local wide = look.tex == "Halo-Wide"
	h.tex:SetTexture(HALO .. look.tex)
	h.tex:SetBlendMode(look.dark and "BLEND" or "ADD")
	local size = d / (wide and 0.72 or 0.80)
	h:SetSize(size, size)
	local r, g, bl = E.PaletteColor(o.color)
	if look.dark then r, g, bl = 0, 0, 0 end
	if look.fire then
		r, g, bl = 1, 0.42, 0.08
		if not h.fire then h.fire = BuildFire(h) end
		LayFire(h, d)
	end
	h.peak = look.alpha
	h.tex:SetVertexColor(r, g, bl, look.alpha)
	if look.double then
		local s = max(1, floor((o.edge or 2) / 2 + 0.5))
		E.DrawRingOn(h, h.lines2, 72, d / 2 + 3 + s / 2, s, r, g, bl, 0.9, o.pattern)
	end
	if look.rainbow then h:SetScript("OnUpdate", RainbowTick); RainbowTick(h) end
	h:Show()
	if look.pulse then
		h.anim:SetDuration(look.pulse)
		if not h.pulse:IsPlaying() then h.pulse:Play() end
	else
		h.pulse:Stop(); h:SetAlpha(1)
	end
end
end

function E.ApplyRingGlow()
	local b = S.border
	if not b then return end
	if not S.halo then
		S.halo = E.NewHalo(S.map, b)
		S.halo:SetFrameLevel(max(1, S.map:GetFrameLevel() - 1))
	end
	local style = S.round and db.ringGlow or "NONE"
	E.StyleHalo(S.halo, { style = style, d = E.Diameter(), edge = db.border ~= "NONE" and db.borderSize or 0,
		color = db.ringColor, pattern = db.edgeStyle })
end

function E.ApplyBorder()
	local bf = S.map.BorderFrame
	local round = S.round
	if bf then
		bf:SetShown(db.border == "BLIZZARD" and not round)
		if bf.CloseButton then bf.CloseButton:SetShown(not db.hideClose) end
	end
	local b = S.border
	local e = b.edges
	E.ApplyRingGlow()
	if db.border == "NONE" or (db.border == "BLIZZARD" and not round) then b:Hide() return end
	local c = CreateColorFromHexString and CreateColorFromHexString(db.borderColor or "ff000000")
	local r, g, bl, a = 0, 0, 0, 1
	if c then r, g, bl, a = c:GetRGBA() end
	local s = db.borderSize
	if db.border == "BLIZZARD" then r, g, bl, a, s = 0.72, 0.6, 0.36, 1, 2   -- a gold ring, like the minimap's
	elseif db.border == "CLASS" then r, g, bl = E.ClassColor(); a = 1
	elseif db.border == "ACCENT" then local ac = Pathway.ACCENT; r, g, bl, a = ac[1], ac[2], ac[3], 1 end
	if round then
		for i = 1, 4 do e[i]:Hide() end
		E.DrawRing(r, g, bl, a, s)
		b:Show()
		return
	end
	for i = 1, #b.ring do b.ring[i]:Hide() end
	for i = 1, 4 do e[i]:SetColorTexture(r, g, bl, a); e[i]:ClearAllPoints(); e[i]:Show() end
	e[1]:SetPoint("BOTTOMLEFT", b, "TOPLEFT", -s, 0);     e[1]:SetPoint("BOTTOMRIGHT", b, "TOPRIGHT", s, 0);       e[1]:SetHeight(s)
	e[2]:SetPoint("TOPLEFT", b, "BOTTOMLEFT", -s, 0);     e[2]:SetPoint("TOPRIGHT", b, "BOTTOMRIGHT", s, 0);       e[2]:SetHeight(s)
	e[3]:SetPoint("TOPRIGHT", b, "TOPLEFT", 0, 0);        e[3]:SetPoint("BOTTOMRIGHT", b, "BOTTOMLEFT", 0, 0);     e[3]:SetWidth(s)
	e[4]:SetPoint("TOPLEFT", b, "TOPRIGHT", 0, 0);        e[4]:SetPoint("BOTTOMLEFT", b, "BOTTOMRIGHT", 0, 0);     e[4]:SetWidth(s)
	b:Show()
end

-- Compass: N, E, S and W just inside the round map's rim, and a soft glow that
-- slides around the ring to show which way you face. The map stays north-up.
local GLOW_N, GLOW_SPAN = 16, 0.6          -- segments, half the arc in radians
local GLOW_COLOR = { 0.21, 0.82, 0.5 }     -- GoodMap green

-- Colors you can pick for the facing glow and the player arrow.
local PALETTE = {
	GREEN = GLOW_COLOR, GOLD = { 1, 0.82, 0 }, WHITE = { 1, 1, 1 }, BLUE = { 0.3, 0.62, 1 },
	CYAN = { 0.3, 0.9, 1 }, PURPLE = { 0.72, 0.48, 1 }, PINK = { 1, 0.5, 0.8 }, RED = { 1, 0.3, 0.3 },
	ORANGE = { 1, 0.6, 0.2 },
}
function E.PaletteColor(name, custom)
	if name == "CLASS" then return E.ClassColor() end
	if name == "ACCENT" then local a = Pathway.ACCENT; return a[1], a[2], a[3] end
	if name == "CUSTOM" and type(custom) == "string" and CreateColorFromHexString then
		local ok, c = pcall(CreateColorFromHexString, custom)
		if ok and c then local r, g, b = c:GetRGB(); return r, g, b end
	end
	local c = PALETTE[name] or GLOW_COLOR
	return c[1], c[2], c[3]
end
function E.SetupCompass()
	local f = CreateFrame("Frame", nil, S.overlay)
	f:SetAllPoints(S.overlay)
	f:EnableMouse(false)
	f.letters = {}
	local names = {}
	for w in L["N E S W"]:gmatch("%S+") do names[#names + 1] = w end
	for i = 1, 4 do
		local fs = f:CreateFontString(nil, "OVERLAY", "GameFontNormal")
		fs:SetText(names[i] or ("NESW"):sub(i, i))
		if i == 1 then fs:SetTextColor(1, 0.82, 0) else fs:SetTextColor(0.92, 0.92, 0.92) end
		f.letters[i] = fs
	end
	S.compass = f

	local g = CreateFrame("Frame", nil, S.overlay)
	g:SetPoint("CENTER", S.overlay, "CENTER", 0, 0)
	g:SetSize(1, 1)
	g.back = {}
	for i = 1, GLOW_N do
		local l = g:CreateLine(nil, "OVERLAY")
		l:SetBlendMode("ADD")
		g[i] = l
		local b = g:CreateLine(nil, "OVERLAY")
		b:SetBlendMode("ADD")
		g.back[i] = b
	end
	g:Hide()
	S.glow = g

	-- The facer reads your facing once a frame; the glow and the arrow redraw only when it changes.
	local facer = CreateFrame("Frame")
	facer:Hide()
	facer:SetScript("OnUpdate", Pathway.Perf.W("Minimap", E.FaceTick))
	S.facer = facer
end

function E.ApplyCompass()
	local f = S.compass
	if not f then return end
	local on = db.compass and S.round and not S.houseActive and not E.Busy()
	f:SetShown(on)
	local d = E.Diameter()
	if on then
		local font = GameFontNormal:GetFont()
		local r = d / 2 - 9
		local pos = { { 0, r }, { r, 0 }, { 0, -r }, { -r, 0 } }
		for i, fs in ipairs(f.letters) do
			fs:SetFont(font, d < 200 and 10 or d < 400 and 11 or 13, "OUTLINE")
			fs:ClearAllPoints()
			fs:SetPoint("CENTER", f, "CENTER", pos[i][1], pos[i][2])
		end
	end
	local g = S.glow
	g.r = d / 2
	E.StyleGlow(g)
	S.facing = nil                                          -- redraw on the next frame
	if S.flightHud then E.FlightLayout() end                -- flight mode follows the size and the shape
	if S.farmLook then E.FarmLayout() end
end

-- The facing glow's styles: how wide, how it fades, where its bright part sits.
--   ARC a soft arc · WIDE a broad one · BEAM narrow and bright · COMET bright where
--   you face, trailing behind · TWIN a bright front and a faint back ·
--   SPOT a small bright point · FAN a very wide, faint fan
local GLOW_STYLES = {
	ARC = { span = 0.6, thick = 1 }, WIDE = { span = 1.1, thick = 1 }, BEAM = { span = 0.22, thick = 1.6 },
	COMET = { span = 0.55, thick = 1.2, comet = true }, TWIN = { span = 0.5, thick = 1, twin = true },
	SPOT = { span = 0.13, thick = 2.4 }, FAN = { span = 1.6, thick = 0.8 },
}
function E.GlowStyle(name) return GLOW_STYLES[name] or GLOW_STYLES.ARC end

-- colors and fades for a glow made of GLOW_N lines (the minimap's, or a preview's)
function E.StyleGlow(g, o)
	o = o or db
	local st = E.GlowStyle(o.glowStyle)
	g.st = st
	local thick = max(3, (o.borderSize or 2) + 2) * st.thick * (o.glowWidth or 1)
	local cr, cg, cb = E.PaletteColor(o.glowColor, o.glowCustom)
	local peak = o.glowAlpha or 0.95
	for i = 1, GLOW_N do
		local t = (i - 0.5) / GLOW_N                     -- 0..1 along the arc
		local a
		if st.comet then a = peak * t ^ 1.6               -- tail behind, bright at the head
		elseif st.twin then a = peak * cos(abs(t * 2 - 1) * PI / 2) ^ 2
		else a = peak * cos(abs(t * 2 - 1) * PI / 2) ^ 2 end
		g[i]:SetThickness(thick)
		g[i]:SetColorTexture(cr, cg, cb, a)
	end
	if g.back then
		for i = 1, GLOW_N do g.back[i]:SetThickness(thick * 0.8); g.back[i]:SetColorTexture(cr, cg, cb, peak * 0.25 * cos(abs((i - 0.5) / GLOW_N * 2 - 1) * PI / 2) ^ 2) end
	end
end

function E.DrawGlowOn(g, a)
	local st = g.st or GLOW_STYLES.ARC
	local span = st.span
	local r, step = g.r, 2 * span / GLOW_N
	local start = st.comet and (a - 2 * span) or (a - span)
	for i = 1, GLOW_N do
		local a0 = start + (i - 1) * step
		local a1 = a0 + step * 1.15                              -- a little overlap hides the joints
		g[i]:SetStartPoint("CENTER", g, r * cos(a0), r * sin(a0))
		g[i]:SetEndPoint("CENTER", g, r * cos(a1), r * sin(a1))
	end
	if g.back then
		local show = st.twin and true or false
		for i = 1, GLOW_N do
			local l = g.back[i]
			l:SetShown(show and g:IsShown())
			if show then
				local a0 = a + PI - span + (i - 1) * step
				local a1 = a0 + step * 1.15
				l:SetStartPoint("CENTER", g, r * cos(a0), r * sin(a0))
				l:SetEndPoint("CENTER", g, r * cos(a1), r * sin(a1))
			end
		end
	end
end

function E.DrawGlow(a) E.DrawGlowOn(S.glow, a) end

function E.FaceTick()
	local facing = GetPlayerFacing()
	if not facing or issecret(facing) then return end        -- the slow tick notices and hides what needs it
	if S.facing and abs(facing - S.facing) < 0.004 then return end
	S.facing = facing
	if S.arrowActive then S.arrow.tex:SetRotation(facing) end
	if S.glowOn then E.DrawGlow(facing + PI / 2) end          -- facing 0 is north, up on the map
end

-- Which of the glow and the custom arrow are wanted right now (slow tick).
function E.UpdateHeading()
	local facing = GetPlayerFacing()
	local hasFacing = facing ~= nil and not issecret(facing)
	local shown = S.mapShown and not S.houseActive and hasFacing
	local arrow = (shown and db.arrowStyle ~= "BLIZZARD" and S.posOK and (S.map:GetMapID() == S.playerMap or S.flightOn)
		and not (S.radarVisible and db.radarHideArrow) and not S.detail) and true or false
	if arrow ~= (S.arrowActive or false) then
		S.arrowActive = arrow
		S.arrow:SetShown(arrow)
		if arrow then S.ax = nil; E.Wake() end
		S.facing = nil
		E.ApplyUnitPins()
	end
	local glow = (shown and db.compassGlow and S.round and not E.Busy()) and true or false
	if glow ~= (S.glowOn or false) then
		S.glowOn = glow
		S.glow:SetShown(glow)
		S.facing = nil
	end
	S.facer:SetShown(arrow or glow)
end

-- Player arrow styles. Blizzard's own arrow stays unless you pick one of these.
-- Yours has a layer of its own above the map and the radar: the minimap draws
-- its own arrow over everything inside the map, and add-ons can no longer hide it.
-- The layer is see-through, clipped to the map and follows you, so the arrow looks
-- like part of the map.
function E.SetupArrow()
	local layer = CreateFrame("Frame", nil, S.map)
	layer:SetAllPoints(S.sc)
	layer:SetClipsChildren(true)
	layer:EnableMouse(false)
	S.arrowLayer = layer
	local a = CreateFrame("Frame", nil, layer)
	a:SetSize(24, 24)
	a:SetPoint("CENTER", S.radarAnchor, "CENTER", 0, 0)
	a:Hide()
	a.tex = a:CreateTexture(nil, "OVERLAY")
	a.tex:SetAllPoints()
	a.tex:SetTexture("Interface\\Minimap\\MinimapArrow")
	Mask(a.tex)
	S.arrow = a
end

-- The classic arrow is Blizzard's minimap arrow; the others ship with GoodMap as
-- white shapes (with a dark outline) that take any color.
local ARROW_TEXTURES = {
	CLASSIC = "Interface\\Minimap\\MinimapArrow",
	DART = "Interface\\AddOns\\Pathway\\GoodMap\\Textures\\Arrow-Dart",
	CHEVRON = "Interface\\AddOns\\Pathway\\GoodMap\\Textures\\Arrow-Chevron",
	TRIANGLE = "Interface\\AddOns\\Pathway\\GoodMap\\Textures\\Arrow-Triangle",
	NEEDLE = "Interface\\AddOns\\Pathway\\GoodMap\\Textures\\Arrow-Needle",
	BEACON = "Interface\\AddOns\\Pathway\\GoodMap\\Textures\\Arrow-Beacon",
}

function E.ArrowTexture(style) return ARROW_TEXTURES[style] or ARROW_TEXTURES.CLASSIC end
E.GLOW_N = GLOW_N

function E.ApplyArrowStyle()
	local a = S.arrow
	if not a then return end
	local style, color = db.arrowStyle, db.arrowColor
	a.tex:SetTexture(ARROW_TEXTURES[style] or ARROW_TEXTURES.CLASSIC)
	if style == "CLASSIC" and color == "GOLD" then
		a.tex:SetDesaturated(false)                    -- the arrow's own gold
		a.tex:SetVertexColor(1, 1, 1)
	else
		a.tex:SetDesaturated(style == "CLASSIC")
		a.tex:SetVertexColor(E.PaletteColor(color, db.arrowCustom))
	end
	local size = db.playerSize * 2
	a:SetSize(size, size)
	E.ApplyUnitPins()
	S.facing = nil
	if S.ready and S.mapShown then E.UpdateHeading() end
end

-- Blizzard's group members on the map (you included) and the pin that draws them.
-- Found among the map's data providers, so it doesn't depend on a field name.
function E.GroupMembers()
	local map, gp = S.map, S.groupProvider
	local live = map.dataProviders
	if not (gp and (not live or live[gp])) then
		gp = map.groupMembersDataProvider
		if not (type(gp) == "table" and type(gp.SetUnitPinSize) == "function") then
			gp = nil
			for dp in pairs(live or {}) do
				if type(dp) == "table" and type(dp.SetUnitPinSize) == "function" then gp = dp break end
			end
		end
		S.groupProvider, S.groupPin = gp, nil
	end
	local pin = gp and gp.pin or S.groupPin
	if not pin and gp and map.ExecuteOnAllPins then
		map:ExecuteOnAllPins(function(p) if not pin and p.SynchronizePinSizes and p.SetPinSize then pin = p end end)
		S.groupPin = pin
	end
	return gp, pin
end

-- /goodmap arrow: which player arrows GoodMap sees, and how they're stacked.
function E.PrintArrowInfo()
	local gp, pin = E.GroupMembers()
	local a = S.arrow
	local function where(f)
		if not (f and f.GetFrameLevel) then return "none" end
		return format("%s %d%s", f:GetFrameStrata(), f:GetFrameLevel(), f:IsVisible() and "" or " (hidden)")
	end
	Print(format("arrow %s%s, style %s, size %s  |  group provider %s, pin %s, your size %s",
		where(a), S.arrowTop and " (top test)" or "", tostring(db.arrowStyle), tostring(db.playerSize),
		gp and (gp == S.map.groupMembersDataProvider and "found" or "found by search") or "none", where(pin), tostring(S.uPlayer)))
	Print(format("radar %s, minimap %s  |  map %s, on your zone %s",
		S.radarVisible and "showing" or (S.radarEmbedded and "embedded" or "off"), where(Minimap), where(S.map),
		tostring(S.map:GetMapID() == S.playerMap)))
end

-- /goodmap where: which map the game says you're on, and which one GoodMap shows.
function E.PrintWhere()
	local wx, wy, _, inst = UnitPosition("player")
	local _, kind = IsInInstance()
	Print(format("%s / %s  |  instance %s (%s)  |  position %s", GetZoneText() or "?", GetSubZoneText() or "",
		tostring(inst), tostring(kind), wx and "yes" or "no"))
	local id, chain, guard = C_Map.GetBestMapForUnit and C_Map.GetBestMapForUnit("player"), {}, 0
	while id and id ~= 0 and guard < 8 do
		local info = C_Map.GetMapInfo(id)
		local r = MapRect(id)
		chain[#chain + 1] = format("%d %s (type %s, art %s, inst %s)", id, info and info.name or "?",
			tostring(info and info.mapType), HasArt(id) and "yes" or "no", r and tostring(r[5]) or "-")
		id, guard = info and info.parentMapID, guard + 1
	end
	Print("game's map: " .. (#chain > 0 and table.concat(chain, " > ") or "none"))
	local found = E.FindMapAt()
	Print(format("GoodMap shows %s, found here %s, on it %s, hands over %s", tostring(S.playerMap), tostring(found),
		tostring(S.playerMap and PlayerPos(S.playerMap) ~= nil), tostring(E.NoMapHere())))
end

-- Your arrow's layer: above the radar and everything the minimap carries, below
-- GoodMap's border and text.
function E.ArrowLevel()
	local level = (S.radarHolder and S.radarHolder:GetFrameLevel() or 1500) + 30
	if S.radarEmbedded and Minimap then level = max(level, Minimap:GetFrameLevel() + 30) end
	return min(level, 9300)
end


function E.ApplyTab()
	-- Re-parenting keeps Blizzard's tab fade logic happy while keeping the tab invisible.
	BattlefieldMapTab:SetParent(db.hideTab and S.hidden or UIParent)
end

-- Click-through: the scroll container, the map frame, our buttons and every pin stop taking the mouse.
local function PinMouse(pin, on)
	if on then
		if pin.gmStored then
			pin:SetMouseClickEnabled(pin.gmClick)
			pin:SetMouseMotionEnabled(pin.gmMotion)
			pin.gmStored = nil
		end
	elseif not pin.gmStored then
		pin.gmStored, pin.gmClick, pin.gmMotion = true, pin:IsMouseClickEnabled(), pin:IsMouseMotionEnabled()
		pin:SetMouseClickEnabled(false)
		pin:SetMouseMotionEnabled(false)
	end
end

function E.SetInteractive(on)
	if S.interactive == on then return end
	S.interactive = on
	S.sc:EnableMouse(on)
	S.sc:EnableMouseWheel(on)
	S.map:EnableMouse(on and S.mapMouse)
	if S.house then S.house:EnableMouse(on); S.house:EnableMouseWheel(on) end
	for _, b in ipairs(S.overlayButtons) do b:EnableMouse(on) end
	for f in pairs(S.hoverFrames or {}) do f:SetMouseMotionEnabled(on) end
	S.map:ExecuteOnAllPins(PinMouse, on)
	E.RadarMouse()
end

function E.UpdateAltMouse()
	if S.markKey then return E.ApplyMouse() end
	E.SetInteractive(IsAltKeyDown() and S.map:IsMouseOver() or false)
end

function E.ApplyMouse()
	if S.markKey then E.SetInteractive(true)            -- the mark key makes the map clickable while held
	elseif db.mouse == "NONE" then E.SetInteractive(false)
	elseif db.mouse == "ALT" then E.SetInteractive(IsAltKeyDown() and S.map:IsMouseOver() or false)
	else E.SetInteractive(true) end
end

function E.TargetAlpha()
	if S.hovered or S.peeking then return 1 end
	if S.inCombat then return min(db.idleAlpha, db.combatAlpha) end
	return db.idleAlpha
end

function E.ApplyAlpha()
	local map = S.map
	if S.pending then return end
	FadeTo(map, E.TargetAlpha())
	if (S.hovered or S.peeking) and db.fullOnHover then map:SetGlobalAlpha(1)
	else map:RefreshAlpha() end
end

--------------------------------------------------------------------------------
-- Overlay: zone name, clock, coordinates, zoom buttons, waypoint arrow
--------------------------------------------------------------------------------
local function OverlayButton(parent)
	local b = CreateFrame("Button", nil, parent)
	b:RegisterForClicks("LeftButtonUp", "RightButtonUp")
	b:SetScript("OnLeave", HideTooltip)
	S.overlayButtons[#S.overlayButtons + 1] = b
	return b
end

function E.SetupOverlay()
	local ov = CreateFrame("Frame", nil, S.map)
	ov:SetAllPoints(S.sc)
	ov:SetFrameLevel(9500)
	ov:EnableMouse(false)
	S.overlay, S.overlayButtons = ov, {}

	-- The text sits on its own layer so it can fade as one (calmer in combat).
	local tl = CreateFrame("Frame", nil, ov)
	tl:SetAllPoints(ov)
	tl:EnableMouse(false)
	S.textLayer = tl
	-- Soft dark strips behind the text keep it readable on busy map art.
	S.shades = {}
	for i = 1, 2 do
		local t = tl:CreateTexture(nil, "BACKGROUND")
		t:SetTexture("Interface\\Buttons\\WHITE8X8")
		t:Hide()
		Mask(t)
		S.shades[i] = t
	end

	S.zoneText = tl:CreateFontString(nil, "OVERLAY", "GameFontNormal")
	S.zoneText:SetWordWrap(false)
	S.cursorText = tl:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
	S.flightText = tl:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
	S.flightText:SetWordWrap(false)
	S.flightText:Hide()

	-- Status line: frame rate, latency and your lowest durability.
	local status = OverlayButton(tl)
	status.text = status:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
	status.text:SetPoint("CENTER")
	status:SetScript("OnEnter", function(self) Tooltip(self, L["Status line"], L["Frame rate, latency and your lowest durability."]) end)
	S.status = status

	-- Clock: left-click stopwatch & alarms, right-click calendar.
	local clock = OverlayButton(tl)
	clock.text = clock:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
	clock.text:SetPoint("CENTER")
	clock:SetScript("OnClick", function(_, button)
		if button == "RightButton" then if ToggleCalendar then ToggleCalendar() end
		elseif ToggleTimeManager then ToggleTimeManager() end
	end)
	clock:SetScript("OnEnter", function(self)
		GameTooltip:SetOwner(self, "ANCHOR_LEFT")
		if GameTime_UpdateTooltip then GameTime_UpdateTooltip() else GameTooltip:SetText(TIMEMANAGER_TITLE or L["Clock"]) end
		GameTooltip:AddLine(" ")
		GameTooltip:AddLine(L["Left-click: stopwatch and alarm"], 1, 1, 1)
		GameTooltip:AddLine(L["Right-click: calendar"], 1, 1, 1)
		GameTooltip:Show()
	end)
	S.clock = clock

	-- Player coordinates: click to re-centre, Shift-click to share your spot in chat.
	local coords = OverlayButton(tl)
	coords.text = coords:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
	coords.text:SetPoint("CENTER")
	coords:SetScript("OnClick", function() if IsShiftKeyDown() then E.ShareLocation() else E.Recenter() end end)
	coords:SetScript("OnEnter", function(self) Tooltip(self, L["Your position"], L["Click: center the map on you"], L["Shift-click: share your location in chat"]) end)
	S.coords = coords
	S.playerText = coords.text

	-- Zoom buttons (shown while hovering)
	local function zoomButton(atlas, delta, w, h)
		local b = OverlayButton(ov)
		b:SetSize(w, h)
		b:SetNormalAtlas(atlas)
		b:SetPushedAtlas(atlas .. "-down")
		b:SetHighlightAtlas(atlas .. "-mouseover")
		b:SetScript("OnClick", function() E.Zoom(delta) end)
		b:Hide()
		return b
	end
	S.zoomIn = zoomButton("ui-hud-minimap-zoom-in", 1, 17, 17)
	S.zoomOut = zoomButton("ui-hud-minimap-zoom-out", -1, 17, 9)
	S.zoomIn:SetPoint("BOTTOMRIGHT", ov, "BOTTOMRIGHT", -6, 30)
	S.zoomOut:SetPoint("TOP", S.zoomIn, "BOTTOM", 0, -3)

	-- Off-map arrows with distance: your tracked target, and your corpse (blue).
	local function edgeArrow()
		local arrow = CreateFrame("Frame", nil, ov)
		arrow:SetSize(20, 20)
		arrow:Hide()
		arrow.tex = arrow:CreateTexture(nil, "OVERLAY")
		arrow.tex:SetAllPoints()
		if C_Texture and C_Texture.GetAtlasInfo and C_Texture.GetAtlasInfo("Navigation-Tracked-Arrow") then
			arrow.tex:SetAtlas("Navigation-Tracked-Arrow")
		else
			arrow.tex:SetTexture("Interface\\Minimap\\MinimapArrow")
		end
		arrow.text = arrow:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
		return arrow
	end
	S.wpArrow = edgeArrow()
	S.corpseArrow = edgeArrow()
	S.corpseArrow.tex:SetVertexColor(0.7, 0.85, 1)
	S.corpseArrow.text:SetTextColor(0.7, 0.85, 1)
	local function arrowTip(self, title)
		GameTooltip:SetOwner(self, "ANCHOR_CURSOR")
		GameTooltip:SetText(title, 1, 0.82, 0)
		local t = self.text:IsShown() and self.text:GetText()
		if type(t) == "string" and t ~= "" then
			for line in t:gmatch("[^\n]+") do GameTooltip:AddLine(line, 1, 1, 1) end
		end
		GameTooltip:Show()
	end
	Hoverable(S.wpArrow, function(self) arrowTip(self, E.WaypointTitle()) end)
	Hoverable(S.corpseArrow, function(self) arrowTip(self, L["Your corpse"]) end)

	-- Hover the zone name for the zone, the sub-zone and its PvP status, like the minimap's.
	local zh = CreateFrame("Frame", nil, tl)
	zh:SetAllPoints(S.zoneText)
	Hoverable(zh, E.ZoneTooltip)
	S.zoneHover = zh
end

-- What the edge arrow points at.
function E.WaypointTitle()
	local ST = C_SuperTrack
	if ST and ST.IsSuperTrackingUserWaypoint and ST.IsSuperTrackingUserWaypoint() then return L["Your map pin"] end
	local q = ST and ST.GetSuperTrackedQuestID and ST.GetSuperTrackedQuestID()
	if q and not issecret(q) and q > 0 and C_QuestLog.GetTitleForQuestID then
		local t = C_QuestLog.GetTitleForQuestID(q)
		if type(t) == "string" and not issecret(t) and t ~= "" then return t end
	end
	return L["Your tracked target"]
end

local PVP_LINES = { sanctuary = "SANCTUARY_TERRITORY", arena = "FREE_FOR_ALL_TERRITORY", contested = "CONTESTED_TERRITORY", combat = "COMBAT_ZONE" }
function E.ZoneTooltip(owner)
	local fs = S.zoneText
	local shown = fs:GetText()
	if not (fs:IsShown() and type(shown) == "string" and shown ~= "") then return end
	GameTooltip:SetOwner(owner, "ANCHOR_CURSOR")
	local mapID = S.map:GetMapID()
	if S.houseActive or (mapID and S.playerMap and mapID ~= S.playerMap) then
		GameTooltip:SetText(shown, 1, 0.82, 0)
	else
		local zone, sub = GetZoneText(), GetSubZoneText()
		local pvp, _, faction = Pathway.ZonePVP()
		local c = PVP_COLOR[pvp] or DEFAULT_COLOR
		GameTooltip:SetText((type(zone) == "string" and zone ~= "") and zone or shown, c[1], c[2], c[3])
		if type(sub) == "string" and sub ~= "" and sub ~= zone then GameTooltip:AddLine(sub, 1, 1, 1) end
		local line = PVP_LINES[pvp] and _G[PVP_LINES[pvp]]
		if (pvp == "friendly" or pvp == "hostile") and type(faction) == "string" and type(_G.FACTION_CONTROLLED_TERRITORY) == "string" then
			line = format(_G.FACTION_CONTROLLED_TERRITORY, faction)
		end
		if type(line) == "string" then GameTooltip:AddLine(line, c[1], c[2], c[3]) end
	end
	GameTooltip:Show()
end

function E.ApplyText()
	if not S.overlay then return end
	local font = GameFontNormal:GetFont()
	local zt, ct, ov, fl, st = S.zoneText, S.cursorText, S.overlay, S.flightText, S.status
	zt:SetFont(font, db.zoneTextSize, "OUTLINE")
	ct:SetFont(font, db.coordSize, "OUTLINE")
	fl:SetFont(font, db.coordSize, "OUTLINE")
	st.text:SetFont(font, db.coordSize - 1, "OUTLINE")
	S.playerText:SetFont(font, db.coordSize, "OUTLINE")
	S.clock.text:SetFont(font, db.coordSize + 1, "OUTLINE")
	S.wpArrow.text:SetFont(font, db.coordSize, "OUTLINE")
	S.corpseArrow.text:SetFont(font, db.coordSize, "OUTLINE")

	local pos = db.zoneTextPos
	local top = pos:find("TOP") ~= nil
	local side, edge = top and "TOP" or "BOTTOM", top and "BOTTOM" or "TOP"   -- zone name's edge, the other edge
	local sign = top and 1 or -1
	local mapView = not S.houseActive
	local flying = S.flightLine and db.flightInfo and mapView
	local status = db.statusLine
	local d = E.Diameter()
	zt:ClearAllPoints(); S.clock:ClearAllPoints(); S.coords:ClearAllPoints(); ct:ClearAllPoints()
	fl:ClearAllPoints(); st:ClearAllPoints()
	S.zoomIn:ClearAllPoints()
	local nearDepth, farDepth                   -- how deep the text reaches in from each edge
	local row = db.coordSize + 4
	if S.round then
		-- Zone name near the top of the circle; clock, coordinates and status near the bottom.
		local inset = floor(d * 0.07 + 0.5)
		if db.compass then inset = max(inset, 17) end         -- clear of the N and S
		zt:SetPoint(side, ov, side, 0, -sign * inset)
		zt:SetJustifyH("CENTER")
		zt:SetWidth(max(40, d * 0.56))
		fl:SetPoint(side, zt, edge, 0, -sign * 2)
		fl:SetJustifyH("CENTER")
		ct:SetPoint(side, flying and fl or zt, edge, 0, -sign * 2)
		local last
		S.clock:SetPoint(edge, ov, edge, 0, sign * inset)
		if db.clock then last = S.clock end
		if last then S.coords:SetPoint(edge, last, side, 0, sign * 1)
		else S.coords:SetPoint(edge, ov, edge, 0, sign * inset) end
		if db.playerCoords and mapView then last = S.coords end
		if last then st:SetPoint(edge, last, side, 0, sign * 1)
		else st:SetPoint(edge, ov, edge, 0, sign * inset) end
		nearDepth = inset + db.zoneTextSize + (db.cursorCoords and mapView and row or 0) + (flying and row or 0) + 10
		farDepth = inset + ((db.clock and 1 or 0) + (db.playerCoords and mapView and 1 or 0) + (status and 1 or 0)) * (db.coordSize + 7) + 8
		local r = d / 2
		S.zoomIn:SetPoint("CENTER", ov, "CENTER", floor(r * 0.7 + 0.5), -floor(r * 0.38 + 0.5))
	else
		-- clock sits opposite the zone name; coordinates and status on the other edge
		local h = pos:find("LEFT") and "LEFT" or pos:find("RIGHT") and "RIGHT" or ""
		local x = h == "LEFT" and 5 or h == "RIGHT" and -5 or 0
		zt:SetPoint(pos, ov, pos, x, top and -5 or 5)
		zt:SetJustifyH(h == "" and "CENTER" or h)
		fl:SetPoint(side .. h, zt, edge .. h, 0, -sign * 2)
		fl:SetJustifyH(h == "" and "CENTER" or h)
		local clockPoint = top and (pos:find("RIGHT") and "TOPLEFT" or "TOPRIGHT") or (pos:find("RIGHT") and "BOTTOMLEFT" or "BOTTOMRIGHT")
		S.clock:SetPoint(clockPoint, ov, clockPoint, clockPoint:find("LEFT") and 4 or -4, top and -4 or 4)
		local cy = top and 4 or -4
		S.coords:SetPoint(edge .. "LEFT", ov, edge .. "LEFT", 4, cy)
		st:SetPoint(edge .. "RIGHT", ov, edge .. "RIGHT", -4, cy)
		ct:SetPoint(edge, ov, edge, 0, cy + (top and 1 or -1))
		nearDepth = max(db.zoneText and db.zoneTextSize or 0, db.clock and db.coordSize + 2 or 0) + (flying and row or 0) + 12
		farDepth = db.coordSize + 12
		S.zoomIn:SetPoint("BOTTOMRIGHT", ov, "BOTTOMRIGHT", -6, 30)
	end
	S.clock:SetShown(db.clock)
	S.coords:SetShown(db.playerCoords and mapView)
	ct:SetShown(db.cursorCoords and mapView)
	fl:SetShown(flying)
	st:SetShown(status)
	E.FitZoneText()

	-- The shading follows whatever text is on each edge.
	local nearText, farText
	if S.round then
		nearText = db.zoneText or (db.cursorCoords and mapView) or flying
		farText = db.clock or (db.playerCoords and mapView) or status
	else
		nearText = db.zoneText or db.clock or flying
		farText = ((db.playerCoords or db.cursorCoords) and mapView) or status
	end
	local shades = S.shades
	local function shade(t, want, at, depth)
		if not (want and db.textShade) then t:Hide() return end
		t:ClearAllPoints()
		t:SetPoint(at .. "LEFT", ov, at .. "LEFT", 0, 0)
		t:SetPoint(at .. "RIGHT", ov, at .. "RIGHT", 0, 0)
		t:SetHeight(depth)
		local dark, clear = CreateColor(0, 0, 0, 0.55), CreateColor(0, 0, 0, 0)
		-- vertical gradients run bottom (first colour) to top (second)
		if at == "TOP" then t:SetGradient("VERTICAL", clear, dark) else t:SetGradient("VERTICAL", dark, clear) end
		t:Show()
	end
	shade(shades[1], nearText, side, nearDepth)
	shade(shades[2], farText, edge, farDepth)

	S.coordFmt = format("%%.%df, %%.%df", db.coordDecimals, db.coordDecimals)
	S.lastPT, S.lastCT, S.lastClock, S.lastStatus, S.lastFlight = nil, nil, nil, nil, nil
	E.UpdateZoneText()
	E.UpdateClock()
	E.UpdateStatus()
	E.UpdateFlight()
	E.ApplyDifficulty()
	E.Wake()
end

-- Status line ------------------------------------------------------------------
function E.UpdateDurability()
	if not db.statusLine then S.durability = nil return end
	local low
	for slot = 1, 19 do
		local cur, most = GetInventoryItemDurability(slot)
		if cur and most and most > 0 and not issecret(cur) then
			local p = cur / most
			if not low or p < low then low = p end
		end
	end
	S.durability = low and floor(low * 100 + 0.5)
	S.lastStatus = nil
end

function E.UpdateStatus()
	local st = S.status
	if not (st and db.statusLine) then return end
	local _, _, home, world = GetNetStats()
	local t = format(L["%d fps"], floor(GetFramerate() + 0.5)) .. "  ·  " .. format(L["%d ms"], max(home or 0, world or 0))
	local dur = S.durability
	if dur then
		local c = dur < 25 and "ff4040" or dur < 50 and "ffd040" or "ffffff"
		t = t .. "  ·  |cff" .. c .. dur .. "%|r"
	end
	if t ~= S.lastStatus then
		S.lastStatus = t
		st.text:SetText(t)
		st:SetSize(max(8, st.text:GetStringWidth() + 6), db.coordSize + 4)
	end
end

-- Flight paths: where you're going and how long is left. GoodMap learns each
-- route's time the first time you fly it.
function E.SetupFlights()
	if type(_G.TakeTaxiNode) == "function" then hooksecurefunc("TakeTaxiNode", function(i) E.OnTakeTaxi(i) end) end
end

function E.OnTakeTaxi(index)
	local name, kind = _G.TaxiNodeName, _G.TaxiNodeGetType
	local dest = name and name(index)
	if type(dest) ~= "string" or issecret(dest) or dest == "" then return end
	local src
	for i = 1, (_G.NumTaxiNodes and _G.NumTaxiNodes() or 0) do
		if kind and kind(i) == "CURRENT" then src = name(i) break end
	end
	if issecret(src) then src = nil end
	local ok, route = pcall(E.TaxiRoute, index)
	S.flight = { dest = dest, key = (src or "?") .. ">" .. dest, taken = GetTime(), route = ok and route or nil }
end

-- The route you picked, from the flight master's map: takeoff, each stop and the
-- destination, as world positions. Straight lines between them, like the flight map draws.
function E.TaxiRoute(index)
	local TM = _G.C_TaxiMap
	local numRoutes, nodeSlot = _G.GetNumRoutes, _G.TaxiGetNodeSlot
	if not (TM and TM.GetAllTaxiNodes and numRoutes and nodeSlot) then return end
	local fm = _G.FlightMapFrame
	local mapID = (fm and fm:IsShown() and fm.GetMapID and fm:GetMapID()) or (_G.GetTaxiMapID and _G.GetTaxiMapID())
	if not mapID or issecret(mapID) then return end
	local nodes = TM.GetAllTaxiNodes(mapID)
	if type(nodes) ~= "table" then return end
	local bySlot = {}
	for _, n in ipairs(nodes) do
		if type(n) == "table" and n.slotIndex and not issecret(n.slotIndex) and n.position then bySlot[n.slotIndex] = n end
	end
	local pts, cont = {}, nil
	local function add(slot)
		local n = slot and not issecret(slot) and bySlot[slot]
		local p = n and n.position
		if not p or issecret(p.x) or issecret(p.y) then return false end
		local c, wx, wy = E.MapToWorld(mapID, p.x, p.y)
		if not c or (cont and c ~= cont) then return false end
		cont = c
		local nm = n.name
		pts[#pts + 1] = { wx, wy, name = (type(nm) == "string" and not issecret(nm)) and nm or nil }
		return true
	end
	local hops = numRoutes(index)
	if type(hops) ~= "number" or issecret(hops) or hops < 1 then return end
	for hop = 1, hops do
		if hop == 1 and not add(nodeSlot(index, hop, true)) then return end
		if not add(nodeSlot(index, hop, false)) then return end
	end
	if #pts < 2 then return end
	local len, at = 0, { 0 }
	for i = 2, #pts do
		len = len + sqrt((pts[i][1] - pts[i - 1][1]) ^ 2 + (pts[i][2] - pts[i - 1][2]) ^ 2)
		at[i] = len
	end
	return { cont = cont, pts = pts, at = at, len = len, mapID = mapID }
end

-- Seconds left, and whether that's an estimate (a route GoodMap hasn't flown yet).
function E.FlightLeft()
	local f = S.flight
	if not (f and f.start) then return end
	local flown = GetTime() - f.start
	local learned = ROOT.flights[f.key]
	if learned then return max(0, learned - flown), false end
	local r = f.route
	if not (r and r.len > 0) then return end
	local done, v = f.done or 0, ROOT.flightSpeed or 30
	if flown > 20 and done > 200 then v = v * 0.4 + (done / flown) * 0.6 end   -- this flight's own pace counts more
	return max(0, (r.len - done) / max(v, 5)), true
end

-- How far along the route you are, in yards, from your position (never backward).
function E.FlightProgress()
	local f = S.flight
	local r = f and f.route
	if not r then return end
	local wx, wy = UnitPosition("player")
	if not wx or issecret(wx) or issecret(wy) then return end
	local pts, best, bestD = r.pts, nil, nil
	for i = 2, #pts do
		local ax, ay = pts[i - 1][1], pts[i - 1][2]
		local dx, dy = pts[i][1] - ax, pts[i][2] - ay
		local l2 = dx * dx + dy * dy
		local t = l2 > 0 and Clamp(((wx - ax) * dx + (wy - ay) * dy) / l2, 0, 1) or 0
		local d = (wx - ax - t * dx) ^ 2 + (wy - ay - t * dy) ^ 2
		local along = r.at[i - 1] + t * sqrt(l2)
		if f.done and along < f.done - 150 then d = d + 1e9 end    -- a leg you already flew, close by
		if not bestD or d < bestD then best, bestD = along, d end
	end
	if best then f.done = max(f.done or 0, best) end
	f.frac = r.len > 0 and Clamp((f.done or 0) / r.len, 0, 1) or 0
end

function E.FlightWanted()
	return db.flightMode and S.mode == "NORMAL" and not S.houseActive and S.flight and S.flight.start and true or false
end

function E.UpdateFlight()
	local f, now = S.flight, GetTime()
	local line
	if f then
		if UnitOnTaxi("player") then
			f.start = f.start or now
			if not S.flightOn and S.mapShown and E.FlightWanted() then E.FlightStart() end
			if not S.flightOn then
				line = f.dest
				local left, about = E.FlightLeft()
				if left then line = line .. "  |cff35d07f" .. (about and "~" or "") .. E.Clock(left) .. "|r" end
			end
		elseif f.start then                                 -- landed: remember how long it took
			E.FlightLanded(now - f.start)
		elseif now - f.taken > 15 then                      -- never took off
			S.flight = nil
		end
	end
	if S.flightOn and not (S.flight and S.flight.start and E.FlightWanted()) then E.FlightStop() end
	local was = S.flightLine
	S.flightLine = line and true or nil
	if line and line ~= S.lastFlight then S.lastFlight = line; S.flightText:SetText(line) end
	if (was or nil) ~= S.flightLine and db.flightInfo then E.ApplyText() end
end

--------------------------------------------------------------------------------
-- Flight mode: between flight points GoodMap becomes a flight map. The map art
-- dims to dusk and clouds drift past the way you came. Your route glows gold,
-- with lights running ahead of you to the destination, which pulses with its
-- name. The map's edge fills from the top as you fly, a comet at its tip.
-- "Flying over" and the zone sit at the top; the countdown, where you're going
-- and when you'll land at the bottom. The usual text, the compass and the radar
-- step aside until you land. A soft chime plays 10 seconds out.
--------------------------------------------------------------------------------
local FLIGHT_TEX = "Interface\\AddOns\\Pathway\\GoodMap\\Textures\\Flight-"
local SKY, GOLD, NIGHT = { 0.45, 0.72, 1 }, { 1, 0.8, 0.36 }, { 0.02, 0.05, 0.13 }
local RING_N = 72                                   -- segments in the progress ring
local LIGHTS_MAX = 64                               -- lights running along the route

function E.FlightLanded(took)
	local f = S.flight
	if f then
		if took > 5 and f.key:sub(1, 2) ~= "?>" then ROOT.flights[f.key] = floor(took + 0.5) end
		local r = f.route
		if r and r.len > 100 and took > 10 then              -- how fast flights go, for routes you haven't flown
			local v = r.len / took
			ROOT.flightSpeed = ROOT.flightSpeed and (ROOT.flightSpeed * 0.7 + v * 0.3) or v
		end
	end
	S.flight = nil
	if S.flightOn then E.FlightStop(true) end
end

-- The smallest map (your zone, then the maps around it) the whole route fits on.
function E.FlightMap(r)
	local tried = {}
	local function fits(id)
		for _, p in ipairs(r.pts) do
			if not E.WorldToMap(id, r.cont, p[1], p[2]) then return false end
		end
		return true
	end
	local id = S.playerMap
	while id and id > 0 and not tried[id] do
		tried[id] = true
		if fits(id) then return id end
		local info = C_Map.GetMapInfo(id)
		id = info and info.parentMapID
	end
	if r.mapID and fits(r.mapID) then return r.mapID end
end

local function FlightTex(parent, layer, name, r, g, b, a, blend)
	local t = parent:CreateTexture(nil, layer)
	t:SetTexture(FLIGHT_TEX .. name)
	t:SetVertexColor(r, g, b, a)
	if blend then t:SetBlendMode(blend) end
	return t
end

-- Fades a frame in, or out and then hides it.
local function Fades(f, inTime, outTime)
	local fin, fout = f:CreateAnimationGroup(), f:CreateAnimationGroup()
	fin:SetToFinalAlpha(true)
	fout:SetToFinalAlpha(true)
	local a = fin:CreateAnimation("Alpha")
	a:SetFromAlpha(0); a:SetToAlpha(1); a:SetDuration(inTime); a:SetSmoothing("OUT")
	local b = fout:CreateAnimation("Alpha")
	b:SetFromAlpha(1); b:SetToAlpha(0); b:SetDuration(outTime); b:SetSmoothing("IN")
	fout:SetScript("OnFinished", function() f:Hide() end)
	f.fadeIn, f.fadeOut = fin, fout
end
local function FadeIn(f)
	if f:IsShown() and not f.fadeOut:IsPlaying() then return end
	f.fadeOut:Stop(); f:Show(); f.fadeIn:Play()
end
local function FadeOut(f)
	f.fadeIn:Stop()
	if f:IsShown() and not f.fadeOut:IsPlaying() then f.fadeOut:Play() end
end

-- A ring that grows and fades: takeoff (sky blue) and landing (gold).
local function Ripple(parent, size)
	local t = FlightTex(parent, "OVERLAY", "Ring", 1, 1, 1, 1, "ADD")
	t:SetPoint("CENTER")
	t:SetSize(size, size)
	local ag = t:CreateAnimationGroup()
	local s = ag:CreateAnimation("Scale")
	s:SetScaleFrom(0.2, 0.2); s:SetScaleTo(1, 1); s:SetDuration(1.4); s:SetSmoothing("OUT")
	local a = ag:CreateAnimation("Alpha")
	a:SetFromAlpha(1); a:SetToAlpha(0); a:SetDuration(1.4); a:SetSmoothing("IN")
	ag:SetScript("OnFinished", function() t:Hide() end)
	t.anim = ag
	t:Hide()
	return t
end
local function PlayRipple(t, c, alpha)
	t:SetVertexColor(c[1], c[2], c[3], alpha)
	t.anim:Stop(); t:Show(); t.anim:Play()
end

-- A slow, endless pulse (alpha back and forth).
local function Breathe(region, from, to, secs)
	local ag = region:CreateAnimationGroup()
	ag:SetLooping("BOUNCE")
	local a = ag:CreateAnimation("Alpha")
	a:SetFromAlpha(from); a:SetToAlpha(to); a:SetDuration(secs); a:SetSmoothing("IN_OUT")
	return ag
end

function E.SetupFlightMode()
	-- Under the route and the icons: dusk over the map art, drifting clouds, a dark rim.
	local back = CreateFrame("Frame", nil, S.sc)
	back:SetAllPoints(S.sc)
	back:SetFrameLevel(E.PinLevel("PIN_FRAME_LEVEL_MAP_EXPLORATION", 1500) + 2)
	back:EnableMouse(false)
	back:Hide()
	back.tint = back:CreateTexture(nil, "BACKGROUND")
	back.tint:SetAllPoints()
	back.tint:SetColorTexture(NIGHT[1], NIGHT[2], NIGHT[3], 0.48)
	back.clouds = {}
	for i, c in ipairs({ { 1, 0.2, 10 }, { 0.6, 0.12, 17 } }) do    -- small and far, big and near (faster)
		local t = back:CreateTexture(nil, "BORDER", nil, i)
		t:SetTexture(FLIGHT_TEX .. "Clouds", "REPEAT", "REPEAT")
		t:SetAllPoints()
		t:SetVertexColor(0.86, 0.91, 1, c[2])
		t.span, t.speed, t.u, t.v = c[1], c[3], i * 0.37, i * 0.61
		back.clouds[i] = t
	end
	back.vignette = FlightTex(back, "ARTWORK", "Vignette", NIGHT[1], NIGHT[2], NIGHT[3], 0.85)
	back.vignette:SetAllPoints()
	Mask(back.tint); Mask(back.clouds[1]); Mask(back.clouds[2]); Mask(back.vignette)
	back:SetScript("OnUpdate", Pathway.Perf.W("Minimap", E.FlightAnimate))
	Fades(back, 0.7, 0.5)
	S.flightBack = back

	-- Over the map: a soft sky halo around the rim, and the progress ring with its comet.
	local front = CreateFrame("Frame", nil, S.map)
	front:SetAllPoints(S.sc)
	front:SetFrameLevel(9450)                      -- between GoodMap's border (9400) and its text (9500)
	front:EnableMouse(false)
	front:Hide()
	front.halo = FlightTex(front, "BACKGROUND", "Ring", SKY[1], SKY[2], SKY[3], 0.42, "ADD")
	front.halo:SetPoint("CENTER")
	front.haloPulse = Breathe(front.halo, 0.45, 1, 2.4)
	S.flightRing = E.NewProgress(front)
	Fades(front, 0.7, 0.5)
	S.flightFront = front

	-- Takeoff and landing ripples, on their own so they outlive the fade.
	local pulse = CreateFrame("Frame", nil, S.map)
	pulse:SetAllPoints(S.sc)
	pulse:SetFrameLevel(9451)
	pulse:EnableMouse(false)
	pulse.ripple = Ripple(pulse, 300)
	S.flightPulse = pulse

	-- The words: where you are at the top, the countdown at the bottom.
	local hud = CreateFrame("Frame", nil, S.overlay)
	hud:SetAllPoints(S.overlay)
	hud:SetFrameLevel(S.overlay:GetFrameLevel() + 30)
	hud:EnableMouse(false)
	hud:Hide()
	hud.topShade = FlightTex(hud, "BACKGROUND", "Glow", 0, 0, 0, 0.62)
	hud.bottomShade = FlightTex(hud, "BACKGROUND", "Glow", 0, 0, 0, 0.62)
	Mask(hud.topShade); Mask(hud.bottomShade)
	local function line(r, g, b)
		local fs = hud:CreateFontString(nil, "OVERLAY", "GameFontNormal")
		fs:SetTextColor(r, g, b)
		fs:SetWordWrap(false)
		fs:SetShadowOffset(1, -1)
		fs:SetShadowColor(0, 0, 0, 0.9)
		return fs
	end
	hud.over = line(SKY[1], SKY[2], SKY[3])
	hud.zone = line(1, 1, 1)
	hud.time = line(1, 1, 1)
	hud.dest = line(GOLD[1], GOLD[2], GOLD[3])
	hud.lands = line(0.8, 0.82, 0.86)
	hud.over:SetText(L["Flying over"])
	local zf = hud.zone:CreateAnimationGroup()      -- each new zone fades in
	local za = zf:CreateAnimation("Alpha")
	za:SetFromAlpha(0); za:SetToAlpha(1); za:SetDuration(0.8); za:SetSmoothing("OUT")
	hud.zoneFade = zf
	Fades(hud, 0.5, 0.4)
	S.flightHud = hud

	-- the route, on the map canvas (above the dusk, below the icons)
	local rf = CreateFrame("Frame", nil, S.canvas)
	rf:SetAllPoints(S.canvas)
	rf:SetFrameLevel(E.PinLevel("PIN_FRAME_LEVEL_MAP_EXPLORATION", 1500) + 3)
	rf:Hide()
	rf.flown, rf.ahead, rf.glow, rf.lights = {}, {}, {}, {}
	Fades(rf, 0.6, 0.4)
	S.routeFrame = rf

	-- a soft glow under you
	local me = CreateFrame("Frame", nil, S.canvas)
	me:SetSize(1, 1)
	me:SetFrameLevel(E.PinLevel("PIN_FRAME_LEVEL_GROUP_MEMBER", 2050) - 1)
	me.tex = FlightTex(me, "ARTWORK", "Glow", SKY[1], SKY[2], SKY[3], 0.6, "ADD")
	me.tex:SetSize(42, 42)
	me.tex:SetPoint("CENTER")
	Mask(me.tex)
	me:Hide()
	S.flightMe = me
end

function E.FlightStart()
	local f = S.flight
	if not (f and S.flightBack) then return end
	S.flightOn = true
	S.flightMap, S.flightChimed, S.flightZone, S.flightFitAt, S.flightView = nil, nil, false, 0, nil
	-- Blizzard's map jumps to your zone at every zone border, which made the
	-- flight view snap in and out; it keeps still until you land
	if not S.zoneEventHeld and S.map.IsEventRegistered and S.map:IsEventRegistered("ZONE_CHANGED_NEW_AREA") then
		S.map:UnregisterEvent("ZONE_CHANGED_NEW_AREA"); S.zoneEventHeld = true
	end
	local r = f.route
	if r and db.flightFit then
		local id = E.FlightMap(r)
		if id then
			S.flightMap = id
			S.ctxBase, S.ctxManual = nil, nil                -- flight mode sets the view until you land
			if S.map:GetMapID() ~= id then S.map:SetMapID(id) end
			Later("flightFit", E.FlightFit, 0.05)
		end
	end
	S.flightMe:ClearAllPoints()
	S.flightMe:SetPoint("CENTER", S.radarAnchor, "CENTER", 0, 0)
	E.FlightLayout()
	E.ApplyChrome()
	FadeIn(S.flightBack); FadeIn(S.flightFront); FadeIn(S.flightHud)
	S.flightFront.haloPulse:Play()
	S.flightRing.headPulse:Play()
	PlayRipple(S.flightPulse.ripple, SKY, 0.8)
	E.FarmLookUpdate()
	E.ApplyLayers()                               -- quests step aside
	E.UpdateHeading()
	E.FlightTick()
end

function E.FlightStop(landed)
	S.flightOn = false
	if S.zoneEventHeld then S.zoneEventHeld = nil; S.map:RegisterEvent("ZONE_CHANGED_NEW_AREA") end
	S.flightView = nil
	FadeOut(S.flightBack); FadeOut(S.flightFront); FadeOut(S.flightHud); FadeOut(S.routeFrame)
	S.flightFront.haloPulse:Stop()
	S.flightRing.headPulse:Stop()
	S.flightMe:Hide()
	if landed and S.mapShown then PlayRipple(S.flightPulse.ripple, GOLD, 0.9) end
	for _, kind in ipairs({ "fstop", "fdest" }) do
		for p in pairs(S.cpins) do if p.kind == kind then E.FreeCanvasPin(p) end end
	end
	S.flightDest, S.flightStops = nil, nil
	local back = S.flightMap
	S.flightMap = nil
	E.FarmLookUpdate()
	E.ApplyChrome()
	E.ApplyLayers()
	E.UpdateHeading()
	if not S.mapShown then return end
	-- back to your zone, at your usual zoom
	if back and S.playerMap and S.map:GetMapID() ~= S.playerMap then S.map:SetMapID(S.playerMap)
	elseif S.sc.zoomLevels then E.RestoreZoom(S.sc) end
end

-- On a flight or a farming route the map has its own look: the usual text, the
-- compass letters, the holiday button and the zoom buttons step aside (on a flight
-- the edge arrows and the radar too), and come back afterwards.
function E.Busy() return S.flightOn or S.farmLook end

function E.ApplyChrome()
	local busy = E.Busy() and true or false
	local tl = S.textLayer
	if busy ~= (S.chromeHidden or false) then
		S.chromeHidden = busy
		if busy then
			FadeTo(tl, 0)
			C_Timer.After(0.25, function() if S.chromeHidden then tl:Hide() end end)
		else
			tl:Show()
			E.ApplyCalm()
		end
	end
	E.ApplyCompass()
	E.UpdateWaypointArrow()
	E.UpdateEventButton()
	E.UpdateHoverWidgets(S.hovered)
	E.UpdateRadarState()
end

-- Zoom and pan so the whole route fits in the middle of the map, never closer
-- than Blizzard's own closest zoom.
function E.FlightFit()
	local f = S.flight
	local r = f and f.route
	local sc, mapID = S.sc, S.map:GetMapID()
	S.flightFitAt = GetTime()
	if not (S.flightOn and r and sc.zoomLevels and sc.zoomLevels[1] and mapID) then return end
	local x0, y0, x1, y1 = 1, 1, 0, 0
	for _, pt in ipairs(r.pts) do
		local x, y = E.WorldToMap(mapID, r.cont, pt[1], pt[2])
		if not x then return end
		x0, y0, x1, y1 = min(x0, x), min(y0, y), max(x1, x), max(y1, y)
	end
	local cw, ch = S.canvas:GetWidth(), S.canvas:GetHeight()
	local w, h = sc:GetWidth(), sc:GetHeight()
	local bw, bh = max((x1 - x0) * cw, 1), max((y1 - y0) * ch, 1)
	local need
	if S.round then need = min(w, h) * 0.72 / sqrt(bw * bw + bh * bh)
	else need = min(w * 0.84 / bw, h * 0.66 / bh) end
	local levels = sc.zoomLevels
	local top = levels[max(1, #levels - db.extraZoom)].scale
	local scale = Clamp(need, levels[1].scale, max(top, levels[1].scale))
	-- a little above the middle: the countdown at the bottom takes more room than the words at the top
	local cx, cy = (x0 + x1) / 2, (y0 + y1) / 2 + 0.04 * min(w, h) / (ch * scale)
	-- a refit that changes almost nothing is skipped, so the view never twitches
	local v = S.flightView
	if v and v.map == mapID and abs(v.scale - scale) / v.scale < 0.03 and abs(v.cx - cx) < 0.01 and abs(v.cy - cy) < 0.01 then
		return
	end
	S.flightView = { map = mapID, scale = scale, cx = cx, cy = cy }
	if db.smoothZoom and not (v and v.instant) then
		sc:SetZoomTarget(scale)
		E.KeepPan(cx, cy)
	else
		sc:InstantPanAndZoom(scale, cx, cy, true)
	end
end

-- Sizes and places everything for the map's shape and size.
function E.FlightLayout()
	local hud, front, back, ring = S.flightHud, S.flightFront, S.flightBack, S.flightRing
	if not hud then return end
	local round = S.round
	local d = E.Diameter()
	local w, h = S.sc:GetWidth() or d, S.sc:GetHeight() or d
	local font = GameFontNormal:GetFont()
	local small = max(9, floor(d * 0.032 + 0.5))
	local mid = max(12, floor(d * 0.05 + 0.5))
	local destSize = max(10, floor(d * 0.04 + 0.5))
	local big = Clamp(floor(d * 0.1 + 0.5), 20, 34)
	hud.over:SetFont(font, small, "")
	hud.zone:SetFont(font, mid, "OUTLINE")
	hud.time:SetFont(font, big, "OUTLINE")
	hud.dest:SetFont(font, destSize, "OUTLINE")
	hud.lands:SetFont(font, small, "")
	local tw = round and d * 0.62 or w - 16
	for _, fs in ipairs({ hud.over, hud.zone, hud.dest, hud.lands }) do fs:SetWidth(tw) end
	local thick = max(3, db.borderSize + 2)
	local topInset = round and floor(d * 0.075 + 0.5) or 6
	local bottomInset = round and floor(d * 0.085 + 0.5) or thick + 6
	hud.over:ClearAllPoints()
	hud.over:SetPoint("TOP", hud, "TOP", 0, -topInset)
	hud.zone:ClearAllPoints()
	hud.zone:SetPoint("TOP", hud.over, "BOTTOM", 0, -1)
	hud.lands:ClearAllPoints()
	hud.lands:SetPoint("BOTTOM", hud, "BOTTOM", 0, bottomInset)
	hud.dest:ClearAllPoints()
	hud.dest:SetPoint("BOTTOM", hud.lands, "TOP", 0, 1)
	hud.time:ClearAllPoints()
	hud.time:SetPoint("BOTTOM", hud.dest, "TOP", 0, 0)
	-- soft dark shades behind the words (round glows, so no hard edges)
	local topH, bottomH = small + mid + 4, small + destSize + big + 2
	hud.topShade:ClearAllPoints()
	hud.topShade:SetPoint("CENTER", hud, "TOP", 0, -(topInset + topH / 2))
	hud.topShade:SetSize(tw * 1.25, topH * 2.6)
	hud.bottomShade:ClearAllPoints()
	hud.bottomShade:SetPoint("CENTER", hud, "BOTTOM", 0, bottomInset + bottomH / 2)
	hud.bottomShade:SetSize(tw * 1.3, bottomH * 2.2)

	-- the halo sits on the rim (the ring texture's ring is at 80% of its half size)
	front.halo:SetSize(d / 0.8 * 1.06, d / 0.8 * 1.06)
	front.halo:SetShown(round)
	S.flightPulse.ripple:SetSize(d * 1.05, d * 1.05)
	local m = max(min(w, h), 1)
	for _, t in ipairs(back.clouds) do
		t.su, t.sv = t.span * w / m, t.span * h / m
		t.rate = t.speed / m * t.span                 -- texture units a second for its speed on screen
		t:SetTexCoord(t.u, t.u + t.su, t.v, t.v + t.sv)
	end

	E.LayoutProgress(ring, GOLD)
	if S.flightOn and S.flight then E.FlightTick() end
end

-- A progress ring just inside the map's border, filling clockwise from the top with
-- a comet at its tip (a bar along the bottom on a square map). Flights and farming
-- routes both use one.
function E.NewProgress(parent)
	local ring = CreateFrame("Frame", nil, parent)
	ring:SetAllPoints(parent)
	ring.track, ring.fill = {}, {}
	for i = 1, RING_N do
		ring.track[i] = ring:CreateLine(nil, "ARTWORK")
		ring.fill[i] = ring:CreateLine(nil, "OVERLAY")
	end
	ring.barTrack = ring:CreateTexture(nil, "ARTWORK")
	ring.barTrack:SetColorTexture(1, 1, 1, 0.14)
	ring.bar = ring:CreateTexture(nil, "OVERLAY")
	ring.bar:SetTexture("Interface\\Buttons\\WHITE8X8")
	ring.head = FlightTex(ring, "OVERLAY", "Glow", 1, 0.93, 0.72, 1, "ADD")
	ring.head:SetDrawLayer("OVERLAY", 7)
	ring.headPulse = Breathe(ring.head, 0.6, 1, 0.9)
	return ring
end

function E.LayoutProgress(ring, c)
	local round, d = S.round, E.Diameter()
	local thick = max(3, db.borderSize + 2)
	local r = d / 2 - thick / 2 - 1
	ring.r = r
	for i, l in ipairs(ring.track) do
		local a0 = PI / 2 - (i - 1) / RING_N * 2 * PI
		local a1 = PI / 2 - (i + 0.15) / RING_N * 2 * PI          -- a little overlap hides the joints
		l:SetThickness(thick)
		l:SetColorTexture(1, 1, 1, 0.12)
		l:SetStartPoint("CENTER", ring, r * cos(a0), r * sin(a0))
		l:SetEndPoint("CENTER", ring, r * cos(a1), r * sin(a1))
		l:SetShown(round)
		ring.fill[i]:SetThickness(thick)
		ring.fill[i]:SetColorTexture(c[1], c[2], c[3], 0.95)
	end
	ring.barTrack:ClearAllPoints()
	ring.barTrack:SetPoint("BOTTOMLEFT", ring, "BOTTOMLEFT", 1, 1)
	ring.barTrack:SetPoint("BOTTOMRIGHT", ring, "BOTTOMRIGHT", -1, 1)
	ring.barTrack:SetHeight(thick)
	ring.barTrack:SetShown(not round)
	ring.bar:ClearAllPoints()
	ring.bar:SetPoint("BOTTOMLEFT", ring.barTrack, "BOTTOMLEFT")
	ring.bar:SetHeight(thick)
	ring.bar:SetVertexColor(c[1], c[2], c[3], 0.95)
	ring.head:SetSize(thick * 6, thick * 6)
end

function E.DrawProgress(ring, frac)
	local head = ring.head
	if S.round then
		local n, r = frac * RING_N, ring.r
		for i, l in ipairs(ring.fill) do
			if i - 1 < n then
				local a0 = PI / 2 - (i - 1) / RING_N * 2 * PI
				local a1 = PI / 2 - min(i + 0.15, n) / RING_N * 2 * PI
				l:SetStartPoint("CENTER", ring, r * cos(a0), r * sin(a0))
				l:SetEndPoint("CENTER", ring, r * cos(a1), r * sin(a1))
				l:Show()
			else
				l:Hide()
			end
		end
		ring.bar:Hide()
		local a = PI / 2 - n / RING_N * 2 * PI
		head:ClearAllPoints()
		head:SetPoint("CENTER", ring, "CENTER", r * cos(a), r * sin(a))
	else
		for _, l in ipairs(ring.fill) do l:Hide() end
		local w = ((S.sc:GetWidth() or 0) - 2) * frac               -- the ring frame is the scroll frame's size
		ring.bar:SetWidth(max(w, 0.01))
		ring.bar:SetShown(w > 0.5)
		head:ClearAllPoints()
		head:SetPoint("CENTER", ring.barTrack, "LEFT", w, 0)
	end
	head:SetShown(frac > 0.005 and frac < 0.995)
	ring:Show()
end

-- Lines between canvas points, kept the same thickness on screen whatever the zoom.
local function RouteLine(rf, list, i, layer, r, g, b, a, thick, blend)
	local l = list[i]
	if not l then
		l = rf:CreateLine(nil, layer)
		if blend then l:SetBlendMode(blend) end
		if l.AddMaskTexture then Mask(l) end
		list[i] = l
	end
	l:SetColorTexture(r, g, b, a)
	l:SetThickness(thick)
	return l
end

function E.DrawRoute()
	local f, rf = S.flight, S.routeFrame
	local r = f and f.route
	local mapID = S.map:GetMapID()
	local mr = mapID and MapRect(mapID)
	if not (S.flightOn and r and mr and mr[5] == r.cont) then
		rf.fadeIn:Stop(); rf.fadeOut:Stop(); rf:Hide()
		rf.cpts, rf.key, rf.r, rf.seg = nil, nil, nil, nil
		S.flightMe:Hide()
		return
	end
	local cw, ch = S.canvas:GetWidth(), S.canvas:GetHeight()
	local k = 1 / max(S.sc:GetCanvasScale(), 0.01)
	local pts, at = r.pts, r.at
	local done = f.done or 0
	-- the leg you're on: legs before it are flown, legs after it are ahead
	local seg = #pts
	for i = 2, #pts do if done < at[i] then seg = i break end end
	local key = mapID .. ":" .. floor(cw) .. ":" .. floor(ch) .. ":" .. floor(k * 1000)
	if rf.key == key and rf.r == r and rf.seg == seg and rf.cpts then
		-- the same view and the same leg: only the split point moves, every frame,
		-- so the contrail and the gold line stay glued to you
		local cp, i = rf.cpts, seg
		local ax, ay, bx, by = cp[2 * i - 3], cp[2 * i - 2], cp[2 * i - 1], cp[2 * i]
		local a0, a1 = at[i - 1], at[i]
		local t = a1 > a0 and Clamp((done - a0) / (a1 - a0), 0, 1) or 1
		local mx, my = ax + (bx - ax) * t, ay + (by - ay) * t
		local l = rf.flown[i - 1]
		if l and t > 0 then l:SetStartPoint("TOPLEFT", S.canvas, ax, ay); l:SetEndPoint("TOPLEFT", S.canvas, mx, my); l:Show() end
		local g, a = rf.glow[1], rf.ahead[1]
		if g and a and t < 1 then
			g:SetStartPoint("TOPLEFT", S.canvas, mx, my); g:SetEndPoint("TOPLEFT", S.canvas, bx, by)
			a:SetStartPoint("TOPLEFT", S.canvas, mx, my); a:SetEndPoint("TOPLEFT", S.canvas, bx, by)
		end
		return
	end
	rf.key, rf.r, rf.seg = key, r, seg
	local cp = rf.cpts or {}
	for i = 1, #pts do
		cp[2 * i - 1] = (pts[i][2] - mr[2]) / mr[4] * cw
		cp[2 * i] = -(pts[i][1] - mr[1]) / mr[3] * ch
	end
	rf.cpts, rf.k = cp, cw / abs(mr[4])                   -- canvas units a yard
	local nf, na, hx, hy = 0, 0, nil, nil
	for i = 2, #pts do
		local ax, ay, bx, by = cp[2 * i - 3], cp[2 * i - 2], cp[2 * i - 1], cp[2 * i]
		local a0, a1 = at[i - 1], at[i]
		local t = a1 > a0 and Clamp((done - a0) / (a1 - a0), 0, 1) or 1
		if i < seg then t = 1 elseif i > seg then t = 0 end
		local mx, my = ax + (bx - ax) * t, ay + (by - ay) * t
		-- every leg up to yours gets a contrail line (yours grows as you fly)
		if i <= seg then
			nf = nf + 1
			local l = RouteLine(rf, rf.flown, nf, "ARTWORK", 1, 1, 1, 0.3, 1.5 * k)
			l:SetStartPoint("TOPLEFT", S.canvas, ax, ay); l:SetEndPoint("TOPLEFT", S.canvas, mx, my); l:SetShown(t > 0)
		end
		if t < 1 or i == seg then                       -- what's ahead: gold, with a soft glow
			na = na + 1
			local g = RouteLine(rf, rf.glow, na, "BORDER", GOLD[1], GOLD[2], GOLD[3], 0.16, 8 * k, "ADD")
			g:SetStartPoint("TOPLEFT", S.canvas, mx, my); g:SetEndPoint("TOPLEFT", S.canvas, bx, by); g:Show()
			local l = RouteLine(rf, rf.ahead, na, "ARTWORK", GOLD[1], GOLD[2], GOLD[3], 0.6, 1.5 * k)
			l:SetStartPoint("TOPLEFT", S.canvas, mx, my); l:SetEndPoint("TOPLEFT", S.canvas, bx, by); l:Show()
			if not hx then                              -- your heading, for the clouds
				local dx, dy = bx - ax, by - ay
				local len = sqrt(dx * dx + dy * dy)
				if len > 0 then hx, hy = dx / len, -dy / len end
			end
		end
	end
	for i = nf + 1, #rf.flown do rf.flown[i]:Hide() end
	for i = na + 1, #rf.ahead do rf.ahead[i]:Hide(); rf.glow[i]:Hide() end
	if hx then S.flightHX, S.flightHY = hx, hy end
	if rf.lk ~= k then                                -- the lights keep their size on screen
		rf.lk = k
		for _, l in ipairs(rf.lights) do l:SetSize(9 * k, 9 * k) end
	end
	if not rf:IsShown() or rf.fadeOut:IsPlaying() then FadeIn(rf) end
	local me = S.flightMe
	me:SetScale(k)
	me:SetShown(PlayerPos(mapID) ~= nil)
	E.PlaceFlightPins()
end

-- About 40 times a second while you fly: the clouds drift and the lights run on.
function E.FlightAnimate(self, elapsed)
	self.acc = (self.acc or 0) + elapsed
	if self.acc < 0.025 then return end
	local dt = min(self.acc, 0.25)
	self.acc = 0
	-- where you are along the route, every frame: the lights and the line move
	-- with you smoothly instead of hopping five times a second
	if S.flightOn and S.flight and S.flight.route then E.FlightProgress(); E.DrawRoute() end
	local hx, hy = S.flightHX or 0, S.flightHY or -1        -- your heading on screen (y down)
	for _, t in ipairs(self.clouds) do                       -- clouds go by the other way
		if t.rate then
			t.u = (t.u + hx * t.rate * dt) % 1
			t.v = (t.v + hy * t.rate * dt) % 1
			t:SetTexCoord(t.u, t.u + t.su, t.v, t.v + t.sv)
		end
	end
	E.RunLights(dt)
end

-- Lights every 18 px along the route ahead, running toward the destination.
function E.RunLights(dt)
	local rf, f = S.routeFrame, S.flight
	local r = f and f.route
	local cp = rf.cpts
	if not (r and cp and rf:IsShown() and rf.k and rf.k > 0) then return end
	local yd = 1 / (max(S.sc:GetCanvasScale(), 0.01) * rf.k)   -- yards a screen pixel
	local gap = 18 * yd
	rf.travel = ((rf.travel or 0) + 26 * yd * dt) % gap
	local done, len, at = f.done or 0, r.len, r.at
	local s = done + (rf.travel - done) % gap
	local lights, n, leg = rf.lights, 0, 2
	while s < len and n < LIGHTS_MAX do
		while leg < #at and at[leg] < s do leg = leg + 1 end
		local a0, a1 = at[leg - 1], at[leg]
		local t = a1 > a0 and Clamp((s - a0) / (a1 - a0), 0, 1) or 0
		local ax, ay = cp[2 * leg - 3], cp[2 * leg - 2]
		n = n + 1
		local l = lights[n]
		if not l then
			l = FlightTex(rf, "OVERLAY", "Glow", 1, 0.9, 0.62, 1, "ADD")
			l:SetSize(9 * (rf.lk or 1), 9 * (rf.lk or 1))
			Mask(l)
			lights[n] = l
		end
		l:SetPoint("CENTER", S.canvas, "TOPLEFT", ax + (cp[2 * leg - 1] - ax) * t, ay + (cp[2 * leg] - ay) * t)
		l:SetAlpha(Clamp(min((s - done) / gap, (len - s) / gap), 0, 1))
		l:Show()
		s = s + gap
	end
	for i = n + 1, #lights do lights[i]:Hide() end
end

-- The stops along the way, and the destination: a gold beacon with its name.
function E.PlaceFlightPins()
	local f = S.flight
	local r = f and f.route
	if not r then return end
	local mapID = S.map:GetMapID()
	local level = E.PinLevel("PIN_FRAME_LEVEL_TOPMOST", 2100)
	if not S.flightDest then
		S.flightStops = {}
		for i = 2, #r.pts - 1 do
			local s = E.CanvasPin("fstop", level)
			if not s.ring then
				s:SetSize(14, 14)
				s.ring = FlightTex(s, "ARTWORK", "Ring", 1, 1, 1, 1)
				s.ring:SetSize(18, 18)
				s.ring:SetPoint("CENTER")
				s.dot = s:CreateTexture(nil, "OVERLAY")
				s.dot:SetTexture(CIRCLE_MASK)
				s.dot:SetVertexColor(1, 1, 1, 0.9)
				s.dot:SetSize(4, 4)
				s.dot:SetPoint("CENTER")
				Mask(s.ring); Mask(s.dot)
				s.clip = true                             -- off the round map's circle, hidden
				Hoverable(s, E.FlightPinTip)
			end
			s.pt = r.pts[i]
			S.flightStops[#S.flightStops + 1] = s
		end
		local d = E.CanvasPin("fdest", level + 1)
		if not d.core then
			d:SetSize(18, 18)
			d.glow = FlightTex(d, "BORDER", "Glow", GOLD[1], GOLD[2], GOLD[3], 0.9, "ADD")
			d.glow:SetSize(32, 32)
			d.glow:SetPoint("CENTER")
			d.core = d:CreateTexture(nil, "OVERLAY")
			d.core:SetTexture(CIRCLE_MASK)
			d.core:SetVertexColor(1, 0.95, 0.8, 1)
			d.core:SetSize(8, 8)
			d.core:SetPoint("CENTER")
			d.pulses = {}
			for i = 1, 2 do                               -- two rings, half a beat apart
				local p = FlightTex(d, "ARTWORK", "Ring", GOLD[1], GOLD[2], GOLD[3], 0.9, "ADD")
				p:SetSize(60, 60)
				p:SetPoint("CENTER")
				local ag = p:CreateAnimationGroup()
				ag:SetLooping("REPEAT")
				local grow = ag:CreateAnimation("Scale")
				grow:SetScaleFrom(0.2, 0.2); grow:SetScaleTo(1, 1); grow:SetDuration(2); grow:SetSmoothing("OUT")
				local fade = ag:CreateAnimation("Alpha")
				fade:SetFromAlpha(1); fade:SetToAlpha(0); fade:SetDuration(2); fade:SetSmoothing("IN")
				if i == 2 then grow:SetStartDelay(1); fade:SetStartDelay(1) end
				Mask(p)
				d.pulses[i] = ag
			end
			d.anim = d.pulses[1]
			d.label = d:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
			d.label:SetPoint("TOP", d, "BOTTOM", 0, -2)
			d.label:SetTextColor(GOLD[1], GOLD[2], GOLD[3])
			d.label:SetShadowOffset(1, -1)
			d.label:SetShadowColor(0, 0, 0, 1)
			Mask(d.glow); Mask(d.core)
			d.clip = true                                 -- its name can't be masked
			Hoverable(d, E.FlightPinTip)
		end
		d.pt = r.pts[#r.pts]
		d.label:SetText(f.dest or "")
		for _, ag in ipairs(d.pulses) do ag:Play() end
		S.flightDest = d
	end
	local function place(pin)
		local x, y = E.WorldToMap(mapID, r.cont, pin.pt[1], pin.pt[2], true)
		E.PlaceCanvasPin(pin, x, y)
	end
	for _, s in ipairs(S.flightStops) do place(s) end
	place(S.flightDest)
end

-- Hover a stop or the destination: its name (and, for the destination, when you'll land).
function E.FlightPinTip(pin)
	local pt = pin.pt
	if not (pt and pin.nx) or (S.round and not E.InView(pin.nx, pin.ny)) then return end
	local dest = pin == S.flightDest
	local name = dest and S.flight and S.flight.dest or pt.name
	if not name then return end
	GameTooltip:SetOwner(pin, "ANCHOR_RIGHT")
	GameTooltip:SetText(name, 1, 0.82, 0)
	if dest then
		local left = E.FlightLeft()
		if left then GameTooltip:AddLine(format(L["Lands at %s"], E.ClockIn(left)), 1, 1, 1) end
	else
		GameTooltip:AddLine(L["A stop on your route"], 1, 1, 1)
	end
	GameTooltip:Show()
end

-- The landing time, on the game's clock (local or realm time, 12 or 24 hours).
function E.ClockIn(secs)
	local h, m
	if (GetCVarBool and GetCVarBool("timeMgrUseLocalTime")) or not GetGameTime then
		local t = date("*t", time() + floor(secs + 0.5))
		h, m = t.hour, t.min
	else
		local gh, gm = GetGameTime()
		local total = (gh * 60 + gm + floor(secs / 60 + 0.5)) % 1440
		h, m = floor(total / 60), total % 60
	end
	local mil = GetCVarBool and GetCVarBool("timeMgrUseMilitaryTime")
	if _G.GameTime_GetFormattedTime then return _G.GameTime_GetFormattedTime(h, m, not mil) end
	if mil then return format("%02d:%02d", h, m) end
	return format("%d:%02d %s", (h - 1) % 12 + 1, m, h < 12 and "AM" or "PM")
end

-- Five times a second while you fly.
function E.FlightTick()
	if not S.flightOn then return end
	local f = S.flight
	if not f then return end
	E.FlightProgress()
	-- looked around or zoomed: back to the whole route once you leave the map alone
	if S.flightMap and S.map:GetMapID() ~= S.flightMap and not S.hovered then
		-- something switched the map under us: straight back, same view, no zoom animation
		S.map:SetMapID(S.flightMap)
		local v = S.flightView
		if v and v.map == S.flightMap then S.sc:InstantPanAndZoom(v.scale, v.cx, v.cy, true) end
		S.flightFitAt = GetTime()
	elseif S.flightMap and S.idle and (S.lastInteract or 0) > (S.flightFitAt or 0) then
		S.flightFitAt = GetTime()        -- you zoomed or panned: ease back to the whole route
		Later("flightFit", E.FlightFit, 0.05)
	end
	if f.route then E.DrawRoute() end
	local hud = S.flightHud
	-- where you are
	local zone = GetZoneText()
	if type(zone) ~= "string" or issecret(zone) or zone == "" then zone = nil end
	if zone ~= S.flightZone then
		S.flightZone = zone
		hud.zone:SetText(zone or "")
		hud.over:SetShown(zone ~= nil)
		hud.zoneFade:Stop(); hud.zoneFade:Play()
	end
	-- how long, where to, and when you'll land
	hud.dest:SetText(f.dest or "")
	local left, about = E.FlightLeft()
	if left then
		local soon = left <= 10
		hud.time:SetText((about and "|cff8fa6c8~|r" or "") .. E.Clock(left))
		if soon then hud.time:SetTextColor(GOLD[1], GOLD[2], GOLD[3]) else hud.time:SetTextColor(1, 1, 1) end
		hud.lands:SetText(format(L["Lands at %s"], E.ClockIn(left)))
		if soon and not S.flightChimed then
			S.flightChimed = true
			if db.flightChime and _G.SOUNDKIT and _G.SOUNDKIT.MAP_PING then PlaySound(_G.SOUNDKIT.MAP_PING) end
		end
	else
		hud.time:SetText("")
		hud.lands:SetText(L["GoodMap learns this route as you fly it."])
	end
	-- the ring
	local frac = f.frac
	if not frac and left and ROOT.flights[f.key] then frac = 1 - left / max(ROOT.flights[f.key], 1) end
	if db.flightRing and frac then E.DrawProgress(S.flightRing, Clamp(frac, 0, 1)) else S.flightRing:Hide() end
end

--------------------------------------------------------------------------------
-- Farming routes. Gather a herb, ore or lumber and GoodMap offers routes for the
-- zone: a loop for all herbs, one for all ore, one for both, one for the zone's
-- lumber, loops for the zone's most common nodes (computed from GatherMate2's node
-- data, in GoodMap_Routes), and one through the spots you've gathered yourself.
-- Fish from a pool and GoodMap asks, once, whether you'd like a route from pool to
-- pool; fishing anywhere else is left alone. Pick a route and the map becomes a
-- farming map: the loop glows in the color of what you gather, lights run ahead of
-- you to the next spot, which pulses, spots you've cleared dim while they respawn,
-- and the map's edge fills as you go round. Fireflies drift over a herb route,
-- sparks rise over an ore route, leaves fall over a lumber route and bubbles rise
-- over the pools, and every gather sends out a ripple and its name.
--------------------------------------------------------------------------------
local FARM_COLOR = { H = { 0.5, 0.92, 0.45 }, O = { 1, 0.64, 0.3 }, B = { 0.45, 0.86, 0.84 }, L = { 0.95, 0.8, 0.56 },
	F = { 0.42, 0.7, 1 }, V = { 0.76, 0.52, 1 } }
local FARM_DUSK = { H = { 0.02, 0.07, 0.03 }, O = { 0.08, 0.045, 0.02 }, B = { 0.02, 0.06, 0.06 }, L = { 0.07, 0.05, 0.025 },
	F = { 0.015, 0.035, 0.08 }, V = { 0.05, 0.02, 0.09 } }
local FARM_MOTE = { H = { 0.8, 1, 0.55 }, O = { 1, 0.78, 0.4 }, L = { 0.98, 0.68, 0.34 }, L2 = { 0.8, 0.86, 0.42 },
	F = { 0.78, 0.92, 1 }, V = { 0.88, 0.72, 1 }, V2 = { 0.56, 0.32, 1 } }
local FARM_ICON = { H = "Interface\\Icons\\Trade_Herbalism", O = "Interface\\Icons\\Trade_Mining", L = "Interface\\Icons\\INV_Axe_02",
	F = "Interface\\Icons\\Trade_Fishing", V = "Interface\\Icons\\Spell_Shadow_ShadowWordPain" }
local FARM_CATS = { "H", "O", "F" }      -- the routes window's tabs, in order (no lumber or void motes on Forever)
local FARM_REACH = 30                 -- yards: close enough to count a spot as cleared
local FISH_REACH = 40                 -- you fish a pool from the shore
local FARM_RESPAWN = 300              -- seconds a cleared spot stays dim
local FARM_MOTES = 18
local FARM_LIGHTS = 48
local FARM_FX = 4                     -- blooms, ripples or glints at once
local FARM_SPEED = 22                 -- yards a second, until GoodMap learns how fast you go
-- each expansion's lumber, by node: for its name in your language and its icon
local LUMBER_ITEM = { [704] = 245586, [705] = 242691, [706] = 251762, [707] = 251764, [708] = 251763, [709] = 251766,
	[710] = 251767, [711] = 251768, [712] = 251772, [713] = 251773, [714] = 248012, [715] = 256963 }
-- Flying through a void mote pays a little Voidlight Marl and a couple of Coffer Key Shards.
local MARL, SHARDS = 3316, 3310
local GATHER = {}                     -- gathering spell name: "H" herbs, "O" ore, "L" lumber
local FISHING = {}                    -- the fishing spell's name; "VOID" for Void Hole Fishing, at an Oceanic Vortex
local B64 = {}
do
	local digits = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	for i = 1, 64 do B64[digits:byte(i)] = i - 1 end
end
-- (retail-only zone tips and special fishing nodes are left out on Forever)
local FARM_TIPS, SPECIAL_NODE = {}, {}
local KIND_LABEL = { H = L["Herb route"], O = L["Ore route"], B = L["Herb and ore route"], L = L["Lumber route"],
	F = L["Fishing pools"], V = L["Void motes"] }
-- Each kind's own touch over the map: soft blooms over herbs, quick glints over ore,
-- ripples spreading over the pools (size is a share of the map's width).
local FARM_FXLOOK = {
	H = { tex = "Glow", color = { 0.62, 1, 0.5 }, every = 1.5, life = 2.6, size = 0.24, alpha = 0.32 },
	O = { tex = "Glow", color = { 1, 0.88, 0.6 }, every = 1.4, life = 0.55, size = 0.07, alpha = 0.95 },
	F = { tex = "Ring", color = { 0.72, 0.9, 1 }, every = 0.8, life = 2.2, size = 0.2, alpha = 0.6, grow = true },
}

-- What you gather: the spell you cast on the node, and the node's name.
function E.SetupGathering()
	local name = C_Spell and C_Spell.GetSpellName
	if not name then return end
	-- mining, herb gathering, and logging (housing lumber, and the old garrison timber)
	for id, kind in pairs({ [2575] = "O", [195122] = "O", [423341] = "O", [471013] = "O", [2366] = "H", [1239682] = "L", [167895] = "L" }) do
		local n = name(id)
		if type(n) == "string" and not issecret(n) then GATHER[n] = kind end
	end
	for _, id in ipairs({ 7620, 131474, 131476 }) do
		local n = name(id)
		if type(n) == "string" and not issecret(n) then FISHING[n] = true end
	end
	local void = name(1224771)                                    -- Void Hole Fishing
	if type(void) == "string" and not issecret(void) then FISHING[void] = "VOID" end
end

local function SpellName(spellID)
	if not spellID or issecret(spellID) or not C_Spell or not C_Spell.GetSpellName then return end
	local n = C_Spell.GetSpellName(spellID)
	if type(n) == "string" and not issecret(n) then return n end
end

local function GatherKind(spellID)
	local n = SpellName(spellID)
	return n and GATHER[n] or nil
end

-- Which tab a route sits under: herbs, ore, lumber, pools or void motes. A route for
-- herbs and ore sits under both.
local function InCat(route, cat)
	return route.cat == cat or (route.kind == "B" and (cat == "H" or cat == "O"))
end

function E.UNIT_SPELLCAST_SENT(unit, target, guid, spellID)
	if unit ~= "player" then return end
	local n = SpellName(spellID)
	if n and FISHING[n] then E.OnFishCast(target, FISHING[n] == "VOID") return end
	local kind = n and GATHER[n]
	if not kind then return end
	if type(target) ~= "string" or issecret(target) or target == "" then target = nil end
	if issecret(guid) then guid = nil end
	S.gathering = { kind = kind, what = target, guid = guid }
end

function E.UNIT_SPELLCAST_SUCCEEDED(unit, guid, spellID)
	if unit ~= "player" then return end
	local g = S.gathering
	if not g or GatherKind(spellID) ~= g.kind then return end
	if g.guid and (issecret(guid) or guid ~= g.guid) then return end
	S.gathering = nil
	E.OnGather(g.kind, g.what)
end

-- Your zone's map (the node data is kept by zone) and where you are on it.
function E.GatherSpot()
	local mapID = C_Map.GetBestMapForUnit and C_Map.GetBestMapForUnit("player")
	if not mapID or issecret(mapID) then mapID = S.playerMap end
	if not mapID then return end
	local x, y = PlayerPos(mapID)
	if x then return mapID, x, y end
end

function E.OnGather(kind, what)
	local mapID, x, y = E.GatherSpot()
	if not mapID then return end
	if db.farmSpots then E.RememberSpot(mapID, x, y, kind, what) end
	if S.farm then E.FarmGathered(kind, what) return end
	E.Offer(E.RouteMap(mapID), kind)
end

-- A zone's routes for what you farm: the routes window the first time you gather
-- there, a small question after you've stopped a route there (or when you arrive in
-- a farming mode). Once each per zone, until you stop a route.
function E.Offer(zone, cat, ask)
	if not db.farmRoutes or S.mode == "PVP" or S.farm then return end
	S.routesAsked = S.routesAsked or {}
	local key = zone .. cat
	if S.routesAsked[key] or not E.HasRoutes(zone, cat) then return end
	S.routesAsked[key] = true
	if ask or (S.stopped and S.stopped[key]) then E.Ask(zone, cat) else E.ShowRoutes(zone, cat) end
end

-- In a farming mode, the zone you arrive in offers its routes for what you farm.
function E.OfferMode()
	local kind = E.FarmKind()
	if not kind or S.farm then return end
	local mapID = E.GatherSpot()
	if mapID then E.Offer(E.RouteMap(mapID), kind, true) end
end

-- You picked a farming mode: the zone's routes for it come up.
function E.OnFarmMode()
	local kind = E.FarmKind()
	if not (kind and S.ready) then return end
	local mapID = E.GatherSpot() or S.playerMap
	if not mapID then return end
	local zone = E.RouteMap(mapID)
	S.routesAsked = S.routesAsked or {}
	S.routesAsked[zone .. kind] = true
	E.ShowRoutes(zone, kind)
end

-- Fishing. Regular fishing is left alone: GoodMap only speaks up when you fish a
-- pool. A pool's name under your mouse as you cast gives it away; otherwise the
-- catches do, since a pool's catches keep coming from the same object, while every
-- cast in open water is a new bobber.
function E.OnFishCast(target, vortex)
	if vortex then E.OnPool(L["Oceanic Vortex"]) return end   -- you only cast that into a vortex
	local what = target
	if type(what) ~= "string" or issecret(what) or what == "" then
		local tip, line = _G.GameTooltip, _G.GameTooltipTextLeft1
		what = tip and tip:IsShown() and line and line:GetText()
		if type(what) ~= "string" or issecret(what) then what = nil end
	end
	if what and E.PoolNames()[what] then E.OnPool(what) end
end

function E.PoolNames()
	if S.poolNames then return S.poolNames end
	local data, set = E.RoutesData(), {}
	for _, n in ipairs(data and data.pools or {}) do set[n] = true end
	S.poolNames = set
	return set
end

function E.LOOT_READY()
	if not (_G.IsFishingLoot and IsFishingLoot()) then return end
	local guid = _G.GetLootSourceInfo and GetLootSourceInfo(1)
	if type(guid) ~= "string" or issecret(guid) then guid = nil end
	local now = GetTime()
	local pool = guid and guid == S.fishFrom and now - (S.fishAt or 0) < 300
	S.fishFrom, S.fishAt = guid, now
	local f = S.farm
	if f and f.route.kind == "F" then
		local _, item
		if _G.GetLootSlotInfo then _, item = GetLootSlotInfo(1) end
		if type(item) ~= "string" or issecret(item) or item == "" then item = nil end
		E.FarmGathered("F", item)
	end
	if pool then E.OnPool(nil, guid) end
end

-- You're fishing a pool: GoodMap remembers where it was, and asks once per zone
-- whether you'd like a route from pool to pool.
function E.OnPool(name, guid)
	S.poolsSeen = S.poolsSeen or {}
	if not (guid and S.poolsSeen[guid]) then
		if guid then S.poolsSeen[guid] = true end
		E.RememberPool(name)
	end
	if S.farm or not db.farmFish or S.mode == "PVP" then return end
	local mapID = E.GatherSpot()
	if not mapID then return end
	local zone = E.RouteMap(mapID)
	S.routesAsked = S.routesAsked or {}
	if S.routesAsked[zone .. "F"] then return end
	S.routesAsked[zone .. "F"] = true
	if E.HasRoutes(zone, "F") then E.Ask(zone, "F", "pool") end
end

-- The pool is about 15 yards in front of you, where your line went in.
function E.RememberPool(name)
	if not db.farmSpots then return end
	local mapID, x, y = E.GatherSpot()
	local r = mapID and MapRect(mapID)
	if not r then return end
	local facing = GetPlayerFacing and GetPlayerFacing()
	if facing and not issecret(facing) then
		local a = facing + math.pi
		x, y = x + sin(a) * 15 / abs(r[4]), y + cos(a) * 15 / abs(r[3])
	end
	E.RememberSpot(mapID, Clamp(x, 0, 1), Clamp(y, 0, 1), "F", name)
end

-- Void motes are retail-only: nothing to learn on Forever.
function E.CURRENCY_DISPLAY_UPDATE() end
function E.OnMote() end

-- The map the routes are kept by: yours, or the zone around a cave or a town.
function E.RouteMap(mapID)
	local data = E.RoutesData()
	local id = mapID
	for _ = 1, 2 do
		if (data and data.maps and data.maps[id]) or ROOT.spots[id] then return id end
		local info = C_Map.GetMapInfo(id)
		id = info and info.parentMapID
		if not id or id == 0 or issecret(id) then break end
	end
	return mapID
end

-- Spots you've gathered, by zone (shared by your characters): up to 150 of each kind (the oldest go).
function E.RememberSpot(mapID, x, y, kind, what)
	local spots = ROOT.spots[mapID]
	if not spots then spots = {}; ROOT.spots[mapID] = spots end
	local same, oldest = 0, nil
	for i, s in ipairs(spots) do
		if s.k == kind then
			if abs(s.x - x) < 0.004 and abs(s.y - y) < 0.004 then s.c = (s.c or 1) + 1 return end
			same = same + 1
			oldest = oldest or i
		end
	end
	if same >= 150 then tremove(spots, oldest) end
	spots[#spots + 1] = { x = floor(x * 10000 + 0.5) / 10000, y = floor(y * 10000 + 0.5) / 10000, k = kind, n = what, c = 1 }
	S.mySpots = nil                                      -- your routes get worked out again
end

-- GoodMap_Routes, loaded the first time it's needed.
function E.RoutesData()
	if _G.GoodMap_RoutesData == nil and not S.routesTried then
		S.routesTried = true
		local load = Pathway.AddOns.LoadAddOn
		if load then pcall(load, "GoodMap_Routes") end
	end
	return _G.GoodMap_RoutesData
end

function E.RoutesFor(mapID)
	local list = {}
	local data = E.RoutesData()
	local raw = data and data.maps and data.maps[mapID]
	local all = { H = L["All herbs"], O = L["All ore"], B = L["Herbs and ore"], L = L["All lumber"], F = L["All fishing pools"], V = L["All void motes"] }
	for _, r in ipairs(raw or {}) do
		local kind, node = r[1], r[2]
		local name = node == 0 and all[kind] or E.NodeName(node) or all[kind]
		if all[kind] then
			list[#list + 1] = { map = mapID, kind = kind, node = node, nodes = r[3], raw = r[4], name = name, cat = kind == "B" and "H" or kind }
		end
	end
	for _, cat in ipairs(FARM_CATS) do
		local mine = E.MySpotsRoute(mapID, cat)
		if mine then list[#list + 1] = mine end
	end
	return list
end

function E.HasRoutes(mapID, cat)
	for _, r in ipairs(E.RoutesFor(mapID)) do if InCat(r, cat) then return true end end
	return false
end

-- A node's name in your language: herbs and lumber are named after their items. Ore
-- and pools as GatherMate2 has them.
local function NodeItem(node)
	local data = _G.GoodMap_RoutesData
	return LUMBER_ITEM[node] or (data and data.items and data.items[node])
end

function E.NodeName(node)
	if SPECIAL_NODE[node] then return SPECIAL_NODE[node] end
	local item = NodeItem(node)
	if item and C_Item and Pathway.Item.GetItemNameByID then
		local n = Pathway.Item.GetItemNameByID(item)
		if type(n) == "string" and not issecret(n) and n ~= "" then return n end
		if Pathway.Item.RequestLoadItemDataByID then pcall(Pathway.Item.RequestLoadItemDataByID, item) end
	end
	local data = E.RoutesData()
	return data and data.names and data.names[node]
end

local function RouteIcon(route)
	local item = route.node ~= 0 and NodeItem(route.node)
	if item and C_Item and Pathway.Item.GetItemIconByID then
		local icon = Pathway.Item.GetItemIconByID(item)
		if icon and not issecret(icon) then return icon end
	end
	if route.kind == "V" and C_CurrencyInfo and C_CurrencyInfo.GetCurrencyInfo then
		local info = C_CurrencyInfo.GetCurrencyInfo(MARL)
		local icon = info and info.iconFileID
		if icon and not issecret(icon) then return icon end
	end
	return FARM_ICON[route.kind] or FARM_ICON.H
end

-- Spots: 5 characters each, x and y as two base-64 digits out of 4095, then how many nodes.
function E.RoutePoints(route)
	if route.pts then return route.pts end
	local raw, pts = route.raw, {}
	for i = 1, #raw - 4, 5 do
		local a, b, c, d, w = raw:byte(i, i + 4)
		pts[#pts + 1] = { (B64[a] * 64 + B64[b]) / 4095, (B64[c] * 64 + B64[d]) / 4095, B64[w] }
	end
	route.pts = pts
	return pts
end

-- The route in world positions (to draw it on any map and measure it in yards).
function E.RouteWorld(route)
	if route.world then return route.world end
	local w = { at = {} }
	for i, p in ipairs(E.RoutePoints(route)) do
		local c, wx, wy = E.MapToWorld(route.map, p[1], p[2])
		if not c then return end
		w.cont, w[i] = c, { wx, wy, p[3] }
	end
	if #w < 2 then return end
	local len = 0
	for i = 1, #w do
		local a, b = w[i], w[i % #w + 1]
		w.at[i] = len
		len = len + sqrt((a[1] - b[1]) ^ 2 + (a[2] - b[2]) ^ 2)
	end
	w.len = len
	route.world = w
	return w
end

-- A loop through the spots you've gathered, fished or flown through here, one per kind.
local MINE_NAME = { H = L["Your herb spots"], O = L["Your ore spots"], L = L["Your lumber spots"], F = L["Your pool spots"], V = L["Your void motes"] }
function E.MySpotsRoute(mapID, cat)
	cat = cat or "H"
	local all = ROOT.spots[mapID]
	if not all or #all < 6 then return end
	S.mySpots = S.mySpots or {}
	local key = mapID .. cat
	if S.mySpots[key] then return S.mySpots[key] end
	local spots = {}
	for _, s in ipairs(all) do if s.k == cat then spots[#spots + 1] = s end end
	if #spots < 6 then return end
	local r = MapRect(mapID)
	if not r then return end
	local W, H = abs(r[4]), abs(r[3])
	local pts = {}
	for _, s in ipairs(spots) do
		local near
		for _, p in ipairs(pts) do
			if ((p[1] - s.x) * W) ^ 2 + ((p[2] - s.y) * H) ^ 2 < 1600 then near = p break end   -- within 40 yards
		end
		if near then near[3] = near[3] + (s.c or 1) else pts[#pts + 1] = { s.x, s.y, s.c or 1 } end
	end
	if #pts < 5 then return end
	if #pts > 120 then
		tsort(pts, function(a, b) return a[3] > b[3] end)
		for i = #pts, 121, -1 do pts[i] = nil end
	end
	local order, route = E.Loop(pts, W, H), {}
	for i, k in ipairs(order) do route[i] = pts[k] end
	local mine = { map = mapID, kind = cat, node = 0, nodes = #spots, pts = route, name = MINE_NAME[cat], mine = true, cat = cat }
	S.mySpots[key] = mine
	return mine
end

-- The shortest loop found quickly: nearest neighbour first, then untangled (2-opt).
function E.Loop(P, W, H)
	local n = #P
	local function d(a, b)
		local p, q = P[a], P[b]
		return sqrt(((p[1] - q[1]) * W) ^ 2 + ((p[2] - q[2]) * H) ^ 2)
	end
	local t, used = { 1 }, { true }
	for _ = 2, n do
		local last, best, bd = t[#t], nil, nil
		for k = 1, n do
			if not used[k] then
				local dd = d(last, k)
				if not bd or dd < bd then best, bd = k, dd end
			end
		end
		t[#t + 1], used[best] = best, true
	end
	local better, rounds = true, 0
	while better and rounds < 40 do
		better, rounds = false, rounds + 1
		for i = 1, n - 2 do
			for j = i + 2, (i == 1) and n - 1 or n do
				local a, b, c, e = t[i], t[i + 1], t[j], t[j % n + 1]
				if d(a, c) + d(b, e) < d(a, b) + d(c, e) - 1e-6 then
					local lo, hi = i + 1, j
					while lo < hi do t[lo], t[hi] = t[hi], t[lo]; lo, hi = lo + 1, hi - 1 end
					better = true
				end
			end
		end
	end
	return t
end

-- A route's lap: what GoodMap has learned from your own laps, or worked out from its
-- length, how fast you usually go and a moment at each spot.
local function RouteKey(route)
	return route.map .. route.kind .. route.node .. (route.mine and "m" or "")
end
local function SpotTime(kind) return kind == "F" and 45 or 3 end
function E.LapMinutes(route)
	local learned = ROOT.laps[RouteKey(route)]
	if learned then return max(1, floor(learned / 60 + 0.5)) end
	local w, n = E.RouteWorld(route), #E.RoutePoints(route)
	if not w then return 0 end
	local speed = ROOT.laps.speed or FARM_SPEED
	return max(1, floor((w.len / speed + n * SpotTime(route.kind)) / 60 + 0.5))
end

--------------------------------------------------------------------------------
-- The routes window: a tab for each kind the zone has (herbs, ore, lumber, pools,
-- void motes), its routes with how many spots and about how long a lap takes, and a
-- tip for the zone. Hover a route to see it on the map, click it to follow it.
--------------------------------------------------------------------------------
local ROUTES_W = 440
local function RouteRow(f)
	local b = CreateFrame("Button", nil, f)
	b:SetSize(ROUTES_W - 48, 36)
	b.hl = b:CreateTexture(nil, "HIGHLIGHT")
	b.hl:SetAllPoints()
	b.hl:SetColorTexture(1, 1, 1, 0.08)
	b.icon = b:CreateTexture(nil, "ARTWORK")
	b.icon:SetSize(28, 28)
	b.icon:SetPoint("LEFT", b, "LEFT", 4, 0)
	b.icon2 = b:CreateTexture(nil, "OVERLAY")
	b.icon2:SetSize(18, 18)
	b.icon2:SetPoint("BOTTOMRIGHT", b.icon, "BOTTOMRIGHT", 4, -3)
	b.name = b:CreateFontString(nil, "OVERLAY", "GameFontNormal")
	b.name:SetPoint("TOPLEFT", b.icon, "TOPRIGHT", 10, -1)
	b.name:SetJustifyH("LEFT")
	b.name:SetWidth(ROUTES_W - 130)
	b.name:SetWordWrap(false)
	b.info = b:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
	b.info:SetPoint("TOPLEFT", b.name, "BOTTOMLEFT", 0, -3)
	b.info:SetTextColor(0.72, 0.72, 0.75)
	b.on = b:CreateTexture(nil, "OVERLAY")
	b.on:SetTexture("Interface\\Buttons\\UI-CheckBox-Check")
	b.on:SetSize(22, 22)
	b.on:SetPoint("RIGHT", b, "RIGHT", -6, 0)
	b:SetScript("OnEnter", function(self) E.PreviewRoute(self.route) end)
	b:SetScript("OnLeave", function() E.PreviewRoute(nil) end)
	b:SetScript("OnClick", function(self) E.StartRoute(self.route); f:Hide() end)
	return b
end

local function OptionBox(f, key, text)
	local cb = CreateFrame("CheckButton", nil, f, "UICheckButtonTemplate")
	cb:SetSize(24, 24)
	cb.label = f:CreateFontString(nil, "OVERLAY", "GameFontHighlight")
	cb.label:SetPoint("LEFT", cb, "RIGHT", 2, 1)
	cb.label:SetText(text)
	cb:SetScript("OnClick", function(self) E.Set(key, self:GetChecked() and true or false) end)
	cb.key = key
	return cb
end

local TAB_NAME, EMPTY_TEXT
function E.BuildRoutes()
	TAB_NAME = TAB_NAME or { H = L["Herbs"], O = L["Ore"], L = L["Lumber"], F = L["Fishing"], V = L["Void motes"] }
	EMPTY_TEXT = EMPTY_TEXT or {
		H = L["No herb routes here yet. Gather a few herbs and GoodMap makes one from your spots."],
		O = L["No ore routes here yet. Mine a few nodes and GoodMap makes one from your spots."],
		L = L["No lumber routes here yet. Chop a few trees and GoodMap makes one from your spots."],
		F = L["No pool routes here yet. Fish a few pools and GoodMap makes one from them."],
		V = L["GoodMap learns where void motes are as you fly through them. After a few, it makes a route."],
	}
	local f = CreateFrame("Frame", "GoodMapRoutes", UIParent, "BackdropTemplate")
	f:SetSize(ROUTES_W, 200)
	f:SetPoint("CENTER", UIParent, "CENTER", 0, 80)
	f:SetFrameStrata("DIALOG")
	f:SetClampedToScreen(true)
	f:EnableMouse(true)
	f:SetMovable(true)
	f:RegisterForDrag("LeftButton")
	f:SetScript("OnDragStart", f.StartMoving)
	f:SetScript("OnDragStop", f.StopMovingOrSizing)
	if f.SetBackdrop and _G.BACKDROP_DIALOG_32_32 then f:SetBackdrop(_G.BACKDROP_DIALOG_32_32) end
	f.title = f:CreateFontString(nil, "OVERLAY", "GameFontNormalLarge")
	f.title:SetPoint("TOP", f, "TOP", 0, -22)
	f.title:SetText(L["Farming routes"])
	f.zone = f:CreateFontString(nil, "OVERLAY", "GameFontHighlight")
	f.zone:SetPoint("TOP", f.title, "BOTTOM", 0, -4)
	-- tabs: herbs, ore, lumber, pools, void motes (those the zone has, and what you farm)
	f.tabs = {}
	for i, cat in ipairs(FARM_CATS) do
		local t = CreateFrame("Button", nil, f)
		t:SetSize(80, 24)
		t.bg = t:CreateTexture(nil, "BACKGROUND")
		t.bg:SetAllPoints()
		t.hl = t:CreateTexture(nil, "HIGHLIGHT")
		t.hl:SetAllPoints()
		t.hl:SetColorTexture(1, 1, 1, 0.06)
		t.line = t:CreateTexture(nil, "ARTWORK")
		t.line:SetPoint("BOTTOMLEFT", t, "BOTTOMLEFT")
		t.line:SetPoint("BOTTOMRIGHT", t, "BOTTOMRIGHT")
		t.line:SetHeight(2)
		t.icon = t:CreateTexture(nil, "ARTWORK")
		t.icon:SetSize(16, 16)
		t.icon:SetPoint("LEFT", t, "LEFT", 5, 0)
		t.icon:SetTexture(FARM_ICON[cat])
		t.label = t:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
		t.label:SetPoint("LEFT", t.icon, "RIGHT", 4, 0)
		t.label:SetWidth(54)
		t.label:SetJustifyH("LEFT")
		t.label:SetWordWrap(false)
		t.label:SetText(TAB_NAME[cat])
		t.cat = cat
		t:SetScript("OnClick", function(self) f.cat = self.cat; E.PreviewRoute(nil); E.FillRoutes(f) end)
		t:Hide()
		f.tabs[i] = t
	end
	f.empty = f:CreateFontString(nil, "OVERLAY", "GameFontHighlight")
	f.empty:SetWidth(ROUTES_W - 70)
	f.tip = f:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
	f.tip:SetWidth(ROUTES_W - 64)
	f.tip:SetJustifyH("LEFT")
	f.tip:SetTextColor(0.78, 0.76, 0.66)
	f.rows = {}
	f.path = OptionBox(f, "farmPath", L["Path on the map"])
	f.arrow = OptionBox(f, "farmArrow", L["Waypoint arrow"])
	f.stop = CreateFrame("Button", nil, f, "UIPanelButtonTemplate")
	f.stop:SetSize(120, 24)
	f.stop:SetText(L["Stop route"])
	f.stop:SetScript("OnClick", function() E.StopRoute(); E.FillRoutes(f) end)
	f.close = CreateFrame("Button", nil, f, "UIPanelButtonTemplate")
	f.close:SetSize(96, 24)
	f.close:SetPoint("BOTTOMRIGHT", f, "BOTTOMRIGHT", -22, 20)
	f.close:SetText(_G.CLOSE or L["Close"])
	f.close:SetScript("OnClick", function() f:Hide() end)
	f.stop:SetPoint("RIGHT", f.close, "LEFT", -8, 0)
	f.credit = f:CreateFontString(nil, "OVERLAY", "GameFontDisableSmall")
	f.credit:SetPoint("BOTTOMLEFT", f, "BOTTOMLEFT", 24, 26)
	f.credit:SetWidth(170)
	f.credit:SetJustifyH("LEFT")
	f.credit:SetText(L["Routes from GatherMate2's node data"])
	f:Hide()
	f:SetScript("OnHide", function() E.PreviewRoute(nil) end)
	if _G.UISpecialFrames then table.insert(_G.UISpecialFrames, "GoodMapRoutes") end   -- Esc closes it
	S.routesWin = f
	return f
end

function E.ShowRoutes(mapID, cat)
	mapID = mapID or E.GatherSpot() or S.playerMap
	if not mapID then return end
	mapID = E.RouteMap(mapID)
	local f = S.routesWin or E.BuildRoutes()
	f.mapID = mapID
	f.cat = cat or (S.farm and S.farm.route.cat) or E.FarmKind() or "H"
	E.FillRoutes(f)
	f:Show()
end

-- A small question: show this zone's routes? For a pool you've started fishing, or
-- for what you farm, when there's no window up already.
local ASK_TEXT
function E.Ask(mapID, cat, reason)
	ASK_TEXT = ASK_TEXT or {
		H = L["There are herb routes in %s. Show them?"],
		O = L["There are ore routes in %s. Show them?"],
		L = L["There are lumber routes in %s. Show them?"],
		F = L["There are fishing pool routes in %s. Show them?"],
		V = L["There are void mote routes in %s. Show them?"],
	}
	local f = S.askWin
	if not f then
		f = CreateFrame("Frame", "GoodMapAsk", UIParent, "BackdropTemplate")
		f:SetSize(360, 170)
		f:SetPoint("CENTER", UIParent, "CENTER", 0, 160)
		f:SetFrameStrata("DIALOG")
		f:SetClampedToScreen(true)
		f:EnableMouse(true)
		f:SetMovable(true)
		f:RegisterForDrag("LeftButton")
		f:SetScript("OnDragStart", f.StartMoving)
		f:SetScript("OnDragStop", f.StopMovingOrSizing)
		if f.SetBackdrop and _G.BACKDROP_DIALOG_32_32 then f:SetBackdrop(_G.BACKDROP_DIALOG_32_32) end
		f.icon = f:CreateTexture(nil, "ARTWORK")
		f.icon:SetSize(36, 36)
		f.icon:SetPoint("TOPLEFT", f, "TOPLEFT", 24, -24)
		f.title = f:CreateFontString(nil, "OVERLAY", "GameFontNormalLarge")
		f.title:SetPoint("TOPLEFT", f.icon, "TOPRIGHT", 12, -2)
		f.text = f:CreateFontString(nil, "OVERLAY", "GameFontHighlight")
		f.text:SetPoint("TOPLEFT", f.title, "BOTTOMLEFT", 0, -6)
		f.text:SetWidth(262)
		f.text:SetJustifyH("LEFT")
		f.never = OptionBox(f, "farmFish", L["Don't ask again"])
		f.never:SetPoint("BOTTOMLEFT", f, "BOTTOMLEFT", 22, 18)
		f.never:SetScript("OnClick", function() end)                -- it counts when you answer
		local function answer(yes)
			if f.never:GetChecked() then E.Set(f.cat == "F" and f.reason == "pool" and "farmFish" or "farmRoutes", false) end
			f:Hide()
			if yes then E.ShowRoutes(f.mapID, f.cat) end
		end
		f.yes = CreateFrame("Button", nil, f, "UIPanelButtonTemplate")
		f.yes:SetSize(132, 24)
		f.yes:SetScript("OnClick", function() answer(true) end)
		f.no = CreateFrame("Button", nil, f, "UIPanelButtonTemplate")
		f.no:SetSize(104, 24)
		f.no:SetScript("OnClick", function() answer(false) end)
		f.no:SetPoint("BOTTOMRIGHT", f, "BOTTOMRIGHT", -22, 46)
		f.yes:SetPoint("RIGHT", f.no, "LEFT", -8, 0)
		f:Hide()
		if _G.UISpecialFrames then table.insert(_G.UISpecialFrames, "GoodMapAsk") end   -- Esc closes it
		S.askWin = f
	end
	if S.routesWin and S.routesWin:IsShown() then return end
	local info = C_Map.GetMapInfo(mapID)
	local zone = info and info.name
	if type(zone) ~= "string" or issecret(zone) then zone = nil end
	local pool = cat == "F" and reason == "pool"
	f.mapID, f.cat, f.reason = mapID, cat, reason
	f.icon:SetTexture(RouteIcon({ kind = cat, node = 0 }))
	f.title:SetText(pool and L["Fishing a pool?"] or L["Farming routes"])
	f.text:SetText(format(pool and L["GoodMap knows where pools come up in %s. Want a route from pool to pool?"] or ASK_TEXT[cat], zone or L["this zone"]))
	f.yes:SetText(pool and L["Show pool routes"] or L["Show routes"])
	f.no:SetText(pool and L["Just fishing"] or L["Not now"])
	f:SetHeight(max(170, 142 + (f.text:GetStringHeight() or 30)))
	f.never:SetChecked(false)
	f:Show()
end

local function SameRoute(a, b)
	return a and b and a.map == b.map and a.kind == b.kind and a.node == b.node and (a.mine or false) == (b.mine or false)
end

function E.FillRoutes(f)
	local info = C_Map.GetMapInfo(f.mapID)
	local zone = info and info.name
	f.zone:SetText((type(zone) == "string" and not issecret(zone)) and zone or "")
	local all, has = E.RoutesFor(f.mapID), {}
	for _, r in ipairs(all) do
		for _, cat in ipairs(FARM_CATS) do if InCat(r, cat) then has[cat] = true end end
	end
	local want = E.FarmKind()
	if not (has[f.cat or ""] or f.cat == want) then
		for _, cat in ipairs(FARM_CATS) do if has[cat] then f.cat = cat break end end
		f.cat = has[f.cat or ""] and f.cat or want or "H"
	end
	local routes = {}
	for _, r in ipairs(all) do if InCat(r, f.cat) then routes[#routes + 1] = r end end
	local y = -64
	local tabs = {}
	for _, t in ipairs(f.tabs) do
		if has[t.cat] or t.cat == f.cat then tabs[#tabs + 1] = t else t:Hide() end
	end
	if #tabs > 1 then
		local x = -(#tabs * 84 - 4) / 2
		for _, t in ipairs(tabs) do
			local on = t.cat == f.cat
			local c = FARM_COLOR[t.cat]
			t:ClearAllPoints()
			t:SetPoint("TOPLEFT", f, "TOP", x, -60)
			t.bg:SetColorTexture(1, 1, 1, on and 0.1 or 0.03)
			t.line:SetColorTexture(c[1], c[2], c[3], on and 0.9 or 0)
			t.label:SetTextColor(on and 1 or 0.62, on and 1 or 0.62, on and 1 or 0.65)
			t.icon:SetDesaturated(not on)
			t:Show()
			x = x + 84
		end
		y = -92
	else
		for _, t in ipairs(tabs) do t:Hide() end
	end
	for i, route in ipairs(routes) do
		local b = f.rows[i] or RouteRow(f)
		f.rows[i] = b
		b.route = route
		local both = route.kind == "B"
		b.icon:SetTexture(both and FARM_ICON.H or RouteIcon(route))
		b.icon2:SetTexture(FARM_ICON.O)
		b.icon2:SetShown(both)
		b.name:SetText(route.name)
		b.info:SetText(format(L["%d spots · about %d min a lap"], #E.RoutePoints(route), E.LapMinutes(route)))
		b.on:SetShown(S.farm and SameRoute(S.farm.route, route) or false)
		b:ClearAllPoints()
		b:SetPoint("TOP", f, "TOP", 0, y)
		b:Show()
		y = y - 38
	end
	for i = #routes + 1, #f.rows do f.rows[i]:Hide() end
	f.empty:ClearAllPoints()
	f.empty:SetPoint("TOP", f, "TOP", 0, y - 4)
	f.empty:SetText(EMPTY_TEXT[f.cat] or EMPTY_TEXT.H)
	f.empty:SetShown(#routes == 0)
	if #routes == 0 then y = y - 44 end
	local tips = FARM_TIPS[f.mapID]
	local tip = tips and tips[f.cat]
	f.tip:ClearAllPoints()
	f.tip:SetPoint("TOPLEFT", f, "TOPLEFT", 32, y - 4)
	f.tip:SetText(tip and format(L["Tip: %s"], tip) or "")
	f.tip:SetShown(tip ~= nil)
	if tip then y = y - 8 - (f.tip:GetStringHeight() or 14) end
	f.path:ClearAllPoints()
	f.path:SetPoint("TOPLEFT", f, "TOPLEFT", 26, y - 6)
	f.arrow:ClearAllPoints()
	f.arrow:SetPoint("TOPLEFT", f, "TOPLEFT", 226, y - 6)
	f.path:SetChecked(db.farmPath)
	f.arrow:SetChecked(db.farmArrow)
	f.stop:SetShown(S.farm ~= nil)
	f:SetHeight(-y + 90)
end

--------------------------------------------------------------------------------
-- Following a route
--------------------------------------------------------------------------------
function E.StartRoute(route)
	local w = route and E.RouteWorld(route)
	if not w then return end
	if S.farm then E.StopRoute(true) end
	if S.askWin then S.askWin:Hide() end
	S.farm = { route = route, w = w, cleared = {}, gathered = 0, started = GetTime(), lapAt = GetTime(), lap = 1, done = 0, away = 0 }
	S.farm.next = E.FarmNearest() or 1
	-- following a route puts GoodMap in that farming mode, so the next zone offers its routes too
	local kind = route.kind == "B" and (E.FarmKind() == "O" and "O" or "H") or route.kind
	if KIND_MODE[kind] and db.mode ~= "PVP" and db.mode ~= KIND_MODE[kind] then db.mode = KIND_MODE[kind] end
	E.FarmGuide()
	E.FarmLookUpdate()
	E.DrawFarmRoute()
	E.FarmHud()
	if S.farmPulse then PlayRipple(S.farmPulse.ripples[1], FARM_COLOR[route.kind] or FARM_COLOR.B, 0.8) end
end

function E.StopRoute(quiet)
	local f = S.farm
	if not f then return end
	S.farm = nil
	if f.pinned and C_Map.ClearUserWaypoint then C_Map.ClearUserWaypoint() end
	-- the next time you gather here, GoodMap asks whether to load a route again
	local key = f.route.map .. (f.route.cat or f.route.kind)
	S.stopped = S.stopped or {}
	S.stopped[key] = true
	if S.routesAsked then S.routesAsked[key] = nil end
	E.FarmLookUpdate()
	E.DrawFarmRoute()
	if not quiet and S.routesWin and S.routesWin:IsShown() then E.FillRoutes(S.routesWin) end
end

-- The spot to head for first: the nearest, or the one after it if you're already past it.
function E.FarmNearest()
	local f = S.farm
	local wx, wy = UnitPosition("player")
	if not (f and wx) or issecret(wx) or issecret(wy) then return end
	local w, best, bd = f.w, nil, nil
	for i, p in ipairs(w) do
		local dd = (p[1] - wx) ^ 2 + (p[2] - wy) ^ 2
		if not bd or dd < bd then best, bd = i, dd end
	end
	local n = #w
	local p, q = w[best], w[best % n + 1]
	if (q[1] - wx) ^ 2 + (q[2] - wy) ^ 2 < (q[1] - p[1]) ^ 2 + (q[2] - p[2]) ^ 2 then best = best % n + 1 end
	return best
end

-- The waypoint arrow: your map pin on the next spot, so the game's arrow and
-- distance lead you there.
function E.FarmGuide()
	local f = S.farm
	if not f then return end
	if db.farmArrow then
		local p = E.RoutePoints(f.route)[f.next]
		if p and E.PinInWorld(f.route.map, p[1], p[2]) then f.pinned = true end
	elseif f.pinned then
		f.pinned = nil
		if C_Map.ClearUserWaypoint then C_Map.ClearUserWaypoint() end
	end
end

-- A spot reached: it dims while it respawns, and the next one lights up.
function E.FarmReached(i)
	local f = S.farm
	local n = #f.w
	f.cleared[i] = GetTime()
	f.done = f.done + 1
	if f.done >= n then
		f.done, f.lap = 0, f.lap + 1
		E.LearnLap(f)
	end
	f.next = i % n + 1
	E.FarmGuide()
	E.FarmLightsPath()
	E.PlaceFarmNext()
end

-- A lap done: GoodMap quietly learns how long the route takes you, and how fast you go,
-- for the lap times in the routes window.
function E.LearnLap(f)
	local now = GetTime()
	local lap = now - (f.lapAt or now)
	f.lapAt = now
	if lap < 20 or lap > 7200 then return end
	local key = RouteKey(f.route)
	local was = ROOT.laps[key]
	ROOT.laps[key] = was and (was * 0.6 + lap * 0.4) or lap
	local moving = lap - #f.w * SpotTime(f.route.kind)
	if moving > 10 and f.w.len then
		local v = Clamp(f.w.len / moving, 6, 60)
		local speed = ROOT.laps.speed
		ROOT.laps.speed = speed and (speed * 0.7 + v * 0.3) or v
	end
end

function E.FarmGathered(kind, what)
	local f = S.farm
	f.gathered = f.gathered + 1
	local c = FARM_COLOR[kind] or FARM_COLOR.B
	local p = S.farmPulse
	if p and S.farmLook then
		p.flip = 3 - (p.flip or 1)
		PlayRipple(p.ripples[p.flip], c, 0.85)
		if what then
			p.float:SetText("+ " .. what)
			p.float:SetTextColor(c[1], c[2], c[3])
			p.floatAnim:Stop(); p.float:Show(); p.floatAnim:Play()
		end
	end
	E.FarmHud()
end

-- Five times a second while you follow a route.
function E.FarmTick()
	local f = S.farm
	if not f then return end
	local wx, wy = UnitPosition("player")
	if not wx or issecret(wx) or issecret(wy) then return end
	-- left the zone for a while: the route stops
	local mapID = f.route.map
	if E.WorldToMap(mapID, f.w.cont, wx, wy) then f.away = 0 else
		f.away = f.away + 0.2
		if f.away > 20 then
			E.StopRoute()
			Print(L["Farming route stopped: you left the zone."])
			return
		end
	end
	local w, n = f.w, #f.w
	local reach = f.route.kind == "F" and FISH_REACH or FARM_REACH
	-- reached the next spot, or one of the next few (you went your own way)
	for k = 0, 3 do
		local j = (f.next + k - 1) % n + 1
		local p = w[j]
		if (p[1] - wx) ^ 2 + (p[2] - wy) ^ 2 < reach * reach then
			for _ = 0, k do E.FarmReached(f.next) end
			break
		end
	end
	local p = w[f.next]
	f.dist = sqrt((p[1] - wx) ^ 2 + (p[2] - wy) ^ 2)
	E.FarmLookUpdate()
	E.FarmLightsPath()
	E.FarmSpotLook()
	E.FarmHud()
end

--------------------------------------------------------------------------------
-- The farming look
--------------------------------------------------------------------------------
function E.SetupFarming()
	-- the route on the map canvas (above the dusk, below the icons)
	local ff = CreateFrame("Frame", nil, S.canvas)
	ff:SetAllPoints(S.canvas)
	ff:SetFrameLevel(E.PinLevel("PIN_FRAME_LEVEL_MAP_EXPLORATION", 1500) + 3)
	ff:Hide()
	ff.glow, ff.core, ff.lights = {}, {}, {}
	ff:SetScript("OnUpdate", Pathway.Perf.W("Minimap", E.FarmLightsTick))
	S.farmFrame = ff

	-- under the route: a tint of the land's color, a dark rim, fireflies or sparks
	local back = CreateFrame("Frame", nil, S.sc)
	back:SetAllPoints(S.sc)
	back:SetFrameLevel(E.PinLevel("PIN_FRAME_LEVEL_MAP_EXPLORATION", 1500) + 2)
	back:EnableMouse(false)
	back:Hide()
	back.tint = back:CreateTexture(nil, "BACKGROUND")
	back.tint:SetAllPoints()
	back.vignette = FlightTex(back, "BORDER", "Vignette", 0, 0, 0, 0.7)
	back.vignette:SetAllPoints()
	Mask(back.tint); Mask(back.vignette)
	back.motes = {}
	for i = 1, FARM_MOTES do
		local m = FlightTex(back, "ARTWORK", "Glow", 1, 1, 1, 1, "ADD")
		Mask(m)
		back.motes[i] = m
	end
	-- each kind's own touch: blooms over herbs, glints over ore, ripples over pools
	back.fx = {}
	for i = 1, FARM_FX do
		local t = FlightTex(back, "ARTWORK", "Glow", 1, 1, 1, 0, "ADD")
		Mask(t)
		t:Hide()
		back.fx[i] = t
	end
	-- and a slow void storm turning over the map, for void motes
	back.swirl = FlightTex(back, "BORDER", "Clouds", 1, 1, 1, 0.3, "ADD")
	back.swirl:SetPoint("CENTER")
	Mask(back.swirl)
	back.swirl:Hide()
	back:SetScript("OnUpdate", Pathway.Perf.W("Minimap", E.FarmMotesTick))
	Fades(back, 0.7, 0.5)
	S.farmBack = back

	-- over the map: a soft halo on the rim and the lap ring
	local front = CreateFrame("Frame", nil, S.map)
	front:SetAllPoints(S.sc)
	front:SetFrameLevel(9449)
	front:EnableMouse(false)
	front:Hide()
	front.halo = FlightTex(front, "BACKGROUND", "Ring", 1, 1, 1, 0.38, "ADD")
	front.halo:SetPoint("CENTER")
	front.haloPulse = Breathe(front.halo, 0.45, 1, 2.8)
	S.farmRing = E.NewProgress(front)
	Fades(front, 0.7, 0.5)
	S.farmFront = front

	-- gathering: a ripple and the node's name floating up
	local pulse = CreateFrame("Frame", nil, S.map)
	pulse:SetAllPoints(S.sc)
	pulse:SetFrameLevel(9452)
	pulse:EnableMouse(false)
	pulse.ripples = { Ripple(pulse, 300), Ripple(pulse, 300) }
	pulse.float = pulse:CreateFontString(nil, "OVERLAY", "GameFontNormal")
	pulse.float:SetPoint("CENTER", pulse, "CENTER", 0, 18)
	pulse.float:SetShadowOffset(1, -1)
	pulse.float:SetShadowColor(0, 0, 0, 1)
	pulse.float:Hide()
	local fa = pulse.float:CreateAnimationGroup()
	local rise = fa:CreateAnimation("Translation")
	rise:SetOffset(0, 30); rise:SetDuration(1.8); rise:SetSmoothing("OUT")
	local show = fa:CreateAnimation("Alpha")
	show:SetFromAlpha(0); show:SetToAlpha(1); show:SetDuration(0.2)
	local hide = fa:CreateAnimation("Alpha")
	hide:SetFromAlpha(1); hide:SetToAlpha(0); hide:SetDuration(0.6); hide:SetStartDelay(1.2)
	fa:SetScript("OnFinished", function() pulse.float:Hide() end)
	pulse.floatAnim = fa
	S.farmPulse = pulse

	-- the words: the route at the top, what you've gathered and the next spot at the bottom
	local hud = CreateFrame("Frame", nil, S.overlay)
	hud:SetAllPoints(S.overlay)
	hud:SetFrameLevel(S.overlay:GetFrameLevel() + 30)
	hud:EnableMouse(false)
	hud:Hide()
	hud.topShade = FlightTex(hud, "BACKGROUND", "Glow", 0, 0, 0, 0.6)
	hud.bottomShade = FlightTex(hud, "BACKGROUND", "Glow", 0, 0, 0, 0.6)
	Mask(hud.topShade); Mask(hud.bottomShade)
	local function line(r, g, b)
		local fs = hud:CreateFontString(nil, "OVERLAY", "GameFontNormal")
		fs:SetTextColor(r, g, b)
		fs:SetWordWrap(false)
		fs:SetShadowOffset(1, -1)
		fs:SetShadowColor(0, 0, 0, 0.9)
		return fs
	end
	hud.over = line(1, 1, 1)
	hud.name = line(1, 1, 1)
	hud.count = line(1, 1, 1)
	hud.rate = line(0.8, 0.82, 0.86)
	hud.next = line(1, 1, 1)
	hud.over:SetText(L["Farming route"])
	-- stop the route from the map: a small button that shows while you hover it
	local stop = CreateFrame("Button", nil, hud)
	stop:SetSize(18, 18)
	stop:SetNormalAtlas("common-icon-redx")
	stop:SetHighlightAtlas("common-icon-redx")
	stop:SetScript("OnClick", function() E.StopRoute() end)
	Hoverable(stop, function(self) Tooltip(self, L["Stop route"]) end)
	stop:SetMouseClickEnabled(true)
	stop:Hide()
	hud.stop = stop
	Fades(hud, 0.5, 0.4)
	S.farmHud = hud
end

function E.FarmLookWanted()
	local f = S.farm
	if not (f and S.mapShown and S.mode == "NORMAL" and not S.flightOn and not S.houseActive) then return false end
	local mr = MapRect(S.map:GetMapID())
	return (mr and mr[5] == f.w.cont) and true or false
end

function E.FarmLookUpdate()
	local want = E.FarmLookWanted()
	if want == (S.farmLook or false) then return end
	S.farmLook = want
	if want then
		E.FarmLayout()
		FadeIn(S.farmBack); FadeIn(S.farmFront); FadeIn(S.farmHud)
		S.farmFront.haloPulse:Play()
		S.farmRing.headPulse:Play()
	else
		FadeOut(S.farmBack); FadeOut(S.farmFront); FadeOut(S.farmHud)
		S.farmFront.haloPulse:Stop()
		S.farmRing.headPulse:Stop()
	end
	E.ApplyChrome()
	E.ApplyLayers()                               -- quests step aside
	E.UpdateHeading()
end

-- Sizes, places and colors everything for the map's shape and the route.
function E.FarmLayout()
	local hud, back, front = S.farmHud, S.farmBack, S.farmFront
	if not hud then return end
	local f = S.farm
	local kind = f and f.route.kind or "H"
	local c, dusk = FARM_COLOR[kind] or FARM_COLOR.B, FARM_DUSK[kind] or FARM_DUSK.B
	local round, d = S.round, E.Diameter()
	local w, h = S.sc:GetWidth() or d, S.sc:GetHeight() or d
	local font = GameFontNormal:GetFont()
	local small, mid = max(9, floor(d * 0.032 + 0.5)), max(12, floor(d * 0.048 + 0.5))
	local big = Clamp(floor(d * 0.075 + 0.5), 16, 26)
	hud.over:SetFont(font, small, "")
	hud.over:SetTextColor(c[1], c[2], c[3])
	hud.over:SetText(KIND_LABEL[kind] or L["Herb route"])
	hud.name:SetFont(font, mid, "OUTLINE")
	hud.count:SetFont(font, big, "OUTLINE")
	hud.rate:SetFont(font, small, "")
	hud.next:SetFont(font, small + 1, "OUTLINE")
	hud.next:SetTextColor(c[1], c[2], c[3])
	local tw = round and d * 0.62 or w - 16
	for _, fs in ipairs({ hud.over, hud.name, hud.count, hud.rate, hud.next }) do fs:SetWidth(tw) end
	local thick = max(3, db.borderSize + 2)
	local topInset = round and floor(d * 0.075 + 0.5) or 6
	local bottomInset = round and floor(d * 0.085 + 0.5) or thick + 6
	hud.over:ClearAllPoints(); hud.over:SetPoint("TOP", hud, "TOP", 0, -topInset)
	hud.name:ClearAllPoints(); hud.name:SetPoint("TOP", hud.over, "BOTTOM", 0, -1)
	hud.next:ClearAllPoints(); hud.next:SetPoint("BOTTOM", hud, "BOTTOM", 0, bottomInset)
	hud.rate:ClearAllPoints(); hud.rate:SetPoint("BOTTOM", hud.next, "TOP", 0, 2)
	hud.count:ClearAllPoints(); hud.count:SetPoint("BOTTOM", hud.rate, "TOP", 0, 1)
	local topH, bottomH = small + mid + 4, small * 2 + big + 6
	hud.topShade:ClearAllPoints()
	hud.topShade:SetPoint("CENTER", hud, "TOP", 0, -(topInset + topH / 2))
	hud.topShade:SetSize(tw * 1.25, topH * 2.6)
	hud.bottomShade:ClearAllPoints()
	hud.bottomShade:SetPoint("CENTER", hud, "BOTTOM", 0, bottomInset + bottomH / 2)
	hud.bottomShade:SetSize(tw * 1.3, bottomH * 2.2)
	hud.stop:ClearAllPoints()
	if round then hud.stop:SetPoint("CENTER", hud, "CENTER", d * 0.3, d * 0.36)
	else hud.stop:SetPoint("TOPRIGHT", hud, "TOPRIGHT", -6, -6) end

	back.tint:SetColorTexture(dusk[1], dusk[2], dusk[3], 0.32)
	back.vignette:SetVertexColor(dusk[1], dusk[2], dusk[3], 0.75)
	back.w, back.h = w, h
	back.rim = min(w, h) / 2
	for i, m in ipairs(back.motes) do
		-- fireflies drift up, sparks rise faster, leaves tumble down, bubbles wobble up,
		-- void wisps spiral in
		local mk = kind == "B" and ((i % 2 == 0) and "O" or "H") or kind
		local mc = FARM_MOTE[((mk == "L" or mk == "V") and i % 3 == 0) and (mk .. "2") or mk] or FARM_MOTE.H
		m:SetVertexColor(mc[1], mc[2], mc[3], 1)
		m:SetTexture(FLIGHT_TEX .. (mk == "F" and "Ring" or "Glow"))
		m.x, m.y = (random() - 0.5) * w, (random() - 0.5) * h
		m.phase, m.tw = random() * 6.28, 1.2 + random() * 2
		m.spin, m.rot, m.orbit = nil, 0, nil
		if mk == "V" then
			m.size = 2.5 + random() * 3
			m:SetSize(m.size * 2, m.size * 2)
			m.orbit, m.ang, m.rad = true, random() * 6.28, back.rim * (0.3 + random() * 0.65)
			m.va, m.vr = 0.35 + random() * 0.5, -(5 + random() * 8)
			m.vy, m.sway = 0, 0
		elseif mk == "O" then
			m.size = 3 + random() * 3
			m:SetSize(m.size * 2, m.size * 2)
			m.vy, m.sway = 10 + random() * 10, 4 + random() * 6
		elseif mk == "L" then
			m.size = 3 + random() * 3
			m:SetSize(m.size * 2.8, m.size * 1.2)
			m.vy, m.sway = -(6 + random() * 7), 10 + random() * 10
			m.spin, m.rot = (random() - 0.5) * 2.4, random() * 6.28
		elseif mk == "F" then
			m.size = 2 + random() * 3
			m:SetSize(m.size * 2.4, m.size * 2.4)
			m.vy, m.sway = 6 + random() * 7, 2 + random() * 3
		else
			m.size = 4 + random() * 4
			m:SetSize(m.size * 2, m.size * 2)
			m.vy, m.sway = 4 + random() * 5, 4 + random() * 6
		end
		m:SetRotation(m.rot)
	end
	-- the kind's own touch
	local fx = FARM_FXLOOK[kind == "B" and "H" or kind]
	back.fxLook = fx
	for _, t in ipairs(back.fx) do
		t.life = nil
		t:Hide()
		if fx then
			t:SetTexture(FLIGHT_TEX .. fx.tex)
			local fc = kind == "B" and FARM_COLOR.B or fx.color
			t:SetVertexColor(fc[1], fc[2], fc[3], 1)
		end
	end
	back.fxIn, back.fxSize = 0.5, d
	back.gust = kind == "L"
	back.flicker = kind == "O"
	back.swirl:SetShown(kind == "V")
	if kind == "V" then
		local s = max(w, h) * 1.5
		back.swirl:SetSize(s, s)
		back.swirl:SetVertexColor(c[1], c[2], c[3], 0.3)
	end
	front.halo:SetVertexColor(c[1], c[2], c[3], 0.38)
	front.halo:SetSize(d / 0.8 * 1.06, d / 0.8 * 1.06)
	front.halo:SetShown(round)
	for _, r in ipairs(S.farmPulse.ripples) do r:SetSize(d * 1.05, d * 1.05) end
	E.LayoutProgress(S.farmRing, c)
	E.FarmHud()
end

function E.FarmHud()
	local f, hud = S.farm, S.farmHud
	if not (f and hud) then return end
	hud.name:SetText(f.route.name or "")
	local k = f.route.kind
	hud.count:SetText(format(k == "F" and L["%d caught"] or k == "V" and L["%d motes"] or L["%d gathered"], f.gathered))
	local mins = (GetTime() - f.started) / 60
	local rate = mins >= 1 and floor(f.gathered / mins * 60 + 0.5) or nil
	hud.rate:SetText(rate and format(L["%d an hour · lap %d"], rate, f.lap) or format(L["Lap %d"], f.lap))
	hud.next:SetText(f.dist and format(L["Next spot: %s"], E.Yards(f.dist)) or "")
	if S.farmLook then E.DrawProgress(S.farmRing, Clamp(f.done / max(#f.w, 1), 0, 1)) end
end

-- Fireflies drift up and twinkle, sparks rise faster, leaves tumble down in gusts,
-- bubbles wobble up, void wisps spiral in under a slow storm; blooms, glints and
-- ripples come and go. About 40 times a second.
function E.FarmMotesTick(self, elapsed)
	self.acc = (self.acc or 0) + elapsed
	if self.acc < 0.025 then return end
	local dt = min(self.acc, 0.25)
	self.acc = 0
	self.t = (self.t or 0) + dt
	local t, w, h = self.t, self.w or 200, self.h or 200
	local gust = self.gust and 2.5 * max(0, sin(t * 0.45)) ^ 8 or 0   -- now and then the wind picks up
	for _, m in ipairs(self.motes) do
		if m.orbit then
			m.ang, m.rad = m.ang + m.va * dt, m.rad + m.vr * dt
			if m.rad < 8 then m.rad, m.ang = (self.rim or 100) * (0.75 + random() * 0.25), random() * 6.28 end
			m:SetPoint("CENTER", self, "CENTER", cos(m.ang) * m.rad, sin(m.ang) * m.rad)
			m:SetAlpha(Clamp(m.rad / ((self.rim or 100) * 0.35), 0, 1) * (0.45 + 0.45 * sin(t * m.tw + m.phase)))
		else
			m.y = m.y + m.vy * dt
			if m.vy > 0 and m.y > h / 2 + 8 then m.y, m.x = -h / 2 - 8, (random() - 0.5) * w
			elseif m.vy < 0 and m.y < -h / 2 - 8 then m.y, m.x = h / 2 + 8, (random() - 0.5) * w end
			if gust > 0 then
				m.x = m.x + gust * 16 * dt
				if m.x > w / 2 + 10 then m.x = -w / 2 - 10 end
			end
			local x = m.x + sin(t * 0.7 + m.phase) * m.sway
			m:SetPoint("CENTER", self, "CENTER", x, m.y)
			m:SetAlpha(0.25 + 0.6 * (0.5 + 0.5 * sin(t * m.tw + m.phase)))
			if m.spin then m:SetRotation(m.rot + t * m.spin * (1 + gust)) end
		end
	end
	local fx = self.fxLook
	if fx then
		self.fxIn = (self.fxIn or 0) - dt
		if self.fxIn <= 0 then
			self.fxIn = fx.every * (0.6 + random() * 0.8)
			for _, e in ipairs(self.fx) do
				if not e.life then
					e.life, e.age = fx.life, 0
					e.size = (self.fxSize or 200) * fx.size * (0.7 + random() * 0.6)
					e:SetPoint("CENTER", self, "CENTER", (random() - 0.5) * w * 0.75, (random() - 0.5) * h * 0.75)
					e:SetSize(1, 1)
					e:SetAlpha(0)
					e:Show()
					break
				end
			end
		end
		for _, e in ipairs(self.fx) do
			if e.life then
				e.age = e.age + dt
				local p = e.age / e.life
				if p >= 1 then
					e.life = nil
					e:Hide()
				else
					local s = e.size * (fx.grow and (0.2 + 0.8 * p) or (0.55 + 0.45 * sin(p * math.pi)))
					e:SetSize(s, s)
					e:SetAlpha(fx.alpha * (fx.grow and (1 - p) or sin(p * math.pi)))
				end
			end
		end
	end
	if self.swirl:IsShown() then self.swirl:SetRotation(t * 0.06) end
	if self.flicker and S.farmFront then                    -- the rim glows like embers
		local c = FARM_COLOR.O
		S.farmFront.halo:SetVertexColor(c[1], c[2], c[3], 0.24 + 0.16 * (0.5 + 0.5 * sin(t * 7.3) * sin(t * 3.1 + 1)))
	end
end

--------------------------------------------------------------------------------
-- The route on the map: a glowing loop, its spots, the next spot pulsing, and
-- lights running from you toward the next spots.
--------------------------------------------------------------------------------
function E.PreviewRoute(route)
	if S.farmPreview == route then return end
	S.farmPreview = route
	E.DrawFarmRoute()
end

function E.DrawFarmRoute()
	local ff = S.farmFrame
	if not ff then return end
	local route = S.farmPreview or (S.farm and S.farm.route)
	local preview = S.farmPreview ~= nil
	local mapID = S.map:GetMapID()
	local mr = mapID and MapRect(mapID)
	local w = route and E.RouteWorld(route)
	if not (w and mr and mr[5] == w.cont and (preview or db.farmPath)) then
		ff:Hide()
		ff.cpts, ff.lp = nil, nil
		E.FreeFarmPins()
		return
	end
	local c = FARM_COLOR[route.kind] or FARM_COLOR.B
	local cw, ch = S.canvas:GetWidth(), S.canvas:GetHeight()
	local k = 1 / max(S.sc:GetCanvasScale(), 0.01)
	local cp, n = {}, #w
	for i, p in ipairs(w) do
		cp[2 * i - 1] = (p[2] - mr[2]) / mr[4] * cw
		cp[2 * i] = -(p[1] - mr[1]) / mr[3] * ch
	end
	ff.cpts, ff.c = cp, c
	for i = 1, n do
		local j = i % n + 1
		local ax, ay, bx, by = cp[2 * i - 1], cp[2 * i], cp[2 * j - 1], cp[2 * j]
		local g = RouteLine(ff, ff.glow, i, "BORDER", c[1], c[2], c[3], 0.14, 7 * k, "ADD")
		g:SetStartPoint("TOPLEFT", S.canvas, ax, ay); g:SetEndPoint("TOPLEFT", S.canvas, bx, by); g:Show()
		local l = RouteLine(ff, ff.core, i, "ARTWORK", c[1], c[2], c[3], preview and 0.45 or 0.6, 1.5 * k)
		l:SetStartPoint("TOPLEFT", S.canvas, ax, ay); l:SetEndPoint("TOPLEFT", S.canvas, bx, by); l:Show()
	end
	for i = n + 1, #ff.core do ff.core[i]:Hide(); ff.glow[i]:Hide() end
	if ff.lk ~= k then
		ff.lk = k
		for _, l in ipairs(ff.lights) do l:SetSize(8 * k, 8 * k) end
	end
	ff:Show()
	E.PlaceFarmSpots(mapID, w, c)
	E.FarmLightsPath()
end

function E.FreeFarmPins()
	for _, kind in ipairs({ "fspot", "fnext" }) do
		for p in pairs(S.cpins) do if p.kind == kind then E.FreeCanvasPin(p) end end
	end
	S.farmSpots, S.farmNext, S.farmSpotsFor, S.farmSpotsMap = nil, nil, nil, nil
end

function E.PlaceFarmSpots(mapID, w, c)
	local route = S.farmPreview or (S.farm and S.farm.route)
	if S.farmSpots and S.farmSpotsFor == route and S.farmSpotsMap == mapID then
		E.PlaceFarmNext()
		E.FarmSpotLook()
		return
	end
	E.FreeFarmPins()
	S.farmSpotsFor, S.farmSpotsMap = route, mapID
	local level = E.PinLevel("PIN_FRAME_LEVEL_TOPMOST", 2100)
	S.farmSpots = {}
	for i, p in ipairs(w) do
		local s = E.CanvasPin("fspot", level)
		if not s.dot then
			s.ring = s:CreateTexture(nil, "ARTWORK")
			s.ring:SetTexture(CIRCLE_MASK)
			s.ring:SetVertexColor(0, 0, 0, 0.7)
			s.ring:SetPoint("CENTER")
			s.dot = s:CreateTexture(nil, "OVERLAY")
			s.dot:SetTexture(CIRCLE_MASK)
			s.dot:SetPoint("CENTER")
			Mask(s.ring); Mask(s.dot)
			s.clip = true
		end
		local size = 5 + min(p[3], 40) / 8                -- busier spots are a little bigger
		s:SetSize(size + 4, size + 4)
		s.dot:SetSize(size, size)
		s.ring:SetSize(size + 3, size + 3)
		s.dot:SetVertexColor(c[1], c[2], c[3], 1)
		local x, y = E.WorldToMap(mapID, w.cont, p[1], p[2], true)
		E.PlaceCanvasPin(s, x, y)
		S.farmSpots[i] = s
	end
	E.PlaceFarmNext()
	E.FarmSpotLook()
end

-- The next spot: a pulsing beacon in the route's color.
function E.PlaceFarmNext()
	local f = S.farm
	if not (f and S.farmSpots and not S.farmPreview) then
		if S.farmNext then S.farmNext:Hide() end
		return
	end
	local c = FARM_COLOR[f.route.kind] or FARM_COLOR.B
	local nb = S.farmNext
	if not nb then
		nb = E.CanvasPin("fnext", E.PinLevel("PIN_FRAME_LEVEL_TOPMOST", 2100) + 1)
		if not nb.core then
			nb:SetSize(16, 16)
			nb.glow = FlightTex(nb, "BORDER", "Glow", 1, 1, 1, 0.9, "ADD")
			nb.glow:SetSize(30, 30)
			nb.glow:SetPoint("CENTER")
			nb.core = nb:CreateTexture(nil, "OVERLAY")
			nb.core:SetTexture(CIRCLE_MASK)
			nb.core:SetSize(8, 8)
			nb.core:SetPoint("CENTER")
			nb.pulses, nb.rings = {}, {}
			for i = 1, 2 do
				local p = FlightTex(nb, "ARTWORK", "Ring", 1, 1, 1, 0.9, "ADD")
				p:SetSize(54, 54)
				p:SetPoint("CENTER")
				local ag = p:CreateAnimationGroup()
				ag:SetLooping("REPEAT")
				local grow = ag:CreateAnimation("Scale")
				grow:SetScaleFrom(0.2, 0.2); grow:SetScaleTo(1, 1); grow:SetDuration(1.8); grow:SetSmoothing("OUT")
				local fade = ag:CreateAnimation("Alpha")
				fade:SetFromAlpha(1); fade:SetToAlpha(0); fade:SetDuration(1.8); fade:SetSmoothing("IN")
				if i == 2 then grow:SetStartDelay(0.9); fade:SetStartDelay(0.9) end
				Mask(p)
				nb.pulses[i], nb.rings[i] = ag, p
			end
			Mask(nb.glow); Mask(nb.core)
			nb.clip = true
		end
		S.farmNext = nb
	end
	nb.glow:SetVertexColor(c[1], c[2], c[3], 0.9)
	nb.core:SetVertexColor(1, 1, 1, 1)
	for i, p in ipairs(nb.rings) do p:SetVertexColor(c[1], c[2], c[3], 0.9); nb.pulses[i]:Play() end
	local s = S.farmSpots[f.next]
	if s and s.nx then E.PlaceCanvasPin(nb, s.nx, s.ny) end
end

-- Cleared spots dim while they respawn.
function E.FarmSpotLook()
	local f, spots = S.farm, S.farmSpots
	if not spots then return end
	local now = GetTime()
	for i, s in ipairs(spots) do
		local t = f and not S.farmPreview and f.cleared[i]
		s:SetAlpha((t and now - t < FARM_RESPAWN) and 0.3 or 1)
	end
end

-- The lights' path: from you, through the next few spots.
function E.FarmLightsPath()
	local ff, f = S.farmFrame, S.farm
	local cp = ff and ff.cpts
	if not (cp and f and not S.farmPreview) then if ff then ff.lp = nil end return end
	local lp, cum, n = {}, { 0 }, #f.w
	local mapID = S.map:GetMapID()
	local px, py = PlayerPos(mapID)
	if px then lp[1], lp[2] = px * S.canvas:GetWidth(), -py * S.canvas:GetHeight() end
	for k = 0, min(3, n - 1) do
		local i = (f.next + k - 1) % n + 1
		lp[#lp + 1], lp[#lp + 2] = cp[2 * i - 1], cp[2 * i]
	end
	for i = 2, #lp / 2 do
		local dx, dy = lp[2 * i - 1] - lp[2 * i - 3], lp[2 * i] - lp[2 * i - 2]
		cum[i] = cum[i - 1] + sqrt(dx * dx + dy * dy)
	end
	ff.lp, ff.lcum = lp, cum
end

-- About 40 times a second: the lights run on toward the next spots.
function E.FarmLightsTick(self, elapsed)
	self.acc = (self.acc or 0) + elapsed
	if self.acc < 0.025 then return end
	local dt = min(self.acc, 0.25)
	self.acc = 0
	local lp, cum, lights = self.lp, self.lcum, self.lights
	local n = 0
	if lp and cum and #cum >= 2 then
		local k = 1 / max(S.sc:GetCanvasScale(), 0.01)
		local gap, total = 16 * k, cum[#cum]
		self.travel = ((self.travel or 0) + 28 * k * dt) % gap
		local s, seg = self.travel, 2
		local c = self.c or FARM_COLOR.B
		while s < total and n < FARM_LIGHTS do
			while seg < #cum and cum[seg] < s do seg = seg + 1 end
			local a0, a1 = cum[seg - 1], cum[seg]
			local t = a1 > a0 and Clamp((s - a0) / (a1 - a0), 0, 1) or 0
			local ax, ay = lp[2 * seg - 3], lp[2 * seg - 2]
			n = n + 1
			local l = lights[n]
			if not l then
				l = FlightTex(self, "OVERLAY", "Glow", 1, 1, 1, 1, "ADD")
				l:SetSize(8 * k, 8 * k)
				Mask(l)
				lights[n] = l
			end
			l:SetVertexColor(0.5 + c[1] * 0.5, 0.5 + c[2] * 0.5, 0.5 + c[3] * 0.5, 1)
			l:SetPoint("CENTER", S.canvas, "TOPLEFT", ax + (lp[2 * seg - 1] - ax) * t, ay + (lp[2 * seg] - ay) * t)
			l:SetAlpha(Clamp(min(s / gap, (total - s) / gap), 0, 1))
			l:Show()
			s = s + gap
		end
	end
	for i = n + 1, #lights do lights[i]:Hide() end
end

function E.UpdateZoneText()
	if not (S.zoneText and db.zoneText) then
		if S.zoneText then S.zoneText:SetShown(false); S.zoneHover:Hide() end
		return
	end
	local fs, mapID = S.zoneText, S.map:GetMapID()
	fs:Show()
	S.zoneHover:Show()
	if S.houseActive then
		fs:SetText(E.HouseTitle())
		fs:SetTextColor(1, 0.82, 0)
	elseif mapID and S.playerMap and mapID ~= S.playerMap then
		local info = C_Map.GetMapInfo(mapID)
		fs:SetText(info and info.name or "")
		fs:SetTextColor(1, 1, 1)
	else
		fs:SetText(GetMinimapZoneText() or "")
		local c = PVP_COLOR[(Pathway.ZonePVP())] or DEFAULT_COLOR
		fs:SetTextColor(c[1], c[2], c[3])
	end
end

function E.UpdateClock()
	if not (db.clock and S.clock) then return end
	local t = GameTime_GetTime and GameTime_GetTime(true) or date("%H:%M")
	if t ~= S.lastClock then
		S.lastClock = t
		S.clock.text:SetText(t)
		S.clock:SetSize(S.clock.text:GetStringWidth() + 6, db.coordSize + 6)
		E.FitZoneText()
	end
end

-- On a square map the zone name shares its edge with the clock: it stops short of it.
function E.FitZoneText()
	local zt = S.zoneText
	if not zt then return end
	if S.round then zt:SetWidth(max(40, E.Diameter() * 0.56)) return end
	local room = S.map:GetWidth() - 12
	if db.clock then room = room - (S.clock:GetWidth() or 40) - 8 end
	if db.zoneTextPos == "TOP" or db.zoneTextPos == "BOTTOM" then room = room - (db.clock and (S.clock:GetWidth() or 40) + 8 or 0) end
	zt:SetWidth(max(40, room))
end

function E.UpdateCoords(px, py)
	if db.playerCoords then
		local t = px and format(S.coordFmt, px * 100, py * 100) or ""
		if t ~= S.lastPT then
			S.lastPT = t
			S.playerText:SetText(t)
			S.coords:SetSize(max(8, S.playerText:GetStringWidth() + 6), db.coordSize + 6)
		end
	end
	if db.cursorCoords then
		local t = ""
		if S.hovered and S.sc:IsMouseOver() then
			local cx, cy = S.sc:GetNormalizedCursorPosition()
			if cx then t = format(S.coordFmt, cx * 100, cy * 100) end
		end
		if t ~= S.lastCT then S.lastCT = t; S.cursorText:SetText(t) end
	end
end

function E.UpdateHoverWidgets(over)
	local zoom = over and db.zoomButtons and not E.Busy()
	S.zoomIn:SetShown(zoom)
	S.zoomOut:SetShown(zoom)
	if S.farmHud then S.farmHud.stop:SetShown(over and S.farmLook or false) end
	S.grip:SetShown(over and not db.locked and not S.peeking)
end

-- Instance difficulty: the Blizzard badge moves onto GoodMap while the minimap is hidden.
function E.ApplyDifficulty()
	local f = MinimapCluster and MinimapCluster.InstanceDifficulty
	if not (f and S.overlay) then return end
	local want = db.difficulty and S.clusterHidden and S.mapShown and not S.houseActive
	if want then
		if not S.diffSaved then
			local saved = { parent = f:GetParent(), scale = f:GetScale(), points = {} }
			for i = 1, f:GetNumPoints() do saved.points[i] = { f:GetPoint(i) } end
			S.diffSaved = saved
			f:SetParent(S.overlay)
			f:SetScale(0.85)
		end
		local pos = db.difficultyPos
		local top, left = pos:find("TOP") ~= nil, pos:find("LEFT") ~= nil
		local M = MT(f)
		M.ClearAllPoints(f)
		if S.round then
			-- on the rim, like the Blizzard minimap's badge
			local r = E.Diameter() / 2 * 0.72
			M.SetPoint(f, "CENTER", S.overlay, "CENTER", left and -r or r, top and r or -r)
		else
			-- keep clear of the zone name and clock (one edge) and the coordinates (the other)
			local textTop = db.zoneTextPos:find("TOP") ~= nil
			local dy = 2
			if (db.zoneText or db.clock) and top == textTop then dy = db.zoneTextSize + 8
			elseif left and db.playerCoords and top ~= textTop then dy = db.coordSize + 10 end
			M.SetPoint(f, pos, S.overlay, pos, left and 2 or -2, top and -dy or dy)
		end
	elseif S.diffSaved then
		local saved = S.diffSaved
		S.diffSaved = nil
		f:SetParent(saved.parent)
		f:SetScale(saved.scale)
		f:ClearAllPoints()
		for _, p in ipairs(saved.points) do f:SetPoint(unpack(p)) end
	end
end

function E.Recenter()
	local map = S.map
	S.lastInteract, S.idle = 0, true
	if S.houseActive then E.Wake() return end
	if S.playerMap and map:GetMapID() ~= S.playerMap then map:SetMapID(S.playerMap) end
	local px, py = PlayerPos(S.playerMap)
	if px then
		local sc = S.sc
		local minX, maxX, minY, maxY = sc:CalculateScrollExtentsAtScale(sc:GetCanvasScale())
		sc:SetPanTarget(Clamp(px, minX, maxX), Clamp(py, minY, maxY))
	end
	E.Wake()
end

function E.ShareLocation()
	local mapID = S.playerMap
	local px, py = PlayerPos(mapID)
	if not (px and _G.UiMapPoint and C_Map.CanSetUserWaypointOnMap and C_Map.CanSetUserWaypointOnMap(mapID)) then
		Print(L["Your position can't be shared here."])
		return
	end
	local ok = pcall(C_Map.SetUserWaypoint, _G.UiMapPoint.CreateFromCoordinates(mapID, px, py))
	local link = ok and C_Map.GetUserWaypointHyperlink and C_Map.GetUserWaypointHyperlink()
	if not link then Print(L["Your position can't be shared here."]) return end
	local CFU = _G.ChatFrameUtil
	if CFU and CFU.InsertLink then
		if not CFU.InsertLink(link) and CFU.OpenChat then CFU.OpenChat(link) end
	elseif _G.ChatEdit_InsertLink then
		if not _G.ChatEdit_InsertLink(link) and _G.ChatFrame_OpenChat then _G.ChatFrame_OpenChat(link) end
	end
end

function E.OpenTracking()
	local tracking = MinimapCluster and MinimapCluster.Tracking and MinimapCluster.Tracking.Button
	if tracking and tracking.OpenMenu then tracking:OpenMenu() end
end

-- Off-map waypoint arrow -------------------------------------------------------
function E.RefreshWaypointTarget()
	local ox, oy = S.wpX, S.wpY
	S.wpX, S.wpY = nil, nil
	E.RefreshCorpse()
	if not ((db.waypointArrow or db.fitWaypoint) and S.map) or S.houseActive or S.mode == "PVP" then E.UpdateWaypointArrow() return end
	local mapID = S.map:GetMapID()
	if not mapID then return end
	local x, y
	if C_Navigation and C_Navigation.GetNextWaypointForMap then x, y = C_Navigation.GetNextWaypointForMap(mapID) end
	if not x and C_SuperTrack then
		if C_SuperTrack and C_SuperTrack.IsSuperTrackingUserWaypoint and C_SuperTrack.IsSuperTrackingUserWaypoint() then
			local p = C_Map.GetUserWaypointPositionForMap(mapID)
			if p then x, y = p.x, p.y end
		else
			local questID = C_SuperTrack and C_SuperTrack.GetSuperTrackedQuestID and C_SuperTrack.GetSuperTrackedQuestID()
			if questID and questID > 0 then
				local quests = C_QuestLog.GetQuestsOnMap and C_QuestLog.GetQuestsOnMap(mapID)
				if quests then
					for _, q in ipairs(quests) do
						if q.questID == questID then x, y = q.x, q.y break end
					end
				end
				if not x and C_TaskQuest and C_TaskQuest.GetQuestLocation then x, y = C_TaskQuest.GetQuestLocation(questID, mapID) end
			end
		end
	end
	if issecret(x) or issecret(y) then x, y = nil, nil end
	S.wpX, S.wpY = x, y
	if not (x and ox and abs(x - ox) < 0.002 and abs(y - oy) < 0.002) then S.etaD, S.etaV = nil, nil end   -- a new target
	E.UpdateWaypointArrow()
end

function E.UpdateWaypointArrow()
	local arrow = S.wpArrow
	if not arrow then return end
	local show = db.waypointArrow and S.mapShown and not S.houseActive and not S.flightOn
	E.EdgeArrow(arrow, show and S.wpX, S.wpY)
	E.UpdateCorpseArrow()
end

-- Points an edge arrow at tx, ty (normalized, on the shown map). Hidden while the target is in view.
function E.EdgeArrow(arrow, tx, ty)
	if not tx then
		if arrow:IsShown() then arrow:Hide() end
		return
	end
	local sc = S.sc
	local scale = sc:GetCanvasScale()
	local dx = (tx - sc:GetCurrentScrollX()) * S.canvas:GetWidth() * scale
	local dy = (sc:GetCurrentScrollY() - ty) * S.canvas:GetHeight() * scale
	local hw, hh = sc:GetWidth() * 0.5, sc:GetHeight() * 0.5
	local margin = 13
	local k
	if S.round then
		local r, len = min(hw, hh), sqrt(dx * dx + dy * dy)
		if len <= r - 2 then                           -- on screen: the map pin shows it
			if arrow:IsShown() then arrow:Hide() end
			return
		end
		k = (r - margin) / max(len, 0.001)
	else
		if abs(dx) <= hw - 2 and abs(dy) <= hh - 2 then
			if arrow:IsShown() then arrow:Hide() end
			return
		end
		k = min((hw - margin) / max(abs(dx), 0.001), (hh - margin) / max(abs(dy), 0.001))
	end
	local ax, ay = dx * k, dy * k
	arrow:SetPoint("CENTER", S.overlay, "CENTER", ax, ay)
	arrow.tex:SetRotation(atan2(dy, dx) - PI / 2)
	local len = (ax * ax + ay * ay) ^ 0.5
	if len > 0 then
		arrow.text:ClearAllPoints()
		arrow.text:SetPoint("CENTER", arrow, "CENTER", -ax / len * 22, -ay / len * (arrow.lines == 2 and 22 or 16))
	end
	arrow.text:SetShown(arrow ~= S.wpArrow or db.waypointDistance)
	if not arrow:IsShown() then arrow:Show() end
end

-- Distance (and time to arrive, from how fast you've been closing in).
function E.UpdateWaypointDistance()
	E.UpdateCorpseDistance()
	local arrow = S.wpArrow
	if not (arrow and arrow:IsShown() and db.waypointDistance) then S.etaD, S.etaV = nil, nil return end
	local d = C_Navigation and C_Navigation.GetDistance and C_Navigation.GetDistance() or 0
	if issecret(d) then d = 0 end
	local t, lines = "", 1
	if d and d > 0 then
		t = E.Yards(d)
		if db.waypointETA then
			local now = GetTime()
			if S.etaD and now > S.etaT then
				local v = (S.etaD - d) / (now - S.etaT)              -- yards a second toward the target
				S.etaV = S.etaV and (S.etaV * 0.6 + v * 0.4) or v
			end
			S.etaD, S.etaT = d, now
			local v = S.etaV
			if v and v > 1 and d / v < 5940 then t, lines = t .. "\n" .. E.Clock(d / v), 2 end
		end
	end
	if t ~= S.lastDist then
		S.lastDist = t
		arrow.text:SetText(t)
		if lines ~= arrow.lines then arrow.lines = lines; E.UpdateWaypointArrow() end
	end
end

-- Corpse arrow: after you die, the edge of the map points to your body.
function E.RefreshCorpse()
	S.cpX, S.cpY = nil, nil
	local DI = _G.C_DeathInfo
	if db.corpseArrow and S.map and DI and DI.GetCorpseMapPosition and UnitIsDeadOrGhost("player") and not S.houseActive then
		local mapID = S.map:GetMapID()
		local ok, p = pcall(DI.GetCorpseMapPosition, mapID)
		if ok and p and p.x and not issecret(p.x) and (p.x ~= 0 or p.y ~= 0) then S.cpX, S.cpY = p.x, p.y end
	end
end

function E.UpdateCorpseArrow()
	local arrow = S.corpseArrow
	if arrow then E.EdgeArrow(arrow, S.mapShown and S.cpX, S.cpY) end
end

function E.UpdateCorpseDistance()
	local arrow = S.corpseArrow
	if not (arrow and arrow:IsShown()) then return end
	local r = MapRect(S.map:GetMapID())
	local wx, wy = UnitPosition("player")
	local t = ""
	if r and wx and not issecret(wx) then
		local cx, cy = r[1] + S.cpY * r[3], r[2] + S.cpX * r[4]
		t = E.Yards(sqrt((cx - wx) ^ 2 + (cy - wy) ^ 2))
	end
	if t ~= S.lastCorpse then S.lastCorpse = t; arrow.text:SetText(t) end
end

--------------------------------------------------------------------------------
-- Navigation: follow, return to zone, zoom (extra / remembered / context)
--------------------------------------------------------------------------------
function E.SetupNavigation()
	local map, sc = S.map, S.sc

	hooksecurefunc(sc, "CreateZoomLevels", function(self)
		local n, levels = db.extraZoom, self.zoomLevels
		if n > 0 and levels and #levels > 0 then
			local last = levels[#levels]
			local s = last.scale
			for _ = 1, n do
				s = s * 1.25
				levels[#levels + 1] = { scale = s, layerIndex = last.layerIndex }
			end
		end
		if E.TerrainZoomLevels then E.TerrainZoomLevels(levels) end
	end)

	hooksecurefunc(sc, "OnCanvasSizeChanged", E.RestoreZoom)

	-- the detail view takes the wheel first, so the zone map under it stays as it was
	local wheel = sc:GetScript("OnMouseWheel")
	if wheel then
		sc:SetScript("OnMouseWheel", function(self, delta, ...)
			if E.DetailWheel and E.DetailWheel(delta) then S.lastInteract = GetTime() return end
			return wheel(self, delta, ...)
		end)
	end
	sc:HookScript("OnMouseWheel", function(self, delta)
		S.lastInteract = GetTime()
		-- a smooth zoom-out would also slide the map to its middle: stay where you were
		if delta and delta < 0 and db.smoothZoom then E.KeepPan() end
		E.SaveZoom()
	end)

	-- The Blizzard minimap zoom keys zoom GoodMap too.
	local function zoomKey(delta)
		return function()
			if db.zoomKeys and S.mapShown and not (db.radarMouse and Minimap:IsMouseOver()) then E.Zoom(delta) end
		end
	end
	if Minimap_ZoomIn then hooksecurefunc("Minimap_ZoomIn", zoomKey(1)) end
	if Minimap_ZoomOut then hooksecurefunc("Minimap_ZoomOut", zoomKey(-1)) end

	-- A tiny data provider: gives us map/zoom/pan callbacks without polling.
	local provider = CreateFromMixins(MapCanvasDataProviderMixin)
	provider.RefreshAllData, provider.RemoveAllData = noop, noop
	function provider:OnMapChanged() E.OnMapChanged(); if E.Terrain then E.Terrain.key = nil; E.TerrainUpdate() end end
	function provider:OnCanvasScaleChanged() E.OnCanvasScaleChanged() end
	function provider:OnCanvasSizeChanged() E.OnCanvasScaleChanged() end
	function provider:OnCanvasPanChanged()
		if E.TerrainUpdate then E.TerrainUpdate() end
		if S.wpX or S.cpX then E.UpdateWaypointArrow() end
		if S.clipPins then E.ClipCanvasPins() end
		-- dragging the map moves the radar with you: keep it inside the window
		if S.radarVisible then
			local px, py = PlayerPos(S.playerMap)
			if px then E.RadarFit(px, py) end
		end
	end
	map:AddDataProvider(provider)

	-- The per-frame driver (asleep unless needed)
	local driver = CreateFrame("Frame")
	driver:Hide()
	driver:SetScript("OnUpdate", Pathway.Perf.W("Minimap", E.FastTick))
	S.driver = driver
	S.wakeUntil, S.lastInteract, S.textTimer = 0, 0, 0
end

function E.SaveZoom()
	local sc = S.sc
	if S.ctxBase then S.ctxManual = true return end   -- context zoom (flying, resting) is temporary
	if S.peeking or S.mode == "PVP" then return end   -- battleground mode zooms for itself
	if db.rememberZoom and sc.zoomLevels then
		db.zoomIndex = sc:GetZoomLevelIndexForScale(sc.targetScale or sc:GetCanvasScale())
	end
end

function E.Zoom(delta)
	if S.houseActive then E.HouseZoom(delta) return end
	local sc = S.sc
	if not sc.zoomLevels then return end
	local x, y = sc:GetCurrentScrollX(), sc:GetCurrentScrollY()
	if delta > 0 then sc:ZoomIn() else sc:ZoomOut(); E.KeepPan(x, y) end
	S.lastInteract = GetTime()
	E.SaveZoom()
end

-- Point the pan where it was (or at x, y), within what the target zoom allows.
function E.KeepPan(x, y)
	local sc = S.sc
	x, y = x or sc:GetCurrentScrollX(), y or sc:GetCurrentScrollY()
	if not (x and y) then return end
	local minX, maxX, minY, maxY = sc:CalculateScrollExtentsAtScale(sc.targetScale or sc:GetCanvasScale())
	sc:SetPanTarget(Clamp(x, minX, maxX), Clamp(y, minY, maxY))
end

function E.ApplySmoothZoom()
	if S.map.SetShouldZoomInstantly then S.map:SetShouldZoomInstantly(not db.smoothZoom) end
end

function E.RestoreZoom(sc)
	if not (sc.zoomLevels and sc.mapID and #sc.zoomLevels > 0) then return end
	if S.mode == "PVP" then                            -- the whole battleground
		sc:InstantPanAndZoom(sc.zoomLevels[1].scale, 0.5, 0.5, true)
		return
	end
	local scale
	if db.rememberZoom then
		-- each zone opens at the zoom you like there; a zone you haven't zoomed in yet
		-- opens at a comfortable default (a few hundred yards across), never right on top of you
		scale = E.UsualScale(sc, E.ZoneSpan(sc.mapID))
	end
	S.appliedScale = scale
	local px, py
	if db.follow and sc.mapID == E.PlayerMapID() then px, py = PlayerPos(sc.mapID) end
	if scale or px then
		sc:InstantPanAndZoom(scale or sc:GetCanvasScale(), px or 0.5, py or 0.5, true)
	end
end

function E.ApplyZoomLevels()
	local sc = S.sc
	if sc.mapID then sc:OnCanvasSizeChanged() end
end

-- Your usual zoom: how far out you usually look, in yards across the view, so it
-- feels the same in a big zone as in a small city. GoodMap learns it as you play
-- (the longer you stay at a zoom, the more it counts) and goes back to it when
-- you move onto another map. Peeking, flying, the city zoom-in and zooming out
-- to fit a waypoint are temporary, so they don't count.
function E.ViewSpan(mapID, scale)
	local r = mapID and MapRect(mapID)
	local cw = S.canvas:GetWidth()
	if not (r and cw and cw > 0 and scale and scale > 0) then return end
	local sc = S.sc
	return min(sc:GetWidth(), sc:GetHeight()) / (cw * scale) * abs(r[4])
end

-- Zoom, zone by zone: what you set in a zone is remembered for that zone (the
-- average of how you keep it), and zones you haven't touched use the default.
local DEFAULT_SPAN = 640
local function ZoneSpans()
	local pdb = Pathway.db
	if not pdb then return {} end
	pdb.mapZoom = pdb.mapZoom or {}
	return pdb.mapZoom
end
function E.ZoneSpan(mapID)
	return (mapID and ZoneSpans()[mapID]) or DEFAULT_SPAN
end
function E.ForgetZoneZoom(mapID)
	if mapID then ZoneSpans()[mapID] = nil else wipe(ZoneSpans()) end
end

-- The zoom step on this map nearest a view this many yards across.
function E.UsualScale(sc, span)
	local levels = sc.zoomLevels
	span = span or DEFAULT_SPAN
	if not (span and span > 0 and levels and levels[1]) then return end
	local best, bestD
	for _, z in ipairs(levels) do
		local v = E.ViewSpan(sc.mapID, z.scale)
		if v and v > 0 then
			local d = abs(log(v / span))
			if not bestD or d < bestD then best, bestD = z.scale, d end
		end
	end
	return best
end

function E.LearnZoom(dt)
	local sc = S.sc
	local usual = db.rememberZoom and sc.zoomLevels and S.mode == "NORMAL" and not (S.peeking or S.houseActive or S.flightOn
		or S.ctxBase or (S.fitK or 0) > 0) and S.map:GetMapID() == S.playerMap
	if not usual then S.zoomAt, S.zoomSince = nil, nil return end
	local scale = sc.targetScale or sc:GetCanvasScale()
	local now = GetTime()
	if S.zoomAt ~= scale then S.zoomAt, S.zoomSince = scale, now return end   -- let a new zoom settle first
	if now - S.zoomSince < 3 then return end
	-- only your own zooming teaches it: the zoom Pathway opened the zone at doesn't count
	local spans = ZoneSpans()
	local mapID = sc.mapID
	if not spans[mapID] and S.appliedScale and abs(scale - S.appliedScale) < 1e-6 then return end
	local span = E.ViewSpan(mapID, scale)
	if not (span and span > 0) then return end
	local was = spans[mapID]
	if not (was and was > 0) then spans[mapID] = span return end
	local k = dt / (90 + dt)                      -- the last minute and a half or so count most
	spans[mapID] = exp(log(was) + (log(span) - log(was)) * k)
end

-- Context zoom: out while flying, gliding or on a taxi (back 2 s after landing),
-- in while resting in a city or inn. Manual zooming wins until the context ends.
function E.UpdateContextZoom(now)
	local sc = S.sc
	if not sc.zoomLevels or S.peeking or S.mode == "PVP" or S.flightMap or S.map:GetMapID() ~= S.playerMap then return end
	-- a new zone's map starts at its own default zoom: on a taxi, jump straight to the
	-- zoom you had, instead of zooming in and back out at every border
	local mapID = S.map:GetMapID()
	if UnitOnTaxi("player") and S.taxiMap ~= mapID then
		local had = S.taxiMap and S.taxiStep
		S.taxiMap = mapID
		if had and sc.zoomLevels[had] then
			local px, py = PlayerPos(mapID)
			sc:InstantPanAndZoom(sc.zoomLevels[had].scale, px or 0.5, py or 0.5, true)
		end
	elseif not UnitOnTaxi("player") then
		S.taxiMap, S.taxiStep = nil, nil
	end
	local offset = 0
	if db.flightZoom > 0 then
		local gliding = C_PlayerInfo and C_PlayerInfo.GetGlidingInfo and C_PlayerInfo.GetGlidingInfo()
		if IsFlying() or UnitOnTaxi("player") or gliding then S.lastFlying = now end
		if S.lastFlying and (now - S.lastFlying) < 2 then offset = -db.flightZoom end
	end
	-- by an inn, a flight master or mailboxes (Pathway knows where they are): two steps
	-- closer, so the town's services are easy to tell apart; out again as you leave
	if offset == 0 then
		local PW = _G.Pathway
		if PW and PW.db and PW.db.settings.serviceZoom ~= false and PW.NearServices and PW:NearServices() then offset = 2 end
	end
	if offset == 0 and db.cityZoom > 0 and IsResting and IsResting() then offset = db.cityZoom end
	-- indoors with no map of its own (an inn, a house, a tunnel): two steps closer
	if offset == 0 and db.indoorZoom ~= false and IsIndoors and IsIndoors() then
		local info = C_Map.GetMapInfo(mapID)
		if info and info.mapType == (Enum.UIMapType and Enum.UIMapType.Zone or 3) then offset = 2 end
	end
	local current = sc:GetZoomLevelIndexForScale(sc.targetScale or sc:GetCanvasScale())
	if offset == 0 then offset = -E.FitSteps(S.ctxBase or current) end
	if offset ~= 0 then
		if not S.ctxBase then S.ctxBase, S.ctxManual = current, false end
		if S.ctxManual or not S.idle then return end
		local want = Clamp(S.ctxBase + offset, 1, #sc.zoomLevels)
		if UnitOnTaxi("player") then S.taxiStep = want end
		if current ~= want and sc.zoomLevels[want] then sc:SetZoomTarget(sc.zoomLevels[want].scale) end
	elseif S.ctxBase then
		local base, manual = S.ctxBase, S.ctxManual
		S.ctxBase, S.ctxManual = nil, nil
		if not manual and current ~= base and sc.zoomLevels[base] then sc:SetZoomTarget(sc.zoomLevels[base].scale) end
	end
end

-- Fit to waypoint: how many zoom steps out (up to 3) put your tracked target
-- in view around you. 0 when it's in view already, or too far to help.
-- Stepping back in needs a little room to spare, so the zoom doesn't flicker.
function E.FitSteps(base)
	local was = S.fitK or 0
	S.fitK = 0
	if not (db.fitWaypoint and S.wpX and S.mode == "NORMAL" and base) then return 0 end
	local px, py = PlayerPos(S.playerMap)
	local levels = S.sc.zoomLevels
	if not (px and levels) then return 0 end
	local hw, hh = S.sc:GetWidth() * 0.5 - 16, S.sc:GetHeight() * 0.5 - 16
	local dx, dy = (S.wpX - px) * S.canvas:GetWidth(), (S.wpY - py) * S.canvas:GetHeight()
	for k = 0, 3 do
		local z = levels[base - k]
		if not z then break end
		local s = z.scale * (k < was and 1.18 or 1)
		local x, y = dx * s, dy * s
		local fits
		if S.round then fits = x * x + y * y <= min(hw, hh) ^ 2 else fits = abs(x) <= hw and abs(y) <= hh end
		if fits then
			if k == 0 then return 0 end
			S.fitK = k
			return k
		end
	end
	return 0
end

function E.Wake()
	S.wakeUntil = GetTime() + 0.6
	if S.mapShown and S.driver then S.driver:Show() end
end

function E.Follow(px, py)
	local sc = S.sc
	local minX, maxX, minY, maxY = sc:CalculateScrollExtentsAtScale(sc:GetCanvasScale())
	local dz = db.deadzone
	if dz > 0 then
		local cx, cy = sc:GetCurrentScrollX(), sc:GetCurrentScrollY()
		-- minX/minY are the half view sizes in normalized units
		if cx and cy and abs(px - cx) < minX * dz and abs(py - cy) < minY * dz then return end
	end
	local tx, ty = Clamp(px, minX, maxX), Clamp(py, minY, maxY)
	if tx ~= sc.targetScrollX or ty ~= sc.targetScrollY then sc:SetPanTarget(tx, ty) end
end

function E.FastTick(driver, elapsed)
	local now = GetTime()
	if S.houseActive then
		E.HouseTick(now)
	else
		local mapID = S.map:GetMapID()
		local px, py
		if mapID and mapID == S.playerMap then
			px, py = PlayerPos(mapID)
		elseif mapID and S.flightOn then
			local ax, ay = PlayerPos(mapID)                      -- you, on the route's map
			if ax then E.RadarAnchor(ax, ay) end
		end
		if px then
			if db.follow and S.idle and S.mode ~= "PVP" and not S.flightMap then E.Follow(px, py) end
			if S.radarVisible or S.arrowActive or S.flightOn then E.RadarAnchor(px, py) end
			if S.radarVisible then E.RadarFit(px, py) end
		end
		S.textTimer = S.textTimer - elapsed
		if S.textTimer <= 0 then
			S.textTimer = 0.05
			E.UpdateCoords(px, py)
		end
	end
	if now > S.wakeUntil and not (S.hovered and db.cursorCoords and not S.houseActive) then driver:Hide() end
end

function E.SlowTick()
	local map = S.map
	if not (map:IsShown() and S.mapShown) then return end
	local now = GetTime()
	S.tick = (S.tick or 0) + 1
	if S.tick % 5 == 0 or not S.playerMap then
		S.playerMap = E.PlayerMapID()
		E.UpdateDetail()
		E.UpdateClock()
		E.UpdateWaypointDistance()
		E.UpdateStatus()
		E.UpdateFlight()
		E.HouseCheck()
		E.LearnZoom(1)
	end
	if S.tick % 10 == 0 then E.RefreshWaypointTarget() end
	if S.flightOn then E.FlightTick() end
	if S.farm then E.FarmTick() end

	local over = (map:IsMouseOver() or (S.bar:IsShown() and S.bar:IsMouseOver())) and true or false
	if over then S.lastInteract = now end
	if over ~= S.hovered then S.hovered = over; E.OnHover(over) end
	if db.mouse == "ALT" then E.UpdateAltMouse() end

	local idle = not over and not S.dragging and (now - S.lastInteract) >= db.resumeDelay
	if idle and not S.idle then E.Wake() end
	S.idle = idle
	if idle and db.autoReturn and S.playerMap and map:GetMapID() ~= S.playerMap and not S.houseActive and not S.flightMap then
		map:SetMapID(S.playerMap)
	end

	local wx, wy = UnitPosition("player")
	if wx ~= S.wx or wy ~= S.wy then
		S.wx, S.wy = wx, wy
		if wx then E.Wake() end
	end
	if S.houseActive then
		S.posOK = false
		if over then E.HouseHover() elseif S.houseTip then S.houseTip = nil; HideTooltip() end
	else
		S.posOK = S.playerMap and PlayerPos(S.playerMap) ~= nil or false
		-- in a dungeon that doesn't share your position: its whole floor, with the game's own marker for you
		if not S.posOK and S.playerMap and map:GetMapID() == S.playerMap and S.fitFor ~= S.playerMap and E.InstanceMap() then
			local sc = S.sc
			if sc.zoomLevels and sc.zoomLevels[1] then
				S.fitFor = S.playerMap
				sc:InstantPanAndZoom(sc.zoomLevels[1].scale, 0.5, 0.5, true)
			end
		elseif S.posOK then
			S.fitFor = nil
		end
		E.UpdateContextZoom(now)
		if S.round then E.MaskPins() end
	end
	E.UpdateRadarState()
	E.RadarAdapt()
	E.UpdateHeading()
end

function E.OnHover(over)
	E.ApplyAlpha()
	E.ApplyCalm()
	E.UpdateHoverWidgets(over)
	if over then E.Wake() end
end

-- Calmer in combat: the bar and the text step back while you fight (hovering brings them back).
function E.Calm() return db.combatCalm and S.inCombat and not S.hovered end

function E.ApplyCalm()
	if S.textLayer then FadeTo(S.textLayer, E.Calm() and 0 or 1) end
	local bar = S.bar
	if bar and bar:IsShown() then
		FadeTo(bar, (E.Calm() or (db.barMouseover and not S.hovered)) and 0 or 1)
	end
	local eb = S.eventButton
	if eb and eb:IsShown() then FadeTo(eb, E.Calm() and 0 or 1) end
end

function E.Activate()
	if S.mapShown then return end
	local map = S.map
	S.mapShown = true
	E.ApplyTab()
	if S.sizeDirty then S.sizeDirty = nil; map:OnFrameSizeChanged() end
	S.playerMap = E.PlayerMapID()
	S.hovered, S.idle, S.lastInteract = false, true, 0
	map:SetAlpha(0)
	FadeTo(map, E.TargetAlpha())
	E.ApplyAlpha()
	E.UpdateHoverWidgets(false)
	E.ApplyMouse()
	E.UpdateCluster()
	E.HouseCheck()
	E.UpdateHouseView()
	if not S.ticker then S.ticker = C_Timer.NewTicker(0.2, Pathway.Perf.W("Minimap", E.SlowTick)) end
	E.SlowTick()
	if db.follow and not S.houseActive and S.mode ~= "PVP" then
		local px, py = PlayerPos(map:GetMapID() == S.playerMap and S.playerMap)
		if px then S.sc:InstantPanAndZoom(S.sc:GetCanvasScale(), px, py, true) end
	end
	E.UpdateZoneText()
	E.UpdateClock()
	E.RefreshWaypointTarget()
	E.RefreshBar()
	E.UpdateEventButton()
	E.PlaceNotes()
	Later("hbd", E.HBDRefresh, 0.1)
	E.Wake()
end

function E.Deactivate()
	if not S.mapShown then return end
	E.EndPeek()
	S.mapShown = false
	if S.ticker then S.ticker:Cancel(); S.ticker = nil end
	S.driver:Hide()
	S.hovered = false
	S.ctxBase, S.ctxManual = nil, nil
	E.UpdateHouseView()
	E.UpdateRadarState()
	E.UpdateHeading()
	E.UpdateCluster()
	E.RefreshBar()
	E.UpdateWaypointArrow()
	E.UpdateEventButton()
	E.HBDRefresh()
	-- the bell goes back beside Blizzard's minimap
	if Pathway and Pathway.PlaceNotesButton then Pathway:PlaceNotesButton() end
end

function E.OnMapChanged()
	S.ax = nil
	if S.arrowActive then Later("unitPins", function() S.uPlayer = nil; E.ApplyUnitPins() end, 0.05) end
	E.UpdateZoneText()
	if S.flightOn then Later("route", E.DrawRoute, 0.05) end
	if S.farm or S.farmPreview then Later("farmRoute", function() E.DrawFarmRoute(); E.FarmLookUpdate() end, 0.05) end
	if S.radarEmbedded then Later("radarState", E.UpdateRadarState) end
	Later("waypoint", E.RefreshWaypointTarget, 0.05)
	Later("groupPins", E.RefreshGroupPins, 0.05)
	Later("hbd", E.HBDRefresh, 0.05)
	E.Wake()
end

function E.OnCanvasScaleChanged()
	E.DetailZoomCheck()
	if E.TerrainUpdate then E.TerrainUpdate() end
	if S.radarVisible then
		E.UpdateRadarSize()
		local px, py = PlayerPos(S.playerMap)
		if px then E.RadarFit(px, py) end
	end
	if S.wpX or S.cpX then E.UpdateWaypointArrow() end
	E.PlaceCanvasPins()
	S.ax = nil
	if S.flightOn then E.DrawRoute() end
	if S.farmFrame and S.farmFrame:IsShown() then E.DrawFarmRoute() end
end

--------------------------------------------------------------------------------
-- Peek: hold the peek key (Num Pad 0 by default) to enlarge GoodMap in place.
--------------------------------------------------------------------------------
function GoodMap_Peek(keystate)
	if keystate == "up" then
		if not S.peekHold then E.EndPeek(true) end     -- the first-peek window keeps it open
	else
		E.StartPeek()
	end
end

function E.StartPeek()
	if S.peeking or not (S.ready and S.mapShown) or S.editMode then return end
	local map = S.map
	local s = map:GetScale()
	local l, b, w, h = map:GetRect()
	if not l then return end
	S.peeking = true
	if not S.peekBack then
		-- Remember exactly where the map is, so letting go puts it back there.
		-- (Still set if the last peek is gliding back: then the map returns to the same place.)
		local back = { scale = s }
		for i = 1, map:GetNumPoints() do back[i] = { map:GetPoint(i) } end
		S.peekBack = back
		-- grow away from the nearest screen corner so the map stays on screen
		local cx, cy = (l + w / 2) * s, (b + h / 2) * s
		local right = cx > UIParent:GetWidth() / 2
		local top = cy > UIParent:GetHeight() / 2
		S.peekCorner = (top and "TOP" or "BOTTOM") .. (right and "RIGHT" or "LEFT")
		S.peekFX = (right and (l + w) or l) * s
		S.peekFY = (top and (b + h) or b) * s
	end
	E.ApplyPeekSize()
	E.ApplyPeekZoom()
	E.ApplyAlpha()
	E.UpdateHoverWidgets(S.hovered)
	E.LayoutBar()
	E.Wake()
	-- The first peek stays open and asks how far out to zoom.
	if not ROOT.peekSetupDone then E.ShowPeekSetup() end
end

-- How big the peeking map is (follows the setting live while you peek).
function E.ApplyPeekSize()
	if not (S.peeking and S.peekBack) then return end
	local ns = S.peekBack.scale * db.peekScale
	if db.smoothZoom then Tween("peek", S.map:GetScale(), ns, 0.14, E.PeekPlace) else StopTween("peek"); E.PeekPlace(ns) end
end

-- How far out the peeking map zooms: peekZoom steps out from where you were, 4 = the whole zone.
function E.ApplyPeekZoom()
	if not S.peeking then return end
	local n = db.peekZoom
	if S.houseActive then
		S.peekHouseZoom = S.peekHouseZoom or S.houseK
		E.HouseSetZoom(S.peekHouseZoom * (n >= 4 and 0.5 or 0.8 ^ n), true)
		return
	end
	local sc = S.sc
	local levels = sc.zoomLevels
	if not (levels and levels[1]) then return end
	S.peekScaleWas = S.peekScaleWas or sc.targetScale or sc:GetCanvasScale()
	local target = S.peekScaleWas
	if n >= 4 then
		target = levels[1].scale
	elseif n > 0 then
		local i = sc:GetZoomLevelIndexForScale(S.peekScaleWas)
		target = levels[max(1, i - n)].scale
	end
	if db.smoothZoom then sc:SetZoomTarget(target)
	else sc:InstantPanAndZoom(target, sc:GetCurrentScrollX() or 0.5, sc:GetCurrentScrollY() or 0.5, true) end
end

function E.PeekZoomName(n)
	n = floor((n or 0) + 0.5)
	if n <= 0 then return L["Don't zoom out"] end
	if n >= 4 then return L["The whole zone"] end
	return n == 1 and L["1 step out"] or format(L["%d steps out"], n)
end

-- The first-peek window: GoodMap stays peeking while it's open, so you see what you pick.
function E.ShowPeekSetup()
	local f = S.peekSetup or E.BuildPeekSetup()
	if not f then ROOT.peekSetupDone = true return end
	S.peekHold = true
	f.zoom:SetValue(db.peekZoom)
	f.size:SetValue(db.peekScale)
	f:Show()
end

function E.FinishPeekSetup()
	ROOT.peekSetupDone = true
	if not S.peekHold then return end
	S.peekHold = nil
	E.RefreshSettings()
	E.EndPeek(true)
end

local function SetupSlider(f, key, label, fmt, y, apply)
	local r = RANGE[key]
	local title = f:CreateFontString(nil, "OVERLAY", "GameFontNormal")
	title:SetPoint("TOPLEFT", f, "TOPLEFT", 22, y)
	title:SetText(label)
	local ok, sl = pcall(CreateFrame, "Frame", nil, f, "MinimalSliderWithSteppersTemplate")
	if not (ok and sl and sl.Init) then return end
	sl:SetPoint("TOPLEFT", title, "BOTTOMLEFT", -4, -4)
	sl:SetWidth(f:GetWidth() - 110)
	local steps = floor((r[2] - r[1]) / r[3] + 0.5)
	sl:Init(db[key], r[1], r[2], steps, { [MinimalSliderWithSteppersMixin.Label.Right] = fmt })
	sl:RegisterCallback(MinimalSliderWithSteppersMixin.Event.OnValueChanged, function(_, value)
		value = Clamp(value, r[1], r[2])
		if key == "peekZoom" then value = floor(value + 0.5) end
		if db[key] ~= value then
			db[key] = value
			apply()
		end
	end, f)
	return sl
end

function E.BuildPeekSetup()
	local f = CreateFrame("Frame", "GoodMapPeekSetup", UIParent, "BackdropTemplate")
	f:SetSize(380, 236)
	f:SetPoint("CENTER", UIParent, "CENTER", 0, 120)
	f:SetFrameStrata("DIALOG")
	f:SetClampedToScreen(true)
	f:EnableMouse(true)
	f:SetMovable(true)
	f:RegisterForDrag("LeftButton")
	f:SetScript("OnDragStart", f.StartMoving)
	f:SetScript("OnDragStop", f.StopMovingOrSizing)
	if f.SetBackdrop and _G.BACKDROP_DIALOG_32_32 then f:SetBackdrop(_G.BACKDROP_DIALOG_32_32) end
	f.title = f:CreateFontString(nil, "OVERLAY", "GameFontNormalLarge")
	f.title:SetPoint("TOP", f, "TOP", 0, -22)
	f.title:SetText(format(L["%s: peek"], TITLE))
	f.text = f:CreateFontString(nil, "OVERLAY", "GameFontHighlight")
	f.text:SetPoint("TOP", f.title, "BOTTOM", 0, -8)
	f.text:SetWidth(330)
	f.text:SetText(L["While you hold the peek key, GoodMap grows and zooms out. It stays like this while you choose."])
	f.zoom = SetupSlider(f, "peekZoom", L["Zoom out while peeking"], E.PeekZoomName, -92, function() E.ApplyPeekZoom(); E.RefreshSettings() end)
	f.size = SetupSlider(f, "peekScale", L["Peek size"], Num("%.1fx"), -142, function() E.ApplyPeekSize(); E.RefreshSettings() end)
	if not (f.zoom and f.size) then f:Hide() return end    -- no slider template: skip the window
	f.note = f:CreateFontString(nil, "OVERLAY", "GameFontDisableSmall")
	f.note:SetPoint("BOTTOMLEFT", f, "BOTTOMLEFT", 22, 24)
	f.note:SetWidth(220)
	f.note:SetJustifyH("LEFT")
	f.note:SetText(L["You can change these later in GoodMap's settings, under Navigation."])
	local okay = CreateFrame("Button", nil, f, "UIPanelButtonTemplate")
	okay:SetSize(96, 24)
	okay:SetPoint("BOTTOMRIGHT", f, "BOTTOMRIGHT", -22, 20)
	okay:SetText(_G.OKAY or L["OK"])
	okay:SetScript("OnClick", function() f:Hide() end)
	f:Hide()
	f:SetScript("OnHide", E.FinishPeekSetup)     -- OK, Esc, or the peek ending some other way
	if _G.UISpecialFrames then table.insert(_G.UISpecialFrames, "GoodMapPeekSetup") end   -- Esc closes it too
	S.peekSetup = f
	return f
end

-- Scale the peeking map around its fixed corner.
function E.PeekPlace(s)
	local map = S.map
	map:SetScale(s)
	map:ClearAllPoints()
	map:SetPoint(S.peekCorner, UIParent, "BOTTOMLEFT", S.peekFX / s, S.peekFY / s)
end

-- Back to exactly where and how big the map was before the peek.
local function PeekReturn()
	local map, back = S.map, S.peekBack
	S.peekBack = nil
	if not (back and back[1]) then
		map:SetScale(db.scale)
		E.ApplyPosition()
		return
	end
	map:SetScale(back.scale)
	map:ClearAllPoints()
	for _, p in ipairs(back) do map:SetPoint(unpack(p)) end
end

-- glide: ease back (letting go of the key). Without it the map is back at once,
-- for callers that move or rescale the map right after.
function E.EndPeek(glide)
	if S.peekHold and not glide and S.peekSetup and S.peekSetup:IsShown() then
		S.peekHold = nil
		S.peekSetup:Hide()                      -- saves what you picked
	end
	if not S.peeking then
		if not glide and S.peekBack then StopTween("peek"); PeekReturn() end   -- cut a glide short
		return
	end
	S.peeking = false
	local map = S.map
	if glide and db.smoothZoom and S.peekBack then
		Tween("peek", map:GetScale(), S.peekBack.scale, 0.12, E.PeekPlace, function() if not S.peeking then PeekReturn() end end)
	else
		StopTween("peek")
		PeekReturn()
	end
	if S.peekHouseZoom then
		E.HouseSetZoom(S.peekHouseZoom, true)
		S.peekHouseZoom = nil
	end
	if S.peekScaleWas then
		local sc = S.sc
		local px, py = PlayerPos(S.map:GetMapID() == S.playerMap and S.playerMap)
		if db.smoothZoom then
			sc:SetZoomTarget(S.peekScaleWas)
			E.KeepPan(px, py)
		else
			sc:InstantPanAndZoom(S.peekScaleWas, px or sc:GetCurrentScrollX() or 0.5, py or sc:GetCurrentScrollY() or 0.5, true)
			if px then E.Follow(px, py) end
		end
		S.peekScaleWas = nil
	end
	E.ApplyAlpha()
	E.UpdateHoverWidgets(S.hovered)
	E.LayoutBar()
	E.Wake()
end

-- Give the peek binding a key once: Num Pad 0, if nothing else uses it.
function E.SetupPeekKey(force)
	if InCombatLockdown() then S.peekKeyAfterCombat = force and "force" or true return end
	if not (SetBinding and GetBindingAction) then return end
	if not force then
		-- once per character: key bindings can be per character
		local done = type(ROOT.peekDone) == "table" and ROOT.peekDone or {}
		ROOT.peekDone = done
		if done[E.CharKey()] then return end
		done[E.CharKey()] = true
		if GetBindingKey and GetBindingKey("GOODMAP_PEEK") then return end
		local action = GetBindingAction("NUMPAD0")
		if action and action ~= "" then
			Print(format(L["%s is already in use, so the peek key wasn't set. You can pick one in GoodMap's settings."], E.PeekKeyName()))
			return
		end
	end
	if SetBinding("NUMPAD0", "GOODMAP_PEEK") then
		if SaveBindings and GetCurrentBindingSet then SaveBindings(GetCurrentBindingSet()) end
		if force then Print(format(L["Peek is now on %s. Hold it to enlarge GoodMap."], E.PeekKeyName())) end
	end
end

-- The game's own name for the key and for the key binding menu, in your language.
function E.PeekKeyName()
	local text = GetBindingText and GetBindingText("NUMPAD0")
	return (type(text) == "string" and text ~= "") and text or "Num Pad 0"
end

function E.KeybindingsPath()
	return (SETTINGS or "Options") .. " > " .. (SETTINGS_KEYBINDINGS_LABEL or "Keybindings") .. " > " .. (ADDONS or "AddOns")
end

--------------------------------------------------------------------------------
-- Icons: pin scale, extra layers, built-in layers, unit pins, add-ons
--------------------------------------------------------------------------------
local function SameFunction(dp, mixin)
	return mixin and dp.RefreshAllData ~= nil and dp.RefreshAllData == mixin.RefreshAllData
end

function E.SetProvider(dp, on)
	local map = S.map
	if not dp then return end
	local has = map.dataProviders[dp]
	if on and not has then
		local ok, err = pcall(map.AddDataProvider, map, dp)
		if not ok then
			map.dataProviders[dp] = nil
			if not S.warned then S.warned = true; Print(L["A map layer failed to load:"], err) end
			return
		end
		if map:IsShown() then
			pcall(dp.RefreshAllData, dp, true)
			pcall(dp.OnShow, dp)
		end
	elseif not on and has then
		if map:IsShown() then pcall(dp.OnHide, dp) end
		pcall(map.RemoveDataProvider, map, dp)
		map.dataProviders[dp] = nil
	end
end

function E.SetupIcons()
	local map = S.map
	-- Built-in providers, matched by their own RefreshAllData implementation.
	S.builtin = {}
	for _, def in ipairs(BUILTINS) do
		for _, name in ipairs(def.mixins) do
			local mixin = _G[name]
			for dp in pairs(map.dataProviders) do
				if SameFunction(dp, mixin) then S.builtin[#S.builtin + 1] = { dp = dp, key = def.key } end
			end
		end
	end
	-- Pins from the extra layers use frame-level kinds the zone map doesn't know, so they
	-- borrow the world map's levels (read only). The zone map's own layout is never
	-- replaced: that would taint every pin it draws.
	local own = map:GetPinFrameLevelsManager()
	local world = WorldMapFrame and WorldMapFrame.GetPinFrameLevelsManager and WorldMapFrame:GetPinFrameLevelsManager()
	if world and own and world ~= own and world.GetValidFrameLevel and type(own.definitions) == "table" then
		S.levels, S.ownLevels = world, own.definitions
	end
	S.layers, S.guarded = {}, {}

	-- New pins inherit click-through state, and the extra layers' pins get their level.
	S.pinBase, S.pinSet, S.halos = setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" })
	S.kindOf, S.cpins, S.cpool = {}, {}, {}
	hooksecurefunc(map, "RegisterPin", function(_, pin)
		if S.interactive == false then PinMouse(pin, false) elseif pin.gmStored then PinMouse(pin, true) end
		local kind = S.levels and pin.pinFrameLevelType
		if kind and not S.ownLevels[kind] then
			local ok, level = pcall(S.levels.GetValidFrameLevel, S.levels, kind, pin.pinFrameLevelIndex)
			if ok and type(level) == "number" then pin:SetFrameLevel(level) end
		end
		E.SizePin(pin)
	end)
	-- Blizzard resets party/raid sizes when "show players" is toggled.
	hooksecurefunc(map, "UpdateUnitsVisibility", function()
		S.uGroup = (BattlefieldMapOptions and BattlefieldMapOptions.showPlayers) and BATTLEFIELD_MAP_PARTY_MEMBER_SIZE or 0
		E.ApplyUnitPins()
	end)
	-- Mark key held + left-click: ping or raid marker. Ctrl + right-click: GoodMap menu.
	-- Alt + right-click: TomTom waypoint. Double-click: ping. Double right-click: raid marker.
	map:AddCanvasClickHandler(function(canvas, button, x, y)
		if button == "LeftButton" and S.markKey and x then E.MarkAt(canvas:GetMapID(), x, y) return true end
		if button == "RightButton" then
			if IsControlKeyDown() then E.ShowMenu(canvas, x, y) return true end
			local TomTom = _G.TomTom
			if IsAltKeyDown() and db.tomTom and TomTom and TomTom.AddWaypoint and x then
				TomTom:AddWaypoint(canvas:GetMapID(), x, y, { title = format("%.1f, %.1f", x * 100, y * 100), from = TITLE })
				return true
			end
		end
		return E.MapClick(canvas, button, x, y)
	end, 100)
end

-- Double-click pings that spot; double right-click drops a raid marker. A single
-- click still opens a sub-zone (left) or goes up a map (right), a moment later,
-- once it's clear it wasn't the first half of a double-click.
local DOUBLE_CLICK = 0.35
function E.MapClick(canvas, button, x, y)
	if not x or IsShiftKeyDown() or IsAltKeyDown() or IsControlKeyDown() then return end
	if not ((button == "LeftButton" and db.dblPing) or (button == "RightButton" and db.dblMarker)) then return end
	local now, cx, cy = GetTime(), GetCursorPosition()
	local mapID = canvas:GetMapID()
	local last = S.lastClick
	if last and last.button == button and last.map == mapID and now - last.t <= DOUBLE_CLICK
		and abs(cx - last.cx) < 12 and abs(cy - last.cy) < 12 then
		S.lastClick = nil
		S.clickToken = (S.clickToken or 0) + 1                  -- the single click's action is off
		if button == "LeftButton" then E.MarkAt(mapID, x, y, "PING") else E.DoubleRight(mapID, x, y) end
		return true
	end
	S.lastClick = { button = button, map = mapID, t = now, cx = cx, cy = cy }
	-- What a single click would do, held for a moment.
	local sc, nav = S.sc, nil
	local ignore = sc.ShouldNavigateIgnoreZoneMapPositionData and sc:ShouldNavigateIgnoreZoneMapPositionData()
	if db.clickNavigate then
		if button == "LeftButton" then
			local info = C_Map.GetMapInfoAtPosition and C_Map.GetMapInfoAtPosition(mapID, x, y, ignore)
			if info and info.mapID and info.mapID ~= mapID then nav = info.mapID end
		elseif not ignore then
			local info = C_Map.GetMapInfo(mapID)
			if info and info.parentMapID and info.parentMapID > 0 then nav = info.parentMapID end
		end
	end
	if not nav then return end                                  -- a single click does nothing here anyway
	S.clickToken = (S.clickToken or 0) + 1
	local token = S.clickToken
	C_Timer.After(DOUBLE_CLICK, function()
		if S.clickToken == token and S.map:GetMapID() == mapID then
			S.lastInteract = GetTime()
			S.map:SetMapID(nav)
		end
	end)
	return true
end

-- The first marker goes straight down (a red X unless you pick another); once
-- one is on the map, a double right-click asks which one you want.
function E.DoubleRight(mapID, x, y)
	if not next(S.markers) then E.MarkAt(mapID, x, y, "MARKER", tonumber(db.markIcon) or 7) return end
	MenuUtil.CreateContextMenu(S.map, function(_, root)
		root:SetTag("MENU_GOODMAP_MARKER")
		root:CreateTitle(L["Place a raid marker"])
		for i = 1, 8 do root:CreateButton(E.MarkerName(i), function() E.MarkAt(mapID, x, y, "MARKER", i) end) end
		root:CreateDivider()
		root:CreateButton(L["Clear markers"], function() E.ClearMarkers() end)
	end)
end

function E.PinLevel(kind, fallback)
	local m = S.map and S.map:GetPinFrameLevelsManager()
	local ok, level = pcall(m.GetValidFrameLevel, m, kind)
	return (ok and type(level) == "number") and level or fallback
end

-- Icon sizes by type, on top of the global icon scale, and an optional dark
-- outline. Pins are recognised by their template name; area blobs and
-- full-map effects are never touched.
local PIN_KINDS = {
	{ "Blob", false }, { "SpellEffect", false }, { "Exploration", false }, { "Highlight", false }, { "GroupMember", false },
	{ "Vignette", "iconRare" },
	{ "Quest", "iconQuest" }, { "BonusObjective", "iconQuest" }, { "TaskPOI", "iconQuest" },
	{ "FlightPoint", "iconTravel" }, { "MapLink", "iconTravel" }, { "DungeonEntrance", "iconTravel" }, { "DelveEntrance", "iconTravel" },
	{ "HandyNotes", "iconAddons" }, { "GatherMate", "iconAddons" }, { "RareScanner", "iconAddons" }, { "^RS", "iconAddons" },
}

local function PinKind(template)
	if type(template) ~= "string" then return false end
	local kind = S.kindOf[template]
	if kind == nil then
		kind = false
		for _, k in ipairs(PIN_KINDS) do
			if template:find(k[1]) then kind = k[2] break end
		end
		S.kindOf[template] = kind
	end
	return kind
end

-- After Blizzard sets a pin's scale, multiply it by the size for its type.
local function ScalePin(pin)
	local key = PinKind(pin.pinTemplate)
	if not key then return end
	local cur = pin:GetScale()
	local set = S.pinSet[pin]
	local base = (set and abs(cur - set) < 1e-6) and S.pinBase[pin] or cur   -- Blizzard didn't rescale it
	S.pinBase[pin] = base
	local m = db[key]
	local want = base * m
	if abs(want - cur) > 1e-6 then
		pin:SetScale(want)
		if pin.ApplyCurrentPosition then pin:ApplyCurrentPosition() end
	end
	S.pinSet[pin] = want
	local halo = S.halos[pin]
	if db.iconOutline then
		local w, h = pin:GetSize()
		if w and w >= 6 then
			if not halo then
				halo = pin:CreateTexture(nil, "BACKGROUND", nil, -8)
				halo:SetTexture(CIRCLE_MASK)
				halo:SetVertexColor(0, 0, 0, 0.5)
				halo:SetPoint("CENTER", pin, "CENTER", 0, 0)
				Mask(halo)
				S.halos[pin] = halo
			end
			local s = max(w, h) * 1.2
			halo:SetSize(s, s)
			halo:Show()
		end
	elseif halo then
		halo:Hide()
	end
end

-- Nothing is hooked until you change a size or turn the outline on.
local function Sizing()
	return db.iconQuest ~= 1 or db.iconRare ~= 1 or db.iconTravel ~= 1 or db.iconAddons ~= 1 or db.iconOutline
end

function E.SizePin(pin)
	if not (PinKind(pin.pinTemplate) and (S.pinBase[pin] or Sizing())) then return end
	if not S.pinBase[pin] and pin.ApplyCurrentScale and not pin.gmScaleHook then
		pin.gmScaleHook = true
		hooksecurefunc(pin, "ApplyCurrentScale", ScalePin)
	end
	ScalePin(pin)
end

function E.ApplyPinSizes()
	if S.map then S.map:ExecuteOnAllPins(E.SizePin) end
end

-- GoodMap's own layers sit out combat and catch up when it ends: new pins drawn from
-- add-on code in combat run into Blizzard's combat lock (and it's wasted work mid-fight).
function E.Guard(dp)
	if not dp or dp.gmGuarded then return dp end
	dp.gmGuarded = true
	for _, name in ipairs({ "RefreshAllData", "RefreshPlugin" }) do
		local fn = dp[name]
		if type(fn) == "function" then
			dp[name] = function(self, ...)
				if InCombatLockdown() then S.layersStale = true return end
				return fn(self, ...)
			end
		end
	end
	S.guarded[#S.guarded + 1] = dp
	return dp
end

function E.CatchUpLayers()
	if not S.layersStale then return end
	S.layersStale = nil
	if not S.map:IsShown() then return end
	for _, dp in ipairs(S.guarded) do
		if S.map.dataProviders[dp] then pcall(dp.RefreshAllData, dp) end
	end
end

function E.WorldQuestSetup(dp)
	dp:SetMatchWorldMapFilters(true)
	dp:SetUsesSpellEffect(true)
	dp:SetCheckBounties(true)
	-- Blizzard refreshes world quests every 0.5 s; let the user pick a calmer rate.
	function dp:OnShow()
		if self.ticker then self.ticker:Cancel() end
		self.ticker = C_Timer.NewTicker(db.wqInterval, function() self:RefreshAllData() end)
	end
	function dp:OnHide()
		if self.ticker then self.ticker:Cancel(); self.ticker = nil end
	end
	S.worldQuests = dp
end

function E.ApplyLayers()
	for _, def in ipairs(LAYERS) do
		-- battlegrounds, flights and farming routes: no quest clutter
		local calm = S.mode == "PVP" or (S.flightOn and db.flightCalm) or (S.farmLook and db.farmCalm)
		local on = db[def.key] and not (calm and def.key ~= "L_tracking") and not (def.square and S.round)
		local id = def.id or def.key
		local list = S.layers[id]
		if on and not list then
			list = {}
			for _, name in ipairs(def.mixins) do
				local mixin = _G[name]
				if mixin then
					local dp = CreateFromMixins(mixin)
					if def.worldQuests then E.WorldQuestSetup(dp) end
					list[#list + 1] = E.Guard(dp)
				end
			end
			S.layers[id] = list
		end
		if list then for _, dp in ipairs(list) do E.SetProvider(dp, on) end end
	end
end

function E.ApplyBuiltins()
	for _, entry in ipairs(S.builtin) do E.SetProvider(entry.dp, db[entry.key]) end
end

function E.ApplyWorldQuestRate()
	local dp = S.worldQuests
	if dp and dp.ticker and S.map:IsShown() then dp:OnShow() end
end

function E.ApplyAreaLabels()
	if db.areaLabels and not S.areaLabel and AreaLabelDataProviderMixin then
		S.areaLabel = E.Guard(CreateFromMixins(AreaLabelDataProviderMixin))
		S.areaLabel:SetOffsetY(-10)
	end
	if S.areaLabel then
		E.SetProvider(S.areaLabel, db.areaLabels)
		if S.areaLabel.Label then S.areaLabel.Label:SetScale(0.695 * db.areaLabelScale) end
	end
end

-- Unit pins are only touched when you change them from Blizzard's defaults.
-- Blizzard's own player arrow on the map steps aside for yours. The new size only
-- takes effect when the map resizes its pins, so GoodMap asks it to right away.
function E.ApplyUnitPins()
	local gp, pin = E.GroupMembers()
	local layer = S.arrowLayer
	if layer then
		layer:SetFrameStrata(S.arrowTop and "TOOLTIP" or E.Strata())   -- /goodmap arrow top: a test
		layer:SetFrameLevel(E.ArrowLevel())
		S.arrow:SetFrameLevel(layer:GetFrameLevel() + 1)
	end
	if not gp then return end
	local p = ((S.radarVisible and db.radarHideArrow) or S.arrowActive) and 0 or db.playerSize
	if p ~= (S.uPlayer or BATTLEFIELD_MAP_PLAYER_SIZE) then
		gp:SetUnitPinSize("player", p)
		S.uPlayer = p
		if pin and pin.SynchronizePinSizes then pcall(pin.SynchronizePinSizes, pin) end
	end
	if BattlefieldMapOptions and BattlefieldMapOptions.showPlayers then
		local g = db.groupSize
		if S.mode == "PVP" then g = max(12, floor(g * 1.5 + 0.5)) end   -- easier to read in a fight
		if g ~= (S.uGroup or BATTLEFIELD_MAP_PARTY_MEMBER_SIZE) then
			gp:SetUnitPinSize("party", g)
			gp:SetUnitPinSize("raid", g)
			S.uGroup = g
		end
	end
end

function E.ApplyIcons()
	if abs(S.map:GetGlobalPinScale() - db.pinScale) > 0.001 then
		S.map:SetGlobalPinScale(db.pinScale)
		-- every pin already on the map takes the new size now, not on the next zone change
		if S.map.ExecuteOnAllPins then
			S.map:ExecuteOnAllPins(function(pin) if pin.ApplyCurrentScale then pcall(pin.ApplyCurrentScale, pin) end end)
		end
	end
	E.ApplyAreaLabels()
	E.ApplyUnitPins()
	E.ApplyArrowStyle()
	E.ApplyPinSizes()
	E.PlaceCanvasPins()
end

function E.ApplyThirdParty()
	local HN = _G.HandyNotes
	if HN and HN.WorldMapDataProvider and not S.handyNotes then
		S.handyNotes = E.Guard(CreateFromMixins(HN.WorldMapDataProvider))
		local function live() return S.map.dataProviders[S.handyNotes] and S.map:IsShown() end
		if type(HN.UpdateWorldMapPlugin) == "function" then
			hooksecurefunc(HN, "UpdateWorldMapPlugin", function(_, plugin)
				if live() and S.handyNotes.RefreshPlugin then S.handyNotes:RefreshPlugin(plugin) end
			end)
		end
		if type(HN.UpdateWorldMap) == "function" then
			hooksecurefunc(HN, "UpdateWorldMap", function() if live() then S.handyNotes:RefreshAllData() end end)
		end
	end
	if S.handyNotes then E.SetProvider(S.handyNotes, db.handyNotes) end

	local RS = _G.RareScannerDataProviderMixin
	if RS and not S.rareScanner then S.rareScanner = E.Guard(CreateFromMixins(MapCanvasDataProviderMixin, RS)) end
	if S.rareScanner then E.SetProvider(S.rareScanner, db.rareScanner) end

	-- GatherMate2's world map nodes (the radar shows its minimap ones already).
	if not S.gatherMate then
		local AA = _G.LibStub and _G.LibStub("AceAddon-3.0", true)
		local GM = AA and AA:GetAddon("GatherMate2", true)
		local ok, disp = false, nil
		if GM and GM.GetModule then ok, disp = pcall(GM.GetModule, GM, "Display", true) end
		local mixin = ok and type(disp) == "table" and (disp.WorldMapDataProvider or disp.worldMapDataProvider)
		if type(mixin) == "table" and type(mixin.RefreshAllData) == "function" then
			S.gatherMate = E.Guard(CreateFromMixins(MapCanvasDataProviderMixin, mixin))
			if type(disp.UpdateWorldMap) == "function" then
				hooksecurefunc(disp, "UpdateWorldMap", function()
					if S.map.dataProviders[S.gatherMate] and S.map:IsShown() then Later("gatherMate", function() pcall(S.gatherMate.RefreshAllData, S.gatherMate) end, 0.1) end
				end)
			end
		end
	end
	if S.gatherMate then E.SetProvider(S.gatherMate, db.gatherMate and S.mode ~= "PVP") end
	E.SetupHBD()
end

--------------------------------------------------------------------------------
-- Canvas pins: GoodMap's own markers and pings, and other add-ons' icons. They
-- sit on the map canvas at a map position and keep their size as you zoom.
--------------------------------------------------------------------------------
function E.CanvasPin(kind, level)
	local pool = S.cpool[kind]
	local f = pool and tremove(pool)
	if not f then
		f = CreateFrame("Frame", nil, S.canvas)
		f:SetSize(1, 1)
		f.kind = kind
	end
	f:SetFrameLevel(level)
	S.cpins[f] = true
	return f
end

function E.FreeCanvasPin(f)
	if not S.cpins[f] then return end
	S.cpins[f] = nil
	f:Hide()
	f.nx, f.ny = nil, nil
	local pool = S.cpool[f.kind] or {}
	S.cpool[f.kind] = pool
	pool[#pool + 1] = f
end

function E.PlaceCanvasPin(f, x, y)
	f.nx, f.ny = x, y
	if not x then f:Hide() return end
	local s = (f.k or 1) / max(S.sc:GetCanvasScale(), 0.01)
	f:SetScale(s)
	f:ClearAllPoints()
	f:SetPoint("CENTER", S.canvas, "TOPLEFT", x * S.canvas:GetWidth() / s, -y * S.canvas:GetHeight() / s)
	f:Show()
	if f.clip and S.round then f:SetShown(E.InView(x, y)) end
end

function E.PlaceCanvasPins()
	if not S.cpins then return end
	for f in pairs(S.cpins) do if f.nx then E.PlaceCanvasPin(f, f.nx, f.ny) end end
end

-- Other add-ons' icons can't share GoodMap's round mask, so off the circle they hide.
function E.InView(x, y)
	local sc = S.sc
	local cx, cy = sc:GetCurrentScrollX(), sc:GetCurrentScrollY()
	if not cx then return true end
	local s = sc:GetCanvasScale()
	local dx, dy = (x - cx) * S.canvas:GetWidth() * s, (y - cy) * S.canvas:GetHeight() * s
	local r = E.Diameter() / 2 - 4
	return dx * dx + dy * dy <= r * r
end

function E.ClipCanvasPins()
	for f in pairs(S.cpins) do
		if f.clip and f.nx then f:SetShown(not S.round or E.InView(f.nx, f.ny)) end
	end
end

--------------------------------------------------------------------------------
-- HereBeDragons world map pins (TomTom waypoints and others). The add-on's
-- own icon frames are borrowed while GoodMap shows and the world map doesn't;
-- the world map takes them back the moment it opens. HereBeDragons decides
-- which pins belong on which map, so its own placement code is reused.
--------------------------------------------------------------------------------
function E.SetupHBD()
	if S.hbd then return end
	local P = _G.LibStub and _G.LibStub("HereBeDragons-Pins-2.0", true)
	local wp = P and P.worldmapProvider
	if not (wp and type(wp.HandlePin) == "function" and type(P.worldmapPins) == "table") then return end
	local h = { lib = P, held = {} }
	local handle = wp.HandlePin
	local proxyMap = {
		GetMapID = function() return S.map:GetMapID() end,
		AcquirePin = function(_, _, icon, x, y, level) E.HBDPlace(icon, x, y, level) end,
	}
	local proxy = { GetMap = function() return proxyMap end }
	h.place = function(icon, data) pcall(handle, proxy, icon, data) end
	S.hbd = h
	local function resync() Later("hbd", E.HBDRefresh, 0.05) end
	hooksecurefunc(wp, "HandlePin", function(_, icon, data) if E.HBDLive() then h.place(icon, data) end end)
	for _, name in ipairs({ "RefreshAllData", "RemovePinByIcon", "RemovePinsByRef", "RemoveAllData" }) do
		if type(wp[name]) == "function" then hooksecurefunc(wp, name, resync) end
	end
	resync()
end

function E.HBDLive()
	return db.hbdPins and S.mapShown and not S.houseActive and S.mode ~= "PVP" and not (WorldMapFrame and WorldMapFrame:IsShown())
end

function E.HBDPlace(icon, x, y, level)
	local h = S.hbd
	if not (icon and x and y and icon.SetParent) then return end
	local f = h.held[icon]
	if not f then
		f = E.CanvasPin("hbd", E.PinLevel(level or "PIN_FRAME_LEVEL_AREA_POI", 2100))
		f.clip = true
		h.held[icon] = f
	end
	f.k = db.iconAddons
	icon:SetParent(f)
	icon:ClearAllPoints()
	icon:SetPoint("CENTER", f, "CENTER", 0, 0)
	icon:Show()
	E.PlaceCanvasPin(f, x, y)
end

function E.HBDRefresh()
	local h = S.hbd
	if not h then return end
	for icon, f in pairs(h.held) do
		h.held[icon] = nil
		-- still ours (not taken back by the world map): park it out of sight
		if icon:GetParent() == f then icon:Hide(); icon:SetParent(S.hidden) end
		E.FreeCanvasPin(f)
	end
	if not E.HBDLive() then return end
	for icon, data in pairs(h.lib.worldmapPins) do h.place(icon, data) end
end

--------------------------------------------------------------------------------
-- Unexplored areas: the zone art for the parts you haven't explored yet,
-- softly tinted. The art list lives in the load-on-demand add-on
-- GoodMap_Reveal (Blizzard game data), loaded only when this is turned on.
--------------------------------------------------------------------------------
function E.ApplyReveal()
	if db.reveal and not _G.GoodMap_RevealData then
		if InCombatLockdown() then S.revealAfterCombat = true return end
		local load = Pathway.AddOns.LoadAddOn
		local ok, loaded, why = false, false, nil
		if load then ok, loaded, why = pcall(load, "GoodMap_Reveal") end
		if not (ok and loaded and _G.GoodMap_RevealData) then
			if not S.revealWarned then
				S.revealWarned = true
				Print(format(L["Unexplored areas need GoodMap_Reveal, which comes with GoodMap. Turn it on in the AddOns list. (%s)"], tostring(why or "?")))
			end
			return
		end
	end
	if db.reveal and _G.GoodMap_RevealData and not S.reveal then
		local dp = CreateFromMixins(MapCanvasDataProviderMixin)
		dp.tex, dp.used, dp.cache = {}, 0, {}
		function dp:RefreshAllData() E.DrawReveal() end
		function dp:RemoveAllData() E.HideReveal() end
		function dp:OnMapChanged() E.DrawReveal() end
		function dp:OnCanvasScaleChanged()
			if E.LayerIndex() ~= S.revealLayer then E.DrawReveal() end
		end
		function dp:OnGlobalAlphaChanged() if S.revealFrame then S.revealFrame:SetAlpha(S.map:GetGlobalAlpha()) end end
		local f = CreateFrame("Frame", nil, S.canvas)
		f:SetAllPoints(S.canvas)
		f:EnableMouse(false)
		S.revealFrame, S.reveal = f, dp
	end
	if S.reveal then
		E.SetProvider(S.reveal, db.reveal)
		if db.reveal then E.DrawReveal() else E.HideReveal() end
	end
end

-- "w,h,x,y[,flags]:fileIDs;..." -> { { w, h, x, y, ids }, ... }; "a+n" is a, a+1 .. a+n.
function E.RevealArt(artID)
	local cache = S.reveal.cache
	local list = cache[artID]
	if list == nil then
		list = false
		local raw = _G.GoodMap_RevealData and _G.GoodMap_RevealData[artID]
		if type(raw) == "string" then
			list = {}
			for o in raw:gmatch("[^;]+") do
				local w, h, x, y, rest = o:match("^(%d+),(%d+),(%d+),(%d+)[,%d]*:(.+)$")
				if w then
					local ids = {}
					for a, n in rest:gmatch("(%d+)%+?(%d*)") do
						a = tonumber(a)
						for i = 0, tonumber(n) or 0 do ids[#ids + 1] = a + i end
					end
					list[#list + 1] = { tonumber(w), tonumber(h), tonumber(x), tonumber(y), ids }
				end
			end
		end
		cache[artID] = list
	end
	return list
end

function E.HideReveal()
	local dp = S.reveal
	if not dp then return end
	for i = 1, dp.used do dp.tex[i]:Hide() end
	dp.used = 0
end

-- The map's current art layer. Before the map has its zoom levels (right at login)
-- Blizzard's own lookup errors, so it's the first layer until then.
function E.LayerIndex()
	local sc = S.sc
	if not (sc.zoomLevels and sc.GetCurrentLayerIndex) then return 1 end
	return sc:GetCurrentLayerIndex() or 1
end

function E.DrawReveal()
	E.HideReveal()
	local dp, map = S.reveal, S.map
	if not (dp and db.reveal and map.dataProviders[dp]) then return end
	local mapID = map:GetMapID()
	local art = mapID and C_Map.GetMapArtID and C_Map.GetMapArtID(mapID)
	local list = art and E.RevealArt(art)
	local layers = list and C_Map.GetMapArtLayers(mapID)
	local layerIndex = E.LayerIndex()
	local layer = layers and (layers[layerIndex] or layers[1])
	if not layer then return end
	S.revealLayer = layerIndex
	-- what you've explored already, by its first tile
	local explored = {}
	local info = _G.C_MapExplorationInfo and _G.C_MapExplorationInfo.GetExploredMapTextures(mapID)
	for _, e in ipairs(info or {}) do
		if e.fileDataIDs and e.fileDataIDs[1] then explored[e.fileDataIDs[1]] = true end
		explored[(e.offsetX or -1) .. ":" .. (e.offsetY or -1)] = true
	end
	local TW, TH = layer.tileWidth, layer.tileHeight
	local f = S.revealFrame
	f:SetFrameLevel(E.PinLevel("PIN_FRAME_LEVEL_MAP_EXPLORATION", 2001))
	f:SetAlpha(map:GetGlobalAlpha())
	local tint = db.revealTint
	local n = 0
	for _, o in ipairs(list) do
		local w, h, ox, oy, ids = o[1], o[2], o[3], o[4], o[5]
		if not (explored[ids[1]] or explored[ox .. ":" .. oy]) then
			local wide, tall = ceil(w / TW), ceil(h / TH)
			for j = 1, tall do
				local ph = j < tall and TH or (h % TH == 0 and TH or h % TH)
				local fh = TH
				if j == tall then fh = 16; while fh < ph do fh = fh * 2 end end
				for k = 1, wide do
					local id = ids[(j - 1) * wide + k]
					if id then
						local pw = k < wide and TW or (w % TW == 0 and TW or w % TW)
						local fw = TW
						if k == wide then fw = 16; while fw < pw do fw = fw * 2 end end
						n = n + 1
						local t = dp.tex[n]
						if not t then t = f:CreateTexture(nil, "ARTWORK"); Mask(t); dp.tex[n] = t end
						t:SetSize(pw, ph)
						t:SetTexCoord(0, pw / fw, 0, ph / fh)
						t:ClearAllPoints()
						t:SetPoint("TOPLEFT", f, "TOPLEFT", ox + TW * (k - 1), -(oy + TH * (j - 1)))
						t:SetTexture(id, nil, nil, "TRILINEAR")
						if tint then t:SetVertexColor(0.62, 0.68, 0.8) else t:SetVertexColor(1, 1, 1) end
						t:Show()
					end
				end
			end
		end
	end
	dp.used = n
end

--------------------------------------------------------------------------------
-- Minimap radar: the real minimap lives inside GoodMap, centred on you.
--   ALIGNED: terrain off, minimap sized so its blips sit on true map positions.
--   FIXED:   a classic round minimap inset of a fixed size.
-- The radar never pokes out of GoodMap's window: it is clipped to the window,
-- shrinks to fit near the edges, and fades out while you drag the map away.
--------------------------------------------------------------------------------
function E.SetupRadar()
	local holder = CreateFrame("Frame", nil, S.map)
	holder:SetAllPoints(S.sc)
	-- above the map art and the explored-area art, below every map pin
	holder:SetFrameLevel(E.PinLevel("PIN_FRAME_LEVEL_MAP_EXPLORATION", 1500) + 1)
	holder:SetClipsChildren(true)
	holder:Hide()
	S.radarHolder = holder

	local anchor = CreateFrame("Frame", nil, S.canvas)
	anchor:SetSize(1, 1)
	anchor:SetPoint("CENTER", S.canvas, "TOPLEFT", 0, 0)
	S.radarAnchor = anchor
	S.radarSaved = {}
	S.radiusCache = {}

	EventRegistry:RegisterCallback("EditMode.Enter", function()
		S.editMode = true
		E.EndPeek()
		E.UpdateVisibility()
		E.UpdateRadarState(); E.UpdateCluster(); E.RefreshBar()
		E.ApplyEditMode()
	end, E)
	EventRegistry:RegisterCallback("EditMode.Exit", function()
		S.editMode = false
		E.ApplyEditMode()
		E.UpdateVisibility()
		E.UpdateCluster(); E.UpdateRadarState(); E.RefreshBar()
	end, E)
	if _G.HybridMinimap then E.HookHybrid() end
	-- Something else re-showing the Blizzard minimap while GoodMap replaces it.
	if MinimapCluster then
		MinimapCluster:HookScript("OnShow", function(self) if S.clusterHidden then self:SetAlpha(0) end end)
	end
end

function E.HookHybrid()
	local hm = _G.HybridMinimap
	if not hm or S.hybridHooked then return end
	S.hybridHooked = true
	local function reapply() if S.radarEmbedded then Later("radarLook", E.ApplyRadarLook) end end
	hm:HookScript("OnShow", reapply)
	hm:HookScript("OnHide", reapply)
end

function E.UpdateRadarState()
	-- Short position drop-outs (map edges, loading) must not bounce the minimap back and forth.
	local posFine = S.posOK
	if posFine then
		S.posLost = nil
	elseif S.radarEmbedded then
		S.posLost = S.posLost or GetTime()
		posFine = GetTime() - S.posLost < 1.5
	end
	-- Cities and inns can show a gray square where the minimap's terrain would be, so a
	-- radar that draws terrain sits those out. Aligned (icons only, no terrain) has no
	-- square, so towns keep their mailboxes, banks and auction houses. Indoors the game
	-- zooms the minimap its own way, so the radar steps out unless you ask for it.
	local terrain = not E.RadarAligned() and db.radarTerrain
	local place = (db.radarCities or not terrain or not (IsResting and IsResting())) and (db.radarIndoors or not IsIndoors())
	local radar = db.radar and S.mode ~= "PVP"
	local want = (radar and place and S.mapShown and not S.editMode and not S.houseActive and posFine) and true or false
	if S.detail then want = S.mapShown and not S.editMode and true or false end
	if want ~= (S.radarEmbedded or false) then
		-- moving the game's minimap in or out runs its layout; in a fight that waits
		if InCombatLockdown() then S.radarAfterCombat = true
		elseif want then E.RadarEmbed() else E.RadarRelease() end
	end
	if S.radarEmbedded then
		-- no gathering blips from a flight path; only where GoodMap knows where you are, so the
		-- picture never sits loose at an old spot (the tram's picture is centred, so it always fits)
		local ride = S.detail and E.RideKind and E.RideKind() == "tram"
		local visible = (ride or ((S.detail or (S.map:GetMapID() == S.playerMap and not S.flightOn)) and posFine)) and true or false
		if visible ~= S.radarVisible then
			S.radarVisible = visible
			if visible then
				local px, py = PlayerPos(S.playerMap)
				if px then S.ax = nil; E.RadarAnchor(px, py) end
				E.UpdateRadarSize()
				S.radarFits = nil
				if px then E.RadarFit(px, py) end
			end
			S.radarHolder:SetShown(visible)
			if S.detail then S.radarHolder:SetAlpha(1) end
			E.ApplyUnitPins()
		end
	end
end

function E.RadarEmbed()
	local mm = Minimap
	if not mm or S.radarEmbedded then return end
	local M, R = MT(mm), S.radarSaved
	wipe(R)
	R.parent, R.scale, R.strata, R.level = mm:GetParent(), mm:GetScale(), mm:GetFrameStrata(), mm:GetFrameLevel()
	R.w, R.h = mm:GetSize()
	R.mouse, R.wheel, R.alpha, R.zoom, R.shown = mm:IsMouseEnabled(), mm:IsMouseWheelEnabled(), mm:GetAlpha(), mm:GetZoom(), mm:IsShown()
	R.points = {}
	for i = 1, mm:GetNumPoints() do R.points[i] = { mm:GetPoint(i) } end
	if mm.ZoomHitArea then R.hit = mm.ZoomHitArea:IsMouseEnabled() end

	local holder = S.radarHolder
	M.SetParent(mm, holder)
	M.ClearAllPoints(mm)
	M.SetPoint(mm, "CENTER", S.radarAnchor, "CENTER", 0, 0)
	M.SetScale(mm, 1)
	M.SetFrameStrata(mm, E.Strata())
	M.SetFrameLevel(mm, holder:GetFrameLevel() + 1)
	M.Show(mm)
	if MinimapBackdrop then R.backdrop = MinimapBackdrop:IsShown(); MinimapBackdrop:Hide() end
	S.radarEmbedded, S.radarVisible, S.radarD, S.radarFits = true, nil, nil, nil
	holder:SetAlpha(1)
	if E.RadarAligned() then M.SetZoom(mm, 0) end
	E.ApplyRadarLook()
	E.RefreshBar()
end

function E.RadarRelease()
	if not S.radarEmbedded then return end
	local mm = Minimap
	local M, R = MT(mm), S.radarSaved
	S.radarEmbedded, S.radarVisible, S.radarFits, S.radarAvail = false, false, nil, nil
	S.radarHolder:Hide()
	M.SetParent(mm, R.parent)
	M.ClearAllPoints(mm)
	for _, p in ipairs(R.points) do M.SetPoint(mm, unpack(p)) end
	M.SetScale(mm, R.scale)
	M.SetSize(mm, R.w, R.h)
	M.SetFrameStrata(mm, R.strata)
	M.SetFrameLevel(mm, R.level)
	M.EnableMouse(mm, R.mouse)
	M.EnableMouseWheel(mm, R.wheel)
	M.SetAlpha(mm, R.alpha)
	if mm.ZoomHitArea and R.hit ~= nil then mm.ZoomHitArea:EnableMouse(R.hit) end
	if R.zoom then M.SetZoom(mm, min(R.zoom, mm:GetZoomLevels() - 1)) end
	local hybrid = _G.HybridMinimap and _G.HybridMinimap:IsShown() or false
	C_Minimap.SetDrawGroundTextures(not hybrid)
	C_Minimap.SetIgnoreRotateMinimap(hybrid)
	if _G.HybridMinimap then _G.HybridMinimap:SetAlpha(1) end
	if R.iconScaled then
		local ok = MinimapCluster and MinimapCluster.UpdateSystemSettingIconScale and pcall(MinimapCluster.UpdateSystemSettingIconScale, MinimapCluster)
		if not ok then mm:SetIconScale(1) end
	end
	if R.backdrop and MinimapBackdrop then MinimapBackdrop:Show() end
	M.SetShown(mm, R.shown ~= false)
	E.ClusterTakesBack(mm)
	E.ApplyUnitPins()
	E.RefreshBar()
end

-- The radar always shows what a node or icon is when you hover it. It takes clicks
-- and the mouse wheel only as an "interactive radar"; otherwise they go to the map.
-- Farming and click-through leave the mouse to the world.
function E.RadarMouse()
	if not S.radarEmbedded then return end
	local mm, R = Minimap, S.radarSaved
	local M = MT(mm)
	local on = S.interactive ~= false
	local full = on and db.radarMouse
	M.EnableMouse(mm, full)
	M.EnableMouseWheel(mm, full)
	if not full then M.SetMouseMotionEnabled(mm, on) end
	if mm.ZoomHitArea then mm.ZoomHitArea:EnableMouse(full and (R.hit or false)) end
end

function E.RadarAligned() return db.radarMode == "ALIGNED" end

function E.ApplyRadarLook()
	if not S.radarEmbedded then return end
	local mm, R = Minimap, S.radarSaved
	local M = MT(mm)
	local aligned = E.RadarAligned()
	local terrain = (S.detail or ((not aligned) and db.radarTerrain)) and true or false
	C_Minimap.SetDrawGroundTextures(terrain)
	C_Minimap.SetIgnoreRotateMinimap(aligned or S.detail or false)
	if _G.HybridMinimap then _G.HybridMinimap:SetAlpha(terrain and 1 or 0) end
	M.SetAlpha(mm, S.detail and 1 or (terrain and db.radarAlpha or 1))
	M.SetFrameStrata(mm, E.Strata())
	E.RadarMouse()
	local iconScale = db.radarIconScale
	if iconScale ~= 1 or R.iconScaled then
		mm:SetIconScale(iconScale)
		R.iconScaled = true
	end
	S.radarD = nil
	E.UpdateRadarSize()
end

function E.RadarAnchor(px, py)
	if S.detail then return end
	local x, y = px * S.canvas:GetWidth(), -py * S.canvas:GetHeight()
	if not S.ax or abs(x - S.ax) > 0.05 or abs(y - S.ay) > 0.05 then
		S.ax, S.ay = x, y
		S.radarAnchor:SetPoint("CENTER", S.canvas, "TOPLEFT", x, y)
	end
end

-- How much room the radar has around you before it would cross the window edge.
function E.RadarFit(px, py)
	if S.detail then return end
	local sc = S.sc
	local cx, cy = sc:GetCurrentScrollX(), sc:GetCurrentScrollY()
	if not (cx and cy) then return end
	local scale = sc:GetCanvasScale()
	local dx = (px - cx) * S.canvas:GetWidth() * scale
	local dy = (py - cy) * S.canvas:GetHeight() * scale
	local avail
	if S.round then avail = min(sc:GetWidth(), sc:GetHeight()) * 0.5 - sqrt(dx * dx + dy * dy)
	else avail = min(sc:GetWidth() * 0.5 - abs(dx), sc:GetHeight() * 0.5 - abs(dy)) end
	S.radarAvail = avail
	local fits = (S.radarD or 0) * 0.5 <= avail + 1
	if fits ~= S.radarFits then
		S.radarFits = fits
		FadeTo(S.radarHolder, fits and 1 or 0)
	end
end

-- While idle, resize the radar to the room it has (near zone borders, with a dead zone).
function E.RadarAdapt()
	if S.detail then return end
	if not (S.radarVisible and S.radarAvail and S.idle) then return end
	if abs(S.radarAvail - (S.radarAvailUsed or -1000)) > 8 or S.radarFits == false then
		S.radarAvailUsed = S.radarAvail
		E.UpdateRadarSize()
	end
end

function E.RadarLimit()
	local limit = min(S.sc:GetWidth(), S.sc:GetHeight()) * 0.9 * (1 - db.deadzone)
	if S.idle and S.radarAvail then limit = min(limit, max(24, 2 * S.radarAvail - 4)) end
	return limit
end

-- Pick the minimap zoom whose diameter fits GoodMap (radii are learnt as we go).
function E.RadarAutoZoom(d)
	local mm = Minimap
	local zoom, levels = mm:GetZoom(), mm:GetZoomLevels()
	local key = IsIndoors() and "in" or "out"
	local cache = S.radiusCache[key] or {}
	S.radiusCache[key] = cache
	local r = C_Minimap.GetViewRadius()
	cache[zoom] = r
	local limit = E.RadarLimit()
	if d > limit and zoom < levels - 1 then
		MT(mm).SetZoom(mm, zoom + 1)
		return true
	elseif zoom > 0 then
		local wider = cache[zoom - 1]
		if (wider and d * wider / r <= limit) or (not wider and d < limit * 0.5) then
			MT(mm).SetZoom(mm, zoom - 1)
			return true
		end
	end
end

function E.UpdateRadarSize()
	if not S.radarEmbedded then return end
	if S.detail then E.DetailLayout() return end
	local d
	if E.RadarAligned() then
		local mapID = S.map:GetMapID()
		local w = mapID and MapYards(mapID)
		if not w then return end
		local pixelsPerYard = S.canvas:GetWidth() * S.sc:GetCanvasScale() / w
		d = 2 * C_Minimap.GetViewRadius() * pixelsPerYard
		if db.radarAutoZoom and E.RadarAutoZoom(d) then return end   -- MINIMAP_UPDATE_ZOOM re-runs us
	else
		d = db.radarSize
		if S.idle and S.radarAvail then d = min(d, max(40, 2 * S.radarAvail - 4)) end
	end
	d = max(d, 8)
	if not S.radarD or abs(d - S.radarD) > 0.25 then
		S.radarD = d
		MT(Minimap).SetSize(Minimap, d, d)
	end
end

function E.ApplyRadar()
	local mode = E.RadarAligned() and "ALIGNED" or "FIXED"
	if S.radarEmbedded then
		if mode == "ALIGNED" and S.lastRadarMode ~= "ALIGNED" then MT(Minimap).SetZoom(Minimap, 0) end
		E.ApplyRadarLook()
	end
	S.lastRadarMode = mode
	E.UpdateRadarState()
	E.ApplyUnitPins()
	E.RefreshBar()
end

--------------------------------------------------------------------------------
-- Detail view: inside a building, a cave or a tunnel the game has no map for,
-- and in cities and towns, GoodMap shows the game's own detailed minimap
-- picture (the rooms of the inn, the streets and houses of the city) filling
-- the whole window, in GoodMap's frame, with the game's blips and Pathway's
-- quest spots and route on it. Zoom out past its widest view to go back to the
-- zone map; zoom in past the zone map's closest to come back.
--------------------------------------------------------------------------------
local CITY_MAPS = { [1453] = true, [1455] = true, [1457] = true, [1454] = true, [1456] = true, [1458] = true }
local CITY_INDOORS = { [1455] = true, [1458] = true }       -- Ironforge and Undercity: inside the mountain, under the ground
function E.DetailWanted()
	-- the tram's tunnel: the game's own tram map, you on the line, under the rainbow
	if E.RideKind and E.RideKind() == "tram" then return S.mapShown and not S.editMode and true or false end
	if not (db.detailView and S.mapShown and S.playerMap) then return false end
	if S.flightOn or S.flightMap then S.detailManual = nil return false end
	if S.houseActive or S.peeking or S.editMode or S.mode == "PVP" then return false end
	if S.map:GetMapID() ~= S.playerMap then return false end       -- you're looking at another map
	if S.detailOff then return false end
	if UnitOnTaxi and UnitOnTaxi("player") then return false end
	-- you zoomed in past the map's closest: the detail stays until you zoom back out
	if S.detailManual or S.detailForce then return true end
	local info = C_Map.GetMapInfo(S.playerMap)
	local zoneLevel = not info or not info.mapType or info.mapType <= (Enum.UIMapType and Enum.UIMapType.Zone or 3)
	-- indoors with no map of its own (an inn, a house, a tunnel): the rooms themselves
	if IsIndoors and IsIndoors() and zoneLevel and not CITY_MAPS[S.playerMap] then return true end
	-- a city or a town: its streets and houses, until you leave it
	if db.detailCities and zoneLevel then
		if CITY_MAPS[S.playerMap] and not (E.TerrainOn and E.TerrainOn() and not CITY_INDOORS[S.playerMap]) then return true end
		local PW = _G.Pathway
		local town = PW and PW.TownHere and PW:TownHere(S.inTown ~= nil)
		S.inTown = town
		-- where the continent has terrain squares, the map itself zooms in to them (Terrain.lua)
		local terrain = E.TerrainOn and E.TerrainOn() and not CITY_INDOORS[S.playerMap]
		if E.TownZoom and terrain then E.TownZoom(town ~= nil or CITY_MAPS[S.playerMap] == true) end
		if terrain then return false end
		if town then return true end
	end
	return false
end

function E.UpdateDetail()
	local want = E.DetailWanted()
	if want == (S.detail or false) then
		if S.detail then E.DetailLayout() end
		return
	end
	S.detail = want
	local holder = S.radarHolder
	if want then
		-- the picture sits where the radar does: over the map's art, under every pin. The map
		-- follows the picture's scale and stays on you (DetailSync), so the pins line up on it.
		S.detailPrevScale = S.sc.targetScale or S.sc:GetCanvasScale()
		holder:SetAlpha(0); FadeTo(holder, 1)
		if not S.round and Minimap.SetMaskTexture then Minimap:SetMaskTexture("Interface\\Buttons\\WHITE8X8"); S.detailMask = true end
	else
		if S.detailPrevScale and S.sc.SetZoomTarget then S.sc:SetZoomTarget(S.detailPrevScale) end
		S.detailPrevScale = nil
		if S.detailMask and Minimap.SetMaskTexture then Minimap:SetMaskTexture("Textures\\MinimapMask"); S.detailMask = nil end
	end
	S.radarVisible, S.radarD = nil, nil
	E.UpdateRadarState()
	if S.radarEmbedded then
		if want then
			local M = MT(Minimap)
			M.ClearAllPoints(Minimap)
			M.SetPoint(Minimap, "CENTER", S.sc, "CENTER", 0, 0)
			if S.detailZoom then M.SetZoom(Minimap, min(S.detailZoom, Minimap:GetZoomLevels() - 1)) end
		else
			local M = MT(Minimap)
			M.ClearAllPoints(Minimap)
			M.SetPoint(Minimap, "CENTER", S.radarAnchor, "CENTER", 0, 0)
			if E.RadarAligned() then M.SetZoom(Minimap, 0) end
		end
		E.ApplyRadarLook()
		holder:SetShown(true)
	end
	E.UpdateHeading(); E.ApplyUnitPins()
	if Pathway.Send then Pathway:Send("GOODMAP_DETAIL", want) end
end

-- How many yards the window shows across, and how many the game's picture shows
-- at its widest. Zooming the map in past the picture's widest view switches over
-- to it (the map's art has no more detail to give there); zooming the picture
-- out past its widest switches back, at the same scale.
local PICTURE_YARDS = { out = 466.67, inside = 300 }
function E.PictureYards() return (IsIndoors and IsIndoors()) and PICTURE_YARDS.inside or PICTURE_YARDS.out end
function E.ViewYards(scale)
	local mapID = S.map:GetMapID()
	local w = mapID and MapYards(mapID)
	local cw = S.canvas:GetWidth()
	scale = scale or S.sc:GetCanvasScale()
	if not (w and cw and cw > 0 and scale and scale > 0) then return end
	return min(S.sc:GetWidth(), S.sc:GetHeight()) * w / (cw * scale)
end
function E.DetailZoomCheck()
	if S.detail or not db.detailView or S.flightOn or S.map:GetMapID() ~= S.playerMap then return end
	if E.TerrainOn and E.TerrainOn() and not (IsIndoors and IsIndoors()) then return end     -- the terrain fades in instead
	if not (S.wheelAt and GetTime() - S.wheelAt < 1.5) then return end      -- only when you zoom yourself
	local v = E.ViewYards(S.sc.targetScale)
	if v and v <= E.PictureYards() then
		S.detailOff, S.detailManual = nil, true
		S.detailZoom = 0
		E.UpdateDetail()
	end
end
-- back to the map at about the picture's widest scale (a little wider), centred on you
function E.MapAtPicture()
	local mapID = S.map:GetMapID()
	local w = mapID and MapYards(mapID)
	local cw = S.canvas:GetWidth()
	if not (w and cw and cw > 0) then return end
	local want = min(S.sc:GetWidth(), S.sc:GetHeight()) * w / (cw * E.PictureYards() * 1.3)
	local levels = S.sc.zoomLevels
	if levels and levels[1] and levels[1].scale and levels[#levels].scale then want = Clamp(want, levels[1].scale, levels[#levels].scale) end
	local px, py = PlayerPos(S.playerMap)
	if px and S.sc.InstantPanAndZoom then S.sc:InstantPanAndZoom(want, px, py, true)
	elseif S.sc.SetZoomTarget then S.sc:SetZoomTarget(want) end
end

-- Keep the map at the picture's scale and centred on you, so the map's pins sit
-- on the picture where they belong (a few times a second is plenty for pins).
function E.DetailSync()
	if not (S.detail and S.radarEmbedded) then return end
	local mapID = S.map:GetMapID()
	local w, cw = mapID and MapYards(mapID), S.canvas:GetWidth()
	local r = C_Minimap.GetViewRadius and C_Minimap.GetViewRadius()
	local d = S.radarD or E.Diameter()
	if not (w and cw and cw > 0 and r and r > 0 and d > 0) then return end
	-- the picture shows 2r yards over d pixels: the canvas at that many pixels a yard
	local scale = (d / (2 * r)) * w / cw
	local px, py = PlayerPos(S.playerMap)
	if not px then return end
	if S.syncScale and abs(S.syncScale - scale) / scale < 0.002 and abs((S.syncX or 0) - px) < 1e-5 and abs((S.syncY or 0) - py) < 1e-5 then return end
	S.syncScale, S.syncX, S.syncY = scale, px, py
	if S.sc.InstantPanAndZoom then S.sc:InstantPanAndZoom(scale, px, py, true) end
end

-- the game's picture covers the whole window: round or square
function E.DetailLayout()
	if not (S.detail and S.radarEmbedded) then return end
	local w, h = S.sc:GetWidth() or 0, S.sc:GetHeight() or 0
	local d = S.round and min(w, h) or max(w, h)
	if d > 8 and (not S.radarD or abs(d - S.radarD) > 0.25) then
		S.radarD = d
		MT(Minimap).SetSize(Minimap, d, d)
	end
end

-- the mouse wheel zooms the game's picture; past its widest view, back to the zone map
function E.DetailWheel(delta)
	if not delta then return false end
	if S.detail then
		local mm = Minimap
		local z, levels = mm:GetZoom(), mm:GetZoomLevels()
		if delta > 0 and z < levels - 1 then MT(mm).SetZoom(mm, z + 1); S.syncScale = nil
		elseif delta < 0 and z > 0 then MT(mm).SetZoom(mm, z - 1); S.syncScale = nil
		elseif delta < 0 then
			S.detailOff, S.detailManual = true, nil
			E.UpdateDetail()
			if not S.detail then E.MapAtPicture() end
		end
		S.detailZoom = mm:GetZoom()
		return true
	end
	S.wheelAt = GetTime()
	-- on the zone map, anywhere: one more turn in at its closest zoom brings the detail in
	-- (on maps whose closest zoom never gets as near as the picture)
	local sc = S.sc
	local i = sc.zoomLevels and sc:GetZoomLevelIndexForScale(sc.targetScale or sc:GetCanvasScale())
	local atMax = i and i >= #sc.zoomLevels
	if delta > 0 and atMax and db.detailView and S.map:GetMapID() == S.playerMap and not S.flightOn
		and not (E.TerrainOn and E.TerrainOn() and not (IsIndoors and IsIndoors())) then
		S.detailOff, S.detailManual = nil, true
		S.detailZoom = 0                           -- its widest view: the closest step after the map's own
		E.UpdateDetail()
		return S.detail and true or false
	end
	return false
end
function E.InDetail() return S.detail and true or false end
do
	local sync = CreateFrame("Frame")
	local acc = 0
	sync:SetScript("OnUpdate", Pathway.Perf.W("Minimap", function(_, elapsed)
		if not S.detail then return end
		acc = acc + elapsed
		if acc < 0.05 then return end
		acc = 0
		E.DetailSync()
	end))
end

--------------------------------------------------------------------------------
-- Button bar: GoodMap's own button, Blizzard's minimap buttons and LibDBIcon
-- add-on buttons, docked next to the map
--------------------------------------------------------------------------------
local BLIZZARD_BUTTONS = { "tracking", "calendar", "indicator", "compartment", "expansion" }
local function BlizzardButton(id)
	local mc = MinimapCluster
	if id == "tracking" then return mc and mc.Tracking
	elseif id == "calendar" then return GameTimeFrame
	elseif id == "indicator" then return mc and mc.IndicatorFrame
	elseif id == "compartment" then return AddonCompartmentFrame
	elseif id == "expansion" then return ExpansionLandingPageMinimapButton end
end

function E.SetupBar()
	local bar = CreateFrame("Frame", nil, S.map)
	-- Kept well under the 10000 frame-level ceiling: Blizzard menus open 500+ levels
	-- above the button that owns them (add-on list, tracking), and once they hit the
	-- ceiling the menu's dark background draws over its own text.
	bar:SetFrameLevel(9000)
	bar:SetSize(1, 1)
	bar:Hide()
	-- a quiet strip behind the buttons, with a hairline in Pathway's color
	bar.bg = bar:CreateTexture(nil, "BACKGROUND")
	bar.bg:SetPoint("TOPLEFT", -5, 4); bar.bg:SetPoint("BOTTOMRIGHT", 5, -4)
	bar.bg:SetColorTexture(0.03, 0.035, 0.045, 0.72)
	bar.line = bar:CreateTexture(nil, "BORDER")
	bar.line:SetPoint("TOPLEFT", bar.bg, "TOPLEFT"); bar.line:SetPoint("TOPRIGHT", bar.bg, "TOPRIGHT"); bar.line:SetHeight(1)
	local function tint() local a = Pathway.ACCENT; bar.line:SetColorTexture(a[1], a[2], a[3], 0.8) end
	tint(); Pathway:OnPaint(tint)
	S.bar, S.barList, S.slots, S.grabbed, S.hookedButtons = bar, {}, {}, {}, {}
	S.looseSeen, S.looseList, S.looseDirty = {}, {}, true
	S.queueLayout = function() Later("barLayout", E.LayoutBar) end

	-- GoodMap's own button
	local launcher = CreateFrame("Button", nil, bar)
	launcher:SetSize(31, 31)
	launcher:RegisterForClicks("LeftButtonUp", "RightButtonUp")
	launcher.icon = launcher:CreateTexture(nil, "ARTWORK")
	launcher.icon:SetAllPoints()
	launcher.icon:SetTexture(ICON)
	launcher.icon:SetTexCoord(0.08, 0.92, 0.08, 0.92)
	launcher:SetHighlightTexture("Interface\\Buttons\\ButtonHilight-Square", "ADD")
	launcher:SetScript("OnClick", function(self, button) if button == "RightButton" then E.OpenSettings() else E.ShowMenu(self) end end)
	launcher:SetScript("OnEnter", function(self) Tooltip(self, BRAND, L["Click: menu"], L["Right-click: settings"]) end)
	launcher:SetScript("OnLeave", HideTooltip)
	S.launcher = launcher

	if MiniMapIndicatorFrame_UpdatePosition then hooksecurefunc("MiniMapIndicatorFrame_UpdatePosition", S.queueLayout) end
	if MinimapCluster and MinimapCluster.SetHeaderUnderneath then
		hooksecurefunc(MinimapCluster, "SetHeaderUnderneath", function()
			S.queueLayout()
			if S.diffSaved then Later("difficulty", E.ApplyDifficulty) end
		end)
	end
	local eb = ExpansionLandingPageMinimapButton
	if eb then
		if eb.SetLandingPageIconOffset then hooksecurefunc(eb, "SetLandingPageIconOffset", S.queueLayout) end
		if eb.ResetLandingPageIconOffset then hooksecurefunc(eb, "ResetLandingPageIconOffset", S.queueLayout) end
	end
end

function E.LDBI()
	if not S.ldbi and _G.LibStub then
		S.ldbi = _G.LibStub("LibDBIcon-1.0", true)
		if S.ldbi and S.ldbi.RegisterCallback then
			S.ldbi.RegisterCallback(E, "LibDBIcon_IconCreated", function() Later("barRefresh", E.RefreshBar, 0.1) end)
		end
	end
	return S.ldbi
end

-- Other add-ons' own minimap buttons (made without LibDBIcon). Only a named,
-- unprotected, button-sized Button that sits on the minimap (or is pinned to it)
-- and whose name says it's a minimap button qualifies, so map pins and
-- waypoint markers are never picked up.
local LOOSE_NAMES = { "minimap", "mapicon", "mapbutton" }
local LOOSE_SKIP = { "pin", "poi", "node", "marker", "waypoint", "arrow", "blip", "ping", "zoom",
	"libdbicon", "goodmap", "tracking", "expansionlanding", "zonetext", "clock", "calendar", "mail", "queue" }

local function LooseName(name)
	if type(name) ~= "string" then return false end
	name = name:lower()
	for _, w in ipairs(LOOSE_SKIP) do if name:find(w, 1, true) then return false end end
	for _, w in ipairs(LOOSE_NAMES) do if name:find(w, 1, true) then return true end end
	return false
end

local function OnMinimap(f)
	local p = f:GetParent()
	if p == Minimap or (MinimapBackdrop and p == MinimapBackdrop) then return true end
	for i = 1, f:GetNumPoints() do
		local _, rel = f:GetPoint(i)
		if rel == Minimap then return true end
	end
	return false
end

function E.IsLooseButton(f)
	if f:IsForbidden() or f:GetObjectType() ~= "Button" or f:IsProtected() then return false end
	if S.grabbed[f] or not LooseName(f:GetName()) then return false end
	for _, id in ipairs(BLIZZARD_BUTTONS) do if BlizzardButton(id) == f then return false end end
	local w, h = f:GetSize()
	if w < 20 or h < 20 or w > 48 or h > 48 or abs(w - h) > 8 then return false end
	return OnMinimap(f)
end

-- Runs once after login and after add-ons load, never every frame.
function E.ScanLoose()
	S.looseDirty = nil
	local seen, list = S.looseSeen, S.looseList
	local added
	local function try(f)
		if not seen[f] and E.IsLooseButton(f) then seen[f] = true; list[#list + 1] = f; added = true end
	end
	local function children(parent)
		if parent then
			for _, f in ipairs({ parent:GetChildren() }) do pcall(try, f) end
		end
	end
	children(Minimap)
	children(MinimapBackdrop)
	if EnumerateFrames then      -- buttons parented elsewhere but pinned to the minimap
		local f = EnumerateFrames()
		while f do
			pcall(try, f)
			f = EnumerateFrames(f)
		end
	end
	if added then tsort(list, function(a, b) return (a:GetName() or "") < (b:GetName() or "") end) end
end

--------------------------------------------------------------------------------
-- Add-on buttons: each add-on's minimap button goes on the bar only if you've
-- picked it (Pathway's setup asks, and asks again when a new one turns up);
-- the rest wait in the add-on list, the numbered button. Buttons made with
-- LibDBIcon join the list the library's own way; others Pathway lists itself.
--------------------------------------------------------------------------------
local function LooseLabel(b)
	local raw = b:GetName() or "?"
	local n = raw:gsub("[_%-]?[Mm]ini[Mm]ap[_%-]?[Bb]utton[%d]*$", ""):gsub("[_%-]?[Mm]ini[Mm]ap[_%-]?[Ii]con$", "")
		:gsub("[_%-]?[Mm]ap[Bb]utton$", ""):gsub("[_%-]?[Mm]ap[Ii]con$", ""):gsub("[_%-]?[Mm]ini[Mm]ap$", ""):gsub("^[_%-]+", "")
	n = n:gsub("(%l)(%u)", "%1 %2"):gsub("_", " ")
	return n ~= "" and n or raw
end
local function ButtonIcon(b)
	local t = b.icon or b.Icon
	if t and t.GetTexture then return t:GetTexture() end
	for _, r in ipairs({ b:GetRegions() }) do
		if r.GetObjectType and r:GetObjectType() == "Texture" and r:GetDrawLayer() == "ARTWORK" then
			local tex = r:GetTexture()
			if tex then return tex end
		end
	end
end
function E.AddonButtons()
	local out = {}
	local ldbi = E.LDBI()
	if ldbi then
		local ldb = _G.LibStub and _G.LibStub("LibDataBroker-1.1", true)
		for _, name in ipairs(ldbi:GetButtonList()) do
			local b = ldbi:GetMinimapButton(name)
			if b then
				local obj = ldb and ldb:GetDataObjectByName(name)
				out[#out + 1] = { key = name, label = name, icon = obj and obj.icon or ButtonIcon(b), button = b, kind = "ldb" }
			end
		end
	end
	if db.barOthers then
		if S.looseDirty then E.ScanLoose() end
		for _, b in ipairs(S.looseList) do
			local name = b:GetName()
			-- Pathway's own buttons are the bar's, not an add-on's to choose
			if not (type(name) == "string" and name:find("^PathwayMinimap")) then
				out[#out + 1] = { key = name, label = LooseLabel(b), icon = ButtonIcon(b), button = b, kind = "loose" }
			end
		end
	end
	tsort(out, function(a, b) return a.label:lower() < b.label:lower() end)
	return out
end
function E.OnBar(key) return ROOT.barPicks[key] and true or false end
function E.SetOnBar(key, on)
	ROOT.barPicks[key] = on and true or nil
	Later("barRefresh", E.RefreshBar, 0)
end

-- the add-on list (the numbered button), for a button made without LibDBIcon
local function ListLoose(it)
	S.looseListed = S.looseListed or {}
	if S.looseListed[it.key] then return true end
	local acf = AddonCompartmentFrame
	if not (acf and acf.RegisterAddon) then return false end
	local b = it.button
	local entry = { text = it.label, icon = it.icon, notCheckable = true, registerForAnyClick = true,
		func = function(_, input)
			local click = b:GetScript("OnClick")
			local mb = type(input) == "table" and input.buttonName or (type(input) == "string" and input) or "LeftButton"
			if click then pcall(click, b, mb) end
		end,
		funcOnEnter = function(owner)
			local enter = b:GetScript("OnEnter")
			if enter then pcall(enter, owner or b) end
		end,
		funcOnLeave = function() if GameTooltip then GameTooltip:Hide() end end }
	local ok = pcall(acf.RegisterAddon, acf, entry)
	if ok then S.looseListed[it.key] = entry end
	return ok
end
local function UnlistLoose(it)
	local entry = S.looseListed and S.looseListed[it.key]
	local acf = AddonCompartmentFrame
	if not (entry and acf) then return end
	S.looseListed[it.key] = nil
	local reg = acf.registeredAddons
	if type(reg) == "table" then
		for i = #reg, 1, -1 do if reg[i] == entry then table.remove(reg, i) end end
		if acf.UpdateDisplay then pcall(acf.UpdateDisplay, acf) end
	end
end

-- a button seen for the first time, once setup is done: ask where it goes
function E.NewButton(it, onBar)
	if ROOT.seenButtons[it.key] then return end
	ROOT.seenButtons[it.key] = true
	local PW = Pathway
	if onBar or not (PW and PW.Notify and PW.db and PW.SetupDone and PW:SetupDone()) then return end
	PW:Notify({ key = "barpick:" .. it.key, kind = "info", icon = it.icon,
		text = format(L["%s has a minimap button"], it.label),
		sub = L["It waits in your add-on list (the numbered button)."],
		action = { L["On the bar"], function() E.SetOnBar(it.key, true) end } })
end

function E.MarkButtonsSeen(items)
	for _, it in ipairs(items) do
		ROOT.seenButtons[it.key] = true
		if Pathway and Pathway.ClearNote then Pathway:ClearNote("barpick:" .. it.key) end
	end
end

function E.QueueLooseScan(delay)
	S.looseDirty = true
	if S.ready then Later("looseScan", E.RefreshBar, delay or 1) end
end

function E.WantBar()
	if db.bar == "OFF" or not S.mapShown then return false end
	if db.bar == "AUTO" then return (S.clusterHidden or S.radarEmbedded) and true or false end
	return true
end

-- kind: nil for Blizzard's buttons, "ldb" for LibDBIcon, "loose" for other add-ons' own buttons
function E.Grab(b, kind)
	if S.grabbed[b] then return end
	local st = { parent = b:GetParent(), scale = b:GetScale(), level = b:GetFrameLevel(), kind = kind, points = {} }
	for i = 1, b:GetNumPoints() do st.points[i] = { b:GetPoint(i) } end
	if kind then
		-- Add-ons re-anchor their buttons around the minimap; mute that while docked.
		st.sp, st.cap = rawget(b, "SetPoint"), rawget(b, "ClearAllPoints")
		b.SetPoint, b.ClearAllPoints = noop, noop
	end
	if kind == "ldb" then
		st.alpha = b:GetAlpha()
		b:SetAlpha(1)
	end
	S.grabbed[b] = st
	E.ClusterGives(b)
	if not S.hookedButtons[b] then
		S.hookedButtons[b] = true
		b:HookScript("OnShow", S.queueLayout)
		b:HookScript("OnHide", S.queueLayout)
		if kind ~= "ldb" then b:HookScript("OnSizeChanged", S.queueLayout) end
		-- a button dragged by hand snaps back into its slot
		if kind == "loose" then b:HookScript("OnDragStop", S.queueLayout) end
	end
	b:SetParent(S.bar)
	b:SetFrameLevel(S.bar:GetFrameLevel() + 1)
end

function E.Release(b)
	local st = S.grabbed[b]
	if not st then return end
	S.grabbed[b] = nil
	if S.inList and S.inList[b] then S.inList[b] = nil; b:Show() end
	if st.kind then b.SetPoint, b.ClearAllPoints = st.sp, st.cap end
	if st.kind == "ldb" then b:SetAlpha(st.alpha or 1) end
	b:SetParent(st.parent)
	if st.level then b:SetFrameLevel(st.level) end
	b:SetScale(st.scale)
	local M = MT(b)
	M.ClearAllPoints(b)
	for _, p in ipairs(st.points) do M.SetPoint(b, unpack(p)) end
	local ldbi = st.kind == "ldb" and E.LDBI()
	if ldbi and b.gmName then ldbi:Refresh(b.gmName) end
	E.ClusterTakesBack(b)
end

function E.RefreshBar()
	if not S.bar then return end
	local list = S.barList
	wipe(list)
	if E.WantBar() then
		S.launcher:Hide()                      -- Pathway's button carries this menu
		local blizzard = db.barBlizzard and S.clusterHidden
		for _, id in ipairs(BLIZZARD_BUTTONS) do
			local b = BlizzardButton(id)
			if b then
				if blizzard then E.Grab(b); list[#list + 1] = b else E.Release(b) end
			end
		end
		-- every add-on's button: on the bar if you picked it, else in the add-on list
		-- (and on the bar after all where the game has no add-on list)
		S.inList = S.inList or {}
		local ldbi = E.LDBI()
		local useList = db.barCompartment ~= false and AddonCompartmentFrame and true or false
		for _, it in ipairs(E.AddonButtons()) do
			local b = it.button
			local onBar = E.OnBar(it.key) or not useList
			if not onBar then
				local listed = false
				if it.kind == "ldb" then
					if ldbi and ldbi.AddButtonToCompartment then
						if not (ldbi.IsButtonInCompartment and ldbi:IsButtonInCompartment(it.key)) then pcall(ldbi.AddButtonToCompartment, ldbi, it.key) end
						listed = not ldbi.IsButtonInCompartment or ldbi:IsButtonInCompartment(it.key) and true or false
					end
				else
					listed = ListLoose(it)
				end
				if not listed then onBar = true end
			elseif it.kind == "ldb" then
				if ldbi and ldbi.RemoveButtonFromCompartment and ldbi.IsButtonInCompartment and ldbi:IsButtonInCompartment(it.key) then
					pcall(ldbi.RemoveButtonFromCompartment, ldbi, it.key)
				end
			else
				UnlistLoose(it)
			end
			if it.kind == "ldb" then b.gmName = it.key end
			E.Grab(b, it.kind)
			if onBar then
				if S.inList[b] then S.inList[b] = nil; b:Show() end
				list[#list + 1] = b
			else
				S.inList[b] = true
				if not b.gmListHook then
					b.gmListHook = true
					b:HookScript("OnShow", function(self) if S.inList[self] and S.grabbed[self] then self:Hide() end end)
				end
				b:Hide()
			end
			E.NewButton(it, onBar)
		end
		-- Pathway's own buttons always sit on the bar
		if S.looseDirty then E.ScanLoose() end
		for _, b in ipairs(S.looseList) do
			local name = b:GetName()
			if type(name) == "string" and name:find("^PathwayMinimap") then E.Grab(b, "loose"); list[#list + 1] = b
			elseif not db.barOthers then E.Release(b) end
		end
		-- Pathway's own button always leads the bar
		local pw, notes = _G.PathwayMinimapPathway, nil
		for i, b in ipairs(list) do
			if b == notes then table.remove(list, i); table.insert(list, 1, notes); break end
		end
		for i, b in ipairs(list) do
			if b == pw then table.remove(list, i); table.insert(list, 1, pw); break end
		end
		S.bar:Show()
		S.bar:SetAlpha(((db.barMouseover and not S.hovered) or E.Calm()) and 0 or 1)
		E.LayoutBar()
	else
		local hadIndicator = MinimapCluster and S.grabbed[MinimapCluster.IndicatorFrame]
		for b in pairs(S.grabbed) do E.Release(b) end
		if hadIndicator and MiniMapIndicatorFrame_UpdatePosition then MiniMapIndicatorFrame_UpdatePosition() end
		S.bar:Hide()
	end
end

function E.Slot(i)
	local slot = S.slots[i]
	if not slot then
		slot = CreateFrame("Frame", nil, S.bar)
		S.slots[i] = slot
	end
	return slot
end

-- Blizzard's indicator holds the mail and crafting-order icons; it stays shown
-- when both are hidden, so it only counts when one of them shows
local function IndicatorEmpty(b)
	local mc = MinimapCluster
	if not (mc and b == mc.IndicatorFrame) then return false end
	local any = false
	for _, child in ipairs({ b:GetChildren() }) do
		if not S.hookedButtons[child] then
			S.hookedButtons[child] = true
			child:HookScript("OnShow", S.queueLayout)
			child:HookScript("OnHide", S.queueLayout)
		end
		if child:IsShown() then any = true end
	end
	return not any
end

function E.LayoutBar()
	local bar = S.bar
	if not (bar and bar:IsShown()) then return end
	local size, gap, side = db.barSize, db.barSpacing, db.barSide
	local step = size + gap
	local vertical = side == "LEFT" or side == "RIGHT"
	local edge = vertical and S.map:GetHeight() or S.map:GetWidth()
	local per = max(1, floor((edge + gap) / step))
	local n = 0
	for _, b in ipairs(S.barList) do
		local w, h = b:GetSize()
		if b:IsShown() and w > 1 and h > 1 and not IndicatorEmpty(b) then
			local a, c = n % per, floor(n / per)
			n = n + 1
			local slot = E.Slot(n)
			slot:SetSize(size, size)
			slot:ClearAllPoints()
			if side == "TOP" then slot:SetPoint("BOTTOMRIGHT", bar, "BOTTOMRIGHT", -a * step, c * step)
			elseif side == "BOTTOM" then slot:SetPoint("TOPRIGHT", bar, "TOPRIGHT", -a * step, -c * step)
			elseif side == "LEFT" then slot:SetPoint("TOPRIGHT", bar, "TOPRIGHT", -c * step, -a * step)
			else slot:SetPoint("TOPLEFT", bar, "TOPLEFT", c * step, -a * step) end
			local s = size / max(w, h)
			if abs(b:GetScale() - s) > 0.001 then b:SetScale(s) end
			local M = MT(b)
			M.ClearAllPoints(b)
			M.SetPoint(b, "CENTER", slot, "CENTER", 0, 0)
		end
	end
	local along, across = max(1, min(n, per) * step - gap), max(1, ceil(n / per) * step - gap)
	if vertical then bar:SetSize(across, along) else bar:SetSize(along, across) end
	bar:ClearAllPoints()
	if S.round then   -- centred on the circle
		if side == "TOP" then bar:SetPoint("BOTTOM", S.map, "TOP", 0, 4)
		elseif side == "BOTTOM" then bar:SetPoint("TOP", S.map, "BOTTOM", 0, -4)
		elseif side == "LEFT" then bar:SetPoint("RIGHT", S.map, "LEFT", -4, 0)
		else bar:SetPoint("LEFT", S.map, "RIGHT", 4, 0) end
	elseif side == "TOP" then bar:SetPoint("BOTTOMRIGHT", S.map, "TOPRIGHT", 0, 4)
	elseif side == "BOTTOM" then bar:SetPoint("TOPRIGHT", S.map, "BOTTOMRIGHT", 0, -4)
	elseif side == "LEFT" then bar:SetPoint("TOPRIGHT", S.map, "TOPLEFT", -4, 0)
	else bar:SetPoint("TOPLEFT", S.map, "TOPRIGHT", 4, 0) end
	if S.eventButton and S.eventButton:IsShown() then E.PlaceEventButton() else E.PlaceNotes() end
end

--------------------------------------------------------------------------------
-- Holiday and event button: on days with a holiday or world event a small
-- button pops up on the left of the map. Hover for details, click for the
-- calendar, right-click to hide it for a day, a week, a month or for good.
--------------------------------------------------------------------------------
function E.SetupEventButton()
	local b = CreateFrame("Button", nil, S.map)
	b:SetSize(28, 28)
	b:SetFrameLevel(9000)
	b:RegisterForClicks("LeftButtonUp", "RightButtonUp")
	b:Hide()
	local bg = b:CreateTexture(nil, "BACKGROUND")
	bg:SetTexture(CIRCLE_MASK)
	bg:SetVertexColor(0, 0, 0, 0.8)
	bg:SetAllPoints()
	b.icon = b:CreateTexture(nil, "ARTWORK")
	b.icon:SetPoint("CENTER")
	b.icon:SetSize(22, 22)
	local mask = b:CreateMaskTexture()
	mask:SetTexture(CIRCLE_MASK, "CLAMPTOBLACKADDITIVE", "CLAMPTOBLACKADDITIVE")
	mask:SetAllPoints(b.icon)
	b.icon:AddMaskTexture(mask)
	b.glow = b:CreateTexture(nil, "OVERLAY")
	b.glow:SetTexture(CIRCLE_MASK)
	b.glow:SetVertexColor(GLOW_COLOR[1], GLOW_COLOR[2], GLOW_COLOR[3], 1)
	b.glow:SetBlendMode("ADD")
	b.glow:SetPoint("CENTER")
	b.glow:SetSize(34, 34)
	b.glow:SetAlpha(0)
	local pulse = b.glow:CreateAnimationGroup()
	pulse:SetLooping("BOUNCE")
	local fade = pulse:CreateAnimation("Alpha")
	fade:SetFromAlpha(0)
	fade:SetToAlpha(0.55)
	fade:SetDuration(0.9)
	fade:SetSmoothing("IN_OUT")
	b.pulse = pulse
	b:SetScript("OnClick", function(self, button)
		if button == "RightButton" then
			HideTooltip()
			E.EventMenu(self)
		elseif ToggleCalendar then
			ToggleCalendar()
		end
	end)
	b:SetScript("OnEnter", function(self) E.EventTooltip(self) end)
	b:SetScript("OnLeave", HideTooltip)
	S.eventButton, S.eventList = b, {}
	if _G.C_Calendar and _G.C_Calendar.OpenCalendar then pcall(_G.C_Calendar.OpenCalendar) end
	-- the day can change while you play
	C_Timer.NewTicker(600, function()
		local day = E.Today()
		if day ~= S.eventDay and _G.C_Calendar and _G.C_Calendar.OpenCalendar then pcall(_G.C_Calendar.OpenCalendar) end
		E.ReadEvents()
	end)
end

-- Right-click: hide the button for a while, or for good (the setting brings it back).
function E.EventMenu(owner)
	MenuUtil.CreateContextMenu(owner, function(_, root)
		root:SetTag("MENU_GOODMAP_EVENTS")
		root:CreateTitle(L["Holiday and event button"])
		root:CreateButton(L["Hide for 1 day"], function() E.HideEvents(1) end)
		for _, days in ipairs({ 7, 30 }) do
			root:CreateButton(format(L["Hide for %d days"], days), function() E.HideEvents(days) end)
		end
		root:CreateButton(L["Don't show it again"], function()
			E.Set("eventButton", false)
			Print(L["The holiday button is off. You can turn it back on in GoodMap's settings, under Navigation."])
		end)
	end)
end

-- The date (realm calendar) a number of days from today, as "YYYY-MM-DD".
function E.DayPlus(days)
	local _, t = E.Today()
	if not t then return end
	return date("%Y-%m-%d", time({ year = t.year, month = t.month, day = t.monthDay + days, hour = 12 }))
end

function E.HideEvents(days)
	ROOT.eventsHiddenUntil = E.DayPlus(days)
	E.UpdateEventButton()
end

function E.EventsHidden()
	local day = S.eventDay
	if not day then return false end
	if ROOT.eventsHidden == day then return true end               -- 1.3.0-1.3.1: hidden for the rest of today
	local untilDay = ROOT.eventsHiddenUntil
	return type(untilDay) == "string" and day < untilDay
end

function E.Today()
	local DT = _G.C_DateAndTime
	local t = DT and DT.GetCurrentCalendarTime and DT.GetCurrentCalendarTime()
	if t and t.year then return format("%04d-%02d-%02d", t.year, t.month, t.monthDay), t end
end

-- Today's holidays from the calendar (realm time). Titles can be secret during
-- some restricted moments: those are skipped.
function E.ReadEvents()
	local list, C = S.eventList, _G.C_Calendar
	if not list then return end
	wipe(list)
	local day, now = E.Today()
	S.eventDay = day
	if db.eventButton and day and C and C.GetMonthInfo and C.GetNumDayEvents and C.GetDayEvent then
		local ok, mi = pcall(C.GetMonthInfo, 0)
		if ok and type(mi) == "table" and mi.year then
			local offset = (now.year - mi.year) * 12 + (now.month - mi.month)
			local okN, n = pcall(C.GetNumDayEvents, offset, now.monthDay)
			local seen = {}
			for i = 1, (okN and type(n) == "number" and n or 0) do
				local okE, e = pcall(C.GetDayEvent, offset, now.monthDay, i)
				if okE and type(e) == "table" and not issecret(e.title) and not issecret(e.calendarType)
					and e.calendarType == "HOLIDAY" and type(e.title) == "string" and not seen[e.title] then
					seen[e.title] = true
					list[#list + 1] = e
				end
			end
		end
	end
	E.UpdateEventButton()
end

function E.UpdateEventButton()
	local b = S.eventButton
	if not b then return end
	local list = S.eventList
	local show = db.eventButton and #list > 0 and S.mapShown and S.mode == "NORMAL" and not S.editMode
		and not E.EventsHidden() and not E.Busy()
	if not show then
		if b:IsShown() then b.pulse:Stop(); b:Hide(); E.PlaceNotes() end
		return
	end
	local icon = list[1].iconTexture
	b.icon:SetTexture((icon and not issecret(icon)) and icon or "Interface\\Icons\\INV_Misc_Note_06")
	E.PlaceEventButton()
	if not b:IsShown() then
		b:Show()
		b:SetAlpha(E.Calm() and 0 or 1)
		if S.eventPulsed ~= S.eventDay then              -- a few pulses, once a day
			S.eventPulsed = S.eventDay
			b.pulse:Play()
			C_Timer.After(8, function() b.pulse:Stop(); b.glow:SetAlpha(0) end)
		end
	end
end

-- The buttons beside the map sit a layer above it: the Blizzard minimap it replaces is only
-- made invisible (some of its frames can't have their mouse turned off), and anything left
-- over them would take their clicks.
E.SIDE_STRATA = "HIGH"
function E.PlaceEventButton()
	local b = S.eventButton
	b:SetFrameStrata(E.SIDE_STRATA); b:SetFrameLevel(50)
	b:ClearAllPoints()
	local bar = S.bar
	if bar and bar:IsShown() and db.barSide == "LEFT" then b:SetPoint("RIGHT", bar, "LEFT", -4, 0)
	else b:SetPoint("RIGHT", S.map, "LEFT", -4, 0) end
	E.PlaceNotes()
end

-- Pathway's notification bell: just under the holiday button, or in its place
function E.PlaceNotes()
	local n = _G.PathwayNotesButton
	if not (n and S.map) then return end
	if n:GetParent() ~= S.map then n:SetParent(S.map) end
	n:SetFrameStrata(E.SIDE_STRATA)
	n:SetFrameLevel(50)
	n:ClearAllPoints()
	local eb = S.eventButton
	if eb and eb:IsShown() then
		n:SetPoint("TOP", eb, "BOTTOM", 0, -6)
	else
		local bar = S.bar
		if bar and bar:IsShown() and db.barSide == "LEFT" then n:SetPoint("RIGHT", bar, "LEFT", -4, 0)
		else n:SetPoint("RIGHT", S.map, "LEFT", -4, 0) end
	end
end

function E.EventTooltip(owner)
	GameTooltip:SetOwner(owner, "ANCHOR_LEFT")
	GameTooltip:SetText(L["Today"])
	local _, now = E.Today()
	local nowT = now and time({ year = now.year, month = now.month, day = now.monthDay, hour = now.hour, min = now.minute })
	for _, e in ipairs(S.eventList) do
		local left = ""
		local t = e.endTime
		if nowT and type(t) == "table" and t.year then
			local secs = time({ year = t.year, month = t.month, day = t.monthDay, hour = t.hour, min = t.minute }) - nowT
			if secs > 0 then
				local span = _G.SecondsToTime and _G.SecondsToTime(secs, true, true, 1) or E.Clock(secs / 60)
				left = format(L["Ends in %s"], span)
			end
		end
		GameTooltip:AddDoubleLine(e.title, left, 1, 0.82, 0, 0.8, 0.8, 0.8)
	end
	GameTooltip:AddLine(" ")
	GameTooltip:AddLine(L["Click: calendar"], 1, 1, 1)
	GameTooltip:AddLine(L["Right-click: hide for a while"], 1, 1, 1)
	GameTooltip:Show()
end

