-- Player houses don't exist on WoW: Forever; these keep the callers simple.
--------------------------------------------------------------------------------
local function NOOP() end
function E.HouseMode() return "OFF" end
E.HouseCheck, E.UpdateHouseView, E.SetupHouse, E.HouseLayout = NOOP, NOOP, NOOP, NOOP
E.HouseZoom, E.HouseTick, E.HouseHover, E.HouseSetZoom = NOOP, NOOP, NOOP, NOOP
E.HouseSave, E.HouseInfoUpdated, E.HouseForget = NOOP, NOOP, NOOP
function E.HouseTitle() return "" end
function E.HouseStats() return 0, 0, 0 end

--------------------------------------------------------------------------------
-- Group map pings and markers. Hold the mark key and click the map (or use
-- Ctrl + right-click > Ping here) and everyone in your group who uses GoodMap
-- sees it. Markers use the raid icons; in a raid only the leader and
-- assistants can place them, like world markers. Add-ons can't place markers
-- in the world itself, so these live on the map.
--   P,cont,x,y          ping at a world position
--   M,icon,cont,x,y     raid marker icon (1-8) at a world position
--   C                   clear all markers
--------------------------------------------------------------------------------
local PREFIX = "GoodMap"
local RAID_ICON = "Interface\\TargetingFrame\\UI-RaidTargetingIcon_%d"

function E.SetupGroup()
	S.markers, S.pings, S.lastPing = {}, {}, {}
	local CI = _G.C_ChatInfo
	if CI and CI.RegisterAddonMessagePrefix then pcall(CI.RegisterAddonMessagePrefix, PREFIX) end
end

function GoodMap_MarkKey(keystate)
	if not S.ready then return end
	local down = keystate ~= "up"
	if (S.markKey or false) == down then return end
	S.markKey = down or nil
	if S.mapShown then E.ApplyMouse() end
	if down and S.mapShown and S.map:IsMouseOver() then
		GameTooltip:SetOwner(S.map, "ANCHOR_CURSOR")
		GameTooltip:SetText(E.MarkLabel(db.markClick))
		GameTooltip:Show()
	elseif not down and GameTooltip:GetOwner() == S.map then
		GameTooltip:Hide()
	end
end

function E.MarkerName(i)
	return format("|T" .. RAID_ICON .. ":0|t %s", i, _G["RAID_TARGET_" .. i] or tostring(i))
end

function E.MarkLabel(what)
	local marker = E.MarkerName(tonumber(db.markIcon) or 1)
	if what == "MARKER" then return format(L["Click the map: %s"], marker) end
	if what == "BOTH" then return format(L["Click the map: ping and %s"], marker) end
	return L["Click the map: ping"]
end

function E.GroupChannel()
	if IsInGroup and _G.LE_PARTY_CATEGORY_INSTANCE and IsInGroup(_G.LE_PARTY_CATEGORY_INSTANCE) then return "INSTANCE_CHAT" end
	if IsInRaid() then return "RAID" end
	if IsInGroup and IsInGroup() then return "PARTY" end
end

function E.SendGroup(msg)
	local CI, chat = _G.C_ChatInfo, E.GroupChannel()
	if not (chat and CI and CI.SendAddonMessage) then return end
	if CI.InChatMessagingLockdown and CI.InChatMessagingLockdown() then return end
	pcall(CI.SendAddonMessage, PREFIX, msg, chat)
end

-- In a raid only the leader and assistants place markers; in a party anyone can.
function E.CanMark(unit)
	if not IsInRaid() then return true end
	return (UnitIsGroupLeader(unit) or UnitIsGroupAssistant(unit)) and true or false
end

function E.MarkAt(mapID, x, y, what, icon)
	what = what or db.markClick
	local cont, wx, wy = E.MapToWorld(mapID, x, y)
	if not cont then return end
	local me = UnitName("player")
	local placed, marker
	if what == "PING" or what == "BOTH" then
		local now = GetTime()
		if now - (S.lastPing[me] or 0) >= 0.5 then
			S.lastPing[me] = now
			E.SendGroup(format("P,%d,%.1f,%.1f", cont, wx, wy))
			E.ShowPing(cont, wx, wy, me)
			placed = true
		end
	end
	if what == "MARKER" or what == "BOTH" then
		if not E.CanMark("player") then Print(L["In a raid, only the leader and assistants can place markers."]) return end
		icon = icon or tonumber(db.markIcon) or 1
		E.SendGroup(format("M,%d,%d,%.1f,%.1f", icon, cont, wx, wy))
		E.SetMarker(icon, cont, wx, wy, me)
		placed, marker = true, icon
	end
	if not placed then return end
	if db.worldPins then E.PinInWorld(mapID, x, y) end
	E.ShareInChat(mapID, x, y, marker)
end

--------------------------------------------------------------------------------
-- In the world: a ping or marker can also become your map pin (the game allows
-- one per player), which shows its marker in the world with the distance to
-- it. A map pin link in chat reaches players who don't use GoodMap: clicking it
-- puts the spot on their map and in their world too. Map pins can't be placed
-- in dungeons, raids and battlegrounds.
--------------------------------------------------------------------------------
function E.CanPin(mapID)
	return (mapID and _G.UiMapPoint and C_Map.CanSetUserWaypointOnMap and C_Map.CanSetUserWaypointOnMap(mapID)) and true or false
end

function E.PinInWorld(mapID, x, y)
	if not E.CanPin(mapID) then return false end
	if not pcall(C_Map.SetUserWaypoint, _G.UiMapPoint.CreateFromCoordinates(mapID, x, y)) then return false end
	local ST = _G.C_SuperTrack
	if ST and ST.SetSuperTrackedUserWaypoint then pcall(ST.SetSuperTrackedUserWaypoint, true) end
	return true
end

-- A map pin link for chat. Unless your map pin is already there (keep), your own
-- pin is put back the way it was afterwards.
function E.PinLink(mapID, x, y, keep)
	if not (E.CanPin(mapID) and C_Map.GetUserWaypointHyperlink) then return end
	if keep then return C_Map.GetUserWaypointHyperlink() end
	local ST = _G.C_SuperTrack
	local had = C_Map.HasUserWaypoint and C_Map.HasUserWaypoint() and C_Map.GetUserWaypoint()
	local tracked = ST and ST.IsSuperTrackingUserWaypoint and ST.IsSuperTrackingUserWaypoint()
	if not pcall(C_Map.SetUserWaypoint, _G.UiMapPoint.CreateFromCoordinates(mapID, x, y)) then return end
	local link = C_Map.GetUserWaypointHyperlink()
	if had then pcall(C_Map.SetUserWaypoint, had) elseif C_Map.ClearUserWaypoint then C_Map.ClearUserWaypoint() end
	if tracked and ST.SetSuperTrackedUserWaypoint then pcall(ST.SetSuperTrackedUserWaypoint, true) end
	return link
end

-- Your group's chat, or /say when you're not in a group. Each post comes from
-- your own click, and they're spaced out so a burst of clicks doesn't flood chat.
function E.ShareInChat(mapID, x, y, icon)
	if not db.shareChat then return end
	local now = GetTime()
	if now - (S.lastShare or -10) < 3 then return end
	local CI = _G.C_ChatInfo
	if CI and CI.InChatMessagingLockdown and CI.InChatMessagingLockdown() then return end
	local link = E.PinLink(mapID, x, y, db.worldPins)
	if type(link) ~= "string" or link == "" then return end
	S.lastShare = now
	local send = (CI and CI.SendChatMessage) or _G.SendChatMessage
	if send then pcall(send, icon and format("{rt%d} %s", icon, link) or link, E.GroupChannel() or "SAY") end
end

-- A group member's ping: the map it's on (your zone first, then the map you're
-- looking at, then the maps around them), as your map pin.
function E.PinFromWorld(cont, wx, wy)
	local tried = {}
	local function find(id)
		while id and id > 0 and not tried[id] do
			tried[id] = true
			local x, y = E.WorldToMap(id, cont, wx, wy)
			if x and E.CanPin(id) then return id, x, y end
			local info = C_Map.GetMapInfo(id)
			id = info and info.parentMapID
		end
	end
	local id, x, y = find(S.playerMap)
	if not id and S.map then id, x, y = find(S.map:GetMapID()) end
	if id then return E.PinInWorld(id, x, y) end
	return false
end

function E.ClearMarkers(fromGroup)
	if not fromGroup then
		if not E.CanMark("player") then Print(L["In a raid, only the leader and assistants can place markers."]) return end
		E.SendGroup("C")
	end
	for i, f in pairs(S.markers) do f.cont = nil; E.FreeCanvasPin(f); S.markers[i] = nil end
end

function E.CHAT_MSG_ADDON(prefix, text, _, sender)
	if issecret(prefix) or prefix ~= PREFIX or issecret(text) or issecret(sender) or type(text) ~= "string" then return end
	local name = _G.Ambiguate and _G.Ambiguate(sender, "none") or sender
	if name == UnitName("player") then return end              -- our own, already shown
	local kind, a, b, c, d = strsplit(",", text)
	if kind == "P" then
		local now = GetTime()
		if not db.groupPings or now - (S.lastPing[name] or 0) < 0.4 then return end
		S.lastPing[name] = now
		a, b, c = tonumber(a), tonumber(b), tonumber(c)
		if a and b and c then
			E.ShowPing(a, b, c, name)
			if db.groupPinsWorld then E.PinFromWorld(a, b, c) end
		end
	elseif kind == "M" then
		local icon, cont, wx, wy = tonumber(a), tonumber(b), tonumber(c), tonumber(d)
		if icon and icon >= 1 and icon <= 8 and cont and wx and wy and E.CanMark(name) then E.SetMarker(floor(icon), cont, wx, wy, name) end
	elseif kind == "C" then
		if E.CanMark(name) then E.ClearMarkers(true) end
	end
end

function E.GROUP_LEFT()
	if S.markers then E.ClearMarkers(true) end
end

-- Group pins show what they are when you hover them (inside the round map's edge).
local function GroupPinTip(f)
	if not f.nx or (S.round and not E.InView(f.nx, f.ny)) then return end
	GameTooltip:SetOwner(f, "ANCHOR_RIGHT")
	if f.icon then
		GameTooltip:SetText(E.MarkerName(f.icon))
		if f.who then GameTooltip:AddLine(format(L["Placed by %s"], f.who), 1, 1, 1) end
	else
		GameTooltip:SetText(format(L["Ping from %s"], f.who or "?"))
	end
	GameTooltip:Show()
end

function E.SetMarker(icon, cont, wx, wy, who)
	local f = S.markers[icon]
	if not f then
		f = E.CanvasPin("marker" .. icon, E.PinLevel("PIN_FRAME_LEVEL_TOPMOST", 2100) + 1)
		if not f.tex then
			f:SetSize(18, 18)
			f.tex = f:CreateTexture(nil, "OVERLAY")
			f.tex:SetSize(18, 18)
			f.tex:SetPoint("CENTER")
			f.tex:SetTexture(format(RAID_ICON, icon))
			Mask(f.tex)
			f.icon = icon
			Hoverable(f, GroupPinTip)
		end
		S.markers[icon] = f
	end
	f.who = who
	f.cont, f.wx, f.wy = cont, wx, wy
	E.PlaceGroupPin(f)
end

-- A ping: a dot in the sender's class color with a ripple, and their name, for a few seconds.
function E.ShowPing(cont, wx, wy, who)
	if not S.mapShown or S.houseActive then return end
	local f = E.CanvasPin("ping", E.PinLevel("PIN_FRAME_LEVEL_TOPMOST", 2100) + 2)
	if not f.dot then
		f:SetSize(16, 16)
		Hoverable(f, GroupPinTip)
		f.dot = f:CreateTexture(nil, "OVERLAY")
		f.dot:SetTexture(CIRCLE_MASK)
		f.dot:SetSize(8, 8)
		f.dot:SetPoint("CENTER")
		f.ring = f:CreateTexture(nil, "ARTWORK")
		f.ring:SetTexture(CIRCLE_MASK)
		f.ring:SetSize(40, 40)
		f.ring:SetPoint("CENTER")
		f.ring:SetBlendMode("ADD")
		local ag = f.ring:CreateAnimationGroup()
		ag:SetLooping("REPEAT")
		local grow = ag:CreateAnimation("Scale")
		grow:SetScaleFrom(0.15, 0.15)
		grow:SetScaleTo(1, 1)
		grow:SetDuration(0.9)
		local fade = ag:CreateAnimation("Alpha")
		fade:SetFromAlpha(0.8)
		fade:SetToAlpha(0)
		fade:SetDuration(0.9)
		f.anim = ag
		f.label = f:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
		f.label:SetPoint("TOP", f.dot, "BOTTOM", 0, -3)
		Mask(f.dot); Mask(f.ring)
	end
	local r, g, b = 1, 0.82, 0
	local _, class = UnitClass(who)
	if who == UnitName("player") then r, g, b = E.ClassColor()
	elseif class and RAID_CLASS_COLORS and RAID_CLASS_COLORS[class] then local c = RAID_CLASS_COLORS[class]; r, g, b = c.r, c.g, c.b end
	f.dot:SetVertexColor(r, g, b, 1)
	f.ring:SetVertexColor(r, g, b, 1)
	f.label:SetText(who or "")
	f.who = who
	f.cont, f.wx, f.wy = cont, wx, wy
	S.pings[f] = true
	E.PlaceGroupPin(f)
	f.anim:Play()
	if who ~= UnitName("player") and _G.SOUNDKIT and _G.SOUNDKIT.MAP_PING then PlaySound(_G.SOUNDKIT.MAP_PING) end
	f.token = (f.token or 0) + 1
	local token = f.token
	C_Timer.After(4, function()
		if f.token ~= token then return end
		f.anim:Stop()
		S.pings[f] = nil
		E.FreeCanvasPin(f)
	end)
end

function E.PlaceGroupPin(f)
	local x, y
	if S.map and not S.houseActive then x, y = E.WorldToMap(S.map:GetMapID(), f.cont, f.wx, f.wy) end
	E.PlaceCanvasPin(f, x, y)
end

function E.RefreshGroupPins()
	if not S.markers then return end
	for _, f in pairs(S.markers) do E.PlaceGroupPin(f) end
	for f in pairs(S.pings) do E.PlaceGroupPin(f) end
end

--------------------------------------------------------------------------------
-- Edit Mode: GoodMap shows a highlight you can drag; it snaps to the screen's
-- edges and center lines.
--------------------------------------------------------------------------------
function E.SetupEditMode()
	local box = CreateFrame("Frame", nil, S.map)
	box:SetAllPoints(S.map)
	box:SetFrameLevel(9800)
	box:EnableMouse(true)
	box:RegisterForDrag("LeftButton")
	box:Hide()
	box.bg = box:CreateTexture(nil, "BACKGROUND")
	box.bg:SetAllPoints()
	box.bg:SetColorTexture(0.1, 0.55, 1, 0.3)
	Mask(box.bg)
	box.label = box:CreateFontString(nil, "OVERLAY", "GameFontHighlightLarge")
	box.label:SetPoint("CENTER")
	box.label:SetText(TITLE)
	box:SetScript("OnDragStart", function()
		S.editDragging = true
		S.map:StartMoving()
	end)
	box:SetScript("OnDragStop", E.EditDrop)
	S.editBox = box
end

function E.ApplyEditMode()
	local box = S.editBox
	if not box then return end
	if S.editDragging and not S.editMode then E.EditDrop() end
	box.label:SetText(TITLE)
	box:SetShown(S.editMode and true or false)
	E.UpdateEventButton()
end

function E.EditDrop()
	if not S.editDragging then return end
	S.editDragging = false
	local map = S.map
	map:StopMovingOrSizing()
	map:SetUserPlaced(false)
	local s = map:GetScale()
	local l, b, w, h = map:GetRect()
	if not l then E.ApplyPosition() return end
	local W, H = UIParent:GetWidth(), UIParent:GetHeight()
	local L0, B0, R0, T0 = l * s, b * s, (l + w) * s, (b + h) * s       -- screen units
	local snap, dx, dy = 12, 0, 0
	if abs(L0) < snap then dx = -L0 elseif abs(W - R0) < snap then dx = W - R0
	elseif abs((L0 + R0) / 2 - W / 2) < snap then dx = W / 2 - (L0 + R0) / 2 end
	if abs(B0) < snap then dy = -B0 elseif abs(H - T0) < snap then dy = H - T0
	elseif abs((B0 + T0) / 2 - H / 2) < snap then dy = H / 2 - (B0 + T0) / 2 end
	db.posX, db.posY = (L0 + dx) / s, (T0 + dy) / s
	E.ApplyPosition()
end

--------------------------------------------------------------------------------
-- Context menu, presets, slash command, addon compartment, dialogs
--------------------------------------------------------------------------------
function E.ShowMenu(owner, x, y)
	local mapID = x and S.map:GetMapID()
	MenuUtil.CreateContextMenu(owner, function(_, root)
		root:SetTag("MENU_GOODMAP")
		root:CreateTitle(TITLE)
		local function check(text, key)
			root:CreateCheckbox(text, function() return db[key] end, function() E.Set(key, not db[key]) end)
		end
		local mode = root:CreateButton(L["Mode"])
		local modes = E.ModeList()
		for i = 1, #modes, 2 do
			local key = modes[i]
			mode:CreateRadio(modes[i + 1], function() return db.mode == key end, function() E.Set("mode", key) end)
		end
		if mapID then
			root:CreateButton(L["Ping here"], function() E.MarkAt(mapID, x, y, "PING") end)
			local mark = root:CreateButton(L["Marker here"])
			for i = 1, 8 do mark:CreateButton(E.MarkerName(i), function() E.MarkAt(mapID, x, y, "MARKER", i) end) end
			if next(S.markers) then root:CreateButton(L["Clear markers"], function() E.ClearMarkers() end) end
			root:CreateDivider()
		end
		root:CreateButton(L["Farming routes"], function() E.ShowRoutes() end)
		if S.farm then root:CreateButton(L["Stop route"], function() E.StopRoute() end) end
		check(L["Lock"], "locked")
		check(L["Follow me"], "follow")
		check(L["Minimap radar"], "radar")
		check(L["Replace the Blizzard minimap"], "replaceMinimap")
		root:CreateCheckbox(SHOW_BATTLEFIELDMINIMAP_PLAYERS or L["Show players"],
			function() return BattlefieldMapOptions and BattlefieldMapOptions.showPlayers end,
			function()
				BattlefieldMapOptions.showPlayers = not BattlefieldMapOptions.showPlayers
				S.map:UpdateUnitsVisibility()
			end)
		local shape = root:CreateButton(L["Shape"])
		for _, m in ipairs({ { "ROUND", L["Round"] }, { "SQUARE", L["Square"] } }) do
			shape:CreateRadio(m[2], function() return db.shape == m[1] end, function() E.Set("shape", m[1]) end)
		end
		local mouse = root:CreateButton(L["Mouse"])
		for _, m in ipairs({ { "NORMAL", L["Normal"] }, { "ALT", L["Hold Alt to use the map"] }, { "NONE", L["Click-through"] } }) do
			mouse:CreateRadio(m[2], function() return db.mouse == m[1] end, function() E.Set("mouse", m[1]) end)
		end
		local preset = root:CreateButton(L["Preset"])
		preset:CreateButton(L["Lean (best FPS)"], function() E.ApplyPreset("lean") end)
		preset:CreateButton(L["Balanced"], function() E.ApplyPreset("balanced") end)
		preset:CreateButton(L["Everything"], function() E.ApplyPreset("everything") end)
		root:CreateButton(L["Tracking..."], E.OpenTracking)
		root:CreateDivider()
		root:CreateButton(L["Settings..."], E.OpenSettings)
		root:CreateButton(L["Hide GoodMap (Shift-M)"], function() ToggleBattlefieldMap() end)
	end)
end

function E.ApplyPreset(name)
	local preset = PRESETS[name]
	if not preset then return end
	for k, v in pairs(preset) do if db[k] ~= v then E.Set(k, v) end end
	Print(format(L["Preset applied: %s"], PRESET_NAMES[name] or name))
end

function E.OpenSettings()
	if InCombatLockdown() then
		S.openAfterCombat = true
		Print(L["Settings will open after combat."])
		return
	end
	Pathway:OpenSettings("gm_general")
end

function E.ResetAll()
	for k, v in pairs(DEFAULTS) do db[k] = v end
	if BattlefieldMapOptions then BattlefieldMapOptions.opacity = 0 end
	E.EndPeek()
	E.AfterProfileChange()
	Print(L["All settings reset."])
end

function E.NewProfile(name)
	name = type(name) == "string" and name:match("^%s*(.-)%s*$") or ""
	if name == "" then return end
	E.UseProfile(name, db)
	Print(format(L["Now using the profile \"%s\"."], name))
end

function E.DoImport(text)
	if E.ImportString(text) then Print(L["Settings imported."]) else Print(L["That isn't a GoodMap settings string."]) end
end

local function PopupEditBox(dialog)
	if dialog.GetEditBox then return dialog:GetEditBox() end
	return dialog.editBox or dialog.EditBox
end

function E.SetupPopups()
	local P = _G.StaticPopupDialogs
	if type(P) ~= "table" then return end
	local function hide(eb) eb:GetParent():Hide() end
	P.GOODMAP_EXPORT = {
		text = L["Copy this text with Ctrl+C and share it:"],
		button1 = CLOSE or "OK",
		hasEditBox = true, editBoxWidth = 320,
		OnShow = function(dialog)
			local eb = PopupEditBox(dialog)
			if eb then eb:SetText(E.ExportString()); eb:HighlightText(); eb:SetFocus() end
		end,
		EditBoxOnEnterPressed = hide, EditBoxOnEscapePressed = hide,
		timeout = 0, whileDead = true, hideOnEscape = true, preferredIndex = 3,
	}
	P.GOODMAP_IMPORT = {
		text = L["Paste GoodMap settings with Ctrl+V. They replace the settings in your current profile."],
		button1 = ACCEPT or "OK", button2 = CANCEL or "Cancel",
		hasEditBox = true, editBoxWidth = 320,
		OnShow = function(dialog) local eb = PopupEditBox(dialog); if eb then eb:SetText(""); eb:SetFocus() end end,
		OnAccept = function(dialog) local eb = PopupEditBox(dialog); E.DoImport(eb and eb:GetText()) end,
		EditBoxOnEnterPressed = function(eb) E.DoImport(eb:GetText()); hide(eb) end,
		EditBoxOnEscapePressed = hide,
		timeout = 0, whileDead = true, hideOnEscape = true, preferredIndex = 3,
	}
	P.GOODMAP_NEW_PROFILE = {
		text = L["Name your new profile. It starts as a copy of your current settings."],
		button1 = ACCEPT or "OK", button2 = CANCEL or "Cancel",
		hasEditBox = true, maxLetters = 40,
		OnShow = function(dialog) local eb = PopupEditBox(dialog); if eb then eb:SetText(""); eb:SetFocus() end end,
		OnAccept = function(dialog) local eb = PopupEditBox(dialog); E.NewProfile(eb and eb:GetText()) end,
		EditBoxOnEnterPressed = function(eb) E.NewProfile(eb:GetText()); hide(eb) end,
		EditBoxOnEscapePressed = hide,
		timeout = 0, whileDead = true, hideOnEscape = true, preferredIndex = 3,
	}
	P.GOODMAP_DELETE_PROFILE = {
		text = L["Delete the profile \"%s\"?"],
		button1 = YES or "Yes", button2 = NO or "No",
		OnAccept = function(_, data) E.DeleteProfile(data) end,
		timeout = 0, whileDead = true, hideOnEscape = true, preferredIndex = 3,
	}
end

function E.Popup(which, text, data)
	if StaticPopup_Show then StaticPopup_Show(which, text, nil, data) end
end

function E.RegisterSlash()
	SLASH_GOODMAP1, SLASH_GOODMAP2 = "/goodmap", "/gmap"
	SlashCmdList.GOODMAP = function(msg)
		msg = (msg or ""):lower():match("^%s*(.-)%s*$")
		if msg == "" or msg == "config" or msg == "options" then E.OpenSettings()
		elseif msg == "toggle" or msg == "show" or msg == "hide" then ToggleBattlefieldMap()
		elseif msg == "menu" then E.ShowMenu(UIParent)
		elseif msg == "reset" then E.ResetPosition(); Print(L["Position reset."])
		elseif msg == "lock" then E.Set("locked", true)
		elseif msg == "unlock" then E.Set("locked", false)
		elseif msg == "radar" then E.Set("radar", not db.radar)
		elseif msg == "lean" or msg == "balanced" or msg == "everything" then E.ApplyPreset(msg)
		elseif msg == "export" then E.Popup("GOODMAP_EXPORT")
		elseif msg == "import" then E.Popup("GOODMAP_IMPORT")
		elseif msg == "peek" then E.SetupPeekKey(true)
		elseif msg == "farm" or msg == "routes" then E.ShowRoutes()
		elseif msg == "stop" then GoodMap_StopRoute()
		elseif SLASH_MODE[msg] then E.Set("mode", SLASH_MODE[msg])
		elseif msg == "where" then E.PrintWhere()
		elseif msg == "check" then if E.SelfCheck then E.SelfCheck() end
		elseif msg:match("^preview") then local k = msg:match("^preview%s+(%a+)"); if k and E.RidePreview then E.RidePreview(k, 5) elseif E.RidePreviewAll then E.RidePreviewAll() end
		elseif msg == "arrow" then E.PrintArrowInfo()
		elseif msg == "arrow top" then S.arrowTop = not S.arrowTop; E.ApplyUnitPins(); E.PrintArrowInfo()
		else Print("/goodmap  |  toggle  |  menu  |  reset  |  lock  |  unlock  |  radar  |  routes  |  stop  |  normal  |  herbs  |  ore  |  fish  |  pvp  |  lean  |  balanced  |  everything  |  export  |  import  |  peek  |  where  |  check  |  preview") end
	end
end

function GoodMap_OnAddonCompartmentClick(_, button)
	if button == "RightButton" then E.OpenSettings() else ToggleBattlefieldMap() end
end

function GoodMap_OnAddonCompartmentEnter(_, frame)
	Tooltip(frame, BRAND, L["Left-click: show or hide GoodMap"], L["Right-click: settings"])
end

function GoodMap_OnAddonCompartmentLeave()
	GameTooltip:Hide()
end

-- Pathway draws GoodMap's settings in its own window, from the same layout as above.
-- the handful of minimap options most people want; the rest are under Advanced
E.ESSENTIALS = {
	replaceMinimap = true, shape = true, roundSize = true, width = true, height = true, scale = true, locked = true,
	border = true, compass = true, follow = true, zoomButtons = true, zoneText = true, playerCoords = true, clock = true,
	waypointArrow = true, flightMode = true, farmRoutes = true, radar = true, radarMode = true, bar = true,
	groupPings = true, hideInCombat = true, pinScale = true,
	arrowStyle = true, arrowColor = true, arrowCustom = true, playerSize = true, compassGlow = true, glowColor = true,
	border = true, borderSize = true, ringGlow = true, ringColor = true, borderColor = true, edgeStyle = true,
	glowStyle = true, glowAlpha = true, glowWidth = true,
	["btn:Show or hide"] = true, ["btn:Preset: Lean"] = true, ["btn:Preset: Balanced"] = true, ["btn:Preset: Everything"] = true,
}

-- api.only: just these keys, on one page (headers show only above what's kept)
-- api.prefix: page keys for the full set, so both can exist side by side
-- Direct access for Pathway's setup and style pages: read a setting, or change it
-- and apply it to the minimap right now (saved with the rest of the minimap's settings)
NS.API = 2                 -- what Pathway's setup and style pages expect
function E.Get(k) return db and db[k] end
function E.SetLive(k, v)
	if not db or DEFAULTS[k] == nil then return end
	if type(v) == "number" and RANGE[k] then v = Clamp(v, RANGE[k][1], RANGE[k][2]) end
	if not ValidValue(k, v) then return end                  -- only choices the minimap knows
	db[k] = v
	if S.ready and APPLY[k] then
		local ok, err = pcall(APPLY[k], k)
		if not ok then geterrorhandler()(err) end
	end
	Pathway:Send("MAP_LOOK_CHANGED", k)
end

-- Pathway reads and changes the minimap's settings through "map.<key>": ready as
-- soon as the minimap is, so the setup and style pages change the real minimap live
function E.RegisterStore()
	Pathway.stores.map = {
		get = function(k) return db and db[k] end,
		set = function(k, v) E.SetLive(k, v) end,
	}
end

function E.PathwaySettings(api)
	E.RegisterStore()
	local only, pre = api.only, api.prefix or ""
	local p, pending
	local PAGES = {
		[L["Navigation"]] = { "gm_nav", L["Navigation"], "Following, zoom, text, waypoints and flight mode." },
		[L["Icons"]] = { "gm_icons", L["Icons"], "Icon sizes, the player arrow and which map layers show." },
		[L["Minimap"]] = { "gm_radar", "Radar & buttons", "The real minimap inside GoodMap, and the button bar." },
		[L["Group"]] = { "gm_group", L["Group"], "Pings and markers your group sees." },
	}
	local function Sub(name)
		if only then return end
		local t = PAGES[name] or { "gm_" .. name, name }
		p = api.Page(pre .. t[1], "Minimap: " .. t[2], t[3])
	end
	local function Header(text)
		if text == TITLE then return end
		if only then pending = text else p:Section(text) end
	end
	local function Keep(key)
		if only and not only[key] then return false end
		if pending then p:Section(pending); pending = nil end
		return true
	end
	local function Parent(row, parent, predicate) if row and predicate then p:Depends(row, predicate) end return row end
	local function Check(key, name, tip, parent, pred)
		if not Keep(key) then return end
		return Parent(p:Toggle(name, tip, "map." .. key), parent, pred)
	end
	local function Slider(key, name, tip, fmt, parent, pred)
		if not Keep(key) then return end
		local r = RANGE[key]
		return Parent(p:Slider(name, r[1], r[2], r[3], "map." .. key, fmt, 1, tip), parent, pred)
	end
	local function Dropdown(key, name, tip, values, parent, pred)
		if not Keep(key) then return end
		return Parent(p:Dropdown(name, values, "map." .. key, tip), parent, pred)
	end
	local function Button(name, text, fn, tip)
		if not Keep("btn:" .. name) then return end
		return p:Button(text, fn, false, tip)
	end
	local function Color(key, name) if Keep(key) then return p:Color(name, "map." .. key) end end
	local function KeyRow() end
	local function on(key) return function() return db[key] end end
	local POSITIONS = { "TOPLEFT", L["Top left"], "TOP", L["Top"], "TOPRIGHT", L["Top right"], "BOTTOMLEFT", L["Bottom left"], "BOTTOM", L["Bottom"], "BOTTOMRIGHT", L["Bottom right"] }
	local CORNERS = { "TOPLEFT", L["Top left"], "TOPRIGHT", L["Top right"], "BOTTOMLEFT", L["Bottom left"], "BOTTOMRIGHT", L["Bottom right"] }
	p = api.Page(pre .. "gm_general", only and "Minimap" or "Minimap: everything",
		only and "Your zone map becomes your minimap. Shift-M shows or hides it. Every other option is under Advanced."
		or "All of the minimap's options, for fine-tuning.")
	-- General ---------------------------------------------------------------
	Header(TITLE)
	Button(L["Show or hide"], L["Toggle (Shift-M)"], function() ToggleBattlefieldMap() end, L["Shift-M shows or hides GoodMap. While it's hidden, the Blizzard minimap is back."])

	Header(L["Mode"])
	Dropdown("mode", L["Mode"], "Normal is the minimap as you set it up. Pick what you farm (herbs, ore or fishing) and it focuses on that. Battleground shows the whole battleground with bigger group dots and no quest clutter.",
		E.ModeList())
	Check("pvpAuto", L["Automatic in battlegrounds"], L["Switches to Battleground mode when you enter a battleground or arena, and back when you leave."])
	KeyRow("GOODMAP_FARM", L["Farming routes"])
	KeyRow("GOODMAP_STOP", L["Stop farming route"])

	Header(L["Preset"])
	Button(L["Preset: Lean"], L["Best FPS"], function() E.ApplyPreset("lean") end, L["Turns off the heavier map layers and refreshes less often."])
	Button(L["Preset: Balanced"], L["Recommended"], function() E.ApplyPreset("balanced") end, L["GoodMap's defaults."])
	Button(L["Preset: Everything"], L["Show it all"], function() E.ApplyPreset("everything") end, L["Every map layer on, fastest refresh."])

	Header(L["Minimap replacement"])
	Check("replaceMinimap", L["Replace the Blizzard minimap"], L["Hides the Blizzard minimap while GoodMap is shown. Its buttons move to GoodMap's button bar."])
	Check("yieldWorldMap", L["Step aside for the world map"], L["Hides GoodMap while the world map (M) is open and brings it back when you close it."])
	Check("instanceFallback", L["Use the Blizzard minimap where there's no position"], L["Most dungeons and raids don't share your position with add-ons, so GoodMap hands over to the Blizzard minimap there."])
	Check("instanceMaps", L["Dungeon maps"], L["In a dungeon, raid or delve that has a map, GoodMap shows the whole floor you're on, with the game's own marker for you, instead of handing over."])
	local dv = Check("detailView", L["Detailed view inside buildings"], L["In an inn, a house, a cave or a tunnel the game has no map for, the minimap shows the game's own picture of the rooms around you, with its blips and your quest spots. Zoom out past its widest view for the zone map."])
	Check("detailTerrain", L["Terrain up close"], L["Past the zone map's own detail, the game's minimap terrain fades in under every pin, so you can zoom right in on the real ground: roads, houses, docks."], dv, on("detailView"))
	Check("detailCities", L["Detailed view in cities and towns"], L["In cities and towns the minimap shows the streets and houses up close: the game's own minimap picture, filling the window. Zoom out past its widest view for the city map; zoom in again to come back."], dv, on("detailView"))
	Check("subMaps", L["Cave, building and floor maps"], L["Switches to the map of the cave, building, tunnel or floor you're in when the game has one, and back when you leave."])
	Check("indoorZoom", L["Closer indoors"], L["Indoors with no map of its own (an inn, a house), the map comes two steps closer."])

	Header(L["Frame"])
	Check("locked", L["Lock position and size"], L["Stops Shift-dragging and resizing the map."])
	local shape = Dropdown("shape", L["Shape"], L["Round looks like the Blizzard minimap. Square shows more of the map."], { "ROUND", L["Round"], "SQUARE", L["Square"] })
	local function round() return db.shape == "ROUND" end
	local function square() return db.shape == "SQUARE" end
	Slider("roundSize", L["Size"], L["How wide the round map is. You can also drag the grip in the bottom-right corner (hover the map)."], Num("%d"), shape, round)
	Slider("width", L["Width"], L["You can also drag the grip in the bottom-right corner (hover the map)."], Num("%d"), shape, square)
	Slider("height", L["Height"], nil, Num("%d"), shape, square)
	Slider("scale", L["Scale"], nil, Pct)
	Dropdown("strata", L["Frame strata"], L["Which layer of the screen the map is drawn on."], { "BACKGROUND", L["Background"], "LOW", L["Low"], "MEDIUM", L["Medium"], "HIGH", L["High"], "DIALOG", L["Dialog"] })
	if Keep("mapOpacity") then p:SliderFn(L["Map opacity"], 0.05, 1, 0.05, function() return 1 - ((BattlefieldMapOptions and BattlefieldMapOptions.opacity) or 0) end, function(v)
			if BattlefieldMapOptions then BattlefieldMapOptions.opacity = 1 - v end
			if S.ready then E.ApplyAlpha() end
	end, Pct, L["How solid the map artwork looks."]) end
	Check("fullOnHover", L["Full opacity on mouseover"], L["Shows the artwork fully while your mouse is over the map."])
	Slider("idleAlpha", L["Opacity when idle"], L["Fades the whole map, icons included, while your mouse is somewhere else."], Pct)
	Slider("combatAlpha", L["Opacity in combat"], nil, Pct)
	Dropdown("mouse", L["Mouse"], L["Click-through lets you click the world under the map."], { "NORMAL", L["Normal"], "ALT", L["Hold Alt to use the map"], "NONE", L["Click-through"] })

	Header(L["Look"])
	local border = Dropdown("border", L["Border"], nil, { "ACCENT", "Pathway color", "THIN", L["Thin line"], "CLASS", L["Class color"], "BLIZZARD", L["Blizzard"], "NONE", L["None"] })
	Parent(Color("borderColor", L["Border color"]), border, function() return db.border == "THIN" end)
	Slider("borderSize", L["Border thickness"], nil, Num("%d px"), border, function() return db.border == "THIN" or db.border == "CLASS" or db.border == "ACCENT" end)
	Dropdown("edgeStyle", "Border pattern", nil, { "SOLID", "Solid", "DASHED", "Dashed", "DOTTED", "Dotted" }, border, function() return db.border ~= "NONE" and db.border ~= "BLIZZARD" end)
	local rg = Dropdown("ringGlow", "Glow around the map", "A glow just outside the round map's edge.",
		{ "NONE", "None", "SOFT", "Soft", "NEON", "Neon", "PULSE", "Pulse", "BREATHE", "Breathe (slow pulse)", "AURA", "Aura (wide)",
		  "SHADOW", "Shadow", "DOUBLE", "Double ring", "RAINBOW", "Rainbow", "FIRE", "Fire" })
	Dropdown("ringColor", "Glow color", nil, { "ACCENT", "Pathway color", "GREEN", "Pathway green", "CLASS", L["Class color"], "GOLD", L["Gold"], "WHITE", L["White"],
		"BLUE", L["Blue"], "CYAN", L["Cyan"], "PURPLE", L["Purple"], "PINK", L["Pink"], "RED", L["Red"], "ORANGE", L["Orange"] }, rg, function() return db.ringGlow ~= "NONE" end)
	Check("hideClose", L["Hide close button"], L["Only applies to the Blizzard border."], border, function() return db.border == "BLIZZARD" end)
	Check("hideTab", L["Hide the tab"], L["The GoodMap button in the bar, Ctrl + right-click and /goodmap open the menu."])
	Check("compass", L["Compass letters"], L["N, E, S and W just inside the round map's edge."])
	local glow = Check("compassGlow", L["Facing glow"], L["A soft glow slides around the round map's ring to show which way you're facing, as you turn."])
	local glowColor = Dropdown("glowColor", L["Glow color"], nil, { "ACCENT", "Pathway color", "GREEN", "Pathway green", "CLASS", L["Class color"], "GOLD", L["Gold"], "WHITE", L["White"], "BLUE", L["Blue"], "CYAN", L["Cyan"], "PURPLE", L["Purple"], "PINK", L["Pink"], "RED", L["Red"], "ORANGE", L["Orange"], "CUSTOM", L["Custom"] }, glow, on("compassGlow"))
	Parent(Color("glowCustom", L["Custom glow color"]), glowColor, function() return db.compassGlow and db.glowColor == "CUSTOM" end)
	Dropdown("glowStyle", "Glow style", "How the glow that shows which way you face looks.",
		{ "ARC", "Arc", "WIDE", "Wide arc", "BEAM", "Beam", "COMET", "Comet", "TWIN", "Front and back", "SPOT", "Spot", "FAN", "Fan" }, glow, on("compassGlow"))
	Slider("glowAlpha", "Glow brightness", nil, Pct, glow, on("compassGlow"))
	Slider("glowWidth", "Glow thickness", nil, Num("%.2fx"), glow, on("compassGlow"))

	Header(L["Visibility"])
	Check("showInPvP", L["Always show in battlegrounds and arenas"])
	Check("hideInInstance", L["Hide in dungeons, raids and delves"])
	Check("hideInCombat", L["Hide in combat"])
	Check("combatCalm", L["Calmer in combat"], L["While you're fighting, the button bar and the map text fade out. They come back when combat ends, or when you hover the map."])

	Header(L["Reset"])
	Button(L["Position"], L["Reset position"], function() E.ResetPosition() end, L["Moves GoodMap back to the minimap's corner."])
	Button(L["Everything"], L["Reset all settings"], function() E.ResetAll() end, L["Puts every GoodMap setting in this profile back to default."])

	-- Navigation ------------------------------------------------------------
	Sub(L["Navigation"])
	Header(L["Movement"])
	local follow = Check("follow", L["Follow me"], L["Keeps you in the middle of the map while you move."])
	Slider("deadzone", L["Follow dead zone"], L["How far you can move from the middle before the map catches up. 0% keeps you exactly in the middle; higher values move the map less often."], Pct, follow, on("follow"))
	Slider("resumeDelay", L["Resume after"], L["Seconds after your mouse leaves the map before it follows you again."], Num(L["%d s"]))
	Check("autoReturn", L["Return to your zone"], L["After you look at another map, jump back to your zone once you stop using the map."])
	Check("clickNavigate", L["Click to open sub-zones"], L["Left-click a sub-zone to open it, right-click to go up a level."])
	Header(L["Zoom"])
	Slider("extraZoom", L["Extra zoom levels"], L["How far past Blizzard's closest zoom you can go, 25% closer each step. At 20 you can get over 80 times closer."], Num("%d"))
	Check("rememberZoom", "Remember my zoom in each zone", "Each zone opens at a comfortable default. Zoom in or out there and it's remembered for that zone (the way you usually keep it), and used every time you come back.")
	Button("Zoom", "Forget my zoom in every zone", function()
		E.ForgetZoneZoom()
		Print("Every zone opens at the default zoom again.")
	end, "Every zone goes back to the default zoom until you change it there.")
	Slider("flightZoom", L["Zoom out while flying"], L["Zoom levels to step out while flying, skyriding or on a flight path. It zooms back in after you land. 0 turns it off."], Num("%d"))
	Slider("cityZoom", L["Zoom in when resting"], L["Zoom levels to step in while you're in a city or an inn. It zooms back out when you leave. 0 turns it off."], Num("%d"))
	Check("smoothZoom", L["Smooth zoom"], L["Glides between zoom levels instead of jumping."])
	Check("zoomButtons", L["Zoom buttons on mouseover"])
	Check("zoomKeys", L["Minimap zoom keys zoom GoodMap"], L["Your Minimap Zoom In and Zoom Out key bindings also zoom GoodMap."])
	Header(L["Peek"])
	KeyRow("GOODMAP_PEEK", L["Peek"])
	Button(L["Peek key"], format(L["Use %s"], E.PeekKeyName()), function() E.SetupPeekKey(true) end, format(L["Hold the peek key to make GoodMap bigger and zoomed out. Let go and it snaps back. %s is the default. You can pick any key above or under %s."], E.PeekKeyName(), E.KeybindingsPath()))
	Slider("peekScale", L["Peek size"], L["How much bigger GoodMap gets while you hold the peek key."], Num("%.1fx"))
	Slider("peekZoom", L["Zoom out while peeking"], L["How far out GoodMap zooms while you hold the peek key, from where you are to the whole zone."], E.PeekZoomName)
	Header(L["Text"])
	local zone = Check("zoneText", L["Zone name"], L["The sub-zone name, colored by PvP status. While you look at another map, it shows that map's name. In a house, it shows the room you're in."])
	Dropdown("zoneTextPos", L["Zone name position"], nil, POSITIONS, zone, on("zoneText"))
	Slider("zoneTextSize", L["Zone name size"], nil, Num("%d"), zone, on("zoneText"))
	Check("clock", L["Clock"], L["Left-click for the stopwatch and alarm, right-click for the calendar. It follows the game's 24-hour and local time options."])
	Check("playerCoords", L["Player coordinates"], L["Click to center the map on you, Shift-click to share your location in chat."])
	Check("cursorCoords", L["Cursor coordinates"], L["Shown while your mouse is over the map."])
	Slider("coordDecimals", L["Coordinate decimals"], nil, Num("%d"))
	Slider("coordSize", L["Text size"], L["Coordinates, clock and distance."], Num("%d"))
	Check("textShade", L["Shade behind text"], L["A soft dark strip behind the zone name, clock and coordinates, so they're easy to read on any map."])
	Check("flightInfo", L["Flight info"], L["On a flight path, shows where you're going under the zone name, and how long is left once GoodMap knows the route. It learns each route the first time you fly it."])
	Check("statusLine", L["Status line"], L["Frame rate, latency and your lowest durability, next to the coordinates."])
	Check("eventButton", L["Holiday and event button"], L["On days with a holiday or world event, a small button pops up on the left of the map. Hover it for details, click for the calendar, right-click to hide it for a day, a week, a month or for good."])
	Header(L["Waypoints"])
	local wpArrow = Check("waypointArrow", L["Edge arrow for your tracked target"], L["When the quest or map pin you're tracking is outside the view, an arrow on the map's edge points to it."])
	local dist = Check("waypointDistance", L["Show distance"], nil, wpArrow, on("waypointArrow"))
	Check("waypointETA", L["Show time to arrive"], L["Worked out from how fast you've been getting closer."], dist, function() return db.waypointArrow and db.waypointDistance end)
	Check("fitWaypoint", L["Zoom out to fit your target"], L["When your tracked target is just outside the view, GoodMap zooms out up to three steps to show it, and back in as you get close."])
	Check("corpseArrow", L["Corpse arrow"], L["After you die, an arrow on the map's edge points to your corpse, with the distance."])
	Header(L["Flight mode"])
	local fm = Check("flightMode", L["Flight mode"], L["On a flight path, GoodMap shows your whole route, how long is left and when you'll land. It learns each route's time, and estimates new ones from the distance."])
	Check("flightFit", L["Show the whole route"], L["Zooms out to fit the whole flight, and back to your usual zoom when you land."], fm, on("flightMode"))
	Check("flightRing", L["Progress ring"], L["The round map's edge fills up as you fly. On a square map, a bar along the bottom does."], fm, on("flightMode"))
	Check("flightCalm", L["Hide quests while flying"], L["Quests, world quests and other map icons step aside while you fly, so the route stands out. Your tracked target stays."], fm, on("flightMode"))
	Check("flightChime", L["Landing chime"], L["A soft sound 10 seconds before you land."], fm, on("flightMode"))
	Header(L["Ride effects"])
	local rfx = Check("rideFx", L["Ride effects"], L["The minimap comes alive on the way: the tram, boats, zeppelins, lifts, swimming and running back as a ghost each get their own look."])
	Check("rideTram", L["Deeprun Tram: rainbow tunnel"], L["A rainbow tunnel rushes at you while you ride the tram, with where it's going and the time left."], rfx, on("rideFx"))
	Check("rideBoat", L["Boats and ferries: water"], L["Light on the water, a wake behind you and foam going by, with where the boat goes and the time left."], rfx, on("rideFx"))
	Check("rideZeppelin", L["Zeppelins: wind"], L["Wind streams past and clouds drift below, with where the zeppelin goes and the time left."], rfx, on("rideFx"))
	Check("rideLift", L["Lifts: light shaft"], L["Bands of light slide the way the lift goes. Works where the game shares your height."], rfx, on("rideFx"))
	Check("rideSwim", L["Swimming: water light and bubbles"], L["Ripples while you swim; deep blue, wavering light and rising bubbles underwater."], rfx, on("rideFx"))
	Check("rideBreath", L["Air gauge underwater"], L["The minimap's edge shows the air you have left, turns amber, then red and pulses faster before you run out of breath."], rfx, on("rideFx"))
	Check("rideHearth", L["Hearthing: light spirals in"], L["While you cast your hearthstone, Astral Recall or a teleport, light spirals in to you and a ring turns from blue to gold, with where you're going and the time left. A burst of light where you land."], rfx, on("rideFx"))
	Check("rideCalm", L["Reduce motion"], L["The effects play slower and softer: no flashes, no speed lines in the tunnel, a single ring when you land. For anyone the motion bothers."], rfx, on("rideFx"))
	for _, k in ipairs(E.RIDE_ORDER or {}) do
		local names = { tram = L["Tram tunnel"], boat = L["Boat water"], zeppelin = L["Zeppelin wind"], lift = L["Lift light"],
			swim = L["Swimming"], under = L["Underwater and air"], ghost = L["Ghost"], hearth = L["Hearthing"] }
		Button("preview" .. k, L["Preview: "] .. (names[k] or k), function() if E.RidePreview then E.RidePreview(k, 5) end end, L["Plays the effect on the minimap for a few seconds."])
	end
	Check("rideGhost", L["Ghost: the spirit world"], L["A cold haze with wisps drifting up while you run back to your corpse."], rfx, on("rideFx"))

	Header(L["Farming routes"])
	Check("farmRoutes", L["Offer routes when you gather"], L["The first time you gather a herb, ore or lumber in a zone, GoodMap shows that zone's farming routes."])
	Check("farmFish", L["Ask when you fish a pool"], L["When you fish from a pool, GoodMap asks once per zone whether you'd like a route from pool to pool. Fishing anywhere else is left alone."])
	Check("farmPath", L["Path on the map"], L["Draws the route on the map, with lights running ahead of you to the next spot."])
	Check("farmArrow", L["Waypoint arrow"], L["Puts your map pin on the next spot, so the game's arrow and distance lead you there. It replaces your own map pin while you follow a route."])
	Check("farmCalm", L["Hide quests while farming"], L["Quests and world quests step aside while you follow a route. Your tracked target stays."])
	Check("farmSpots", L["Remember spots you gather"], L["GoodMap keeps the spots you gather, for a route through your own spots."])
	Button(L["Farming routes"], L["Open farming routes"], function() E.ShowRoutes() end, L["Routes for the zone you're in. Also /goodmap routes."])
	Button(L["Your spots"], L["Forget my spots"], function()
		wipe(ROOT.spots)
		S.mySpots = nil
		Print(L["Your gathered spots were forgotten."])
	end, L["Forgets every spot you've gathered, in every zone."])

	-- Icons -----------------------------------------------------------------
	Sub(L["Icons"])
	Header(L["Size"])
	Slider("pinScale", L["Icon scale"], L["Size of map icons. Blizzard's default for the zone map is 60%."], Pct)
	local arrow = Dropdown("arrowStyle", L["Player arrow"], L["Blizzard's own arrow, or one of GoodMap's in the color you pick."],
		{ "BLIZZARD", L["Blizzard"], "CLASSIC", L["Classic"], "DART", L["Dart"], "CHEVRON", L["Chevron"], "TRIANGLE", L["Triangle"], "NEEDLE", L["Compass needle"], "BEACON", L["Dot and beam"] })
	local custom = function() return db.arrowStyle ~= "BLIZZARD" end
	local arrowColor = Dropdown("arrowColor", L["Arrow color"], L["Gold on the classic arrow is its own color."],
		{ "ACCENT", "Pathway color", "GOLD", L["Gold"], "WHITE", L["White"], "CLASS", L["Class color"], "GREEN", "Pathway green", "BLUE", L["Blue"], "CYAN", L["Cyan"], "PURPLE", L["Purple"], "PINK", L["Pink"], "RED", L["Red"], "ORANGE", L["Orange"], "CUSTOM", L["Custom"] }, arrow, custom)
	Parent(Color("arrowCustom", L["Custom arrow color"]), arrowColor, function() return custom() and db.arrowColor == "CUSTOM" end)
	Slider("playerSize", L["Player arrow size"], L["Blizzard's default: 12."], Num("%d"))
	Slider("groupSize", L["Party and raid dot size"], L["Blizzard's default: 8."], Num("%d"))
	Header(L["Icon sizes by type"])
	Slider("iconQuest", L["Quests"], L["Quest objectives, world quests and bonus objectives."], Pct)
	Slider("iconRare", L["Rares and treasures"], nil, Pct)
	Slider("iconTravel", L["Travel"], L["Flight points, portals, and dungeon and delve entrances."], Pct)
	Slider("iconAddons", L["Add-on icons"], L["HandyNotes, RareScanner, GatherMate2 and other add-ons' map pins."], Pct)
	Check("iconOutline", L["Dark outline"], L["A soft dark circle behind icons, so they stand out on busy map art."])
	Header(L["Extra layers from the world map"])
	Check("L_quests", L["Quests"], L["Your active quest objectives and quest areas."])
	Check("L_questOffers", L["Available quests"], L["Quest givers you haven't talked to yet."])
	Check("L_tracking", L["Tracking and waypoints"], L["Collectibles you track, your map pin and the waypoint you're following. Ctrl-click places a map pin."])
	Header(L["Built-in layers (turn off to save work)"])
	Check("B_vignettes", L["Rares and treasures"])
	Check("B_pois", L["Points of interest and events"])
	Check("B_flightPoints", L["Flight points"])
	Check("B_dungeons", L["Dungeon and raid entrances"])
	Check("B_bosses", L["Boss icons"])
	local labels = Check("areaLabels", L["Area labels on hover"], L["Sub-zone names when you hover the map."])
	Slider("areaLabelScale", L["Area label size"], nil, Pct, labels, on("areaLabels"))
	Header(L["Add-ons"])
	Check("handyNotes", "HandyNotes", L["Show HandyNotes icons (if installed)."])
	Check("rareScanner", "RareScanner", L["Show RareScanner icons (if installed)."])
	Check("gatherMate", "GatherMate2", L["Show GatherMate2 nodes (if installed)."])
	Check("hbdPins", L["Other add-ons' map pins"], L["Pins other add-ons put on the world map, like TomTom waypoints."])
	Check("tomTom", L["TomTom: Alt + right-click"], L["Alt + right-click the map to add a TomTom waypoint (if installed)."])

	-- Minimap ---------------------------------------------------------------
	Sub(L["Minimap"])
	Header(L["Radar: the minimap inside GoodMap"])
	local radar = Check("radar", L["Embed the minimap"], L["The real minimap moves into GoodMap, centered on you, so gathering nodes, tracking and other minimap icons show up on the map. It always stays inside GoodMap's window."])
	local function radarOn() return db.radar end
	local style = Dropdown("radarMode", L["Radar style"], L["Aligned: no terrain, and the icons sit exactly where they are on the map (it grows as you zoom). Fixed: a round minimap of a set size."], { "ALIGNED", L["Aligned to map"], "FIXED", L["Fixed size"] }, radar, radarOn)
	local function aligned() return db.radar and db.radarMode == "ALIGNED" end
	local function fixed() return db.radar and db.radarMode == "FIXED" end
	Check("radarAutoZoom", L["Auto-zoom the minimap"], L["Picks a minimap zoom whose range fits inside GoodMap."], style, aligned)
	Slider("radarSize", L["Radar size"], nil, Num("%d px"), style, fixed)
	local terrain = Check("radarTerrain", L["Show minimap terrain"], nil, style, fixed)
	Slider("radarAlpha", L["Terrain opacity"], nil, Pct, terrain, function() return fixed() and db.radarTerrain end)
	Slider("radarIconScale", L["Minimap icon size"], L["Size of minimap icons like gathering nodes and tracking."], Pct, radar, radarOn)
	Check("radarMouse", L["Interactive radar"], L["Lets the radar take clicks and the mouse wheel. When off, clicks go to the map. Hovering a node shows what it is either way."], radar, radarOn)
	Check("radarHideArrow", L["Hide GoodMap's player arrow"], L["Uses the minimap's own arrow instead while the radar is showing."], radar, radarOn)
	Check("radarCities", L["Show the radar in cities and inns"], L["In cities the minimap can show a gray square where its terrain would be. When this is off, the radar sits out while you're resting."], radar, radarOn)
	Check("radarIndoors", L["Show the radar indoors"], L["In caves and buildings."], radar, radarOn)
	Header(L["Button bar"])
	local bar = Dropdown("bar", L["Button bar"], L["Puts minimap buttons in a bar next to GoodMap."], { "OFF", L["Off"], "AUTO", L["When the Blizzard minimap is hidden"], "ALWAYS", L["Always"] })
	local function barOn() return db.bar ~= "OFF" end
	Check("barLauncher", L["GoodMap button"], L["Click for the menu, right-click for settings."], bar, barOn)
	Check("barBlizzard", L["Blizzard buttons"], L["Tracking, calendar, mail, add-on compartment and expansion summary."], bar, barOn)
	Check("barOthers", L["Other add-on buttons"], L["Also docks the minimap buttons some add-ons make on their own, so they don't float over the map."], bar, barOn)
	Check("barCompartment", L["Add-ons in the add-on list"], L["Add-ons with a minimap button (BugSack and the like) go in the numbered add-on button instead of taking a spot on the bar, unless you pick them for the bar."], bar, barOn)
	Button(L["Add-on buttons on the bar"], L["Choose"], function() if Pathway.ShowBarButtons then Pathway:ShowBarButtons() end end, L["Pick which add-ons' buttons sit on the bar. The rest wait in the add-on list."])
	Dropdown("barSide", L["Bar position"], nil, { "BOTTOM", L["Below the map"], "TOP", L["Above the map"], "LEFT", L["Left of the map"], "RIGHT", L["Right of the map"] }, bar, barOn)
	Slider("barSize", L["Button size"], nil, Num("%d px"), bar, barOn)
	Slider("barSpacing", L["Button spacing"], nil, Num("%d px"), bar, barOn)
	Check("barMouseover", L["Show only on mouseover"], nil, bar, barOn)
	Header(L["Instance difficulty"])
	local diff = Check("difficulty", L["Show instance difficulty"], L["Shows the dungeon or raid difficulty on GoodMap while the Blizzard minimap is hidden."])
	Dropdown("difficultyPos", L["Difficulty position"], nil, CORNERS, diff, on("difficulty"))

	-- Group -----------------------------------------------------------------
	Sub(L["Group"])
	Header(L["Pings and markers"])
	local pings = Check("groupPings", L["Show group pings"], L["Pings from party and raid members who use GoodMap."])
	Check("groupPinsWorld", L["Show group members' pings in the world"], L["A group member's ping becomes your map pin, so you see it in the world with the distance to it. It replaces your own map pin."], pings, on("groupPings"))
	Check("dblPing", L["Double-click to ping"], L["Double-click the map to ping that spot for your group."])
	Check("dblMarker", L["Double right-click for a raid marker"], L["Double right-click the map to drop a raid marker: the red X unless you pick another below. Once a marker is down, a double right-click asks which one you want."])
	Check("worldPins", L["Put your pings and markers in the world"], L["Your ping or marker also becomes your map pin, so it shows in the world with the distance to it. The game allows one map pin, so each new one replaces the last. Map pins don't work in dungeons, raids and battlegrounds."])
	Check("shareChat", L["Share in chat"], L["Also posts a map pin link in your group's chat, or in /say when you're not in a group. Players without GoodMap can click it to see the spot on their map and in the world."])
	local marks = {}
	for i = 1, 8 do marks[#marks + 1] = tostring(i); marks[#marks + 1] = E.MarkerName(i) end
	Dropdown("markClick", L["The mark key places"], L["Hold the mark key and click the map. Everyone in your group who uses GoodMap sees it. Add-ons can't put markers in the world itself, so they show on the map."],
		{ "PING", L["A ping"], "MARKER", L["A raid marker"], "BOTH", L["A ping and a raid marker"] })
	Dropdown("markIcon", L["Raid marker"], L["The marker that double right-click and the mark key put down first."], marks)
	KeyRow("GOODMAP_MARK", L["Pings and markers"])
	Button(L["Markers"], L["Clear markers"], function() E.ClearMarkers() end, L["Removes the markers on the map for everyone in your group. In a raid, only the leader and assistants can."])

end

Pathway:AddSettings("MAP", function(api) if NS.ready then api.only = E.ESSENTIALS; E.PathwaySettings(api) end end)
Pathway:AddSettings("ADVANCED", function(api) if NS.ready then api.prefix = "adv_"; E.PathwaySettings(api) end end)

-- Which apply function each setting triggers.
OnKeys("mode pvpAuto", function(key) E.ApplyMode(); if key == "mode" then E.OnFarmMode() end end)
OnKeys("compass compassGlow", function() E.ApplyCompass(); E.ApplyText(); E.UpdateHeading() end)
OnKeys("arrowStyle arrowColor arrowCustom", function() E.ApplyArrowStyle() end)
OnKeys("glowColor glowCustom glowStyle glowAlpha glowWidth", function() E.ApplyCompass(); S.facing = nil end)
OnKeys("farmPath farmArrow", function(key)
	if key == "farmPath" then E.DrawFarmRoute() else E.FarmGuide() end
	if S.routesWin and S.routesWin:IsShown() then E.FillRoutes(S.routesWin) end
end)
OnKeys("farmCalm", function() E.ApplyLayers() end)
OnKeys("flightMode flightFit flightRing flightCalm flightChime", function()
	if S.flightOn then E.FlightStop() end
	E.UpdateFlight()
end)
OnKeys("peekZoom", function() E.ApplyPeekZoom() end)
OnKeys("peekScale", function() E.ApplyPeekSize() end)
OnKeys("statusLine", function() E.UpdateDurability(); E.ApplyText() end)
OnKeys("flightInfo", function() E.ApplyText() end)
OnKeys("rideFx rideTram rideBoat rideZeppelin rideLift rideSwim rideBreath rideGhost rideHearth rideCalm", function() if E.RideSettingsChanged then E.RideSettingsChanged() end end)
OnKeys("eventButton", function()
	if db.eventButton then ROOT.eventsHidden, ROOT.eventsHiddenUntil = nil, nil end   -- turned back on: show it now
	E.ReadEvents()
end)
OnKeys("waypointETA fitWaypoint", function() S.etaD, S.etaV, S.lastDist = nil, nil, nil; E.RefreshWaypointTarget(); E.UpdateWaypointDistance() end)
OnKeys("corpseArrow", function() E.RefreshWaypointTarget() end)
OnKeys("iconQuest iconRare iconTravel iconAddons iconOutline", function() E.ApplyPinSizes(); E.PlaceCanvasPins() end)
OnKeys("gatherMate hbdPins", function() E.ApplyThirdParty(); E.HBDRefresh() end)
OnKeys("reveal revealTint", function() E.ApplyReveal() end)
OnKeys("radarCities radarIndoors", function() E.UpdateRadarState() end)
OnKeys("replaceMinimap", function() E.UpdateCluster(); Later("barRefresh", E.RefreshBar) end)
OnKeys("yieldWorldMap instanceFallback instanceMaps showInPvP hideInInstance hideInCombat", function() E.UpdateVisibility() end)
OnKeys("detailView detailCities detailTerrain", function() S.detailOff = nil; E.UpdateDetail(); if E.Terrain then E.Terrain.key = nil; E.TerrainUpdate() end end)
OnKeys("subMaps", function()
	local old = S.playerMap
	S.playerMap = E.PlayerMapID()
	if S.mapShown and S.playerMap and S.map:GetMapID() == old then S.map:SetMapID(S.playerMap) end
end)
OnKeys("indoorZoom", function() if S.mapShown then E.UpdateContextZoom(GetTime()) end end)
OnKeys("width height shape roundSize", function() Later("size", E.ApplySize, 0.05) end)
OnKeys("smoothZoom", function() E.ApplySmoothZoom() end)
OnKeys("combatCalm", function() E.ApplyCalm() end)
OnKeys("scale", function() E.ApplyScale() end)
OnKeys("strata", function() E.ApplyStrata() end)
OnKeys("locked", function() E.UpdateHoverWidgets(S.hovered) end)
OnKeys("border borderColor borderSize hideClose ringGlow ringColor edgeStyle", function() E.ApplyBorder(); E.ApplyCompass() end)
OnKeys("hideTab", function() E.ApplyTab() end)
OnKeys("idleAlpha combatAlpha fullOnHover", function() E.ApplyAlpha() end)
OnKeys("mouse", function() E.ApplyMouse() end)
OnKeys("follow", function() E.Wake() end)
OnKeys("deadzone", function() E.Wake(); if S.radarEmbedded then E.UpdateRadarSize() end end)
OnKeys("clickNavigate", function() S.map:SetShouldNavigateOnClick(db.clickNavigate) end)
OnKeys("extraZoom", function() Later("zoomLevels", E.ApplyZoomLevels, 0.1) end)
OnKeys("rememberZoom", function() if not db.rememberZoom then db.zoomIndex = false end end)
OnKeys("zoomButtons", function() E.UpdateHoverWidgets(S.hovered) end)
OnKeys("zoneText zoneTextPos zoneTextSize clock playerCoords cursorCoords coordDecimals coordSize textShade", function() E.ApplyText() end)
OnKeys("difficulty difficultyPos", function() E.ApplyDifficulty() end)
OnKeys("waypointArrow waypointDistance", function() S.lastDist = nil; E.RefreshWaypointTarget(); E.UpdateWaypointDistance() end)
OnKeys("pinScale areaLabels areaLabelScale playerSize groupSize", function() E.ApplyIcons() end)
OnKeys("L_quests L_questOffers L_worldQuests L_bonus L_delves L_tracking L_races L_events L_housing", function() E.ApplyLayers() end)
OnKeys("B_vignettes B_flightPoints B_dungeons B_pois B_petTamers B_digSites B_bosses", function() E.ApplyBuiltins() end)
OnKeys("wqInterval", function() E.ApplyWorldQuestRate() end)
OnKeys("handyNotes rareScanner", function() E.ApplyThirdParty() end)
OnKeys("radar radarMode radarAutoZoom radarSize radarTerrain radarAlpha radarIconScale radarMouse radarHideArrow", function() Later("radar", E.ApplyRadar) end)
OnKeys("bar barLauncher barBlizzard barOthers barCompartment barSide barSize barSpacing barMouseover", function() Later("barRefresh", E.RefreshBar) end)

--------------------------------------------------------------------------------
-- Startup and events
--------------------------------------------------------------------------------
function E.ApplyAll()
	E.ApplyStrata()
	E.ApplyScale()
	E.ApplySize()
	E.ApplyPosition()
	E.ApplyBorder()
	E.ApplyTab()
	E.ApplyMouse()
	E.ApplyAlpha()
	E.ApplyCalm()
	E.ApplySmoothZoom()
	S.map:SetShouldNavigateOnClick(db.clickNavigate)
	E.ApplyText()
	E.ApplyIcons()
	E.ApplyLayers()
	E.ApplyBuiltins()
	E.ApplyThirdParty()
	E.ApplyReveal()
	E.ApplyRadar()
	E.UpdateCluster()
	E.RefreshBar()
	E.UpdateVisibility()
	E.UpdateHouseView()
	if S.houseActive then
		if not S.peeking then S.houseK = db.houseZoom end
		E.HouseLayout()
	end
	E.UpdateDurability()
	E.ReadEvents()
	E.ApplyEditMode()
	if S.mapShown then E.UpdateHeading() end
end

function E.FirstRun()
	-- GoodMap is meant to be your minimap: on, opaque, in the minimap's corner.
	SetCVar("showBattlefieldMinimap", "1")
	if BattlefieldMapOptions then BattlefieldMapOptions.opacity = 0 end
	ROOT.setupDone = true
	C_Timer.After(3, function()
		print(format(L["%s is now your minimap. Shift-M hides or shows it, M opens the world map as usual, and /goodmap opens settings."], BRAND))
	end)
end

function E.Init()
	for _, other in ipairs({ "EnhanceBattlefieldMinimap", "EBFM" }) do
		if Pathway.AddOns.IsAddOnLoaded(other) then
			Print(format(L["%s is turned on too and changes the same map. Turn it off. GoodMap stays inactive until then."], other))
			return
		end
	end
	if not BattlefieldMapFrame then Pathway.AddOns.LoadAddOn("Blizzard_BattlefieldMap") end
	local map = BattlefieldMapFrame
	if not (map and map.ScrollContainer) then Print(L["Blizzard's zone map isn't available."]) return end
	S.map, S.sc, S.canvas = map, map.ScrollContainer, map.ScrollContainer.Child

	-- this character's profile
	db = E.FillDefaults(ROOT.profiles[E.ProfileName()])
	if not ROOT.setupDone then E.FirstRun() end
	-- the "show zone map" switch is kept per character: a new character starts with it off
	PathwayCharDB = PathwayCharDB or {}
	if not PathwayCharDB.mapSetup then
		PathwayCharDB.mapSetup = true
		SetCVar("showBattlefieldMinimap", "1")
		if BattlefieldMapOptions then BattlefieldMapOptions.opacity = 0 end
	end

	S.inPvP = E.InPvP()
	S.mode = E.Mode()

	E.SetupFrame()
	E.SetupOverlay()
	E.SetupCompass()
	E.SetupNavigation()
	E.SetupIcons()
	E.SetupRadar()
	E.SetupArrow()
	E.SetupHouse()
	E.SetupBar()
	E.SetupEventButton()
	E.SetupGroup()
	E.SetupEditMode()
	E.SetupFlights()
	E.SetupFlightMode()
	if E.SetupRides then E.SetupRides() end
	if E.SetupTerrain then E.SetupTerrain() end
	E.SetupGathering()
	E.SetupFarming()
	E.SetupPopups()
	-- settings live in Pathway's window (E.PathwaySettings below)
	E.RegisterSlash()

	map:HookScript("OnShow", E.OnMapShown)
	map:HookScript("OnHide", E.OnMapHidden)
	hooksecurefunc(map, "Toggle", E.OnToggle)
	if WorldMapFrame then
		WorldMapFrame:HookScript("OnShow", function() if db.yieldWorldMap then E.UpdateVisibility() end end)
		WorldMapFrame:HookScript("OnHide", function()
			if S.override == "world" then S.override = nil end
			E.UpdateVisibility()
			Later("hbd", E.HBDRefresh, 0.05)       -- borrow add-on pins back from the world map
		end)
	end

	S.ready = true
	E.RegisterStore()
	-- choices that landed in Pathway's own settings before the minimap could take them
	local ps = PathwayDB and PathwayDB.settings
	if ps then
		for key, v in pairs(ps) do
			local k = type(key) == "string" and key:match("^map%.(.+)$")
			if k then
				if DEFAULTS[k] ~= nil and ValidValue(k, v) then db[k] = v end
				ps[key] = nil
			end
		end
	end
	-- Pathway's color runs through the border, the glow and the arrow
	Pathway:OnPaint(function() if S.ready then E.ApplyBorder(); E.ApplyCompass(); E.ApplyArrowStyle() end end)
	-- An error in one setting is reported but doesn't stop the rest of the start-up.
	local report = geterrorhandler()
	xpcall(E.HouseCheck, report)
	xpcall(E.ApplyAll, report)
	if map:IsShown() then xpcall(E.OnMapShown, report) end

	local events = {
		"PLAYER_ENTERING_WORLD", "ZONE_CHANGED", "ZONE_CHANGED_INDOORS", "ZONE_CHANGED_NEW_AREA",
		"PLAYER_STARTED_MOVING", "MODIFIER_STATE_CHANGED", "MINIMAP_UPDATE_ZOOM",
		"PLAYER_REGEN_DISABLED", "PLAYER_REGEN_ENABLED", "PLAYER_LOGOUT",
		"SUPER_TRACKING_CHANGED", "SUPER_TRACKING_PATH_UPDATED", "USER_WAYPOINT_UPDATED", "QUEST_POI_UPDATE",
		"PLAYER_UPDATE_RESTING", "UPDATE_INVENTORY_DURABILITY", "CALENDAR_UPDATE_EVENT_LIST", "CHAT_MSG_ADDON",
		"GROUP_LEFT", "MAP_EXPLORATION_UPDATED", "PLAYER_DEAD", "PLAYER_ALIVE", "PLAYER_UNGHOST",
		"PLAYER_CONTROL_LOST", "PLAYER_CONTROL_GAINED", "LOOT_READY", "CURRENCY_DISPLAY_UPDATE",
	}
	for _, event in ipairs(events) do pcall(S.events.RegisterEvent, S.events, event) end
	for _, event in ipairs({ "UNIT_SPELLCAST_SENT", "UNIT_SPELLCAST_SUCCEEDED" }) do    -- gathering, yours only
		if not pcall(S.events.RegisterUnitEvent, S.events, event, "player") then pcall(S.events.RegisterEvent, S.events, event) end
	end
	C_Timer.After(2, function() E.SetupPeekKey(false) end)
end

local function ZoneChanged()
	local old = S.playerMap
	S.playerMap = E.PlayerMapID()
	if S.ready then E.HouseCheck() end
	if S.mapShown then
		-- into a cave, a building or onto another floor (and back out): its map straight away
		if old and S.playerMap and old ~= S.playerMap and S.map:GetMapID() == old
			and not S.flightMap and not S.houseActive and not S.peeking then
			S.map:SetMapID(S.playerMap)
		end
		E.UpdateZoneText(); E.Wake()
		-- a new place: its detail view comes back, even if you'd zoomed out of the last one
		if GetSubZoneText and GetSubZoneText() ~= S.detailSub then
			S.detailSub = GetSubZoneText()
			-- a new place: its own detail comes back if you'd zoomed out of the last one
			-- (a detail you zoomed into yourself stays: you asked for it)
			if not S.detailManual then S.detailOff = nil end
		end
		E.UpdateDetail()
		-- indoors the radar steps out at once, so the minimap's own art never shows through
		E.UpdateRadarState()
	end
end

local function NewArea(isLogin, isReload)
	ZoneChanged()
	-- battleground mode follows you in and out of battlegrounds
	if S.ready then
		S.inPvP = E.InPvP()
		E.ApplyMode()
		if isLogin or isReload then E.UpdateDurability() end
		-- in a farming mode, each new zone offers its routes for what you farm
		if E.FarmKind() then C_Timer.After(2, E.OfferMode) end
	end
	-- add-ons often make their minimap buttons during login
	if isLogin or isReload then E.QueueLooseScan(3) end
	S.override = nil
	C_Timer.After(0, E.UpdateVisibility)
	-- the position and house state can arrive a moment after loading
	C_Timer.After(1.5, function() E.HouseCheck(); E.UpdateVisibility(); E.UpdateHouseView() end)
end

E.PLAYER_ENTERING_WORLD, E.ZONE_CHANGED_NEW_AREA = NewArea, NewArea
E.ZONE_CHANGED, E.ZONE_CHANGED_INDOORS = ZoneChanged, ZoneChanged

function E.PLAYER_UPDATE_RESTING() if S.mapShown then E.UpdateContextZoom(GetTime()); E.UpdateDetail(); E.UpdateRadarState() end end

function E.UPDATE_INVENTORY_DURABILITY() if db.statusLine then Later("durability", E.UpdateDurability, 0.5) end end
function E.CALENDAR_UPDATE_EVENT_LIST() if S.ready then Later("events", E.ReadEvents, 0.5) end end
function E.MAP_EXPLORATION_UPDATED() if S.reveal and db.reveal then Later("reveal", E.DrawReveal, 0.2) end end
local function DeathEvent() if S.mapShown then Later("waypoint", E.RefreshWaypointTarget, 0.2) end end
E.PLAYER_DEAD, E.PLAYER_ALIVE, E.PLAYER_UNGHOST = DeathEvent, DeathEvent, DeathEvent

function E.PLAYER_STARTED_MOVING() if S.mapShown then E.Wake() end end

-- Taking off and landing: noticed right away, even while GoodMap is hidden.
local function ControlChanged() if S.flight then C_Timer.After(0.1, E.UpdateFlight) end end
E.PLAYER_CONTROL_LOST, E.PLAYER_CONTROL_GAINED = ControlChanged, ControlChanged

function E.MODIFIER_STATE_CHANGED()
	if S.mapShown and db.mouse == "ALT" then E.UpdateAltMouse() end
end

function E.MINIMAP_UPDATE_ZOOM()
	if S.radarEmbedded then Later("radarSize", E.UpdateRadarSize) end
end

local function WaypointEvent()
	if S.mapShown then Later("waypoint", E.RefreshWaypointTarget, 0.1) end
end
E.SUPER_TRACKING_CHANGED, E.SUPER_TRACKING_PATH_UPDATED, E.USER_WAYPOINT_UPDATED, E.QUEST_POI_UPDATE = WaypointEvent, WaypointEvent, WaypointEvent, WaypointEvent

function E.PLAYER_REGEN_DISABLED()
	S.inCombat = true
	if db.hideInCombat then E.UpdateVisibility() end
	if S.mapShown then E.ApplyAlpha(); E.ApplyCalm() end
end

function E.PLAYER_REGEN_ENABLED()
	S.inCombat = false
	if db.hideInCombat then E.UpdateVisibility() end
	if S.mapShown then E.ApplyAlpha(); E.ApplyCalm() end
	E.CatchUpLayers()
	if S.radarAfterCombat then S.radarAfterCombat = nil; E.UpdateDetail(); E.UpdateRadarState() end
	if S.revealAfterCombat then S.revealAfterCombat = nil; E.ApplyReveal() end
	if S.openAfterCombat then S.openAfterCombat = nil; E.OpenSettings() end
	if S.peekKeyAfterCombat then
		local force = S.peekKeyAfterCombat == "force"
		S.peekKeyAfterCombat = nil
		E.SetupPeekKey(force)
	end
end

function E.PLAYER_LOGOUT()
	E.HouseSave()
end

function E.ADDON_LOADED(name)
	if name == ADDON_NAME then
		E.LoadDB()
	elseif name == "HandyNotes" or name == "RareScanner" or name == "GatherMate2" or name == "TomTom" then
		if S.ready then E.ApplyThirdParty() end
	elseif name == "Blizzard_HybridMinimap" then
		if S.ready then E.HookHybrid() end
	elseif name == "Chamberlain" or name == "HouseMinimap" then
		S.houseAddon = nil
		if S.ready then E.UpdateVisibility(); E.UpdateHouseView() end
	end
	-- a late-loading add-on may bring its own minimap button, or map pins
	if S.ready and name ~= ADDON_NAME and not name:find("^Blizzard_") then
		E.QueueLooseScan(1)
		if not S.hbd then Later("thirdParty", E.ApplyThirdParty, 0.5) end
	end
end

function E.PLAYER_LOGIN()
	-- the minimap module only starts when it's switched on in Pathway (Modules)
	if PathwayDB and PathwayDB.settings and PathwayDB.settings.goodmap == false then return end
	-- if the minimap can't start on this client, say so and leave the rest of Pathway running
	local ok, err = xpcall(E.Init, function(e) return tostring(e) .. "\n" .. (debugstack and debugstack() or "") end)
	NS.ready = ok and S.ready and true or false
	if not ok then
		print("|cff6ee7b7Path|rway: the minimap couldn't start on this client. Everything else works; you can turn the minimap off under /pw settings > Modules.")
		geterrorhandler()(err)
	end
end

S.events = CreateFrame("Frame")
S.events:RegisterEvent("ADDON_LOADED")
S.events:RegisterEvent("PLAYER_LOGIN")
S.events:SetScript("OnEvent", Pathway.Perf.W("Minimap", function(_, event, ...)
	local handler = E[event]
	if handler then handler(...) end
end))

-- Shared with GoodMap's own files only (the add-on's private namespace).
NS.E, NS.S, NS.Mask = E, S, Mask
NS.MapRect, NS.MapYards, NS.PlayerPos = MapRect, MapYards, PlayerPos
NS.FX = { Tex = FlightTex, Fades = Fades, FadeIn = FadeIn, FadeOut = FadeOut, Breathe = Breathe, Ripple = Ripple, PlayRipple = PlayRipple }
end part() end
-- ==================== GoodMap/Rides.lua
do local __addon, __ns = ... local function part()
-- Copyright (C) 2026 SoFinSicc. Part of Pathway (curseforge.com/wow/addons/pathway): free software under the GPLv3 or later, with additional terms that require keeping this credit. See LICENSE.md.
--[[ Pathway minimap — ride effects
     The minimap comes alive on the way: a rainbow tunnel in the Deeprun Tram,
     water on boats and ferries, wind on zeppelins, a shaft of light on lifts,
     light and bubbles when you swim (with an air gauge that warns you before
     you run out of breath), and the spirit world while you run back as a ghost.
     Flights keep their own flight mode.

     The game doesn't tell add-ons you're on a boat, so Pathway notices it: you
     move while you aren't moving yourself. Which boat it is comes from where you
     boarded (Pathway knows every dock), and so does where it's going. How long
     is left is measured on the way, and learned from your rides.

     Everything here runs only while an effect is showing, and each one can be
     turned off (minimap settings, Ride effects). ]]

local ADDON, P = __addon, __ns
local NS = P.GoodMap
local E, S, FX = NS.E, NS.S, NS.FX
local Mask = NS.Mask
local L = NS.L or setmetatable({}, { __index = function(_, k) return k end })
if not (E and S and FX) then return end

local pi, sin, cos, abs, sqrt, floor, min, max, random = math.pi, math.sin, math.cos, math.abs, math.sqrt, math.floor, math.min, math.max, math.random
local atan2 = math.atan2 or function(y, x) return math.atan(y, x) end
local format = string.format

local TEX = "Interface\\AddOns\\Pathway\\GoodMap\\Textures\\"
local TRAM_INSTANCE = 369
local TICK = 0.2

local function Get(k) return E.Get(k) end
local function On(k) return Get("rideFx") ~= false and Get(k) ~= false end
local function Clamp(v, a, b) return v < a and a or (v > b and b or v) end
local function Smooth(e0, e1, x) local t = Clamp((x - e0) / (e1 - e0), 0, 1) return t * t * (3 - 2 * t) end

local function HSV(h, s, v)
	local i = floor(h * 6) % 6
	local f = h * 6 - floor(h * 6)
	local p, q, t = v * (1 - s), v * (1 - f * s), v * (1 - (1 - f) * s)
	if i == 0 then return v, t, p elseif i == 1 then return q, v, p elseif i == 2 then return p, v, t
	elseif i == 3 then return p, q, v elseif i == 4 then return t, p, v end
	return v, p, q
end

local function Tex(parent, layer, file, r, g, b, a, blend, sub)
	local t = parent:CreateTexture(nil, layer, nil, sub)
	t:SetTexture(file)
	t:SetVertexColor(r, g, b, a)
	if blend then t:SetBlendMode(blend) end
	Mask(t)
	return t
end
local function Wash(parent, r, g, b, a, layer)
	local t = parent:CreateTexture(nil, layer or "BACKGROUND")
	t:SetAllPoints()
	t:SetColorTexture(r, g, b, a)
	Mask(t)
	return t
end
local function Size() local d = E.Diameter() return d, S.sc:GetWidth() or d, S.sc:GetHeight() or d end

-- the state: what you're doing right now, and the ride you're on
local R = { kind = nil, hx = -0.7, hy = -0.7 }
E.Ride = R
local FXF = {}          -- kind -> its effect's frame
E.RideFrames = FXF

--------------------------------------------------------------------------------
-- Noticing a ride
--------------------------------------------------------------------------------
local function TransportEnd(p)
	if p.w then return p.w[1], p.w[2], p.w[3] end
	return P:WorldPos(p[1], p[2], p[3])
end

-- the boat, zeppelin or ferry whose dock you boarded at (nil when none is near)
local function WhichTransport(inst, wx, wy)
	local best, bestD, from
	for _, t in ipairs(P.TRANSPORT or {}) do
		if t.kind ~= "tram" then
			for _, side in ipairs({ "a", "b" }) do
				local i, x, y = TransportEnd(t[side])
				if i == inst and x then
					local d = sqrt((x - wx) ^ 2 + (y - wy) ^ 2)
					if d < 400 and (not bestD or d < bestD) then best, bestD, from = t, d, side end
				end
			end
		end
	end
	return best, from
end

local function Learned()
	local l = P.db and P.db.learned
	if not l then return {} end
	l.rides = l.rides or {}
	return l.rides
end

local function StartRide(kind, inst, wx, wy)
	R.ride = { kind = kind, start = GetTime(), inst = inst, x = wx, y = wy }
	if kind == "boat" then
		local t, from = WhichTransport(inst, wx, wy)
		if t then
			R.ride.t, R.ride.from = t, from
			R.ride.kind = t.kind == "zeppelin" and "zeppelin" or "boat"
			R.ride.key = t[from == "a" and "name" or "back"]
		else
			-- nothing that runs from here: a knockback, a charge, a mount's leap. Not a ride.
			R.ride = nil
		end
	end
end

local function EndRide(arrived)
	local r = R.ride
	R.ride = nil
	if not (r and arrived) then return end
	local secs = GetTime() - r.start
	if r.kind == "tram" then
		if secs > 15 and secs < 300 then Learned().tram = floor(secs + 0.5) end
		return
	end
	if not (r.key and r.t) then return end
	-- a whole ride, dock to dock: its time is learned for next time
	local inst, wx, wy = P:PlayerPos()
	local i, x, y = TransportEnd(r.t[r.from == "a" and "b" or "a"])
	if inst and i == inst and x and sqrt((x - wx) ^ 2 + (y - wy) ^ 2) < 400 then
		if secs > 20 and secs < 900 then Learned()[r.key] = floor(secs + 0.5) end
	end
end

-- Five times a second: are you being carried? swimming? a ghost?
local mismatchFor, calmFor = 0, 0
function E.RideTick()
	local now = GetTime()
	local inst, wx, wy = P:PlayerPos()
	local _, _, wz = UnitPosition("player")
	local own = GetUnitSpeed and GetUnitSpeed("player") or 0
	local prev = R.prev
	local onTaxi = UnitOnTaxi and UnitOnTaxi("player")
	local falling = IsFalling and IsFalling()
	if inst and prev and prev.inst == inst and not onTaxi then
		local dt = now - prev.t
		if dt > 0.05 then
			local dx, dy = wx - prev.x, wy - prev.y
			local v = sqrt(dx * dx + dy * dy) / dt
			local dz = (wz and prev.z) and (wz - prev.z) or 0
			R.speed = (R.speed or v) * 0.6 + v * 0.4
			local mismatch = abs(v - own)
			if v > 1 then                        -- your heading on screen (map north up)
				local sx, sy = -dx, dy
				local l = sqrt(sx * sx + sy * sy)
				R.hx, R.hy = R.hx * 0.7 + sx / l * 0.3, R.hy * 0.7 + sy / l * 0.3
			end
			-- a lift: up or down, standing still (only where the game shares your height)
			if own < 0.1 and v < 0.5 and abs(dz) / dt > 1 and not falling then
				R.liftDir, R.liftAt = dz > 0 and 1 or -1, now
			end
			if v > 80 then
				mismatchFor = 0                     -- a jump (hearth, teleport, blink), not a ride
			elseif mismatch > 2.5 and not falling then
				mismatchFor = mismatchFor + dt; calmFor = 0
				if not R.ride and mismatchFor >= 1.2 then StartRide(inst == TRAM_INSTANCE and "tram" or "boat", inst, prev.x, prev.y) end
			elseif mismatch < 0.8 then
				calmFor = calmFor + dt; mismatchFor = 0
				if R.ride and calmFor >= 2.5 then EndRide(true) end
			end
		end
	elseif R.ride and R.ride.loadedAt and now - R.ride.loadedAt > 25 then
		EndRide(false)                          -- after a loading screen the ride never went on
	end
	if onTaxi and R.ride then EndRide(false) end
	-- a hearth on the same continent has no loading screen: you just jump
	if R.arriveBy and inst and prev and (prev.inst ~= inst or sqrt((wx - prev.x) ^ 2 + (wy - prev.y) ^ 2) > 200) then E.RideArrive() end
	R.prev = inst and { inst = inst, x = wx, y = wy, z = wz, t = now } or nil
	if inst ~= TRAM_INSTANCE then R.outside = GetRealZoneText and GetRealZoneText() or R.outside end
	E.RideChoose()
end

function E.RideLoaded()
	R.prev = nil
	if R.ride then R.ride.loadedAt = GetTime(); R.ride.crossed = true end
end

-- Hearthing: your hearthstone, Astral Recall or a teleport, while you cast it.
local HEARTHS = { [8690] = true, [556] = true, [3561] = true, [3562] = true, [3563] = true, [3565] = true,
	[3566] = true, [3567] = true, [18960] = true }
local function IsHearth(spellID)
	if HEARTHS[spellID] then return true end
	local name = spellID and GetSpellInfo and GetSpellInfo(spellID)
	return name and (name:find("Hearthstone") or name:find("^Teleport:")) and true or false
end
function E.RideCast(event, unit, _, spellID)
	if unit ~= "player" then return end
	if event == "UNIT_SPELLCAST_START" then
		if not IsHearth(spellID) then return end
		local _, _, _, startMs, endMs = UnitCastingInfo("player")
		local now = GetTime()
		R.hearth = { spell = spellID, start = startMs and startMs / 1000 or now, stop = endMs and endMs / 1000 or now + 10 }
		if spellID == 8690 or spellID == 556 then
			R.hearth.to = GetBindLocation and GetBindLocation() or ""
		else
			R.hearth.to = ((GetSpellInfo and GetSpellInfo(spellID) or ""):gsub("^Teleport:%s*", ""))
		end
	elseif not R.hearth then
		return
	elseif event == "UNIT_SPELLCAST_SUCCEEDED" and spellID == R.hearth.spell then
		R.hearth = nil
		R.arriveBy = GetTime() + 40               -- the burst plays where you land
		local hf = E.RideFrames and E.RideFrames.hearth
		if hf then hf.flash = 0.6 end
	elseif event == "UNIT_SPELLCAST_STOP" or event == "UNIT_SPELLCAST_INTERRUPTED" or event == "UNIT_SPELLCAST_FAILED" then
		if spellID == R.hearth.spell then R.hearth = nil end
	end
	E.RideChoose()
end

-- Landing after a hearth: a burst of light where you arrive.
function E.RideArrive()
	if not (R.arriveBy and GetTime() < R.arriveBy and On("rideHearth")) then return end
	R.arriveBy = nil
	local f = S.rideArrive
	if not f then return end
	f:Show(); f:SetAlpha(1)
	f.t = 0
end

-- Air: the game's breath timer.
function E.RideMirror(event, timer, value, maxValue, scale, paused)
	if timer ~= "BREATH" then return end
	if event == "MIRROR_TIMER_START" then
		R.breath = { value = value or 0, max = (maxValue and maxValue > 0) and maxValue or 1, scale = scale or -1, t = GetTime(), paused = paused and paused > 0 }
	elseif event == "MIRROR_TIMER_STOP" then
		R.breath = nil
	elseif event == "MIRROR_TIMER_PAUSE" and R.breath then
		R.breath.value = E.BreathLeft() or R.breath.value; R.breath.t = GetTime(); R.breath.paused = (timer and value and value > 0)
	end
	E.RideChoose()
end

-- milliseconds of air left, and the fraction of it (nil when there's no timer)
function E.BreathLeft()
	local b = R.breath
	if not b then return end
	local left
	if GetMirrorTimerProgress then left = GetMirrorTimerProgress("BREATH") end
	if not left or left <= 0 then
		left = b.paused and b.value or b.value + (b.scale or -1) * (GetTime() - b.t) * 1000
	end
	left = Clamp(left, 0, b.max)
	return left, left / b.max, (b.scale or -1) < 0
end

--------------------------------------------------------------------------------
-- Which effect
--------------------------------------------------------------------------------
function E.InTram()
	local _, _, _, inst = UnitPosition("player")
	return inst == TRAM_INSTANCE
end
-- the tram keeps the minimap up for its tunnel while it moves, even though no map covers it
local function TramMoving() return R.ride and R.ride.kind == "tram" and E.InTram() end
function E.RideHoldsMap() return On("rideTram") and TramMoving() and true or false end
function E.RideKind() return R.kind end

-- Preview: play one effect for a few seconds, as if it were happening
function E.RidePreview(kind, secs)
	if not FXF[kind] then return end
	secs = secs or 5
	local now = GetTime()
	R.preview = { kind = kind, stop = now + secs }
	if kind == "hearth" then R.hearth = { spell = 0, start = now, stop = now + secs, to = L["Preview"], preview = true } end
	if kind == "under" then R.breath = { value = 60000 * 0.6, max = 60000, scale = -60000 * 0.5 / secs / 1000, t = now, preview = true } end
	if kind == "lift" then R.liftDir = 1 end
	E.RideChoose()
	C_Timer.After(secs + 0.05, function()
		if R.preview and GetTime() >= R.preview.stop then
			local k = R.preview.kind
			R.preview = nil
			if R.hearth and R.hearth.preview then R.hearth = nil; if On("rideHearth") then R.arriveBy = GetTime() + 5; E.RideArrive() end end
			if R.breath and R.breath.preview then R.breath = nil end
			E.RideChoose()
		end
	end)
end
local ORDER = { "tram", "boat", "zeppelin", "lift", "swim", "under", "ghost", "hearth" }
E.RIDE_ORDER = ORDER
function E.RidePreviewAll(secs)
	secs = secs or 3
	for i, k in ipairs(ORDER) do C_Timer.After((i - 1) * (secs + 0.4), function() E.RidePreview(k, secs) end) end
end

function E.RideChoose()
	local kind
	if R.preview and GetTime() < R.preview.stop and S.mapShown then
		kind = R.preview.kind
	elseif R.hearth and On("rideHearth") and S.mapShown and S.map and S.map:IsShown() and not S.flightOn then
		kind = "hearth"
	elseif TramMoving() then
		-- the tunnel only while the tram moves; standing on the platform is the normal minimap
		kind = On("rideTram") and not S.flightOn and "tram" or nil
	elseif not (S.mapShown and S.map and S.map:IsShown()) or S.flightOn or (UnitOnTaxi and UnitOnTaxi("player")) then
		kind = nil
	elseif UnitIsGhost and UnitIsGhost("player") then
		kind = On("rideGhost") and "ghost" or nil
	elseif R.liftAt and GetTime() - R.liftAt < 1.5 then
		kind = On("rideLift") and "lift" or nil
	elseif R.ride then
		local k = R.ride.kind
		kind = ((k == "boat" and On("rideBoat")) or (k == "zeppelin" and On("rideZeppelin"))) and k or nil
	else
		local _, frac, losing = E.BreathLeft()
		local under = (frac and losing) or (IsSubmerged and IsSubmerged())
		if under then kind = (On("rideSwim") or On("rideBreath")) and "under" or nil
		elseif IsSwimming and IsSwimming() then kind = On("rideSwim") and "swim" or nil end
	end
	if kind ~= R.kind then E.RideShow(kind) end
end

--------------------------------------------------------------------------------
-- The effects
--------------------------------------------------------------------------------

-- One driver for every effect: the ones showing run each frame (about 40 times a
-- second), the rest cost nothing. It counts as "Ride effects" in the performance
-- meter. Busy scenes get fewer particles (Budget), and Reduce motion slows
-- everything down and drops the flashes.
local active = {}
local driver = CreateFrame("Frame")
driver:Hide()
local budget, fpsAcc = 1, 0
function E.RideBudget() return budget end
function E.RideCalm() return Get("rideCalm") == true end
driver:SetScript("OnUpdate", Pathway.Perf.W("Ride effects", function(self, elapsed)
	self.acc = (self.acc or 0) + elapsed
	if self.acc < 0.025 then return end
	local dt = min(self.acc, 0.2)
	self.acc = 0
	fpsAcc = fpsAcc + dt
	if fpsAcc > 1 then
		fpsAcc = 0
		local fps = GetFramerate and GetFramerate() or 60
		local want = fps >= 45 and 1 or (fps >= 30 and 0.7 or (fps >= 20 and 0.45 or 0.3))
		budget = budget + (want - budget) * 0.5
	end
	local k = E.RideCalm() and 0.45 or 1
	local any = false
	for f in pairs(active) do
		any = true
		f.time = (f.time or 0) + dt * k
		f.tick(f, dt * k)
	end
	if not any then self:Hide() end
end))
local function Drive(f, fn)
	f.tick = fn
	f:HookScript("OnShow", function() active[f] = true; driver:Show() end)
	f:HookScript("OnHide", function() active[f] = nil end)
end
E.RideDrive = Drive
-- how many of n particles to show right now
local function Budgeted(n, least) return max(least or 1, floor(n * budget + 0.5)) end

local function Back(level)
	local f = CreateFrame("Frame", nil, S.sc)
	f:SetAllPoints(S.sc)
	f:SetFrameLevel(level or E.PinLevel("PIN_FRAME_LEVEL_MAP_EXPLORATION", 1500) + 2)
	f:EnableMouse(false)
	f:Hide()
	FX.Fades(f, 0.8, 0.6)
	return f
end

-- Streaks that fly past against your heading: wind, foam, speed.
local function Streaks(f, n, r, g, b, a, layer)
	f.streaks = {}
	for i = 1, n do
		local t = Tex(f, layer or "ARTWORK", TEX .. "Ride-Streak", r, g, b, a, "ADD")
		t.base = a
		t:Hide()
		f.streaks[i] = t
	end
end
local function SpawnStreak(s, d, w, h, along)
	-- somewhere ahead of you, so it crosses the map
	local hx, hy = R.hx, R.hy
	local px, py = -hy, hx
	local off = (random() - 0.5) * 1.1 * d
	s.x = hx * d * (along or 0.7) + px * off
	s.y = hy * d * (along or 0.7) + py * off
	s.len = d * (0.14 + random() * 0.2)
	s.speed = d * (0.7 + random() * 0.8)
	s.wob, s.ph = 4 + random() * 6, random() * 6.28
	s.life = 0
end
local function MoveStreaks(f, dt, d, w, h, speedK, wobK)
	local hx, hy = R.hx, R.hy
	local ang = atan2(hy, hx)
	local limit = Budgeted(#f.streaks, 4)
	for si, s in ipairs(f.streaks) do
		if not s.len then SpawnStreak(s, d, w, h, (random() * 2 - 1) * 0.7) end
		s.life = s.life + dt
		s.x = s.x - hx * s.speed * speedK * dt
		s.y = s.y - hy * s.speed * speedK * dt
		local wob = sin(f.time * s.wob + s.ph) * 5 * (wobK or 1)
		local x, y = s.x + -hy * wob, s.y + hx * wob
		if (x * hx + y * hy) < -0.75 * d then SpawnStreak(s, d, w, h) x, y = s.x, s.y end
		s:SetSize(s.len, max(3, d * 0.018))
		s:SetRotation(ang)
		s:ClearAllPoints()
		s:SetPoint("CENTER", f, "CENTER", x, y)
		local fade = Smooth(0, 0.4, s.life) * (1 - Smooth(0.45 * d, 0.75 * d, sqrt(x * x + y * y)))
		s:SetAlpha(si <= limit and fade or 0)
		s:Show()
	end
end

-- Rings that grow from you and fade: wakes and ripples.
local function Ripples(f, n, r, g, b, a)
	f.rip = {}
	for i = 1, n do
		local t = Tex(f, "ARTWORK", TEX .. "Ride-Ring", r, g, b, a, "ADD")
		t:SetPoint("CENTER", S.radarAnchor or f, "CENTER")
		t.age = (i - 1) / n
		f.rip[i] = t
	end
end
local function MoveRipples(f, dt, d, period, reach)
	for _, t in ipairs(f.rip) do
		t.age = (t.age + dt / period) % 1
		local s = d * reach * (0.08 + t.age)
		t:SetSize(s, s)
		t:SetAlpha((1 - t.age) ^ 1.6 * Smooth(0, 0.08, t.age))
	end
end

-- Two layers of water light drifting past each other.
local function Caustics(f, a1, a2, r, g, b)
	f.c1 = Tex(f, "BORDER", TEX .. "Ride-Caustics", r, g, b, a1, "ADD", 1)
	f.c2 = Tex(f, "BORDER", TEX .. "Ride-Caustics", r, g, b, a2, "ADD", 2)
	for _, t in ipairs({ f.c1, f.c2 }) do
		t:SetTexture(TEX .. "Ride-Caustics", "REPEAT", "REPEAT")
		t:SetHorizTile(true); t:SetVertTile(true)
		t:SetAllPoints()
	end
	f.u1, f.v1, f.u2, f.v2 = 0, 0, 0.37, 0.61
end
local function MoveCaustics(f, dt, flow)
	local hx, hy = R.hx, R.hy
	f.u1 = (f.u1 - hx * 0.05 * flow * dt + 0.01 * dt) % 1
	f.v1 = (f.v1 + hy * 0.05 * flow * dt + 0.006 * dt) % 1
	f.u2 = (f.u2 - hx * 0.03 * flow * dt - 0.008 * dt) % 1
	f.v2 = (f.v2 + hy * 0.03 * flow * dt + 0.011 * dt) % 1
	local bob = sin(f.time * 0.9) * 0.02
	f.c1:SetTexCoord(f.u1, f.u1 + 1.6, f.v1 + bob, f.v1 + 1.6 + bob)
	f.c2:SetTexCoord(f.u2, f.u2 + 2.3, f.v2 - bob, f.v2 + 2.3 - bob)
end

local function Hud()
	local hud = CreateFrame("Frame", nil, S.overlay)
	hud:SetAllPoints(S.overlay)
	hud:SetFrameLevel(S.overlay:GetFrameLevel() + 30)
	hud:EnableMouse(false)
	hud:Hide()
	hud.shade = FX.Tex(hud, "BACKGROUND", "Glow", 0, 0, 0, 0.6)
	Mask(hud.shade)
	local function line(r, g, b)
		local fs = hud:CreateFontString(nil, "OVERLAY", "GameFontNormal")
		fs:SetTextColor(r, g, b)
		fs:SetWordWrap(false)
		fs:SetShadowOffset(1, -1); fs:SetShadowColor(0, 0, 0, 0.9)
		return fs
	end
	hud.dest = line(1, 0.82, 0.3)
	hud.time = line(1, 1, 1)
	FX.Fades(hud, 0.5, 0.4)
	return hud
end
function E.RideHudLayout()
	local hud = S.rideHud
	if not hud then return end
	local d = E.Diameter()
	local font = GameFontNormal:GetFont()
	hud.dest:SetFont(font, max(10, floor(d * 0.042 + 0.5)), "OUTLINE")
	hud.time:SetFont(font, Clamp(floor(d * 0.075 + 0.5), 14, 26), "OUTLINE")
	local inset = S.round and d * 0.12 or 8
	hud.time:ClearAllPoints(); hud.time:SetPoint("BOTTOM", hud, "BOTTOM", 0, inset)
	hud.dest:ClearAllPoints(); hud.dest:SetPoint("BOTTOM", hud.time, "TOP", 0, 1)
	hud.dest:SetWidth(d * 0.7)
	hud.shade:ClearAllPoints(); hud.shade:SetPoint("BOTTOM", hud, "BOTTOM", 0, inset - d * 0.06)
	hud.shade:SetSize(d * 0.9, d * 0.32)
end
-- the edge fills up as the ride goes on (like flight mode), and a soft chime
-- ten seconds before you arrive
function E.RideProgress(r, left)
	local ring = S.rideRing
	if not (ring and r) then return end
	local total = (GetTime() - r.start) + max(0, left)
	local frac = total > 0 and Clamp(1 - max(0, left) / total, 0, 1) or 0
	if Get("flightRing") ~= false then
		if not S.rideRingFrame:IsShown() then E.LayoutProgress(ring, { 0.45, 0.85, 1 }); FX.FadeIn(S.rideRingFrame) end
		E.DrawProgress(ring, frac)
	end
	if left <= 10 and left > 0 and not r.chimed then
		r.chimed = true
		if Get("flightChime") ~= false and _G.SOUNDKIT and _G.SOUNDKIT.MAP_PING then PlaySound(_G.SOUNDKIT.MAP_PING) end
	end
end

local function Clock(secs)
	secs = max(0, floor(secs + 0.5))
	return format("%d:%02d", floor(secs / 60), secs % 60)
end

-- The words while you ride: where to, and how long is left.
function E.RideHudText(kind)
	local hud = S.rideHud
	local dest, time = "", ""
	local r = R.ride
	if kind == "tram" then
		local sw, ifg = C_Map.GetMapInfo(1453), C_Map.GetMapInfo(1455)
		local to = R.outside and ifg and R.outside == ifg.name and sw or ifg
		if R.outside and sw and R.outside == sw.name then to = ifg end
		dest = to and format(L["To %s"], to.name) or ""
		local learned = Learned().tram
		if r and learned then
			local left = learned - (GetTime() - r.start)
			time = Clock(left); E.RideProgress(r, left)
		end
	elseif (kind == "boat" or kind == "zeppelin") and r and r.t then
		dest = r.key or ""
		local inst, wx, wy = P:PlayerPos()
		local i, x, y = TransportEnd(r.t[r.from == "a" and "b" or "a"])
		local learned = Learned()[r.key]
		local left
		if inst and i == inst and x and (R.speed or 0) > 2 then
			left = sqrt((x - wx) ^ 2 + (y - wy) ^ 2) / R.speed
		elseif learned then
			left = learned - (GetTime() - r.start)
		end
		if left then time = Clock(left); E.RideProgress(r, left) end
	elseif kind == "preview" then
		dest = L["Preview"]
	elseif kind == "hearth" and R.hearth then
		dest = R.hearth.to and R.hearth.to ~= "" and R.hearth.to or ""
		time = format("%.1f", max(0, R.hearth.stop - GetTime()))
	elseif kind == "under" and On("rideBreath") then
		local left, frac = E.BreathLeft()
		if left then
			dest = frac < 0.15 and "|cffff5544" .. L["Swim up!"] .. "|r" or (frac < 0.35 and "|cffffb040" .. L["Air running out"] .. "|r" or L["Air"])
			time = Clock(left / 1000)
		end
	end
	if R.preview and dest == "" then dest = L["Preview"] end
	hud.dest:SetText(dest); hud.time:SetText(time)
	return dest ~= "" or time ~= ""
end

--------------------------------------------------------------------------------
-- Building each effect
--------------------------------------------------------------------------------
function E.SetupRides()
	if S.rideSetUp or not S.sc then return end
	S.rideSetUp = true

	-- The tram: a rainbow tunnel rushing at you, over everything (no map covers the tram).
	local tun = CreateFrame("Frame", nil, S.map)
	tun:SetAllPoints(S.sc)
	tun:SetFrameLevel(9380)
	tun:EnableMouse(false)
	tun:Hide()
	FX.Fades(tun, 0.8, 0.6)
	tun.bg = Wash(tun, 0.02, 0.0, 0.05, 1)
	tun.glow = Tex(tun, "BORDER", TEX .. "Flight-Glow", 0.6, 0.5, 1, 0.55, "ADD")
	tun.rings, tun.rays = {}, {}
	for i = 1, 18 do
		local t = Tex(tun, "ARTWORK", TEX .. "Ride-Ring", 1, 1, 1, 1, "ADD")
		t.z, t.h = i / 18, (i / 18 * 0.8) % 1
		tun.rings[i] = t
	end
	for i = 1, 16 do
		local t = Tex(tun, "OVERLAY", TEX .. "Ride-Streak", 1, 1, 1, 1, "ADD")
		t.a, t.s, t.h = random() * 2 * pi, 0.05 + random() * 0.9, random()
		tun.rays[i] = t
	end
	tun.core = Tex(tun, "OVERLAY", TEX .. "Flight-Glow", 1, 1, 1, 0.9, "ADD")
	Drive(tun, function(self, dt)
		local d = E.Diameter()
		local riding = (R.ride or R.preview) and true or false
		self.speed = (self.speed or 0.3) + ((riding and 1.5 or 0.35) - (self.speed or 0.3)) * min(1, dt * 1.5)
		local sp, t = self.speed, self.time
		local nRings, nRays = Budgeted(#self.rings, 8), E.RideCalm() and 0 or Budgeted(#self.rays, 4)
		for ri, r in ipairs(self.rings) do
			r.z = r.z - sp * 0.32 * dt
			if r.z <= 0.035 then r.z = r.z + 1; r.h = (t * 0.13) % 1 end
			local z = r.z
			local s = d * 0.075 / z
			local cx = d * 0.16 * sin(t * 0.55 + z * 2.4) * z
			local cy = d * 0.13 * cos(t * 0.42 + z * 1.9) * z
			local cr, cg, cb = HSV((r.h + z * 0.25) % 1, 0.85, 1)
			r:SetVertexColor(cr, cg, cb)
			r:SetAlpha(ri <= nRings and Smooth(1, 0.78, z) * (1 - Smooth(1.25 * d, 2.1 * d, s)) * 0.95 or 0)
			r:SetSize(s, s)
			r:ClearAllPoints(); r:SetPoint("CENTER", self, "CENTER", cx, cy)
		end
		for ai, r in ipairs(self.rays) do
			r.s = r.s * (1 + sp * 1.6 * dt) + sp * 0.02 * dt
			if r.s > 1.3 then r.s, r.a, r.h = 0.04 + random() * 0.05, random() * 2 * pi, (t * 0.13 + random() * 0.3) % 1 end
			local dist = r.s * d * 0.5
			local len = d * 0.05 + r.s * d * 0.32
			local cr, cg, cb = HSV(r.h, 0.5, 1)
			r:SetVertexColor(cr, cg, cb)
			r:SetSize(len, max(2, d * 0.012 * (0.5 + r.s)))
			r:SetRotation(r.a)
			r:ClearAllPoints(); r:SetPoint("CENTER", self, "CENTER", cos(r.a) * dist, sin(r.a) * dist)
			r:SetAlpha(ai <= nRays and Smooth(0.04, 0.2, r.s) * (1 - Smooth(0.9, 1.3, r.s)) * (0.35 + 0.5 * min(1, sp)) or 0)
		end
		local pulse = 0.75 + 0.25 * sin(t * 3)
		-- the real tram map breathes through the tunnel: the dark thins in slow waves and the
		-- game's picture of the line (you on it) shows under the rainbow, then sinks back
		local see = S.detail and S.radarEmbedded and S.radarVisible
		local wave = see and (0.5 - 0.5 * cos(t * 0.9)) or 0
		self.see = (self.see or 0) + (wave - (self.see or 0)) * min(1, dt * 3)
		self.bg:SetAlpha(1 - 0.72 * self.see)
		self.glow:SetSize(d * 0.7, d * 0.7); self.glow:SetAlpha(0.35 * pulse * (1 - 0.4 * self.see))
		local gr, gg, gb = HSV((t * 0.13) % 1, 0.6, 1)
		self.glow:SetVertexColor(gr, gg, gb)
		self.core:SetSize(d * 0.07 * pulse, d * 0.07 * pulse)
		self.hudAcc = (self.hudAcc or 0) + dt
		if self.hudAcc > 0.5 then self.hudAcc = 0; E.RideHudText("tram") end
	end)
	FXF.tram = tun

	-- Boats and ferries: water light, a wake behind you, foam going by.
	local water = Back()
	water.tint = Wash(water, 0.04, 0.22, 0.36, 0.22)
	Caustics(water, 0.30, 0.18, 0.55, 0.9, 1)
	Ripples(water, 4, 0.75, 0.95, 1, 0.55)
	Streaks(water, 10, 0.8, 0.95, 1, 0.45)
	water.vignette = FX.Tex(water, "OVERLAY", "Vignette", 0.0, 0.08, 0.16, 0.65); water.vignette:SetAllPoints(); Mask(water.vignette)
	Drive(water, function(self, dt)
		local d, w, h = Size()
		MoveCaustics(self, dt, 1)
		MoveRipples(self, dt, d, 3.2, 0.9)
		MoveStreaks(self, dt, d, w, h, 0.35, 0.6)
		self.hudAcc = (self.hudAcc or 0) + dt
		if self.hudAcc > 0.5 then self.hudAcc = 0; E.RideHudText("boat") end
	end)
	FXF.boat = water

	-- Zeppelins (and anything else that carries you): wind streaming past, clouds below.
	local wind = Back()
	wind.tint = Wash(wind, 0.78, 0.86, 1, 0.08)
	wind.clouds = {}
	for i, c in ipairs({ { 1.0, 0.16 }, { 0.6, 0.1 } }) do
		local t = wind:CreateTexture(nil, "BORDER", nil, i)
		t:SetTexture(TEX .. "Flight-Clouds", "REPEAT", "REPEAT")
		t:SetAllPoints(); t:SetVertexColor(0.9, 0.94, 1, c[2]); Mask(t)
		t.span, t.u, t.v = c[1] + 0.6, i * 0.3, i * 0.5
		wind.clouds[i] = t
	end
	Streaks(wind, 22, 1, 1, 1, 0.55)
	wind.vignette = FX.Tex(wind, "OVERLAY", "Vignette", 0.55, 0.7, 0.9, 0.35); wind.vignette:SetAllPoints(); Mask(wind.vignette)
	Drive(wind, function(self, dt)
		local d, w, h = Size()
		for i, t in ipairs(self.clouds) do
			t.u = (t.u - R.hx * 0.04 * i * dt) % 1
			t.v = (t.v + R.hy * 0.04 * i * dt) % 1
			t:SetTexCoord(t.u, t.u + t.span, t.v, t.v + t.span)
		end
		MoveStreaks(self, dt, d, w, h, 1, 1.4)
		self.hudAcc = (self.hudAcc or 0) + dt
		if self.hudAcc > 0.5 then self.hudAcc = 0; E.RideHudText("zeppelin") end
	end)
	FXF.zeppelin = wind

	-- Lifts: bands of light sliding the way you go.
	local lift = Back()
	lift.tint = Wash(lift, 1, 0.85, 0.55, 0.08)
	lift.bands = {}
	for i = 1, 5 do
		local t = Tex(lift, "ARTWORK", TEX .. "Ride-Band", 1, 0.88, 0.6, 0.35, "ADD")
		t.p = (i - 1) / 5
		lift.bands[i] = t
	end
	Drive(lift, function(self, dt)
		local d, w, h = Size()
		local dir = R.liftDir or 1
		for _, t in ipairs(self.bands) do
			t.p = (t.p - dir * 0.45 * dt) % 1
			t:SetSize(w, h * 0.14)
			t:ClearAllPoints(); t:SetPoint("CENTER", self, "CENTER", 0, (t.p - 0.5) * h * 1.2)
			t:SetAlpha(sin(t.p * pi))
		end
	end)
	FXF.lift = lift

	-- Swimming: light on the water and soft ripples.
	local swim = Back()
	swim.tint = Wash(swim, 0.05, 0.3, 0.42, 0.12)
	Caustics(swim, 0.2, 0.1, 0.6, 0.95, 1)
	Ripples(swim, 3, 0.8, 1, 1, 0.4)
	Drive(swim, function(self, dt)
		local d = E.Diameter()
		MoveCaustics(self, dt, 0.4)
		MoveRipples(self, dt, d, 4, 0.6)
	end)
	FXF.swim = swim

	-- Underwater: deep blue, wavering light, bubbles rising, and an air gauge
	-- round the edge that turns amber, then red, before you run out of breath.
	local under = Back()
	under.tint = Wash(under, 0.01, 0.1, 0.24, 0.4)
	Caustics(under, 0.24, 0.14, 0.45, 0.8, 1)
	under.vignette = FX.Tex(under, "OVERLAY", "Vignette", 0.0, 0.03, 0.1, 0.7); under.vignette:SetAllPoints(); Mask(under.vignette)
	under.bubbles = {}
	for i = 1, 14 do
		local t = Tex(under, "OVERLAY", TEX .. "Ride-Bubble", 0.85, 0.97, 1, 0.7)
		t.y = random(); t.x = random() - 0.5; t.k = 0.6 + random() * 0.8; t.ph = random() * 6.28
		under.bubbles[i] = t
	end
	Drive(under, function(self, dt)
		local d, w, h = Size()
		MoveCaustics(self, dt, 0.25)
		local _, frac = E.BreathLeft()
		frac = frac or 1
		local breath = On("rideBreath")
		-- fewer bubbles as your air runs out
		local show = min(breath and Clamp(floor(14 * (0.3 + frac * 0.7) + 0.5), 3, 14) or 14, Budgeted(14, 3))
		for i, t in ipairs(self.bubbles) do
			t.y = t.y + dt * 0.12 * t.k
			if t.y > 1 then t.y, t.x = 0, random() - 0.5 end
			local s = d * 0.03 * t.k
			t:SetSize(s, s)
			t:ClearAllPoints()
			t:SetPoint("CENTER", self, "CENTER", t.x * w * 0.8 + sin(self.time * 2 * t.k + t.ph) * 4, (t.y - 0.5) * h)
			t:SetAlpha(i <= show and Smooth(0, 0.1, t.y) * (1 - Smooth(0.85, 1, t.y)) or 0)
		end
		-- low on air: the edge closes in and pulses, faster as it gets worse
		local warn = breath and (1 - Smooth(0.12, 0.4, frac)) or 0
		local rate = 2 + warn * 6
		self.vignette:SetVertexColor(0.02 + warn * 0.5, 0.03, 0.1 - warn * 0.08, 0.7 + warn * 0.25 * (0.5 + 0.5 * sin(self.time * rate)))
		if S.rideAir and breath then
			local c = frac < 0.15 and { 1, 0.3, 0.25 } or (frac < 0.35 and { 1, 0.7, 0.25 } or { 0.45, 0.85, 1 })
			if c[1] ~= self.lastC then self.lastC = c[1]; E.LayoutProgress(S.rideAir, c) end
			E.DrawProgress(S.rideAir, frac)
			S.rideAir:SetAlpha(warn > 0 and (0.75 + 0.25 * sin(self.time * rate)) or 0.85)
		end
		self.hudAcc = (self.hudAcc or 0) + dt
		if self.hudAcc > 0.25 then self.hudAcc = 0; local has = E.RideHudText("under"); S.rideHud:SetShown(has) end
	end)
	FXF.under = under
	local air = CreateFrame("Frame", nil, S.map)
	air:SetAllPoints(S.sc)
	air:SetFrameLevel(9455)
	air:EnableMouse(false)
	air:Hide()
	FX.Fades(air, 0.6, 0.5)
	S.rideAir = E.NewProgress(air)
	S.rideAirFrame = air
	local rr = CreateFrame("Frame", nil, S.map)
	rr:SetAllPoints(S.sc)
	rr:SetFrameLevel(9455)
	rr:EnableMouse(false)
	rr:Hide()
	FX.Fades(rr, 0.6, 0.5)
	S.rideRing = E.NewProgress(rr)
	S.rideRingFrame = rr

	-- A ghost: the spirit world, cold and hazy, with wisps drifting up.
	local ghost = Back()
	ghost.tint = Wash(ghost, 0.5, 0.58, 0.72, 0.34)
	ghost.vignette = FX.Tex(ghost, "ARTWORK", "Vignette", 0.08, 0.12, 0.22, 0.75); ghost.vignette:SetAllPoints(); Mask(ghost.vignette)
	ghost.wisps = {}
	for i = 1, 9 do
		local t = Tex(ghost, "OVERLAY", TEX .. "Flight-Glow", 0.75, 0.88, 1, 0.3, "ADD")
		t.y, t.x, t.k, t.ph = random(), random() - 0.5, 0.5 + random(), random() * 6.28
		ghost.wisps[i] = t
	end
	Drive(ghost, function(self, dt)
		local d, w, h = Size()
		local nW = Budgeted(#self.wisps, 3)
		for wi, t in ipairs(self.wisps) do
			t.y = t.y + dt * 0.035 * t.k
			if t.y > 1 then t.y, t.x = 0, random() - 0.5 end
			local s = d * (0.12 + 0.1 * t.k)
			t:SetSize(s, s * 0.7)
			t:ClearAllPoints()
			t:SetPoint("CENTER", self, "CENTER", t.x * w * 0.9 + sin(self.time * 0.6 * t.k + t.ph) * d * 0.05, (t.y - 0.5) * h)
			t:SetAlpha(wi <= nW and Smooth(0, 0.2, t.y) * (1 - Smooth(0.75, 1, t.y)) or 0)
		end
		self.tint:SetAlpha(0.3 + 0.05 * sin(self.time * 0.8))
	end)
	FXF.ghost = ghost

	-- Hearthing: light spirals in to you, a rune ring turns from blue to gold,
	-- and the middle burns brighter until you're gone.
	local hf = CreateFrame("Frame", nil, S.map)
	hf:SetAllPoints(S.sc)
	hf:SetFrameLevel(9385)
	hf:EnableMouse(false)
	hf:Hide()
	FX.Fades(hf, 0.4, 0.5)
	hf.dim = Wash(hf, 0.02, 0.03, 0.08, 0.35)
	hf.vignette = FX.Tex(hf, "BORDER", "Vignette", 0.05, 0.08, 0.25, 0.8); hf.vignette:SetAllPoints(); Mask(hf.vignette)
	hf.ring = Tex(hf, "ARTWORK", TEX .. "Ride-Ring", 0.5, 0.75, 1, 0.8, "ADD")
	hf.ring2 = Tex(hf, "ARTWORK", TEX .. "Ride-Ring", 1, 0.85, 0.45, 0.5, "ADD")
	hf.core = Tex(hf, "OVERLAY", TEX .. "Flight-Glow", 1, 0.9, 0.6, 0.9, "ADD")
	hf.flashT = Wash(hf, 1, 0.97, 0.88, 0, "OVERLAY")
	hf.sparks = {}
	for i = 1, 28 do
		local t = Tex(hf, "OVERLAY", TEX .. "Flight-Glow", 1, 1, 1, 1, "ADD")
		t.a, t.r, t.k = random() * 2 * pi, 0.3 + random() * 0.7, 0.6 + random() * 0.8
		hf.sparks[i] = t
	end
	Drive(hf, function(self, dt)
		local d = E.Diameter()
		local h = R.hearth
		local p = h and Clamp((GetTime() - h.start) / max(0.5, h.stop - h.start), 0, 1) or 1
		local t = self.time
		-- blue to gold as the cast fills
		local cr, cg, cb = 0.45 + 0.55 * p, 0.7 + 0.15 * p, 1 - 0.55 * p
		local swirl = 1.2 + p * 4
		local shown = min(floor(10 + p * 18), Budgeted(28, 8))
		for i, s in ipairs(self.sparks) do
			s.a = s.a + swirl * s.k * dt
			s.r = s.r - (0.08 + p * 0.5) * s.k * dt
			if s.r < 0.04 then s.r, s.a = 0.85 + random() * 0.2, random() * 2 * pi end
			local rr = s.r * d * 0.5
			local sz = d * (0.02 + 0.03 * (1 - s.r)) * (0.7 + p)
			s:SetSize(sz, sz)
			s:SetVertexColor(cr, cg, cb)
			s:ClearAllPoints(); s:SetPoint("CENTER", self, "CENTER", cos(s.a) * rr, sin(s.a) * rr)
			s:SetAlpha(i <= shown and Smooth(0.04, 0.2, s.r) * (1 - Smooth(0.8, 1.05, s.r)) or 0)
		end
		local pulse = 0.5 + 0.5 * sin(t * (3 + p * 9))
		local rs = d * (0.95 - p * 0.35)
		self.ring:SetSize(rs, rs); self.ring:SetVertexColor(cr, cg, cb); self.ring:SetAlpha(0.45 + 0.4 * pulse)
		local r2 = d * (0.4 + 0.5 * ((t * 0.6) % 1))
		self.ring2:SetSize(r2, r2); self.ring2:SetAlpha((1 - (t * 0.6) % 1) * (0.3 + 0.5 * p))
		local cs = d * (0.12 + p * 0.45) * (0.9 + 0.1 * pulse)
		self.core:SetSize(cs, cs); self.core:SetAlpha(0.5 + 0.5 * p)
		self.dim:SetAlpha(0.15 + 0.35 * p)
		if self.flash and self.flash > 0 and not E.RideCalm() then
			self.flash = self.flash - dt
			self.flashT:SetAlpha(Clamp(self.flash / 0.6, 0, 1) * 0.85)
		else
			self.flashT:SetAlpha(0)
		end
		self.hudAcc = (self.hudAcc or 0) + dt
		if self.hudAcc > 0.1 then self.hudAcc = 0; E.RideHudText("hearth") end
	end)
	FXF.hearth = hf

	-- Arriving: a ring of light bursts out from where you land.
	local arr = CreateFrame("Frame", nil, S.map)
	arr:SetAllPoints(S.sc)
	arr:SetFrameLevel(9386)
	arr:EnableMouse(false)
	arr:Hide()
	arr.rings = {}
	for i = 1, 3 do arr.rings[i] = Tex(arr, "OVERLAY", TEX .. "Ride-Ring", 1, 0.88, 0.55, 1, "ADD") end
	arr.core = Tex(arr, "OVERLAY", TEX .. "Flight-Glow", 1, 0.95, 0.8, 1, "ADD")
	Drive(arr, function(self, dt)
		self.t = (self.t or 0) + dt
		local d, t = E.Diameter(), self.t
		local calm = E.RideCalm()
		for i, r in ipairs(self.rings) do
			local k = (calm and i > 1) and 1 or Clamp((t - (i - 1) * 0.18) / 1.3, 0, 1)
			local sz = d * (0.1 + 1.1 * (1 - (1 - k) ^ 3))
			r:SetSize(sz, sz); r:SetAlpha(k > 0 and (1 - k) ^ 1.5 or 0)
		end
		local c = Clamp(1 - t / 0.9, 0, 1)
		self.core:SetSize(d * 0.5 * (1 + t), d * 0.5 * (1 + t)); self.core:SetAlpha(c)
		if t > 1.8 then self:Hide() end
	end)
	S.rideArrive = arr

	S.rideHud = Hud()
	E.RideHudLayout()

	-- watching: five times a second while the minimap is up
	local watch = CreateFrame("Frame")
	watch:SetScript("OnUpdate", Pathway.Perf.W("Minimap", function(self, elapsed)
		self.acc = (self.acc or 0) + elapsed
		if self.acc < TICK then return end
		self.acc = 0
		if Get("rideFx") == false then if R.kind then E.RideShow(nil) end return end
		E.RideTick()
	end))
	for _, ev in ipairs({ "MIRROR_TIMER_START", "MIRROR_TIMER_STOP", "MIRROR_TIMER_PAUSE", "PLAYER_ENTERING_WORLD", "PLAYER_UNGHOST", "PLAYER_ALIVE", "PLAYER_DEAD" }) do
		pcall(watch.RegisterEvent, watch, ev)
	end
	for _, ev in ipairs({ "UNIT_SPELLCAST_START", "UNIT_SPELLCAST_STOP", "UNIT_SPELLCAST_INTERRUPTED", "UNIT_SPELLCAST_FAILED", "UNIT_SPELLCAST_SUCCEEDED" }) do
		if not pcall(watch.RegisterUnitEvent, watch, ev, "player") then pcall(watch.RegisterEvent, watch, ev) end
	end
	watch:SetScript("OnEvent", function(_, event, ...)
		if event:find("^MIRROR") then E.RideMirror(event, ...)
		elseif event:find("^UNIT_SPELLCAST") then E.RideCast(event, ...)
		elseif event == "PLAYER_ENTERING_WORLD" then E.RideLoaded(); C_Timer.After(0.5, E.RideChoose); C_Timer.After(1.2, E.RideArrive)
		else C_Timer.After(0.2, E.RideChoose) end
	end)
	S.rideWatch = watch
end

function E.RideShow(kind)
	if R.kind == "tram" or kind == "tram" then
		-- the tram holds the minimap up while you're in it, and lets it go after
		C_Timer.After(0, E.UpdateVisibility)
	end
	for k, f in pairs(FXF) do
		if k == kind then
			-- over the detail view's picture when it's up, else over the map art and under the icons
			if f.baseLevel == nil then f.baseLevel = f:GetFrameLevel() end
			if f.baseLevel < 9000 then f:SetFrameLevel(S.detail and 9360 or f.baseLevel) end
			FX.FadeIn(f)
		elseif f:IsShown() then FX.FadeOut(f) end
	end
	if S.rideRingFrame and S.rideRingFrame:IsShown() and not (kind == "boat" or kind == "zeppelin" or kind == "tram") then FX.FadeOut(S.rideRingFrame) end
	local air = kind == "under" and On("rideBreath")
	if air then FX.FadeIn(S.rideAirFrame) elseif S.rideAirFrame and S.rideAirFrame:IsShown() then FX.FadeOut(S.rideAirFrame) end
	local hud = S.rideHud
	if hud then
		local words = kind == "tram" or kind == "boat" or kind == "zeppelin" or kind == "under" or kind == "hearth"
		if words then E.RideHudLayout(); E.RideHudText(kind); FX.FadeIn(hud) elseif hud:IsShown() then FX.FadeOut(hud) end
	end
	local was = R.kind
	R.kind = kind
	-- the tram: the game's own tram map comes in under the tunnel (and goes again after)
	if (was == "tram") ~= (kind == "tram") and E.UpdateDetail then C_Timer.After(0, E.UpdateDetail) end
end

-- the words follow the minimap's size and shape, like flight mode's
local flightLayout = E.FlightLayout
E.FlightLayout = function(...) flightLayout(...); E.RideHudLayout() end

-- The settings change: show what's on now.
function E.RideSettingsChanged()
	if not S.rideSetUp then return end
	E.RideChoose()
	E.UpdateVisibility()
end

--------------------------------------------------------------------------------
-- /gmap check: everything on the minimap, tried in front of you. Each ride
-- effect plays for a moment, the terrain zooms in and out, the detailed
-- picture comes and goes, and each step says in chat whether it worked.
--------------------------------------------------------------------------------
local function Say(ok, text) print((ok == nil and "|cff8a929b  " or (ok and "|cff35d07f  ✓ " or "|cffff6b5b  ✗ ")) .. text .. "|r") end
function E.SelfCheck()
	if R.checking then return end
	if not (S.mapShown and S.map:IsShown()) then print("|cff35d07fPath|rway minimap check: the minimap isn't showing (Shift-M shows it).") return end
	R.checking = true
	print("|cff35d07fPath|rway minimap check: about 40 seconds. Keep still for a moment.")
	local _, _, _, inst = UnitPosition("player")
	local mapID = S.map:GetMapID()
	local info = mapID and C_Map.GetMapInfo(mapID)
	Say(nil, format("Here: %s / %s, %s, map %s (%s)", GetZoneText() or "?", GetSubZoneText() or "", (IsIndoors and IsIndoors()) and "indoors" or "outdoors",
		tostring(mapID), info and info.name or "?"))
	local tiles = E.TerrainTiles and E.TerrainTiles(mapID)
	local n = 0
	for _ in pairs(tiles or {}) do n = n + 1 end
	Say(n > 0 or nil, format("Terrain squares for this continent: %d%s", n, n == 0 and " (none: the detailed picture stands in)" or ""))
	local town = Pathway.TownHere and Pathway:TownHere()
	Say(nil, town and format("In town: %s (%d yards round, %s)", town.name, Pathway:TownRadius(town.low),
		(P.db.learned.towns or {})[town.low] and "learned" or "first guess") or "Not in a town")
	local learned, ln = Learned(), 0
	for _ in pairs(learned) do ln = ln + 1 end
	Say(nil, format("Rides timed so far: %d", ln))
	-- every ride effect, one after another
	local t = 1.5
	local names = { tram = "Tram tunnel", boat = "Boat water", zeppelin = "Zeppelin wind", lift = "Lift light", swim = "Swimming",
		under = "Underwater and air gauge", ghost = "Ghost", hearth = "Hearthing" }
	for _, k in ipairs(ORDER) do
		C_Timer.After(t, function() E.RidePreview(k, 2.6) end)
		C_Timer.After(t + 0.9, function()
			local f = FXF[k]
			local ok = f and f:IsShown() and (tonumber(f:GetEffectiveAlpha()) or 1) > 0.05
			Say(ok, names[k] .. (ok and "" or (On("ride" .. (k == "under" and "Swim" or k:gsub("^%l", string.upper))) and " didn't show" or " is turned off")))
		end)
		t = t + 3.1
	end
	-- the terrain up close: zoom in, look, zoom back
	C_Timer.After(t, function()
		if not (E.TerrainOn and E.TerrainOn()) then Say(nil, "Terrain up close: not here (turned off, or no squares)") return end
		local sc = S.sc
		R.checkScale = sc.targetScale or sc:GetCanvasScale()
		local cw, w = S.canvas:GetWidth(), NS.MapYards(S.map:GetMapID())
		if cw and w then sc:SetZoomTarget(min(S.sc:GetWidth(), S.sc:GetHeight()) * w / (cw * 300)) end
	end)
	C_Timer.After(t + 2, function()
		if not R.checkScale then return end
		local T = E.Terrain
		local shown = T.frame:IsShown() and T.alpha > 0.5 and T.used > 0
		local loaded = 0
		for i = 1, T.used do local tx = T.pool[i]; if tx and tx.GetTextureFileID and tx:GetTextureFileID() then loaded = loaded + 1 end end
		Say(shown, format("Terrain up close: %d squares, %d loaded by the game", T.used, loaded))
		S.sc:SetZoomTarget(R.checkScale); R.checkScale = nil
	end)
	t = t + 3.5
	-- the detailed picture: on for a moment, then back
	C_Timer.After(t, function() S.detailForce = true; E.UpdateDetail() end)
	C_Timer.After(t + 1.5, function()
		local ok = S.detail and S.radarEmbedded and (S.radarD or 0) > 20
		Say(ok, format("Detailed picture: %s, %d px", ok and "showing" or "didn't show", floor(S.radarD or 0)))
		S.detailForce = nil; E.UpdateDetail()
	end)
	C_Timer.After(t + 2.5, function()
		R.checking = nil
		print("|cff35d07fPath|rway minimap check: done. A screenshot of this is all I need if anything's off.")
	end)
end
end part() end
-- ==================== GoodMap/Terrain.lua
do local __addon, __ns = ... local function part()
-- Copyright (C) 2026 SoFinSicc. Part of Pathway (curseforge.com/wow/addons/pathway): free software under the GPLv3 or later, with additional terms that require keeping this credit. See LICENSE.md.
--[[ Pathway minimap — terrain up close
     Past the zone map's own detail, the game's minimap terrain fades in under
     every pin: the real ground, roads, houses and docks, drawn from the minimap
     squares already in the game (Data\Terrain.lua lists them). It's part of the
     map itself, so it pans and zooms with it and every pin, your arrow and your
     route sit exactly where they belong. In towns and cities the map zooms in to
     it by itself, and back out as you leave.

     Where the game has no squares (inside buildings and caves, instances), the
     detailed view shows the game's own minimap picture instead (GoodMap.lua). ]]

local ADDON, P = __addon, __ns
local NS = P.GoodMap
local E, S, Mask = NS.E, NS.S, NS.Mask
local MapRect, MapYards, PlayerPos = NS.MapRect, NS.MapYards, NS.PlayerPos
if not (E and S and MapRect) then return end

local floor, min, max, abs = math.floor, math.min, math.max, math.abs
local TILE = 1600 / 3                        -- yards a square: 533 1/3
local TILES = P.TERRAIN_TILES or {}

local function Get(k) return E.Get(k) end
local function Clamp(v, a, b) return v < a and a or (v > b and b or v) end
local function Smooth(e0, e1, x) local t = Clamp((x - e0) / (e1 - e0), 0, 1) return t * t * (3 - 2 * t) end

local T = { pool = {}, used = 0, alpha = 0 }
E.Terrain = T

-- the squares this map's continent has (nil when there are none)
function E.TerrainTiles(mapID)
	local r = mapID and MapRect(mapID)
	return r and r[5] and TILES[r[5]], r
end
function E.TerrainOn()
	return Get("detailTerrain") ~= false and Get("detailView") ~= false and E.TerrainTiles(S.map and S.map:GetMapID()) ~= nil
end

-- how much terrain shows: none at zone-map distance, all of it once the map
-- shows less than the game's widest minimap view (about 470 yards across)
function E.TerrainAlphaFor(viewYards)
	if not viewYards then return 0 end
	local py = E.PictureYards()
	return 1 - Smooth(py * 1.0, py * 1.9, viewYards)
end

function E.SetupTerrain()
	if T.frame or not S.canvas then return end
	local f = CreateFrame("Frame", nil, S.canvas)
	f:SetAllPoints(S.canvas)
	-- over the map's art and its explored areas, under the radar and every pin
	f:SetFrameLevel(E.PinLevel("PIN_FRAME_LEVEL_MAP_EXPLORATION", 1500) + 1)
	f:EnableMouse(false)
	f:SetAlpha(0)
	f:Hide()
	T.frame = f
end

local function Tile(i)
	local t = T.pool[i]
	if not t then
		t = T.frame:CreateTexture(nil, "BACKGROUND")
		-- a hair inset, so neighbouring squares meet without a seam
		t:SetTexCoord(0.5 / 256, 255.5 / 256, 0.5 / 256, 255.5 / 256)
		Mask(t)
		T.pool[i] = t
	end
	return t
end

-- Place the squares around what the window shows (and a square beyond, so
-- panning doesn't uncover an edge). Squares are on the map canvas, so they
-- move and scale with it: only a change of view range redraws them.
function E.TerrainUpdate()
	local f = T.frame
	if not f then return end
	local mapID = S.map:GetMapID()
	local tiles, r = E.TerrainTiles(mapID)
	local a = 0
	if tiles and Get("detailTerrain") ~= false and Get("detailView") ~= false and not S.flightOn and not S.houseActive then
		a = E.TerrainAlphaFor(E.ViewYards())
		-- the indoor picture covers it anyway
		if S.detail then a = 0 end
	end
	if a ~= T.alpha then
		T.alpha = a
		f:SetAlpha(a)
	end
	if a <= 0.001 then
		if f:IsShown() then f:Hide() end
		T.key = nil
		return
	end
	if not f:IsShown() then f:Show() end
	local sc, cv = S.sc, S.canvas
	local cw, ch = cv:GetWidth(), cv:GetHeight()
	local scale = sc:GetCanvasScale()
	local cx, cy = sc:GetCurrentScrollX(), sc:GetCurrentScrollY()
	if not (cw and cw > 0 and ch and ch > 0 and scale and scale > 0 and type(cx) == "number" and type(cy) == "number") then return end
	-- the view in map coordinates, then in world yards (r: north, west at the map's top left; size)
	local hw, hh = sc:GetWidth() / (cw * scale) * 0.5, sc:GetHeight() / (ch * scale) * 0.5
	local x0, x1, y0, y1 = cx - hw, cx + hw, cy - hh, cy + hh
	local west0, west1 = r[2] + x0 * r[4], r[2] + x1 * r[4]
	local north0, north1 = r[1] + y0 * r[3], r[1] + y1 * r[3]
	local tx0 = floor(32 - max(west0, west1) / TILE) - 1
	local tx1 = floor(32 - min(west0, west1) / TILE) + 1
	local ty0 = floor(32 - max(north0, north1) / TILE) - 1
	local ty1 = floor(32 - min(north0, north1) / TILE) + 1
	local key = mapID .. ":" .. tx0 .. ":" .. tx1 .. ":" .. ty0 .. ":" .. ty1 .. ":" .. floor(cw) .. ":" .. floor(ch)
	if key == T.key then return end
	T.key = key
	local n = 0
	for tx = max(0, tx0), min(63, tx1) do
		for ty = max(0, ty0), min(63, ty1) do
			local fid = tiles[tx * 64 + ty]
			if fid then
				-- the square's top left in the world, then on the canvas
				local west, north = (32 - tx) * TILE, (32 - ty) * TILE
				local nx, ny = (west - r[2]) / r[4], (north - r[1]) / r[3]
				local sw, sh = TILE / abs(r[4]) * cw, TILE / abs(r[3]) * ch
				n = n + 1
				local t = Tile(n)
				if t.fid ~= fid then t:SetTexture(fid); t.fid = fid end
				t:ClearAllPoints()
				t:SetPoint("TOPLEFT", cv, "TOPLEFT", nx * cw, -ny * ch)
				t:SetSize(sw, sh)
				t:Show()
			end
		end
	end
	for i = n + 1, T.used do T.pool[i]:Hide() end
	T.used = n
end

-- more zoom steps past the zone map's own closest, down to about 100 yards
-- across, so the terrain can be looked at up close
function E.TerrainZoomLevels(levels)
	if Get("detailTerrain") == false or Get("detailView") == false or not levels or #levels == 0 then return end
	if not E.TerrainTiles(S.map and S.map:GetMapID()) then return end
	local last = levels[#levels]
	local s = last.scale
	local guard = 0
	while guard < 20 do
		local v = E.ViewYards(s)
		if not v or v <= 100 then break end
		s = s * 1.25
		levels[#levels + 1] = { scale = s, layerIndex = last.layerIndex }
		guard = guard + 1
	end
end

--------------------------------------------------------------------------------
-- Towns and cities: the map zooms in to the terrain while you're there, and
-- back out to where it was as you leave (unless you've zoomed yourself since).
--------------------------------------------------------------------------------
function E.TownZoom(inTown)
	local sc = S.sc
	if not (sc and sc.SetZoomTarget) then return end
	if inTown and not T.townPrev then
		local v = E.ViewYards()
		local py = E.PictureYards()
		if not v or v <= py then return end           -- already as close as the terrain
		local cw = S.canvas:GetWidth()
		local w = MapYards(S.map:GetMapID())
		if not (w and cw and cw > 0) then return end
		local want = min(sc:GetWidth(), sc:GetHeight()) * w / (cw * py * 0.85)
		local levels = sc.zoomLevels
		if levels and levels[#levels] and levels[#levels].scale then want = min(want, levels[#levels].scale) end
		T.townPrev, T.townSet = sc.targetScale or sc:GetCanvasScale(), want
		sc:SetZoomTarget(want)
	elseif not inTown and T.townPrev then
		local prev, set = T.townPrev, T.townSet
		T.townPrev, T.townSet = nil, nil
		local now = sc.targetScale or sc:GetCanvasScale()
		-- only if the zoom is still what the town set: your own zoom wins
		if set and abs(now - set) / set < 0.05 then sc:SetZoomTarget(prev) end
	end
end
end part() end
-- ==================== Fishing/FishingBlinker.lua
do local __addon, __ns = ... local function part()
-- Copyright (C) 2026 SoFinSicc. Part of Pathway (curseforge.com/wow/addons/pathway): free software under the GPLv3 or later, with additional terms that require keeping this credit. See LICENSE.md.
--[[----------------------------------------------------------------------------
  Lil's Fishing Blinker 2.0                            Retail / Midnight 12.x

  A cinematic fishing companion. Scroll up to cast, scroll down to reel in.

  The constitution
    * Elegant, fast, clean - like the rest of the Lil's family.
    * One hardware input = one game action. Nothing casts, loots, equips or
      clicks on its own. No ads, no donation links.
    * Combat-safe: never touches protected state in combat; bails out cleanly.
    * Leaves no mess: every CVar, binding and faded frame is put back, even
      after a /reload, a crash or a combat interruption.
    * Honest data: fish, rates and spots are learned from your own catches.
    * Native look: built on the game's own templates and fonts (portrait
      window, inset panels, panel buttons, Options > AddOns page), so it fits
      in and UI skins restyle it with everything else.

  Performance model
    * Nothing runs while you're not fishing.
    * While fishing: animations run on the GPU; the only per-frame code is the
      bite-timer ring, which runs while the line is in the water.
    * Bag scans are coalesced, and each item's tooltip is read once, ever.

  With Lil's GoodMap installed, the map turns into a fishing map while you
  fish: water glow, bite-timer ring, ripples, session info and your spots.
------------------------------------------------------------------------------]]

local ADDON_NAME, P = __addon, __ns
local NS = P.Fishing            -- Fishing Blinker lives inside Pathway as its fishing module
local VERSION = "2.0"
local TITLE = "Fishing Blinker"
local BRAND = "|cffa875ffFishing|r Blinker"
local ICON = "Interface\\Icons\\INV_Fishingpole_02"
local MEDIA = "Interface\\AddOns\\" .. ADDON_NAME .. "\\Fishing\\Media\\"
-- WoW: Forever runs on the Classic client: fill in what it doesn't have
local C_Item, C_Container = P.Item, P.Container
local C_AddOns = C_AddOns or { IsAddOnLoaded = IsAddOnLoaded, LoadAddOn = LoadAddOn }
local CIRCLE = "Interface\\CharacterFrame\\TempPortraitAlphaMask"

local _G = _G
local pairs, ipairs, type, tonumber, tostring, next, pcall = pairs, ipairs, type, tonumber, tostring, next, pcall
local floor, max, min, abs, sin, cos, PI = math.floor, math.max, math.min, math.abs, math.sin, math.cos, math.pi
local format, tsort, tconcat = string.format, table.sort, table.concat

-- Functions and frames live in tables to stay far below Lua's local limits.
local F = {}      -- core functions
local UI = {}     -- window
local FX = {}     -- screen cues
local GM = {}     -- GoodMap fishing map
local S = {}      -- runtime state
local db

-- Shared suite palette (same values as Lil's BankCrafter).
local C = {
    accent = {0.66, 0.46, 1.00},
    good   = {0.30, 0.90, 0.40},
    bad    = {1.00, 0.35, 0.30},
    warn   = {1.00, 0.70, 0.20},
    muted  = {0.60, 0.60, 0.60},
    gold   = {1.00, 0.82, 0.20},
}
local function Hex(c) return format("|cff%02x%02x%02x", c[1] * 255, c[2] * 255, c[3] * 255) end
local ACCENT, GOOD, MUTED = Hex(C.accent), Hex(C.good), Hex(C.muted)

--------------------------------------------------------------------------------
-- Static data
--------------------------------------------------------------------------------
-- Known Fishing channel IDs. Anything else is matched by spell name, so new
-- expansion variants work without an update.
local FISHING_IDS = {
    [7620] = true, [7731] = true, [7732] = true, [18248] = true, [33095] = true,
    [51294] = true, [88868] = true, [110508] = true, [131474] = true, [131476] = true,
    [131490] = true, [271392] = true, [312784] = true, [376518] = true, [394747] = true,
    [433555] = true,
}
local FISHING_BASE_ID = 131474

-- Classic lures and hats we can recognise by ID. Everything newer is found by
-- reading its tooltip, so this list never needs to grow.
local KNOWN_LURES = {
    [6529] = 1, [6530] = 2, [6532] = 3, [6533] = 4, [34861] = 5, [46006] = 5, [118391] = 6,
}
local KNOWN_HATS = { -- itemID = {priority, has a lure use}
    [117405] = {5, true}, [118393] = {4, false}, [88710] = {3, true}, [33820] = {2, true}, [19972] = {1, false},
}

-- Sounds are picked by SOUNDKIT name, never raw numbers.
local SOUNDS = {
    "NONE", "None", "READY_CHECK", "Ready Check", "RAID_WARNING", "Raid Warning",
    "IG_QUEST_LIST_COMPLETE", "Quest Complete", "TELL_MESSAGE", "Whisper", "MAP_PING", "Map Ping",
    "ALARM_CLOCK_WARNING_3", "Alarm Clock",
}
for i = #SOUNDS - 1, 3, -2 do
    if not (SOUNDKIT and SOUNDKIT[SOUNDS[i]]) then table.remove(SOUNDS, i + 1); table.remove(SOUNDS, i) end
end

local DEFAULTS = {
    schema = 3,
    -- fishing mode
    bindMouse = true, autoLoot = true, cinematicMode = true, showWindow = true, idleTimeout = 45, showCountdown = true,
    tooltip = true, showSmartLure = true,
    -- GoodMap
    mapFX = true, mapSpots = "FISHING", mapInfo = true,
    -- screen cues
    showStatus = true, showRing = true,
    showCast = true, castColor = "99ff5a6e",
    showWater = true, waterColor = "664da6ff",
    showCatch = true, catchColor = "9945e07a",
    -- audio
    isolateAudio = true, targetSFX = 1.0, targetAmbience = 0.0,
    castSound = "NONE", catchSound = "READY_CHECK", newFishSound = "IG_QUEST_LIST_COMPLETE",
}

--------------------------------------------------------------------------------
-- Helpers
--------------------------------------------------------------------------------
local function Clamp01(v) if v < 0 then return 0 elseif v > 1 then return 1 end return v end
local function IsSecret(v) return _G.issecretvalue ~= nil and _G.issecretvalue(v) or false end

local function Print(msg, color)
    DEFAULT_CHAT_FRAME:AddMessage(format("%s:|r |cff%s%s|r", BRAND, color or "ffffff", msg))
end

local function HexRGBA(hex)
    local a, r, g, b = tostring(hex):match("^(%x%x)(%x%x)(%x%x)(%x%x)$")
    if not a then return 1, 1, 1, 1 end
    return tonumber(r, 16) / 255, tonumber(g, 16) / 255, tonumber(b, 16) / 255, tonumber(a, 16) / 255
end

local function PlayChoice(key)
    local id = key and key ~= "NONE" and SOUNDKIT and SOUNDKIT[key]
    if id then PlaySound(id, "Master") end
end

-- Creates a frame from a template, falling back to a plain frame if the
-- template ever disappears from the game (same as Lil's BankCrafter).
local function Make(kind, name, parent, template, fallback)
    local ok, f = pcall(CreateFrame, kind, name, parent, template)
    if ok and f then return f end
    return CreateFrame(kind, name, parent, fallback)
end

local function Text(parent, font, justify)
    local fs = parent:CreateFontString(nil, "OVERLAY", font or "GameFontHighlight")
    fs:SetJustifyH(justify or "LEFT")
    return fs
end

local function NewSession()
    S.session = {start = GetTime(), casts = 0, catches = 0, catchTime = 0, fish = {}, new = {}, announced = false}
    S.target = S.target or {}
    S.target.casts, S.target.hits, S.target.announced = 0, 0, false
end
NewSession()
S.castSerial, S.loggedSerial, S.lastCastTime, S.lastStopTime = 0, 0, 0, 0

-- Every frame we own lives under one root, so clean-screen mode can tell
-- ours from everyone else's.
local root = CreateFrame("Frame", "FB_Root", UIParent)
root:SetAllPoints(UIParent)

--------------------------------------------------------------------------------
-- CVars: saved before change, restored on exit. A restore that fails (a
-- protected CVar mid-combat) is kept and retried later, never lost.
--------------------------------------------------------------------------------
local function CVarMatches(name, value)
    local cur = GetCVar(name)
    if cur == nil then return true end
    return cur == tostring(value) or (tonumber(cur) ~= nil and tonumber(cur) == tonumber(value))
end

function F.SetCVar(name, value)
    db.restore = db.restore or {}
    if db.restore[name] == nil then db.restore[name] = GetCVar(name) end
    pcall(SetCVar, name, value)
end

function F.RestoreCVar(name)
    local r = db.restore
    if not (r and r[name] ~= nil) then return end
    pcall(SetCVar, name, r[name])
    if CVarMatches(name, r[name]) then r[name] = nil end
    if next(r) == nil then db.restore = nil end
end

function F.RestoreCVars()
    local r = db and db.restore
    if not r then return true end
    for name, value in pairs(r) do
        pcall(SetCVar, name, value)
        if CVarMatches(name, value) then r[name] = nil end
    end
    if next(r) == nil then db.restore = nil; return true end
    return false
end

-- The mouse-wheel override lives on a secure driver that drops it the instant
-- combat starts, from the secure environment, so it works even in combat.
local driver = CreateFrame("Frame", "FB_Driver", UIParent, "SecureHandlerStateTemplate")
driver:SetAttribute("_onstate-combat", [[ if newstate == "1" then self:ClearBindings() end ]])
RegisterStateDriver(driver, "combat", "[combat] 1; 0")

--------------------------------------------------------------------------------
-- Data: everything learned from your own catches.
--   db.log[fish] = {id, total (items), catches, zones = {[zone] = {n, q, spots = {[cell] = {m,x,y,n}}}}}
--   db.zoneStats[zone] = {casts, catches}
--------------------------------------------------------------------------------
function F.Zone()
    local z = GetRealZoneText()
    if not z or z == "" then z = GetZoneText() end
    if not z or z == "" then z = "Unknown Waters" end
    return z
end

function F.PlayerSpot()
    if not (C_Map and C_Map.GetBestMapForUnit) then return end
    local mapID = C_Map.GetBestMapForUnit("player")
    if not mapID then return end
    local pos = C_Map.GetPlayerMapPosition(mapID, "player")
    if not pos then return end
    local x, y = pos:GetXY()
    if not x or not y or IsSecret(x) or (x == 0 and y == 0) then return end
    return mapID, x, y
end

function F.ZoneStats(zone)
    local s = db.zoneStats[zone]
    if not s then s = {casts = 0, catches = 0}; db.zoneStats[zone] = s end
    return s
end

local function FishRecord(name)
    local rec = db.log[name]
    if not rec then rec = {total = 0, catches = 0, zones = {}}; db.log[name] = rec end
    return rec
end

local function ZoneRecord(rec, zone)
    local z = rec.zones[zone]
    if not z then z = {n = 0, q = 0, spots = {}}; rec.zones[zone] = z end
    return z
end

S.idIndex = {}

-- Returns true the first time a species is ever logged.
function F.LogCatch(name, id, zone, qty, mapID, x, y)
    local isNew = db.log[name] == nil
    local rec = FishRecord(name)
    if id and not rec.id then rec.id = id end
    if rec.id then S.idIndex[rec.id] = name end
    rec.total, rec.catches = rec.total + qty, rec.catches + 1
    local z = ZoneRecord(rec, zone)
    z.n, z.q = z.n + 1, z.q + qty
    if mapID and x and y then
        local gx, gy = floor(x * 20), floor(y * 20)
        local key = mapID .. ":" .. gx .. ":" .. gy
        local c = z.spots[key]
        if not c then c = {m = mapID, x = (gx + 0.5) / 20, y = (gy + 0.5) / 20, n = 0}; z.spots[key] = c end
        c.n = c.n + 1
    end
    S.cells = nil -- spot index is rebuilt on demand
    return isNew
end

function F.FishList(zone)
    local out = {}
    for name, rec in pairs(db.log) do
        local z = rec.zones[zone]
        if z and z.n > 0 then out[#out + 1] = {name = name, id = rec.id, n = z.n, q = z.q or z.n} end
    end
    tsort(out, function(a, b) if a.n ~= b.n then return a.n > b.n end return a.name < b.name end)
    return out
end

function F.SpotsFor(name)
    local out = {}
    local rec = db.log[name]
    if not rec then return out end
    for zone, z in pairs(rec.zones) do
        for _, c in pairs(z.spots) do out[#out + 1] = {zone = zone, m = c.m, x = c.x, y = c.y, n = c.n} end
    end
    tsort(out, function(a, b) return a.n > b.n end)
    return out
end

-- Every spot on one map, merged across fish: {x, y, n, fish = {name = n}}.
function F.CellsFor(mapID)
    S.cells = S.cells or {}
    local list = S.cells[mapID]
    if list then return list end
    local byKey = {}
    for name, rec in pairs(db.log) do
        for _, z in pairs(rec.zones) do
            for key, c in pairs(z.spots) do
                if c.m == mapID then
                    local cell = byKey[key]
                    if not cell then cell = {x = c.x, y = c.y, n = 0, fish = {}}; byKey[key] = cell end
                    cell.n = cell.n + c.n
                    cell.fish[name] = (cell.fish[name] or 0) + c.n
                end
            end
        end
    end
    list = {}
    for _, cell in pairs(byKey) do list[#list + 1] = cell end
    tsort(list, function(a, b) return a.n > b.n end)
    S.cells[mapID] = list
    return list
end

local function BestZone(rec)
    local best, bestN = nil, 0
    for zone, z in pairs(rec.zones) do if z.n > bestN then best, bestN = zone, z.n end end
    return best, bestN
end

function F.ZoneList()
    local out = {}
    for zone, s in pairs(db.zoneStats) do
        if s.casts > 0 or s.catches > 0 then out[#out + 1] = {zone = zone, casts = s.casts, catches = s.catches} end
    end
    tsort(out, function(a, b) if a.casts ~= b.casts then return a.casts > b.casts end return a.zone < b.zone end)
    return out
end

--------------------------------------------------------------------------------
-- Waypoints: the same bridge as Lil's BankCrafter. The game's map pin (which
-- Zygor, RestedXP, TomTom and most navigation addons follow), plus TomTom's
-- and Zygor's own arrows when installed. Every call into another addon is
-- protected.
--------------------------------------------------------------------------------
-- a fishing spot becomes a Pathway stop: the arrow, the minimap path and the map lead you there
function F.SetWaypoint(sp, fish)
    local title = (fish or "Fishing") .. ": " .. sp.zone
    local ok = P:StartRoute("next", { single = { key = "fish", goal = title, point = { sp.m, sp.x, sp.y } }, title = "Fishing spot" })
    if ok then
        Print(format("Heading to %s (%.0f, %.0f). Follow the arrow.", sp.zone, sp.x * 100, sp.y * 100), "80ff80")
    else
        Print("That spot is on another continent.", "ffd040")
    end
end

--------------------------------------------------------------------------------
-- Tackle
-- Since Dragonflight the fishing pole sits in the profession TOOL slot, with
-- accessory slots beside it. Lures, hats and gear are recognised from their
-- tooltips (read once per item, ever), so new expansions need no update.
--------------------------------------------------------------------------------
local function SlotID(name, fallback)
    local ok, id = pcall(GetInventorySlotInfo, name)
    if ok and type(id) == "number" then return id end
    return fallback
end
local SLOT_MAIN = INVSLOT_MAINHAND or 16
local SLOT_HEAD = INVSLOT_HEAD or 1
local SLOT_TOOL = SlotID("FISHINGTOOLSLOT", 28)
local SLOT_GEAR = {}
for _, n in ipairs({"FISHINGGEAR0SLOT", "FISHINGGEAR1SLOT"}) do
    local id = SlotID(n)
    if id then SLOT_GEAR[#SLOT_GEAR + 1] = id end
end

local USE_PREFIX = ITEM_SPELL_TRIGGER_ONUSE or "Use:"
S.tooltipCache, S.kindCache = {}, {}

-- {fishing = mentions fishing, use = has a "Use:" line about fishing}, or nil
-- while the item's data is still loading.
local function FishingInfo(id)
    local c = S.tooltipCache[id]
    if c then return c end
    local data = C_TooltipInfo and C_TooltipInfo.GetItemByID and C_TooltipInfo.GetItemByID(id)
    if not data then data = F.ScanItemTooltip(id) end
    local lines = data and data.lines
    if not (lines and #lines > 1) then return end
    c = {fishing = false, use = false}
    for _, line in ipairs(lines) do
        local t = line.leftText
        if type(t) == "string" and not IsSecret(t) and t:lower():find(S.fishingKey, 1, true) then
            c.fishing = true
            if t:sub(1, #USE_PREFIX) == USE_PREFIX then c.use = true end
        end
    end
    S.tooltipCache[id] = c
    return c
end

-- Classic clients have no tooltip data API: read a hidden tooltip instead.
local scanTip
function F.ScanItemTooltip(id)
    if not scanTip then
        scanTip = CreateFrame("GameTooltip", "PathwayFishScanTooltip", nil, "GameTooltipTemplate")
        scanTip:SetOwner(WorldFrame, "ANCHOR_NONE")
    end
    scanTip:ClearLines()
    scanTip:SetItemByID(id)
    local lines = {}
    for i = 1, scanTip:NumLines() do
        local fs = _G["PathwayFishScanTooltipTextLeft" .. i]
        lines[#lines + 1] = { leftText = fs and fs:GetText() }
    end
    return { lines = lines }
end

-- "pole", "hat", "gear", "lure" or false (cached once known).
function F.TackleKind(id)
    local k = S.kindCache[id]
    if k ~= nil then return k end
    if KNOWN_LURES[id] then k = "lure"
    elseif KNOWN_HATS[id] then k = "hat"
    else
        local _, _, _, equipLoc, _, classID, subClassID = C_Item.GetItemInfoInstant(id)
        if not classID then return false end
        if classID == 2 and subClassID == 20 then k = "pole"
        elseif equipLoc == "INVTYPE_PROFESSION_TOOL" or equipLoc == "INVTYPE_PROFESSION_GEAR" or equipLoc == "INVTYPE_HEAD" or classID == 0 then
            local info = FishingInfo(id)
            if not info then return false end -- not loaded yet: ask again later, don't cache
            if not info.fishing then k = false
            elseif equipLoc == "INVTYPE_PROFESSION_TOOL" then k = "pole"
            elseif equipLoc == "INVTYPE_PROFESSION_GEAR" then k = "gear"
            elseif equipLoc == "INVTYPE_HEAD" then k = "hat"
            elseif info.use then k = "lure"
            else k = false end
        else k = false end
    end
    S.kindCache[id] = k
    return k
end

local function HatHasUse(id)
    if KNOWN_HATS[id] then return KNOWN_HATS[id][2] end
    local info = FishingInfo(id)
    return info and info.use or false
end

local function ItemAuraActive(id)
    local spellName = C_Item.GetItemSpell(id)
    if not spellName or IsSecret(spellName) then return false end
    if C_UnitAuras and C_UnitAuras.GetAuraDataBySpellName then
        return C_UnitAuras.GetAuraDataBySpellName("player", spellName, "HELPFUL") ~= nil
    end
    return AuraUtil and AuraUtil.FindAuraByName and AuraUtil.FindAuraByName(spellName, "player", "HELPFUL") ~= nil or false
end

-- A lure attached to the pole shows as a timed green line on its tooltip.
local function PoleEnchanted(slot)
    if slot == SLOT_MAIN then local has = GetWeaponEnchantInfo(); return has and true or false end
    if not (C_TooltipInfo and C_TooltipInfo.GetInventoryItem) then return false end
    local data = C_TooltipInfo.GetInventoryItem("player", slot)
    for _, line in ipairs(data and data.lines or {}) do
        local t, col = line.leftText, line.leftColor
        if type(t) == "string" and not IsSecret(t) and t:find("%(%d+[^%)]*%)%s*$") and col and col.g and col.g > 0.9 and col.r < 0.3 then
            return true
        end
    end
    return false
end

-- Builds S.tackle: what you own, what's on, and the next thing to do.
function F.ScanTackle()
    local T = {items = {}, next = nil}
    local seen = {}
    local function add(id, kind, state, action)
        if seen[id] then return end
        seen[id] = true
        T.items[#T.items + 1] = {id = id, kind = kind, state = state, action = action, count = C_Item.GetItemCount(id) or 0}
    end

    -- Equipped pole: the fishing tool slot, or the main hand on older setups.
    local poleSlot, poleID = SLOT_TOOL, GetInventoryItemID("player", SLOT_TOOL)
    if not poleID then
        local mh = GetInventoryItemID("player", SLOT_MAIN)
        if mh and F.TackleKind(mh) == "pole" then poleSlot, poleID = SLOT_MAIN, mh end
    end
    T.poleSlot, T.pole = poleSlot, poleID

    local headID = GetInventoryItemID("player", SLOT_HEAD)
    local hatOn = headID and F.TackleKind(headID) == "hat" and headID or nil
    local gearOn = {}
    for _, slot in ipairs(SLOT_GEAR) do
        local id = GetInventoryItemID("player", slot)
        if id then gearOn[#gearOn + 1] = id end
    end

    -- Bags
    local bagPoles, bagHats, bagGear, lures = {}, {}, {}, {}
    for bag = 0, (NUM_TOTAL_EQUIPPED_BAG_SLOTS or NUM_BAG_SLOTS or 4) do
        for slot = 1, (C_Container.GetContainerNumSlots(bag) or 0) do
            local id = C_Container.GetContainerItemID(bag, slot)
            if id and not seen[id] then
                seen[id] = true
                local kind = F.TackleKind(id)
                if kind == "pole" then bagPoles[#bagPoles + 1] = id
                elseif kind == "hat" then bagHats[#bagHats + 1] = id
                elseif kind == "gear" then bagGear[#bagGear + 1] = id
                elseif kind == "lure" then lures[#lures + 1] = id end
            end
        end
    end
    for id, kind in pairs(db.custom) do
        if kind == "lure" and not seen[id] and (C_Item.GetItemCount(id) or 0) > 0 then lures[#lures + 1] = id end
    end
    wipe(seen)
    tsort(lures, function(a, b) return (KNOWN_LURES[a] or 9) > (KNOWN_LURES[b] or 9) end)

    -- Lure state: an aura from the lure, or a timed enchant on the pole.
    local lureOn = poleID and PoleEnchanted(poleSlot) or false
    for _, id in ipairs(lures) do if ItemAuraActive(id) then lureOn = true end end
    if hatOn and HatHasUse(hatOn) and ItemAuraActive(hatOn) then lureOn = true end
    T.lureOn = lureOn

    -- Suggestions, in the order a person would do them.
    local queue = {}
    local function suggest(id, kind, verb) queue[#queue + 1] = {id = id, kind = kind, verb = verb} end
    if poleID then add(poleID, "pole", "on")
    elseif bagPoles[1] then add(bagPoles[1], "pole", "ready", "equip"); suggest(bagPoles[1], "equip", "Equip") end
    local hatUse = hatOn and HatHasUse(hatOn)
    if hatOn and hatUse then add(hatOn, "hat", lureOn and "on" or "ready", "lure")
    elseif hatOn then add(hatOn, "hat", "on")
    elseif bagHats[1] then
        local best = bagHats[1]
        for _, id in ipairs(bagHats) do
            if (KNOWN_HATS[id] and KNOWN_HATS[id][1] or 0) > (KNOWN_HATS[best] and KNOWN_HATS[best][1] or 0) then best = id end
        end
        add(best, "hat", "ready", "equip"); suggest(best, "equip", "Equip")
    end
    for _, id in ipairs(gearOn) do add(id, "gear", "on") end
    for i, id in ipairs(bagGear) do
        if #gearOn + i <= max(#SLOT_GEAR, 1) then add(id, "gear", "ready", "equip"); suggest(id, "equip", "Equip") end
    end
    if hatUse and not lureOn and poleID then suggest(hatOn, "lure", "Use") end
    for i, id in ipairs(lures) do
        local on = ItemAuraActive(id)
        add(id, "lure", on and "on" or "ready", "lure")
        if i == 1 and not lureOn and poleID and not hatUse then suggest(id, "lure", "Apply") end
    end
    for id, kind in pairs(db.custom) do
        if kind == "toy" and PlayerHasToy and PlayerHasToy(id) then
            local on = ItemAuraActive(id)
            add(id, "toy", on and "on" or "ready", "toy")
            if not on then suggest(id, "toy", "Use") end
        elseif kind == "gear" and (C_Item.GetItemCount(id) or 0) > 0 then
            local on = C_Item.IsEquippedItem(id)
            add(id, "gear", on and "on" or "ready", not on and "equip" or nil)
            if not on then suggest(id, "equip", "Equip") end
        end
    end

    -- Readiness: what you own, weighted.
    local weights, got = 0, 0
    local parts = {}
    local function category(label, weight, frac)
        weights, got = weights + weight, got + weight * frac
        parts[#parts + 1] = (frac >= 1 and GOOD or "|cffff6655") .. label .. "|r"
    end
    category("Pole", 40, poleID and 1 or 0)
    if #lures > 0 or hatUse then category("Lure", 25, lureOn and 1 or 0) end
    if hatOn or bagHats[1] then category("Hat", 15, hatOn and 1 or 0) end
    if #gearOn > 0 or bagGear[1] then category("Gear", 20, #gearOn / max(#SLOT_GEAR, #gearOn, 1)) end
    T.score = weights > 0 and got / weights or 0
    T.parts = tconcat(parts, MUTED .. "  ·  |r")
    T.queue = queue
    S.tackle = T
    return T
end

function F.QueueScan()
    if S.scanQueued or not (S.active or UI.IsShown()) then return end
    S.scanQueued = true
    C_Timer.After(0.25, function()
        S.scanQueued = false
        if InCombatLockdown() then return end
        F.ScanTackle()
        UI.RefreshTackle()
        GM.RefreshInfo()
    end)
end

-- Secure button actions. One click = one action.
function F.ApplyAction(btn, id, action)
    btn:SetAttribute("type", nil); btn:SetAttribute("item", nil); btn:SetAttribute("toy", nil); btn:SetAttribute("macrotext", nil)
    if not id or not action then return end
    if action == "toy" then
        btn:SetAttribute("type", "toy"); btn:SetAttribute("toy", id)
    elseif action == "lure" then
        -- The classic lure macro: use it, then drop it on the pole's slot.
        btn:SetAttribute("type", "macro")
        btn:SetAttribute("macrotext", "/use item:" .. id .. "\n/use " .. ((S.tackle and S.tackle.poleSlot) or SLOT_TOOL))
    else
        btn:SetAttribute("type", "item"); btn:SetAttribute("item", "item:" .. id)
    end
end

--------------------------------------------------------------------------------
-- The fishing window (native portrait frame, three tabs)
--------------------------------------------------------------------------------
local W -- the window

function UI.IsShown() return W ~= nil and W:IsShown() end

local function Bar(parent, w, h)
    local bar = CreateFrame("StatusBar", nil, parent)
    bar:SetSize(w, h)
    bar:SetStatusBarTexture("Interface\\TargetingFrame\\UI-StatusBar")
    bar:SetMinMaxValues(0, 1); bar:SetValue(0)
    local bg = bar:CreateTexture(nil, "BACKGROUND"); bg:SetAllPoints(); bg:SetColorTexture(0, 0, 0, 0.45)
    local edge = Make("Frame", nil, bar, "TooltipBackdropTemplate", "BackdropTemplate")
    edge:SetPoint("TOPLEFT", -3, 3); edge:SetPoint("BOTTOMRIGHT", 3, -3)
    if edge.SetBackdropColor then pcall(edge.SetBackdropColor, edge, 0, 0, 0, 0) end
    bar.text = Text(bar, "GameFontHighlightSmall", "CENTER"); bar.text:SetPoint("CENTER", 0, 1)
    return bar
end

local function RateColor(frac)
    if frac >= 0.8 then return 0.25, 0.8, 0.35 elseif frac >= 0.5 then return 0.95, 0.75, 0.15 end
    return 0.85, 0.25, 0.2
end

local function Section(parent, label, y)
    local t = Text(parent, "GameFontNormal")
    t:SetPoint("TOPLEFT", 12, y); t:SetText(label)
    return t
end

local function Row(parent, y, h, icon)
    local r = CreateFrame("Button", nil, parent)
    r:SetPoint("TOPLEFT", 6, y); r:SetPoint("RIGHT", -6, 0); r:SetHeight(h)
    r.sel = r:CreateTexture(nil, "BACKGROUND"); r.sel:SetAllPoints(); r.sel:SetColorTexture(C.accent[1], C.accent[2], C.accent[3], 0.22); r.sel:Hide()
    r:SetHighlightTexture("Interface\\QuestFrame\\UI-QuestTitleHighlight", "ADD")
    r.name = Text(r, "GameFontHighlightSmall")
    if icon then
        r.icon = r:CreateTexture(nil, "ARTWORK"); r.icon:SetSize(h - 4, h - 4); r.icon:SetPoint("LEFT", 4, 0)
        r.name:SetPoint("LEFT", r.icon, "RIGHT", 6, 0)
    else
        r.name:SetPoint("LEFT", 8, 0)
    end
    r.name:SetPoint("RIGHT", -90, 0); r.name:SetWordWrap(false)
    r.right = Text(r, "GameFontNormalSmall", "RIGHT"); r.right:SetPoint("RIGHT", -6, 0)
    r:Hide()
    return r
end

local function EmptyRow(r, text)
    r.fish, r.itemID, r.spot = nil, nil, nil
    if r.icon then r.icon:SetTexture(nil) end
    r.name:SetText(MUTED .. text .. "|r"); r.right:SetText(""); r.sel:Hide(); r:Show()
end

function UI.Build()
    if W then return end
    -- Holds secure buttons, so no Escape-to-close (it couldn't hide in combat).
    W = Make("Frame", "FB_Window", UIParent, "PortraitFrameTemplate", "BackdropTemplate")
    W:SetSize(372, 476)
    W:SetPoint("TOPLEFT", 24, -150)
    W:SetClampedToScreen(true); W:SetMovable(true); W:EnableMouse(true); W:SetToplevel(true)
    W:Hide()
    if W.SetTitle then W:SetTitle(TITLE) end
    if W.SetPortraitToAsset then W:SetPortraitToAsset(ICON) end
    W:RegisterForDrag("LeftButton")
    W:SetScript("OnDragStart", function(self) if not InCombatLockdown() then self:StartMoving() end end)
    W:SetScript("OnDragStop", function(self)
        self:StopMovingOrSizing()
        local p, _, rp, x, y = self:GetPoint()
        db.pos = db.pos or {}; db.pos.window = {p, rp, x, y}
    end)
    W:SetScript("OnShow", function() F.ScanTackle(); UI.Refresh() end)

    local inset = Make("Frame", nil, W, "InsetFrameTemplate", "BackdropTemplate")
    inset:SetPoint("TOPLEFT", 10, -62); inset:SetPoint("BOTTOMRIGHT", -10, 30)
    UI.inset = inset

    -- Zone line under the title
    UI.zone = Text(W, "GameFontNormal")
    UI.zone:SetPoint("TOPLEFT", 66, -32); UI.zone:SetPoint("RIGHT", -12, 0); UI.zone:SetWordWrap(false)
    UI.mode = Text(W, "GameFontHighlightSmall")
    UI.mode:SetPoint("TOPLEFT", UI.zone, "BOTTOMLEFT", 0, -3)

    UI.pages = {}
    for i = 1, 3 do
        local p = CreateFrame("Frame", nil, inset)
        p:SetAllPoints(); p:Hide()
        UI.pages[i] = p
    end
    UI.BuildFishingPage(UI.pages[1])
    UI.BuildJournalPage(UI.pages[2])
    UI.BuildZonesPage(UI.pages[3])

    -- Bottom tabs, like the character window.
    W.Tabs = {}
    local labels = {"Fishing", "Journal", "Zones"}
    for i, label in ipairs(labels) do
        local tab = Make("Button", "FB_WindowTab" .. i, W, "PanelTabButtonTemplate", "UIPanelButtonTemplate")
        tab:SetID(i); tab:SetText(label)
        if PanelTemplates_TabResize then pcall(PanelTemplates_TabResize, tab, 0) end
        if i == 1 then tab:SetPoint("TOPLEFT", W, "BOTTOMLEFT", 12, 2) else tab:SetPoint("LEFT", W.Tabs[i - 1], "RIGHT", 4, 0) end
        tab:SetScript("OnClick", function() UI.SelectTab(i); PlaySound(SOUNDKIT and SOUNDKIT.IG_CHARACTER_INFO_TAB or 841) end)
        W.Tabs[i] = tab
    end
    if PanelTemplates_SetNumTabs then pcall(PanelTemplates_SetNumTabs, W, #labels) end
    UI.SelectTab(1)

    local pos = db.pos and db.pos.window
    if pos then W:ClearAllPoints(); W:SetPoint(pos[1], UIParent, pos[2], pos[3], pos[4]) end
end

function UI.SelectTab(i)
    UI.tab = i
    for n, p in ipairs(UI.pages) do p:SetShown(n == i) end
    if PanelTemplates_SetTab and pcall(PanelTemplates_SetTab, W, i) then return end
    for n, t in ipairs(W.Tabs) do t:SetEnabled(n ~= i) end
end

-- Fishing page: readiness, tackle, apply-next, target meter, session
function UI.BuildFishingPage(p)
    Section(p, "Tackle", -10)
    UI.ready = Bar(p, 330, 14); UI.ready:SetPoint("TOP", 0, -32)
    UI.readyParts = Text(p, "GameFontHighlightSmall", "CENTER"); UI.readyParts:SetPoint("TOP", UI.ready, "BOTTOM", 0, -6)

    UI.slots = {}
    for i = 1, 8 do
        local b = Make("Button", "FB_Tackle" .. i, p, "SecureActionButtonTemplate", nil)
        b:SetSize(34, 34)
        if i == 1 then b:SetPoint("TOPLEFT", 14, -74) else b:SetPoint("LEFT", UI.slots[i - 1], "RIGHT", 6, 0) end
        b:RegisterForClicks("AnyUp", "AnyDown")
        b.icon = b:CreateTexture(nil, "ARTWORK"); b.icon:SetAllPoints()
        b:SetNormalTexture("Interface\\Buttons\\UI-Quickslot2")
        local nt = b:GetNormalTexture(); nt:ClearAllPoints(); nt:SetPoint("CENTER"); nt:SetSize(58, 58)
        b:SetPushedTexture("Interface\\Buttons\\UI-Quickslot-Depress")
        b:SetHighlightTexture("Interface\\Buttons\\ButtonHilight-Square", "ADD")
        b.count = b:CreateFontString(nil, "OVERLAY", "NumberFontNormal"); b.count:SetPoint("BOTTOMRIGHT", -2, 2)
        b.check = b:CreateTexture(nil, "OVERLAY"); b.check:SetSize(14, 14); b.check:SetPoint("TOPRIGHT", 3, 3)
        b.check:SetTexture("Interface\\RaidFrame\\ReadyCheck-Ready")
        b.glow = b:CreateTexture(nil, "OVERLAY"); b.glow:SetTexture("Interface\\Buttons\\UI-ActionButton-Border")
        b.glow:SetBlendMode("ADD"); b.glow:SetSize(64, 64); b.glow:SetPoint("CENTER"); b.glow:SetVertexColor(unpack(C.accent))
        local ag = b.glow:CreateAnimationGroup(); ag:SetLooping("BOUNCE")
        local a = ag:CreateAnimation("Alpha"); a:SetFromAlpha(0.25); a:SetToAlpha(1); a:SetDuration(0.8)
        b.glowAnim = ag
        b:SetScript("OnEnter", function(self)
            if not self.itemID then return end
            GameTooltip:SetOwner(self, "ANCHOR_TOP")
            GameTooltip:SetItemByID(self.itemID)
            if self.hint then GameTooltip:AddLine(" "); GameTooltip:AddLine(self.hint, C.accent[1], C.accent[2], C.accent[3]) end
            GameTooltip:Show()
        end)
        b:SetScript("OnLeave", GameTooltip_Hide)
        b:Hide()
        UI.slots[i] = b
    end
    UI.noTackle = Text(p, "GameFontDisableSmall", "CENTER"); UI.noTackle:SetPoint("TOP", 0, -84)

    local apply = Make("Button", "FB_ApplyNext", p, "SecureActionButtonTemplate,UIPanelButtonTemplate", "SecureActionButtonTemplate")
    apply:SetSize(330, 24); apply:SetPoint("TOP", 0, -118)
    apply:RegisterForClicks("AnyUp", "AnyDown")
    UI.apply = apply

    Section(p, "Target", -152)
    UI.targetName = Text(p, "GameFontHighlightSmall", "RIGHT"); UI.targetName:SetPoint("TOPRIGHT", -12, -154)
    UI.targetBar = Bar(p, 330, 14); UI.targetBar:SetPoint("TOP", 0, -174)
    UI.targetInfo = Text(p, "GameFontDisableSmall", "CENTER"); UI.targetInfo:SetPoint("TOP", UI.targetBar, "BOTTOM", 0, -6)

    Section(p, "Session", -218)
    UI.stats = {}
    local labels = {"Casts", "Catches", "Hook rate", "Per hour"}
    for i, label in ipairs(labels) do
        local x = 12 + (i - 1) * 85
        local v = Text(p, "GameFontHighlightLarge", "LEFT"); v:SetPoint("TOPLEFT", x, -240)
        local l = Text(p, "GameFontDisableSmall", "LEFT"); l:SetPoint("TOPLEFT", v, "BOTTOMLEFT", 0, -2); l:SetText(label)
        UI.stats[i] = v
    end
    UI.rating = Text(p, "GameFontHighlightSmall", "LEFT"); UI.rating:SetPoint("TOPLEFT", 12, -282)
    UI.best = Text(p, "GameFontHighlightSmall", "LEFT"); UI.best:SetPoint("TOPLEFT", 12, -300); UI.best:SetPoint("RIGHT", -12, 0)
    UI.best:SetWordWrap(false)

    local new = Make("Button", nil, p, "UIPanelButtonTemplate", nil)
    new:SetSize(110, 22); new:SetPoint("BOTTOMLEFT", 10, 10); new:SetText("New Session")
    new:SetScript("OnClick", function() NewSession(); F.RefreshAll() end)
    UI.toggle = Make("Button", nil, p, "UIPanelButtonTemplate", nil)
    UI.toggle:SetSize(150, 22); UI.toggle:SetPoint("BOTTOMRIGHT", -10, 10)
    UI.toggle:SetScript("OnClick", function() F.ToggleMode() end)
end

function UI.RefreshTackle()
    if not (W and UI.slots) or InCombatLockdown() then return end
    local T = S.tackle or F.ScanTackle()
    UI.ready:SetValue(T.score)
    UI.ready:SetStatusBarColor(RateColor(T.score))
    UI.ready.text:SetText(T.score >= 1 and "Fully rigged" or ("Readiness  " .. floor(T.score * 100 + 0.5) .. "%"))
    UI.readyParts:SetText(T.parts)

    local nextID = T.queue[1] and T.queue[1].id
    for i, b in ipairs(UI.slots) do
        local it = T.items[i]
        if it then
            b.itemID = it.id
            b.icon:SetTexture(C_Item.GetItemIconByID(it.id))
            b.icon:SetDesaturated(false)
            b.count:SetText((it.kind == "lure" and it.count > 1) and it.count or "")
            b.check:SetShown(it.state == "on")
            local isNext = db.showSmartLure and it.id == nextID
            b.glow:SetShown(isNext)
            if isNext then b.glowAnim:Play() else b.glowAnim:Stop() end
            local act = (it.state ~= "on" and it.action) or ((it.action == "lure" or it.action == "toy") and it.action) or nil
            F.ApplyAction(b, it.id, act)
            b.hint = (it.state == "on" and (it.kind == "lure" and "Active" or "Equipped"))
                or (act == "equip" and "Click to equip") or (act == "lure" and "Click to put it on your pole")
                or (act == "toy" and "Click to use") or nil
            b:Show()
        else
            b.itemID = nil; F.ApplyAction(b, nil); b.glowAnim:Stop(); b:Hide()
        end
    end
    UI.noTackle:SetShown(#T.items == 0)
    UI.noTackle:SetText("No fishing pole found. Equip one to start.")

    local s = db.showSmartLure and T.queue[1]
    if s then
        F.ApplyAction(UI.apply, s.id, s.kind)
        UI.apply:SetText(s.verb .. ": " .. (C_Item.GetItemNameByID(s.id) or ("item " .. s.id)))
        UI.apply:Enable(); UI.apply:Show()
    elseif T.pole then
        F.ApplyAction(UI.apply, nil)
        UI.apply:SetText(T.score >= 1 and "Tight lines!" or "Rigged with what you own")
        UI.apply:Disable(); UI.apply:Show()
    else
        UI.apply:Hide()
    end
end

function UI.RefreshSession()
    if not W then return end
    local s = S.session
    local mins = (GetTime() - s.start) / 60
    UI.stats[1]:SetText(s.casts)
    UI.stats[2]:SetText(s.catches)
    UI.stats[3]:SetText(s.casts > 0 and (floor(s.catches / s.casts * 100 + 0.5) .. "%") or "-")
    UI.stats[4]:SetText(mins >= 1 and floor(s.catches / mins * 60 + 0.5) or "-")
    if s.casts >= 20 then
        UI.rating:SetText("Hook rate: " .. F.HookRating(s.catches / s.casts))
    else
        UI.rating:SetText(MUTED .. "Hook rating after " .. (20 - s.casts) .. " more casts|r")
    end
    local bestName, bestQ = nil, 0
    for name, q in pairs(s.fish) do if q > bestQ then bestName, bestQ = name, q end end
    UI.best:SetText(bestName and ("Most caught: |cffffffff" .. bestName .. "|r x" .. bestQ) or "")
    UI.toggle:SetText(S.active and "Stop Fishing Mode" or "Start Fishing Mode")
    UI.mode:SetText(S.active and (GOOD .. "Fishing mode on|r" .. MUTED .. "  ·  wheel up cast, wheel down reel|r") or (MUTED .. "Standby  ·  cast Fishing to begin|r"))
    UI.zone:SetText(F.Zone())
end

-- Target meter: chance per cast of landing the chosen fish.
-- Under 20 casts it uses your history in this zone; from 20 on, what you measured.
function UI.RefreshTarget()
    if not W then return end
    local t = S.target
    if not t.name then
        UI.targetName:SetText(MUTED .. "pick a fish in the Journal|r")
        UI.targetBar:SetValue(0); UI.targetBar:SetStatusBarColor(0.4, 0.4, 0.4)
        UI.targetBar.text:SetText("No target"); UI.targetInfo:SetText("")
        return
    end
    UI.targetName:SetText("|cffffffff" .. t.name .. "|r")
    local chance, source = F.TargetChance()
    if chance then
        UI.targetBar:SetValue(chance)
        UI.targetBar:SetStatusBarColor(RateColor(chance * 3)) -- 33%+ per cast is excellent
        UI.targetBar.text:SetText(format("Chance per cast  %.0f%%", chance * 100))
    else
        UI.targetBar:SetValue(0); UI.targetBar:SetStatusBarColor(0.4, 0.4, 0.4)
        UI.targetBar.text:SetText("No data yet")
        source = "fish here to start measuring"
    end
    local prog = t.casts >= 20 and (GOOD .. "measured|r") or (t.casts .. "/20 casts")
    UI.targetInfo:SetText(prog .. "  ·  caught " .. t.hits .. "  ·  " .. source)
end

function F.TargetChance()
    local t = S.target
    if not t.name then return end
    if t.casts >= 20 then return t.hits / t.casts, "over " .. t.casts .. " casts" end
    local zone = F.Zone()
    local rec, zs = db.log[t.name], db.zoneStats[zone]
    local z = rec and rec.zones[zone]
    if z and zs and zs.casts > 0 then return min(1, z.n / zs.casts), "from your history here" end
end

-- Journal page: this zone's fish and the chosen fish's best spots
function UI.BuildJournalPage(p)
    UI.jHeader = Text(p, "GameFontNormal"); UI.jHeader:SetPoint("TOPLEFT", 12, -10); UI.jHeader:SetPoint("RIGHT", -12, 0)
    UI.jSub = Text(p, "GameFontDisableSmall"); UI.jSub:SetPoint("TOPLEFT", UI.jHeader, "BOTTOMLEFT", 0, -3)
    UI.fishRows = {}
    for i = 1, 9 do
        local r = Row(p, -46 - (i - 1) * 24, 22, true)
        r:SetScript("OnClick", function(self) if self.fish then F.SelectFish(self.fish) end end)
        r:SetScript("OnEnter", function(self)
            if not self.itemID then return end
            GameTooltip:SetOwner(self, "ANCHOR_RIGHT"); GameTooltip:SetItemByID(self.itemID)
            GameTooltip:AddLine(" "); GameTooltip:AddLine("Click to make it your target", C.accent[1], C.accent[2], C.accent[3])
            GameTooltip:Show()
        end)
        r:SetScript("OnLeave", GameTooltip_Hide)
        UI.fishRows[i] = r
    end
    UI.spotHeader = Section(p, "Best spots", -272)
    UI.spotRows = {}
    for i = 1, 4 do
        local r = Row(p, -292 - (i - 1) * 20, 18, false)
        r:SetScript("OnClick", function(self) if self.spot then F.SetWaypoint(self.spot, S.target.name) end end)
        r:SetScript("OnEnter", function(self)
            if not self.spot then return end
            GameTooltip:SetOwner(self, "ANCHOR_RIGHT"); GameTooltip:SetText("Click to set a waypoint"); GameTooltip:Show()
        end)
        r:SetScript("OnLeave", GameTooltip_Hide)
        UI.spotRows[i] = r
    end
end

function UI.RefreshJournal()
    if not (W and UI.tab == 2) then return end
    local zone = F.Zone()
    local zs = db.zoneStats[zone]
    local casts, catches = zs and zs.casts or 0, zs and zs.catches or 0
    UI.jHeader:SetText(zone)
    UI.jSub:SetText(catches .. " catches from " .. casts .. " casts" .. (casts > 0 and format("  ·  %.0f%%", catches / casts * 100) or ""))
    local list = F.FishList(zone)
    for i, r in ipairs(UI.fishRows) do
        local f = list[i]
        if f then
            r.fish, r.itemID = f.name, f.id
            r.icon:SetTexture(f.id and C_Item.GetItemIconByID(f.id) or "Interface\\Icons\\INV_Misc_QuestionMark")
            r.name:SetText(f.name .. (S.session.new[f.name] and ("  " .. GOOD .. "NEW|r") or ""))
            r.right:SetText(casts > 0 and format("x%d  |cffffffff%.0f%%|r", f.q, min(1, f.n / casts) * 100) or ("x" .. f.q))
            r.sel:SetShown(f.name == S.target.name)
            r:Show()
        else
            r:Hide()
        end
    end
    if #list == 0 then EmptyRow(UI.fishRows[1], "Nothing logged here yet - cast away!") end

    local name = S.target.name
    local spots = name and F.SpotsFor(name) or {}
    UI.spotHeader:SetText(name and ("Best spots for |cffffffff" .. name .. "|r") or "Best spots")
    for i, r in ipairs(UI.spotRows) do
        local s = spots[i]
        if s then
            r.spot = s
            r.name:SetText(format("%s  " .. MUTED .. "(%.0f, %.0f)|r", s.zone, s.x * 100, s.y * 100))
            r.right:SetText("x" .. s.n)
            r:Show()
        elseif i == 1 then
            EmptyRow(r, name and "No spots logged yet - catch it to map it." or "Click a fish to see where you catch it.")
        else
            r.spot = nil; r:Hide()
        end
    end
end

-- Zones page: catch rate by zone
function UI.BuildZonesPage(p)
    local h = Text(p, "GameFontNormal"); h:SetPoint("TOPLEFT", 12, -10); h:SetText("Catch rate by zone")
    local sub = Text(p, "GameFontDisableSmall"); sub:SetPoint("TOPLEFT", h, "BOTTOMLEFT", 0, -3); sub:SetText("Catches / casts, from every session")
    UI.zoneRows = {}
    for i = 1, 14 do UI.zoneRows[i] = Row(p, -46 - (i - 1) * 22, 20, false) end
end

function UI.RefreshZones()
    if not (W and UI.tab == 3) then return end
    local list = F.ZoneList()
    for i, r in ipairs(UI.zoneRows) do
        local z = list[i]
        if z then
            r.name:SetText(z.zone)
            r.right:SetText(z.catches .. " / " .. z.casts .. "  |cffffffff" .. (z.casts > 0 and format("%.0f%%", z.catches / z.casts * 100) or "-") .. "|r")
            r:Show()
        else
            r:Hide()
        end
    end
    if #list == 0 then EmptyRow(UI.zoneRows[1], "No casts recorded yet.") end
end

function UI.Refresh()
    if not (W and W:IsShown()) then return end
    UI.RefreshSession(); UI.RefreshTarget(); UI.RefreshJournal(); UI.RefreshZones()
    if not InCombatLockdown() then UI.RefreshTackle() end
end

function UI.Toggle()
    if InCombatLockdown() then Print("The fishing window opens after combat.", "ffd040"); return end
    UI.Build()
    W:SetShown(not W:IsShown())
end

local oldSelectTab = UI.SelectTab
function UI.SelectTab(i) oldSelectTab(i); if W and W:IsShown() then UI.Refresh() end end

--------------------------------------------------------------------------------
-- Ring timer (shared by the screen cue and the GoodMap rim):
-- a circle of short lines that drains clockwise as the cast runs out.
--------------------------------------------------------------------------------
local function NewArc(parent, segments, thickness)
    local arc = {lines = {}, lit = -1, parent = parent}
    for i = 1, segments do
        local l = parent:CreateLine(nil, "OVERLAY")
        l:SetThickness(thickness)
        arc.lines[i] = l
    end
    function arc:Layout(radius)
        local n = #self.lines
        local step = 2 * PI / n
        for i, l in ipairs(self.lines) do
            local a0 = PI / 2 - (i - 1) * step
            local a1 = a0 - step * 1.15 -- a little overlap hides the joints
            l:SetStartPoint("CENTER", self.parent, radius * cos(a0), radius * sin(a0))
            l:SetEndPoint("CENTER", self.parent, radius * cos(a1), radius * sin(a1))
        end
        self.lit = -1
    end
    function arc:SetColor(r, g, b, a) self.r, self.g, self.b, self.a = r, g, b, a or 1; self.lit = -1 end
    function arc:SetProgress(p)
        local n = #self.lines
        local k = floor(Clamp01(p) * n + 0.5)
        if k == self.lit then return end
        self.lit = k
        for i, l in ipairs(self.lines) do
            if i <= k then l:SetColorTexture(self.r or 1, self.g or 1, self.b or 1, self.a or 1)
            else l:SetColorTexture(1, 1, 1, 0.10) end
        end
    end
    return arc
end

-- An expanding, fading ring.
local function NewRipple(parent, size)
    local f = CreateFrame("Frame", nil, parent)
    f:SetSize(size, size); f:SetPoint("CENTER"); f:Hide()
    local t = f:CreateTexture(nil, "OVERLAY"); t:SetAllPoints(); t:SetTexture(MEDIA .. "ring"); t:SetBlendMode("ADD")
    local ag = f:CreateAnimationGroup()
    local s = ag:CreateAnimation("Scale"); s:SetScaleFrom(0.12, 0.12); s:SetScaleTo(1, 1); s:SetDuration(1.5); s:SetSmoothing("OUT")
    local a = ag:CreateAnimation("Alpha"); a:SetFromAlpha(1); a:SetToAlpha(0); a:SetDuration(1.5); a:SetSmoothing("IN")
    ag:SetScript("OnFinished", function() f:Hide() end)
    return {frame = f, tex = t, Play = function(_, r, g, b, alpha)
        t:SetVertexColor(r, g, b, alpha or 1)
        ag:Stop(); f:Show(); ag:Play()
    end, Stop = function() ag:Stop(); f:Hide() end}
end

local function RipplePool(parent, size, n)
    local pool = {i = 0}
    for k = 1, n do pool[k] = NewRipple(parent, size) end
    function pool:Play(r, g, b, a, delay)
        local function go()
            self.i = self.i % #self + 1
            self[self.i]:Play(r, g, b, a)
        end
        if delay and delay > 0 then C_Timer.After(delay, go) else go() end
    end
    function pool:Resize(sz) for k = 1, #self do self[k].frame:SetSize(sz, sz) end end
    function pool:Stop() for k = 1, #self do self[k]:Stop() end end
    return pool
end

--------------------------------------------------------------------------------
-- Screen cues: soft edge vignette, status text, and the bite-timer ring
--------------------------------------------------------------------------------
function FX.Build()
    if FX.vig then return end
    -- Edge vignette (replaces the old full-screen colour fill)
    local vf = CreateFrame("Frame", nil, root)
    vf:SetAllPoints(); vf:SetFrameStrata("BACKGROUND"); vf:Hide()
    local tex = vf:CreateTexture(nil, "BACKGROUND"); tex:SetAllPoints(); tex:SetTexture(MEDIA .. "vignette")
    local ag = vf:CreateAnimationGroup(); ag:SetToFinalAlpha(true)
    local inA = ag:CreateAnimation("Alpha"); inA:SetFromAlpha(0); inA:SetToAlpha(1); inA:SetOrder(1); inA:SetSmoothing("OUT")
    local outA = ag:CreateAnimation("Alpha"); outA:SetFromAlpha(1); outA:SetToAlpha(0); outA:SetOrder(2); outA:SetSmoothing("IN")
    ag:SetScript("OnFinished", function() if ag:GetLooping() == "NONE" then vf:Hide() end end)
    FX.vig = {frame = vf, Play = function(_, hex, tIn, tOut, loop)
        ag:Stop()
        tex:SetVertexColor(HexRGBA(hex))
        inA:SetDuration(tIn); outA:SetDuration(tOut)
        ag:SetLooping(loop and "REPEAT" or "NONE")
        vf:Show(); ag:Play()
    end, Stop = function() ag:Stop(); ag:SetLooping("NONE"); vf:Hide() end}

    -- Status word ("Cast", "Caught!") - rises and fades like zone text
    local st = CreateFrame("Frame", nil, root)
    st:SetSize(600, 60); st:SetPoint("CENTER", 0, 270); st:SetFrameStrata("HIGH"); st:Hide()
    st.text = st:CreateFontString(nil, "OVERLAY", "GameFontNormalHuge")
    local font = GameFontNormal:GetFont()
    st.text:SetFont(font, 30, "OUTLINE"); st.text:SetShadowOffset(2, -2); st.text:SetShadowColor(0, 0, 0, 0.9)
    st.text:SetPoint("CENTER")
    local sag = st:CreateAnimationGroup()
    local a1 = sag:CreateAnimation("Alpha"); a1:SetFromAlpha(0); a1:SetToAlpha(1); a1:SetDuration(0.18); a1:SetOrder(1)
    local m1 = sag:CreateAnimation("Translation"); m1:SetOffset(0, 10); m1:SetDuration(1.6); m1:SetOrder(1); m1:SetSmoothing("OUT")
    local a2 = sag:CreateAnimation("Alpha"); a2:SetFromAlpha(1); a2:SetToAlpha(0); a2:SetDuration(0.6); a2:SetStartDelay(1.0); a2:SetOrder(2)
    sag:SetScript("OnFinished", function() st:Hide() end)
    FX.status = {Show = function(_, text, c)
        if not db.showStatus then return end
        st.text:SetText(text); st.text:SetTextColor(c[1], c[2], c[3])
        sag:Stop(); st:Show(); sag:Play()
    end, Stop = function() sag:Stop(); st:Hide() end}

    -- Bite-timer ring with the fish in the middle
    local ring = CreateFrame("Frame", "FB_Ring", root)
    ring:SetSize(84, 84); ring:SetPoint("CENTER", 0, 190); ring:SetFrameStrata("HIGH"); ring:Hide()
    local back = ring:CreateTexture(nil, "BACKGROUND"); back:SetTexture(MEDIA .. "glow"); back:SetSize(120, 120); back:SetPoint("CENTER")
    back:SetVertexColor(0, 0, 0, 0.55)
    local fish = ring:CreateTexture(nil, "ARTWORK"); fish:SetSize(46, 46); fish:SetPoint("CENTER")
    fish:SetTexture("Interface\\Icons\\INV_Misc_Fish_04")
    local mask = ring:CreateMaskTexture(); mask:SetTexture(CIRCLE, "CLAMPTOBLACKADDITIVE", "CLAMPTOBLACKADDITIVE"); mask:SetAllPoints(fish)
    fish:AddMaskTexture(mask)
    ring.arc = NewArc(ring, 48, 3); ring.arc:Layout(34); ring.arc:SetColor(C.accent[1], C.accent[2], C.accent[3], 1)
    ring.ripples = RipplePool(ring, 150, 2)
    local fag = ring:CreateAnimationGroup()
    local fa = fag:CreateAnimation("Alpha"); fa:SetFromAlpha(0); fa:SetToAlpha(1); fa:SetDuration(0.25)
    FX.ring = ring; FX.ringFade = fag

    -- One driver runs only while the line is in the water.
    FX.tick = CreateFrame("Frame"); FX.tick:Hide()
    FX.tick:SetScript("OnUpdate", function() FX.UpdateTimer() end)
    Pathway.Perf.Hook(FX.tick, "Fishing", "OnUpdate")
end

-- 1 when the cast starts, 0 when the channel would end.
function FX.Remaining()
    local _, _, _, startMS, endMS = UnitChannelInfo("player")
    if not startMS or IsSecret(startMS) or not endMS or endMS <= startMS then return S.waitStart and 1 or 0 end
    return Clamp01((endMS - GetTime() * 1000) / (endMS - startMS))
end

function FX.UpdateTimer()
    local p = FX.Remaining()
    if FX.ring:IsShown() then FX.ring.arc:SetProgress(p) end
    GM.SetProgress(p)
end

--------------------------------------------------------------------------------
-- GoodMap fishing map
-- GoodMap keeps its internals private, so this dresses the frame it draws on
-- (Blizzard's zone map, BattlefieldMapFrame) and reads its shape setting.
-- Nothing here changes GoodMap; when you stop fishing it all fades away.
--------------------------------------------------------------------------------
function GM.Available()
    local loaded = P.GoodMap.ready
    local map = rawget(_G, "BattlefieldMapFrame")
    return loaded and type(map) == "table" and map.ScrollContainer ~= nil
end

function GM.Round()
    local root = rawget(_G, "PathwayMapDB")
    if type(root) ~= "table" or type(root.profiles) ~= "table" then return true end
    local key = (UnitName("player") or "?") .. " - " .. (GetRealmName() or "?")
    local name = type(root.chars) == "table" and root.chars[key]
    local p = (name and root.profiles[name]) or root.profiles.Default
    return not (type(p) == "table" and p.shape == "SQUARE")
end

function GM.Build()
    if GM.layer then return true end
    if not GM.Available() then return false end
    local map = BattlefieldMapFrame
    local sc = map.ScrollContainer
    GM.map, GM.sc = map, sc

    -- Between GoodMap's border (9400) and its text (9500).
    local L = CreateFrame("Frame", "FB_MapLayer", map)
    L:SetAllPoints(sc); L:SetFrameLevel(9450); L:EnableMouse(false); L:SetAlpha(0); L:Hide()
    GM.layer = L

    local mask = map:CreateMaskTexture()
    mask:SetTexture(CIRCLE, "CLAMPTOBLACKADDITIVE", "CLAMPTOBLACKADDITIVE")
    mask:SetPoint("CENTER", sc, "CENTER")
    GM.mask, GM.masked = mask, {}

    local function Masked(t) GM.masked[#GM.masked + 1] = t; return t end
    -- Water: a cool glow over the map, darker toward the edge.
    GM.water = Masked(L:CreateTexture(nil, "BACKGROUND")); GM.water:SetTexture(MEDIA .. "glow"); GM.water:SetPoint("CENTER"); GM.water:SetBlendMode("ADD")
    GM.edge = Masked(L:CreateTexture(nil, "BORDER")); GM.edge:SetTexture(MEDIA .. "vignette"); GM.edge:SetAllPoints(); GM.edge:SetVertexColor(0.02, 0.06, 0.14, 0.75)
    -- Rim: a soft violet halo around the round map.
    GM.rim = L:CreateTexture(nil, "ARTWORK"); GM.rim:SetTexture(MEDIA .. "ring"); GM.rim:SetPoint("CENTER"); GM.rim:SetBlendMode("ADD")
    GM.rim:SetVertexColor(C.accent[1], C.accent[2], C.accent[3], 0.9)
    local rag = GM.rim:CreateAnimationGroup(); rag:SetLooping("BOUNCE")
    local ra = rag:CreateAnimation("Alpha"); ra:SetFromAlpha(0.35); ra:SetToAlpha(1); ra:SetDuration(1.6); ra:SetSmoothing("IN_OUT")
    GM.rimPulse = rag
    local wag = GM.water:CreateAnimationGroup(); wag:SetLooping("BOUNCE")
    local wa = wag:CreateAnimation("Alpha"); wa:SetFromAlpha(0.6); wa:SetToAlpha(1); wa:SetDuration(2.2); wa:SetSmoothing("IN_OUT")
    GM.waterPulse = wag

    GM.arc = NewArc(L, 72, 2); GM.arc:SetColor(C.accent[1], C.accent[2], C.accent[3], 1)
    GM.ripples = RipplePool(L, 200, 4)

    -- Info strip at the bottom, on a soft shade like GoodMap's own text.
    GM.shade = Masked(L:CreateTexture(nil, "ARTWORK", nil, 1))
    GM.shade:SetTexture("Interface\\Buttons\\WHITE8X8")
    GM.shade:SetPoint("BOTTOMLEFT"); GM.shade:SetPoint("BOTTOMRIGHT"); GM.shade:SetHeight(76)
    GM.shade:SetGradient("VERTICAL", CreateColor(0, 0, 0, 0.7), CreateColor(0, 0, 0, 0))
    local font = GameFontNormal:GetFont()
    GM.info1 = L:CreateFontString(nil, "OVERLAY"); GM.info1:SetFont(font, 12, "OUTLINE"); GM.info1:SetPoint("BOTTOM", 0, 40)
    GM.info2 = L:CreateFontString(nil, "OVERLAY"); GM.info2:SetFont(font, 11, "OUTLINE"); GM.info2:SetPoint("BOTTOM", 0, 26)
    GM.info2:SetTextColor(0.85, 0.85, 0.85)

    -- "+ Fish" rising from the middle on a catch
    GM.float = L:CreateFontString(nil, "OVERLAY"); GM.float:SetFont(font, 14, "OUTLINE"); GM.float:SetPoint("CENTER", 0, 14); GM.float:Hide()
    local fag = GM.float:CreateAnimationGroup()
    local fm = fag:CreateAnimation("Translation"); fm:SetOffset(0, 34); fm:SetDuration(1.8); fm:SetSmoothing("OUT")
    local fa1 = fag:CreateAnimation("Alpha"); fa1:SetFromAlpha(0); fa1:SetToAlpha(1); fa1:SetDuration(0.2)
    local fa2 = fag:CreateAnimation("Alpha"); fa2:SetFromAlpha(1); fa2:SetToAlpha(0); fa2:SetDuration(0.6); fa2:SetStartDelay(1.2)
    fag:SetScript("OnFinished", function() GM.float:Hide() end)
    GM.floatAnim = fag

    -- Fade in / out
    local inG = L:CreateAnimationGroup(); inG:SetToFinalAlpha(true)
    local ia = inG:CreateAnimation("Alpha"); ia:SetFromAlpha(0); ia:SetToAlpha(1); ia:SetDuration(0.6); ia:SetSmoothing("OUT")
    local outG = L:CreateAnimationGroup(); outG:SetToFinalAlpha(true)
    local oa = outG:CreateAnimation("Alpha"); oa:SetFromAlpha(1); oa:SetToAlpha(0); oa:SetDuration(0.5); oa:SetSmoothing("IN")
    outG:SetScript("OnFinished", function() L:Hide(); GM.rimPulse:Stop(); GM.waterPulse:Stop(); GM.ripples:Stop() end)
    GM.fadeIn, GM.fadeOut = inG, outG

    -- Fishing spots: glowing markers on the map canvas (they pan and zoom with it).
    local canvas = sc.Child
    GM.canvas = canvas
    GM.pinLayer = CreateFrame("Frame", nil, canvas)
    GM.pinLayer:SetAllPoints(canvas); GM.pinLayer:SetFrameLevel(canvas:GetFrameLevel() + 300)
    GM.pins = {}

    map:HookScript("OnShow", GM.Update)
    map:HookScript("OnHide", GM.Update)
    map:HookScript("OnSizeChanged", function() if GM.layer:IsShown() then GM.Layout() end end)
    if map.OnMapChanged then hooksecurefunc(map, "OnMapChanged", function() GM.RefreshPins() end) end
    if map.OnCanvasScaleChanged then hooksecurefunc(map, "OnCanvasScaleChanged", function() GM.RefreshPins() end) end
    return true
end

function GM.Layout()
    local w, h = GM.sc:GetWidth(), GM.sc:GetHeight()
    if not (w and h) or w <= 0 then return end
    local d = min(w, h)
    local round = GM.Round()
    GM.round = round
    GM.mask:SetSize(d, d)
    for _, t in ipairs(GM.masked) do
        if round and not t.fbMasked then t:AddMaskTexture(GM.mask); t.fbMasked = true
        elseif not round and t.fbMasked then t:RemoveMaskTexture(GM.mask); t.fbMasked = false end
    end
    GM.water:SetSize(d * 1.1, d * 1.1)
    GM.rim:SetSize(d / 0.82 * 1.02, d / 0.82 * 1.02)
    GM.rim:SetShown(round)
    GM.arc:Layout(d / 2 - 5)
    GM.ripples:Resize(d * 0.95)
    GM.shade:SetHeight(min(76, d * 0.32))
    local wr, wg, wb, wa = HexRGBA(db.waterColor)
    GM.water:SetVertexColor(wr, wg, wb, min(0.55, wa * 0.7))
end

function GM.Wanted() return S.active and db.mapFX and GM.layer ~= nil and GM.map:IsShown() end

function GM.Update()
    if not GM.layer then return end
    local want = GM.Wanted()
    if want and not GM.on then
        GM.on = true
        GM.fadeOut:Stop()
        GM.Layout()
        GM.layer:Show(); GM.fadeIn:Play()
        GM.rimPulse:Play(); GM.waterPulse:Play()
        GM.arc:SetProgress(0)
        GM.RefreshInfo()
        GM.ripples:Play(C.accent[1], C.accent[2], C.accent[3], 0.9)
    elseif not want and GM.on then
        GM.on = false
        GM.fadeIn:Stop(); GM.fadeOut:Play()
    end
    GM.RefreshPins()
end

function GM.SetProgress(p) if GM.on then GM.arc:SetProgress(p) end end

function GM.OnCast()
    if not GM.on then return end
    local r, g, b = 0.55, 0.8, 1
    GM.ripples:Play(r, g, b, 0.9)
    GM.ripples:Play(r, g, b, 0.6, 0.35)
end

function GM.OnWait()
    if GM.on then GM.ripples:Play(0.4, 0.7, 1, 0.35) end
end

function GM.OnCatch(name, isNew)
    if not GM.on then return end
    local c = isNew and C.gold or C.good
    GM.ripples:Play(c[1], c[2], c[3], 1)
    GM.ripples:Play(c[1], c[2], c[3], 0.7, 0.25)
    GM.arc:SetProgress(0)
    if name then
        GM.float:SetText((isNew and "New: " or "+ ") .. name)
        GM.float:SetTextColor(c[1], c[2], c[3])
        GM.floatAnim:Stop(); GM.float:Show(); GM.floatAnim:Play()
    end
    GM.RefreshInfo()
end

function GM.RefreshInfo()
    if not (GM.on and GM.info1) then return end
    local s = S.session
    local show = db.mapInfo
    GM.info1:SetShown(show); GM.info2:SetShown(show); GM.shade:SetShown(show)
    if not show then return end
    local mins = (GetTime() - s.start) / 60
    local rate = s.casts > 0 and floor(s.catches / s.casts * 100 + 0.5) .. "%" or "-"
    GM.info1:SetText(format("%s%d|r caught  ·  %s%s|r hooked%s", "|cffffffff", s.catches, "|cffffffff", rate,
        mins >= 1 and format("  ·  |cffffffff%d|r/hr", floor(s.catches / mins * 60 + 0.5)) or ""))
    local t = S.target
    if t.name then
        local chance = F.TargetChance()
        GM.info2:SetText(Hex(C.accent) .. t.name .. "|r" .. (chance and format("  %.0f%% per cast", chance * 100) or ""))
    else
        local list = F.FishList(F.Zone())
        GM.info2:SetText(list[1] and ("Top here: " .. list[1].name .. " x" .. list[1].q) or "First cast here - good luck!")
    end
end

local function PinTooltip(self)
    local cell = self.cell
    if not cell then return end
    GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
    GameTooltip:SetText("Fishing spot", C.accent[1], C.accent[2], C.accent[3])
    local list = {}
    for name, n in pairs(cell.fish) do list[#list + 1] = {name, n} end
    tsort(list, function(a, b) return a[2] > b[2] end)
    for i = 1, min(6, #list) do GameTooltip:AddDoubleLine(list[i][1], "x" .. list[i][2], 1, 1, 1, 0.8, 0.8, 0.8) end
    GameTooltip:Show()
end

function GM.RefreshPins()
    if not GM.pinLayer then return end
    local mode = db and db.mapSpots
    local want = GM.map:IsShown() and (mode == "ALWAYS" or (mode == "FISHING" and S.active))
    local cells = want and F.CellsFor(GM.map:GetMapID() or 0) or {}
    local W2, H2 = GM.canvas:GetSize()
    local scale = (GM.sc.GetCanvasScale and GM.sc:GetCanvasScale()) or 1
    if not scale or scale <= 0 then scale = 1 end
    local targetName = S.target.name
    local round = GM.round
    for i = 1, max(#cells, #GM.pins) do
        local cell, pin = cells[i], GM.pins[i]
        if cell and i <= 60 then
            if not pin then
                pin = CreateFrame("Frame", nil, GM.pinLayer)
                pin.glow = pin:CreateTexture(nil, "ARTWORK"); pin.glow:SetAllPoints(); pin.glow:SetTexture(MEDIA .. "glow"); pin.glow:SetBlendMode("ADD")
                pin.dot = pin:CreateTexture(nil, "OVERLAY"); pin.dot:SetTexture(MEDIA .. "ring"); pin.dot:SetPoint("CENTER")
                pin:EnableMouse(true)
                if pin.SetMouseClickEnabled then pin:SetMouseClickEnabled(false) end
                pin:SetScript("OnEnter", PinTooltip); pin:SetScript("OnLeave", GameTooltip_Hide)
                GM.pins[i] = pin
            end
            if round and not pin.fbMasked then pin.glow:AddMaskTexture(GM.mask); pin.dot:AddMaskTexture(GM.mask); pin.fbMasked = true
            elseif not round and pin.fbMasked then pin.glow:RemoveMaskTexture(GM.mask); pin.dot:RemoveMaskTexture(GM.mask); pin.fbMasked = false end
            pin.cell = cell
            local size = (16 + min(cell.n, 25) * 0.6) / scale
            pin:SetSize(size, size)
            pin.dot:SetSize(size * 0.75, size * 0.75)
            local c = (targetName and cell.fish[targetName]) and C.gold or C.accent
            pin.glow:SetVertexColor(c[1], c[2], c[3], 0.85)
            pin.dot:SetVertexColor(1, 1, 1, 0.9)
            pin:ClearAllPoints(); pin:SetPoint("CENTER", GM.pinLayer, "TOPLEFT", cell.x * W2, -cell.y * H2)
            pin:Show()
        elseif pin then
            pin.cell = nil; pin:Hide()
        end
    end
end

--------------------------------------------------------------------------------
-- Clean screen
-- Fades what's on screen when fishing starts (action bars, unit frames,
-- trackers, other addons' HUDs). Windows opened afterwards stay visible, and
-- Lil's GoodMap stays: it's your minimap. Alpha only, so it's combat-safe.
--------------------------------------------------------------------------------
local KEEP_EXACT = {
    FB_Root = true, FB_Window = true, Minimap = true, MinimapCluster = true, GeneralDockManager = true,
    PlayerCastingBarFrame = true, CastingBarFrame = true, MirrorTimerContainer = true,
    UIErrorsFrame = true, LootFrame = true, ColorPickerFrame = true, WorldMapFrame = true,
    GameMenuFrame = true, SettingsPanel = true, AlertFrame = true, GroupLootContainer = true,
}
local KEEP_PREFIX = {"ChatFrame", "ChatConfig", "FloatingChat", "ChatMenu", "StaticPopup", "GameTooltip",
    "ItemRefTooltip", "ShoppingTooltip", "DropDownList", "FB_", "Minimap", "EditModeManager", "ContainerFrame", "Menu",
    "BattlefieldMap", "GoodMap"}
local HUD_NAMES = {"PlayerFrame", "TargetFrame", "FocusFrame", "BuffFrame", "DebuffFrame", "ObjectiveTrackerFrame",
    "MainMenuBar", "MainActionBar", "MultiBarBottomLeft", "MultiBarBottomRight", "MultiBarRight", "MultiBarLeft",
    "MultiBar5", "MultiBar6", "MultiBar7", "StanceBar", "PetActionBar", "PossessActionBar", "MicroMenuContainer",
    "BagsBar", "StatusTrackingBarManager", "MainStatusTrackingBarContainer", "SecondaryStatusTrackingBarContainer",
    "PartyFrame", "CompactRaidFrameContainer", "DurabilityFrame", "ExtraAbilityContainer"}
S.faded = setmetatable({}, {__mode = "k"})

-- Some of the game's frames are locked against addons ("forbidden"); touching
-- them in any way but IsForbidden() is an error. Check that first, always.
local function Locked(frame)
    if type(frame) ~= "table" then return true end
    local ok, forbidden = pcall(function() return frame.IsForbidden and frame:IsForbidden() end)
    return not ok or forbidden
end

local function ShouldKeep(frame, special)
    if frame == root then return true end
    local n = frame:GetName()
    if not n or IsSecret(n) then return false end
    if KEEP_EXACT[n] or (UIPanelWindows and UIPanelWindows[n]) or special[n] then return true end
    for _, p in ipairs(KEEP_PREFIX) do
        if n:sub(1, #p) == p then return true end
    end
    return false
end

local function Fade(frame)
    if Locked(frame) then return end
    pcall(function()
        local a = frame:GetAlpha()
        if IsSecret(a) then return end
        if S.faded[frame] == nil then S.faded[frame] = a end
        if a > 0 then frame:SetAlpha(0) end
    end)
end

function F.FocusSweep(initial)
    if initial then
        local special = {}
        for _, n in ipairs(UISpecialFrames) do special[n] = true end
        for _, child in ipairs({UIParent:GetChildren()}) do
            if not Locked(child) then
                local ok, fade = pcall(function() return child:IsShown() and not ShouldKeep(child, special) end)
                if ok and fade then Fade(child) end
            end
        end
    else
        for frame in pairs(S.faded) do Fade(frame) end
    end
    for _, n in ipairs(HUD_NAMES) do
        local fr = rawget(_G, n)
        if type(fr) == "table" and fr.SetAlpha then Fade(fr) end
    end
end

function F.SetFocusScreen(on)
    if on then
        if S.focusTicker then return end
        F.FocusSweep(true)
        S.focusTicker = C_Timer.NewTicker(1, function() F.FocusSweep(false) end)
    else
        if S.focusTicker then S.focusTicker:Cancel(); S.focusTicker = nil end
        for frame, alpha in pairs(S.faded) do pcall(frame.SetAlpha, frame, alpha) end
        wipe(S.faded)
    end
end

-- Zone banner at the top of the screen in cinematic mode
function FX.BuildBanner()
    if FX.banner then return end
    local b = CreateFrame("Frame", nil, root)
    b:SetSize(700, 60); b:SetPoint("TOP", 0, -70); b:Hide()
    local font = GameFontNormal:GetFont()
    b.zone = b:CreateFontString(nil, "OVERLAY"); b.zone:SetFont(font, 20, "OUTLINE"); b.zone:SetPoint("TOP")
    b.zone:SetTextColor(C.accent[1], C.accent[2], C.accent[3]); b.zone:SetShadowOffset(1, -1)
    b.sub = b:CreateFontString(nil, "OVERLAY"); b.sub:SetFont(font, 12, "OUTLINE"); b.sub:SetPoint("TOP", b.zone, "BOTTOM", 0, -4)
    b.sub:SetTextColor(0.85, 0.85, 0.85)
    b.countdown = b:CreateFontString(nil, "OVERLAY"); b.countdown:SetFont(font, 12, "OUTLINE"); b.countdown:SetPoint("TOP", b.sub, "BOTTOM", 0, -6)
    b.countdown:SetTextColor(C.gold[1], C.gold[2], C.gold[3])
    FX.banner = b
end

function FX.RefreshBanner()
    FX.BuildBanner()
    local b = FX.banner
    if not (S.active and db.cinematicMode) then b:Hide(); return end
    local zone = F.Zone()
    b.zone:SetText(zone)
    if S.target.name then
        b.sub:SetText("Hunting  " .. S.target.name)
    else
        local list, parts = F.FishList(zone), {}
        for i = 1, min(3, #list) do parts[i] = list[i].name .. " x" .. list[i].q end
        b.sub:SetText(#parts > 0 and tconcat(parts, MUTED .. "  ·  |r") or "No catches logged here yet")
    end
    b:Show()
end

function F.RefreshAll()
    UI.Refresh()
    FX.RefreshBanner()
    GM.RefreshInfo()
end

--------------------------------------------------------------------------------
-- Idle standby with a countdown
--------------------------------------------------------------------------------
function F.StopIdle()
    if S.idleTicker then S.idleTicker:Cancel(); S.idleTicker = nil end
    if FX.banner then FX.banner.countdown:SetText("") end
end

function F.StartIdle()
    F.StopIdle()
    local left = db.idleTimeout
    S.idleTicker = C_Timer.NewTicker(1, function()
        left = left - 1
        if left <= 0 then F.StopIdle(); F.Disable(); return end
        if db.showCountdown and left <= 15 and FX.banner then
            FX.banner.countdown:SetText("Standby in " .. left .. "s  ·  scroll up to keep fishing")
            if not FX.banner:IsShown() then FX.banner:Show() end
        end
    end)
end

--------------------------------------------------------------------------------
-- Ratings and summary
--------------------------------------------------------------------------------
-- Hook rate = catches / casts: mostly your reaction time, so it's labelled as yours.
function F.HookRating(rate)
    local pct = floor(rate * 100 + 0.5) .. "%  "
    if rate >= 0.90 then return pct .. GOOD .. "Sharp|r" elseif rate >= 0.75 then return pct .. "|cffffd040Good|r"
    elseif rate >= 0.50 then return pct .. "|cffff9933Slow|r" end
    return pct .. "|cffff5544Missing bites|r"
end

function F.Summary()
    local s = S.session
    if s.casts == 0 then return end
    local mins = max((GetTime() - s.start) / 60, 0.01)
    local bestName, bestQ = nil, 0
    for name, q in pairs(s.fish) do if q > bestQ then bestName, bestQ = name, q end end
    Print(format("Session: %dm  ·  %d casts, %d catches (%d%% hooked)%s%s", floor(mins + 0.5), s.casts, s.catches,
        floor(s.catches / s.casts * 100 + 0.5),
        mins >= 1 and format("  ·  %.0f/hr", s.catches / mins * 60) or "",
        bestName and ("  ·  most caught: " .. bestName .. " x" .. bestQ) or ""), "cccccc")
    local newList = {}
    for name in pairs(s.new) do newList[#newList + 1] = name end
    if #newList > 0 then tsort(newList); Print("New species: " .. tconcat(newList, ", "), "80ff80") end
end

--------------------------------------------------------------------------------
-- Fishing mode
--------------------------------------------------------------------------------
-- Runs one optional step. If it fails, the rest of fishing mode still works,
-- and the error is shown once (and kept in db.lastError for bug reports).
S.reported = {}
function F.Safe(label, fn, ...)
    local ok, err = pcall(fn, ...)
    if not ok then
        db.lastError = label .. ": " .. tostring(err)
        if not S.reported[label] then
            S.reported[label] = true
            Print(label .. " ran into a problem and was skipped. Please report: " .. tostring(err), "ffd040")
        end
    end
    return ok
end

function F.Enable()
    if S.active or not db or InCombatLockdown() then return end
    S.active = true
    NewSession()
    FX.Build()

    F.SetCVar("SoftTargetInteract", 3)
    F.SetCVar("SoftTargetInteractGameObject", 1)
    F.SetCVar("SoftTargetInteractRange", 30)
    if db.isolateAudio then
        F.SetCVar("Sound_SFXVolume", db.targetSFX)
        F.SetCVar("Sound_MusicVolume", db.targetAmbience)
        F.SetCVar("Sound_AmbienceVolume", db.targetAmbience)
        F.SetCVar("Sound_DialogVolume", db.targetAmbience)
    end
    -- The game's own auto loot, only while fishing; your setting comes back after.
    if db.autoLoot then F.SetCVar("autoLootDefault", 1) end
    if db.bindMouse then
        SetOverrideBindingSpell(driver, true, "MOUSEWHEELUP", S.fishingName)
        SetOverrideBinding(driver, true, "MOUSEWHEELDOWN", "INTERACTTARGET")
    end

    F.Safe("Fishing map", function() GM.Build(); GM.Update() end)
    if db.cinematicMode then F.Safe("Cinematic mode", F.SetFocusScreen, true) end
    if db.showWindow then F.Safe("Fishing window", function() UI.Build(); W:Show() end) end
    F.Safe("Tackle scan", F.ScanTackle)
    F.Safe("Display", F.RefreshAll)
    local canInteract = GetCVar("SoftTargetInteract") ~= nil
    Print(db.bindMouse and (canInteract and "Ready. Wheel up to cast, wheel down to reel in." or "Ready. Wheel up to cast, click the bobber to reel in.") or "Ready.", "80ff80")
end

function F.Disable()
    if not S.active then return end
    S.active = false
    S.waitStart = nil

    if S.castTimer then S.castTimer:Cancel(); S.castTimer = nil end
    if S.waitTicker then S.waitTicker:Cancel(); S.waitTicker = nil end
    F.StopIdle()
    F.RestoreCVars() -- anything combat blocks is retried when combat ends
    if not InCombatLockdown() then ClearOverrideBindings(driver) end -- in combat the secure driver already did it
    F.Safe("Cinematic mode", F.SetFocusScreen, false)

    if FX.vig then FX.vig:Stop(); FX.status:Stop(); FX.tick:Hide(); FX.ring:Hide(); FX.ring.ripples:Stop() end
    if FX.banner then FX.banner:Hide() end
    F.Safe("Fishing map", GM.Update)
    F.Safe("Fishing window", UI.Refresh)

    F.Summary()
    Print("Standby. Controls restored.", "ff7766")
end

function F.ToggleMode() if S.active then F.Disable() else F.Enable() end end

--------------------------------------------------------------------------------
-- Fishing events
--------------------------------------------------------------------------------
function F.OnCast()
    if not S.active then F.Enable() end
    if not S.active then return end
    F.StopIdle()
    if S.castTimer then S.castTimer:Cancel(); S.castTimer = nil end

    S.castSerial = S.castSerial + 1
    S.lastCastTime = GetTime()
    S.waitStart = GetTime()
    local s = S.session
    s.casts = s.casts + 1
    local zs = F.ZoneStats(F.Zone()); zs.casts = zs.casts + 1
    if S.target.name then S.target.casts = S.target.casts + 1 end
    F.RefreshAll()
    F.QueueScan()

    PlayChoice(db.castSound)
    FX.status:Show("Cast", {0.75, 0.85, 1})
    if db.showCast then FX.vig:Play(db.castColor, 0.15, 0.7, false) end
    if db.showRing then
        FX.ring.arc:SetProgress(1); FX.ring:Show(); FX.ringFade:Play()
        FX.ring.ripples:Play(0.55, 0.8, 1, 0.9)
    end
    FX.tick:Show()
    GM.OnCast()

    -- After the splash settles: the waiting phase.
    S.castTimer = C_Timer.NewTimer(1.0, function()
        S.castTimer = nil
        if db.showWater then FX.vig:Play(db.waterColor, 1.2, 1.2, true) end
        GM.OnWait()
        S.waitTicker = S.waitTicker or C_Timer.NewTicker(3, function()
            if S.waitStart and S.active then GM.OnWait() end
        end)
    end)
end

function F.OnStop()
    if not S.active then return end
    S.lastStopTime = GetTime()
    S.waitStart = nil
    if S.castTimer then S.castTimer:Cancel(); S.castTimer = nil end
    if S.waitTicker then S.waitTicker:Cancel(); S.waitTicker = nil end
    -- Only the waiting cues end here; the catch celebration belongs to the loot event.
    FX.vig:Stop(); FX.tick:Hide(); FX.ring:Hide()
    GM.SetProgress(0)
    F.StartIdle()
end

-- A real catch = fishing loot. LOOT_READY fires before auto-loot empties the
-- window, and the serial check counts one cast once even if the event repeats.
function F.OnLoot()
    if not S.active or S.castSerial == 0 or S.loggedSerial == S.castSerial then return end
    local fishing = (IsFishingLoot and IsFishingLoot()) or (GetTime() - S.lastStopTime < 3)
    if not fishing then return end
    S.loggedSerial = S.castSerial

    local zone = F.Zone()
    local mapID, px, py = F.PlayerSpot()
    local newNames, firstName = {}, nil
    for i = 1, (GetNumLootItems() or 0) do
        if GetLootSlotType(i) == ((Enum.LootSlotType and Enum.LootSlotType.Item) or 1) then
            local _, name, qty = GetLootSlotInfo(i)
            if name and not IsSecret(name) then
                local link = GetLootSlotLink(i)
                local id = link and tonumber(link:match("item:(%d+)"))
                qty = qty or 1
                firstName = firstName or name
                if F.LogCatch(name, id, zone, qty, mapID, px, py) then
                    newNames[#newNames + 1] = name; S.session.new[name] = true
                end
                S.session.fish[name] = (S.session.fish[name] or 0) + qty
                if name == S.target.name then S.target.hits = S.target.hits + 1 end
            end
        end
    end
    local zs = F.ZoneStats(zone); zs.catches = zs.catches + 1
    local s = S.session
    s.catches = s.catches + 1
    if S.lastCastTime > 0 then s.catchTime = s.catchTime + (GetTime() - S.lastCastTime) end
    if s.casts >= 20 and not s.announced then
        s.announced = true
        Print("20-cast check: hook rate " .. F.HookRating(s.catches / s.casts) .. ".")
    end
    local t = S.target
    if t.name and t.casts >= 20 and not t.announced then
        t.announced = true
        Print(format("20-cast evaluation for %s: %d caught (%.0f%% per cast).", t.name, t.hits, t.hits / t.casts * 100))
    end
    F.RefreshAll()

    local isNew = #newNames > 0
    if db.showCatch then FX.vig:Play(db.catchColor, 0.06, 0.9, false) end
    if isNew then
        PlayChoice(db.newFishSound)
        FX.status:Show("New: " .. newNames[1] .. "!", C.gold)
        Print("First catch ever: " .. tconcat(newNames, ", ") .. " - added to your journal.", "80ff80")
    else
        PlayChoice(db.catchSound)
        FX.status:Show("Caught!", C.good)
    end
    GM.OnCatch(newNames[1] or firstName, isNew)
    GM.RefreshPins()
end

function F.SelectFish(name)
    S.target.name = (name ~= S.target.name) and name or nil
    S.target.casts, S.target.hits, S.target.announced = 0, 0, false
    F.RefreshAll()
    GM.RefreshPins()
end

--------------------------------------------------------------------------------
-- Launchers: addon compartment, keybindings, slash commands.
-- No minimap button, like the rest of the Lil's family.
--------------------------------------------------------------------------------
function F.OpenSettings()
    if InCombatLockdown() then Print("Settings open after combat.", "ffd040"); return end
    P:OpenSettings("fishing")
end

local function LauncherTooltip(owner)
    GameTooltip:SetOwner(owner, "ANCHOR_LEFT")
    GameTooltip:SetText(BRAND .. "  |cffffffff" .. VERSION .. "|r")
    GameTooltip:AddLine(S.active and (GOOD .. "Fishing mode on|r") or (MUTED .. "Standby|r"))
    GameTooltip:AddLine(" ")
    GameTooltip:AddLine("Left-click: fishing window", 1, 1, 1)
    GameTooltip:AddLine("Right-click: fishing mode on / off", 1, 1, 1)
    GameTooltip:AddLine("Shift-click: settings", 1, 1, 1)
    GameTooltip:Show()
end

function FishingBlinker_OnCompartmentClick(_, btn)
    if IsShiftKeyDown() then F.OpenSettings()
    elseif btn == "RightButton" then F.ToggleMode()
    else UI.Toggle() end
end
function FishingBlinker_OnCompartmentEnter(_, frame) LauncherTooltip(frame) end
function FishingBlinker_OnCompartmentLeave() GameTooltip:Hide() end
FishingBlinker_Toggle = function() F.ToggleMode() end
FishingBlinker_ToggleWindow = function() UI.Toggle() end
BINDING_HEADER_FISHINGBLINKER = TITLE
BINDING_NAME_FISHINGBLINKER_TOGGLE = "Fishing mode on / off"
BINDING_NAME_FISHINGBLINKER_WINDOW = "Fishing window"

local function ParseItemID(msg) return tonumber(msg:match("item:(%d+)") or msg:match("(%d+)")) end

SLASH_FISHINGBLINKER1 = "/fb"
SLASH_FISHINGBLINKER2 = "/blinker"
SlashCmdList["FISHINGBLINKER"] = function(msg)
    if not db then print(BRAND .. ": switched off. Turn it on in /pw settings > Modules."); return end
    local cmd, rest = (msg or ""):match("^(%S*)%s*(.-)$")
    cmd = cmd:lower()
    if cmd == "" then UI.Toggle()
    elseif cmd == "config" or cmd == "settings" or cmd == "options" then F.OpenSettings()
    elseif cmd == "on" then F.Enable()
    elseif cmd == "off" then F.Disable()
    elseif cmd == "toggle" then F.ToggleMode()
    elseif cmd == "new" or cmd == "reset" then NewSession(); F.RefreshAll(); Print("New session started.")
    elseif cmd == "add" then
        local id = ParseItemID(rest)
        if not id then Print("Usage: /fb add <item link or ID> [toy|gear|lure]", "ffd040"); return end
        local kind = rest:match("%s(%a+)%s*$")
        if kind ~= "toy" and kind ~= "gear" and kind ~= "lure" then
            kind = (PlayerHasToy and PlayerHasToy(id)) and "toy" or ((C_Item.GetItemInventoryTypeByID(id) or 0) ~= 0 and "gear") or "lure"
        end
        db.custom[id] = kind
        Print("Added " .. (C_Item.GetItemNameByID(id) or id) .. " as " .. kind .. ".")
        F.QueueScan()
    elseif cmd == "remove" then
        local id = ParseItemID(rest)
        if not id then Print("Usage: /fb remove <item link or ID>", "ffd040"); return end
        db.custom[id] = nil; Print("Removed item " .. id .. ".")
        F.QueueScan()
    elseif cmd == "status" then
        local map = rawget(_G, "BattlefieldMapFrame")
        Print(format("GoodMap %s  ·  map %s  ·  fishing map %s  ·  fishing mode %s",
            (P.GoodMap.ready and "on" or "off"),
            (type(map) == "table" and (map:IsShown() and "shown" or "hidden") or "missing"),
            (GM.on and "on" or (GM.layer and "ready" or "not built")),
            (S.active and "on" or "off")))
        if db.lastError then Print("Last problem: " .. db.lastError, "ffd040") end
    elseif cmd == "catches" then
        local zone, parts = F.Zone(), {}
        local list = F.FishList(zone)
        for i = 1, min(10, #list) do parts[i] = list[i].name .. " x" .. list[i].q end
        Print(zone .. ": " .. (#parts > 0 and tconcat(parts, ", ") or "nothing logged yet."))
    else
        Print("/fb  window  ·  /fb config  ·  /fb on | off  ·  /fb new  ·  /fb add <item>  ·  /fb remove <item>  ·  /fb catches  ·  /fb status")
    end
end

--------------------------------------------------------------------------------
-- Settings: Options > AddOns > Lil's Fishing Blinker (native, like GoodMap)
--------------------------------------------------------------------------------
-- Fishing's settings, drawn in Pathway's window.
function F.PathwaySettings(api)
    local hooks = {}
    P.stores.fish = {
        get = function(k) return db and db[k] end,
        set = function(k, v) if db then db[k] = v; if hooks[k] then hooks[k](v) end end end,
    }
    local p = api.Page("fishing", "Fishing", "Scroll up to cast, scroll down to reel in. Cast Fishing once, or use your keybind, to start.")
    local function Header(text) if text ~= TITLE then p:Section(text) end end
    local function Check(key, name, tip, onSet) hooks[key] = onSet; return p:Toggle(name, tip, "fish." .. key) end
    local function Slider(key, name, tip, lo, hi, step, fmt, onSet) hooks[key] = onSet; return p:Slider(name, lo, hi, step, "fish." .. key, fmt, 1, tip) end
    local function Dropdown(key, name, tip, values, onSet) hooks[key] = onSet; return p:Dropdown(name, values, "fish." .. key, tip) end
    local function Color(key, name) return p:Color(name, "fish." .. key) end
    local function Button(name, text, fn, tip) return p:Button(text, fn, false, tip) end
    local Pct = function(v) return floor(v * 100 + 0.5) .. "%" end
    local Sec = function(v) return floor(v + 0.5) .. " s" end
    local live = function() if S.active then F.RefreshAll(); GM.Update() end end
    local liveAudio = function(cvars) return function(v) if S.active and db.isolateAudio then for _, c in ipairs(cvars) do F.SetCVar(c, v) end end end end
    Header(TITLE)
    Button("Fishing window", "Open", function() if SettingsPanel then HideUIPanel(SettingsPanel) end; UI.Toggle() end, "Your tackle, session, journal and catch rates.")
    Button("Fishing mode", "On / Off", function() F.ToggleMode() end, "Casting Fishing also turns it on.")

    Header("Fishing mode")
    Check("bindMouse", "Mouse-wheel controls", "Wheel up casts, wheel down reels in. Each scroll is one action, and the binding drops the instant combat starts.")
    Check("autoLoot", "Auto loot while fishing", "Turns on the game's own auto loot while fishing mode is on, and puts your setting back afterwards.",
        function(on) if S.active then if on then F.SetCVar("autoLootDefault", 1) else F.RestoreCVar("autoLootDefault") end end end)
    Check("cinematicMode", "Cinematic mode", "Fades your action bars, unit frames and other HUD clutter while you fish, leaving chat, your minimap and Lil's GoodMap. Windows you open stay visible.",
        function(on) if S.active then F.SetFocusScreen(on); FX.RefreshBanner() end end)
    Check("showWindow", "Open the fishing window when fishing starts")
    Check("showCountdown", "Standby countdown", "Shows the last 15 seconds before fishing mode switches itself off.")
    Slider("idleTimeout", "Standby after", "Fishing mode switches off after this long without a cast.", 20, 120, 5, Sec)

    Header("Minimap")
    Check("mapFX", "Fishing map", GM.Available() and "While you fish, GoodMap turns into a fishing map: water glow, a bite-timer ring around the edge, ripples on every cast and catch." or "Turn on Pathway's minimap (Modules) to get a fishing map while you fish.", live)
    Dropdown("mapSpots", "Fishing spots on the map", "Where you've caught fish, as glowing markers. Gold markers have your target fish.",
        {"FISHING", "While fishing", "ALWAYS", "Always", "NEVER", "Never"}, function() GM.RefreshPins() end)
    Check("mapInfo", "Session info on the map", "Catches, hook rate and your target's chance along the bottom of the map.", function() GM.RefreshInfo() end)

    Header("Screen cues")
    Check("showRing", "Bite timer", "A ring above your character that drains as the cast runs out.")
    Check("showStatus", "Cast and catch words")
    Check("showCast", "Cast glow")
    Color("castColor", "Cast glow color")
    Check("showWater", "Waiting glow", "A slow pulse at the edges of the screen while your line is in the water.")
    Color("waterColor", "Waiting glow color", "Also tints the water on the fishing map.")
    Check("showCatch", "Catch glow")
    Color("catchColor", "Catch glow color")

    Header("Sound")
    Check("isolateAudio", "Audio isolation", "Sound effects up; music, ambience and dialog down, so the splash is easy to hear. Master volume is never touched, and everything is put back afterwards.")
    Slider("targetSFX", "Sound effects", nil, 0, 1, 0.05, Pct, liveAudio({"Sound_SFXVolume"}))
    Slider("targetAmbience", "Music, ambience and dialog", nil, 0, 1, 0.05, Pct, liveAudio({"Sound_MusicVolume", "Sound_AmbienceVolume", "Sound_DialogVolume"}))
    Dropdown("castSound", "Cast sound", nil, SOUNDS, PlayChoice)
    Dropdown("catchSound", "Catch sound", nil, SOUNDS, PlayChoice)
    Dropdown("newFishSound", "New species sound", nil, SOUNDS, PlayChoice)

    Header("Tackle and journal")
    Check("showSmartLure", "Suggest the next piece of tackle", "Highlights what to equip or apply next, with a one-click button. Each click does one thing.")
    Check("tooltip", "Catch history on fish tooltips")

end

P:AddSettings("EXTRAS", function(api) if NS.ready then F.PathwaySettings(api) end end)

--------------------------------------------------------------------------------
-- Tooltips: "caught x42 - best: Azj-Kahet (30)"
--------------------------------------------------------------------------------
function F.HookTooltips()
    if not (TooltipDataProcessor and Enum and Enum.TooltipDataType) then return end
    TooltipDataProcessor.AddTooltipPostCall(Enum.TooltipDataType.Item, function(tt, data)
        if not (db and db.tooltip) or InCombatLockdown() or not data then return end
        local id = data.id
        if not id or IsSecret(id) then return end
        local name = S.idIndex[id]
        local rec = name and db.log[name]
        if not rec then return end
        local zone, n = BestZone(rec)
        tt:AddLine(format("%sFishing Blinker:|r caught x%d%s", ACCENT, rec.total, zone and format("  ·  best: %s (%d)", zone, n) or ""), 0.9, 0.9, 0.9)
    end)
end

--------------------------------------------------------------------------------
-- Saved variables
--------------------------------------------------------------------------------
function F.Migrate()
    db.log = db.log or {}
    db.zoneStats = db.zoneStats or {}
    db.custom = db.custom or {}
    -- v1.3: per-zone name counts
    if db.catches then
        for zone, t in pairs(db.catches) do
            for name, n in pairs(t) do
                local rec = FishRecord(name); local z = ZoneRecord(rec, zone)
                rec.total, rec.catches, z.n, z.q = rec.total + n, rec.catches + n, z.n + n, z.q + n
            end
        end
        db.catches = nil
    end
    if db.customLures then
        for id in pairs(db.customLures) do db.custom[id] = "lure" end
        db.customLures = nil
    end
    local v = db.schema or 1
    if v < 2 then
        -- split catches (loot windows) from items
        for _, rec in pairs(db.log) do
            rec.catches = rec.catches or rec.total or 0
            for _, z in pairs(rec.zones or {}) do z.q = z.q or z.n; z.spots = z.spots or {} end
        end
        for _, s in pairs(db.zoneStats) do s.casts, s.catches = s.casts or 0, s.catches or 0 end
    end
    if v < 3 then
        -- colours become hex strings for the native colour pickers; sounds by name
        for _, key in ipairs({"castColor", "waterColor", "catchColor"}) do
            if type(db[key]) == "table" then db[key] = DEFAULTS[key] end
        end
        if type(db.castSound) ~= "string" then db.castSound = DEFAULTS.castSound end
        if type(db.catchSound) ~= "string" then db.catchSound = DEFAULTS.catchSound end
        for _, old in ipairs({"biteSound", "castSpeed", "waterSpeed", "shrinkSpeed", "catchSpeed", "showCastIcon",
            "showShrinkIcon", "showCaughtIcon", "showTracker", "showJournal", "showReadiness", "minimapAngle", "hideMinimapButton"}) do
            db[old] = nil
        end
        if db.pos then db.pos.tackle, db.pos.journal = nil, nil end
    end
    db.schema = DEFAULTS.schema
    for _, rec in pairs(db.log) do rec.catches = rec.catches or rec.total or 0 end
    for name, rec in pairs(db.log) do if rec.id then S.idIndex[rec.id] = name end end
end

--------------------------------------------------------------------------------
-- Event hub
--------------------------------------------------------------------------------
local hub = CreateFrame("Frame")
for _, e in ipairs({"ADDON_LOADED", "PLAYER_LOGIN", "PLAYER_LOGOUT", "PLAYER_REGEN_DISABLED", "PLAYER_REGEN_ENABLED",
    "BAG_UPDATE_DELAYED", "PLAYER_EQUIPMENT_CHANGED", "GET_ITEM_INFO_RECEIVED", "ZONE_CHANGED_NEW_AREA", "LOOT_READY"}) do
    hub:RegisterEvent(e)
end
hub:RegisterUnitEvent("UNIT_AURA", "player")
hub:RegisterUnitEvent("UNIT_SPELLCAST_CHANNEL_START", "player")
hub:RegisterUnitEvent("UNIT_SPELLCAST_CHANNEL_STOP", "player")

hub:SetScript("OnEvent", function(self, event, ...)
    if event == "ADDON_LOADED" then
        if (...) ~= ADDON_NAME then return end
        PathwayFishDB = PathwayFishDB or {}
        db = PathwayFishDB
        local fresh, prevSchema = next(db) == nil, db.schema
        for k, v in pairs(DEFAULTS) do if db[k] == nil then db[k] = v end end
        db.schema = fresh and DEFAULTS.schema or (prevSchema or 1)
        F.Migrate()
        self:UnregisterEvent("ADDON_LOADED")
        if PathwayDB and PathwayDB.settings and PathwayDB.settings.fishing == false then
            self:UnregisterAllEvents()
            db = nil
            return
        end
    elseif not db then
        return
    elseif event == "PLAYER_LOGIN" then
        S.fishingName = (C_Spell and C_Spell.GetSpellName and C_Spell.GetSpellName(FISHING_BASE_ID)) or "Fishing"
        S.fishingKey = S.fishingName:lower()
        F.RestoreCVars() -- undo anything left from a crash or a /reload mid-session
        F.HookTooltips()
        NS.ready = true
        pcall(GM.Build)
    elseif event == "PLAYER_LOGOUT" then
        F.RestoreCVars()
    elseif event == "PLAYER_REGEN_DISABLED" then
        F.Disable()
    elseif event == "PLAYER_REGEN_ENABLED" then
        F.RestoreCVars()
        F.QueueScan()
    elseif event == "LOOT_READY" then
        F.OnLoot()
    elseif event == "ZONE_CHANGED_NEW_AREA" then
        if S.active then F.RefreshAll() end
    elseif event == "UNIT_SPELLCAST_CHANNEL_START" or event == "UNIT_SPELLCAST_CHANNEL_STOP" then
        if InCombatLockdown() then return end
        local _, _, spellID = ...
        if not spellID or IsSecret(spellID) then return end
        if not FISHING_IDS[spellID] then
            local n = C_Spell and C_Spell.GetSpellName and C_Spell.GetSpellName(spellID)
            if n ~= S.fishingName then return end
        end
        if event == "UNIT_SPELLCAST_CHANNEL_START" then F.OnCast() else F.OnStop() end
    else
        F.QueueScan() -- bags, gear, auras, item info: coalesced into one rescan
    end
end)
Pathway.Perf.Hook(hub, "Fishing", "OnEvent")
end part() end
-- ==================== Settings.lua
do local __addon, __ns = ... local function part()
-- Copyright (C) 2026 SoFinSicc. Part of Pathway (curseforge.com/wow/addons/pathway): free software under the GPLv3 or later, with additional terms that require keeping this credit. See LICENSE.md.
--[[ Pathway — Settings
     One window for every module: pages on the left grouped by what they're
     about, plain-language options on the right, everything applies at once.
     Modules (bags, the minimap, fishing) add their own pages through
     P:AddSettings, and their options are read and written through "stores",
     so a page never needs to know where a value lives. ]]

local ADDON, P = __addon, __ns
local A = P.ACCENT
local ipairs, pairs, floor, max, min, type = ipairs, pairs, math.floor, math.max, math.min, type

local win, pages, order, nav, current = nil, {}, {}, {}, nil
local NAV_W, W, H = 168, 700, 560
local BODY_W = W - NAV_W - 52

local ACCENTS = {
	{ "Pathway green", { 0.21, 0.82, 0.5 } }, { "Mint", { 0.431, 0.906, 0.718 } }, { "Gold", { 1, 0.82, 0.36 } }, { "Sky", { 0.42, 0.72, 1 } },
	{ "Rose", { 1, 0.5, 0.62 } }, { "Violet", { 0.72, 0.56, 1 } }, { "Ember", { 1, 0.56, 0.3 } },
}

P.ACCENTS = ACCENTS

local function S() return P.db.settings end
local function Changed() P:ApplyTheme(); P:Send("SETTINGS_CHANGED") end

---------------------------------------------------------------------------
-- Stores: "bags.view", "map.follow", "fish.autoLoot"... or a plain Pathway key
---------------------------------------------------------------------------
P.stores = {
	bags = {
		get = function(k) return P.Bags.db and P.Bags.db.settings[k] end,
		set = function(k, v)
			local GB = P.Bags
			if not GB.db then return end
			GB.db.settings[k] = v
			GB:ApplyTheme(); GB:LayoutAll()
		end,
	},
}

local function Split(key)
	local prefix, rest = key:match("^(%a+)%.(.+)$")
	if prefix and P.stores[prefix] then return P.stores[prefix], rest end
end
local function Get(key)
	local st, k = Split(key)
	if st then return st.get(k) end
	return S()[key]
end
local function Set(key, v)
	local st, k = Split(key)
	if st then st.set(k, v) else S()[key] = v; Changed() end
	if win and win:IsShown() and current then pages[current]:Refresh() end
end
P.GetSetting, P.SetSetting = Get, Set

StaticPopupDialogs["PATHWAY_RESET"] = {
	text = "Pathway: put every setting back to how it came, for all your characters? Your learned quests are kept. This reloads your UI.",
	button1 = OKAY or "Okay", button2 = CANCEL or "Cancel",
	OnAccept = function() P:ResetAll() end,
	timeout = 0, whileDead = 1, hideOnEscape = 1,
}

StaticPopupDialogs["PATHWAY_RELOAD"] = {
	text = "Pathway: this change needs a quick UI reload. Reload now?",
	button1 = RELOADUI or "Reload", button2 = LATER or "Later",
	OnAccept = function() ReloadUI() end,
	timeout = 0, whileDead = 1, hideOnEscape = 1,
}

---------------------------------------------------------------------------
-- Widgets. Every control is a row; a row can depend on others (dimmed when off).
---------------------------------------------------------------------------
local function Label(parent, text, font, x, y, width)
	local fs = parent:CreateFontString(nil, "OVERLAY")
	fs:SetFontObject(font or P.fonts.button)
	fs:SetPoint("TOPLEFT", x, y)
	if width then fs:SetWidth(width) end
	fs:SetJustifyH("LEFT")
	fs:SetText(text)
	return fs
end

local Builder = {}
Builder.__index = Builder

local function NewRow(self, h)
	local row = CreateFrame("Frame", nil, self.frame)
	row:SetPoint("TOPLEFT", 0, self.y)
	row:SetSize(BODY_W, h)
	self.rows[#self.rows + 1] = row
	return row
end

function Builder:Grow(h) self.y = self.y - h end

function Builder:Refresh()
	for _, fn in ipairs(self.refreshers) do fn() end
	for _, row in ipairs(self.rows) do
		if row.predicate then
			local on = row.predicate() and true or false
			row:SetAlpha(on and 1 or 0.4)
			if row.control then row.control:EnableMouse(on) end
		end
	end
end

-- dim a row while its parent option is off
function Builder:Depends(row, predicate) if row then row.predicate = predicate end; return row end

function Builder:Section(text)
	self:Grow(8)
	local row = NewRow(self, 22)
	Label(row, text:upper(), P.fonts.head, 0, 0)
	local line = row:CreateTexture(nil, "ARTWORK")
	line:SetHeight(1); line:SetColorTexture(1, 1, 1, 0.06)
	line:SetPoint("TOPLEFT", 0, -14); line:SetPoint("TOPRIGHT", -10, -14)
	self:Grow(22)
end

local function Desc(row, desc, x, y, width)
	if not desc then return 0 end
	local d = Label(row, P.DIM .. desc .. "|r", P.fonts.head, x, y, width)
	return d:GetStringHeight()
end

function Builder:Toggle(label, desc, key, reload)
	local row = NewRow(self, 24)
	local c = CreateFrame("Button", nil, row, "BackdropTemplate")
	c:SetSize(30, 16)
	c:SetPoint("TOPLEFT", 0, 0)
	P.Flat(c, P.colors.PANEL)
	c.knob = c:CreateTexture(nil, "OVERLAY")
	c.knob:SetSize(12, 12)
	Label(row, label, P.fonts.button, 40, 1)
	local dh = Desc(row, desc, 40, -14, BODY_W - 50)
	local function draw()
		local on = Get(key)
		c.knob:ClearAllPoints()
		if on then
			c.knob:SetPoint("RIGHT", -2, 0); c.knob:SetColorTexture(A[1], A[2], A[3], 1)
			c:SetBackdropBorderColor(A[1], A[2], A[3], 0.8)
		else
			c.knob:SetPoint("LEFT", 2, 0); c.knob:SetColorTexture(0.45, 0.48, 0.52, 1)
			c:SetBackdropBorderColor(unpack(P.colors.EDGE))
		end
	end
	c:SetScript("OnClick", function()
		Set(key, not Get(key))
		draw()
		PlaySound(SOUNDKIT.IG_MAINMENU_OPTION_CHECKBOX_ON or 856)
		if reload then StaticPopup_Show("PATHWAY_RELOAD") end
	end)
	draw()
	self.refreshers[#self.refreshers + 1] = draw
	row.control = c
	local h = (dh > 0 and (18 + dh) or 20) + 6
	row:SetHeight(h)
	self:Grow(h)
	return row
end

local function Format(fmt, v)
	if type(fmt) == "function" then return fmt(v) end
	return (fmt or "%d"):format(v)
end

function Builder:SliderFn(label, lo, hi, step, get, set, fmt, desc)
	local row = NewRow(self, 26)
	Label(row, label, P.fonts.button, 0, 0)
	local track = CreateFrame("Slider", nil, row, "BackdropTemplate")
	track:SetOrientation("HORIZONTAL")
	track:SetSize(200, 8)
	track:SetPoint("TOPLEFT", 190, -3)
	P.Flat(track, P.colors.PANEL)
	local thumb = track:CreateTexture(nil, "OVERLAY")
	thumb:SetSize(10, 16)
	track:SetThumbTexture(thumb)
	track:SetMinMaxValues(lo, hi)
	track:SetValueStep(step)
	track:SetObeyStepOnDrag(true)
	track:EnableMouseWheel(false)
	local val = Label(row, "", P.fonts.button, 400, 0)
	local busy
	track:SetScript("OnValueChanged", function(_, v)
		if busy then return end
		v = floor(v / step + 0.5) * step
		val:SetText(Format(fmt, v))
		P:Debounce("slider" .. label, 0.1, function() set(v) end)
	end)
	local function draw()
		thumb:SetColorTexture(A[1], A[2], A[3], 1)
		local v = get() or lo
		busy = true; track:SetValue(v); busy = false
		val:SetText(Format(fmt, v))
	end
	draw()
	self.refreshers[#self.refreshers + 1] = draw
	row.control = track
	local dh = Desc(row, desc, 0, -18, BODY_W - 10)
	local h = 26 + (dh > 0 and dh + 2 or 0)
	row:SetHeight(h)
	self:Grow(h)
	return row
end

function Builder:Slider(label, lo, hi, step, key, fmt, scale, desc)
	scale = scale or 1
	return self:SliderFn(label, lo * 1, hi * 1, step,
		function() return (Get(key) or 0) * scale end,
		function(v) Set(key, v / scale) end, fmt, desc)
end

-- values: { value1, "Label 1", value2, "Label 2", ... }
function Builder:Dropdown(label, values, key, desc)
	local row = NewRow(self, 26)
	Label(row, label, P.fonts.button, 0, 0)
	local b = P:FlatButton(row, "")
	b.minW = 180
	b:SetPoint("TOPLEFT", 190, 3)
	local function name(v)
		for i = 1, #values, 2 do if values[i] == v then return values[i + 1] end end
		return tostring(v)
	end
	local function draw() b:SetLabel(name(Get(key)) .. "  " .. P.DIM .. "v|r") end
	b:SetScript("OnClick", function(self)
		local menu = MenuUtil or P.MiniMenu
		menu.CreateContextMenu(self, function(_, root)
			for i = 1, #values, 2 do
				local v = values[i]
				root:CreateRadio(values[i + 1], function() return Get(key) == v end, function() Set(key, v); draw() end, v)
			end
		end)
	end)
	draw()
	self.refreshers[#self.refreshers + 1] = draw
	row.control = b
	local dh = Desc(row, desc, 0, -20, BODY_W - 10)
	local h = 28 + (dh > 0 and dh + 2 or 0)
	row:SetHeight(h)
	self:Grow(h)
	return row
end

-- a row of buttons for a few choices
function Builder:Choice(label, options, key, desc)
	local row = NewRow(self, 26)
	Label(row, label, P.fonts.button, 0, 0)
	local x, btns = 190, {}
	for _, o in ipairs(options) do
		local b = P:FlatButton(row, o[2])
		b:SetPoint("TOPLEFT", x, 3)
		b:SetScript("OnClick", function() Set(key, o[1]); for _, bb in ipairs(btns) do bb.draw() end end)
		b.draw = function()
			local on = Get(key) == o[1]
			b.text:SetTextColor(on and A[1] or 0.85, on and A[2] or 0.87, on and A[3] or 0.9)
			b:SetBackdropBorderColor(unpack(on and P.colors.ACCENT_EDGE or P.colors.EDGE))
		end
		b:SetScript("OnLeave", function() b.draw(); GameTooltip:Hide() end)
		b.draw()
		btns[#btns + 1] = b
		x = x + b:GetWidth() + 4
	end
	self.refreshers[#self.refreshers + 1] = function() for _, b in ipairs(btns) do b.draw() end end
	local dh = Desc(row, desc, 190, -22, BODY_W - 200)
	local h = 28 + (dh > 0 and dh + 2 or 0)
	row:SetHeight(h)
	self:Grow(h)
	return row
end

-- a color stored as "aarrggbb"
function Builder:Color(label, key)
	local row = NewRow(self, 24)
	Label(row, label, P.fonts.button, 0, 0)
	local sw = CreateFrame("Button", nil, row, "BackdropTemplate")
	sw:SetSize(34, 16)
	sw:SetPoint("TOPLEFT", 190, 1)
	P.Flat(sw, { 1, 1, 1, 1 }, P.colors.EDGE)
	local function rgba()
		local hex = Get(key) or "ffffffff"
		local a, r, g, b = tonumber(hex:sub(1, 2), 16), tonumber(hex:sub(3, 4), 16), tonumber(hex:sub(5, 6), 16), tonumber(hex:sub(7, 8), 16)
		return (r or 255) / 255, (g or 255) / 255, (b or 255) / 255, (a or 255) / 255
	end
	local function draw() local r, g, b = rgba(); sw:SetBackdropColor(r, g, b, 1) end
	local function store(r, g, b, a) Set(key, ("%02x%02x%02x%02x"):format(floor((a or 1) * 255), floor(r * 255), floor(g * 255), floor(b * 255))); draw() end
	sw:SetScript("OnClick", function()
		local r, g, b, a = rgba()
		if ColorPickerFrame.SetupColorPickerAndShow then
			ColorPickerFrame:SetupColorPickerAndShow({
				r = r, g = g, b = b, opacity = a, hasOpacity = true,
				swatchFunc = function() local nr, ng, nb = ColorPickerFrame:GetColorRGB(); store(nr, ng, nb, ColorPickerFrame:GetColorAlpha()) end,
				opacityFunc = function() local nr, ng, nb = ColorPickerFrame:GetColorRGB(); store(nr, ng, nb, ColorPickerFrame:GetColorAlpha()) end,
				cancelFunc = function() store(r, g, b, a) end,
			})
		else
			ColorPickerFrame.func = function() local nr, ng, nb = ColorPickerFrame:GetColorRGB(); store(nr, ng, nb, a) end
			ColorPickerFrame.cancelFunc = function() store(r, g, b, a) end
			ColorPickerFrame.hasOpacity = false
			ColorPickerFrame:SetColorRGB(r, g, b)
			ShowUIPanel(ColorPickerFrame)
		end
	end)
	draw()
	self.refreshers[#self.refreshers + 1] = draw
	row.control = sw
	self:Grow(26)
	return row
end

function Builder:Swatches(label)
	local row = NewRow(self, 26)
	Label(row, label, P.fonts.button, 0, 0)
	local x, list = 190, {}
	local function same(a, b) return math.abs(a[1] - b[1]) + math.abs(a[2] - b[2]) + math.abs(a[3] - b[3]) < 0.02 end
	local function set(c) S().accent = { c[1], c[2], c[3] }; Changed(); pages[current]:Refresh() end
	local function add(name, color)
		local b = CreateFrame("Button", nil, row, "BackdropTemplate")
		b:SetSize(22, 18)
		b:SetPoint("TOPLEFT", x, 2)
		P.Flat(b, { color[1], color[2], color[3], 1 }, P.colors.EDGE)
		b:SetScript("OnEnter", function() GameTooltip:SetOwner(b, "ANCHOR_TOP"); GameTooltip:SetText(name, 1, 1, 1); GameTooltip:Show() end)
		b:SetScript("OnLeave", GameTooltip_Hide)
		b:SetScript("OnClick", function() set(color) end)
		b.color = color
		list[#list + 1] = b
		x = x + 26
	end
	for _, a in ipairs(ACCENTS) do add(a[1], a[2]) end
	local cls = P.me.classFile
	local cc = cls and RAID_CLASS_COLORS and RAID_CLASS_COLORS[cls]
	if cc then add("Class color", { cc.r, cc.g, cc.b }) end
	local function draw()
		for _, b in ipairs(list) do b:SetBackdropBorderColor(unpack(same(b.color, S().accent) and { 1, 1, 1, 1 } or P.colors.EDGE)) end
	end
	draw()
	self.refreshers[#self.refreshers + 1] = draw
	self:Grow(28)
	return row
end

function Builder:Button(label, fn, accent, desc)
	local row = NewRow(self, 24)
	local b = P:FlatButton(row, label, accent)
	b:SetPoint("TOPLEFT", 0, 2)
	b:SetScript("OnClick", fn)
	row.control = b
	local dh = 0
	if desc then dh = Desc(row, desc, b:GetWidth() + 10, -1, BODY_W - 20 - b:GetWidth()) end
	local h = max(26, dh + 8)
	row:SetHeight(h)
	self:Grow(h)
	return row
end

function Builder:Text(text)
	local row = NewRow(self, 20)
	local fs = Label(row, text, P.fonts.button, 0, 0, BODY_W - 10)
	fs:SetSpacing(3)
	local h = fs:GetStringHeight() + 10
	row:SetHeight(h)
	self:Grow(h)
	return row
end

---------------------------------------------------------------------------
-- Pages
---------------------------------------------------------------------------
local function NewPage(key, title, blurb, group)
	local scroll = CreateFrame("ScrollFrame", nil, win.body)
	scroll:SetAllPoints()
	scroll:Hide()
	local p = CreateFrame("Frame", nil, scroll)
	p:SetSize(BODY_W, 10)
	scroll:SetScrollChild(p)
	scroll:EnableMouseWheel(true)
	scroll:SetScript("OnMouseWheel", function(self, delta)
		local maxV = max(0, p:GetHeight() - self:GetHeight())
		self:SetVerticalScroll(min(maxV, max(0, self:GetVerticalScroll() - delta * 60)))
	end)
	local b = setmetatable({ frame = p, scroll = scroll, y = -6, refreshers = {}, rows = {} }, Builder)
	local row = NewRow(b, 20)
	Label(row, title, P.fonts.title, 0, 0)
	b:Grow(20)
	if blurb then
		local d = Label(row, P.DIM .. blurb .. "|r", P.fonts.head, 0, -20, BODY_W - 10)
		b:Grow(max(16, d:GetStringHeight() + 6))
	end
	b:Grow(6)
	pages[key] = b
	order[#order + 1] = { key = key, title = title, group = group }
	return b
end

local function Finish(b) b.frame:SetHeight(-b.y + 20) end


local function Off(p, module, what)
	p:Text(P.DIM .. what .. " is switched off. Turn it on under Modules (it takes a quick reload).|r")
end

local function Adv() return S().showAdvanced end
local Relayout

-- pages the minimap and fishing modules add; Pathway adds its own rows at the end of some
local EXTRA_ROWS = {
	gm_general = function(p)
		p:Section("Look")
		p:Button("Style your minimap", function() P:ShowMapLook(true) end, true, "Edge, glow, the facing glow and your arrow, with a live preview.")
		p:Section("Pathway on the minimap")
		p:Toggle("Quest pins", "Who to pick up from and turn in to, and where your objectives are. They follow the icon scale above.", "gmPins")
		p:Toggle("Your route", "Dotted to your next stops, numbered.", "minimapPath")
		p:Toggle("Quest spots", "Every objective spot, each quest in its own color: the guide's quest in your accent color, the next spot pulsing, spots you've checked hollow.", "questLayer")
		p:Toggle("Tracking everywhere", "What you track, at all times: inside the radar the game's own live blips, and everywhere it isn't (indoors, on a flight, past its edge) the herbs and ore you can gather and the town services you track, from Pathway's own data.", "indoorBlips")
		p:Choice("Flight path icons", { { "undiscovered", "Not found yet" }, { "all", "All" }, { "off", "Off" } }, "flightPins")
		p:Button("Find the nearest...", function(b) P.Find:Menu(b) end, false, "Repair, mailbox, flight master, innkeeper, trainers, bank.")
	end,
}

local function Providers(group)
	for _, prov in ipairs(P.settingsProviders) do
		if prov.group == group then
			local made = {}
			local api = {
				Page = function(key, title, blurb)
					if made[#made] then Finish(made[#made]) end
					local pg = NewPage(key, title, blurb, prov.group)
					pg.key = key
					made[#made + 1] = pg
					return pg
				end,
			}
			local ok, err = pcall(prov.fn, api)
			if not ok then geterrorhandler()(err) end
			local last = made[#made]
			if last then
				if EXTRA_ROWS[last.key] then EXTRA_ROWS[last.key](last) end
				Finish(last)
			end
		end
	end
end

