		p:Depends(p:Text(P.DIM .. "Simple: your own number. Standard: everyone in your party or raid, bars moving live. Detailed: plus a bar from your worst to your best fight, your average marked, this fight moving along it.|r"), meterOn)
		p:Depends(p:Choice("Starts on", { { "damage", "Damage" }, { "healing", "Healing" }, { "taken", "Damage taken" } }, "meterMode"), meterOn)
		p:Depends(p:Toggle("Only in combat", "Shows when a fight starts and stays 20 seconds after it ends.", "meterCombatOnly"), meterOn)
		local function groupOn() return S().meter and (S().meterStyle or "detailed") ~= "simple" end
		p:Depends(p:Slider("Players shown", 3, 20, 1, "meterRows", "%d"), groupOn)
		p:Depends(p:Toggle("Group total line", "Your whole group's damage per second under the bars.", "meterGroupLine"), groupOn)
		p:Depends(p:Toggle("Player card on hover", "Point at a name for their card: spec, gear, rank.", "meterCards"), groupOn)
		p:Depends(p:Slider("Meter size", 70, 150, 10, "meterScale", "%d%%", 100), meterOn)
	end
	Finish(p)

	-- Advanced ---------------------------------------------------------------
	if P.Bags.db then
		p = NewPage("bags_adv", "Bag details", "Badges, colors and the finer Loot Inbox options.", "ADVANCED")
		p:Choice("Quality colors", { { "full", "Full" }, { "subtle", "Subtle" }, { "off", "Off" } }, "bags.qualityTint")
		p:Toggle("Replace Blizzard's bags", "Off: another addon can own your bags. Pathway's still open with /gb.", "bags.takeOverBags", true)
		p:Section("Badges")
		p:Toggle("Item level", nil, "bags.showIlvl")
		p:Toggle("Bind on Equip tags", nil, "bags.showBind")
		p:Toggle("Upgrade arrows", "Soft, bright or pulsing, by how much better it is.", "bags.showUpgrade")
		p:Toggle("Split stack tags", nil, "bags.showSplit")
		p:Section("Loot Inbox")
		p:Toggle("Sort the Inbox when I leave a vendor or bank", nil, "bags.autoClear")
		p:Section("Gear")
		p:Button("Forget items I said Never to", function() wipe(P.cdb.ignoredGear); P:Toast("Cleared") end)
		Finish(p)
	end
	Providers("ADVANCED")

	p = NewPage("about", "About", nil, "")
	p:Text(P.TITLE .. "  " .. P.DIM .. "v" .. P.VERSION .. "  ·  for World of Warcraft: Forever|r")
	p:Text("Pathway by |cffffffffSoFinSicc|r  " .. P.DIM .. "·  curseforge.com/wow/addons/pathway\nFree under the GPLv3, with credit required: anything based on Pathway keeps this credit and a name of its own (LICENSE.md).|r")
	p:Text("|cffffffffCommands|r\n/pw  next set   ·   /pw journal   ·   /pw story   ·   /pw zone   ·   /pw flights\n/pw guide   ·   /pw skip   ·   /pw stop   ·   /pw gear   ·   /pw talents   ·   /pw find mail   ·   /pw settings\n/gb  bags   ·   /gb bank   ·   /goodmap  minimap   ·   /fb  fishing")
	p:Text(P.DIM .. "Quest data and quest experience from QuestieDB by the Questie team and contributors, used under the GPLv3. Forever dungeon quest rewards gathered from ForeverChanges and Conquest Capped. Campfires heard from CampFirePin (BeeTwenty), S'more Skills (Henrik8210) and Kerzo Camping Sync (Kerzo); camp data from Happy Camper's camp lookup (Torridon); camp object names from Stoked (KonigTX). Pathway is free software under the same license.|r")
	p:Text(P.DIM .. "Step tips from RestedXP Guides by the RestedXP team (github.com/RestedXP/RXPGuides), used under CC BY-NC-SA 4.0; the tips file is shared under the same license. Pathway is free and non-commercial.|r")
	p:Text(P.DIM .. "WoW-Pro tips from the WoW-Pro Guides by \"The WoW-Pro Community\" (github.com/Ludovicus-Maior/WoW-Pro-Guides), included unchanged in WoWPro/ under CC BY-NC-ND 3.0 (creativecommons.org/licenses/by-nc-nd/3.0). Pathway is not affiliated with WoW-Pro.|r")
	p:Text(P.DIM .. "Minimap terrain up close: the game's own minimap squares, found by their file IDs from the community WoW listfile (github.com/wowdev/wow-listfile).|r")
	p:Button("Reset window positions", function() wipe(P.db.pos); ReloadUI() end, false, "Reloads your UI.")
	p:Button("Start fresh", function() StaticPopup_Show("PATHWAY_RESET") end, false, "Every Pathway setting back to how it came, for all your characters. Reloads your UI.")
	Finish(p)
end

---------------------------------------------------------------------------
-- Window
---------------------------------------------------------------------------
local function ShowPage(key)
	if not pages[key] then key = "modules" end
	current = key
	for k, pg in pairs(pages) do pg.scroll:SetShown(k == key) end
	pages[key].scroll:SetVerticalScroll(0)
	pages[key]:Refresh()
	for _, b in ipairs(nav) do
		local on = b.key == key
		b.bar:SetColorTexture(A[1], A[2], A[3], 1)
		b.bar:SetShown(on)
		b.text:SetTextColor(on and 1 or 0.72, on and 1 or 0.75, on and 1 or 0.8)
	end
end

local function Create()
	win = CreateFrame("Frame", "PathwaySettings", UIParent, "BackdropTemplate")
	if P.ApplySizes then P:ApplySizes() end
	P.Flat(win, P.colors.BG, nil, true)
	win:SetSize(W, H)
	win:SetPoint("CENTER", 0, 30)
	win:SetFrameStrata("DIALOG")
	win:SetToplevel(true)
	win:SetMovable(true); win:EnableMouse(true); win:SetClampedToScreen(true)
	win:RegisterForDrag("LeftButton")
	win:SetScript("OnDragStart", win.StartMoving)
	win:SetScript("OnDragStop", win.StopMovingOrSizing)
	tinsert(UISpecialFrames, "PathwaySettings")
	win:Hide()

	local title = win:CreateFontString(nil, "OVERLAY")
	title:SetFontObject(P.fonts.title)
	title:SetPoint("TOPLEFT", 16, -13)
	local bar = win:CreateTexture(nil, "ARTWORK")
	bar:SetPoint("TOPLEFT", 4, -4); bar:SetPoint("TOPRIGHT", -4, -4); bar:SetHeight(2)
	local function paint()
		title:SetText(P.TITLE .. P.DIM .. "   settings|r")
		bar:SetColorTexture(A[1], A[2], A[3], 0.85)
		if current and win:IsShown() then ShowPage(current) end
	end
	P:OnPaint(paint)
	paint()

	local close = P:CloseButton(win, function() win:Hide() end)
	close:SetPoint("TOPRIGHT", -8, -8)

	win.body = CreateFrame("Frame", nil, win)
	win.body:SetPoint("TOPLEFT", NAV_W + 24, -46)
	win.body:SetPoint("BOTTOMRIGHT", -16, 12)
	BuildPages()

	local side = CreateFrame("Frame", nil, win, "BackdropTemplate")
	P.Flat(side, P.colors.PANEL, { 0, 0, 0, 0 })
	side:SetPoint("TOPLEFT", 5, -40); side:SetPoint("BOTTOMLEFT", 5, 5); side:SetWidth(NAV_W)
	local heads = {}
	for _, o in ipairs(order) do
		local b = CreateFrame("Button", nil, side)
		b:SetSize(NAV_W, 22)
		b.key, b.group = o.key, o.group
		b.text = b:CreateFontString(nil, "OVERLAY"); b.text:SetFontObject(P.fonts.button); b.text:SetPoint("LEFT", 16, 0); b.text:SetText(o.title)
		b.bar = b:CreateTexture(nil, "OVERLAY"); b.bar:SetSize(2, 16); b.bar:SetPoint("LEFT", 6, 0)
		b.hl = b:CreateTexture(nil, "HIGHLIGHT"); b.hl:SetAllPoints(); b.hl:SetColorTexture(1, 1, 1, 0.05)
		b:SetScript("OnClick", function() ShowPage(o.key); PlaySound(SOUNDKIT.IG_MAINMENU_OPTION or 852) end)
		nav[#nav + 1] = b
		if o.group ~= "" and not heads[o.group] then
			local h = side:CreateFontString(nil, "OVERLAY")
			h:SetFontObject(P.fonts.head)
			h:SetText(o.group)
			heads[o.group] = h
		end
	end
	-- the minimap's full set is long: fold "Minimap: …" titles to the part after the colon
	for _, b in ipairs(nav) do
		if b.group == "ADVANCED" then b.text:SetText((b.text:GetText():gsub("^Minimap: ", "Minimap · "))) end
	end
	function Relayout()
		local y, group = -6, nil
		for _, h in pairs(heads) do h:Hide() end
		for _, b in ipairs(nav) do
			local show = b.group ~= "ADVANCED" or Adv()
			b:SetShown(show)
			if show then
				if b.group ~= group then
					group = b.group
					if heads[group] then
						heads[group]:ClearAllPoints(); heads[group]:SetPoint("TOPLEFT", 14, y - 8); heads[group]:Show()
						y = y - 22
					else
						y = y - 8
					end
				end
				b:ClearAllPoints(); b:SetPoint("TOPLEFT", 0, y)
				y = y - (b.group == "ADVANCED" and 20 or 23)
			end
		end
		if current and pages[current] and not Adv() then
			for _, o in ipairs(order) do if o.key == current and o.group == "ADVANCED" then ShowPage("modules") end end
		end
	end
	Relayout()
	win:SetScript("OnShow", function() ShowPage(current or "modules") end)
end

function P:OpenSettings(page)
	if not win then Create() end
	if page and page:find("^adv_") and not Adv() then S().showAdvanced = true; Relayout() end
	if page then current = page end
	if win:IsShown() and not page then win:Hide() else win:Show(); ShowPage(current or "modules") end
end

---------------------------------------------------------------------------
-- Addon list button, Options entry, slash commands
---------------------------------------------------------------------------
function Pathway_OnCompartment(_, button)
	if button == "RightButton" then P:OpenSettings() else P:StartRoute("next") end
end
function Pathway_OnCompartmentEnter(_, btn)
	GameTooltip:SetOwner(btn, "ANCHOR_LEFT")
	GameTooltip:SetText(P.TITLE)
	GameTooltip:AddLine("|cffffffffLeft-click|r  go to the next set", 0.7, 0.7, 0.7)
	GameTooltip:AddLine("|cffffffffRight-click|r  settings", 0.7, 0.7, 0.7)
	GameTooltip:Show()
end
function Pathway_OnCompartmentLeave() GameTooltip:Hide() end

-- a minimap change made anywhere else (the style page, the setup) shows here too
P:Listen("MAP_LOOK_CHANGED", function()
	if win and win:IsShown() and current and pages[current] then P:Debounce("settingsMapRefresh", 0.05, function() pages[current]:Refresh() end) end
end)

P:Listen("READY", function()
	P:ApplyTheme()
	if Settings and Settings.RegisterCanvasLayoutCategory then
		local panel = CreateFrame("Frame")
		local t = panel:CreateFontString(nil, "OVERLAY", "GameFontNormalLarge")
		t:SetPoint("TOPLEFT", 16, -16); t:SetText("Pathway")
		local d = panel:CreateFontString(nil, "OVERLAY", "GameFontHighlight")
		d:SetPoint("TOPLEFT", t, "BOTTOMLEFT", 0, -8); d:SetText("All settings live in Pathway's own window.")
		local b = CreateFrame("Button", nil, panel, "UIPanelButtonTemplate")
		b:SetSize(200, 26); b:SetPoint("TOPLEFT", d, "BOTTOMLEFT", 0, -12); b:SetText("Open Pathway settings")
		b:SetScript("OnClick", function() if SettingsPanel then HideUIPanel(SettingsPanel) end; P:OpenSettings("modules") end)
		pcall(function() Settings.RegisterAddOnCategory(Settings.RegisterCanvasLayoutCategory(panel, "Pathway")) end)
	end
	if not P.db.welcomed then
		P.db.welcomed = true
		C_Timer.After(6, function()
			P:Print("Open your map and use the bar along the bottom, or type |cffffffff/pw|r to head to the closest quests. |cffffffff/pw settings|r for options.")
		end)
	end
end)

local HELP = {
	"/pw — go to the closest set of quests for you",
	"/pw pickup  ·  /pw obj  ·  /pw turnin — just one kind",
	"/pw story — the storyline of the zone you're in  ·  /pw zone — all its quests, chain to chain  ·  /pw to westfall — go anywhere the fastest way",
	"/pw journal — every zone, chain and quest  ·  /pw flights — find new flight paths",
	"/pw find repair (food, inn, mail, flight, class, bank, mining…) — the nearest one",
	"/pw skip  ·  /pw stop  ·  /pw guide (the step window)",
	"/pw gear — look through your bags for upgrades  ·  /pw talents — where your next point goes",
	"/pw fast — Fastest XP's score: experience an hour, set by set",
	"/pw perf — which parts of Pathway are busiest right now",
	"/pw settings — options",
}

SLASH_PATHWAY1, SLASH_PATHWAY2 = "/pw", "/pathway"
SlashCmdList.PATHWAY = function(msg)
	local cmd, arg = (msg or ""):lower():match("^%s*(%S*)%s*(.-)%s*$")
	if cmd == "" or cmd == "next" or (cmd == "go" and arg == "") then P:StartRoute("next")
	elseif cmd == "pickup" or cmd == "pick" then P:StartRoute("pickup")
	elseif cmd == "obj" or cmd == "objectives" then P:StartRoute("objective")
	elseif cmd == "turnin" or cmd == "turn" then P:StartRoute("turnin")
	elseif cmd == "zone" then local z = P:PlayerZone(); if not (z and P:LoadGuide("zone:" .. z)) then P:StartRoute("zone") end
	elseif cmd == "go" or cmd == "to" or cmd == "travel" then
		local z = arg ~= "" and P:FindZone(arg)
		if z then P:GoToZone(z) else P:ToggleGoTo() end
	elseif cmd == "story" then local z = P:PlayerZone(); if not (z and P:LoadGuide("story:" .. z)) then P:Print("No story guide for this zone.") end
	elseif cmd == "journal" or cmd == "j" or cmd == "quests" then P:ToggleJournal()
	elseif cmd == "flights" or cmd == "fp" then P:LoadGuide("flights")
	elseif cmd == "find" then P.Find:Slash(arg)
	elseif cmd == "get" then P:ObtainSlash(arg)
	elseif cmd == "learned" then P:ShowLearned()
	elseif cmd == "talents" or cmd == "talent" then P:TalentSlash()
	elseif cmd == "reset" then StaticPopup_Show("PATHWAY_RESET")
	elseif cmd == "setup" then P:ShowParts()
	elseif cmd == "look" then P:ShowMapLook(true)
	elseif cmd == "showcase" then
		-- everything open at once, for screenshots
		if not P.route then P:StartRoute("next") end
		P:ShowZoneInJournal(P:PlayerZone())
		if P.Bags and P.Bags.ShowBags then P.Bags:ShowBags() end
		P:UpdateGuide(); P:UpdateQuestBar()
		P:Print("Showcase: journal, guide, quest bar and bags are open. Press Print Screen; move windows to taste.")
	elseif cmd == "skip" then P:SkipStop()
	elseif cmd == "stop" then P:StopRoute()
	elseif cmd == "gear" then P:ScanAllGear()
	elseif cmd == "guide" then P:ToggleGuide()
	elseif cmd == "bags" then if P.Bags.db then P.Bags:ToggleBags() else P:Print("Bags are switched off (Modules).") end
	elseif cmd == "settings" or cmd == "config" or cmd == "options" then P:OpenSettings()
	elseif cmd == "net" or cmd == "share" then P:NetReport()
	elseif cmd == "fast" then
		-- Fastest XP's score: the last sets, and how your pace compares with Pathway's guess
		local log = P:FastLog()
		if not log[1] then P:Print("No Fastest XP set finished yet: the score shows after your first one.") return end
		P:Print(("Fastest XP, last %d sets (your pace: %d%% of Pathway's guess):"):format(#log, math.floor(P:FastPace() * 100 + 0.5)))
		for _, e in ipairs(log) do print(("   %s xp/h  |cff8a8f99%s, %d quests, %d min|r"):format(P.Short(e.xph), P:MapName(e.zone) or "?", e.n or 0, e.mins or 0)) end
	elseif cmd == "perf" then
		-- the busiest handlers: measured for 10 seconds if the meter isn't already measuring
		local Perf = P.Perf
		local function Report()
			local top = Perf.Top(10)
			if not top[1] then P:Print("Nothing in Pathway is busy right now.") return end
			P:Print("busiest handlers (ms of work a second):")
			for _, it in ipairs(top) do print(("   %6.2f  %s  |cff8a8f99(%s)|r"):format(it[2], it[1], it[3] or "?")) end
		end
		if Perf.on then Report()
		else
			Perf.Start(true)
			P:Print("Measuring for 10 seconds: play as usual...")
			C_Timer.After(5, Perf.Sample)
			C_Timer.After(10, function() Perf.Sample(); Report(); if not (P.FPSShown and P:FPSShown()) then Perf.Start(false) end end)
		end
	elseif cmd == "why" and tonumber(arg) then
		local id = tonumber(arg)
		local ok, why = P:Available(id)
		local q = P.Q[id]
		P:Print("%s (%d): %s", q and q[P.K.NAME] or "?", id, ok and "available" or (why or "no"))
	else
		for _, line in ipairs(HELP) do P:Print(line) end
	end
end
end part() end
